#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

/*
 * Raspberry Pi 4 Model B - Soil Moisture Sensor (Analog) via MCP3008 ADC
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3V (Pin 1)
 *   MCP3008 VREF -> 3.3V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SCLK)
 *   MCP3008 DOUT -> GPIO9  (MISO)
 *   MCP3008 DIN  -> GPIO10 (MOSI)
 *   MCP3008 CS   -> GPIO8  (CE0)
 *   MCP3008 CH0  -> Soil Moisture Sensor analog output
 *
 * Build: gcc -Wall -o soil_moisture soil_moisture.c -lpigpio -lrt
 * Run:   sudo ./soil_moisture
 */

#define SPI_CHANNEL 0       /* CE0 (GPIO8) */
#define SPI_SPEED   1000000 /* 1 MHz */
#define ADC_CHANNEL 0       /* MCP3008 CH0 */
#define SAMPLE_INTERVAL_US 1000000 /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0 on success (stores 10-bit value in *adc_value), -1 on error.
 */
static int read_mcp3008(int channel, int *adc_value) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }
    if (adc_value == NULL) {
        fprintf(stderr, "Error: NULL pointer passed to read_mcp3008\n");
        return -1;
    }

    /*
     * MCP3008 SPI protocol (Mode 0, 0): 3-byte transfer.
     * Byte 0: 0x01 (Start bit)
     * Byte 1: (0x08 | channel) << 4  (Single-ended + channel selection)
     * Byte 2: 0x00 (Don't care, clocked out to read low byte)
     *
     * Response:
     *   rx[0] = ignored
     *   rx[1] = [null bit][b9 b8] in the two LSBs
     *   rx[2] = b7..b0
     */
    char tx_buffer[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx_buffer[3] = { 0 };

    int result = spiXfer(g_spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d): %s\n",
                result, strerror(errno));
        return -1;
    }

    *adc_value = ((rx_buffer[1] & 0x03) << 8) | (rx_buffer[2] & 0xFF);
    return 0;
}

int main(void) {
    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel: CE0, 1 MHz, Mode 0 */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d): %s\n",
                g_spi_handle, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to install SIGINT handler: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to install SIGTERM handler: %s\n",
                strerror(errno));
    }

    printf("Soil Moisture Sensor Data Acquisition\n");
    printf("SPI Channel: %d, ADC Channel: %d, Sample Interval: %d us\n",
           SPI_CHANNEL, ADC_CHANNEL, SAMPLE_INTERVAL_US);
    printf("Press Ctrl+C to exit.\n\n");

    /* Main sampling loop */
    while (g_running) {
        int adc_value = 0;

        if (read_mcp3008(ADC_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        } else {
            /* Get current timestamp */
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            if (timeinfo != NULL) {
                strftime(timestamp, sizeof(timestamp),
                         "%Y-%m-%d %H:%M:%S", timeinfo);
            } else {
                snprintf(timestamp, sizeof(timestamp), "unknown");
            }

            printf("[%s] ADC Value: %d\n", timestamp, adc_value);
            fflush(stdout);
        }

        /* Sleep for the sample interval, checking g_running every 100 ms */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (g_spi_handle >= 0) {
        if (spiClose(g_spi_handle) != 0) {
            fprintf(stderr, "Warning: SPI close failed: %s\n", strerror(errno));
        }
        g_spi_handle = -1;
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

