#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/*
 * Raspberry Pi 4 Model B
 * MLX91219 Hall-Effect Current Sensor (analog output) -> ADS1115 ADC
 *
 * Wiring:
 *   MLX91219 VCC  -> 3.3 V (Pin 1)
 *   MLX91219 GND  -> GND   (Pin 9)
 *   MLX91219 OUT  -> ADS1115 AIN0 (Pin 1)
 *   MLX91219 ADDR -> GND   (I2C address 0x40)
 *   ADS1115 VDD  -> 3.3 V (Pin 1)
 *   ADS1115 GND  -> GND   (Pin 9)
 *   ADS1115 SDA  -> GPIO2 (BCM 3, Pin 3)
 *   ADS1115 SCL  -> GPIO3 (BCM 5, Pin 5)
 *   ADS1115 ADDR -> GND   (I2C address 0x40)
 *
 * Build: gcc -Wall -Wextra -O2 -o mlx91219_ads1115 mlx91219_ads1115.c -lpigpio -lrt
 * Run:   sudo ./mlx91219_ads1115
 */

#define I2C_BUS        1
#define ADS1115_ADDR   0x40

/* ADS1115 register addresses */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/*
 * Config register (16-bit, big-endian on the bus):
 *   Bit 15    OS       = 1  (begin single conversion)
 *   Bits14:12 MUX      = 100 (AIN0 single-ended)
 *   Bits11:9  PGA      = 001 (±4.096 V)
 *   Bit 8     MODE     = 1  (single-shot)
 *   Bits7:5   DR       = 100 (128 SPS)
 *   Bit 4     COMP_MODE= 0
 *   Bit 3     COMP_POL = 0
 *   Bit 2     COMP_LAT = 0
 *   Bits1:0   COMP_QUE = 11 (disable comparator)
 *
 * Binary: 1 100 001 1 100 0 0 11
 *         = 0xC183
 */
#define ADS1115_CONFIG_SINGLE_AIN0 0xC183

/*
 * Sensor parameters (MLX91219, 5 V supply, 200 mV/A sensitivity):
 *   V_supply = 5.0 V
 *   V_offset = 0.0 V
 *   V_full   = 5.0 V
 *   I_full   = 20.0 A
 *   R_load   = 10.0 Ω
 *   Sensitivity = V_full / I_full = 250 mV/A
 *   ADC range  = ±4.096 V  -> 1 bit = 125 µV
 *   ADC full-scale = 32767 counts
 */
#define V_SUPPLY              5.0
#define V_OFFSET              0.0
#define V_FULL                V_SUPPLY
#define I_FULL               20.0
#define R_LOAD                10.0
#define SENSITIVITY           0.250  /* 250 mV/A */
#define ADC_V_RANGE           4.096
#define ADC_MAX_COUNTS        32767.0

#define SAMPLE_INTERVAL_US    500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Write a 16-bit value to an ADS1115 register.
 * pigpio's i2cWriteI2CBlockData sends raw bytes in the order they
 * appear in the buffer, which matches the ADS1115 big-endian
 * register expectation.
 */
static int ads1115_write_reg(int handle, uint8_t reg, uint16_t value)
{
    char buf[2];
    buf[0] = (char)(value >> 8);
    buf[1] = (char)(value & 0xFF);
    return i2cWriteI2CBlockData(handle, reg, buf, 2);
}

/*
 * Read a 16-bit value from an ADS1115 register.
 * pigpio's i2cReadI2CBlockData returns a buffer with the bytes in
 * the order they were read from the bus, which matches the ADS1115
 * big-endian register expectation.
 */
static int ads1115_read_reg(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (rc != 2) {
        return -1;
    }
    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/*
 * Trigger a single-shot conversion on AIN0 and return the raw ADC code.
 * Returns 0 on success, -1 on I2C error, -2 on sensor-absent (OS bit
 * not set after the config write).
 */
static int ads1115_read_ain0(int handle, int16_t *raw_out)
{
    int rc;

    /* Write config: single-shot, AIN0, ±4.096 V, 128 SPS, comparator disabled */
    rc = ads1115_write_reg(handle, ADS1115_REG_CONFIG, ADS1115_CONFIG_SINGLE_AIN0);
    if (rc < 0) {
        fprintf(stderr, "Error: failed to write ADS1115 config (rc=%d)\n", rc);
        return -1;
    }

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    gpioDelay(10000);

    /* Poll OS bit (bit 15) — set when conversion is ready */
    for (int i = 0; i < 10; i++) {
        uint16_t cfg;
        rc = ads1115_read_reg(handle, ADS1115_REG_CONFIG, &cfg);
        if (rc < 0) {
            fprintf(stderr, "Error: failed to read ADS1115 config (rc=%d)\n", rc);
            return -1;
        }
        if (cfg & 0x8000) {
            break;
        }
        gpioDelay(2000);
    }
    if (!(cfg & 0x8000)) {
        fprintf(stderr, "Error: ADS1115 conversion not complete (OS bit not set)\n");
        return -2;
    }

    /* Read conversion result (big-endian on the bus) */
    uint16_t raw;
    rc = ads1115_read_reg(handle, ADS1115_REG_CONVERSION, &raw);
    if (rc < 0) {
        fprintf(stderr, "Error: failed to read ADS1115 conversion (rc=%d)\n", rc);
        return -1;
    }

    *raw_out = (int16_t)raw;
    return 0;
}

static float raw_to_current(int16_t raw)
{
    float voltage = ((float)raw / ADC_MAX_COUNTS) * ADC_V_RANGE;
    return (voltage - V_OFFSET) / SENSITIVITY;
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at ADS1115 address 0x40 */
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (rc=%d) — check wiring and address\n",
                g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("MLX91219 Current Sensor Reader (ADS1115 ADC, I2C bus %d, addr 0x%02X)\n",
           I2C_BUS, ADS1115_ADDR);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        int16_t raw;
        int rc = ads1115_read_ain0(g_i2c_handle, &raw);

        if (rc == 0) {
            float current = raw_to_current(raw);
            printf("Current: %.2f A (raw=%d)\n", current, raw);
        } else if (rc == -2) {
            fprintf(stderr, "Warning: sensor absent or not responding (no OS bit set)\n");
        } else {
            fprintf(stderr, "Warning: I2C communication error during read\n");
        }

        /* Sleep 500 ms, checking g_running every 100 ms for responsive shutdown */
        for (int i = 0; i < 5 && g_running; i++) {
            gpioDelay(100000);
        }
    }

    /* Cleanup */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

