    }

    *raw_out = (int16_t)raw;
    return 0;
}

static float raw_to_current(int16_t raw)
{
    float voltage = ((float)raw / ADC_MAX_COUNTS) * ADC_V_RANGE;
    return (voltage - V_OFFSET) / SENSITIVITY;
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at ADS1115 address 0x40 */
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (rc=%d) — check wiring and address\n",
                g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("MLX91219 Current Sensor Reader (ADS1115 ADC, I2C bus %d, addr 0x%02X)\n",
           I2C_BUS, ADS1115_ADDR);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        int16_t raw;
        int rc = ads1115_read_ain0(g_i2c_handle, &raw);

        if (rc == 0) {
            float current = raw_to_current(raw);
            printf("Current: %.2f A (raw=%d)\n", current, raw);
        } else if (rc == -2) {
            fprintf(stderr, "Warning: sensor absent or not responding (no OS bit set)\n");
        } else {
            fprintf(stderr, "Warning: I2C communication error during read\n");
        }

        /* Sleep 500 ms, checking g_running every 100 ms for responsive shutdown */
        for (int i = 0; i < 5 && g_running; i++) {
            gpioDelay(100000);
        }
    }

    /* Cleanup */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

