/*
 * Raspberry Pi 3 Model B+ — AZDelivery KY-026 Flame Sensor + MCP3008 ADC
 *
 * Wiring:
 *   KY-026 D0  -> GPIO4  (BCM 4, physical pin 7)
 *   KY-026 A0  -> MCP3008 CH0
 *   MCP3008 CLK -> GPIO11 (BCM 11, physical pin 23)
 *   MCP3008 DOUT-> GPIO9  (BCM 9,  physical pin 21)
 *   MCP3008 DIN -> GPIO10 (BCM 10, physical pin 19)
 *   MCP3008 CS/SHDN -> GPIO8 (BCM 8, physical pin 24)
 *   MCP3008 VDD -> 3.3 V, VREF -> 3.3 V, DGND/AGND -> GND
 *
 * Build: gcc -O2 -Wall -o flame_monitor flame_monitor.c -lpigpio -lrt
 * Run:   sudo ./flame_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define FLAME_SENSOR_PIN    4          /* BCM 4 — digital D0 from KY-026 */
#define MCP3008_CS_PIN      8          /* BCM 8 — MCP3008 CE0 (chip-select) */
#define MCP3008_CHANNEL     0          /* single-ended CH0 */
#define SPI_CHANNEL         0          /* SPI0 CE0 */
#define SPI_SPEED           1000000    /* 1 MHz */
#define SPI_FLAGS           0          /* mode 0, active-low CE */
#define LOG_FILE            "flame_data.csv"
#define SAMPLE_INTERVAL_US  1000000    /* 1 second */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------ MCP3008 read ----------------------------- */
/*
 * MCP3008 single-ended read sequence (3 bytes):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value assembled from rx[1] (lower 2 bits) and rx[2] (8 bits).
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0, 0, 0 };

    /* pigpio spiXfer returns the number of bytes transferred; 3 is expected. */
    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;  /* 0..1023 */
}

/* ------------------------------ Logging helper --------------------------- */
static void log_data(int analog_value, int flame_detected)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%d,%d\n", ts, flame_detected, analog_value);
    fclose(fp);
}

/* ------------------------------- Main ------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- open SPI --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- configure GPIO pins --- */
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(FLAME_SENSOR_PIN) failed\n");
        goto cleanup;
    }
    if (gpioSetMode(MCP3008_CS_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(MCP3008_CS_PIN) failed\n");
        goto cleanup;
    }
    if (gpioWrite(MCP3008_CS_PIN, 1) != 0) {  /* CS idle high */
        fprintf(stderr, "gpioWrite(MCP3008_CS_PIN, 1) failed\n");
        goto cleanup;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    /* --- main loop --- */
    while (g_running) {
        /* KY-026 D0 is active-high: 1 = flame detected */
        int flame_detected = (gpioRead(FLAME_SENSOR_PIN) == 1) ? 1 : 0;

        /* Read analog value from MCP3008 CH0 */
        int analog_value = read_mcp3008(MCP3008_CHANNEL);
        if (analog_value < 0) {
            fprintf(stderr, "Failed to read MCP3008 — sensor may be absent or SPI bus error\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        /* Approximate temperature: linear mapping 0..1023 -> 0..50 °C */
        float temperature = (float)analog_value * 50.0f / 1023.0f;

        log_data(analog_value, flame_detected);

        printf("Flame: %s | Temp: %.2f °C | ADC: %d\n",
               flame_detected ? "YES" : "NO", temperature, analog_value);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

cleanup:
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
    printf("\nCleanup complete. Exiting.\n");
    return EXIT_SUCCESS;
}

