#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define HEAT_SENSOR_CHANNEL 0
#define BUZZER_PIN 27
#define TEMPERATURE_THRESHOLD 60.0
#define LOG_FILE_NAME "fire_log.txt"
#define POLL_DELAY_US 100000
#define DEBOUNCE_DELAY_US 50000
#define BUZZER_DURATION_US 2000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_flame_sensor(void) {
    int level = gpioRead(FLAME_SENSOR_PIN);
    if (level < 0) {
        fprintf(stderr, "Error reading flame sensor on GPIO%d\n", FLAME_SENSOR_PIN);
        return -1;
    }
    gpioDelay(DEBOUNCE_DELAY_US);
    return level;
}

static int read_temperature(void) {
    unsigned char config[3];
    config[0] = 0x01;
    config[1] = 0xC3;
    config[2] = 0x83;

    if (i2cWriteDevice(i2c_handle, (char *)config, 3) < 0) {
        fprintf(stderr, "Error writing ADS1115 config\n");
        return -1;
    }
    gpioDelay(10000);

    char reg = 0x00;
    if (i2cWriteDevice(i2c_handle, &reg, 1) < 0) {
        fprintf(stderr, "Error selecting ADS1115 conversion reg\n");
        return -1;
    }

    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) < 0) {
        fprintf(stderr, "Error reading ADS1115 conversion\n");
        return -1;
    }

    int16_t raw = (data[0] << 8) | data[1];
    raw >>= 4;
    if (raw & 0x8000) {
        raw |= 0xF000;
    }
    return (int)raw;
}

static void activate_buzzer(int duration_us) {
    gpioWrite(BUZZER_PIN, 1);
    gpioDelay(duration_us);
    gpioWrite(BUZZER_PIN, 0);
}

static void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set flame sensor pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set buzzer pin mode\n");
        gpioTerminate();
        return 1;
    }
    gpioWrite(BUZZER_PIN, 0);

    i2c_handle = i2cOpen(1, 0x48, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x48\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE_NAME);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Fire detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        int flame_detected = read_flame_sensor();
        int temp = read_temperature();

        if (flame_detected < 0 || temp < 0) {
            fprintf(stderr, "Sensor read error, skipping cycle\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (flame_detected && temp > TEMPERATURE_THRESHOLD) {
            log_event("Fire detected!");
            activate_buzzer(BUZZER_DURATION_US);
        } else if (flame_detected) {
            log_event("Flame detected!");
        } else if (temp > TEMPERATURE_THRESHOLD) {
            char msg[64];
            snprintf(msg, sizeof(msg), "Temperature exceeded threshold: %.1f C", (double)temp);
            log_event(msg);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(BUZZER_PIN, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

