/*
 * MICS-4514 CO Sensor Logger for Raspberry Pi 4 Model B
 *
 * Reads a 16-bit raw CO resistance value from an external ADC (e.g., ADS1115)
 * via I2C bus 1 and converts it to ppm using a calibrated logarithmic curve.
 * Logs timestamped ppm values to co_log.txt every 5 seconds.
 *
 * Wiring:
 *   MICS-4514 SDA  -> GPIO2 (I2C1 SDA, pin 3)
 *   MICS-4514 SCL  -> GPIO3 (I2C1 SCL, pin 5)
 *   MICS-4514 VDD  -> 3.3 V (pin 1)
 *   MICS-4514 GND  -> GND  (pin 6)
 *   ADS1115 SDA    -> GPIO2
 *   ADS1115 SCL    -> GPIO3
 *   ADS1115 ADDR   -> GND  (I2C address 0x48)
 *   ADS1115 VDD    -> 3.3 V
 *   ADS1115 GND    -> GND
 *
 * Build: gcc -O2 -Wall -o co_logger co_logger.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define ADC_I2C_ADDR         0x48          /* ADS1115 default address when ADDR pin = GND */
#define ADC_REG_CONVERSION   0x00          /* Conversion register pointer */
#define ADC_REG_CONFIG       0x01          /* Config register pointer */

/*
 * ADS1115 config word (16-bit, big-endian on the bus):
 *   Bit 15    OS       = 1  (begin single conversion)
 *   Bits14:12 MUX      = 100 (AIN0 vs GND)  -- read CO output
 *   Bits11:9  PGA      = 001 (±4.096 V)
 *   Bit 8     MODE     = 1  (single-shot)
 *   Bits7:5   DR       = 100 (128 SPS)
 *   Bit 4     COMP_MODE= 0
 *   Bit 3     COMP_POL  = 0
 *   Bit 2     COMP_LAT  = 0
 *   Bits1:0   COMP_QUE  = 11 (disable comparator)
 * Result: 0x84A3
 */
#define ADC_CONFIG_WORD      0x84A3

#define LOG_FILE             "co_log.txt"
#define SAMPLE_INTERVAL_S    5
#define MAX_RETRIES          3
#define RETRY_DELAY_US       100000        /* 100 ms between retries */

/*
 * Calibration constants (example values -- replace with your sensor's
 * datasheet-derived values).
 * RL is the load resistor on the sensor board (typically 10 kΩ).
 * RO is the reference resistor (typically 10 kΩ).
 */
#define RL                   10.0          /* Load resistor in kΩ */
#define RO                   10.0          /* Reference resistor in kΩ */
#define R0_CLEAN_AIR         10.0          /* Sensor resistance at 0 ppm (calibrate in clean air) */
#define SLOPE                0.001         /* Example logarithmic slope */
#define INTERCEPT            (-3.0)        /* Example logarithmic intercept */

/* ----------------------------- Globals ----------------------------------- */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ----------------------------- Prototypes -------------------------------- */
static int  initialize_i2c(void);
static int  read_adc_raw(uint16_t *raw_out);
static double calculate_co_ppm(uint16_t raw);
static int  log_data(double ppm);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- I2C Init ---------------------------------- */
static int initialize_i2c(void)
{
    i2c_handle = i2cOpen(I2C_BUS, ADC_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, ADC_I2C_ADDR, i2c_handle);
        return -1;
    }

    /* Write config to ADS1115: single-shot, AIN0 vs GND, ±4.096 V, 128 SPS */
    char config[3];
    config[0] = ADC_REG_CONFIG;
    config[1] = (char)((ADC_CONFIG_WORD >> 8) & 0xFF);
    config[2] = (char)(ADC_CONFIG_WORD & 0xFF);

    if (i2cWriteDevice(i2c_handle, config, 3) < 0) {
        fprintf(stderr, "Error: Failed to write ADC config to 0x%02X\n", ADC_I2C_ADDR);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    return 0;
}

/* ----------------------------- ADC Read ---------------------------------- */
static int read_adc_raw(uint16_t *raw_out)
{
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C handle invalid\n");
        return -1;
    }
    if (raw_out == NULL) {
        return -1;
    }

    /* Trigger a single conversion */
    char reg = ADC_REG_CONVERSION;
    if (i2cWriteDevice(i2c_handle, &reg, 1) < 0) {
        fprintf(stderr, "Error: Failed to set conversion register pointer\n");
        return -1;
    }

    /* Read 2 bytes of conversion result */
    char buf[2];
    int bytes = i2cReadDevice(i2c_handle, buf, 2);
    if (bytes != 2) {
        fprintf(stderr, "Error: I2C read failed (got %d bytes, expected 2)\n", bytes);
        return -1;
    }

    *raw_out = ((uint16_t)(buf[0] & 0xFF) << 8) | (uint16_t)(buf[1] & 0xFF);
    return 0;
}

/* ----------------------------- PPM Calc ---------------------------------- */
static double calculate_co_ppm(uint16_t raw)
{
    if (raw == 0) {
        return -1.0;  /* Avoid division by zero for invalid readings */
    }

    /* Convert raw ADC count to sensor resistance (kΩ) */
    double r_sensor = ((double)raw / 65535.0) * (RO + RL);

    /*
     * Inverse relationship: higher resistance -> lower CO concentration.
     * ppm = a * log10(R_sensor / R0) + b
     */
    double ppm = INTERCEPT + SLOPE * log10((r_sensor / R0_CLEAN_AIR) - 1.0);

    /* Clamp to physically reasonable range (0–1000 ppm for MICS-4514) */
    if (ppm < 0.0)   ppm = 0.0;
    if (ppm > 1000.0) ppm = 1000.0;

    return ppm;
}

/* ----------------------------- Logging ----------------------------------- */
static int log_data(double ppm)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error: time() failed\n");
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r() failed\n");
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s, %.2f ppm\n", timestamp, ppm) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed on log file\n");
        return -1;
    }

    return 0;
}

/* ----------------------------- Signal Handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Cannot open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write a session header */
    time_t now = time(NULL);
    struct tm tm_info;
    localtime_r(&now, &tm_info);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(log_file, "%s, Session started: MICS-4514 CO logger\n", timestamp);
    fflush(log_file);

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed\n");
    }

    printf("MICS-4514 CO logger started. Logging to %s every %d s. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_INTERVAL_S);

    /* Main sampling loop */
    while (!terminate) {
        uint16_t raw = 0;
        int read_ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && !terminate; attempt++) {
            if (read_adc_raw(&raw) == 0) {
                read_ok = 1;
                break;
            }
            if (attempt < MAX_RETRIES - 1) {
                gpioDelay(RETRY_DELAY_US);
            }
        }

        if (!read_ok) {
            fprintf(stderr, "Error: Failed to read ADC after %d attempts (sensor/bus error)\n",
                    MAX_RETRIES);
            /* Log the error event with a sentinel value */
            if (log_data(-1.0) != 0) {
                fprintf(stderr, "Warning: Failed to log error event\n");
            }
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        double ppm = calculate_co_ppm(raw);

        if (log_data(ppm) != 0) {
            fprintf(stderr, "Warning: Failed to log data\n");
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    cleanup();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

