#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/*
 * Raspberry Pi 3 Model B+
 *   KY-026 Flame Sensor (AZDelivery)
 *     D0  -> GPIO 4  (BCM)
 *     A0  -> MCP3008 CH0
 *     CS  -> GPIO 8  (BCM, SPI0 CE0)
 *     SCLK-> GPIO 11 (BCM)
 *     MOSI-> GPIO 10 (BCM)
 *     MISO-> GPIO 9  (BCM)
 *
 * MCP3008 SPI wiring (SPI0):
 *   CE0  -> GPIO 8  (BCM)
 *   SCLK-> GPIO 11 (BCM)
 *   MOSI-> GPIO 10 (BCM)
 *   MISO-> GPIO 9  (BCM)
 *   VDD  -> 3.3 V
 *   VREF -> 3.3 V
 *   AGND-> GND
 *   DGND-> GND
 */

#define FLAME_SENSOR_PIN 4
#define SPI_CHANNEL      0
#define SPI_SPEED        1000000   /* 1 MHz */
#define SPI_FLAGS        0
#define MCP3008_CHANNEL  0
#define LOG_FILE         "flame_data.csv"
#define SAMPLE_PERIOD_US 1000000   /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read one sample from the MCP3008 (single-ended mode)                */
/* Returns 0–1023 on success, -1 on error.                             */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: rx[1] low 2 bits + rx[2] 8 bits = 10-bit value
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (ret=%d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Log one data row to the CSV file                                    */
/* ------------------------------------------------------------------ */
static int log_data(int flame_detected, int temperature)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("Error getting time");
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("Error converting time");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d\n", timestamp, flame_detected, temperature) < 0) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", FLAME_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz, mode 0 --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error: sigaction(SIGINT) failed");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: sigaction(SIGTERM) failed");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");
    printf("Logging to %s every 1 s.\n", LOG_FILE);

    /* --- Main sampling loop --- */
    while (g_running) {
        int flame_detected = gpioRead(FLAME_SENSOR_PIN);
        if (flame_detected < 0) {
            fprintf(stderr, "Error: gpioRead failed on pin %d\n", FLAME_SENSOR_PIN);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        int temperature = read_mcp3008(MCP3008_CHANNEL);
        if (temperature < 0) {
            fprintf(stderr, "Error: MCP3008 read failed on channel %d\n", MCP3008_CHANNEL);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        if (log_data(flame_detected, temperature) != 0) {
            fprintf(stderr, "Warning: log_data failed for this sample\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

