/*
 * Raspberry Pi 4 Model B – Dual IMP23ABSU Analog MEMS Microphone Logger
 *
 * Wiring (I2C bit-banged via GPIO):
 *   IMP23ABSU #1  SDA -> GPIO2 (BCM2), SCL -> GPIO3 (BCM3)
 *   IMP23ABSU #2  SDA -> GPIO8 (BCM8), SCL -> GPIO9 (BCM9)
 *
 * Build:  gcc -O2 -Wall -o audio_logger audio_logger.c -lpigpio -lrt
 * Run:    sudo ./audio_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define MIC1_SDA_PIN         2       /* BCM2  */
#define MIC1_SCL_PIN         3       /* BCM3  */
#define MIC2_SDA_PIN         8       /* BCM8  */
#define MIC2_SCL_PIN         9       /* BCM9  */

#define SAMPLE_PERIOD_US     100000  /* 100 ms */
#define ERROR_VALUE          (-999.0)
#define LOG_FILE             "audio_log.txt"

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handles[2];

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  init_i2c_bitbang(int pin_sda, int pin_scl);
static int  read_mic_level(int handle, double *level_out);
static double calculate_average(double m1, double m2, double e1, double e2);
static int  log_data(double avg_level);
static void cleanup(void);

/* ----------------------------- Signal Handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- I2C Bit-bang Init -------------------------- */
static int init_i2c_bitbang(int pin_sda, int pin_scl)
{
    int handle = i2cOpen(I2C_BUS, 0, 0);   /* bus 1, no slave addr needed */
    if (handle < 0) {
        fprintf(stderr, "i2cOpen failed on bus %d (pin SDA=%d SCL=%d): %d\n",
                I2C_BUS, pin_sda, pin_scl, handle);
        return -1;
    }

    /* pigpio drives the bus; we just keep the handle for identification. */
    g_i2c_handles[0] = handle;

    /* Configure pins as inputs (pigpio drives them during I2C transactions). */
    if (gpioSetMode(pin_sda, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(SDA=%d) failed\n", pin_sda);
        return -1;
    }
    if (gpioSetMode(pin_scl, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(SCL=%d) failed\n", pin_scl);
        return -1;
    }

    /* Enable internal pull-ups so the bus idles high (IMP23ABSU SDA is open-drain). */
    if (gpioSetPullUpDown(pin_sda, PI_PUD_UP) < 0) {
        fprintf(stderr, "gpioSetPullUpDown(SDA=%d) failed\n", pin_sda);
        return -1;
    }
    if (gpioSetPullUpDown(pin_scl, PI_PUD_UP) < 0) {
        fprintf(stderr, "gpioSetPullUpDown(SCL=%d) failed\n", pin_scl);
        return -1;
    }

    return 0;
}

/* ----------------------------- Read Mic Level ----------------------------- */
static int read_mic_level(int handle, double *level_out)
{
    if (handle < 0 || level_out == NULL) {
        return -1;
    }

    /*
     * Bit-bang a 16-bit read from the IMP23ABSU.
     * The device is present on the bus and responds to the SCL edge;
     * the SDA line is driven by the microphone.
     *
     * Protocol (master -> slave):
     *   1. Pull SDA low to start (device responds by pulling high).
     *   2. Clock out 8 data bits (MSB first).
     *   3. Release SDA (device pulls low to ACK).
     *   4. Re-pull SDA low to read the 8 LSBs.
     *   5. Release SDA high to end the transaction.
     *
     * The IMP23ABSU outputs a 16-bit value where the upper 12 bits
     * represent the signed log10(P_max/P_ref) scaled by a factor of 100.
     * The lower 4 bits are reserved or status.
     */
    char buf[2];
    int  rc;

    /* Phase 1: clock out MSBs (bits 15..8). */
    rc = i2cWriteDevice(handle, buf, 2);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteDevice (MSB) failed: %d\n", rc);
        return -1;
    }

    /* Small delay so the device can shift out the data. */
    gpioDelay(20);  /* 20 us */

    /* Phase 2: clock out LSBs (bits 7..0). */
    rc = i2cWriteDevice(handle, buf, 2);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteDevice (LSB) failed: %d\n", rc);
        return -1;
    }

    /* Small delay for the second data shift. */
    gpioDelay(20);

    /* Read back the 16-bit word. */
    rc = i2cReadDevice(handle, buf, 2);
    if (rc < 0) {
        fprintf(stderr, "i2cReadDevice failed: %d\n", rc);
        return -1;
    }
    if (rc != 2) {
        fprintf(stderr, "i2cReadDevice short read: %d bytes\n", rc);
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];

    /*
     * IMP23ABSU: 12-bit signed log10(P_max/P_ref) scaled by 100.
     * Bits [15:12] are the sign extension; bits [11:0] hold the value.
     */
    int16_t shifted = (int16_t)(raw >> 4);   /* arithmetic shift sign-extends */
    double level = (double)shifted / 100.0;

    *level_out = level;
    return 0;
}

/* ----------------------------- Average + Logging -------------------------- */
static double calculate_average(double m1, double m2, double e1, double e2)
{
    double avg = (m1 + m2) / 2.0;
    if (e1 > ERROR_VALUE && e2 > ERROR_VALUE) {
        avg = ERROR_VALUE;
    }
    return avg;
}

static int log_data(double avg_level)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, avg_level);

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    for (int i = 0; i < 2; i++) {
        if (g_i2c_handles[i] >= 0) {
            i2cClose(g_i2c_handles[i]);
            g_i2c_handles[i] = -1;
        }
    }
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Initialize pigpio. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize I2C for both microphones. */
    if (init_i2c_bitbang(MIC1_SDA_PIN, MIC1_SCL_PIN) < 0 ||
        init_i2c_bitbang(MIC2_SDA_PIN, MIC2_SCL_PIN) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Audio logger started. Sampling every %d ms. Press Ctrl+C to exit.\n",
           SAMPLE_PERIOD_US / 1000);

    /* Main sampling loop. */
    while (g_running) {
        double level1 = ERROR_VALUE;
        double level2 = ERROR_VALUE;
        int    ok1    = (read_mic_level(g_i2c_handles[0], &level1) == 0);
        int    ok2    = (read_mic_level(g_i2c_handles[1], &level2) == 0);

        double avg_level = calculate_average(level1, level2, ok1 ? level1 : ERROR_VALUE, ok2 ? level2 : ERROR_VALUE);

        if (log_data(avg_level) < 0) {
            fprintf(stderr, "Warning: failed to log data.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

