/*
 * Raspberry Pi 4 Model B - Dual ADMP401 MEMS Microphone Sampler
 *
 * Hardware:
 *   - MCP3008 ADC on SPI0 (CE0=GPIO8, CE1=GPIO9, MISO=GPIO9, MOSI=GPIO10, SCLK=GPIO11)
 *   - LED on GPIO27 (BCM)
 *   - Two ADMP401 MEMS microphones connected to MCP3008 channels 0 and 1
 *
 * Behavior:
 *   - Samples one sample per channel every 1 ms for a 100 ms window.
 *   - Computes RMS for each channel.
 *   - Logs timestamp, mic1_rms, mic2_rms to audio_events.csv.
 *   - Lights LED for 500 ms if either RMS exceeds a high threshold.
 *   - Handles SIGINT cleanly (LED off, resources released).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define SPI_CHANNEL      0
#define SPI_SPEED        1000000  /* 1 MHz */
#define SPI_FLAGS        0

#define CS0_PIN          8        /* GPIO8  - CE0  */
#define CS1_PIN          9        /* GPIO9  - CE1  */
#define LED_PIN          27       /* GPIO27 - LED  */

#define NUM_SAMPLES      100      /* 100 samples per channel = 100 ms window */
#define SAMPLE_DELAY_US  1000     /* 1 ms between samples */
#define LED_ON_MS        500      /* LED on duration after threshold breach */
#define THRESHOLD        0.5      /* RMS threshold for LED trigger */

#define LOG_FILE         "audio_events.csv"

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 single-ended read                                           */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (Mode 0, MSB-first):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (single-ended + channel select)
     *   Byte 2: 0x00  (don't care, clocked out to capture low byte)
     *
     * Response:
     *   Byte 0: undefined
     *   Byte 1: bits 7..2 undefined, bit 1 = null bit, bit 0 = MSB of result
     *   Byte 2: bits 7..0 = low 8 bits of result
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (ret=%d)\n",
                channel, ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* RMS calculation                                                     */
/* ------------------------------------------------------------------ */
static double calculate_rms(const int *samples, int num_samples)
{
    if (samples == NULL || num_samples <= 0) {
        return 0.0;
    }

    double sum_sq = 0.0;
    for (int i = 0; i < num_samples; i++) {
        double v = (double)samples[i];
        sum_sq += v * v;
    }
    return sqrt(sum_sq / (double)num_samples);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(double mic1_rms, double mic2_rms)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.4f,%.4f\n", ts, mic1_rms, mic2_rms) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* LED control                                                         */
/* ------------------------------------------------------------------ */
static void control_led(double mic1_rms, double mic2_rms)
{
    if (mic1_rms > THRESHOLD || mic2_rms > THRESHOLD) {
        gpioWrite(LED_PIN, 1);
        gpioDelay(LED_ON_MS * 1000);   /* pigpio gpioDelay is in microseconds */
        gpioWrite(LED_PIN, 0);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED pin */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin %d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    /* Open SPI0 */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Sampling audio from two ADMP401 microphones via MCP3008...\n");
    printf("Press Ctrl+C to stop.\n");

    int mic1_samples[NUM_SAMPLES];
    int mic2_samples[NUM_SAMPLES];
    int sample_idx = 0;

    while (g_running) {
        int v1 = read_mcp3008(0);
        int v2 = read_mcp3008(1);

        if (v1 < 0 || v2 < 0) {
            fprintf(stderr, "ADC read error; aborting.\n");
            break;
        }

        mic1_samples[sample_idx] = v1;
        mic2_samples[sample_idx] = v2;
        sample_idx++;

        if (sample_idx >= NUM_SAMPLES) {
            double rms1 = calculate_rms(mic1_samples, NUM_SAMPLES);
            double rms2 = calculate_rms(mic2_samples, NUM_SAMPLES);

            if (log_data(rms1, rms2) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }

            control_led(rms1, rms2);

            sample_idx = 0;
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

