#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define I2C_ADDR             0x48          /* ADS1115 default address (ADDR -> GND) */
#define LED_PIN              17            /* BCM GPIO17 */
#define BUFFER_SIZE          100
#define CURRENT_THRESHOLD    50.0f         /* Amperes */
#define SAMPLE_RATE_HZ       10
#define SAMPLE_PERIOD_US     (1000000 / SAMPLE_RATE_HZ)
#define ADC_MAX_VALUE        32767.0f      /* 16-bit signed, single-shot mode */
#define ADC_VREF             4.096f        /* ADS1115 PGA gain = 1 */
#define SENSOR_R             0.1f          /* MLX91204 sense resistor (typ 0.1 ohm) */
#define SENSOR_SHUNT_R       0.005f        /* MLX91204 shunt resistor (typ 50 mOhm) */

/* ADS1115 register addresses */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/* Config register bit masks */
#define ADS1115_CFG_OS        0x8000       /* Operational status / single-shot bit */
#define ADS1115_CFG_MUX_A0   0x4000       /* AIN0 single-ended */
#define ADS1115_CFG_PGA_4_096 0x0200       /* PGA = 4.096 V */
#define ADS1115_CFG_MODE_SS  0x0100       /* Single-shot mode */
#define ADS1115_CFG_DR_128   0x0080       /* 128 SPS */
#define ADS1115_CFG_CQUE_NONE 0x0003       /* Disable comparator */

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_terminate = 0;

/* ----------------------------- Data Structures --------------------------- */
typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

/* ----------------------------- Prototypes ------------------------------- */
static void signal_handler(int sig);
static int  ads1115_init(int handle);
static int  ads1115_read_raw(int handle, int16_t *raw_out);
static float raw_to_current(int16_t raw);
static void buffer_add(CircularBuffer *cb, float value);
static float buffer_average(const CircularBuffer *cb);
static void set_led(int pin, bool on);
static void cleanup(int i2c_handle, CircularBuffer *cb);

/* ----------------------------- Signal Handler ---------------------------- */
static void signal_handler(int sig) {
    (void)sig;
    g_terminate = 1;
}

/* ----------------------------- ADS1115 Helpers --------------------------- */
static int ads1115_init(int handle) {
    uint16_t config = ADS1115_CFG_OS
                    | ADS1115_CFG_MUX_A0
                    | ADS1115_CFG_PGA_4_096
                    | ADS1115_CFG_MODE_SS
                    | ADS1115_CFG_DR_128
                    | ADS1115_CFG_CQUE_NONE;

    char cfg[2];
    cfg[0] = (char)(config >> 8);
    cfg[1] = (char)(config & 0xFF);

    if (i2cWriteI2CBlockData(handle, ADS1115_REG_CONFIG, cfg, 2) < 0) {
        fprintf(stderr, "Error: Failed to write ADS1115 config register.\n");
        return -1;
    }
    return 0;
}

static int ads1115_read_raw(int handle, int16_t *raw_out) {
    char conv[2];

    /* Trigger a single-shot conversion */
    uint16_t config = ADS1115_CFG_OS
                    | ADS1115_CFG_MUX_A0
                    | ADS1115_CFG_PGA_4_096
                    | ADS1115_CFG_MODE_SS
                    | ADS1115_CFG_DR_128
                    | ADS1115_CFG_CQUE_NONE;

    char cfg[2];
    cfg[0] = (char)(config >> 8);
    cfg[1] = (char)(config & 0xFF);

    if (i2cWriteI2CBlockData(handle, ADS1115_REG_CONFIG, cfg, 2) < 0) {
        fprintf(stderr, "Error: Failed to trigger ADS1115 conversion.\n");
        return -1;
    }

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    gpioDelay(10000);

    /* Read conversion result */
    if (i2cReadI2CBlockData(handle, ADS1115_REG_CONVERSION, conv, 2) < 0) {
        fprintf(stderr, "Error: Failed to read ADS1115 conversion register.\n");
        return -1;
    }

    *raw_out = (int16_t)(((uint16_t)(uint8_t)conv[0] << 8) | (uint8_t)conv[1]);
    return 0;
}

/* ----------------------------- Conversions -------------------------------- */
static float raw_to_current(int16_t raw) {
    float voltage = ((float)raw / ADC_MAX_VALUE) * ADC_VREF;
    float current = (voltage - SENSOR_SHUNT_R / SENSOR_R) / SENSOR_R;
    return current;
}

/* ----------------------------- Circular Buffer ---------------------------- */
static void buffer_add(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static float buffer_average(const CircularBuffer *cb) {
    if (cb->count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) sum += cb->buffer[i];
    return sum / (float)cb->count;
}

/* ----------------------------- LED Control -------------------------------- */
static void set_led(int pin, bool on) {
    gpioWrite(pin, on ? 1 : 0);
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(int i2c_handle, CircularBuffer *cb) {
    set_led(LED_PIN, false);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (cb) {
        fprintf(stderr, "Buffer contents:");
        for (int i = 0; i < cb->count; i++)
            fprintf(stderr, " %.2f", cb->buffer[i]);
        fprintf(stderr, "\n");
        free(cb);
    }
    gpioTerminate();
}

/* ----------------------------- Main --------------------------------------- */
int main(void) {
    CircularBuffer *cb = NULL;
    int i2c_handle = -1;
    int rc = EXIT_FAILURE;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure LED pin */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    set_led(LED_PIN, false);

    /* Allocate circular buffer */
    cb = (CircularBuffer *)calloc(1, sizeof(CircularBuffer));
    if (!cb) {
        fprintf(stderr, "Error: Memory allocation failed for circular buffer.\n");
        goto done;
    }
    cb->head = 0;
    cb->count = 0;

    /* Open I2C bus to ADS1115 */
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n",
                I2C_BUS, I2C_ADDR);
        goto done;
    }

    /* Initialize ADS1115 */
    if (ads1115_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: ADS1115 initialization failed (sensor absent or bus error).\n");
        goto done;
    }

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    fprintf(stderr, "MLX91204 current monitor started. Sampling at %d Hz.\n", SAMPLE_RATE_HZ);

    /* Main sampling loop */
    while (!g_terminate) {
        int16_t raw;
        if (ads1115_read_raw(i2c_handle, &raw) < 0) {
            fprintf(stderr, "Warning: ADC read failed, retrying...\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float current = raw_to_current(raw);
        buffer_add(cb, current);

        float avg = buffer_average(cb);
        set_led(LED_PIN, avg > CURRENT_THRESHOLD);

        printf("Current: %.2f A | Buffer avg: %.2f A | LED: %s\n",
               current, avg, (avg > CURRENT_THRESHOLD) ? "ON" : "OFF");

        gpioDelay(SAMPLE_PERIOD_US);
    }

    fprintf(stderr, "\nShutting down gracefully...\n");
    rc = EXIT_SUCCESS;

done:
    cleanup(i2c_handle, cb);
    return rc;
}

