#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <tcs34725.h>

#define I2C_BUS        "/dev/i2c-1"
#define CSV_FILENAME   "color_log.csv"
#define SAMPLE_PERIOD_NS 1000000000L  /* 1 second */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int ensure_csv_header(FILE *fp)
{
    long pos = ftell(fp);
    if (pos < 0) {
        perror("ftell");
        return -1;
    }
    if (pos == 0) {
        fprintf(fp, "timestamp,clear,red,green,blue\n");
        fflush(fp);
    }
    return 0;
}

static int log_data(FILE *fp, uint16_t clear, uint16_t red,
                    uint16_t green, uint16_t blue)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        perror("localtime_r");
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

int main(void)
{
    int i2c_fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() != 0) {
        goto cleanup;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open(" I2C_BUS ")");
        goto cleanup;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_DEFAULT_ADDRESS) < 0) {
        perror("ioctl(I2C_SLAVE)");
        goto cleanup;
    }

    /*
     * Probe the sensor by reading the ID register.
     * The TCS34725 returns 0x44 (0x30) when the ALS/color engine is enabled.
     */
    uint8_t id = 0;
    if (i2c_read_byte_data(i2c_fd, TCS34725_COMMAND_BIT,
                           TCS34725_CMD_ID) < 0) {
        fprintf(stderr, "Failed to read ID register (sensor may be absent)\n");
        goto cleanup;
    }
    id = (uint8_t)i2c_read_byte_data(i2c_fd, TCS34725_COMMAND_BIT,
                                     TCS34725_CMD_ID);
    if (id != TCS34725_DEFAULT_ID) {
        fprintf(stderr,
                "Unexpected ID 0x%02X (expected 0x%02X) — wrong sensor or "
                "wrong address\n",
                id, TCS34725_DEFAULT_ID);
        goto cleanup;
    }

    if (tcs34725_init(i2c_fd) != 0) {
        fprintf(stderr, "tcs34725_init failed\n");
        goto cleanup;
    }

    fp = fopen(CSV_FILENAME, "a");
    if (fp == NULL) {
        perror("fopen(" CSV_FILENAME ")");
        goto cleanup;
    }

    if (ensure_csv_header(fp) != 0) {
        goto cleanup;
    }

    /*
     * Wait at least 3 ms after power-on before the first read.
     * On a Raspberry Pi 4 the sensor is powered via the Adafruit
     * TCS34725 breakout board, which takes a short time to settle.
     */
    struct timespec wait = { .tv_sec = 0, .tv_nsec = 3000000L };
    nanosleep(&wait, NULL);

    int consecutive_failures = 0;

    while (g_running) {
        uint16_t clear = 0, red = 0, green = 0, blue = 0;
        int ok = 0;

        if (tcs34725_read_data(i2c_fd, &clear, &red, &green, &blue) == 0) {
            ok = 1;
        } else {
            fprintf(stderr, "tcs34725_read_data failed\n");
            consecutive_failures++;
        }

        if (ok) {
            if (log_data(fp, clear, red, green, blue) != 0) {
                fprintf(stderr, "log_data failed\n");
                consecutive_failures++;
            }
            consecutive_failures = 0;
        } else {
            if (consecutive_failures < 3) {
                /*
                 * Transient I2C error: wait and retry.
                 * On the Pi 4 the sensor is on the same bus as the
                 * main SoC, so short delays are safe.
                 */
                struct timespec delay = { .tv_sec = 0,
                                          .tv_nsec = 100000000L };
                nanosleep(&delay, NULL);
            } else {
                fprintf(stderr,
                        "Three consecutive I2C failures — aborting.\n");
                break;
            }
        }

        /*
         * Sleep for 1 s, but wake early if a signal arrives.
         * nanosleep returns 0 on success; set errno on interruption.
         */
        struct timespec remaining = { .tv_sec = 0,
                                      .tv_nsec = SAMPLE_PERIOD_NS };
        while (g_running && nanosleep(&remaining, &remaining) == -1 &&
               errno == EINTR) {
            /* interrupted by signal — loop to re-check g_running */
        }
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        fflush(fp);
        fclose(fp);
    }
    if (i2c_fd >= 0) {
        tcs34725_cleanup(i2c_fd);
        close(i2c_fd);
    }
    return rc;
}

