#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_DELAY_US    0
#define MOTOR_SHUTDOWN  17
#define OVERCURRENT_THRESHOLD 10.0
#define ADC_CHANNEL     0
#define ADC_MAX         1023
#define ADC_VREF        3.3
#define SAMPLE_INTERVAL 1
#define MAX_RETRIES     3

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static int log_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    unsigned char mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(spi_fd); spi_fd = -1;
        return -1;
    }

    unsigned char bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(spi_fd); spi_fd = -1;
        return -1;
    }

    unsigned int speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(spi_fd); spi_fd = -1;
        return -1;
    }

    return 0;
}

static int spi_read_channel(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = SPI_DELAY_US,
        .cs_change = 0,
    };

    for (int attempt = 1; attempt <= MAX_RETRIES; attempt++) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) >= 0) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %s\n",
                attempt, MAX_RETRIES, strerror(errno));
        if (attempt < MAX_RETRIES) {
            usleep(10000);
        }
    }
    return -1;
}

static float adc_to_amperes(int adc_value) {
    float voltage = (float)adc_value * ADC_VREF / (float)ADC_MAX;
    return voltage * 1000.0f / 10.0f;
}

static int log_open(void) {
    log_fd = open("current_log.csv", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("open(current_log.csv)");
        return -1;
    }

    long pos = lseek(log_fd, 0, SEEK_END);
    if (pos < 0) {
        perror("lseek");
        close(log_fd); log_fd = -1;
        return -1;
    }

    if (pos == 0) {
        if (dprintf(log_fd, "Timestamp,Current (A)\n") < 0) {
            perror("dprintf(header)");
            close(log_fd); log_fd = -1;
            return -1;
        }
    }
    return 0;
}

static int log_write(float current) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time");
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        perror("localtime_r");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (dprintf(log_fd, "%s,%.2f\n", ts, current) < 0) {
        perror("dprintf(data)");
        return -1;
    }

    if (fsync(log_fd) < 0) {
        perror("fsync");
        return -1;
    }
    return 0;
}

static int motor_init(void) {
    if (gpioSetMode(MOTOR_SHUTDOWN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", MOTOR_SHUTDOWN);
        return -1;
    }
    if (gpioWrite(MOTOR_SHUTDOWN, 1) < 0) {
        fprintf(stderr, "gpioWrite(%d, 1) failed\n", MOTOR_SHUTDOWN);
        return -1;
    }
    return 0;
}

static void motor_shutdown(void) {
    if (gpioWrite(MOTOR_SHUTDOWN, 0) < 0) {
        fprintf(stderr, "gpioWrite(%d, 0) failed\n", MOTOR_SHUTDOWN);
    }
}

static void cleanup(void) {
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_fd >= 0) {
        close(log_fd);
        log_fd = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (spi_init() < 0) {
        cleanup();
        return 1;
    }

    if (motor_init() < 0) {
        cleanup();
        return 1;
    }

    if (log_open() < 0) {
        cleanup();
        return 1;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc = spi_read_channel(ADC_CHANNEL);
        if (adc < 0) {
            fprintf(stderr, "ADC read failed; skipping sample\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        float current = adc_to_amperes(adc);

        if (log_write(current) < 0) {
            fprintf(stderr, "Log write failed\n");
        }

        printf("Current: %.2f A\n", current);

        if (current > OVERCURRENT_THRESHOLD) {
            fprintf(stderr, "OVERCURRENT DETECTED! Shutting down motor.\n");
            motor_shutdown();
            sleep(SAMPLE_INTERVAL);
            motor_shutdown();
            fprintf(stderr, "Motor re-enabled.\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    motor_shutdown();
    cleanup();
    return 0;
}

