#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_PERIOD  1.0
#define MAX_CONSEC_ERR 10

/* MLX90817 register map (16-bit big-endian, pigpio returns little-endian word) */
#define REG_PRESSURE_RAW  0x00
#define REG_TEMP_RAW      0x02
#define REG_SCALE_FACTOR  0x04
#define REG_OFFSET        0x06

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Read a 16-bit big-endian register from the MLX90817.
 * Returns 0 on success and stores the value in *out; returns -1 on error. */
static int read_register(int handle, uint8_t reg, uint16_t *out)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed for register 0x%02X (pigpio rc=%d)\n",
                reg, rc);
        return -1;
    }
    /* pigpio returns the word in little-endian byte order; swap to get big-endian */
    uint16_t val = (uint16_t)rc;
    *out = ((val >> 8) & 0xFF) | ((val & 0xFF) << 8);
    return 0;
}

/* Convert raw pressure to kPa using the scale-factor / 4 + offset formula. */
static float convert_pressure(uint16_t raw_p, uint16_t scale, uint16_t offset)
{
    int32_t scaled = (int32_t)scale;
    int32_t off    = (int32_t)offset;
    int32_t p_raw  = (int32_t)raw_p;
    return ((float)(p_raw - off) / (float)scaled) + 0.0f;
}

/* Append one CSV line: timestamp,pressure_kPa. Returns 0 on success, -1 on error. */
static int log_data(FILE *fp, float pressure)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return -1;
    }
    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r() failed\n");
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%.2f\n", ts, pressure) < 0) {
        fprintf(stderr, "fprintf() to log file failed\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush() failed\n");
        return -1;
    }
    return 0;
}

int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed (rc=%d) — sensor absent or bus error\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
