    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        fclose(g_log_file);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- read calibration --- */
    uint16_t scale_raw = 0, offset_raw = 0;
    int consec_err = 0;

    if (read_register(g_i2c_handle, REG_SCALE_FACTOR, &scale_raw) != 0) {
        fprintf(stderr, "Failed to read scale factor — aborting\n");
        goto cleanup;
    }
    if (read_register(g_i2c_handle, REG_OFFSET, &offset_raw) != 0) {
