#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define LED_GPIO       17
#define PRESSURE_THRESHOLD 105.0f
#define MAX_RETRIES    3
#define SAMPLE_PERIOD_US 1000000

/* ADS1115 registers */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/* Config register bits */
#define ADS1115_CFG_OS        0x8000  /* Operational status / single-shot bit */
#define ADS1115_CFG_MUX_AIN0  0x4000  /* AIN0 vs GND */
#define ADS1115_CFG_MUX_AIN1  0x5000  /* AIN1 vs GND */
#define ADS1115_CFG_PGA_4_096 0x0200  /* +/-4.096 V */
#define ADS1115_CFG_MODE_SS   0x0100  /* Single-shot mode */
#define ADS1115_CFG_DR_128    0x0080  /* 128 SPS */
#define ADS1115_CFG_CQUE_NONE 0x0003  /* Disable comparator */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_word(int handle, uint8_t reg, uint16_t val) {
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)((val >> 8) & 0xFF);
    buf[2] = (char)(val & 0xFF);
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_word(int handle, uint8_t reg, uint16_t *out) {
    char buf[2];
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int read_ads1115_channel(int handle, uint16_t mux, int16_t *result) {
    uint16_t config = ADS1115_CFG_OS | mux | ADS1115_CFG_PGA_4_096 |
                      ADS1115_CFG_MODE_SS | ADS1115_CFG_DR_128 |
                      ADS1115_CFG_CQUE_NONE;

    if (i2c_write_word(handle, ADS1115_REG_CONFIG, config) < 0) return -1;

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    gpioDelay(10000);

    uint16_t raw;
    if (i2c_read_word(handle, ADS1115_REG_CONVERSION, &raw) < 0) return -1;

    *result = (int16_t)raw;
    return 0;
}

static int read_pressure(int handle, float *pressure) {
    int16_t raw;
    if (read_ads1115_channel(handle, ADS1115_CFG_MUX_AIN0, &raw) < 0) return -1;

    /* Convert to voltage: PGA +/-4.096 V, 16-bit signed => LSB = 4.096/32768 V */
    float voltage = (float)raw * 4.096f / 32768.0f;

    /* MLX90834 SENT pressure: 0.5 bar to 2.5 bar => 0.5 V to 2.5 V */
    *pressure = (voltage / 2.0f) * 100.0f;
    return 0;
}

static int read_temperature(int handle, float *temperature) {
    int16_t raw;
    if (read_ads1115_channel(handle, ADS1115_CFG_MUX_AIN1, &raw) < 0) return -1;

    /* NTC: V = Vref * (Rref / R_NTC)^4 */
    const float vref = 4.096f;
    const float rref = 10.0f;
    const float r0 = 10.0f;
    const float alpha = 0.00332f;

    float r_ntc = 10.0f * (1.0f - expf(-raw / 32768.0f));
    if (r_ntc <= 0.0f) return -1;

    float resistance = r_ntc;
    float temp = (rref / resistance) * (1.0f - alpha * (rref / resistance - 1.0f));
    if (temp < 0.0f) temp = 0.0f;

    *temperature = temp;
    return 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", LED_GPIO);
        cleanup();
        return 1;
    }
    gpioWrite(LED_GPIO, 0);

    printf("MLX90834 Pressure Sensor Reader (ADS1115 ADC)\n");
    printf("Pressure threshold: %.1f kPa\n", PRESSURE_THRESHOLD);
    printf("Press Ctrl+C to exit\n\n");

    while (g_running) {
        float pressure = 0.0f, temperature = 0.0f;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_pressure(g_i2c_handle, &pressure) == 0 &&
                read_temperature(g_i2c_handle, &temperature) == 0) {
                ok = 1;
                break;
            }
            fprintf(stderr, "I2C read error (attempt %d/%d)\n",
                    attempt + 1, MAX_RETRIES);
            gpioDelay(10000);
        }

        if (!ok) {
            fprintf(stderr, "Failed to read sensor after %d attempts. "
                            "Check wiring and I2C address.\n", MAX_RETRIES);
            gpioWrite(LED_GPIO, 0);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        printf("Pressure: %7.2f kPa | Temperature: %6.2f C\n",
               pressure, temperature);

        if (pressure > PRESSURE_THRESHOLD) {
            gpioWrite(LED_GPIO, 1);
            printf("  *** WARNING: Pressure exceeds %.1f kPa ***\n",
                   PRESSURE_THRESHOLD);
        } else {
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

