/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* MCP3008 on SPI0 CE0 (BCM GPIO8)          */
#define SPI_SPEED      1000000    /* 1 MHz                                   */
#define SPI_FLAGS      0          /* Mode 0, active-low CE                   */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0          */
#define OVERCURRENT_THRESHOLD 10.0 /* Amperes                                */
#define SHUTDOWN_PIN   27         /* BCM GPIO27 — motor shutdown control     */
#define LOG_FILE       "current_log.txt"
#define SAMPLE_US      100000     /* 100 ms between samples                  */

/* ----------------------------- Globals ---------------------------------- */
static int      spi_handle = -1;
static FILE    *log_file   = NULL;
static volatile sig_atomic_t terminate = 0;

/* ----------------------------- Prototypes -------------------------------- */
static int  read_mcp3008(int channel, int *out_value);
static void log_current(double current);
static void shutdown_motor(void);
static void cleanup(void);
static void signal_handler(int sig);

/* ----------------------------- MCP3008 read ------------------------------ */
/*
 * MCP3008 single-ended read sequence (3 bytes):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits).
 */
static int read_mcp3008(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0, 0, 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed (returned %d)\n", ret);
        return -1;
    }

    int raw = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    if (raw < 0 || raw > 1023) {
        fprintf(stderr, "ADC value out of range: %d\n", raw);
        return -1;
    }

    *out_value = raw;
    return 0;
}

/* ----------------------------- Logging ----------------------------------- */
static void log_current(double current)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(log_file, "%s, %.2f\n", ts, current) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed\n");
    }
}

/* ----------------------------- Motor shutdown ---------------------------- */
static void shutdown_motor(void)
{
    if (gpioWrite(SHUTDOWN_PIN, 1) != 0) {
        fprintf(stderr, "Failed to set shutdown pin HIGH\n");
        return;
    }
    printf("Motor shut down (GPIO%d HIGH)\n", SHUTDOWN_PIN);
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    /* Ensure shutdown pin is LOW before releasing pigpio */
    gpioWrite(SHUTDOWN_PIN, 0);
    gpioTerminate();
}

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Shutdown pin as output, LOW --- */
    if (gpioSetMode(SHUTDOWN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SHUTDOWN_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(SHUTDOWN_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise GPIO%d LOW\n", SHUTDOWN_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open SPI --- */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Cannot open log file '%s'\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Current monitoring started. Logging to '%s'. Press Ctrl+C to exit.\n",
           LOG_FILE);

    /* --- Main loop --- */
    while (!terminate) {
        int raw = 0;
        if (read_mcp3008(ADC_CHANNEL, &raw) != 0) {
            fprintf(stderr, "ADC read error — skipping sample\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        double current = (double)raw * 0.001; /* 10 mV / ADC count */

        log_current(current);

        if (current > OVERCURRENT_THRESHOLD) {
            printf("OVERCURRENT DETECTED: %.2f A\n", current);
            shutdown_motor();
            break;
        }

        gpioDelay(SAMPLE_US);
    }

    /* --- Cleanup --- */
    cleanup();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

