#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <stdint.h>

#define SPI_BUS              0
#define SPI_DEVICE           0
#define SPI_SPEED_HZ         1000000
#define SPI_MODE             0
#define SPI_BITS_PER_WORD    8
#define MCP3008_CHANNEL      0
#define METHANE_THRESHOLD    1000.0f
#define LOG_FILE             "methane_log.txt"
#define SAMPLE_INTERVAL_SEC  1
#define MAX_SPI_RETRIES      3

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0 on success and stores the 10-bit ADC value in *adc_value;
 * returns -1 on failure.
 */
static int read_mcp3008(int spi_handle, int channel, int *adc_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read sequence (3 bytes):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (SGL/DIFF=1, D2 D1 D0 = channel)
     *   Byte 2: 0x00  (don't care, clocks out low 2 bits)
     * Response: bits 9..0 are in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    for (int attempt = 1; attempt <= MAX_SPI_RETRIES; ++attempt) {
        int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (ret == 3) {
            *adc_value = ((rx[1] & 0x03) << 8) | rx[2];
            return 0;
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d, ret=%d): %s\n",
                attempt, MAX_SPI_RETRIES, ret, strerror(errno));
        if (attempt < MAX_SPI_RETRIES) {
            usleep(10000); /* 10 ms back-off before retry */
        }
    }
    return -1;
}

static float adc_to_ppm(int adc_value)
{
    /*
     * Placeholder linear conversion; replace with calibrated curve from
     * the Honeywell MICROpeL 41000-020 datasheet.
     */
    return (float)adc_value * 0.1f;
}

static int log_reading(const char *filename, float methane_ppm)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
