     */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    for (int attempt = 1; attempt <= MAX_SPI_RETRIES; ++attempt) {
        int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (ret == 3) {
            *adc_value = ((rx[1] & 0x03) << 8) | rx[2];
            return 0;
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d, ret=%d): %s\n",
                attempt, MAX_SPI_RETRIES, ret, strerror(errno));
        if (attempt < MAX_SPI_RETRIES) {
            usleep(10000); /* 10 ms back-off before retry */
        }
    }
    return -1;
