/*
 * Raspberry Pi 3 Model B+ — HIH-4602-A humidity sensor via MCP3208 ADC
 *
 * Wiring:
 *   MCP3208 VDD  -> 3.3 V (Pin 1)
 *   MCP3208 VREF -> 3.3 V (Pin 1)
 *   MCP3208 AGND -> GND
 *   MCP3208 DGND -> GND
 *   MCP3208 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3208 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3208 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3208 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3208 CH0  -> HIH-4602-A analog output (0–3.3 V)
 *
 * Build: gcc -O2 -Wall -o humidity_monitor humidity_monitor.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define LOG_FILE        "humidity_log.txt"
#define HUMIDITY_THRESHOLD 0.80
#define SAMPLE_INTERVAL_SEC 5
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_DELAY_US    0

#define ADC_CHANNEL     0
#define ADC_MAX_VALUE   4095
#define ADC_VREF        3.3

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SPI / MCP3208 helpers                                               */
/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    return 0;
}

/*
 * MCP3208 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 12-bit value in ((rx[1] & 0x0F) << 8) | rx[2]
 */
static int mcp3208_read(uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = SPI_DELAY_US;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        return -1;
    }

    return ((rx[1] & 0x0F) << 8) | rx[2];
}

/* ------------------------------------------------------------------ */
/* Conversion formulas (per Honeywell HIH-4602-A datasheet)             */
/* ------------------------------------------------------------------ */
static float adc_to_humidity(int adc_value)
{
    float h = (float)adc_value / (float)ADC_MAX_VALUE;
    float humidity = 100.0f * (powf(h, 2.0f) - powf(h, 3.0f)) + 65.0f;
    if (humidity < 0.0f)   humidity = 0.0f;
    if (humidity > 100.0f) humidity = 100.0f;
    return humidity;
}

static float adc_to_temperature(int adc_value)
{
