#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define LOG_FILE        "temperature_log.csv"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0
#define ADC_CHANNEL     0
#define ADC_MAX_VALUE   4095
#define ADC_VREF        3.3f
#define TMP36_OFFSET    0.5f
#define TMP36_SCALE     100.0f
#define SAMPLE_DELAY_US 1000000
#define MAX_CONSECUTIVE_ERRORS 10

static volatile sig_atomic_t program_running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *ce_line = NULL;
static struct gpiod_line *sclk_line = NULL;
static struct gpiod_line *mosi_line = NULL;
static struct gpiod_line *miso_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(spi_fd); spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(spi_fd); spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(spi_fd); spi_fd = -1;
        return -1;
    }

    return 0;
}

static int gpio_init(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name(gpiochip4)");
        return -1;
    }

    ce_line = gpiod_chip_get_line(chip, 8);
    sclk_line = gpiod_chip_get_line(chip, 11);
    mosi_line = gpiod_chip_get_line(chip, 10);
    miso_line = gpiod_chip_get_line(chip, 9);

    if (!ce_line || !sclk_line || !mosi_line || !miso_line) {
        fprintf(stderr, "gpiod_chip_get_line failed\n");
        return -1;
    }

    if (gpiod_line_request_output(ce_line, "mcp3208_ce", 1) < 0) {
        perror("gpiod_line_request_output(ce)");
        return -1;
    }
    if (gpiod_line_request_output(sclk_line, "mcp3208_sclk", 0) < 0) {
        perror("gpiod_line_request_output(sclk)");
        return -1;
    }
    if (gpiod_line_request_output(mosi_line, "mcp3208_mosi", 0) < 0) {
        perror("gpiod_line_request_output(mosi)");
        return -1;
    }
    if (gpiod_line_request_input(miso_line, "mcp3208_miso") < 0) {
        perror("gpiod_line_request_input(miso)");
        return -1;
    }

    return 0;
}

static int mcp3208_read(uint8_t channel) {
    if (channel > 7) return -1;

    uint8_t tx[3] = { 0x01, (uint8_t)((channel & 0x07) << 6), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (gpiod_line_set_value(ce_line, 0) < 0) {
        perror("gpiod_line_set_value(ce)");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        gpiod_line_set_value(ce_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(ce_line, 1) < 0) {
        perror("gpiod_line_set_value(ce)");
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float adc_to_celsius(int adc_value) {
    float voltage = (float)adc_value * ADC_VREF / (float)(ADC_MAX_VALUE + 1);
    return (voltage - TMP36_OFFSET) * TMP36_SCALE;
}

static int log_data(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (!timeinfo) {
        perror("localtime");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.2f\n", timestamp, temperature) < 0) {
        perror("fprintf");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (ce_line) {
        gpiod_line_release(ce_line);
        ce_line = NULL;
    }
    if (sclk_line) {
        gpiod_line_release(sclk_line);
        sclk_line = NULL;
    }
    if (mosi_line) {
        gpiod_line_release(mosi_line);
        mosi_line = NULL;
    }
    if (miso_line) {
        gpiod_line_release(miso_line);
        miso_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,temperature_celsius\n");
        fflush(log_file);
    }

    int consecutive_errors = 0;

    while (program_running) {
        int adc_value = mcp3208_read(ADC_CHANNEL);
        if (adc_value < 0) {
            consecutive_errors++;
            fprintf(stderr, "SPI transfer error (consecutive: %d)\n", consecutive_errors);
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr, "Too many consecutive SPI errors, aborting.\n");
                break;
            }
            usleep(SAMPLE_DELAY_US);
            continue;
        }
        consecutive_errors = 0;

        if (adc_value > ADC_MAX_VALUE) {
            fprintf(stderr, "ADC value out of range: %d\n", adc_value);
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        float temperature = adc_to_celsius(adc_value);

        if (temperature < -40.0f || temperature > 125.0f) {
            fprintf(stderr, "Temperature out of valid range: %.2f\n", temperature);
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        if (log_data(temperature) < 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        usleep(SAMPLE_DELAY_US);
    }

    cleanup();
    return 0;
}

