/*
 * ADXL335 Impact Logger for Raspberry Pi 4 Model B
 *
 * Hardware:
 *   - ADXL335 analog accelerometer (I2C/SPI variant) -> MCP3008 ADC
 *   - MCP3008 SPI ADC on SPI0 (CE0 / GPIO8), 1 MHz, mode 0
 *   - ADXL335 X -> MCP3008 CH0, Y -> CH1, Z -> CH2
 *
 * Build:
 *   gcc -O2 -Wall -o impact_logger impact_logger.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./impact_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define SPI_CHANNEL    0          /* MCP3008 on CE0 (GPIO8)                  */
#define SPI_SPEED      1000000    /* 1 MHz                                   */
#define SPI_FLAGS      0          /* Mode 0, active-low CS handled by pigpio */

#define ADC_CHANNEL_X  0
#define ADC_CHANNEL_Y  1
#define ADC_CHANNEL_Z  2

#define SAMPLE_RATE_HZ  100
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

#define IMPACT_THRESHOLD  5000   /* Raw ADC count above which an impact is logged */

#define LOG_FILE_NAME    "impact_log.txt"

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int      g_spi_handle = -1;
static FILE    *g_log_file   = NULL;

/* ----------------------------- Prototypes -------------------------------- */

static int  initialize_spi(void);
static int  read_adc_channel(int channel);
static void log_data(int x, int y, int z);
static void log_impact(int x, int y, int z);
static void cleanup(void);
static void signal_handler(int sig);

/* ----------------------------- SPI --------------------------------------- */

static int initialize_spi(void)
{
    /*
     * pigpio drives CE0 automatically when spiOpen uses channel 0.
     * Flags bit 0 (resv) = 0  -> mode 0, active-low CS.
     */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (pigpio error %d).\n", g_spi_handle);
        return -1;
    }
    return 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 *
 * MCP3008 SPI protocol (3-byte transfer, mode 0):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   tx[2] = 0x00                       (clock out remaining bits)
 *   rx[1] bits 1:0 + rx[2] bits 7:0     (10-bit result)
 *
 * Returns the 10-bit ADC value (0–1023) or -1 on error.
 */
static int read_adc_channel(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d.\n", channel);
        return -1;
    }

    char tx[3];
    char rx[3];

    tx[0] = 0x01;
    tx[1] = (char)((0x08 | channel) << 4);
    tx[2] = 0x00;

    /*
     * pigpio asserts/de-asserts CE0 automatically around the 3-byte transfer.
     * We still guard the transfer with a brief check to catch pigpio errors.
     */
    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: spiXfer returned %d (expected 3).\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);

    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
        return -1;
    }
    return adc_value;
}

/* ----------------------------- Logging ----------------------------------- */

static void log_data(int x, int y, int z)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(g_log_file);
}

static void log_impact(int x, int y, int z)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s,IMPACT DETECTED,X=%d,Y=%d,Z=%d\n",
            timestamp, x, y, z);
    fflush(g_log_file);
}

/* ----------------------------- Cleanup / Signal --------------------------- */

static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Main -------------------------------------- */

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    if (initialize_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE_NAME);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed; "
                        "Ctrl+C will not clean up gracefully.\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed.\n");
    }

    printf("Impact logger started. Logging to '%s'. Press Ctrl+C to stop.\n",
           LOG_FILE_NAME);

    /* Main sampling loop */
    while (g_running) {
        int x = read_adc_channel(ADC_CHANNEL_X);
        int y = read_adc_channel(ADC_CHANNEL_Y);
        int z = read_adc_channel(ADC_CHANNEL_Z);

        if (x < 0 || y < 0 || z < 0) {
            fprintf(stderr, "Error: ADC read failure; skipping sample.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        log_data(x, y, z);

        if (x > IMPACT_THRESHOLD || y > IMPACT_THRESHOLD || z > IMPACT_THRESHOLD) {
            log_impact(x, y, z);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

