/*
 * Raspberry Pi Zero W - Si1172 Heart Rate / SpO2 Logger
 *
 * Reads raw IR and RED ADC values from the Si1172 optical sensor on I2C
 * bus 1, logs them to biometric_log.csv once per second, and handles
 * SIGINT for graceful shutdown.
 *
 * NOTE: The Si1172 requires a proprietary algorithm to convert raw PPG
 * samples into meaningful HR and SpO2 values.  This program logs the
 * raw 16-bit IR and RED ADC values as proxy metrics and documents the
 * limitation.  A production implementation must integrate the Si1172
 * algorithm (e.g., via the Silicon Labs SDK).
 *
 * Build:  gcc -O2 -Wall -o biometric_log biometric_log.c -lsi1172
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <si1172.h>

#define I2C_BUS        1
#define SI1172_ADDR    0x60
#define LOG_FILE       "biometric_log.csv"
#define SAMPLE_PERIOD  1   /* seconds */

/* Si1172 register addresses (command / command-response bank) */
#define SI1172_REG_HW_KEY      0x01
#define SI1172_REG_HW_KEY_VAL  0x17
#define SI1172_REG_MEAS_RATE   0x08
#define SI1172_REG_IRQ_ENABLE  0x0F
#define SI1172_REG_IRQ_STATUS  0x12
#define SI1172_REG_FIFO_COUNT  0x14
#define SI1172_REG_FIFO_DATA   0x15
#define SI1172_REG_RESPONSE0   0x20
#define SI1172_REG_RESPONSE1   0x21
#define SI1172_REG_RESPONSE2   0x22
#define SI1172_REG_RESPONSE3   0x23
#define SI1172_REG_RESPONSE4   0x24
#define SI1172_REG_RESPONSE5   0x25
#define SI1172_REG_RESPONSE6   0x26
#define SI1172_REG_RESPONSE7   0x27
#define SI1172_REG_RESPONSE8   0x28
#define SI1172_REG_RESPONSE9   0x29
#define SI1172_REG_RESPONSE10  0x2A
#define SI1172_REG_RESPONSE11  0x2B
#define SI1172_REG_RESPONSE12  0x2C
#define SI1172_REG_RESPONSE13  0x2D
#define SI1172_REG_RESPONSE14  0x2E
#define SI1172_REG_RESPONSE15  0x2F

/* Si1172 command codes (16-bit, big-endian on the bus) */
#define SI1172_CMD_RESET        0x01
#define SI1172_CMD_ALS_FORCE    0x06
#define SI1172_CMD_PS_FORCE     0x05
#define SI1172_CMD_PSALS_FORCE  0x07

/* Expected response codes (16-bit, big-endian on the bus) */
#define SI1172_RESP_OK          0x0001
#define SI1172_RESP_ERR_PARAM   0x0002
#define SI1172_RESP_ERR_CMD    0x0003
#define SI1172_RESP_ERR_HW     0x0004
#define SI1172_RESP_ERR_BUSY   0x0005

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int handle, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (i2cWriteDevice(handle, (char *)buf, 2) != 2) {
        fprintf(stderr, "[I2C] write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    uint8_t wbuf[1] = { reg };
    uint8_t rbuf[2] = { 0 };

    if (i2cWriteDevice(handle, (char *)wbuf, 1) != 1) {
        fprintf(stderr, "[I2C] write reg-addr 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (i2cReadDevice(handle, (char *)rbuf, 2) != 2) {
        fprintf(stderr, "[I2C] read reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)rbuf[0] << 8) | rbuf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Si1172 driver                                                       */
/* ------------------------------------------------------------------ */
static int si1172_init(int handle)
{
    uint16_t resp = 0;

    /* 1. Software reset */
    if (i2c_write_reg8(handle, SI1172_REG_HW_KEY, SI1172_REG_HW_KEY_VAL) != 0)
        return -1;
    if (i2c_write_reg8(handle, SI1172_REG_MEAS_RATE, 0x00) != 0)
        return -1;
    if (i2c_write_reg8(handle, SI1172_REG_IRQ_ENABLE, 0x00) != 0)
        return -1;

    /* 2. Issue a reset command and read the response */
    if (i2c_write_reg8(handle, SI1172_REG_IRQ_STATUS, SI1172_CMD_RESET) != 0)
        return -1;
    usleep(10000);  /* allow reset to complete */
    if (i2c_read_reg16(handle, SI1172_REG_RESPONSE0, &resp) != 0)
        return -1;
    if (resp != SI1172_RESP_OK) {
        fprintf(stderr, "[Si1172] reset response 0x%04X (expected 0x%04X)\n",
                resp, SI1172_RESP_OK);
        return -1;
    }

    /* 3. Configure measurement rate (e.g., 100 ms) */
    if (i2c_write_reg8(handle, SI1172_REG_MEAS_RATE, 0x08) != 0)
        return -1;

    /* 4. Clear any pending IRQ */
    if (i2c_write_reg8(handle, SI1172_REG_IRQ_STATUS, 0x00) != 0)
        return -1;

    return 0;
}

static int si1172_read_data(int handle, uint16_t *ir_raw, uint16_t *red_raw)
{
    uint16_t resp = 0;

    /* Trigger a forced ALS+PS measurement */
    if (i2c_write_reg8(handle, SI1172_REG_IRQ_STATUS, SI1172_CMD_PSALS_FORCE) != 0)
        return -1;

    /* Poll for completion (FIFO count > 0) */
    for (int i = 0; i < 20; i++) {
        if (i2c_read_reg16(handle, SI1172_REG_FIFO_COUNT, &resp) != 0)
            return -1;
        if (resp & 0x0001)
            break;
        usleep(5000);
    }
    if (!(resp & 0x0001)) {
        fprintf(stderr, "[Si1172] measurement timeout\n");
        return -1;
    }

    /* Read IR and RED FIFO bytes (big-endian) */
    uint8_t wbuf[1] = { SI1172_REG_FIFO_DATA };
    uint8_t rbuf[4] = { 0 };

    if (i2cWriteDevice(handle, (char *)wbuf, 1) != 1) {
        fprintf(stderr, "[I2C] write FIFO reg failed: %s\n", strerror(errno));
        return -1;
    }
    if (i2cReadDevice(handle, (char *)rbuf, 4) != 4) {
        fprintf(stderr, "[I2C] read FIFO data failed: %s\n", strerror(errno));
        return -1;
    }

    *ir_raw  = ((uint16_t)rbuf[0] << 8) | rbuf[1];
    *red_raw = ((uint16_t)rbuf[2] << 8) | rbuf[3];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, time_t ts, uint16_t ir, uint16_t red,
                     int err_flag)
{
    if (fp == NULL)
        return;
    fprintf(fp, "%ld,%u,%u,%d\n", (long)ts, ir, red, err_flag);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    si1172_terminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Register signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize Si1172 driver */
    if (si1172_init() != 0) {
        fprintf(stderr, "Si1172 initialization failed (sensor may be absent or uninitialized).\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, SI1172_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,ir_raw,red_raw,error_flag\n");
        fflush(g_log_file);
    }

    printf("Logging Si1172 data to %s. Press Ctrl-C to stop.\n", LOG_FILE);

    /* Main sampling loop */
    while (g_running) {
        uint16_t ir_raw = 0, red_raw = 0;
        time_t now = time(NULL);
        int err_flag = 0;

        if (si1172_read_data(g_i2c_handle, &ir_raw, &red_raw) != 0) {
            err_flag = 1;  /* transient I2C error */
        } else {
            /* Log raw values as proxy metrics (per limitation note above) */
            log_data(g_log_file, now, ir_raw, red_raw, err_flag);
        }

        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

