#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/*
 * Raspberry Pi 4 Model B – Honeywell SpiroQuant A+ ES1-005 Mass Flow Sensor
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> SpiroQuant A+ analog output
 *
 * SPI: channel 0 (CE0), 1 MHz, mode 0 (CPOL=0, CPHA=0).
 * Flow sensor: 0–5 L/min full scale, 10-bit ADC (0–1023).
 */

#define SPI_CHANNEL    0
#define SPI_SPEED      1000000          /* 1 MHz */
#define SPI_FLAGS      0                /* mode 0, active-low CE */
#define ADC_CHANNEL    0
#define ADC_MAX_VALUE  1023
#define FLOW_MIN       0.0f
#define FLOW_MAX       5.0f
#define LOG_FILE       "flow_log.csv"
#define SAMPLE_PERIOD  1000000          /* 1 second in microseconds */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static int get_timestamp(char *buf, size_t len)
{
    struct timeval tv;
    struct tm tm_info;

    if (gettimeofday(&tv, NULL) != 0)
        return -1;

    if (localtime_r(&tv.tv_sec, &tm_info) == NULL)
        return -1;

    if (strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info) == 0)
        return -1;

    size_t used = strlen(buf);
    int written = snprintf(buf + used, len - used, ".%06ld",
                           (long)tv.tv_usec);
    if (written < 0 || (size_t)written >= len - used)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Flow conversion                                                     */
/* ------------------------------------------------------------------ */
static float adc_to_flow(int adc_value)
{
    if (adc_value < 0)
        adc_value = 0;
    if (adc_value > ADC_MAX_VALUE)
        adc_value = ADC_MAX_VALUE;

    /* Linear mapping: 0 V -> 0 L/min, Vref -> FLOW_MAX */
    return ((float)adc_value / (float)ADC_MAX_VALUE) * FLOW_MAX;
}

/* ------------------------------------------------------------------ */
/* SPI transfer                                                        */
/* ------------------------------------------------------------------ */
static int read_adc(int handle, int channel, int *out_value)
{
    if (handle < 0 || out_value == NULL)
        return -1;

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: rx[1] low 2 bits + rx[2] 8 bits = 10-bit ADC value.
     */
    char tx[3] = { 0x01, (char)((0x08 | (channel & 0x07)) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (spiXfer returned %d)\n", ret);
        return -1;
    }

    *out_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
    if (g_log_fp != NULL) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI open --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,flow_rate_lpm\n");
        fflush(g_log_fp);
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flow sensor logging started. Press Ctrl+C to stop.\n");

    /* --- Main loop --- */
    while (g_running) {
        int adc_value = 0;

        if (read_adc(g_spi_handle, ADC_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "ADC read error – continuing\n");
            gpioDelay(SAMPLE_PERIOD);
            continue;
        }

        float flow_rate = adc_to_flow(adc_value);

        /* Sensor-absent / out-of-range detection */
        if (adc_value == 0) {
            fprintf(stderr,
                    "Warning: ADC reads 0 – sensor may be absent or disconnected\n");
        }
        if (flow_rate < FLOW_MIN || flow_rate > FLOW_MAX) {
            fprintf(stderr,
                    "Warning: flow rate %.2f L/min out of range [%.1f, %.1f]\n",
                    flow_rate, FLOW_MIN, FLOW_MAX);
        }

        char ts[32];
        if (get_timestamp(ts, sizeof(ts)) != 0) {
            fprintf(stderr, "Timestamp generation failed\n");
            gpioDelay(SAMPLE_PERIOD);
            continue;
        }

        if (fprintf(g_log_fp, "%s,%.2f\n", ts, flow_rate) < 0) {
            perror("fprintf");
        } else {
            fflush(g_log_fp);
        }

        gpioDelay(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

