#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ICP10125_ADDR  0x29
#define CSV_FILE       "environmental_data.csv"
#define SAMPLE_PERIOD  5

/* ICP-10125 high-precision measurement command */
#define CMD_MEAS_HP    0x3F

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        perror("i2c_write_cmd: write");
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        perror("i2c_read_bytes: read");
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "i2c_read_bytes: short read (%zd of %zu)\n", n, len);
        return -1;
    }
    return 0;
}

static int read_sensor_data(int fd, int32_t *raw_p, int32_t *raw_t)
{
    uint8_t cmd = CMD_MEAS_HP;
    uint8_t data[6];

    if (i2c_write_cmd(fd, cmd) < 0)
        return -1;

    /* High-precision measurement takes ~45 ms; give a small margin */
    usleep(50000);

    if (i2c_read_bytes(fd, data, sizeof(data)) < 0)
        return -1;

    *raw_p = ((int32_t)data[0] << 8) | data[1];
    *raw_t = ((int32_t)data[2] << 8) | data[3];
    /* data[4..5] are CRC bytes; not needed for conversion formulas */
    return 0;
}

static void convert_data(int32_t raw_p, int32_t raw_t,
                         float *temp_c, float *press_pa)
{
    /* Temperature: linear interpolation between two points */
    const float t_ref = -40.0f;
    const float t_span = 125.0f;
    const float p_ref = 45000.0f;
    const float p_span = 115000.0f;

    float t_slope = (t_span / 125.0f) * 100.0f;
    float t_intercept = t_ref - t_slope * 0.5f;

    *temp_c = t_intercept + (raw_t - 32768.0f) * t_slope / 65536.0f;

    /* Pressure: linear interpolation with scale factor */
    float p_slope = (p_span / 125.0f) * 100.0f;
    float p_intercept = p_ref - p_slope * 0.5f;

    *press_pa = p_intercept + (raw_p - 32768.0f) * p_slope / 65536.0f;
}

static void log_data(FILE *fp, float temp_c, float press_pa)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, temp_c, press_pa);
    fflush(fp);
}

static void display_data(float temp_c, float press_pa)
{
    printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temp_c, press_pa);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open(" I2C_BUS ")");
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(CSV_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen(" CSV_FILE ")");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,temperature_c,pressure_pa\n");
        fflush(g_log_fp);
    }

    printf("ICP-10125 environmental monitor started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int32_t raw_p = 0, raw_t = 0;

        if (read_sensor_data(g_i2c_fd, &raw_p, &raw_t) < 0) {
            fprintf(stderr, "Sensor read failed; retrying in %d s.\n", SAMPLE_PERIOD);
            sleep(SAMPLE_PERIOD);
            continue;
        }

        float temp_c, press_pa;
        convert_data(raw_p, raw_t, &temp_c, &press_pa);

        log_data(g_log_fp, temp_c, press_pa);
        display_data(temp_c, press_pa);

        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");

    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    return EXIT_SUCCESS;
}

