/*
 * MP23ABS1 Dual Microphone Noise Cancellation via MCP3008 ADC
 * Board: Raspberry Pi 3 Model B+
 * SPI0 CE0 (GPIO8), SCLK (GPIO11), MOSI (GPIO10), MISO (GPIO9)
 *
 * Build: gcc -o mic_nc mic_nc.c -lm
 * Run:   ./mic_nc gain1 gain2
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0

#define ADC_CHANNEL_MIC1 0
#define ADC_CHANNEL_MIC2 1

#define SAMPLE_RATE_HZ 16000
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0-1023 on success, -1 on error.
 */
static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (Mode 0, 0): 3 bytes.
     * Byte 0: 0x01 (Start bit)
     * Byte 1: (0x08 | channel) << 4 (Single-ended + channel select)
     * Byte 2: 0x00 (Don't care, clocked out to read low byte)
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(SPI_CHANNEL, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", bytes);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] + 8 bits of rx[2] */
    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <gain1> <gain2>\n", argv[0]);
        return EXIT_FAILURE;
    }

    char *endptr;
    float gain1 = strtof(argv[1], &endptr);
    if (*endptr != '\0' || gain1 < 0.0f || gain1 > 100.0f) {
        fprintf(stderr, "Error: Invalid gain1 value '%s'\n", argv[1]);
        return EXIT_FAILURE;
    }

    float gain2 = strtof(argv[2], &endptr);
    if (*endptr != '\0' || gain2 < 0.0f || gain2 > 100.0f) {
        fprintf(stderr, "Error: Invalid gain2 value '%s'\n", argv[2]);
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure SPI */
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sampling audio at %d Hz...\n", SAMPLE_RATE_HZ);
    printf("Gain 1: %.2f%%, Gain 2: %.2f%%\n", gain1, gain2);
    printf("Press Ctrl+C to stop.\n");

    int error_count = 0;
    const int max_errors = 10;

    while (running) {
        int adc1 = read_mcp3008(ADC_CHANNEL_MIC1);
        int adc2 = read_mcp3008(ADC_CHANNEL_MIC2);

        if (adc1 < 0 || adc2 < 0) {
            error_count++;
            if (error_count >= max_errors) {
                fprintf(stderr, "Error: Max ADC read failures reached, aborting.\n");
                break;
            }
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }
        error_count = 0;

        /* Apply noise-cancellation: subtract scaled second channel */
        int diff = (int)(adc2 * gain2 / 100.0f);
        int cancelled = adc1 - diff;

        printf("%d\n", cancelled);
        fflush(stdout);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Clean resource release */
    spiClose(spi_handle);
    gpioTerminate();

    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

