/*
 * Raspberry Pi 4 Model B – Vegetronix VH400 soil moisture logger
 *
 * Hardware:
 *   - MCP3008 10-bit ADC on SPI0 (CE0 = GPIO 8, SCLK = GPIO 11,
 *     MOSI = GPIO 10, MISO = GPIO 9), VDD = 3.3 V, VREF = 3.3 V
 *   - Vegetronix VH400 analog output wired to MCP3008 CH0
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o moisture_logger moisture_logger.c \
 *       -lrt -lpigpio -lrt
 *
 * Run:
 *   sudo ./moisture_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO 8)            */
#define SPI_BAUD       1000000    /* 1 MHz – well within MCP3008 spec */
#define SPI_FLAGS      0          /* Mode 0, active-low CE, 8-bit    */
#define ADC_CHANNEL    0          /* MCP3008 CH0                  */
#define ADC_MAX_VALUE  1023       /* 10-bit ADC                    */
#define LOG_FILE       "moisture_log.txt"
#define SAMPLE_PERIOD  60         /* seconds between samples       */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 single-ended read                                           */
/* ------------------------------------------------------------------ */
/*
 * MCP3008 SPI protocol (3-byte transfer, Mode 0):
 *   Byte 0: 0x01                       (start bit)
 *   Byte 1: (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   Byte 2: 0x00                       (clock out remaining bits)
 *
 * Response:
 *   rx[0] = don't care
 *   rx[1] = [null bit][b9 b8] in the low nibble
 *   rx[2] = b7..b0
 */
static int read_mcp3008(int handle, int channel, uint16_t *adc_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    uint16_t value = ((uint16_t)(rx[1] & 0x03) << 8) | (uint16_t)(rx[2] & 0xFF);

    if (value > ADC_MAX_VALUE) {
        fprintf(stderr, "ADC value %u out of range\n", value);
        return -1;
    }

    *adc_value = value;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static int get_iso8601_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        return -1;
    }

    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(const char *timestamp, uint16_t adc_value)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    if (fprintf(fp, "%s,%u\n", timestamp, adc_value) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI open --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("VH400 soil moisture logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    /* --- Main loop --- */
    while (g_running) {
        uint16_t adc_value = 0;

        if (read_mcp3008(g_spi_handle, ADC_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "ADC read failed; continuing.\n");
        } else {
            char timestamp[32];
            if (get_iso8601_timestamp(timestamp, sizeof(timestamp)) == 0) {
                if (log_data(timestamp, adc_value) != 0) {
                    fprintf(stderr, "Logging failed.\n");
                } else {
                    printf("%s  ADC: %u\n", timestamp, adc_value);
                }
            } else {
                fprintf(stderr, "Timestamp generation failed.\n");
            }
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

