     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: bits 9..0 in ((rx[1] & 0x03) << 8) | rx[2]
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

/* ------------------------------------------------------------------ */
/* Convert 10-bit ADC value to water-level percentage                  */
/* ------------------------------------------------------------------ */
static float adc_to_percentage(int adc_value)
{
    return ((float)adc_value / 1023.0f) * 100.0f;
}

/* ------------------------------------------------------------------ */
/* Append one JSON entry and flush; write closing ']' on close.        */
/* ------------------------------------------------------------------ */
static void log_json(float percentage)
{
    if (g_json_file == NULL)
        return;

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);

    fprintf(g_json_file,
            "  {\"timestamp\": \"%s.%03ld\", \"water_level\": %.2f}\n",
            timestamp, ts.tv_nsec / 1000000L, percentage);
    fflush(g_json_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                        */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_json_file != NULL) {
        fflush(g_json_file);
        fclose(g_json_file);
        g_json_file = NULL;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- LED pin ---- */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin %d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    /* ---- SPI open ---- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- JSON file (open once, append mode) ---- */
    g_json_file = fopen(JSON_FILE, "a");
    if (g_json_file == NULL) {
        perror("fopen(" JSON_FILE ")");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write array start */
    if (fprintf(g_json_file, "[\n") < 0) {
        perror("fprintf array start");
        cleanup();
        return EXIT_FAILURE;
    }
    fflush(g_json_file);

    /* ---- Signals ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        int adc_value = read_mcp3008(g_spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "SPI read error — skipping sample\n");
        } else {
            float percentage = adc_to_percentage(adc_value);
            printf("Water level: %.2f%%\n", percentage);
            log_json(percentage);

            if (percentage > WATER_HIGH) {
                gpioWrite(LED_PIN, 1);
            } else if (percentage < WATER_LOW) {
                gpioWrite(LED_PIN, 0);
            }
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++) {
            time_sleep(SAMPLE_STEP);
        }
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    fflush(g_json_file);
    fprintf(g_json_file, "]\n");
    fclose(g_json_file);
    g_json_file = NULL;

    gpioWrite(LED_PIN, 0);
    spiClose(g_spi_handle);
    g_spi_handle = -1;
    gpioTerminate();

    printf("Water level monitoring stopped.\n");
    return EXIT_SUCCESS;
}

