#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define DEFAULT_SPI_CHANNEL 0
#define DEFAULT_ADC_CHANNEL 0
#define DEFAULT_MIN_VALUE 300
#define DEFAULT_MAX_VALUE 700
#define DEFAULT_THRESHOLD 30.0
#define DEFAULT_INTERVAL 60
#define DEFAULT_CONFIG_FILE "~/.msmtprc"
#define DEFAULT_RECIPIENT "recipient@example.com"
#define DEFAULT_LOG_FILE "plant_data.txt"
#define MIN_VALUE 0
#define MAX_VALUE 1000
#define MOISTURE_READ_ERROR -1

static int spi_channel = DEFAULT_SPI_CHANNEL;
static int adc_channel = DEFAULT_ADC_CHANNEL;
static int min_value = DEFAULT_MIN_VALUE;
static int max_value = DEFAULT_MAX_VALUE;
static float threshold = DEFAULT_THRESHOLD;
static int interval = DEFAULT_INTERVAL;
static char *recipient = DEFAULT_RECIPIENT;
static char *config_file = DEFAULT_CONFIG_FILE;
static char *log_file = DEFAULT_LOG_FILE;
static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return MOISTURE_READ_ERROR;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return MOISTURE_READ_ERROR;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float calculate_moisture(int adc_value) {
    if (adc_value < MIN_VALUE) adc_value = MIN_VALUE;
    if (adc_value > MAX_VALUE) adc_value = MAX_VALUE;
    return ((float)(adc_value - min_value) / (float)(max_value - min_value)) * 100.0;
}

static int log_data(float moisture) {
    FILE *fp = fopen(log_file, "a");
    if (!fp) {
        fprintf(stderr, "Error: Cannot open log file '%s': %s\n", log_file, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "Error: localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%s, %.2f\n", timestamp, moisture);
    fclose(fp);
    return 0;
}

static int send_email_alert(float moisture) {
    char body[512];
    snprintf(body, sizeof(body),
             "Subject: Plant Moisture Alert\n\n"
             "Plant moisture level is below threshold.\n"
             "Current moisture: %.2f%%\n",
             moisture);

    FILE *fp = fopen(config_file, "r");
    if (!fp) {
        fprintf(stderr, "Error: Cannot open msmtprc file '%s': %s\n", config_file, strerror(errno));
        return -1;
    }

    char host[256] = { 0 };
    char from[256] = { 0 };
    char user[256] = { 0 };
    char pass[256] = { 0 };
    char account[256] = { 0 };

    char line[512];
    while (fgets(line, sizeof(line), fp)) {
        if (strncmp(line, "account ", 9) == 0) {
            strncpy(account, line + 9, sizeof(account) - 1);
            account[sizeof(account) - 1] = '\0';
        } else if (strncmp(line, "host ", 5) == 0) {
            strncpy(host, line + 5, sizeof(host) - 1);
            host[sizeof(host) - 1] = '\0';
        } else if (strncmp(line, "from ", 4) == 0) {
            strncpy(from, line + 4, sizeof(from) - 1);
            from[sizeof(from) - 1] = '\0';
        } else if (strncmp(line, "user ", 5) == 0) {
            strncpy(user, line + 5, sizeof(user) - 1);
            user[sizeof(user) - 1] = '\0';
        } else if (strncmp(line, "pass ", 5) == 0) {
            strncpy(pass, line + 5, sizeof(pass) - 1);
            pass[sizeof(pass) - 1] = '\0';
        }
    }
    fclose(fp);

    if (account[0] == '\0') {
        fprintf(stderr, "Error: msmtprc account not configured\n");
        return -1;
    }

    char command[1024];
    snprintf(command, sizeof(command),
             "echo '%s' | msmtp -a %s -f %s %s",
             body, host, from, recipient);

    FILE *pipe = popen(command, "r");
    if (!pipe) {
        fprintf(stderr, "Error: Failed to execute msmtp: %s\n", strerror(errno));
        return -1;
    }

    int status = pclose(pipe);
    if (status == -1) {
        fprintf(stderr, "Error: pclose failed: %s\n", strerror(errno));
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: msmtp exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }
    if (WIFSIGNALED(status)) {
        fprintf(stderr, "Error: msmtp killed by signal %d\n", WTERMSIG(status));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "c:a:m:M:t:i:e:d:l:h")) != -1) {
        switch (opt) {
            case 'c': spi_channel = atoi(optarg); break;
            case 'a': adc_channel = atoi(optarg); break;
            case 'm': min_value = atoi(optarg); break;
            case 'M': max_value = atoi(optarg); break;
            case 't': threshold = atof(optarg); break;
            case 'i': interval = atoi(optarg); break;
            case 'e': recipient = optarg; break;
            case 'd': config_file = optarg; break;
            case 'l': log_file = optarg; break;
            case 'h':
            default:
                fprintf(stderr, "Usage: %s [-c spi_channel] [-a adc_channel] [-m min] [-M max] [-t threshold] [-i interval] [-e recipient] [-d config] [-l log]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (threshold < 0.0 || threshold > 100.0) {
        fprintf(stderr, "Error: Threshold must be between 0.0 and 100.0\n");
        return EXIT_FAILURE;
    }

    if (interval <= 0) {
        fprintf(stderr, "Error: Logging interval must be positive\n");
        return EXIT_FAILURE;
    }

    if (min_value < MIN_VALUE || max_value < MIN_VALUE || max_value > MAX_VALUE) {
        fprintf(stderr, "Error: Calibration values must be between %d and %d\n", MIN_VALUE, MAX_VALUE);
        return EXIT_FAILURE;
    }

    if (threshold < 0.0 || threshold > 100.0) {
        fprintf(stderr, "Error: Threshold must be between 0.0 and 100.0\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(spi_channel, 500000, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Plant monitoring started. Logging to '%s' every %d seconds.\n", log_file, interval);
    printf("Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(adc_channel);
        if (adc_value == MOISTURE_READ_ERROR) {
            fprintf(stderr, "Error: Failed to read ADC value. Retrying in %d seconds.\n", interval);
        } else {
            float moisture = calculate_moisture(adc_value);
            printf("Moisture: %.2f%%\n", moisture);

            if (log_data(moisture) != 0) {
                fprintf(stderr, "Error: Failed to log data.\n");
            }

            if (moisture < threshold) {
                printf("Alert: Moisture below threshold (%.2f%% < %.2f%%). Sending email.\n", moisture, threshold);
                if (send_email_alert(moisture) != 0) {
                    fprintf(stderr, "Error: Failed to send email alert.\n");
                }
            }
        }

        for (int i = 0; i < interval && !terminate; i++) {
            sleep(1);
        }
    }

    printf("\nPlant monitoring stopped.\n");
    cleanup();
    return EXIT_SUCCESS;
}

