/*
 * Soil Moisture Monitor — Raspberry Pi 3 Model B+
 * Sensor : Keyes KY-036 analog soil-moisture sensor (analog output -> MCP3008 CH0)
 * ADC    : MCP3008 10-bit SPI ADC on SPI0 CE0 (GPIO8), 1 MHz, mode 0
 * Log    : soil_moisture.log (timestamp, raw_adc, moisture_pct)
 *
 * Build : gcc -O2 -Wall -Wextra -o soil_moisture soil_moisture.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8
#define ADC_CHANNEL     0
#define ADC_MAX         1023
#define LOG_FILE        "soil_moisture.log"
#define DEFAULT_INTERVAL 1
#define ADC_SETTLE_US   10000   /* 10 ms settle after power-on / reset */

static volatile sig_atomic_t g_running = 1;
static int      g_spi_fd   = -1;
static FILE    *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 single-ended read (datasheet section 6.1)                   */
/* ------------------------------------------------------------------ */
static int mcp3008_read(int fd, uint8_t channel, uint16_t *out)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid channel %u (must be 0-7)\n", channel);
        return -1;
    }
    if (out == NULL) {
        return -1;
    }

    /*
     * MCP3008 SPI frame (3 bytes):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: rx[1] low 2 bits + rx[2] 8 bits = 10-bit value
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE failed");
        return -1;
    }

    *out = (uint16_t)(((rx[1] & 0x03) << 8) | rx[2]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Moisture calculation                                               */
/* ------------------------------------------------------------------ */
static float calculate_moisture_pct(uint16_t adc_value)
{
    /*
     * KY-036 analog output: higher voltage = drier soil.
     * Map 0..1023 to 0%..100% so that higher ADC = higher moisture.
     */
    return ((float)adc_value / (float)ADC_MAX) * 100.0f;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, uint16_t adc_value, float moisture_pct)
{
    time_t     rawtime;
    struct tm  tm_info;
    char       timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &tm_info) == NULL) {
        perror("localtime_r failed");
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%u,%.2f\n", timestamp, adc_value, moisture_pct) < 0) {
        perror("fprintf to log failed");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush failed");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int  interval = DEFAULT_INTERVAL;
    int  ret      = EXIT_SUCCESS;

    if (argc > 1) {
        interval = atoi(argv[1]);
        if (interval <= 0) {
            fprintf(stderr, "Invalid interval '%s'; using default %d s\n",
                    argv[1], DEFAULT_INTERVAL);
            interval = DEFAULT_INTERVAL;
        }
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }

    /* --- Open SPI device --- */
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        fclose(g_log_file);
        g_log_file = NULL;
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("SPI_IOC_WR_MODE");
        ret = EXIT_FAILURE;
        goto done;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        ret = EXIT_FAILURE;
        goto done;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        ret = EXIT_FAILURE;
        goto done;
    }

    /* --- ADC settle --- */
    usleep(ADC_SETTLE_US);

    printf("Soil Moisture Monitoring Started.\n");
    printf("  SPI device : %s @ %u Hz, mode %u, %u bits\n",
           SPI_DEVICE, speed, mode, bits);
    printf("  ADC channel: %u\n", ADC_CHANNEL);
    printf("  Log file   : %s\n", LOG_FILE);
    printf("  Interval   : %d s\n", interval);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        uint16_t adc_value = 0;

        if (mcp3008_read(g_spi_fd, ADC_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "Warning: ADC read failed; will retry next cycle.\n");
            sleep(interval);
            continue;
        }

        float moisture_pct = calculate_moisture_pct(adc_value);

        if (log_data(g_log_file, adc_value, moisture_pct) != 0) {
            fprintf(stderr, "Warning: log write failed.\n");
        }

        printf("ADC: %4u  Moisture: %6.2f%%\n", adc_value, moisture_pct);

        /*
         * Sleep in 1 s increments so signals are caught promptly.
         * sleep() is interrupted by signals; if interrupted it returns
         * early, which is fine for our loop structure.
         */
        for (int i = 0; i < interval && g_running; i++) {
            sleep(1);
        }
    }

done:
    printf("\nShutting down...\n");
    cleanup();
    return ret;
}

