/*
 * Raspberry Pi 4 Model B - MLX90823 Pressure Sensor Reader via MCP3008 ADC
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3V (Pin 1)
 *   MCP3008 VREF -> 3.3V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SCLK)
 *   MCP3008 DOUT -> GPIO9  (MISO)
 *   MCP3008 DIN  -> GPIO10 (MOSI)
 *   MCP3008 CS   -> GPIO8  (CE0)
 *   MCP3008 CH0  -> MLX90823 analog output (0-3.3V)
 *
 * Build: gcc -O2 -Wall -o mlx90823_reader mlx90823_reader.c -lpigpio -lrt
 * Run:   sudo ./mlx90823_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* CE0 (GPIO8) */
#define SPI_BAUD       1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 CH0 */
#define ADC_MAX_VALUE  1023       /* 10-bit ADC */
#define VREF           3.3f       /* MCP3008 reference voltage */
#define SAMPLE_PERIOD_S 1         /* Seconds between samples */
#define MAX_CONSEC_ERR 10         /* Abort after this many consecutive errors */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* ISO-8601 timestamp helper                                           */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tmv;
    if (localtime_r(&now, &tmv) != NULL) {
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tmv);
    } else {
        snprintf(buf, len, "UNKNOWN");
    }
}

/* ------------------------------------------------------------------ */
/* Read one sample from MCP3008 (single-ended)                          */
/* Returns 0-1023 on success, -1 on SPI error, -2 on out-of-range.      */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "[ERROR] Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (Mode 0, MSB-first):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: 0x80 | (channel << 4)  (single-ended + channel select)
     *   Byte 2: 0x00  (don't care, clocked out to read low byte)
     *
     * Response:
     *   Byte 0: undefined
     *   Byte 1: bits 7..2 undefined, bit 1 = null bit, bit 0 = B9
     *   Byte 2: B8..B1
     */
    char tx[3] = { 0x01,
                   (char)(0x80 | ((channel & 0x07) << 4)),
                   0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(g_spi_handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "[ERROR] spiXfer returned %d (expected 3)\n", bytes);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];

    if (adc_value < 0 || adc_value > ADC_MAX_VALUE) {
        fprintf(stderr, "[ERROR] ADC value %d out of range\n", adc_value);
        return -2;
    }

    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Convert ADC value to pressure (Pa) using a simple linear model.      */
/* NOTE: The MLX90823 is a calibrated analog pressure sensor; the      */
/* conversion below is a placeholder. Replace with the calibration    */
/* constants from your sensor datasheet for production use.            */
/* ------------------------------------------------------------------ */
static float adc_to_pressure(int adc_value)
{
    /*
     * Placeholder linear mapping:
     *   0   -> 0 Pa
     *   1023-> 100000 Pa
     * Adjust slope/intercept for your specific sensor.
     */
    return (float)adc_value * 100000.0f / (float)ADC_MAX_VALUE;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz, mode 0 --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "[FATAL] spiOpen failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] Failed to install signal handlers\n");
    }

    printf("[INFO] MLX90823 pressure reader started (MCP3008 CH0, SPI0 CE0)\n");
    printf("[INFO] Sampling every %d s. Press Ctrl+C to exit.\n", SAMPLE_PERIOD_S);

    int consecutive_errors = 0;

    while (g_running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);

        if (adc_value < 0) {
            consecutive_errors++;
            char ts[32];
            get_timestamp(ts, sizeof(ts));
            fprintf(stderr, "[%s] [ERROR] SPI/ADC read failed (consecutive=%d)\n",
                    ts, consecutive_errors);

            if (consecutive_errors >= MAX_CONSEC_ERR) {
                fprintf(stderr, "[FATAL] %d consecutive errors - aborting.\n",
                        consecutive_errors);
                break;
            }
        } else {
            consecutive_errors = 0;

            /* Sensor-absent / fault detection:
             *   - ADC stuck at 0 V or 3.3 V usually means the sensor
             *     output is disconnected or shorted.
             */
            if (adc_value == 0 || adc_value == ADC_MAX_VALUE) {
                char ts[32];
                get_timestamp(ts, sizeof(ts));
                fprintf(stderr, "[%s] [WARN] Sensor fault - ADC at rail (%d)\n",
                        ts, adc_value);
            }

            float pressure = adc_to_pressure(adc_value);
            char ts[32];
            get_timestamp(ts, sizeof(ts));
            printf("[%s] ADC=%4d  Pressure=%.2f Pa\n", ts, adc_value, pressure);
        }

        /* Sleep in 100 ms increments so signals are caught promptly. */
        for (int i = 0; i < SAMPLE_PERIOD_S * 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    /* --- Cleanup --- */
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();

    printf("\n[INFO] Shutdown complete.\n");
    return EXIT_SUCCESS;
}

