#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz – well within MCP3008 spec */
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8
#define SAMPLE_INTERVAL 5          /* seconds between readings */
#define ADC_CHANNEL     0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX         1023       /* 10-bit ADC */
#define ADC_MIN         0

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/*
 * MCP3008 single-ended read (3-byte transfer, SPI Mode 0, MSB-first).
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
 *   tx[2] = 0x00                       (clock out remaining bits)
 *   rx[1] bits 1..0  + rx[2] bits 7..0  -> 10-bit result
 */
static int mcp3008_read(int fd, uint8_t channel, uint16_t *out)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid channel %u (must be 0–7)\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    *out = (uint16_t)(((rx[1] & 0x03) << 8) | rx[2]);
    return 0;
}

/* ------------------------------------------------------------------ */
static void print_timestamp(void)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time()");
        return;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        perror("localtime_r()");
        return;
    }
    char buf[32];
    if (strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }
    printf("[%s] ", buf);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        goto cleanup;

    /* Open the SPI device */
    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        goto cleanup;
    }

    /* Configure SPI mode */
    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Configure bits per word */
    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Configure max speed */
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Soil Moisture Sensor Data Acquisition\n");
    printf("SPI device : %s\n", SPI_DEVICE);
    printf("ADC channel: %u\n", ADC_CHANNEL);
    printf("Sample rate: every %d s\n", SAMPLE_INTERVAL);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        uint16_t adc_value = 0;

        if (mcp3008_read(fd, ADC_CHANNEL, &adc_value) != 0) {
            print_timestamp();
            fprintf(stderr, "ADC read failed; continuing.\n");
        } else {
            print_timestamp();

            /* Sensor-absent / wiring-fault heuristic: rail values */
            if (adc_value == ADC_MAX || adc_value == ADC_MIN) {
                fprintf(stderr, "Warning: ADC at rail (%u) – sensor absent or wiring fault\n",
                        adc_value);
            }

            printf("ADC Value: %u\n", adc_value);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++)
            sleep(1);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);

    if (rc == EXIT_SUCCESS)
        printf("\nExiting cleanly.\n");
    return rc;
}

