        printf("ADC Value: %4d  Moisture: %3d%%\n", adc_value, moisture_pct);

        sleep(SAMPLE_INTERVAL);
    }

    /* Clean shutdown */
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
