#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* MCP3008 on CE0 (bus 0, channel 0)      */
#define SPI_SPEED        1000000    /* 1 MHz                                  */
#define SPI_FLAGS        0          /* Mode 0, active-low CE                   */
#define PUMP_GPIO        17         /* BCM 17 – relay driving a 12 V pump     */
#define MOISTURE_LOW     300        /* Turn pump ON  below this value          */
#define MOISTURE_HIGH    600        /* Turn pump OFF above this value          */
#define SAMPLE_PERIOD_S  5          /* Seconds between samples                 */
#define BUFFER_SIZE      20         /* Circular-buffer capacity               */
#define ADC_MAX          1023       /* MCP3008 10-bit full-scale code          */

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_spi_handle = -1;
static int      g_pump_state = 0;   /* 0 = OFF, 1 = ON                        */
static time_t   g_last_sample = 0;
static char     g_log_buffer[BUFFER_SIZE][128];
static int      g_buf_idx = 0;

/* ----------------------------- Prototypes -------------------------------- */
static int  read_mcp3008(int channel);
static void control_pump(int moisture);
static void log_data(int moisture, int pump_state);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- MCP3008 read ------------------------------ */
/*
 * MCP3008 single-ended read (3-byte transfer, SPI mode 0):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care)
 *   tx[2] = 0x00                       (clock out low 2 bits)
 * Result: 10-bit value = ((rx[1] & 0x03) << 8) | rx[2]
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0, 0, 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

/* ----------------------------- Pump control ------------------------------ */
static void control_pump(int moisture)
{
    if (moisture < MOISTURE_LOW && g_pump_state == 0) {
        if (gpioWrite(PUMP_GPIO, 1) == 0) {
            g_pump_state = 1;
            printf("Pump ON  (moisture=%d)\n", moisture);
        } else {
            fprintf(stderr, "gpioWrite(ON) failed on GPIO %d\n", PUMP_GPIO);
        }
    } else if (moisture > MOISTURE_HIGH && g_pump_state == 1) {
        if (gpioWrite(PUMP_GPIO, 0) == 0) {
            g_pump_state = 0;
            printf("Pump OFF (moisture=%d)\n", moisture);
        } else {
            fprintf(stderr, "gpioWrite(OFF) failed on GPIO %d\n", PUMP_GPIO);
        }
    }
}

/* ----------------------------- Logging ----------------------------------- */
static void log_data(int moisture, int pump_state)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    snprintf(g_log_buffer[g_buf_idx], sizeof(g_log_buffer[g_buf_idx]),
             "%s  Moisture=%d  Pump=%s", ts, moisture,
             g_pump_state ? "ON" : "OFF");
    g_buf_idx = (g_buf_idx + 1) % BUFFER_SIZE;
}

static void print_log_buffer(void)
{
    printf("\n--- Log Buffer ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (g_buf_idx + i) % BUFFER_SIZE;
        if (g_log_buffer[idx][0] != '\0')
            printf("%s\n", g_log_buffer[idx]);
    }
    printf("--- End of Log Buffer ---\n\n");
}

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_pump_state) {
        gpioWrite(PUMP_GPIO, 0);
        g_pump_state = 0;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI open --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Pump GPIO as output, ensure OFF --- */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed on GPIO %d\n", PUMP_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(PUMP_GPIO, 0) != 0) {
        fprintf(stderr, "gpioWrite(0) failed on GPIO %d\n", PUMP_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    g_pump_state = 0;

    /* --- Signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Soil moisture monitor started.  Sampling every %d s.\n",
           SAMPLE_PERIOD_S);
    printf("  SPI channel %d  speed %d Hz  mode 0\n", SPI_CHANNEL, SPI_SPEED);
    printf("  Pump relay on GPIO %d  (active-high)\n", PUMP_GPIO);
    printf("  Low threshold = %d  High threshold = %d\n", MOISTURE_LOW, MOISTURE_HIGH);
    printf("Press Ctrl-C to exit.\n\n");

    /* --- Timer callback (runs in pigpio thread) --- */
    if (gpioSetTimerFunc(0, SAMPLE_PERIOD_S, read_moisture_sensor) != 0) {
        fprintf(stderr, "gpioSetTimerFunc failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Main loop --- */
    while (g_running)
        sleep(1);

    printf("\nShutting down...\n");
    print_log_buffer();
    cleanup();
    return EXIT_SUCCESS;

    /* ----------------------------- Timer callback ------------------------- */
    void read_moisture_sensor(void *userdata)
    {
    (void)userdata;

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return;
    }

    if (difftime(now, g_last_sample) < 1.0)
        return;                       /* debounce: within 1 s of last sample */
    g_last_sample = now;

    int moisture = read_mcp3008(0);
    if (moisture < 0) {
        fprintf(stderr, "SPI read error – skipping sample\n");
        return;
    }

    control_pump(moisture);
    log_data(moisture, g_pump_state);
    print_log_buffer();
    }
}

