#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MAX30102_ADDR 0x57

#define REG_INTR_STATUS_1 0x00
#define REG_INTR_STATUS_2 0x01
#define REG_INTR_ENABLE_1 0x02
#define REG_INTR_ENABLE_2 0x03
#define REG_FIFO_WR_PTR 0x04
#define REG_OVF_COUNTER 0x05
#define REG_FIFO_RD_PTR 0x06
#define REG_FIFO_DATA 0x07
#define REG_FIFO_CONFIG 0x08
#define REG_MODE_CONFIG 0x09
#define REG_SPO2_CONFIG 0x0A
#define REG_LED1_PA 0x0C
#define REG_LED2_PA 0x0D
#define REG_PART_ID 0xFF

#define PART_ID_EXPECTED 0x15

#define SAMPLE_INTERVAL_US 1000000
#define SAMPLE_SIZE 6

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen("health_log.txt", "a");
    if (!fp) {
        perror("Error opening health_log.txt");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s: %s\n", ts, message);
    } else {
        fprintf(fp, "[timestamp error]: %s\n", message);
    }
    fclose(fp);
}

static int i2c_read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int i2c_write_register(int handle, uint8_t reg, uint8_t value) {
    return i2cWriteByteData(handle, reg, value);
}

static int init_max30102(int handle) {
    uint8_t part_id = 0;
    if (i2c_read_register(handle, REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Error: Failed to read Part ID register.\n");
        log_event("Error: Failed to read Part ID register.");
        return -1;
    }
    if (part_id != PART_ID_EXPECTED) {
        fprintf(stderr, "Error: Unexpected Part ID 0x%02X (expected 0x%02X). Sensor not present?\n", part_id, PART_ID_EXPECTED);
        log_event("Error: Unexpected Part ID. Sensor not present.");
        return -1;
    }

    if (i2c_write_register(handle, REG_MODE_CONFIG, 0x40) != 0) {
        fprintf(stderr, "Error: Failed to write MODE_CONFIG register.\n");
        log_event("Error: Failed to write MODE_CONFIG register.");
        return -1;
    }
    gpioDelay(10000);

    if (i2c_write_register(handle, REG_INTR_ENABLE_1, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to write INTR_ENABLE_1 register.\n");
        log_event("Error: Failed to write INTR_ENABLE_1 register.");
        return -1;
    }
    if (i2c_write_register(handle, REG_INTR_ENABLE_2, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to write INTR_ENABLE_2 register.\n");
        log_event("Error: Failed to write INTR_ENABLE_2 register.");
        return -1;
    }
    if (i2c_write_register(handle, REG_FIFO_WR_PTR, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to write FIFO_WR_PTR register.\n");
        log_event("Error: Failed to write FIFO_WR_PTR register.");
        return -1;
    }
    if (i2c_write_register(handle, REG_OVF_COUNTER, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to write OVF_COUNTER register.\n");
        log_event("Error: Failed to write OVF_COUNTER register.");
        return -1;
    }
    if (i2c_write_register(handle, REG_FIFO_RD_PTR, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to write FIFO_RD_PTR register.\n");
        log_event("Error: Failed to write FIFO_RD_PTR register.");
        return -1;
    }
    if (i2c_write_register(handle, REG_FIFO_CONFIG, 0x4F) != 0) {
        fprintf(stderr, "Error: Failed to write FIFO_CONFIG register.\n");
        log_event("Error: Failed to write FIFO_CONFIG register.");
        return -1;
    }
    if (i2c_write_register(handle, REG_MODE_CONFIG, 0x03) != 0) {
        fprintf(stderr, "Error: Failed to write MODE_CONFIG register.\n");
        log_event("Error: Failed to write MODE_CONFIG register.");
        return -1;
    }
    gpioDelay(10000);

    if (i2c_write_register(handle, REG_SPO2_CONFIG, 0x27) != 0) {
        fprintf(stderr, "Error: Failed to write SPO2_CONFIG register.\n");
        log_event("Error: Failed to write SPO2_CONFIG register.");
        return -1;
    }
    if (i2c_write_register(handle, REG_LED1_PA, 0x24) != 0) {
        fprintf(stderr, "Error: Failed to write LED1_PA register.\n");
        log_event("Error: Failed to write LED1_PA register.");
        return -1;
    }
    if (i2c_write_register(handle, REG_LED2_PA, 0x24) != 0) {
        fprintf(stderr, "Error: Failed to write LED2_PA register.\n");
        log_event("Error: Failed to write LED2_PA register.");
        return -1;
    }

    return 0;
}

static int read_max30102_data(int handle, uint32_t *spo2, uint32_t *heart_rate) {
    uint8_t data[SAMPLE_SIZE];
    int result = i2cReadI2CBlockData(handle, REG_FIFO_DATA, (char *)data, SAMPLE_SIZE);
    if (result != SAMPLE_SIZE) {
        fprintf(stderr, "Error: Failed to read FIFO data (read %d bytes).\n", result);
        log_event("Error: Failed to read FIFO data.");
        return -1;
    }

    uint32_t red = ((uint32_t)data[0] << 16) | ((uint32_t)data[1] << 8) | data[2];
    uint32_t ir = ((uint32_t)data[3] << 16) | ((uint32_t)data[4] << 8) | data[5];

    *spo2 = (red * 100) / 1023;
    *heart_rate = (ir * 60) / 1023;

    return 0;
}

static void process_data(uint32_t spo2, uint32_t heart_rate) {
    if (spo2 < 95) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Low SpO2: %u%%", spo2);
        log_event(msg);
    }
    if (heart_rate > 100) {
        char msg[128];
        snprintf(msg, sizeof(msg), "High Heart Rate: %u BPM", heart_rate);
        log_event(msg);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: sigaction failed");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MAX30102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at bus %d, addr 0x%02X.\n", I2C_BUS, MAX30102_ADDR);
        log_event("Error: Failed to open I2C device.");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_max30102(i2c_handle) != 0) {
        fprintf(stderr, "Error: MAX30102 initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MAX30102 initialized. Monitoring... (Ctrl+C to exit)\n");

    while (running) {
        uint32_t spo2 = 0, heart_rate = 0;
        if (read_max30102_data(i2c_handle, &spo2, &heart_rate) == 0) {
            printf("SpO2: %u%%, Heart Rate: %u BPM\n", spo2, heart_rate);
            process_data(spo2, heart_rate);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

