#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48
#define ADS1115_REG_CONV  0x00
#define ADS1115_REG_CFG   0x01
#define ADS1115_CFG_BASE  0xC183  /* AIN0 single-ended, PGA 4.096V, single-shot, 128 SPS */
#define ADS1115_MUX_BASE  0x4000  /* AIN0 vs GND */
#define ADS1115_OS_BEGIN  0x8000  /* assert OS bit to start conversion */
#define ADS1115_OS_READY  0x8000  /* bit 15 reads 1 when conversion done */

#define RELAY_GPIO      17
#define REED_GPIO       27
#define LOG_FILE        "/var/log/door_events.log"
#define SAMPLE_DELAY_MS 50
#define LOOP_DELAY_MS   200
#define RELAY_PULSE_MS  3000
#define CALIB_SAMPLES   10
#define THRESHOLD_MIN   50
#define THRESHOLD_MAX   100

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static int g_relay_fd = -1;
static int g_reed_fd = -1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void msleep(unsigned ms) {
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s.%03ld: %s\n", tbuf, ts.tv_nsec / 1000000L, msg);
    fclose(fp);
}

static int i2c_write16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, 3) != 3) {
        perror("i2c_write16 write");
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out) {
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read16 write");
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        perror("i2c_read16 read");
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int ads1115_read(int fd, int16_t *raw) {
    uint16_t cfg = ADS1115_OS_BEGIN | ADS1115_MUX_BASE | ADS1115_CFG_BASE;
    if (i2c_write16(fd, ADS1115_REG_CFG, cfg) < 0) return -1;

    for (int i = 0; i < 100; i++) {
        uint16_t conv;
        if (i2c_read16(fd, ADS1115_REG_CONV, &conv) < 0) return -1;
        if (conv & ADS1115_OS_READY) break;
        msleep(10);
        if (i == 99) {
            log_event("ADS1115 conversion timeout");
            return -1;
        }
    }

    uint16_t raw_u = i2c_read16(fd, ADS1115_REG_CONV, NULL);
    if (raw_u < 0) return -1;
    *raw = (int16_t)raw_u;
    return 0;
}

static int ads1115_init(int fd) {
    uint16_t cfg = ADS1115_MUX_BASE | ADS1115_CFG_BASE;
    if (i2c_write16(fd, ADS1115_REG_CFG, cfg) < 0) return -1;
    return 0;
}

static int gpio_export(int gpio) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/export");
    int fd = open(path, O_WRONLY);
    if (fd < 0) { perror("open export"); return -1; }
    char buf[16];
    snprintf(buf, sizeof(buf), "%d", gpio);
    if (write(fd, buf, strlen(buf)) < 0) { perror("write export"); close(fd); return -1; }
    close(fd);
    return 0;
}

static int gpio_set_dir(int gpio, const char *dir) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", gpio);
    int fd = open(path, O_WRONLY);
    if (fd < 0) { perror("open direction"); return -1; }
    if (write(fd, dir, strlen(dir)) < 0) { perror("write direction"); close(fd); return -1; }
    close(fd);
    return 0;
}

static int gpio_set_value(int gpio, int val) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", gpio);
    int fd = open(path, O_WRONLY);
    if (fd < 0) { perror("open value"); return -1; }
    char buf[2] = { (char)val, '\n' };
    if (write(fd, buf, 2) < 0) { perror("write value"); close(fd); return -1; }
    close(fd);
    return 0;
}

static int gpio_get_value(int gpio) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", gpio);
    int fd = open(path, O_RDONLY);
    if (fd < 0) { perror("open read"); return -1; }
    char buf[2];
