#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8

#define CS0_PIN         8
#define CS1_PIN         7
#define CS2_PIN         25

#define NUM_SENSORS     3
#define READ_INTERVAL   5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        return -1;
    }
    return 0;
}

static int read_mcp3008(int fd, int cs_pin, int channel) {
    if (channel < 0 || channel > 7) {
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    if (gpioWrite(cs_pin, 0) < 0) {
        return -1;
    }

    int ret = spi_transfer(fd, tx, rx, 3);

    if (gpioWrite(cs_pin, 1) < 0) {
        return -1;
    }

    if (ret < 0) {
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int log_data(FILE *fp, int vals[NUM_SENSORS]) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, vals[0], vals[1], vals[2]) < 0) {
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    int spi_fd = -1;
    FILE *fp = NULL;
    int pins[NUM_SENSORS] = { CS0_PIN, CS1_PIN, CS2_PIN };
    int vals[NUM_SENSORS] = { -1, -1, -1 };

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output.\n", pins[i]);
            goto cleanup;
        }
        if (gpioWrite(pins[i], 1) < 0) {
            fprintf(stderr, "Error: failed to set GPIO %d high.\n", pins[i]);
            goto cleanup;
        }
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        goto cleanup;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        goto cleanup;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting SPI bits per word");
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI max speed");
        goto cleanup;
    }

    fp = fopen("soil_moisture_log.csv", "a");
    if (fp == NULL) {
        perror("Error opening CSV file");
        goto cleanup;
    }

    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        if (fprintf(fp, "timestamp,sensor1,sensor2,sensor3\n") < 0) {
            perror("Error writing CSV header");
            goto cleanup;
        }
        fflush(fp);
    }

    printf("Logging soil moisture data to soil_moisture_log.csv every %d seconds. Press Ctrl+C to exit.\n", READ_INTERVAL);

    while (g_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            vals[i] = read_mcp3008(spi_fd, pins[i], 0);
            if (vals[i] < 0) {
                fprintf(stderr, "Warning: failed to read sensor %d (GPIO %d).\n", i + 1, pins[i]);
            }
        }

        if (log_data(fp, vals) < 0) {
            fprintf(stderr, "Error writing to log file.\n");
        }

        sleep(READ_INTERVAL);
    }

cleanup:
    printf("\nShutting down...\n");
    if (fp != NULL) {
        fclose(fp);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    for (int i = 0; i < NUM_SENSORS; i++) {
        gpioWrite(pins[i], 1);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

