        if (result == 3) {
            int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
            return adc_value;
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %d\n",
                attempt + 1, MAX_SPI_RETRIES, result);
        if (attempt < MAX_SPI_RETRIES - 1) {
            gpioDelay(100000);
        }
    }
    return -1;
}

static void control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
