            fprintf(stderr, "Failed to read moisture level after %d retries\n", MAX_SPI_RETRIES);
            log_message("Error: SPI read failed");
            sleep(sleep_interval);
            continue;
        }

        int moisture_percent = (moisture_level * 100) / 1023;
