            control_pump(1);
            for (int i = 0; i < pump_duration && program_running; i++) {
                sleep(1);
            }
            control_pump(0);
            log_message("Pump deactivated");
        }

        for (int i = 0; i < sleep_interval && program_running; i++) {
            sleep(1);
        }
    }

    log_message("Program exiting");
    cleanup();
    return 0;
}

