#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define PCF8591_ADDR   0x48
#define SAMPLE_PERIOD  100000   /* microseconds (100 ms) */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte)
{
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t *value)
{
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    /* Install SIGINT handler for clean shutdown on Ctrl-C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the PCF8591 slave address */
    if (ioctl(fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus address 0x%02X: %s\n",
                PCF8591_ADDR, strerror(errno));
        goto cleanup;
    }

    /*
     * PCF8591 conversion order:
     *   - A previous conversion result is returned on the first read after
     *     power-up or after a write to control byte 0x00 (auto-increment off,
     *     single-ended, channel 0).
     *   - A new conversion is started when control byte 0x01 (auto-increment
     *     on) is written.
     *
     * We perform a dummy write of 0x00 to trigger a fresh conversion, then
     * read the current sample.
     */
    if (i2c_write_byte(fd, 0x00) < 0) {
        goto cleanup;
    }

    /* Small delay to let the first conversion complete */
    usleep(1000);

    while (g_running) {
        uint8_t sample = 0;

        if (i2c_read_byte(fd, &sample) < 0) {
            goto cleanup;
        }

        printf("AIN0: %u\n", (unsigned int)sample);
        fflush(stdout);

        usleep(SAMPLE_PERIOD);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return rc;
}

