/*
 * Raspberry Pi Zero W - Vegetronix VH400 Soil Moisture Monitor
 *
 * Hardware:
 *   - MCP3008 ADC on SPI0 CE0 (GPIO8), SPI mode 0, 1 MHz
 *   - Vegetronix VH400 analog output wired to MCP3008 channel 0
 *   - Relay-driven water pump on GPIO18 (BCM)
 *
 * Behavior:
 *   - Reads VH400 via MCP3008 channel 0 every 60 s
 *   - If moisture < 300, energizes pump for 10 s and logs the event
 *   - Graceful shutdown on SIGINT/SIGTERM: pump off, resources released
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE        "/dev/spidev0.0"
#define SPI_SPEED_HZ      1000000
#define SPI_MODE          0
#define SPI_BITS_PER_WORD 8

#define ADC_CHANNEL       0
#define ADC_MAX_VALUE     1023
#define MOISTURE_THRESHOLD 300
#define PUMP_GPIO         18
#define PUMP_DURATION_S   10
#define POLL_INTERVAL_S   60
#define LOG_FILE          "watering_events.txt"

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static int g_pump_state = 0;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SPI / MCP3008 helpers                                               */
/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    return 0;
}

/*
 * MCP3008 single-ended read.
 * Protocol (3-byte transfer, SPI mode 0, MSB-first):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   tx[2] = 0x00                       (clock out low bits)
 *   rx[1] bits 1:0 + rx[2] bits 7:0     (10-bit result)
 */
static int mcp3008_read(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs   = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | rx[2];
    if (value < 0 || value > ADC_MAX_VALUE) {
        fprintf(stderr, "ADC value out of range: %d\n", value);
        return -1;
    }
    return value;
}

/* ------------------------------------------------------------------ */
/* GPIO / pump helpers                                                */
/* ------------------------------------------------------------------ */
static int pump_init(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", PUMP_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(PUMP_GPIO, 0) < 0) {
        fprintf(stderr, "gpioWrite(%d, 0) failed\n", PUMP_GPIO);
        gpioTerminate();
        return -1;
    }

    g_pump_state = 0;
    return 0;
}

static int pump_set(int on)
{
    if (gpioWrite(PUMP_GPIO, on ? 1 : 0) < 0) {
        fprintf(stderr, "gpioWrite(%d, %d) failed\n", PUMP_GPIO, on);
        return -1;
    }
    g_pump_state = on;
    return 0;
}

static void pump_shutdown(void)
{
    if (g_pump_state) {
        (void)gpioWrite(PUMP_GPIO, 0);
        g_pump_state = 0;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(int moisture)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Moisture: %d, Pump: %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                moisture, g_pump_state ? "ON" : "OFF");
    } else {
        fprintf(fp, "[timestamp error] - Moisture: %d, Pump: %s\n",
                moisture, g_pump_state ? "ON" : "OFF");
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (spi_init() < 0) {
        return EXIT_FAILURE;
    }

    if (pump_init() < 0) {
        close(g_spi_fd); g_spi_fd = -1;
        return EXIT_FAILURE;
    }

    printf("Soil moisture monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int moisture = mcp3008_read(ADC_CHANNEL);
        if (moisture < 0) {
            fprintf(stderr, "ADC read failed; skipping cycle.\n");
        } else {
            printf("Moisture: %d\n", moisture);

            if (moisture < MOISTURE_THRESHOLD) {
                printf("Moisture below threshold (%d). Watering...\n",
                       MOISTURE_THRESHOLD);

                if (pump_set(1) < 0) {
                    fprintf(stderr, "Failed to activate pump.\n");
                } else {
                    log_event(moisture);

                    /*
                     * Sleep in 1-second increments so SIGINT/SIGTERM
                     * is noticed promptly and the pump is turned off
                     * even if sleep is interrupted.
                     */
                    for (int i = 0; i < PUMP_DURATION_S && g_running; i++) {
                        sleep(1);
                    }

                    if (pump_set(0) < 0) {
                        fprintf(stderr, "Failed to deactivate pump.\n");
                    }
                }
            }
        }

        /*
         * Sleep in 1-second increments so SIGINT/SIGTERM is noticed
         * promptly and the loop exits cleanly.
         */
        for (int i = 0; i < POLL_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    pump_shutdown();
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

