 * ADC channel 0 is read in single-ended mode; 10-bit result (0–1023).
 */

#define SPI_CHANNEL 0          /* CE0 on SPI bus 0 */
#define SPI_SPEED   1000000    /* 1 MHz */
#define SPI_FLAGS   0          /* mode 0, active-low CE, 8-bit words */
#define ADC_CHANNEL 0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX     1023       /* 10-bit ADC full-scale at 3.3 V */
#define SAMPLE_US   1000000    /* 1 second between samples */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler – set flag so main loop can exit cleanly             */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read one sample from the MCP3008 (single-ended, channel 0)          */
/* Returns 0–1023 on success, -1 on SPI transfer failure.               */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   Byte 0: 0x01                       (start bit)
     *   Byte 1: (0x08 | channel) << 4      (single-ended + channel, upper nibble)
     *   Byte 2: 0x00                       (clock out remaining bits)
     *
     * Response:
     *   rx[0] = don't care
     *   rx[1] = [null bit][b9 b8] in the low two bits
     *   rx[2] = b7..b0
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Map ADC value to rainfall intensity level                           */
/* ------------------------------------------------------------------ */
static const char *intensity_str(int adc_value)
{
    if (adc_value < 0)   return "ERROR";
    if (adc_value == 0)  return "NO RAIN";
    if (adc_value < 200) return "LIGHT DRIZZLE";
    if (adc_value < 500) return "MODERATE RAIN";
    return "HEAVY RAIN";
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio daemon/library --------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI device -------------------------------------------- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handling for graceful shutdown ---------------------- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("YL-83 Rain Sensor via MCP3008 – logging to stdout\n");
    printf("SPI bus %d, channel %d, %d Hz, single-ended ch %d\n",
           SPI_CHANNEL, ADC_CHANNEL, SPI_SPEED, ADC_CHANNEL);
    printf("Press Ctrl-C to stop.\n\n");

    /* --- Main sampling loop ----------------------------------------- */
    while (g_running) {
        int adc_value = read_mcp3008(g_spi_handle, ADC_CHANNEL);

        if (adc_value < 0) {
            fprintf(stderr, "SPI read error – skipping sample\n");
        } else {
            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];

            if (localtime_r(&now, &tm_info) != NULL) {
                strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
            } else {
                snprintf(ts, sizeof(ts), "----");
            }

            const char *intensity = intensity_str(adc_value);
            printf("[%s] ADC: %4d  |  %s\n", ts, adc_value, intensity);
            fflush(stdout);
        }

        /* Sleep 1 s; gpioDelay is microseconds */
        gpioDelay(SAMPLE_US);
    }

    /* --- Graceful shutdown ------------------------------------------ */
    printf("\nShutting down...\n");
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

