/*
 * Raspberry Pi MCP3008 ADC reader with PWM motor control.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> Potentiometer wiper
 *   GPIO18 (BCM) -> Motor PWM input
 *
 * Build: gcc -O2 -Wall -o adc_pwm adc_pwm.c -lpigpio -lrt
 * Run:   sudo ./adc_pwm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 channel 0 */
#define PWM_PIN        18         /* GPIO18 (BCM) */
#define PWM_FREQ       1000       /* 1 kHz */
#define PWM_RANGE      1023       /* 10-bit resolution */
#define SAMPLE_US      100000     /* 100 ms between samples */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* MCP3008 read                                                        */
/* ------------------------------------------------------------------ */
/*
 * MCP3008 single-ended read sequence (3 bytes):
 *   Byte 0: 0x01                       (start bit)
 *   Byte 1: (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   Byte 2: 0x00                       (clock out remaining bits)
 *
 * Response:
 *   rx[0] = don't care
 *   rx[1] = [null bit][b9 b8] in the low nibble
 *   rx[2] = b7..b0
 */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* PWM setup                                                           */
/* ------------------------------------------------------------------ */
static int setup_pwm(int pin)
{
    if (gpioSetMode(pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", pin);
        return -1;
    }
    if (gpioSetPWMfrequency(pin, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", pin);
        return -1;
    }
    if (gpioSetPWMrange(pin, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", pin);
        return -1;
    }
    if (gpioPWM(pin, 0) != 0) {
        fprintf(stderr, "Failed to initialise PWM duty cycle on GPIO %d\n", pin);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    /* Ensure PWM is off before terminating pigpio */
    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (setup_pwm(PWM_PIN) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADC (CH0)  PWM (GPIO18)\n");
    printf("----------  ------------\n");

    while (g_running) {
        int adc = read_mcp3008(g_spi_handle, ADC_CHANNEL);
        if (adc < 0) {
            /* Transient SPI error: keep running, try again next cycle */
            gpioDelay(SAMPLE_US);
            continue;
        }

        /* Map 0..1023 to 0..PWM_RANGE */
        int pwm = (int)(((float)adc / 1023.0f) * (float)PWM_RANGE);
        if (gpioPWM(PWM_PIN, pwm) != 0) {
            fprintf(stderr, "gpioPWM failed for duty %d\n", pwm);
            break;
        }

        printf("%5d   %5d\n", adc, pwm);
        fflush(stdout);

        gpioDelay(SAMPLE_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

