#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <getopt.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define LED_GPIO 17

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

#define ADS1115_CONFIG_OS_BEGIN (1 << 15)
#define ADS1115_CONFIG_MUX_SINGLE_0 (0x4000)
#define ADS1115_CONFIG_PGA_4_096V (0x0200)
#define ADS1115_CONFIG_MODE_SINGLE (0x0100)
#define ADS1115_CONFIG_DR_128SPS (0x0080)

#define DEFAULT_THRESHOLD 100.0
#define SAMPLE_DELAY_US 100000
#define BLINK_DURATION_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int16_t read_ads1115_single_ended(int handle, uint16_t mux) {
    uint16_t config = ADS1115_CONFIG_OS_BEGIN | mux | ADS1115_CONFIG_PGA_4_096V |
                      ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS;

    char cfg[3];
    cfg[0] = ADS1115_REG_CONFIG;
    cfg[1] = (config >> 8) & 0xFF;
    cfg[2] = config & 0xFF;

    if (i2cWriteDevice(handle, cfg, 3) < 0) {
        return -1;
    }

    gpioDelay(10000);

    char reg[1] = {ADS1115_REG_CONVERSION};
    if (i2cWriteDevice(handle, reg, 1) < 0) {
        return -1;
    }

    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        return -1;
    }

    return (int16_t)((data[0] << 8) | data[1]);
}

static double calculate_magnetic_field(int16_t adc_value) {
    const double v_supplied = 4.096;
    const double adc_full_scale = 32767.0;
    return (v_supplied / adc_full_scale) * adc_value;
}

static void blink_led(int gpio, int duration_us) {
    gpioWrite(gpio, 1);
    gpioDelay(duration_us / 2);
    gpioWrite(gpio, 0);
    gpioDelay(duration_us / 2);
}

int main(int argc, char *argv[]) {
    double threshold = DEFAULT_THRESHOLD;
    int opt;

    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                if (threshold <= 0.0) {
                    fprintf(stderr, "Error: Threshold must be greater than 0.\n");
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold_gauss]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, ADS1115_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", LED_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring magnetic field (threshold: %.2f Gauss)... Press Ctrl+C to exit.\n", threshold);

    while (running) {
        int16_t adc_value = read_ads1115_single_ended(i2c_handle, ADS1115_CONFIG_MUX_SINGLE_0);

        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read from ADS1115.\n");
            break;
        }

        double magnetic_field = calculate_magnetic_field(adc_value);
        printf("Magnetic Field: %.2f Gauss\n", magnetic_field);

        if (magnetic_field > threshold) {
            printf("Threshold exceeded! Blinking LED.\n");
            blink_led(LED_GPIO, BLINK_DURATION_US);
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    gpioWrite(LED_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

