        gpioDelay(SAMPLE_DELAY_US);
    }

    gpioWrite(LED_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
