#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <errno.h>
#include <stdbool.h>
#include <pigpio.h>
#include <mosquitto.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30.0
#define MOISTURE_HYSTERESIS 35.0
#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC_PUBLISH "soil_moisture"
#define MQTT_TOPIC_SUBSCRIBE "pump_control"
#define MQTT_KEEPALIVE 60
#define SAMPLE_INTERVAL 60

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static struct mosquitto *mosq = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        syslog(LOG_ERR, "SPI transfer failed (returned %d): %s", ret, strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_moisture(int adc) {
    if (adc < 0 || adc > 1023) return -1.0;
    return 100.0 - ((float)adc / 1023.0) * 100.0;
}

static int set_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        syslog(LOG_ERR, "Failed to write GPIO %d to %d", PUMP_GPIO, state);
        return -1;
    }
    syslog(LOG_INFO, "Pump set to %s", state ? "ON" : "OFF");
    return 0;
}

static void publish_moisture(float moisture) {
    char payload[32];
    int len = snprintf(payload, sizeof(payload), "%.2f", moisture);
    if (len < 0 || (size_t)len >= sizeof(payload)) {
        syslog(LOG_ERR, "Moisture payload formatting failed");
        return;
    }
    if (mosquitto_publish(mosq, NULL, MQTT_TOPIC_PUBLISH, (uint)len, payload, 0, false) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to publish moisture data: %s", mosquitto_strerror(mosq->last_err));
    }
}

static void mqtt_connect_callback(struct mosquitto *m, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT connected to %s:%d", MQTT_HOST, MQTT_PORT);
        if (mosquitto_subscribe(m, NULL, MQTT_TOPIC_SUBSCRIBE, 0) != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Failed to subscribe to %s: %s", MQTT_TOPIC_SUBSCRIBE, mosquitto_strerror(mosq->last_err));
        }
    } else {
        syslog(LOG_ERR, "MQTT connection failed: %s", mosquitto_strerror(result));
    }
}

static void mqtt_disconnect_callback(struct mosquitto *m, void *userdata, int rc) {
    (void)m; (void)userdata;
    syslog(LOG_WARNING, "MQTT disconnected (rc=%d)", rc);
}

static void mqtt_message_callback(struct mosquitto *m, void *userdata, const struct mosquitto_message *message) {
    (void)m; (void)userdata;
    if (message->payloadlen > 0) {
        char payload[32];
        int len = message->payloadlen < (int)sizeof(payload) - 1 ? message->payloadlen : (int)sizeof(payload) - 1;
        memcpy(payload, message->payload, len);
        payload[len] = '\0';

        if (strcmp(message->topic, MQTT_TOPIC_SUBSCRIBE) == 0) {
            if (strcmp(payload, "pump_on") == 0) {
                syslog(LOG_INFO, "Received pump_on command");
                set_pump(1);
            } else if (strcmp(payload, "pump_off") == 0) {
                syslog(LOG_INFO, "Received pump_off command");
                set_pump(0);
            } else {
                syslog(LOG_WARNING, "Unknown command: %s", payload);
            }
        }
    }
}

static void cleanup(void) {
    syslog(LOG_INFO, "Cleaning up...");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
    }
    mosquitto_lib_cleanup();
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("soil_moisture_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set signal handlers: %s", strerror(errno));
        closelog();
        return 1;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as output", PUMP_GPIO);
        gpioTerminate();
        closelog();
        return 1;
    }
    gpioWrite(PUMP_GPIO, 0);

    mosquitto_lib_init();

    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create MQTT client");
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, mqtt_connect_callback);
    mosquitto_disconnect_callback_set(mosq, mqtt_disconnect_callback);
    mosquitto_message_callback_set(mosq, mqtt_message_callback);

    int rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, MQTT_KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosq = NULL;
        mosquitto_lib_cleanup();
        gpioTerminate();
        closelog();
        return 1;
    }

    rc = mosquitto_loop_start(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT loop start failed: %s", mosquitto_strerror(rc));
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
        mosquitto_lib_cleanup();
        gpioTerminate();
        closelog();
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed: %s", strerror(errno));
        cleanup();
        return 1;
    }

    bool pump_on = false;
    time_t last_sample = time(NULL);

    while (running) {
        int adc = read_mcp3008(0);
        if (adc < 0) {
            syslog(LOG_ERR, "ADC read failed; skipping cycle");
        } else {
            float moisture = adc_to_moisture(adc);
            if (moisture < 0.0) {
                syslog(LOG_ERR, "ADC value out of range: %d", adc);
            } else {
                time_t now = time(NULL);
                if (difftime(now, last_sample) >= SAMPLE_INTERVAL) {
                    if (moisture < MOISTURE_THRESHOLD && !pump_on) {
                        if (set_pump(1) == 0) {
                            pump_on = true;
                        }
                    } else if (moisture > MOISTURE_HYSTERESIS && pump_on) {
                        if (set_pump(0) == 0) {
                            pump_on = false;
                        }
                    }
                    publish_moisture(moisture);
                    last_sample = now;
                }
            }
        }
        sleep(1);
    }

    cleanup();
    return 0;
}

