#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define VREF        3.3
#define NUM_CHANNELS 3
#define CSV_FILE    "sensor_data.csv"
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0 on success and stores the 10-bit value in *value;
 * returns -1 on SPI transfer failure.
 */
static int read_mcp3008(int spi_handle, int channel, uint16_t *value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: rx[1] low 2 bits + rx[2] 8 bits = 10-bit ADC value
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }

    *value = (uint16_t)(((rx[1] & 0x03) << 8) | (uint8_t)rx[2]);
    return 0;
}

static int log_data(const char *filename, float v0, float v1, float v2)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[64];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%.3f,%.3f,%.3f\n", ts, v0, v1, v2) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }

    return 0;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0 at 1 MHz, mode 0 */
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MCP3008 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t raw[NUM_CHANNELS];
        int error = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            if (read_mcp3008(spi_handle, i, &raw[i]) != 0) {
                fprintf(stderr, "Error reading channel %d\n", i);
                error = 1;
                break;
            }
        }

        if (error) {
            break;
        }

        float v0 = (raw[0] / 1023.0f) * VREF;
        float v1 = (raw[1] / 1023.0f) * VREF;
        float v2 = (raw[2] / 1023.0f) * VREF;

        if (log_data(CSV_FILE, v0, v1, v2) != 0) {
            fprintf(stderr, "Error logging data\n");
            break;
        }

        printf("Ch0: %.3f V  Ch1: %.3f V  Ch2: %.3f V\n", v0, v1, v2);

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int s = 0; s < SAMPLE_INTERVAL_S * 10 && g_running; s++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    /* Clean resource release on all exit paths */
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

