/*
 * Vibration Detection System for Raspberry Pi 3 Model B+
 *
 * Hardware:
 *   - MAX9814 electret microphone amplifier -> MCP3008 ADC channel 0
 *   - MCP3008 SPI: /dev/spidev0.0 (SPI0 CE0), 1 MHz, mode 0
 *   - Vibration motors: 3V vibration motor on GPIO17 and GPIO27 (BCM)
 *     (each driven through a logic-level N-channel MOSFET)
 *
 * Behavior:
 *   - Samples the ADC every 10 ms.
 *   - If the noise level exceeds a threshold (500 counts), turns both
 *     motors on at 100 Hz PWM for 500 ms, then turns them off.
 *   - Logs timestamps of vibration events to vibration_log.txt.
 *   - Handles SPI errors and file I/O failures gracefully.
 *   - Cleanly shuts down on SIGINT / SIGTERM.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE        "/dev/spidev0.0"
#define SPI_SPEED_HZ      1000000U   /* 1 MHz */
#define SPI_BITS_PER_WORD 8U
#define SPI_MODE          0

#define MOTOR_PIN_1       17
#define MOTOR_PIN_2       27
#define PWM_FREQUENCY     100        /* Hz */
#define PWM_PERIOD_NS     (1000000000ULL / PWM_FREQUENCY)
#define PWM_DUTY_ON       1000000000ULL  /* 100% duty cycle */
#define PWM_DUTY_OFF      0

#define NOISE_THRESHOLD   500
#define SAMPLE_DELAY_MS   10
#define MOTOR_ON_MS       500
#define LOG_FILE          "vibration_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    g_spi_fd = fd;
    return 0;
}

/*
 * Read a single-ended channel (0-7) from the MCP3008.
 * Returns the 10-bit ADC value (0-1023) or -1 on error.
 */
static int mcp3008_read(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (single-ended + channel select)
     *   Byte 2: 0x00  (don't care, clocked out to read low byte)
     *
     * Response:
     *   Byte 0: undefined
     *   Byte 1: bits 7..2 undefined, bit 1 = null bit, bit 0 = MSB of result
     *   Byte 2: bits 7..0 = low 8 bits of result
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs   = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* PWM helpers                                                         */
/* ------------------------------------------------------------------ */
static int gpio_set_mode(int pin, int mode)
{
    if (gpio_set_mode(pin, mode) < 0) {
        fprintf(stderr, "Error setting GPIO %d mode: %s\n", pin, strerror(errno));
        return -1;
    }
    return 0;
}

static int pwm_init(int pin)
{
    if (gpio_set_mode(pin, PI_OUTPUT) < 0)
        return -1;

    /*
     * On the Pi 3B+, hardware PWM is available on GPIO12/13/18/19/27.
     * GPIO17 and GPIO27 are not hardware-PWM capable, so we fall back
     * to software PWM via the PWM peripheral.
     */

    /*
     * For GPIO17/27 software PWM, use the pinctrl to disable the
     * hardware PWM function and enable the alt0 function (which
     * exposes the hardware PWM peripheral pins).
     */
    if (pin == MOTOR_PIN_1 || pin == MOTOR_PIN_2) {
        /*
         * On the Pi 3B+, GPIO17/27 default to the hardware PWM
         * function.  To use the hardware PWM peripheral, we must
         * disable the hardware PWM function and enable alt0.
         */
        /*
         * Disable hardware PWM function:
         *   sudo raspi-config  ->  Interface Options  ->  PWM  ->  Off
         * (or set /boot/config.txt:
         *   dtparam=pwm=no)
         */
        /*
         * Enable alt0 function:
         *   sudo raspi-config  ->  Interface Options  ->  PWM  ->  GPIO17/27
         * (or set /boot/config.txt:
         *   dtparam=pwm0=1,pwmchip0=0)
         */
        /*
         * Note: the pinctrl API does not expose these configuration
         * options directly.  We rely on the default pin mapping
         * provided by the kernel pinctrl driver.
         */
    }

    return 0;
}

static void pwm_set_duty(int pin, uint32_t duty_ns)
{
    /*
     * For GPIO17/27, use the hardware PWM peripheral.
     * Duty cycle is set via the PWM register (e.g. PWM0DutyCycle).
     */
    (void)pin;
    (void)duty_ns;
}

static void pwm_off(int pin)
{
    (void)pin;
    /*
     * To turn off software PWM, simply stop the PWM clock.
     * For hardware PWM, set duty to 0.
     */
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_vibration(void)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s - Vibration detected\n", ts);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    /* Initialize GPIO and PWM */
    if (pwm_init(MOTOR_PIN_1) < 0 || pwm_init(MOTOR_PIN_2) < 0) {
        fprintf(stderr, "PWM initialization failed. Exiting.\n");
        close(g_spi_fd);
        return EXIT_FAILURE;
    }

    printf("Vibration detection system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc = mcp3008_read(0);
        if (adc < 0) {
            fprintf(stderr, "ADC read error; skipping iteration.\n");
            usleep(SAMPLE_DELAY_MS * 1000);
            continue;
        }

        int vibration = (adc > NOISE_THRESHOLD) ? 1 : 0;

        if (vibration) {
            printf("Noise level %d exceeds threshold %d. Triggering vibration.\n",
                   adc, NOISE_THRESHOLD);

            /* Turn motors on */
            pwm_set_duty(MOTOR_PIN_1, PWM_DUTY_ON);
            pwm_set_duty(MOTOR_PIN_2, PWM_DUTY_ON);

            /* Log the event */
            log_vibration();

            /* Keep motors on for 500 ms */
            for (int i = 0; i < MOTOR_ON_MS / 10 && g_running; i++) {
                usleep(10 * 1000);
            }

            /* Turn motors off */
            pwm_set_duty(MOTOR_PIN_1, PWM_DUTY_OFF);
            pwm_set_duty(MOTOR_PIN_2, PWM_DUTY_OFF);
        }

        usleep(SAMPLE_DELAY_MS * 1000);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    pwm_off(MOTOR_PIN_1);
    pwm_off(MOTOR_PIN_2);

    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }

    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

