#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/i2c-dev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"
#define CSV_FILE "tamper_log.csv"
#define BH1750_ADDR 0x5C
#define BH1750_CONT_HIGHRES 0x10
#define MCP3008_CHANNEL 0
#define SAMPLE_INTERVAL_SEC 5
#define BH1750_CONV_MS 180

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static int i2c_fd = -1;
static FILE *csv_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (spi_fd < 0) return -1;
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer tr = {0};
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = 1000000;
    tr.bits_per_word = 8;
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) return -1;
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int read_bh1750(void) {
    if (i2c_fd < 0) return -1;
    if (write(i2c_fd, &BH1750_CONT_HIGHRES, 1) != 1) return -2;
    usleep(BH1750_CONV_MS * 1000);
    unsigned char buf[2] = {0};
    if (read(i2c_fd, buf, 2) != 2) return -3;
    return (buf[0] << 8) | buf[1];
}

static void log_data(int sound, int light, int err) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(csv_fp, "%s,%d,%d,%d\n", ts, sound, light, err);
    fflush(csv_fp);
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) { perror("open SPI"); return 1; }
    unsigned char mode = SPI_MODE_0;
    unsigned char bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 || ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("SPI config"); close(spi_fd); return 1;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) { perror("open I2C"); close(spi_fd); return 1; }

    csv_fp = fopen(CSV_FILE, "a");
    if (!csv_fp) { perror("open CSV"); close(spi_fd); close(i2c_fd); return 1; }

    while (running) {
        int sound = -1, light = -1, err = 0;
        if (sound < 0) sound = read_mcp3008(MCP3008_CHANNEL);
        if (light < 0) light = read_bh1750();
        if (sound < 0 || light < 0) err = 1;
        log_data(sound, light, err);
        sleep(SAMPLE_INTERVAL_SEC);
    }

    fclose(csv_fp);
    close(spi_fd);
    close(i2c_fd);
    return 0;
}

