#define LOG_FILE         "moisture.log"

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_fp    = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  init_spi(void);
static int  read_mcp3008(int channel, int *out_value);
static void control_pump(int state);
static void log_reading(int moisture, bool pump_on);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- SPI init ---------------------------------- */
static int init_spi(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel %d, %d Hz): pigpio error %d\n",
                SPI_CHANNEL, SPI_SPEED, g_spi_handle);
        return -1;
    }
    return 0;
}

/* ----------------------------- MCP3008 read ------------------------------ */
/*
 * MCP3008 single-ended read sequence (3 bytes):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care)
 *   tx[2] = 0x00                       (clock out low 2 bits)
 * Result: 10-bit value = ((rx[1] & 0x03) << 8) | rx[2]
 */
static int read_mcp3008(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    for (int attempt = 1; attempt <= MAX_RETRIES; ++attempt) {
        int rc = spiXfer(g_spi_handle, tx, rx, 3);
        if (rc == 3) {
            *out_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
            return 0;
        }
        fprintf(stderr, "spiXfer attempt %d/%d failed (rc=%d): %s\n",
                attempt, MAX_RETRIES, rc, strerror(errno));
        if (attempt < MAX_RETRIES) {
            gpioDelay(100000);  /* 100 ms back-off */
        }
    }
    return -1;
}

/* ----------------------------- Pump control ------------------------------ */
static void control_pump(int state)
{
    if (gpioWrite(PUMP_GPIO, state ? 1 : 0) < 0) {
        fprintf(stderr, "gpioWrite(%d, %d) failed: %s\n",
                PUMP_GPIO, state, strerror(errno));
    }
}

/* ----------------------------- Logging ----------------------------------- */
static void log_reading(int moisture, bool pump_on)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32] = { 0 };

    if (t != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    } else {
        snprintf(ts, sizeof(ts), "UNKNOWN");
    }

    printf("[%s] Moisture: %d%%  Pump: %s\n", ts, moisture,
           pump_on ? "ON" : "OFF");

    if (g_log_fp != NULL) {
        fprintf(g_log_fp, "%s,%d,%s\n", ts, moisture,
                pump_on ? "ON" : "OFF");
        fflush(g_log_fp);
    }
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    /* Ensure pump is off before touching anything else */
    control_pump(0);

    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- pump GPIO as output, off --- */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, OUTPUT) failed: %s\n",
                PUMP_GPIO, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    control_pump(0);

    /* --- SPI init --- */
    if (init_spi() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VH400 soil moisture monitor started.  Sampling every %d s.\n",
           SAMPLE_PERIOD_S);

    /* --- main loop --- */
    while (g_running) {
        int moisture = -1;

        if (read_mcp3008(ADC_CHANNEL, &moisture) < 0) {
            fprintf(stderr, "ADC read failed after %d retries — skipping cycle\n",
                    MAX_RETRIES);
        } else {
            /* Threshold logic: turn pump ON if moisture < MOISTURE_THRESH */
            bool pump_on = (moisture < MOISTURE_THRESH);
            control_pump(pump_on);
            log_reading(moisture, pump_on);
        }

        /* Sleep in 1 s increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD_S && g_running; ++i) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

