/*
 * Raspberry Pi Zero W - IR Distance Sensor (GP2Y0A21YK0F) + MCP3008 ADC + Relay
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3V (Pin 1)
 *   MCP3008 VREF -> 3.3V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> GP2Y0A21YK0F OUT
 *   Relay IN     -> GPIO17 (BCM)
 *   Relay VCC    -> 3.3V or 5V (per relay spec)
 *   Relay GND    -> GND
 *
 * Build: gcc -Wall -Wextra -O2 -o door_monitor door_monitor.c -lpigpio -lrt
 * Run:   sudo ./door_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */

#define ADC_CHANNEL    0          /* MCP3008 channel 0 */
#define ADC_MAX_VALUE  1023       /* 10-bit ADC */

#define RELAY_GPIO     17         /* BCM 17 */
#define DISTANCE_THRESHOLD 20     /* cm */
#define DEBOUNCE_DELAY  1000000   /* 1 s in microseconds */
#define POLL_DELAY      100000    /* 100 ms in microseconds */

#define LOG_FILE       "door_events.log"

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read MCP3008 single-ended channel (0-7). Returns 0-1023 or -1.      */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  -> single-ended + channel select
     *   Byte 2: 0x00  (don't care, clocked out to read low byte)
     *
     * Response:
     *   rx[0] = ignored
     *   rx[1] = [null bit][b9 b8] in the two LSBs
     *   rx[2] = b7..b0
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(g_spi_handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", bytes);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Convert ADC value to distance (cm).                                 */
/* GP2Y0A21YK0F: lower voltage = closer.  Distance (cm) ≈ 2233 / V.     */
/* ------------------------------------------------------------------ */
static int adc_to_distance(int adc_value)
{
    if (adc_value < 0 || adc_value > ADC_MAX_VALUE) {
        return -1;
    }

    /*
     * Voltage = (adc_value / 1023.0) * 3.3 V
     * Distance (cm) ≈ 2233.0 / voltage
     *   (approximate inverse relationship)
     */
    double voltage = (adc_value / (double)ADC_MAX_VALUE) * 3.3;
    if (voltage <= 0.0) {
        return -1;
    }

    double distance = 2233.0 / voltage;
    return (int)distance;
}

/* ------------------------------------------------------------------ */
/* Log a door-opening event with timestamp.                            */
/* ------------------------------------------------------------------ */
static void log_event(void)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        perror("localtime_r()");
        fclose(fp);
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%s - Door opened (distance < %d cm)\n", timestamp, DISTANCE_THRESHOLD);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Relay GPIO setup --- */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);  /* ensure relay starts de-energized */

    /* --- SPI open --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Door monitoring started.  Threshold = %d cm.  Press Ctrl+C to exit.\n",
           DISTANCE_THRESHOLD);

    uint32_t last_detection_tick = 0;

    while (g_running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error - skipping cycle\n");
            gpioDelay(POLL_DELAY);
            continue;
        }

        int distance = adc_to_distance(adc_value);
        if (distance < 0) {
            fprintf(stderr, "Invalid distance (ADC=%d) - skipping cycle\n", adc_value);
            gpioDelay(POLL_DELAY);
            continue;
        }

        printf("Distance: %d cm\n", distance);

        if (distance < DISTANCE_THRESHOLD) {
            uint32_t now = gpioTick();
            if (now - last_detection_tick >= DEBOUNCE_DELAY) {
                last_detection_tick = now;

                printf("Object detected within %d cm - door opening simulated\n",
                       DISTANCE_THRESHOLD);

                if (gpioWrite(RELAY_GPIO, 1) != 0) {
                    fprintf(stderr, "Failed to energize relay\n");
                } else {
                    log_event();
                }

                /* Keep relay energized for 500 ms, then de-energize */
                gpioDelay(500000);
                if (gpioWrite(RELAY_GPIO, 0) != 0) {
                    fprintf(stderr, "Failed to de-energize relay\n");
                }
            }
        }

        gpioDelay(POLL_DELAY);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

