#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define VALVE_GPIO 17
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define NUM_SAMPLES 3
#define LOG_FILE "irrigation.log"
#define SAMPLE_INTERVAL_SEC 5

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int calculate_valve_position(int *adc_values, int num_samples) {
    int sum = 0;
    int valid_count = 0;

    for (int i = 0; i < num_samples; i++) {
        int adc = adc_values[i];
        if (adc < 0) {
            fprintf(stderr, "Error: Invalid ADC reading %d from sample %d\n", adc, i);
            continue;
        }
        sum += adc;
        valid_count++;
    }

    if (valid_count == 0) {
        fprintf(stderr, "Error: No valid ADC readings\n");
        return -1;
    }

    int average = sum / valid_count;
    int position = (average * PWM_RANGE) / 1023;

    if (position < 0) position = 0;
    if (position > PWM_RANGE) position = PWM_RANGE;

    return position;
}

static void log_data(int *adc_values, int num_samples, int average, int valve_position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ADC1: %d, ADC2: %d, ADC3: %d, Average: %d, Valve Position: %d\n",
            timestamp, adc_values[0], adc_values[1], adc_values[2], average, valve_position);
    fflush(log_file);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(VALVE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", VALVE_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Warning: Could not set exact PWM frequency on GPIO %d\n", VALVE_GPIO);
    }

    if (gpioSetPWMrange(VALVE_GPIO, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Warning: Could not set exact PWM range on GPIO %d\n", VALVE_GPIO);
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    int adc_values[NUM_SAMPLES];
    int valve_position;

    while (!terminate) {
        for (int i = 0; i < NUM_SAMPLES; i++) {
            adc_values[i] = read_mcp3008(i);
            if (adc_values[i] < 0) {
                fprintf(stderr, "Error reading ADC value from sample %d\n", i);
                terminate = 1;
                break;
            }
        }

        if (terminate) break;

        valve_position = calculate_valve_position(adc_values, NUM_SAMPLES);
        if (valve_position < 0) {
            fprintf(stderr, "Error calculating valve position\n");
            terminate = 1;
            break;
        }

        gpioPWM(VALVE_GPIO, valve_position);

        log_data(adc_values, NUM_SAMPLES, (adc_values[0] + adc_values[1] + adc_values[2]) / NUM_SAMPLES, valve_position);

        sleep(SAMPLE_INTERVAL_SEC);
    }

    gpioPWM(VALVE_GPIO, 0);
    cleanup();
    return EXIT_SUCCESS;
}

