        } else {
            float moisture = adc_to_moisture(adc_value);
            if (moisture < 0.0f) {
                fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
                log_data(-1.0f, "ADC_OUT_OF_RANGE");
            } else {
                log_data(moisture, "OK");
                printf("Moisture: %.2f%%\n", moisture);
            }
        }

        for (int i = 0; i < SAMPLE_INTERVAL && running; i++) {
            gpioSleep(PI_TIME_RELATIVE, 1, 0);
        }
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("\nSoil moisture monitoring stopped.\n");
    return 0;
