#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define CONFIG_FILE "theremin_config.txt"
#define PWM_PERIOD_NS 1000000
#define PWM_RANGE 255
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_MODE 0

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18

#define MAX_DISTANCE 400.0
#define MIN_DISTANCE 2.0
#define MAX_VOLTAGE 3.3
#define MIN_VOLTAGE 0.0

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static double distance_coeff = 1.0;
static double voltage_coeff = 1.0;
static int pwm_duty_cycle = 128;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_config(void) {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (!fp) return -1;
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=\n");
        char *val = strtok(NULL, "=\n");
        if (key && val) {
            if (strcmp(key, "distance_coeff") == 0) distance_coeff = atof(val);
            else if (strcmp(key, "voltage_coeff") == 0) voltage_coeff = atof(val);
            else if (strcmp(key, "pwm_duty_cycle") == 0) pwm_duty_cycle = atoi(val);
        }
    }
    fclose(fp);
    return 0;
}

static int write_config(void) {
    FILE *fp = fopen(CONFIG_FILE, "w");
    if (!fp) return -1;
    fprintf(fp, "distance_coeff=%.6f\n", distance_coeff);
    fprintf(fp, "voltage_coeff=%.6f\n", voltage_coeff);
    fprintf(fp, "pwm_duty_cycle=%d\n", pwm_duty_cycle);
    fclose(fp);
    return 0;
}

static int init_spi(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) { perror("open spidev"); return -1; }
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) { perror("ioctl mode"); close(spi_fd); spi_fd = -1; return -1; }
    int bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) { perror("ioctl bits"); close(spi_fd); spi_fd = -1; return -1; }
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) { perror("ioctl speed"); close(spi_fd); spi_fd = -1; return -1; }
    return 0;
}

static int read_adc(int channel) {
    if (channel < 0 || channel > 7) return -1;
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer tr = {0};
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) { perror("spi transfer"); return -1; }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double measure_distance(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);
    uint32_t start = 0, end = 0;
    uint32_t timeout = 30000;
    while (gpioRead(ECHO_PIN) == 0 && timeout-- > 0) gpioDelay(1);
    if (timeout <= 0) return -1.0;
    start = gpioTick();
    timeout = 30000;
    while (gpioRead(ECHO_PIN) == 1 && timeout-- > 0) gpioDelay(1);
    if (timeout <= 0) return -1.0;
    end = gpioTick();
    uint32_t diff = end - start;
    double distance = (diff / 1000000.0) * 34300.0 / 2.0;
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) return -1.0;
    return distance;
}

static int read_ldr(void) {
    int adc = read_adc(0);
    if (adc < 0) return -1;
    double voltage = (adc / 1023.0) * MAX_VOLTAGE;
    int volume = (int)((voltage - MIN_VOLTAGE) / (MAX_VOLTAGE - MIN_VOLTAGE) * PWM_RANGE);
    if (volume < 0) volume = 0;
    if (volume > PWM_RANGE) volume = PWM_RANGE;
    return volume;
}

static void set_pwm(int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    gpioPWM(PWM_PIN, duty);
}

static void cleanup(void) {
    gpioPWM(PWM_PIN, 0);
    if (spi_fd >= 0) close(spi_fd);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) { fprintf(stderr, "pigpio init failed\n"); return 1; }
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_PIN, 1000);
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);
    if (init_spi() < 0) { gpioTerminate(); return 1; }
    if (read_config() < 0) write_config();
    double last_distance = 100.0, last_volume = 128;
    while (running) {
        double distance = measure_distance();
        if (distance < 0) {
            fprintf(stderr, "Sensor error, retaining last values\n");
        } else {
            double volume = read_ldr();
            if (volume < 0) { fprintf(stderr, "LDR read error\n"); volume = last_volume; }
            last_distance = distance;
            last_volume = volume;
            double freq = 220.0 + (distance * distance_coeff);
            set_pwm((int)(freq * 0.5 + volume * 0.5));
        }
        gpioDelay(20000);
    }
    cleanup();
    return 0;
}

