/*
 * MQ-3 Alcohol Sensor Monitor via MCP3008 ADC on Raspberry Pi Zero W
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3V (Pin 1)
 *   MCP3008 VREF -> 3.3V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MQ-3 AOUT    -> MCP3008 CH0
 *
 * Build: gcc -O2 -Wall -o alcohol_monitor alcohol_monitor.c -lpigpio -lrt
 * Run:   sudo ./alcohol_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, 8-bit words, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX_VALUE  1023       /* 10-bit ADC */
#define LOG_FILE       "alcohol_log.txt"
#define SAMPLE_PERIOD  1          /* seconds between samples */
#define MAX_RETRIES    3          /* retries per ADC read */
#define RETRY_DELAY_US 100000     /* 100 ms between retries */
#define SENSOR_TIMEOUT 10         /* consecutive 0/1023 readings before warning */

#define THRESHOLD_HIGH  50.0f     /* ppm — alarm threshold */
#define THRESHOLD_LOW   20.0f     /* ppm — sobriety threshold */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 single-ended read                                           */
/* ------------------------------------------------------------------ */
/*
 * MCP3008 SPI protocol (3-byte transfer, mode 0):
 *   Byte 0: 0x01                       (start bit)
 *   Byte 1: (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   Byte 2: 0x00                       (clock out remaining bits)
 *
 * Response:
 *   rx[0] = ignored
 *   rx[1] = [null bit][b9 b8] in the two LSBs
 *   rx[2] = b7..b0
 */
static int read_mcp3008(int spi_handle, int channel, int *adc_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }
    if (adc_value == NULL) {
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(spi_handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d): %s\n",
                bytes, strerror(errno));
        return -1;
    }

    int raw = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    *adc_value = raw;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Conversion to ppm                                                   */
/* ------------------------------------------------------------------ */
/*
 * NOTE: The MQ-3 requires calibration for your specific sensor and
 * load resistor.  The linear mapping below is a placeholder —
 * replace with your calibrated curve for reliable ppm readings.
 */
static float adc_to_ppm(int adc_value)
{
    const float slope     = 0.5f;
    const float intercept = 20.0f;
    return slope * (float)adc_value + intercept;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, int adc_value, float ppm,
                     const char *status)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r() failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (fprintf(fp, "%s, ADC: %d, Voltage: %.2f V, PPM: %.2f, %s\n",
                ts, adc_value, (float)adc_value / ADC_MAX_VALUE * 3.3f,
                ppm, status) < 0) {
        fprintf(stderr, "fprintf() to log failed: %s\n", strerror(errno));
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI open --- */
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel %d, %d Hz): %s\n",
                SPI_CHANNEL, SPI_SPEED, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("MQ-3 alcohol sensor monitoring started.\n");
    printf("SPI0 CE0 @ %d Hz, ADC channel %d, logging to '%s'.\n",
           SPI_SPEED, ADC_CHANNEL, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    int consecutive_errors = 0;
    int consecutive_zero   = 0;
    int consecutive_max    = 0;

    while (g_running) {
        int adc_value = -1;
        int ok = 0;

        /* Retry transient SPI errors */
        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_mcp3008(spi_handle, ADC_CHANNEL, &adc_value) == 0) {
                ok = 1;
                break;
            }
            if (attempt < MAX_RETRIES - 1) {
                gpioDelay(RETRY_DELAY_US);
            }
        }

        if (!ok) {
            consecutive_errors++;
            fprintf(stderr, "ADC read failed after %d attempts (consecutive: %d)\n",
                    MAX_RETRIES, consecutive_errors);
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive ADC failures — aborting.\n");
                break;
            }
            sleep(1);
            continue;
        }
        consecutive_errors = 0;

        /* Sensor-absent heuristic: rail-stuck at 0 or 1023 */
        if (adc_value == 0) {
            consecutive_zero++;
        } else {
            consecutive_zero = 0;
        }
        if (adc_value == ADC_MAX_VALUE) {
            consecutive_max++;
        } else {
            consecutive_max = 0;
        }

        if (consecutive_zero >= SENSOR_TIMEOUT) {
            fprintf(stderr, "Warning: ADC consistently reads 0 — sensor may be absent or disconnected.\n");
        }
        if (consecutive_max >= SENSOR_TIMEOUT) {
            fprintf(stderr, "Warning: ADC consistently reads 1023 — sensor may be saturated or faulty.\n");
        }

        float ppm = adc_to_ppm(adc_value);

        /* Classify */
        if (ppm > THRESHOLD_HIGH) {
            log_data(g_log_fp, adc_value, ppm, "Alcohol detected! Limit exceeded.");
            printf("[%d] ADC=%d  PPM=%.2f  ALARM\n",
                   (int)time(NULL), adc_value, ppm);
        } else if (ppm < THRESHOLD_LOW) {
            log_data(g_log_fp, adc_value, ppm, "Sobriety confirmed.");
            printf("[%d] ADC=%d  PPM=%.2f  OK\n",
                   (int)time(NULL), adc_value, ppm);
        } else {
            log_data(g_log_fp, adc_value, ppm, "Alcohol level within acceptable range.");
            printf("[%d] ADC=%d  PPM=%.2f  OK\n",
                   (int)time(NULL), adc_value, ppm);
        }

        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

