#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8

#define MOTOR1_EN 18
#define MOTOR2_EN 24
#define MOTOR1_DIR 23
#define MOTOR2_DIR 25

#define PWM_RANGE 1000
#define PWM_FREQ 1000

#define POT1_GPIO 4
#define POT2_GPIO 17

#define ACCEL_DELAY_MS 10
#define DECEL_DELAY_MS 10
#define HOLD_DURATION_S 2
#define REVERSE_DELAY_S 5

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int map_pot_to_speed(int pot_value) {
    if (pot_value < 0) pot_value = 0;
    if (pot_value > 1023) pot_value = 1023;
    return (pot_value * 100) / 1023;
}

static void set_motor_speed(int motor, int speed) {
    if (speed < 0) speed = 0;
    if (speed > PWM_RANGE) speed = PWM_RANGE;

    if (motor == 1) {
        gpioPWM(MOTOR1_EN, speed);
        gpioWrite(MOTOR1_DIR, 0);
    } else if (motor == 2) {
        gpioPWM(MOTOR2_EN, speed);
        gpioWrite(MOTOR2_DIR, 0);
    }
}

static void motor_accelerate(int motor, int speed) {
    if (motor == 1) {
        gpioWrite(MOTOR1_DIR, 1);
        for (int i = 0; i <= speed && running; i += 10) {
            set_motor_speed(1, i);
            gpioDelay(ACCEL_DELAY_MS * 1000);
        }
    }
    if (motor == 2) {
        gpioWrite(MOTOR2_DIR, 1);
        for (int i = 0; i <= speed && running; i += 10) {
            set_motor_speed(2, i);
            gpioDelay(ACCEL_DELAY_MS * 1000);
        }
    }
}

static void motor_decelerate(int motor, int speed) {
    if (motor == 1) {
        for (int i = speed; i >= 0 && running; i -= 10) {
            set_motor_speed(1, i);
            gpioDelay(DECEL_DELAY_MS * 1000);
        }
        gpioWrite(MOTOR1_DIR, 0);
    }
    if (motor == 2) {
        for (int i = speed; i >= 0 && running; i -= 10) {
            set_motor_speed(2, i);
            gpioDelay(DECEL_DELAY_MS * 1000);
        }
        gpioWrite(MOTOR2_DIR, 0);
    }
}

static void reverse_motors(void) {
    gpioWrite(MOTOR1_DIR, 0);
    gpioWrite(MOTOR2_DIR, 1);
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);
    gpioDelay(200000);
    gpioWrite(MOTOR2_DIR, 0);
    gpioDelay(200000);
