    gpioSetPWMrange(MOTOR2_EN, PWM_RANGE);
    gpioSetPWMfrequency(MOTOR1_EN, PWM_FREQ);
    gpioSetPWMfrequency(MOTOR2_EN, PWM_FREQ);

    gpioSetMode(POT1_GPIO, PI_INPUT);
    gpioSetMode(POT2_GPIO, PI_INPUT);

    while (running) {
        int pot1 = read_adc(0);
        int pot2 = read_adc(1);

        if (pot1 < 0 || pot2 < 0) {
            fprintf(stderr, "Error reading potentiometers. Retrying...\n");
            gpioDelay(1000000);
            continue;
        }

        int speed1 = map_pot_to_speed(pot1);
        int speed2 = map_pot_to_speed(pot2);

        printf("Pot 1: %d, Pot 2: %d, Speed 1: %d, Speed 2: %d\n", pot1, pot2, speed1, speed2);

        motor_accelerate(1, speed1);
        motor_accelerate(2, speed2);

        if (!running) break;

        for (int i = 0; i < HOLD_DURATION_S * 10 && running; i += 10) {
            gpioDelay(100000);
        }

        if (!running) break;

        motor_decelerate(1, speed1);
        motor_decelerate(2, speed2);

        if (!running) break;

        reverse_motors();

        if (!running) break;

        for (int i = 0; i < REVERSE_DELAY_S * 10 && running; i += 10) {
            gpioDelay(100000);
        }
    }

cleanup:
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    gpioWrite(MOTOR1_DIR, 0);
    gpioWrite(MOTOR2_DIR, 0);
    gpioPWM(MOTOR1_EN, 0);
    gpioPWM(MOTOR2_EN, 0);
    gpioTerminate();
    return 0;
}

