#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LED_PIN 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define SAMPLE_RATE_US 10000
#define CALIBRATION_TIME_S 5
#define DEBOUNCE_DELAY_US 10000
#define THRESHOLD 50

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int calibrate_baseline(int duration_s) {
    long sum = 0;
    int samples = 0;
    time_t start = time(NULL);

    while (time(NULL) - start < duration_s && running) {
        int val = read_adc(ADC_CHANNEL);
        if (val < 0) {
            fprintf(stderr, "ADC read error during calibration\n");
            return -1;
        }
        sum += val;
        samples++;
        gpioDelay(SAMPLE_RATE_US);
    }

    if (!running) return -1;
    if (samples == 0) return -1;
    return (int)(sum / samples);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin %d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    int baseline = calibrate_baseline(CALIBRATION_TIME_S);
    if (baseline < 0) {
        fprintf(stderr, "Calibration failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    printf("Baseline: %d\n", baseline);

    int led_state = 0;
    int last_sound_level = -1;

    while (running) {
        int sound_level = read_adc(ADC_CHANNEL);
        if (sound_level < 0) {
            gpioDelay(SAMPLE_RATE_US);
            continue;
        }

        if (abs(sound_level - baseline) > THRESHOLD && sound_level != last_sound_level) {
            if (sound_level > baseline) {
                if (led_state == 0) {
                    gpioWrite(LED_PIN, 1);
                    led_state = 1;
                    printf("Sound detected! LED ON\n");
                }
            } else {
                if (led_state == 1) {
                    gpioWrite(LED_PIN, 0);
                    led_state = 0;
                    printf("Sound stopped. LED OFF\n");
                }
            }
            last_sound_level = sound_level;
            gpioDelay(DEBOUNCE_DELAY_US);
        } else {
            last_sound_level = sound_level;
            gpioDelay(SAMPLE_RATE_US);
        }
    }

    gpioWrite(LED_PIN, 0);
    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

