#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "gpiochip0"
#define CS_LINE_OFFSET  8          /* BCM 8 = physical pin 24, SPI CE0 */
#define SPI_SPEED_HZ    1000000    /* 1 MHz */
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0
#define LOG_FILE        "audio_log.txt"
#define SAMPLE_PERIOD_NS 1000000   /* 1 ms -> 1 kHz */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0–1023 on success, -1 on error.
 */
static int mcp3008_read(int spi_fd, struct gpiod_line *cs_line, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: bits 9..0 are in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;

    /* Manually toggle the chip-select line (active low). */
    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Failed to assert CS line: %s\n", strerror(errno));
        return -1;
    }

    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);

    /* Deassert chip-select regardless of transfer result. */
    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Failed to deassert CS line: %s\n", strerror(errno));
        return -1;
    }

    if (ret < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

int main(void)
{
    int spi_fd = -1;
    FILE *log_file = NULL;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *cs_line = NULL;
    int ret = EXIT_FAILURE;

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Open SPI device --- */
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        goto cleanup;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        goto cleanup;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Open GPIO chip and request CS line --- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open(%s) failed: %s\n", GPIO_CHIP, strerror(errno));
        goto cleanup;
    }

    cs_line = gpiod_chip_get_line(chip, CS_LINE_OFFSET);
    if (!cs_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n", CS_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(cs_line, "mcp3008-cs", 1) < 0) {
        fprintf(stderr, "gpiod_line_request_output failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Open log file --- */
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    /* Write CSV header */
    if (fprintf(log_file, "timestamp_ns|raw_adc_value\n") < 0) {
        fprintf(stderr, "Failed to write header: %s\n", strerror(errno));
        goto cleanup;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Sampling MCP3008 channel 0 at 1 kHz. Press Ctrl+C to stop.\n");

    struct timespec next_ts;
    if (clock_gettime(CLOCK_MONOTONIC_RAW, &next_ts) < 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        goto cleanup;
    }

    while (g_running) {
        int adc = mcp3008_read(spi_fd, cs_line, 0);
        if (adc < 0) {
            fprintf(stderr, "ADC read error, continuing...\n");
            /* Still flush so the error is visible in the log. */
            fflush(log_file);
            continue;
        }

        struct timespec now;
        if (clock_gettime(CLOCK_MONOTONIC_RAW, &now) < 0) {
            fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
            break;
        }

        long long ts_ns = (long long)now.tv_sec * 1000000000LL + now.tv_nsec;

        if (fprintf(log_file, "%lld|%d\n", ts_ns, adc) < 0) {
            fprintf(stderr, "fprintf failed: %s\n", strerror(errno));
            break;
        }
        if (fflush(log_file) != 0) {
            fprintf(stderr, "fflush failed: %s\n", strerror(errno));
            break;
        }

        /* Sleep until next 1 ms boundary */
        next_ts.tv_nsec += SAMPLE_PERIOD_NS;
        if (next_ts.tv_nsec >= 1000000000L) {
            next_ts.tv_sec += 1;
            next_ts.tv_nsec -= 1000000000L;
        }

        struct timespec req = next_ts;
        while (g_running) {
            struct timespec rem;
            int r = nanosleep(&req, &rem);
            if (r < 0) {
                if (errno == EINTR) {
                    /* Signal received during sleep — check g_running. */
                    continue;
                }
                fprintf(stderr, "nanosleep failed: %s\n", strerror(errno));
                goto cleanup;
            }
            req = rem;
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    printf("\nShutting down...\n");

    if (log_file) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        }
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }

    return ret;
}

