#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

/*
 * Raspberry Pi 4 Model B - Propane Leak Detector
 * Sensor: Honeywell MICROpeL MP-741 (analog output)
 * ADC:    MCP3008 on SPI0 CE0 (GPIO 8), channel 0
 * Library: pigpio (modern, actively maintained)
 *
 * NOTE: The MP-741 is a factory-calibrated analog sensor.
 *       The PPM calculation below is a placeholder; a
 *       calibrated load resistor and a known reference
 *       voltage are required for accurate PPM measurement.
 */

#define SPI_CHANNEL    0          /* CE0 on SPI0 */
#define SPI_BAUD       1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 channel 0 */
#define REFERENCE_VOLTAGE 3.3     /* Raspberry Pi 3.3 V rail */
#define MAX_PPM        10000.0    /* Placeholder PPM ceiling */
#define RETRY_DELAY_US 100000     /* 100 ms back-off on error */
#define SAMPLE_PERIOD_US 1000000  /* 1 second between samples */
#define LOG_FILE       "gas_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (Ctrl + C)                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a single-ended sample from the MCP3008                         */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        fprintf(stderr, "Error: null output pointer\n");
