/*
 * ADXL335 accelerometer reader via MCP3008 ADC on Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SCLK, Pin 23)
 *   MCP3008 DOUT -> GPIO9  (MISO,  Pin 21)
 *   MCP3008 DIN  -> GPIO10 (MOSI,  Pin 19)
 *   MCP3008 CS   -> GPIO8  (CE0,    Pin 24)
 *   MCP3008 CH0  -> ADXL335 X_OUT
 *   MCP3008 CH1  -> ADXL335 Y_OUT
 *   MCP3008 CH2  -> ADXL335 Z_OUT
 *
 * Build: gcc -O2 -Wall -o adxl335_mcp3008 adxl335_mcp3008.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* CE0 on GPIO8 */
#define SPI_SPEED_HZ   1000000    /* 1 MHz — well within MCP3008 spec */
#define SPI_FLAGS      0          /* Mode 0, active-low CS, 8-bit words */

#define ADC_VREF       3.3f       /* MCP3008 reference voltage */
#define ADC_MAX        1023       /* 10-bit ADC */

#define SAMPLE_RATE_HZ 10
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

/* Kalman filter parameters */
#define Q_ANGLE_ACCEL  0.001f     /* Process noise covariance (rad/s) */
#define R_MEASUREMENT  0.01f      /* Measurement noise covariance (g/s) */

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- MCP3008 helpers ---------------------------- */

/*
 * Read a single-ended channel (0-7) from the MCP3008.
 * Returns the 10-bit ADC code (0-1023) or -1 on SPI error.
 */
static int mcp3008_read(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   Byte 0: 0x01                       (start bit)
     *   Byte 1: (0x08 | channel) << 4      (single-ended + channel, upper nibble)
     *   Byte 2: 0x00                       (clock out remaining bits)
     *
     * Response:
     *   rx[0] = don't care
     *   rx[1] = [null bit][b9 b8] in the two LSBs
     *   rx[2] = b7..b0
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }

    int adc = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc;
}

/* ----------------------------- Kalman filter ----------------------------- */

/*
 * Kalman filter state for a 1-D acceleration axis.
 */
typedef struct {
    float angle;       /* estimated angle (radians) */
    float rate;        /* estimated angular rate (rad/s) */
    float bias;        /* bias estimate */
} kalman_state_t;

static kalman_state_t kalman_init(void)
{
    kalman_state_t s;
    s.angle      = 0.0f;
    s.rate       = 0.0f;
    s.bias       = 0.0f;
    return s;
}

static void kalman_update(kalman_state_t *s, float measurement)
{
    /* Predict */
    s->angle += s->rate * (1.0f - Q_ANGLE_ACCEL) * (1.0f / SAMPLE_RATE_HZ);
    s->rate  += (measurement - s->angle) * Q_ANGLE_ACCEL * (1.0f / SAMPLE_RATE_HZ);

    /* Update */
    float y = measurement - s->angle;
    float p = Q_ANGLE_ACCEL + (R_MEASUREMENT * R_MEASUREMENT);
    float k = s->rate / p;
    s->angle += k * y;
    s->rate  += k * y;
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI bus --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED_HZ, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Verify ADC channels read --- */
    for (int ch = 0; ch < 3; ch++) {
        int v = mcp3008_read(ch);
        if (v < 0) {
            fprintf(stderr, "ADC channel %d unreadable — sensor absent or wiring fault\n", ch);
            spiClose(g_spi_handle);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        printf("ADC channel %d: %d\n", ch, v);
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- Kalman state --- */
    kalman_state_t kx = kalman_init();
    kalman_state_t ky = kalman_init();
    kalman_state_t kz = kalman_init();

    /* --- Main loop --- */
    while (g_running) {
        int x = mcp3008_read(0);
        int y = mcp3008_read(1);
        int z = mcp3008_read(2);

        if (x < 0 || y < 0 || z < 0) {
            fprintf(stderr, "SPI read error — skipping sample\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /* Convert 10-bit ADC to g (3.3 V reference, ±2 g range) */
        float gx = ((float)x / (float)ADC_MAX) * (2.0f / 3.3f) * 9.80665f;
        float gy = ((float)y / (float)ADC_MAX) * (2.0f / 3.3f) * 9.80665f;
        float gz = ((float)z / (float)ADC_MAX) * (2.0f / 3.3f) * 9.80665f;

        /* Apply Kalman filter */
        kalman_update(&kx, gx);
        kalman_update(&ky, gy);
        kalman_update(&kz, gz);

        /* Print smoothed values at 10 Hz */
        printf("X: %+.3f g  Y: %+.3f g  Z: %+.3f g\n",
               kx.angle, ky.angle, kz.angle);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Cleanup --- */
    spiClose(g_spi_handle);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

