            return EXIT_FAILURE;
        }
        printf("ADC channel %d: %d\n", ch, v);
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- Kalman state --- */
    kalman_state_t kx = kalman_init();
    kalman_state_t ky = kalman_init();
    kalman_state_t kz = kalman_init();

    /* --- Main loop --- */
    while (g_running) {
        int x = mcp3008_read(0);
        int y = mcp3008_read(1);
        int z = mcp3008_read(2);

        if (x < 0 || y < 0 || z < 0) {
            fprintf(stderr, "SPI read error — skipping sample\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /* Convert 10-bit ADC to g (3.3 V reference, ±2 g range) */
        float gx = ((float)x / (float)ADC_MAX) * (2.0f / 3.3f) * 9.80665f;
        float gy = ((float)y / (float)ADC_MAX) * (2.0f / 3.3f) * 9.80665f;
        float gz = ((float)z / (float)ADC_MAX) * (2.0f / 3.3f) * 9.80665f;

        /* Apply Kalman filter */
        kalman_update(&kx, gx);
        kalman_update(&ky, gy);
        kalman_update(&kz, gz);

        /* Print smoothed values at 10 Hz */
        printf("X: %+.3f g  Y: %+.3f g  Z: %+.3f g\n",
               kx.angle, ky.angle, kz.angle);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Cleanup --- */
    spiClose(g_spi_handle);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

