#include <pigpio.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27

#define VOLTAGE_HIGH 3.3
#define VOLTAGE_LOW  0.0
#define ADC_MAX      255.0
#define ADC_RESOLUTION 1000.0
#define MT_PER_VOLT  100.0

#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_sensor(int pin, int *out_state) {
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Warning: gpioRead failed on pin %d (rc=%d)\n", pin, v);
        return -1;
    }
    *out_state = v;
    return 0;
}

static double voltage_to_magnetic_field(double voltage) {
    return (voltage - VOLTAGE_LOW) * MT_PER_VOLT;
}

static int log_data(double f1, double f2, double f3, FILE *fp) {
    if (fprintf(fp, "%.2f,%.2f,%.2f\n", f1, f2, f3) < 0) {
        fprintf(stderr, "Warning: fprintf to log file failed\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Warning: fflush failed on log file\n");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int pins[3] = {SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN};
    for (int i = 0; i < 3; i++) {
        if (gpioSetMode(pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed on pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("DRV5055VA Hall-Effect sensor logging started.\n");
    printf("  Sensor 1: GPIO%d\n", SENSOR1_PIN);
    printf("  Sensor 2: GPIO%d\n", SENSOR2_PIN);
    printf("  Sensor 3: GPIO%d\n", SENSOR3_PIN);
    printf("  Log file: %s\n", LOG_FILE);
    printf("  Press Ctrl+C to stop.\n");

    while (program_running) {
        int s1, s2, s3;
        int rc1 = read_sensor(SENSOR1_PIN, &s1);
        int rc2 = read_sensor(SENSOR2_PIN, &s2);
        int rc3 = read_sensor(SENSOR3_PIN, &s3);

        if (rc1 != 0 || rc2 != 0 || rc3 != 0) {
            fprintf(stderr, "Warning: GPIO read error, skipping this sample\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double v1 = (s1 == 1) ? VOLTAGE_HIGH : VOLTAGE_LOW;
        double v2 = (s2 == 1) ? VOLTAGE_HIGH : VOLTAGE_LOW;
        double v3 = (s3 == 1) ? VOLTAGE_HIGH : VOLTAGE_LOW;

        double a1 = (v1 - VOLTAGE_LOW) / ADC_RESOLUTION;
        double a2 = (v2 - VOLTAGE_LOW) / ADC_RESOLUTION;
        double a3 = (v3 - VOLTAGE_LOW) / ADC_RESOLUTION;

        double f1 = a1 * MT_PER_VOLT;
        double f2 = a2 * MT_PER_VOLT;
        double f3 = a3 * MT_PER_VOLT;

        if (f1 < -100.0 || f1 > 100.0 ||
            f2 < -100.0 || f2 > 100.0 ||
            f3 < -100.0 || f3 > 100.0) {
            fprintf(stderr, "Warning: magnetic field out of range (s1=%.2f, s2=%.2f, s3=%.2f)\n",
                    f1, f2, f3);
        }

        if (log_data(f1, f2, f3, fp) != 0) {
            fprintf(stderr, "Warning: failed to log data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (fclose(fp) != 0) {
        perror("Warning: fclose failed on log file");
    }
    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

