/*
 * Soil Moisture Monitor and Pump Controller
 * Board:  Raspberry Pi 4 Model B
 * ADC:    MCP3008 on SPI0 (CE0), 500 kHz, mode 0
 * Sensor: Soil moisture sensor on MCP3008 channel 0 (single-ended)
 * Pump:   Relay on GPIO17 (BCM), active-high
 *
 * Build:  gcc -O2 -Wall -Wextra -o watering watering.c -lpigpio -lrt
 * Run:    sudo ./watering
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* SPI0 CE0 (BCM 8)                          */
#define SPI_BAUD       500000     /* 500 kHz                                   */
#define SPI_FLAGS      0          /* mode 0, active-low CE                     */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0            */
#define PUMP_GPIO      17         /* BCM 17                                   */
#define MOISTURE_THRESHOLD 30     /* percent                                  */
#define SAMPLE_INTERVAL 60        /* seconds                                  */
#define LOG_FILE       "watering.log"

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_pump_state = 0;       /* 0 = off, 1 = on                          */
static FILE *g_log = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static int  read_mcp3008(int channel);
static int  adc_to_moisture_percent(int adc_value);
static void control_pump(int moisture_percent);
static void log_event(const char *msg);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- MCP3008 read ------------------------------ */
/*
 * MCP3008 single-ended read sequence (3 bytes):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care)
 *   tx[2] = 0x00                       (clock out low 2 bits)
 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2]
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        log_event("Invalid ADC channel requested");
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(SPI_CHANNEL, tx, rx, 3);
    if (bytes != 3) {
        log_event("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

/* ----------------------------- Moisture % -------------------------------- */
static int adc_to_moisture_percent(int adc_value)
{
    if (adc_value < 0)   adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;
    return (int)(((float)adc_value / 1023.0f) * 100.0f);
}

/* ----------------------------- Pump control ------------------------------ */
static void control_pump(int moisture_percent)
{
    if (moisture_percent < MOISTURE_THRESHOLD && !g_pump_state) {
        if (gpioWrite(PUMP_GPIO, 1) == 0) {
            g_pump_state = 1;
            log_event("Pump turned ON");
        } else {
            log_event("Failed to turn pump ON (gpioWrite returned non-zero)");
        }
    } else if (moisture_percent >= MOISTURE_THRESHOLD && g_pump_state) {
        if (gpioWrite(PUMP_GPIO, 0) == 0) {
            g_pump_state = 0;
            log_event("Pump turned OFF");
        } else {
            log_event("Failed to turn pump OFF (gpioWrite returned non-zero)");
        }
    }
}

/* ----------------------------- Logging ----------------------------------- */
static void log_event(const char *msg)
{
    if (!g_log) return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log, "[%s] %s\n", ts, msg);
    fflush(g_log);
}

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_pump_state) {
        gpioWrite(PUMP_GPIO, 0);
        g_pump_state = 0;
        log_event("Pump turned OFF during shutdown");
    }
    if (g_log) {
        log_event("Program terminated");
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- pump GPIO --- */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);   /* pump off at startup */

    /* --- SPI --- */
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel %d, %d baud): %s\n",
                SPI_CHANNEL, SPI_BAUD, pigpio_error(spi_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- log file --- */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("fopen(" LOG_FILE ")");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("Program started");

    /* --- signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- main loop --- */
    while (g_running) {
        int adc = read_mcp3008(ADC_CHANNEL);
        if (adc < 0) {
            log_event("ADC read failed; skipping cycle");
        } else {
            int pct = adc_to_moisture_percent(adc);
            control_pump(pct);
            char msg[128];
            snprintf(msg, sizeof(msg), "ADC=%d  Moisture=%d%%", adc, pct);
            log_event(msg);
        }

        /* sleep but wake early on signal */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    cleanup();
    spiClose(spi_handle);
    return EXIT_SUCCESS;
}

