        goto cleanup;
    }

    /* Write header if file is empty */
    if (ftell(fp) == 0) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            fprintf(fp, "channel%d", i);
            if (i < NUM_CHANNELS - 1) {
                fprintf(fp, ",");
            }
        }
        fprintf(fp, "\n");
        fflush(fp);
    }

    /* --- Main loop --- */
    while (g_running) {
        int values[NUM_CHANNELS];
        int error = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int v = read_mcp3008(fd, i);
            if (v < 0) {
                fprintf(stderr, "Error reading channel %d\n", i);
                error = 1;
                break;
            }
            values[i] = v;
        }

        if (!error) {
            for (int i = 0; i < NUM_CHANNELS; i++) {
                if (fprintf(fp, "%d", values[i]) < 0) {
                    fprintf(stderr, "Error writing to CSV: %s\n", strerror(errno));
                    error = 1;
                    break;
                }
                if (i < NUM_CHANNELS - 1) {
                    fprintf(fp, ",");
                }
            }
            if (!error) {
                fprintf(fp, "\n");
                fflush(fp);
            }
        }

        /* Sleep 1 second, but wake early if interrupted */
        for (int i = 0; i < 10 && g_running; i++) {
