#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define MQTT_BROKER_ADDRESS "tcp://mqtt.eclipseprojects.io:1883"
#define MQTT_CLIENT_ID     "rpi_led_control"
#define MQTT_TOPIC         "home/led_control"
#define LED_GPIO           17
#define MAX_RECONNECT_DELAY 60

static volatile sig_atomic_t g_running = 1;
static MQTTClient g_mqtt_client;

/* ------------------------------------------------------------------ */
/* Logging helper                                                      */
/* ------------------------------------------------------------------ */
static void log_error(const char *message)
{
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s\n", ts, message);
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* JSON parsing                                                        */
/* ------------------------------------------------------------------ */
static int parse_json_led_state(const char *json_string, int *led_state)
{
    cJSON *root = cJSON_Parse(json_string);
    if (root == NULL) {
        log_error("Error parsing JSON: invalid character");
        return -1;
    }

    cJSON *item = cJSON_GetObjectItemCaseSensitive(root, "led_state");
    if (item == NULL) {
        log_error("Error: 'led_state' key not found in JSON");
        cJSON_Delete(root);
        return -1;
    }

    if (!cJSON_IsBool(item)) {
        log_error("Error: 'led_state' value is not a boolean");
        cJSON_Delete(root);
        return -1;
    }

    *led_state = (int)item->valued.b;
    cJSON_Delete(root);
    return 0;
}

/* ------------------------------------------------------------------ */
/* MQTT callbacks                                                      */
/* ------------------------------------------------------------------ */
static void message_arrived(void *context, char *topicName,
                            int topicLen, MQTTClient_message *message)
{
    (void)context;
    (void)topicLen;

    if (message == NULL || message->payload == NULL || message->payloadlen <= 0) {
        log_error("Error: received empty MQTT message");
        MQTTClient_freeMessage(&message);
        MQTTClient_free(topicName);
        return;
    }

    char *payload = malloc(message->payloadlen + 1);
    if (payload == NULL) {
        log_error("Error: memory allocation failed for payload");
        MQTTClient_freeMessage(&message);
        MQTTClient_free(topicName);
        return;
    }
    memcpy(payload, message->payload, message->payloadlen);
    payload[message->payloadlen] = '\0';
    MQTTClient_freeMessage(&message);
    MQTTClient_free(topicName);

    int led_state = 0;
    if (parse_json_led_state(payload, &led_state) == 0) {
        if (gpioWrite(LED_GPIO, led_state) != 0) {
            log_error("Error: failed to write LED GPIO");
        } else {
            printf("LED state updated to: %s\n", led_state ? "ON" : "OFF");
        }
    } else {
        log_error("Error: failed to parse JSON payload");
    }
    free(payload);
}

static void connection_lost(void *context, char *cause)
{
    (void)context;
    if (cause != NULL) {
        fprintf(stderr, "MQTT connection lost: %s\n", cause);
    } else {
        fprintf(stderr, "MQTT connection lost\n");
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    MQTTClient_disconnect(g_mqtt_client, 1000);
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    MQTTClient_destroy(&g_mqtt_client);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        log_error("Error: pigpio initialisation failed");
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    /* --- MQTT client creation --- */
    int rc = MQTTClient_create(&g_mqtt_client, MQTT_BROKER_ADDRESS,
                               MQTT_CLIENT_ID,
                               MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create MQTT client: %d\n", rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    /* --- MQTT callback registration --- */
    MQTTClient_setCallbacks(g_mqtt_client, NULL, connection_lost,
                            message_arrived, NULL);

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- Connect to MQTT broker --- */
    rc = MQTTClient_connect(g_mqtt_client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker: %d\n", rc);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Subscribe to topic --- */
    rc = MQTTClient_subscribe(g_mqtt_client, MQTT_TOPIC, 0);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to subscribe to topic: %d\n", rc);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Connected to MQTT broker and subscribed to %s\n", MQTT_TOPIC);

    /* --- Main loop --- */
    while (g_running) {
        sleep(1);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

