#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN    18
#define POLL_DELAY_US    100000   /* 100 ms */
#define ALARM_HOLD_US    1000000  /* 1 s   */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    int ret;

    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", ret);
        return EXIT_FAILURE;
    }

    /* --- Configure sound sensor pin as input --- */
    ret = gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input (code %d).\n",
                SOUND_SENSOR_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure alarm LED pin as output --- */
    ret = gpioSetMode(ALARM_LED_PIN, PI_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output (code %d).\n",
                ALARM_LED_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Ensure LED is off at start --- */
    ret = gpioWrite(ALARM_LED_PIN, 0);
    if (ret != 0) {
