#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define GPIO_CHIP       "/dev/gpiochip0"
#define GPIO_LINE       17
#define CONSUMER        "vibration-monitor"
#define LOG_FILE        "/var/log/vibration_shutdown.log"
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int log_message(const char *message)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s: %s\n", ts, message);
    } else {
        fprintf(fp, "<unknown-time>: %s\n", message);
    }

    if (fclose(fp) != 0) {
        perror("fclose(" LOG_FILE ")");
        return -1;
    }
    return 0;
}

static int shutdown_system(void)
{
    int ret = system("sudo shutdown -h now");
    if (ret == -1) {
        perror("system()");
        return -1;
    }
    if (!WIFEXITED(ret) || WEXITSTATUS(ret) != 0) {
        fprintf(stderr, "shutdown command did not succeed (exit status %d)\n",
                WIFEXITED(ret) ? WEXITSTATUS(ret) : -1);
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    int chip_fd = open(GPIO_CHIP, O_RDWR);
    if (chip_fd < 0) {
        perror("open(" GPIO_CHIP ")");
        return EXIT_FAILURE;
    }

    struct gpiofd_line_request req;
    memset(&req, 0, sizeof(req));
    req.consumer = CONSUMER;
    req.request_type = GPIOD_LINE_REQUEST_EVENT_FALLING_EDGE;
    req.flags = 0;

    if (ioctl(chip_fd, GPIOD_LINE_REQUEST, &req) < 0) {
        perror("ioctl(GPIOD_LINE_REQUEST)");
        close(chip_fd);
        return EXIT_FAILURE;
    }

    printf("Vibration monitoring started on GPIO%d (BCM). Press Ctrl+C to exit.\n",
           GPIO_LINE);

    while (program_running) {
        struct gpiofd_line_event event;
        int ret = gpiofd_line_event_wait(chip_fd, &(struct timespec){
            .tv_sec  = POLL_TIMEOUT_MS / 1000,
            .tv_nsec = (POLL_TIMEOUT_MS % 1000) * 1000000L
        });

        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("gpiofd_line_event_wait");
            break;
        }
        if (ret == 0) {
            continue;
        }

        if (gpiofd_line_event_read(chip_fd, &event) < 0) {
            perror("gpiofd_line_event_read");
            continue;
        }

        if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            char message[128];
            snprintf(message, sizeof(message),
                     "Vibration detected on GPIO%d (BCM). Initiating shutdown.",
                     GPIO_LINE);

            if (log_message(message) < 0) {
                fprintf(stderr, "Failed to log vibration event.\n");
            } else {
                printf("%s\n", message);
            }

            if (shutdown_system() < 0) {
                fprintf(stderr, "Shutdown command failed. Continuing to monitor.\n");
            }
            break;
        }
    }

    if (gpiofd_line_release(chip_fd, GPIO_LINE) < 0) {
        perror("gpiofd_line_release");
    }
    if (close(chip_fd) < 0) {
        perror("close");
    }

    printf("Vibration monitoring stopped.\n");
    return EXIT_SUCCESS;
}

