#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_REG_CHIP_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_CALIB_00 0x88
#define BMP280_CHIP_ID 0x58
#define LOG_FILE "altitude_log.txt"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

static bmp280_calib_data g_calib;
static int32_t g_t_fine;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_calibration_data(int handle, bmp280_calib_data *cal) {
    uint8_t data[24];
    if (i2cReadI2CBlockData(handle, BMP280_REG_CALIB_00, (char *)data, 24) != 24) {
        fprintf(stderr, "Error: Failed to read 24 bytes of calibration data from 0x88.\n");
        return -1;
    }
    cal->dig_T1 = (uint16_t)(data[0] | (data[1] << 8));
    cal->dig_T2 = (int16_t)(data[2] | (data[3] << 8));
    cal->dig_T3 = (int16_t)(data[4] | (data[5] << 8));
    cal->dig_P1 = (uint16_t)(data[6] | (data[7] << 8));
    cal->dig_P2 = (int16_t)(data[8] | (data[9] << 8));
    cal->dig_P3 = (int16_t)(data[10] | (data[11] << 8));
    cal->dig_P4 = (int16_t)(data[12] | (data[13] << 8));
    cal->dig_P5 = (int16_t)(data[14] | (data[15] << 8));
    cal->dig_P6 = (int16_t)(data[16] | (data[17] << 8));
    cal->dig_P7 = (int16_t)(data[18] | (data[19] << 8));
    cal->dig_P8 = (int16_t)(data[20] | (data[21] << 8));
    cal->dig_P9 = (int16_t)(data[22] | (data[23] << 8));
    return 0;
}

static int read_raw_data(int handle, int32_t *raw_press, int32_t *raw_temp) {
    uint8_t data[6];
    if (i2cReadI2CBlockData(handle, BMP280_REG_PRESS_MSB, (char *)data, 6) != 6) {
        fprintf(stderr, "Error: Failed to read 6 bytes of raw data from 0xF7.\n");
        return -1;
    }
    *raw_press = (int32_t)((data[0] << 12) | (data[1] << 4) | (data[2] >> 4));
    *raw_temp = (int32_t)((data[3] << 12) | (data[4] << 4) | (data[5] >> 4));
    return 0;
}

static int32_t compensate_temperature(int32_t raw_temp) {
    int32_t var1, var2;
    var1 = ((((raw_temp >> 3) - ((int32_t)g_calib.dig_T1 << 1))) * ((int32_t)g_calib.dig_T2)) >> 11;
    var2 = (((((raw_temp >> 4) - ((int32_t)g_calib.dig_T1)) * ((raw_temp >> 4) - ((int32_t)g_calib.dig_T1))) >> 12) * ((int32_t)g_calib.dig_T3)) >> 14;
    g_t_fine = var1 + var2;
    return (g_t_fine * 5 + 128) >> 8;
}

static uint32_t compensate_pressure(int32_t raw_press) {
    int32_t var1, var2;
    uint32_t p;
    var1 = ((int32_t)g_t_fine >> 1) - 64000;
    var2 = (((var1 >> 2) * (var1 >> 2)) >> 11) * ((int32_t)g_calib.dig_P6);
    var2 = var2 + ((var1 * ((int32_t)g_calib.dig_P5)) << 1);
    var2 = (var2 >> 2) + (((int32_t)g_calib.dig_P4) << 16);
    var1 = (((g_calib.dig_P3 * (((var1 >> 2) * (var1 >> 2)) >> 13)) >> 3) + ((((int32_t)g_calib.dig_P2) * var1) >> 1)) >> 18;
    var1 = ((((32768 + var1)) * ((int32_t)g_calib.dig_P1)) >> 15);
    if (var1 == 0) return 0;
    p = (((uint32_t)(((1048576) - raw_press) - (var2 >> 12))) * 3125);
    if (p < 0x80000000) p = (p << 1) / ((uint32_t)var1);
    else p = (p / (uint32_t)var1) * 2;
    var1 = (((int32_t)g_calib.dig_P9) * ((int32_t)(((p >> 3) * (p >> 3)) >> 13))) >> 12;
    var2 = (((int32_t)(p >> 2)) * ((int32_t)g_calib.dig_P8)) >> 13;
    p = (uint32_t)((int32_t)p + ((var1 + var2 + g_calib.dig_P7) >> 4));
    return p;
}

static double calculate_altitude(uint32_t pressure_pa) {
    return 44330.0 * (1.0 - pow((double)pressure_pa / 101325.0, 0.1903));
}

static int log_data(FILE *fp, double altitude) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return -1;
    }
    if (fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d,%.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, altitude) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed.\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error: fflush failed.\n");
        return -1;
    }
    return 0;
}

static int init_bmp280(int handle) {
    int chip_id = i2cReadByteData(handle, BMP280_REG_CHIP_ID);
    if (chip_id < 0) {
        fprintf(stderr, "Error: Failed to read chip ID from I2C.\n");
        return -1;
    }
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x%02X). Sensor not present or wrong part.\n", chip_id, BMP280_CHIP_ID);
        return -1;
    }
    if (i2cWriteByteData(handle, BMP280_REG_RESET, 0xB6) < 0) {
        fprintf(stderr, "Error: Failed to reset BMP280.\n");
        return -1;
    }
    gpioDelay(10000);
    if (read_calibration_data(handle, &g_calib) != 0) return -1;
    if (i2cWriteByteData(handle, BMP280_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write config register.\n");
        return -1;
    }
    if (i2cWriteByteData(handle, BMP280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error: Failed to write control register.\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at address 0x%02X (code %d).\n", BMP280_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_bmp280(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: BMP280 initialisation failed.\n");
        cleanup();
        return 1;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("BMP280 initialised. Logging to %s every %d seconds. Press Ctrl+C to stop.\n", LOG_FILE, SAMPLE_INTERVAL_SEC);

    while (g_running) {
        int32_t raw_press, raw_temp;
        if (read_raw_data(g_i2c_handle, &raw_press, &raw_temp) != 0) {
            fprintf(stderr, "Warning: Failed to read raw data, retrying in %d seconds.\n", SAMPLE_INTERVAL_SEC);
            gpioDelay(SAMPLE_INTERVAL_SEC * 1000000);
            continue;
        }

        int32_t temp_int = compensate_temperature(raw_temp);
        uint32_t press_pa = compensate_pressure(raw_press);
        double altitude = calculate_altitude(press_pa);

        if (log_data(g_log_file, altitude) != 0) {
            fprintf(stderr, "Warning: Failed to log data.\n");
        }

        printf("Raw Pressure: %d Pa, Raw Temperature: %d, Altitude: %.2f m\n", raw_press, temp_int, altitude);

