}

static double calculate_altitude(uint32_t pressure_pa) {
    return 44330.0 * (1.0 - pow((double)pressure_pa / 101325.0, 0.1903));
}

static int log_data(FILE *fp, double altitude) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return -1;
    }
    if (fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d,%.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, altitude) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed.\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error: fflush failed.\n");
        return -1;
    }
    return 0;
}

static int init_bmp280(int handle) {
    int chip_id = i2cReadByteData(handle, BMP280_REG_CHIP_ID);
    if (chip_id < 0) {
        fprintf(stderr, "Error: Failed to read chip ID from I2C.\n");
        return -1;
    }
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x%02X). Sensor not present or wrong part.\n", chip_id, BMP280_CHIP_ID);
        return -1;
    }
    if (i2cWriteByteData(handle, BMP280_REG_RESET, 0xB6) < 0) {
        fprintf(stderr, "Error: Failed to reset BMP280.\n");
        return -1;
    }
    gpioDelay(10000);
    if (read_calibration_data(handle, &g_calib) != 0) return -1;
    if (i2cWriteByteData(handle, BMP280_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write config register.\n");
        return -1;
    }
    if (i2cWriteByteData(handle, BMP280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error: Failed to write control register.\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at address 0x%02X (code %d).\n", BMP280_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_bmp280(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: BMP280 initialisation failed.\n");
        cleanup();
        return 1;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("BMP280 initialised. Logging to %s every %d seconds. Press Ctrl+C to stop.\n", LOG_FILE, SAMPLE_INTERVAL_SEC);

    while (g_running) {
        int32_t raw_press, raw_temp;
        if (read_raw_data(g_i2c_handle, &raw_press, &raw_temp) != 0) {
            fprintf(stderr, "Warning: Failed to read raw data, retrying in %d seconds.\n", SAMPLE_INTERVAL_SEC);
            gpioDelay(SAMPLE_INTERVAL_SEC * 1000000);
            continue;
        }

        int32_t temp_int = compensate_temperature(raw_temp);
        uint32_t press_pa = compensate_pressure(raw_press);
        double altitude = calculate_altitude(press_pa);

        if (log_data(g_log_file, altitude) != 0) {
            fprintf(stderr, "Warning: Failed to log data.\n");
        }

        printf("Raw Pressure: %d Pa, Raw Temperature: %d, Altitude: %.2f m\n", raw_press, temp_int, altitude);

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return 0;
}

