#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

#define NUM_RELAYS 4

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_mode(unsigned pin, unsigned mode) {
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %u\n", pin);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level) {
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Error: gpioWrite failed for pin %u\n", pin);
        return -1;
    }
    return 0;
}

static void all_relays_off(void) {
    int pins[NUM_RELAYS] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (int i = 0; i < NUM_RELAYS; i++) {
        safe_write(pins[i], 0);
    }
}

int main(void) {
    int pins[NUM_RELAYS] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (safe_set_mode(pins[i], PI_OUTPUT) != 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    all_relays_off();

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handler\n");
        all_relays_off();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        for (int i = 0; i < NUM_RELAYS && running; i++) {
            if (safe_write(pins[i], 1) != 0) {
                break;
            }
            printf("Relay %d (BCM %d) ON\n", i + 1, pins[i]);
            sleep(1);
            if (!running) break;
            if (safe_write(pins[i], 0) != 0) {
                break;
            }
            printf("Relay %d (BCM %d) OFF\n", i + 1, pins[i]);
            sleep(1);
        }
    }

    all_relays_off();
    gpioTerminate();
    return EXIT_SUCCESS;
}

