/*
 * Clap Detection System using MAX9814 Electret Microphone Amplifier
 * Board: Raspberry Pi 4 Model B
 *
 * Wiring:
 *   MAX9814 OUT  -> BCM GPIO26 (analog input, ADC sampling)
 *   MAX9814 GAIN -> Left/Right channel select (set to Left for single-ended)
 *   MAX9814 VDD  -> 3.3V
 *   MAX9814 GND  -> GND
 *   LED Anode    -> BCM GPIO16 (with 330 ohm resistor in series)
 *   LED Cathode  -> GND
 *
 * Build: gcc -Wall -Wextra -O2 -o clap_detect clap_detect.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define ADC_PIN        26
#define LED_PIN        16

#define DEBOUNCE_MS    50
#define LED_ON_MS      500
#define SAMPLE_US      1000   /* 1 ms sampling interval */
#define ADC_REF_US     3300   /* 3.3V reference, 10-bit ADC */
#define ADC_MAX        1023

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Bit-banged 10-bit ADC using pigpio.
 * MAX9814 output is biased at ~1.65V; subtract 1.65V from the sampled
 * voltage to get an ADC code centered around 0.
 */
static int read_adc(void)
{
    int value = 0;

    if (gpioSetMode(ADC_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ADC pin %d as input.\n", ADC_PIN);
        return -1;
    }

    /* Allow the pin to settle (MAX9814 output is active high) */
    gpioDelay(1000);

    /* Sample for 1 ms (1000 us) */
    gpioDelay(SAMPLE_US);

    if (gpioSetMode(ADC_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set ADC pin %d as output.\n", ADC_PIN);
        return -1;
    }

    /* Read the state of the pin (active high) */
    value = gpioRead(ADC_PIN);
    if (value < 0) {
        fprintf(stderr, "Error: failed to read ADC pin %d.\n", ADC_PIN);
        return -1;
    }

    return value;
}

static void trigger_led(void)
{
    if (gpioWrite(LED_PIN, 1) < 0) {
        fprintf(stderr, "Warning: failed to turn on LED.\n");
        return;
    }
    gpioDelay(LED_ON_MS * 1000);
    if (gpioWrite(LED_PIN, 0) < 0) {
        fprintf(stderr, "Warning: failed to turn off LED.\n");
    }
}

static void log_timestamp(void)
{
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Warning: localtime failed.\n");
        return;
    }

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] Clap detected!\n", buffer);
    fflush(stdout);
}

int main(void)
{
    int adc_value;
    int last_adc = -1;
    uint32_t last_clap_ms = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set LED pin %d as output.\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: failed to set SIGINT handler.\n");
    }

    printf("Clap detection system started. Press Ctrl+C to exit.\n");
    printf("Sampling MAX9814 on BCM GPIO%d, LED on BCM GPIO%d.\n", ADC_PIN, LED_PIN);
    fflush(stdout);

    while (g_running) {
        adc_value = read_adc();
        if (adc_value < 0) {
            /* Sensor error or bus error: wait and retry */
            gpioDelay(10000);
            continue;
        }

        /* Detect rising edge (clap event) */
        if (adc_value > last_adc) {
            uint32_t now_ms = gpioTick() / 1000;
            if ((now_ms - last_clap_ms) >= DEBOUNCE_MS) {
                trigger_led();
                log_timestamp();
                last_clap_ms = now_ms;
            }
        }

        last_adc = adc_value;
        gpioDelay(SAMPLE_US);
    }

    /* Cleanup */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");

    return EXIT_SUCCESS;
}

