        adc_value = read_adc();
        if (adc_value < 0) {
            /* Sensor error or bus error: wait and retry */
            gpioDelay(10000);
            continue;
        }

        /* Detect rising edge (clap event) */
        if (adc_value > last_adc) {
            uint32_t now_ms = gpioTick() / 1000;
            if ((now_ms - last_clap_ms) >= DEBOUNCE_MS) {
                trigger_led();
                log_timestamp();
                last_clap_ms = now_ms;
            }
        }

        last_adc = adc_value;
        gpioDelay(SAMPLE_US);
    }

    /* Cleanup */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");

    return EXIT_SUCCESS;
}

