#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0
#define ADC_CHANNEL     0
#define ADC_MAX         1023
#define ADC_VREF        3.3f
#define LOG_FILE        "magnetic_log.txt"
#define SAMPLE_DELAY_US 500000

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int setup_signals(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int spi_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("open(SPI device)");
        return -1;
    }
    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(fd);
        return -1;
    }
    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(fd);
        return -1;
    }
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(fd);
        return -1;
    }
    return fd;
}

static int mcp3008_read(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }
    uint8_t tx[3] = {
        0x01,
        (uint8_t)((channel & 0x07) << 4),
        0x00
    };
    uint8_t rx[3] = {0};
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    tr.cs_change = 0;
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        return -1;
    }
    int raw = ((rx[1] & 0x03) << 8) | rx[2];
    return raw;
}

static float raw_to_field(int raw) {
    float v = (float)raw * ADC_VREF / (float)ADC_MAX;
    /* DRV5055-A1: B_mT = V_out * 0.001 + 0.05 (adjust to your calibration) */
    return v * 0.001f + 0.05f;
}

static int log_data(FILE *fp, time_t ts, float field) {
    if (fprintf(fp, "%ld,%.2f\n", (long)ts, field) < 0) {
        perror("fprintf(log)");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush(log)");
        return -1;
    }
    return 0;
}

int main(void) {
    int spi_fd = -1;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    if (setup_signals() != 0) {
        goto cleanup;
    }

    spi_fd = spi_open(SPI_DEVICE);
    if (spi_fd < 0) {
        goto cleanup;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen(log)");
        goto cleanup;
    }

    printf("Starting DRV5055-A1 Hall sensor logging via MCP3008 ADC...\n");
    printf("SPI: %s @ %d Hz, mode %d, %d bits, ADC channel %d\n",
           SPI_DEVICE, SPI_SPEED_HZ, SPI_MODE, SPI_BITS, ADC_CHANNEL);
    printf("Logging to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        int raw = mcp3008_read(spi_fd, ADC_CHANNEL);
        if (raw < 0) {
            fprintf(stderr, "ADC read failed; skipping sample\n");
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        float field = raw_to_field(raw);
        time_t now = time(NULL);

        if (log_data(log_fp, now, field) != 0) {
            fprintf(stderr, "Logging failed; continuing\n");
        }

        printf("raw=%4d  V=%.3f V  B=%.2f mT\n", raw, raw * ADC_VREF / ADC_MAX, field);
        usleep(SAMPLE_DELAY_US);
    }

    printf("\nShutting down cleanly...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (log_fp) {
        fclose(log_fp);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    return ret;
}

