    spi_fd = spi_open(SPI_DEVICE);
    if (spi_fd < 0) {
        goto cleanup;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen(log)");
        goto cleanup;
    }

    printf("Starting DRV5055-A1 Hall sensor logging via MCP3008 ADC...\n");
    printf("SPI: %s @ %d Hz, mode %d, %d bits, ADC channel %d\n",
           SPI_DEVICE, SPI_SPEED_HZ, SPI_MODE, SPI_BITS, ADC_CHANNEL);
    printf("Logging to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        int raw = mcp3008_read(spi_fd, ADC_CHANNEL);
        if (raw < 0) {
            fprintf(stderr, "ADC read failed; skipping sample\n");
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        float field = raw_to_field(raw);
        time_t now = time(NULL);

        if (log_data(log_fp, now, field) != 0) {
            fprintf(stderr, "Logging failed; continuing\n");
        }

        printf("raw=%4d  V=%.3f V  B=%.2f mT\n", raw, raw * ADC_VREF / ADC_MAX, field);
        usleep(SAMPLE_DELAY_US);
    }

    printf("\nShutting down cleanly...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (log_fp) {
        fclose(log_fp);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    return ret;
}

