#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define LOG_FILE "moisture_log.txt"
#define READ_INTERVAL 60

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int bytes = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", bytes);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static int log_data(const char *filename, int moisture_level) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("Error getting time");
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("Error converting time");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s %d\n", timestamp, moisture_level) < 0) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int moisture_level = read_mcp3008(spi_handle, MCP3008_CHANNEL);

        if (moisture_level >= 0) {
            if (log_data(LOG_FILE, moisture_level) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            time_t t = time(NULL);
            struct tm tm_info;
            char timestamp[64];

            if (t != (time_t)-1 && localtime_r(&t, &tm_info) != NULL &&
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) > 0) {
                if (log_data(LOG_FILE, -1) != 0) {
                    fprintf(stderr, "Failed to log error\n");
                }
            }
        }

        for (int i = 0; i < READ_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");

    if (spiClose(spi_handle) != 0) {
        fprintf(stderr, "SPI close failed\n");
    }

    gpioTerminate();

    printf("Soil moisture monitoring stopped.\n");
    return EXIT_SUCCESS;
}

