/*
 * MLX91209 current sensor reader via MCP3008 ADC on Raspberry Pi 3 B+
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> MLX91209 VOUT
 *   MLX91209 VCC -> 5 V
 *   MLX91209 GND -> GND
 *   MLX91209 EN  -> GPIO17 (BCM)
 *
 * Build:  gcc -O2 -Wall -o current_monitor current_monitor.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_EN_LINE    17          /* BCM 17 */
#define ADC_CHANNEL     0           /* MCP3008 single-ended channel 0 */
#define ADC_MAX         1023        /* 10-bit ADC */
#define VREF            3.3         /* MCP3008 VREF tied to 3.3 V */
#define SENSITIVITY     0.1         /* MLX91209: ~100 mV/A */
#define LOG_FILE        "current_log.txt"
#define SAMPLE_PERIOD_S 1

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd   = -1;
static FILE *g_log_fp  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* SPI                                                                 */
/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = 1000000; /* 1 MHz */
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    return 0;
}

static void spi_close(void)
{
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   tx[2] = 0x00                       (clock out remaining bits)
 *   rx[1] low 2 bits + rx[2] 8 bits    = 10-bit result
 */
static int mcp3008_read(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = 1000000;
    tr.bits_per_word = 8;
    tr.delay_usecs   = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

/* ------------------------------------------------------------------ */
/* GPIO                                                                */
/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    int fd = open("/dev/gpiochip0", O_RDWR);
    if (fd < 0) {
        perror("open(/dev/gpiochip0)");
        return -1;
    }

    if (ioctl(fd, GPIO_GET_VALUE, GPIO_EN_LINE) < 0) {
        perror("ioctl(GPIO_GET_VALUE)");
        close(fd);
        return -1;
    }

    /* Request line as output, default LOW (sensor disabled) */
    uint8_t mode = GPIO_MODE_OUTPUT;
    if (ioctl(fd, GPIO_SET_MODE, GPIO_EN_LINE, &mode) < 0) {
        perror("ioctl(GPIO_SET_MODE)");
        close(fd);
        return -1;
    }

    uint8_t val = 0;
    if (ioctl(fd, GPIO_SET_VALUE, GPIO_EN_LINE, &val) < 0) {
        perror("ioctl(GPIO_SET_VALUE)");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

static void gpio_close(void)
{
    int fd = open("/dev/gpiochip0", O_RDWR);
    if (fd < 0) {
        /* No GPIO cleanup if we cannot even open the chip */
        return;
    }
    /* Set line LOW and release it */
    uint8_t val = 0;
    if (ioctl(fd, GPIO_SET_VALUE, GPIO_EN_LINE, &val) < 0) {
        perror("ioctl(GPIO_SET_VALUE) during cleanup");
    }
    close(fd);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_init(void)
{
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }
    return 0;
}

static void log_close(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

static int log_write(double current_a)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time()");
        return -1;
    }

    struct tm tm_buf;
    struct tm *tm_info = localtime_r(&now, &tm_buf);
    if (!tm_info) {
        perror("localtime_r()");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s,%.4f\n", ts, current_a) < 0) {
        perror("fprintf(log)");
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        perror("fflush(log)");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    gpio_close();
    spi_close();
    log_close();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (spi_init() != 0) {
        return EXIT_FAILURE;
    }

    if (gpio_init() != 0) {
        spi_close();
        return EXIT_FAILURE;
    }

    if (log_init() != 0) {
        gpio_close();
        spi_close();
        return EXIT_FAILURE;
    }

    /* Enable sensor power and let it settle */
    if (ioctl(gpio_init(), GPIO_SET_VALUE, GPIO_EN_LINE, (uint8_t *)"1") < 0) {
        fprintf(stderr, "Failed to enable sensor power\n");
        cleanup();
        return EXIT_FAILURE;
    }
    usleep(100000); /* 100 ms */

    printf("MLX91209 current monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc = mcp3008_read(ADC_CHANNEL);
        if (adc < 0) {
            fprintf(stderr, "ADC read failed; retrying in %d s\n",
                    SAMPLE_PERIOD_S);
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        double voltage = (double)adc * VREF / (double)ADC_MAX;
        double current = voltage / SENSITIVITY;

        if (log_write(current_a) != 0) {
            fprintf(stderr, "Log write failed; continuing\n");
        }

        printf("ADC=%4d  V=%.3f  I=%.4f A\n", adc, voltage, current);

        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

