#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/*
 * Raspberry Pi Zero W – MLX91211 current sensor reader via MCP3008 ADC
 *
 * Wiring:
 *   MCP3008 VDD  -> Pi 5V  (pin 2 or 4)
 *   MCP3008 VREF -> Pi 5V  (pin 2 or 4)
 *   MCP3008 AGND -> Pi GND (pin 6)
 *   MCP3008 DGND -> Pi GND (pin 6)
 *   MCP3008 CLK  -> Pi GPIO11 (SCLK, pin 23)
 *   MCP3008 DOUT -> Pi GPIO9  (MISO, pin 21)
 *   MCP3008 DIN  -> Pi GPIO10 (MOSI, pin 19)
 *   MCP3008 CS   -> Pi GPIO8  (CE0,  pin 24)
 *   MCP3008 CH0  -> MLX91211 VOUT (analog)
 *   MLX91211 VDD -> Pi 5V  (pin 2 or 4)
 *   MLX91211 GND -> Pi GND (pin 6)
 *
 * Build:  gcc -O2 -Wall -o current_logger current_logger.c -lpigpio -lrt
 * Run:    sudo ./current_logger
 */

#define SPI_CHANNEL    0          /* CE0 on GPIO8 */
#define SPI_SPEED      1000000    /* 1 MHz, mode 0 */
#define SPI_FLAGS      0          /* active-low CE, MSB first, 8-bit */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX        1023       /* 10-bit ADC */
#define VREF           5.0        /* Pi 5V rail (VDD for MLX91211 and MCP3008) */
#define SAMPLE_US      100000     /* 100 ms between samples */
#define LOG_FILE       "current_log.txt"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler – set flag so main loop can exit cleanly             */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read one sample from the MCP3008 (single-ended, channel 0)          */
/* Returns 0 on success and stores the 10-bit value in *value;        */
/* returns -1 on SPI transfer error.                                  */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int spi_handle, int channel, int *value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read sequence (3 bytes):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: rx[1] low 2 bits + rx[2] 8 bits = 10-bit value
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed (returned %d)\n", ret);
        return -1;
    }

    *value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert ADC count to current (A)                                   */
/* Assumes MLX91211 output is proportional to current through a       */
/* known resistor; calibrate R_load = R_sensor * R_ref / R_load_known */
/* ------------------------------------------------------------------ */
static float adc_to_current(int adc_value)
{
    float voltage = (float)adc_value * VREF / (float)ADC_MAX;
    /*
     * Example: R_load = 100 Ω, R_sensor = 10 Ω  ->  R_ref = 1000 Ω.
     * So R_load_known = 100 Ω, R_ref = 1000 Ω  ->  R_sensor = 10 Ω.
     * Current = V / R = voltage / (100 + 10) = voltage / 110 A.
     */
    return voltage / 110.0f;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped current reading to the log file               */
/* ------------------------------------------------------------------ */
static int log_current(FILE *fp, float current)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s %.2f A\n", timestamp, current) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper – safe to call multiple times                       */
/* ------------------------------------------------------------------ */
static void cleanup(int spi_handle)
{
    if (g_log != NULL) {
        fclose(g_log);
        g_log = NULL;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    int spi_handle = -1;
    int ret_code = EXIT_SUCCESS;

    /* --- Initialize pigpio ------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz, mode 0 ----------------------------- */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file ---------------------------------------------- */
    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        fprintf(stderr, "Error opening log file '%s'\n", LOG_FILE);
        cleanup(spi_handle);
        return EXIT_FAILURE;
    }

    /* --- Install SIGINT handler ------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed\n");
        cleanup(spi_handle);
        return EXIT_FAILURE;
    }

    printf("MLX91211 current logger started. Press Ctrl+C to stop.\n");

    /* --- Main sampling loop ----------------------------------------- */
    while (g_running) {
        int adc_value = 0;

        if (read_mcp3008(spi_handle, ADC_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "SPI transfer error – skipping sample\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        float current = adc_to_current(adc_value);

        /* Sanity check: MLX91211 output should be within 0–5 V */
        if (current < 0.0f || current > 5.0f) {
            fprintf(stderr, "Warning: current %.2f A out of range – skipping\n",
                    current);
            gpioDelay(SAMPLE_US);
            continue;
        }

        if (log_current(g_log, current) != 0) {
            fprintf(stderr, "Logging error – exiting\n");
            ret_code = EXIT_FAILURE;
            break;
        }

        gpioDelay(SAMPLE_US);
    }

    /* --- Clean shutdown --------------------------------------------- */
    printf("\nShutting down...\n");
    cleanup(spi_handle);
    return ret_code;
}

