#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define DEBOUNCE_SAMPLES 5
#define DEBOUNCE_DELAY_US 2000
#define POLL_DELAY_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO pin %d: %d\n", pin, value);
        return -1;
    }
    return value;
}

static int debounce_sensor(int pin) {
    int readings[DEBOUNCE_SAMPLES];
    int sum = 0;

    for (int i = 0; i < DEBOUNCE_SAMPLES; i++) {
        int reading = read_sensor(pin);
        if (reading < 0) {
            return -1;
        }
        readings[i] = reading;
        sum += reading;
        if (i < DEBOUNCE_SAMPLES - 1) {
            gpioDelay(DEBOUNCE_DELAY_US);
        }
    }

    return (sum >= DEBOUNCE_SAMPLES / 2) ? 0 : 1;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int s1 = debounce_sensor(SENSOR_1_PIN);
        int s2 = debounce_sensor(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Sensor read error, exiting.\n");
            break;
        }

        printf("Sensor 1 (GPIO%d): %d\n", SENSOR_1_PIN, s1);
        printf("Sensor 2 (GPIO%d): %d\n", SENSOR_2_PIN, s2);

        if (s1 == 0 && s2 == 0) {
            printf("ALERT: Both sensors detect object\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

