#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include "driver_lib.h"

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

static int spi_handle = -1;
static volatile sig_atomic_t program_running = 1;

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01;
    spi_tx_buf[1] = (0x08 | channel) << 4;
    spi_tx_buf[2] = 0x00;

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

static double calculate_moisture_level(int adc_value) {
    if (adc_value < MIN_ADC) {
        adc_value = MIN_ADC;
    } else if (adc_value > MAX_ADC) {
        adc_value = MAX_ADC;
    }
    return ((double)(adc_value - MIN_ADC) / (MAX_ADC - MIN_ADC)) * 100.0;
}

static void log_data(double moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }

    fprintf(fp, "%s,%.2f\n", timestamp, moisture_level);
    fclose(fp);

    printf("%s,%.2f\n", timestamp, moisture_level);
}

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int spi_setup(spi_config_t config) {
    if (spi_open(&spi_handle, &config) != 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        return -1;
    }
    return 0;
}

int main() {
    spi_config_t config;
    spi_config_init(&config);
    config.channel = SPI_CHANNEL;
    config.baud_rate = SPI_BAUD;
    config.flags = 0;

    if (spi_setup(config) != 0) {
        spi_terminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (program_running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, retrying in %d seconds...\n", READ_DELAY);
            sleep(READ_DELAY);
            continue;
        }

        double moisture_level = calculate_moisture_level(adc_value);
        log_data(moisture_level);

        sleep(READ_DELAY);
    }

    if (spi_handle >= 0) {
        spi_close(spi_handle);
    }
    spi_terminate();
    return 0;
}

