#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <pigpio.h>

#define PIR_GPIO 17
#define DEBOUNCE_MS 200
#define POLL_INTERVAL_US 50000
#define CAPTURE_DIR "/home/pi/security_cam/"
#define MAX_PATH 512
#define MAX_FILENAME 256
#define MAX_CMD 512

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int ensure_directory(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        syslog(LOG_ERR, "Path '%s' exists but is not a directory", path);
        return -1;
    }
    if (mkdir(path, 0755) != 0) {
        syslog(LOG_ERR, "mkdir('%s') failed: %s", path, strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename) {
    pid_t pid = fork();
    if (pid < 0) {
        syslog(LOG_ERR, "fork() failed: %s", strerror(errno));
        return -1;
    }
    if (pid == 0) {
        execlp("libcamera-still", "libcamera-still",
               "-o", filename,
               "--width", "640",
               "--height", "480",
               "--nopreview",
               (char *)NULL);
        perror("execlp libcamera-still");
        _exit(127);
    }
    int status = 0;
    while (waitpid(pid, &status, 0) < 0) {
        if (errno == EINTR) {
            if (!g_running) {
                syslog(LOG_ERR, "waitpid() interrupted during capture");
                return -1;
            }
            continue;
        }
        syslog(LOG_ERR, "waitpid() failed: %s", strerror(errno));
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
        return 0;
    }
    syslog(LOG_ERR, "libcamera-still failed (status=%d)", status);
    return -1;
}

static void generate_filename(char *buf, size_t buflen) {
    time_t rawtime;
    struct tm timeinfo;
    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(buf, buflen, CAPTURE_DIR "%Y%m%d_%H%M%S_%l%z_%s.jpg", &timeinfo);
}

int main(void) {
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting security camera monitor (PIR on GPIO%d)", PIR_GPIO);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction() failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode failed for GPIO%d", PIR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        syslog(LOG_ERR, "gpioSetPullUpDown failed for GPIO%d", PIR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (ensure_directory(CAPTURE_DIR) != 0) {
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Monitoring started. PIR on GPIO%d, output dir '%s'", PIR_GPIO, CAPTURE_DIR);

    int last_state = gpioRead(PIR_GPIO);
    if (last_state < 0) {
        syslog(LOG_ERR, "Initial gpioRead failed for GPIO%d", PIR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int current_state = gpioRead(PIR_GPIO);
        if (current_state < 0) {
            syslog(LOG_ERR, "gpioRead failed for GPIO%d", PIR_GPIO);
            break;
        }

        if (current_state != last_state) {
            gpioDelay(DEBOUNCE_MS * 1000);
            current_state = gpioRead(PIR_GPIO);
            if (current_state < 0) {
                syslog(LOG_ERR, "gpioRead (debounce) failed for GPIO%d", PIR_GPIO);
                break;
            }

            if (current_state == 1) {
                syslog(LOG_INFO, "Motion detected on GPIO%d", PIR_GPIO);

                char filename[MAX_FILENAME];
                generate_filename(filename, sizeof(filename));

                if (capture_image(filename) == 0) {
                    syslog(LOG_INFO, "Image captured: %s", filename);
                } else {
                    syslog(LOG_ERR, "Image capture failed for %s", filename);
                }
            }

            last_state = current_state;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down security camera monitor");
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

