    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction() failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode failed for GPIO%d", PIR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        syslog(LOG_ERR, "gpioSetPullUpDown failed for GPIO%d", PIR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (ensure_directory(CAPTURE_DIR) != 0) {
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Monitoring started. PIR on GPIO%d, output dir '%s'", PIR_GPIO, CAPTURE_DIR);

    int last_state = gpioRead(PIR_GPIO);
    if (last_state < 0) {
        syslog(LOG_ERR, "Initial gpioRead failed for GPIO%d", PIR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int current_state = gpioRead(PIR_GPIO);
        if (current_state < 0) {
            syslog(LOG_ERR, "gpioRead failed for GPIO%d", PIR_GPIO);
            break;
        }

        if (current_state != last_state) {
            gpioDelay(DEBOUNCE_MS * 1000);
            current_state = gpioRead(PIR_GPIO);
            if (current_state < 0) {
                syslog(LOG_ERR, "gpioRead (debounce) failed for GPIO%d", PIR_GPIO);
                break;
            }

            if (current_state == 1) {
                syslog(LOG_INFO, "Motion detected on GPIO%d", PIR_GPIO);

                char filename[MAX_FILENAME];
                generate_filename(filename, sizeof(filename));

                if (capture_image(filename) == 0) {
                    syslog(LOG_INFO, "Image captured: %s", filename);
                } else {
                    syslog(LOG_ERR, "Image capture failed for %s", filename);
                }
            }

            last_state = current_state;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down security camera monitor");
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

