#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <signal.h>

#define DEFAULT_DEVICE "/dev/video0"
#define NUM_BUFFERS 1
#define FRAME_WIDTH 640
#define FRAME_HEIGHT 480
#define MAX_FILENAME_LENGTH 64

static volatile sig_atomic_t stop_flag = 0;
static int g_fd = -1;
static void *g_buffers[NUM_BUFFERS];
static size_t g_buffer_sizes[NUM_BUFFERS];
static int g_buffers_mapped = 0;

static void signal_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int initialize_camera(const char *device) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned int i;

    g_fd = open(device, O_RDWR | O_NONBLOCK, 0);
    if (g_fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", device, strerror(errno));
        return -1;
    }

    if (xioctl(g_fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        goto fail_close;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device %s does not support video capture\n", device);
        goto fail_close;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device %s does not support streaming I/O\n", device);
        goto fail_close;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = FRAME_WIDTH;
    fmt.fmt.pix.height = FRAME_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(g_fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        goto fail_close;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_GREY) {
        fprintf(stderr, "Device %s does not support GREY format\n", device);
        goto fail_close;
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(g_fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        goto fail_close;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory on device %s\n", device);
        goto fail_close;
    }

    for (i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(g_fd, VIDIOC_QUERYBUF, &buf) < 0) {
            fprintf(stderr, "Error querying buffer %d: %s\n", i, strerror(errno));
            goto fail_unmap;
        }

        g_buffer_sizes[i] = buf.length;

        g_buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, g_fd, buf.m.offset);
        if (g_buffers[i] == MAP_FAILED) {
            fprintf(stderr, "Error mapping buffer %d: %s\n", i, strerror(errno));
            g_buffers[i] = NULL;
            goto fail_unmap;
        }
        g_buffers_mapped++;
    }

    for (i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(g_fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "Error queuing buffer %d: %s\n", i, strerror(errno));
            goto fail_unmap;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(g_fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        goto fail_unmap;
    }

    return 0;

fail_unmap:
    for (i = 0; i < req.count; i++) {
        if (g_buffers[i] != NULL && g_buffers[i] != MAP_FAILED) {
            munmap(g_buffers[i], g_buffer_sizes[i]);
            g_buffers[i] = NULL;
        }
    }
fail_close:
    close(g_fd);
    g_fd = -1;
    return -1;
}

static int dequeue_frame(unsigned int *frame_number) {
    struct v4l2_buffer buf;
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(g_fd, &fds);

    tv.tv_sec = 2;
    tv.tv_usec = 0;

    r = select(g_fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        if (errno == EINTR) {
            return -1;
        }
        fprintf(stderr, "Error in select(): %s\n", strerror(errno));
        return -1;
    }

    if (r == 0) {
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(g_fd, VIDIOC_DQBUF, &buf) < 0) {
        if (errno == EAGAIN) {
            return -1;
        }
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    *frame_number = buf.index;

    if (xioctl(g_fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error re-queuing buffer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int save_pgm(const unsigned char *data, size_t size, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "P5\n%d %d\n255\n", FRAME_WIDTH, FRAME_HEIGHT, FRAME_WIDTH * FRAME_HEIGHT) < 0) {
        fprintf(stderr, "Error writing PGM header: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    size_t written = fwrite(data, 1, size, fp);
    if (written != size) {
        fprintf(stderr, "Error writing PGM data: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (g_fd != -1) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (xioctl(g_fd, VIDIOC_STREAMOFF, &type) < 0) {
            fprintf(stderr, "Warning: error stopping stream: %s\n", strerror(errno));
        }
    }

    if (g_buffers_mapped > 0) {
        for (int i = 0; i < g_buffers_mapped; i++) {
            if (g_buffers[i] != NULL && g_buffers[i] != MAP_FAILED) {
                munmap(g_buffers[i], g_buffer_sizes[i]);
                g_buffers[i] = NULL;
            }
        }
        g_buffers_mapped = 0;
    }

    if (g_fd != -1) {
        close(g_fd);
        g_fd = -1;
    }
}

int main(int argc, char *argv[]) {
    const char *device = (argc > 1) ? argv[1] : DEFAULT_DEVICE;
    unsigned int frame_number = 0;
    char filename[MAX_FILENAME_LENGTH];

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (initialize_camera(device) == -1) {
        return 1;
    }

    printf("Starting capture loop on %s...\n", device);

    while (!stop_flag) {
        if (dequeue_frame(&frame_number) == 0) {
            snprintf(filename, sizeof(filename), "image_%04u.pgm", frame_number);
            if (save_pgm((unsigned char *)g_buffers[0], g_buffer_sizes[0], filename) == 0) {
                printf("Saved %s (%u x %u)\n", filename, FRAME_WIDTH, FRAME_HEIGHT);
            } else {
                fprintf(stderr, "Failed to save image %u\n", frame_number);
            }
        } else if (stop_flag) {
            break;
        }
    }

    cleanup();
    printf("Exiting.\n");
    return 0;
}

