#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/videodev2.h>

#define VIDEO_DEVICE "/dev/video0"
#define NUM_BUFFERS 4
#define MAX_UDP_PAYLOAD 65000
#define UDP_PORT 5005
#define UDP_IP "127.0.0.1"

static volatile sig_atomic_t stop_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

typedef struct {
    unsigned int index;
    unsigned int count;
    unsigned int fragment_index;
    unsigned int total_fragments;
    unsigned int payload_size;
    unsigned char data[MAX_UDP_PAYLOAD];
} udp_header_t;

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(int *fd, struct v4l2_buffer *buffers, unsigned int *n_buffers) {
    *fd = open(VIDEO_DEVICE, O_RDWR);
    if (*fd < 0) {
        perror("open(" VIDEO_DEVICE ")");
        return -1;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(*fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        close(*fd);
        *fd = -1;
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(*fd);
        *fd = -1;
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        close(*fd);
        *fd = -1;
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (xioctl(*fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        close(*fd);
        *fd = -1;
        return -1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(*fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        close(*fd);
        *fd = -1;
        return -1;
    }
    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(*fd);
        *fd = -1;
        return -1;
    }

    *n_buffers = req.count;
    for (unsigned int i = 0; i < req.count; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (xioctl(*fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("VIDIOC_QUERYBUF");
            close(*fd);
            *fd = -1;
            return -1;
        }
        buffers[i] = buf;
    }

    for (unsigned int i = 0; i < req.count; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (xioctl(*fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF");
            close(*fd);
            *fd = -1;
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(*fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        close(*fd);
        *fd = -1;
        return -1;
    }
    return 0;
}

static int capture_frame(int fd, struct v4l2_buffer *buffers, unsigned int n_buffers) {
    fd_set fds;
    struct timeval tv;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    tv.tv_sec = 2;
    tv.tv_usec = 0;

    int r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR) return 0;
        perror("select");
        return -1;
    }
    if (r == 0) {
        fprintf(stderr, "select timeout\n");
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    if (buf.index >= n_buffers) {
        fprintf(stderr, "DQBUF returned invalid index %u\n", buf.index);
        xioctl(fd, VIDIOC_QBUF, &buf);
        return -1;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF");
        return -1;
    }
    return 0;
}

static int fragment_frame(const unsigned char *frame, unsigned int frame_size,
                          unsigned int frame_index, unsigned int total_fragments,
                          unsigned char *fragments[], unsigned int *n_fragments,
                          unsigned int max_fragments) {
    unsigned int fragment_size = frame_size / total_fragments;
    if (fragment_size == 0) fragment_size = 1;

    for (unsigned int i = 0; i < total_fragments; i++) {
        unsigned char *fragment = malloc(fragment_size);
        if (!fragment) {
            fprintf(stderr, "malloc failed for fragment %u\n", i);
            return -1;
        }
        memcpy(fragment, frame + (i * fragment_size), fragment_size);
        fragments[*n_fragments] = fragment;
        (*n_fragments)++;
    }
    return 0;
}

static int send_udp_packet(const unsigned char *data, unsigned int data_len,
                           const char *ip, unsigned short port) {
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        return -1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(port);
    if (inet_pton(AF_INET, ip, &addr.sin_addr) <= 0) {
        perror("inet_pton");
        close(sockfd);
        return -1;
    }

    udp_header_t header;
    memset(&header, 0, sizeof(header));
    header.index = 0;
    header.fragment_index = 0;
    header.total_fragments = 4;
    header.payload_size = data_len;

    unsigned char packet[MAX_UDP_PAYLOAD];
    unsigned int packet_len = sizeof(header) + data_len;
    if (packet_len > MAX_UDP_PAYLOAD) {
        fprintf(stderr, "Packet too large: %u\n", packet_len);
        close(sockfd);
        return -1;
    }
    memcpy(packet, &header, sizeof(header));
    memcpy(packet + sizeof(header), data, data_len);

    if (sendto(sockfd, packet, packet_len, 0,
               (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("sendto");
        close(sockfd);
        return -1;
    }
    close(sockfd);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <init_camera> <capture_frame>\n", argv[0]);
        return 1;
    }

    int init_fd = -1, cap_fd = -1;
    struct v4l2_buffer buffers[NUM_BUFFERS];
    unsigned int n_buffers = 0;

    if (signal(SIGINT, signal_handler) == SIG_ERR ||
        signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    if (init_camera(&init_fd, buffers, &n_buffers) < 0) {
        fprintf(stderr, "Failed to initialize camera\n");
        return 1;
    }

    if (init_fd != -1) close(init_fd);

    while (!stop_flag) {
        if (capture_frame(cap_fd, buffers, n_buffers) < 0) {
            if (stop_flag) break;
            fprintf(stderr, "Capture failed, continuing...\n");
            continue;
        }

        unsigned char *fragments[NUM_BUFFERS];
        unsigned int n_fragments = 0;
        unsigned char *frame = buffers[0].bytesused > 0 ? malloc(buffers[0].bytesused) : NULL;
        if (frame) {
            memcpy(frame, buffers[0].bytesused > 0 ? buffers[0].bytes : NULL, buffers[0].bytesused);
        }

        if (fragment_frame(frame ? frame : NULL, buffers[0].bytesused,
                           0, NUM_BUFFERS, fragments, &n_fragments, NUM_BUFFERS) < 0) {
            if (stop_flag) break;
            fprintf(stderr, "Fragmentation failed, continuing...\n");
            free(frame);
            continue;
        }

        for (unsigned int i = 0; i < n_fragments; i++) {
            if (send_udp_packet(fragments[i], strlen((const char *)fragments[i]),
                                UDP_IP, UDP_PORT) < 0) {
                fprintf(stderr, "UDP send failed for fragment %u\n", i);
            }
        }

        for (unsigned int i = 0; i < n_fragments; i++) free(fragments[i]);
        free(frame);
