#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 192
#define IMAGE_HEIGHT 120
#define NUM_BUFFERS 4
#define OUTPUT_FILE "image.jpg"

static volatile sig_atomic_t stop_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

typedef struct {
    void *start;
    size_t length;
} buffer_t;

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR);
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }
    return fd;
}

static int init_device(int fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned int i;

    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", device_name);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", device_name);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        return -1;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    for (i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Error querying buffer");
            return -1;
        }

        buffer_t *b = (buffer_t *)malloc(sizeof(buffer_t));
        if (!b) {
            perror("Error allocating buffer struct");
            return -1;
        }

        b->length = buf.length;
        b->start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (b->start == MAP_FAILED) {
            perror("Error mapping buffer");
            free(b);
            return -1;
        }

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            munmap(b->start, b->length);
            free(b);
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        return -1;
    }

    return 0;
}

static int dequeue_frame(int fd, buffer_t *buf) {
    struct v4l2_buffer buf_struct;
    memset(&buf_struct, 0, sizeof(buf_struct));
    buf_struct.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf_struct.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf_struct) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    buf->start = mmap(NULL, buf_struct.bytesused, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf_struct.m.offset);
    if (buf->start == MAP_FAILED) {
        perror("Error mapping buffer for writing");
        return -1;
    }

    buf->length = buf_struct.bytesused;
    return 0;
}

static int write_mjpeg_file(const char *filename, const buffer_t *buf) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("Error opening file for writing");
        return -1;
    }

    size_t written = fwrite(buf->start, 1, buf->length, fp);
    if (written != buf->length) {
        fprintf(stderr, "Error writing to file: wrote %zu of %zu bytes\n", written, buf->length);
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing file");
        return -1;
    }

    return 0;
}

static void cleanup_device(int fd, buffer_t **buffers, unsigned int n_buffers) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (fd >= 0) {
        if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
            perror("Error stopping stream");
        }
    }

    if (buffers) {
        for (unsigned int i = 0; i < n_buffers; i++) {
            if (buffers[i]) {
                if (munmap(buffers[i]->start, buffers[i]->length) < 0) {
                    perror("Error unmapping buffer");
                }
                free(buffers[i]);
            }
        }
        free(buffers);
    }
}

int main(void) {
    int fd = -1;
    buffer_t *buffers = NULL;
    unsigned int n_buffers = 0;
    int ret_code = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Error registering SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Error registering SIGTERM handler");
        return EXIT_FAILURE;
    }

    fd = open_device(DEVICE_NAME);
    if (fd < 0) {
        goto cleanup;
    }

    if (init_device(fd) < 0) {
        goto cleanup;
    }

    buffers = (buffer_t *)calloc(NUM_BUFFERS, sizeof(buffer_t));
    if (!buffers) {
        perror("Error allocating buffer array");
        goto cleanup;
    }

    n_buffers = NUM_BUFFERS;

    printf("Dequeuing frame...\n");
    buffer_t *frame_buf = (buffer_t *)malloc(sizeof(buffer_t));
    if (!frame_buf) {
        perror("Error allocating frame buffer");
        goto cleanup;
    }

    if (dequeue_frame(fd, frame_buf) < 0) {
        fprintf(stderr, "Failed to dequeue frame\n");
        goto cleanup;
    }

    if (stop_flag) {
        fprintf(stderr, "Interrupted before writing frame\n");
        goto cleanup;
    }

    if (frame_buf->length <= 0) {
        fprintf(stderr, "Error: dequeued buffer has zero bytes\n");
        goto cleanup;
    }

    printf("Writing MJPEG to %s (%zu bytes)\n", OUTPUT_FILE, frame_buf->length);
    if (write_mjpeg_file(OUTPUT_FILE, frame_buf) < 0) {
        fprintf(stderr, "Failed to write MJPEG file\n");
        goto cleanup;
    }

    printf("Saved %s (%zu bytes)\n", OUTPUT_FILE, frame_buf->length);
    ret_code = EXIT_SUCCESS;

cleanup:
    if (frame_buf) {
        if (munmap(frame_buf->start, frame_buf->length) < 0) {
            perror("Error unmapping frame buffer");
        }
        free(frame_buf);
    }
    cleanup_device(fd, &buffers, n_buffers);
    if (fd >= 0) {
        close(fd);
    }
    return ret_code;
}

