#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN      4
#define TILT_SERVO_PIN     5
#define TILT_UP_BUTTON_PIN 6
#define TILT_DOWN_BUTTON_PIN 7
#define PAN_LEFT_BUTTON_PIN 8
#define PAN_RIGHT_BUTTON_PIN 9

#define PWM_FREQUENCY      50
#define PWM_RANGE          1000
#define PWM_DUTY_MIN       50
#define PWM_DUTY_MAX       100
#define PWM_DUTY_MID       75
#define PWM_PERIOD_US      20000
#define POLL_DELAY_US      50000
#define ADJUST_STEP        5
#define MIN_POSITION       25
#define MAX_POSITION       125

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_servo_position(int pin, int position) {
    if (position < MIN_POSITION) position = MIN_POSITION;
    if (position > MAX_POSITION) position = MAX_POSITION;

    int duty = (int)(((float)(position - MIN_POSITION) /
                     (float)(MAX_POSITION - MIN_POSITION)) *
                     (float)(PWM_DUTY_MAX - PWM_DUTY_MIN) +
                     (float)PWM_DUTY_MIN);

    if (gpioServo(pin, duty) < 0) {
        fprintf(stderr, "Error: gpioServo failed on pin %d (duty %d)\n", pin, duty);
        return -1;
    }
    return 0;
}

static int adjust_axis(int pin, int button_pin, int *position, int direction) {
    if (gpioRead(button_pin) == 0) {
        *position += direction * ADJUST_STEP;
        if (*position < MIN_POSITION) *position = MIN_POSITION;
        if (*position > MAX_POSITION) *position = MAX_POSITION;

        if (set_servo_position(pin, *position) != 0) {
            return -1;
        }
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set PAN_SERVO_PIN %d as output\n", PAN_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TILT_SERVO_PIN %d as output\n", TILT_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TILT_UP_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set TILT_UP_BUTTON_PIN %d as input\n", TILT_UP_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(TILT_DOWN_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set TILT_DOWN_BUTTON_PIN %d as input\n", TILT_DOWN_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PAN_LEFT_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set PAN_LEFT_BUTTON_PIN %d as input\n", PAN_LEFT_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PAN_RIGHT_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set PAN_RIGHT_BUTTON_PIN %d as input\n", PAN_RIGHT_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TILT_UP_BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on TILT_UP_BUTTON_PIN %d\n", TILT_UP_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(TILT_DOWN_BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on TILT_DOWN_BUTTON_PIN %d\n", TILT_DOWN_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(PAN_LEFT_BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on PAN_LEFT_BUTTON_PIN %d\n", PAN_LEFT_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(PAN_RIGHT_BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on PAN_RIGHT_BUTTON_PIN %d\n", PAN_RIGHT_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on PAN_SERVO_PIN %d\n", PAN_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on TILT_SERVO_PIN %d\n", TILT_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PAN_SERVO_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on PAN_SERVO_PIN %d\n", PAN_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(TILT_SERVO_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on TILT_SERVO_PIN %d\n", TILT_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMperiod(PAN_SERVO_PIN, PWM_PERIOD_US) < 0) {
        fprintf(stderr, "Error: failed to set PWM period on PAN_SERVO_PIN %d\n", PAN_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMperiod(TILT_SERVO_PIN, PWM_PERIOD_US) < 0) {
        fprintf(stderr, "Error: failed to set PWM period on TILT_SERVO_PIN %d\n", TILT_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioServo(PAN_SERVO_PIN, PWM_DUTY_MID) < 0) {
        fprintf(stderr, "Error: failed to initialise PAN_SERVO_PIN %d\n", PAN_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioServo(TILT_SERVO_PIN, PWM_DUTY_MID) < 0) {
        fprintf(stderr, "Error: failed to initialise TILT_SERVO_PIN %d\n", TILT_SERVO_PIN);
        gpioTermoinate();
        return EXIT_FAILURE;
    }

    int pan_position = PWM_DUTY_MID;
    int tilt_position = PWM_DUTY_MID;

    while (g_running) {
        if (adjust_axis(PAN_SERVO_PIN, PAN_LEFT_BUTTON_PIN, &pan_position, -1) != 0 ||
            adjust_axis(PAN_SERVO_PIN, PAN_RIGHT_BUTTON_PIN, &pan_position, 1) != 0) {
            break;
        }

        if (adjust_axis(TILT_SERVO_PIN, TILT_UP_BUTTON_PIN, &tilt_position, -1) != 0 ||
            adjust_axis(TILT_SERVO_PIN, TILT_DOWN_BUTTON_PIN, &tilt_position, 1) != 0) {
            break;
        }

        gpioDelay(POLL_DELAY_US);
    }

    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

