#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <stdint.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

typedef struct {
    int fd;
    struct v4l2_buffer buf;
    void *buffer_start;
    size_t buffer_length;
} camera_t;

static volatile sig_atomic_t stop_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

static int xioctl(int fd, int request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(camera_t *cam) {
    cam->fd = open("/dev/video0", O_RDWR);
    if (cam->fd < 0) {
        perror("open /dev/video0");
        return -1;
    }

    struct v4l2_capability cap;
    CLEAR(cap);
    if (xioctl(cam->fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        close(cam->fd);
        cam->fd = -1;
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "/dev/video0 is not a video capture device\n");
        close(cam->fd);
        cam->fd = -1;
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "/dev/video0 does not support streaming I/O\n");
        close(cam->fd);
        cam->fd = -1;
        return -1;
    }

    struct v4l2_format fmt;
    CLEAR(fmt);
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(cam->fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        close(cam->fd);
        cam->fd = -1;
        return -1;
    }

    struct v4l2_requestbuffers req;
    CLEAR(req);
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(cam->fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        close(cam->fd);
        cam->fd = -1;
        return -1;
    }

    memset(&cam->buf, 0, sizeof(cam->buf));
    cam->buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    cam->buf.memory = V4L2_MEMORY_MMAP;
    cam->buf.index = 0;

    if (xioctl(cam->fd, VIDIOC_QUERYBUF, &cam->buf) < 0) {
        perror("VIDIOC_QUERYBUF");
        close(cam->fd);
        cam->fd = -1;
        return -1;
    }

    cam->buffer_length = cam->buf.length;
    cam->buffer_start = mmap(NULL, cam->buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, cam->fd, cam->buf.m.offset);
    if (cam->buffer_start == MAP_FAILED) {
        perror("mmap");
        cam->buffer_start = NULL;
        close(cam->fd);
        cam->fd = -1;
        return -1;
    }

    if (xioctl(cam->fd, VIDIOC_QBUF, &cam->buf) < 0) {
        perror("VIDIOC_QBUF");
        munmap(cam->buffer_start, cam->buffer_length);
        cam->buffer_start = NULL;
        close(cam->fd);
        cam->fd = -1;
        return -1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(cam->fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        munmap(cam->buffer_start, cam->buffer_length);
        cam->buffer_start = NULL;
        close(cam->fd);
        cam->fd = -1;
        return -1;
    }

    return 0;
}

static int capture_frame(camera_t *cam) {
    fd_set fds;
    struct timeval tv;
    FD_ZERO(&fds);
    FD_SET(cam->fd, &fds);
    tv.tv_sec = 2;
    tv.tv_usec = 0;

    int r = select(cam->fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR) return -1;
        perror("select");
        return -1;
