#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"

static void print_capability(const struct v4l2_capability *cap)
{
    printf("  %s\n", cap->card);
    printf("  %s\n", cap->driver);
    printf("  %s\n", cap->bus_info);
    printf("  Version: %u.%u.%u\n",
           (cap->version >> 16) & 0xFF,
           (cap->version >> 8) & 0xFF,
           cap->version & 0xFF);
    printf("  Caps: 0x%08X\n", cap->capabilities);
}

static void print_format(const struct v4l2_format *fmt)
{
    printf("    Type : %s\n", fmt->type == V4L2_BUF_TYPE_VIDEO_CAPTURE
                                ? "video-capture" : "video-output");
    printf("    Pixelformat: %s\n",
           __v4l2_pixelformat_to_str(fmt->pixelformat));
    printf("    Field: %s\n", fmt->field == V4L2_FIELD_NONE
                                ? "none" : fmt->field == V4L2_FIELD_TOP
                                ? "top" : "bottom");
    printf("    Bytesperline: %u\n", fmt->bytesperline);
    printf("    Sizeimage: %u\n", fmt->sizeimage);
}

static void print_frmsize(const struct v4l2_frmsizeenum *frmsize)
{
    printf("      Width : %u\n", frmsize->type == V4L2_FRMSIZE_TYPE_DISCRETE
                                  ? frmsize->discrete.width
                                  : frmsize->stepwise.width);
    printf("      Height: %u\n", frmsize->type == V4L2_FRMSIZE_TYPE_DISCRETE
                                  ? frmsize->discrete.height
                                  : frmsize->stepwise.height);
    printf("      Interval: %u\n", frmsize->type == V4L2_FRMSIZE_TYPE_DISCRETE
                                   ? frmsize->discrete.interval
                                   : frmsize->stepwise.interval);
}

static void print_frmival(const struct v4l2_frmivalenum *frmival)
{
    printf("      Type : %s\n",
           frmival->type == V4L2_FRMIVAL_TYPE_DISCRETE
           ? "discrete" : frmival->type == V4L2_FRMIVAL_TYPE_STEPWISE
           ? "stepwise" : "continuous");
    printf("      Value: %u/%u\n",
           frmival->discrete.numerator, frmival->discrete.denominator);
    printf("      Step: %u/%u\n",
           frmival->stepwise.step_numerator, frmival->stepwise.step_denominator);
}

static void print_focus_control(int fd, int supported)
{
    struct v4l2_queryctrl qc;
    memset(&qc, 0, sizeof(qc));
    qc.id = V4L2_CID_FOCUS_AUTO;

    if (ioctl(fd, VIDIOC_QUERYCTRL, &qc) == -1) {
        if (errno == EINVAL) {
            printf("  Autofocus control not supported by the camera.\n");
        } else {
            fprintf(stderr, "Warning: VIDIOC_QUERYCTRL failed for focus: %s\n",
                    strerror(errno));
        }
        return;
    }

    printf("  Autofocus: supported = %s\n", supported ? "yes" : "no");
    printf("            Min = %d, Max = %d, Default = %d, Step = %d\n",
           qc.min, qc.max, qc.default_value, qc.stepwing);
}

int main(void)
{
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_frmsizeenum frmsize;
    struct v4l2_frmivalenum frmival;
    int supported = 0;
    int rc = EXIT_FAILURE;

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    memset(&cap, 0, sizeof(cap));
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        goto cleanup;
    }

    print_capability(&cap);

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device.\n", DEVICE_NAME);
        goto cleanup;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        fprintf(stderr, "VIDIOC_S_FMT failed: %s\n", strerror(errno));
        goto cleanup;
    }

    print_format(&fmt);

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O.\n", DEVICE_NAME);
        goto cleanup;
    }

    printf("Supported frame sizes:\n");
    for (int i = 0; ; i++) {
        memset(&frmsize, 0, sizeof(frmsize));
        frmsize.index = i;
        frmsize.type = V4L2_FRMSIZE_TYPE_DISCRETE;

        if (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) == -1) {
            if (errno == EINVAL)
                break;
            fprintf(stderr, "VIDIOC_ENUM_FRAMESIZES failed: %s\n",
                    strerror(errno));
            goto cleanup;
        }

        print_frmsize(&frmsize);

        memset(&frmival, 0, sizeof(frmival));
        frmival.index = 0;
        frmival.type = V4L2_FRMIVAL_TYPE_DISCRETE;
        frmival.discrete.numerator = 1;
        frmival.discrete.denominator = 1;

        if (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmival) == -1) {
            if (errno == EINVAL)
                continue;
            fprintf(stderr, "VIDIOC_ENUM_FRAMEINTERVALS failed: %s\n",
                    strerror(errno));
            goto cleanup;
        }

        print_frmival(&frmival);
        supported = 1;
    }

    print_focus_control(fd, supported);
    rc = EXIT_SUCCESS;

cleanup:
    if (fd != -1)
        close(fd);

    if (rc == EXIT_SUCCESS)
        printf("Camera capabilities summarized.\n");

    return rc;
}

