#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN  4
#define TILT_SERVO_PIN 5

#define BUTTON_UP_PIN  6
#define BUTTON_DOWN_PIN 7
#define BUTTON_LEFT_PIN 8
#define BUTTON_RIGHT_PIN 9

#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000
#define SERVO_CENTER_PULSE_WIDTH 1500

#define PWM_FREQUENCY 50
#define PWM_RANGE     20000
#define STEP_US       10
#define LOOP_DELAY_US 50000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_servo_pulse_width(int pin, int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE_WIDTH) pulse_width = SERVO_MIN_PULSE_WIDTH;
    if (pulse_width > SERVO_MAX_PULSE_WIDTH) pulse_width = SERVO_MAX_PULSE_WIDTH;

    if (gpioServo(pin, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed on pin %d (pulse %d)\n", pin, pulse_width);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install signal handlers\n");
    }

    printf("Pan-Tilt Servo Control\n");
    printf("====================\n");
    printf("Pins: Pan=GPIO%d, Tilt=GPIO%d\n", PAN_SERVO_PIN, TILT_SERVO_PIN);
    printf("       UP=GPIO%d DOWN=GPIO%d LEFT=GPIO%d RIGHT=GPIO%d\n",
           BUTTON_UP_PIN, BUTTON_DOWN_PIN, BUTTON_LEFT_PIN, BUTTON_RIGHT_PIN);
    printf("Center position: %d us\n", SERVO_CENTER_PULSE_WIDTH);
    printf("Press Ctrl+C to exit.\n");

    int pan_pulse = SERVO_CENTER_PULSE_WIDTH;
    int tilt_pulse = SERVO_CENTER_PULSE_WIDTH;

    while (g_running) {
        if (set_servo_pulse_width(PAN_SERVO_PIN, pan_pulse) != 0) break;
        if (set_servo_pulse_width(TILT_SERVO_PIN, tilt_pulse) != 0) break;

        gpioDelay(LOOP_DELAY_US);

        if (gpioRead(BUTTON_UP_PIN) == 0) {
            pan_pulse += STEP_US;
            if (pan_pulse > SERVO_MAX_PULSE_WIDTH) pan_pulse = SERVO_MAX_PULSE_WIDTH;
        }
        if (gpioRead(BUTTON_DOWN_PIN) == 0) {
            pan_pulse -= STEP_US;
            if (pan_pulse < SERVO_MIN_PULSE_WIDTH) pan_pulse = SERVO_MIN_PULSE_WIDTH;
        }
        if (gpioRead(BUTTON_LEFT_PIN) == 0) {
            tilt_pulse += STEP_US;
            if (tilt_pulse > SERVO_MAX_PULSE_WIDTH) tilt_pulse = SERVO_MAX_PULSE_WIDTH;
        }
        if (gpioRead(BUTTON_RIGHT_PIN) == 0) {
            tilt_pulse -= STEP_US;
            if (tilt_pulse < SERVO_MIN_PULSE_WIDTH) tilt_pulse = SERVO_MIN_PULSE_WIDTH;
        }
    }

    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

