#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <pigpio.h>
#include <curl/curl.h>

#define PIR_GPIO 17
#define DEBOUNCE_DELAY_US 2000000
#define POLL_DELAY_US 100000
#define IMAGE_DIR "motion_captures"
#define HTTP_HOST_PORT "<IP>:<port>"
#define HTTP_PATH "/upload"
#define JPEG_QUALITY 85
#define MAX_RESPONSE_SIZE 16384

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int ensure_directory(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        fprintf(stderr, "Error: '%s' exists but is not a directory\n", path);
        return -1;
    }
    if (mkdir(path, 0755) != 0) {
        fprintf(stderr, "Error creating directory '%s': %s\n", path, strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename) {
    char command[512];
    snprintf(command, sizeof(command),
             "raspi-config --capture %s %d", filename, JPEG_QUALITY);
    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error executing capture command: %s\n", strerror(errno));
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Capture command failed (status=%d)\n", status);
        return -1;
    }
    return 0;
}

static size_t write_callback(char *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    strncat((char *)userp, contents, realsize);
    return realsize;
}

static int post_data(const char *url, const char *json_data, const char *filename) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Error initializing libcurl\n");
        return -1;
    }

    long response_code = 0;
    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        fprintf(stderr, "Error creating HTTP headers\n");
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, malloc(MAX_RESPONSE_SIZE));
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);

    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        free(curl_easy_get_response_data(curl));
        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
    if (response_code != 200) {
        fprintf(stderr, "HTTP POST returned non-200 status: %ld\n", response_code);
        free(curl_easy_get_response_data(curl));
        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
        return -1;
    }

    char *response_body = curl_easy_get_response_data(curl);
    if (!response_body) {
        fprintf(stderr, "Error retrieving HTTP response body\n");
        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
        return -1;
    }

    printf("HTTP POST successful (status=%ld), response body: %s\n", response_code, response_body);

    free(response_body);
    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    return 0;
}

static int format_json(char *buffer, size_t buffer_size, const char *filename,
                       const char *timestamp, int motion_detected, int gpio_pin) {
    int ret = snprintf(buffer, buffer_size,
                       "{\"filename\":\"%s\",\"timestamp\":\"%s\",\"motion_detected\":%d,\"gpio_pin\":%d}",
                       filename, timestamp, motion_detected, gpio_pin);
    if (ret < 0 || (size_t)ret >= buffer_size) {
        fprintf(stderr, "Error formatting JSON string\n");
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <IP address> <port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *ip_address = argv[1];
    int port = atoi(argv[2]);
    if (port <= 0 || port > 65535) {
        fprintf(stderr, "Invalid port number: %s\n", argv[2]);
        return EXIT_FAILURE;
    }

    if (ensure_directory(IMAGE_DIR) != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", PIR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO%d\n", PIR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (curl_global_init(CURL_GLOBAL_DEFAULT) != CURLE_OK) {
        fprintf(stderr, "curl_global_init failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        curl_global_cleanup();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring PIR sensor on GPIO%d. Press Ctrl+C to exit.\n", PIR_GPIO);

    while (running) {
        int motion_detected = gpioRead(PIR_GPIO);
        if (motion_detected < 0) {
            fprintf(stderr, "Error reading GPIO%d\n", PIR_GPIO);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (motion_detected) {
            printf("Motion detected on GPIO%d\n", PIR_GPIO);

            struct timespec ts;
            if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
                fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
                gpioDelay(DEBOUNCE_DELAY_US);
                continue;
            }

            char timestamp[64];
            struct tm tm_info;
            localtime_r(&ts.tv_sec, &tm_info);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
            snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%06ld", ts.tv_nsec / 1000);

            char filename[256];
            char json_data[512];

            if (capture_image(filename) != 0) {
                fprintf(stderr, "Image capture failed for GPIO%d\n", PIR_GPIO);
            } else {
                if (format_json(json_data, sizeof(json_data), filename, timestamp, motion_detected, PIR_GPIO) == 0) {
                    printf("Posting data to %s%s\n", HTTP_HOST_PORT, HTTP_PATH);
                    if (post_data(HTTP_HOST_PORT HTTP_PATH, json_data, filename) != 0) {
                        fprintf(stderr, "Failed to post data for GPIO%d\n", PIR_GPIO);
                    }
                }
            }

            gpioDelay(DEBOUNCE_DELAY_US);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    curl_global_cleanup();
    gpioTerminate();
    return EXIT_SUCCESS;
}

