#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>

#define PIR_GPIO 17
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"
#define DEBOUNCE_MS 50
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int capture_image(const char *filename) {
    char command[512];
    int needed = snprintf(command, sizeof(command),
        "raspi-cam-capture -o %s --width 640 --height 480 --quality 85 --timeout 2000 --nopreview",
        filename);
    if (needed < 0 || (size_t)needed >= sizeof(command)) {
        fprintf(stderr, "Error: command buffer too small\n");
        return -1;
    }

    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error: system() failed: %s\n", strerror(errno));
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: capture command failed (status=0x%04x)\n", status);
        return -1;
    }
    return 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open log file %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[unknown time] %s\n", message);
    }
    fclose(fp);
}

static int generate_filename(char *buf, size_t buflen) {
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        return -1;
    }
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        return -1;
    }
    int ms = ts.tv_nsec / 1000000;
    return snprintf(buf, buflen, "%04d%02d%02d_%02d%02d%02d_%03d.jpg",
        tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
        tm.tm_hour, tm.tm_min, tm.tm_sec, ms);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: cannot install signal handler: %s\n", strerror(errno));
        return 1;
    }

    struct stat st;
    if (stat(IMAGE_DIR, &st) != 0) {
        fprintf(stderr, "Error: images directory '%s' not accessible: %s\n", IMAGE_DIR, strerror(errno));
        return 1;
    }
    if (!S_ISDIR(st.st_mode)) {
        fprintf(stderr, "Error: '%s' exists but is not a directory\n", IMAGE_DIR);
        return 1;
    }

    printf("Motion detection started on GPIO%d. Press Ctrl+C to exit.\n", PIR_GPIO);
    log_event("Program started");

    int last_state = 0;
    struct timespec last_event_time = {0, 0};

    while (program_running) {
        int current_state = gpioRead(PIR_GPIO);
        if (current_state < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d\n", PIR_GPIO);
            log_event("Error: gpioRead failed");
            break;
        }

        if (current_state == 1 && last_state == 0) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            long elapsed_ms = (now.tv_sec - last_event_time.tv_sec) * 1000L +
                              (now.tv_nsec - last_event_time.tv_nsec) / 1000000L;

            if (elapsed_ms >= DEBOUNCE_MS) {
                char filename[256];
                if (generate_filename(filename, sizeof(filename)) < 0) {
                    fprintf(stderr, "Error: failed to generate filename\n");
                    log_event("Error: filename generation failed");
                } else {
                    char log_message[512];
                    snprintf(log_message, sizeof(log_message), "Motion detected on GPIO%d, capturing %s", PIR_GPIO, filename);
                    log_event(log_message);

                    if (capture_image(filename) == 0) {
                        snprintf(log_message, sizeof(log_message), "Image captured and saved as %s", filename);
                        log_event(log_message);
                    } else {
                        snprintf(log_message, sizeof(log_message), "Error: image capture failed for %s", filename);
                        log_event(log_message);
                    }
                }
                last_event_time = now;
            }
        }
        last_state = current_state;
        usleep(POLL_TIMEOUT_MS * 1000);
    }

    log_event("Program stopped");
    printf("Exiting.\n");
    return 0;
}

