#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define OUTPUT_FILE "cropped.yuv"

static volatile sig_atomic_t stop_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

int main(void) {
    int fd = -1;
    FILE *fp = NULL;
    void *buffer = NULL;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    enum v4l2_buf_type type;
    unsigned int width = 0, height = 0;
    unsigned int requested_width = 640, requested_height = 480;
    unsigned int pixel_format = V4L2_PIX_FMT_YUYV;
    unsigned char *crop_buffer = NULL;
    int exit_code = EXIT_SUCCESS;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        perror("open(" DEVICE_NAME ")");
        return EXIT_FAILURE;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = requested_width;
    fmt.fmt.pix.height = requested_height;
    fmt.fmt.pix.pixelformat = pixel_format;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        exit_code = EXIT_FAILURE;
        goto cleanup;
    }

    width = fmt.fmt.pix.width;
    height = fmt.fmt.pix.height;
    if (width != requested_width || height != requested_height) {
        fprintf(stderr, "Warning: device adjusted size to %ux%u\n", width, height);
    }
    if (fmt.fmt.pix.pixelformat != pixel_format) {
        fprintf(stderr, "Warning: device did not accept YUYV; got 0x%08x\n", fmt.fmt.pix.pixelformat);
        exit_code = EXIT_FAILURE;
        goto cleanup;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        exit_code = EXIT_FAILURE;
        goto cleanup;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        exit_code = EXIT_FAILURE;
        goto cleanup;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        perror("VIDIOC_QUERYBUF");
        exit_code = EXIT_FAILURE;
        goto cleanup;
    }

    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("mmap");
        exit_code = EXIT_FAILURE;
        goto cleanup;
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        exit_code = EXIT_FAILURE;
        goto cleanup;
    }

    crop_buffer = malloc(CROP_WIDTH * CROP_HEIGHT * 2);
    if (!crop_buffer) {
        perror("malloc");
        exit_code = EXIT_FAILURE;
        goto cleanup;
    }

    fd = open(OUTPUT_FILE, "wb");
    if (fd == -1) {
        perror("open(" OUTPUT_FILE ")");
        exit_code = EXIT_FAILURE;
        goto cleanup;
    }

    while (!stop_flag) {
        fd_set fds;
        struct timeval tv;
        int r;

        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        tv.tv_sec = 2;
        tv.tv_usec = 0;

        r = select(fd + 1, &fds, NULL, NULL, &tv);
        if (r == -1) {
            if (errno == EINTR) continue;
            perror("select");
            exit_code = EXIT_FAILURE;
            break;
        }
        if (r == 0) {
            fprintf(stderr, "select timeout\n");
            exit_code = EXIT_FAILURE;            break;
        }

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = 0;

        if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
            if (errno == EAGAIN) continue;
            perror("VIDIOC_DQBUF");
            exit_code = EXIT_FAILURE;
            break;
        }

        if (buf.bytesused < (unsigned int)(width * height * 2)) {
            fprintf(stderr, "Short buffer: %u bytes\n", buf.bytesused);
            continue;
        }

        if (width != buf.bytesperline || height != buf.imageheight) {
            fprintf(stderr, "Warning: unexpected buffer dimensions: %ux%u\n", buf.bytesperline, buf.imageheight);
        }

        if (width != requested_width || height != requested_height) {
            fprintf(stderr, "Warning: captured size %ux%u, requested %ux%u\n", width, height, requested_width, requested_height);
        }

        if (width != buf.bytesperline || height != buf.imageheight) {
            fprintf(stderr, "Warning: buffer lines %u, height %u\n", buf.bytesperline, buf.imageheight);
        }

        if (buf.m.maps[0].length < width * height * 2) {
            fprintf(stderr, "Short map: %u bytes\n", buf.m.maps[0].length);
            continue;
        }

        if (fwrite(buffer, 1, width * height * 2, fp) != (size_t)(width * height * 2)) {
            perror("fwrite");
            exit_code = EXIT_FAILURE;
            break;
        }

        for (int i = 0; i < height; i++) {
            for (int j = 0; j < width; j++) {
                int src_index = (i * width + j) * 2;
                int dst_index = (i * CROP_WIDTH + (j % CROP_WIDTH)) * 2;
                crop_buffer[dst_index]     = buffer[src_index];
                crop_buffer[dst_index + 1] = buffer[src_index + 1];
            }
        }

        if (fwrite(crop_buffer, 1, CROP_WIDTH * CROP_HEIGHT * 2, fp) != (size_t)(CROP_WIDTH * CROP_HEIGHT * 2)) {
            perror("fwrite (crop)");
            exit_code = EXIT_FAILURE;
            break;
        }

        if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("VIDIOC_QBUF");
            exit_code = EXIT_FAILURE;
            break;
        }
    }

    if (stop_flag) {
        fprintf(stderr, "Interrupted by signal\n");
    }

cleanup:
    if (fd != -1) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        if (fp) fclose(fp);
    }
    if (buffer && buffer != MAP_FAILED) {
        munmap(buffer, buf.length);
    }
    if (crop_buffer) free(crop_buffer);
    if (fd != -1) close(fd);
    return exit_code;
}

