#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <ctype.h>
#include <pigpio.h>

#define PAN_SERVO_PIN  17
#define TILT_SERVO_PIN 18
#define SERVO_FREQ_HZ  50
#define SERVO_RANGE   180
#define STEP_SIZE      5
#define DELAY_US      100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* Convert angle (0-180) to a 10-bit PWM pulse width (500-2500 us). */
static int angle_to_pulsewidth(int angle)
{
    if (angle < 0)   angle = 0;
    if (angle > 180) angle = 180;
    return 500 + (angle * 2000) / 180;
}

/* Set a servo to the given angle. Returns 0 on success, -1 on error. */
static int set_servo_angle(int pin, int angle)
{
    int pw = angle_to_pulsewidth(angle);
    if (gpioServo(pin, pw) < 0) {
        fprintf(stderr, "Error: gpioServo failed on pin %d (pw=%d)\n", pin, pw);
        return -1;
    }
    return 0;
}

/* Initialize pigpio and start both servos at 90 degrees. */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return -1;
    }

    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pan pin %d\n", PAN_SERVO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for tilt pin %d\n", TILT_SERVO_PIN);
        gpioTerminate();
        return -1;
    }

    /* 50 Hz, 10-bit resolution, no auxiliary data */
    if (gpioSetPWMfrequency(PAN_SERVO_PIN, SERVO_FREQ_HZ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for pan pin %d\n", PAN_SERVO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(TILT_SERVO_PIN, SERVO_FREQ_HZ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for tilt pin %d\n", TILT_SERVO_PIN);
        gpioTerminate();
        return -1;
    }

    /* Start both servos at neutral (90 degrees) */
    if (set_servo_angle(PAN_SERVO_PIN, 90) < 0 ||
        set_servo_angle(TILT_SERVO_PIN, 90) < 0) {
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* Cleanup: set servos to neutral, terminate pigpio, return 0. */
static void cleanup_gpio(void)
{
    set_servo_angle(PAN_SERVO_PIN, 90);
    set_servo_angle(TILT_SERVO_PIN, 90);
    gpioTerminate();
}

int main(void)
{
    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (initialize_gpio() < 0) {
        return 1;
    }

    printf("Servo control ready. Press 'q' or Ctrl+C to exit.\n");
    fflush(stdout);

    int pan_angle  = 90;
    int tilt_angle = 90;

    while (g_running) {
        int c = getchar();

        if (c == 'q' || c == 'Q') {
            break;
        }

        if (c == '\n' || c == '\r') {
            continue;
        }

        if (c == 'h' || c == 'H') {
            tilt_angle += STEP_SIZE;
            if (tilt_angle > 180) tilt_angle = 180;
            if (set_servo_angle(TILT_SERVO_PIN, tilt_angle) < 0) {
                fprintf(stderr, "Error: failed to set tilt servo angle\n");
            }
        } else if (c == 'l' || c == 'L') {
            tilt_angle -= STEP_SIZE;
            if (tilt_angle < 0) tilt_angle = 0;
            if (set_servo_angle(TILT_SERVO_PIN, tilt_angle) < 0) {
                fprintf(stderr, "Error: failed to set tilt servo angle\n");
            }
        } else if (c == 'k' || c == 'K') {
            pan_angle += STEP_SIZE;
            if (pan_angle > 180) pan_angle = 180;
            if (set_servo_angle(PAN_SERVO_PIN, pan_angle) < 0) {
                fprintf(stderr, "Error: failed to set pan servo angle\n");
            }
        } else if (c == 'j' || c == 'J') {
            pan_angle -= STEP_SIZE;
            if (pan_angle < 0) pan_angle = 0;
            if (set_servo_angle(PAN_SERVO_PIN, pan_angle) < 0) {
                fprintf(stderr, "Error: failed to set pan servo angle\n");
            }
        } else if (c == 'd' || c == 'D') {
            tilt_angle += STEP_SIZE;
            if (tilt_angle > 180) tilt_angle = 180;
            if (set_servo_angle(TILT_SERVO_PIN, tilt_angle) < 0) {
                fprintf(stderr, "Error: failed to set tilt servo angle\n");
            }
        } else if (c == 's' || c == 'S') {
            tilt_angle -= STEP_SIZE;
            if (tilt_angle < 0) tilt_angle = 0;
            if (set_servo_angle(TILT_SERVO_PIN, tilt_angle) < 0) {
                fprintf(stderr, "Error: failed to set tilt servo angle\n");
            }
        } else if (c == 'w' || c == 'W') {
            pan_angle += STEP_SIZE;
            if (pan_angle > 180) pan_angle = 180;
            if (set_servo_angle(PAN_SERVO_PIN, pan_angle) < 0) {
                fprintf(stderr, "Error: failed to set pan servo angle\n");
            }
        } else if (c == 'x' || c == 'X') {
            pan_angle -= STEP_SIZE;
            if (pan_angle < 0) pan_angle = 0;
            if (set_servo_angle(PAN_SERVO_PIN, pan_angle) < 0) {
                fprintf(stderr, "Error: failed to set pan servo angle\n");
            }
        } else if (c == 'c' || c == 'C') {
            printf("Pan: %3d  Tilt: %3d\n", pan_angle, tilt_angle);
            fflush(stdout);
        } else {
            /* Unknown character: beep and discard */
            putchar(c);
            fflush(stdout);
        }

        usleep(DELAY_US);
    }

    cleanup_gpio();
    printf("\nExiting cleanly.\n");
    return 0;
}

