#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define OLED_WIDTH 128
#define OLED_HEIGHT 64
#define OLED_PAGES (OLED_HEIGHT / 8)

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, unsigned char cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_data(int fd, unsigned char data) {
    unsigned char buf[2] = {0x40, data};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed (data 0x%02X): %s\n", data, strerror(errno));
        return -1;
    }
    return 0;
}

static int oled_init(int fd) {
    if (i2c_write_cmd(fd, 0xAE) < 0) return -1;
    if (i2c_write_cmd(fd, 0xD5) < 0) return -1;
    if (i2c_write_cmd(fd, 0x80) < 0) return -1;
    if (i2c_write_cmd(fd, 0xA8) < 0) return -1;
    if (i2c_write_cmd(fd, 0x3F) < 0) return -1;
    if (i2c_write_cmd(fd, 0xD3) < 0) return -1;
    if (i2c_write_cmd(fd, 0x00) < 0) return -1;
    if (i2c_write_cmd(fd, 0x40) < 0) return -1;
    if (i2c_write_cmd(fd, 0x8D) < 0) return -1;
    if (i2c_write_cmd(fd, 0x14) < 0) return -1;
    if (i2c_write_cmd(fd, 0x20) < 0) return -1;
    if (i2c_write_cmd(fd, 0x00) < 0) return -1;
    if (i2c_write_cmd(fd, 0xA1) < 0) return -1;
    if (i2c_write_cmd(fd, 0xC8) < 0) return -1;
    if (i2c_write_cmd(fd, 0xDA) < 0) return -1;
    if (i2c_write_cmd(fd, 0x12) < 0) return -1;
    if (i2c_write_cmd(fd, 0x81) < 0) return -1;
    if (i2c_write_cmd(fd, 0xCF) < 0) return -1;
    if (i2c_write_cmd(fd, 0xD9) < 0) return -1;
    if (i2c_write_cmd(fd, 0xF1) < 0) return -1;
    if (i2c_write_cmd(fd, 0xDB) < 0) return -1;
    if (i2c_write_cmd(fd, 0x40) < 0) return -1;
    if (i2c_write_cmd(fd, 0xA4) < 0) return -1;
    if (i2c_write_cmd(fd, 0xA6) < 0) return -1;
    if (i2c_write_cmd(fd, 0xAF) < 0) return -1;
    return 0;
}

static int oled_clear(int fd) {
    for (int page = 0; page < OLED_PAGES; page++) {
        if (i2c_write_cmd(fd, 0xB0 + page) < 0) return -1;
        if (i2c_write_cmd(fd, 0x00) < 0) return -1;
        if (i2c_write_cmd(fd, 0x10) < 0) return -1;
        unsigned char zeros[128];
        memset(zeros, 0, sizeof(zeros));
        for (int i = 0; i < 128; i++) {
            if (i2c_write_data(fd, zeros[i]) < 0) return -1;
        }
    }
    return 0;
}

static int oled_set_cursor(int fd, int page, int col) {
