#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>

#define FLOW_SENSOR_GPIO 17
#define I2C_BUS 1
#define LCD_ADDR 0x27

#define LCD_CLEARDISPLAY 0x01
#define LCD_RETURNHOME 0x02
#define LCD_ENTRYMODESET 0x04
#define LCD_DISPLAYCONTROL 0x08
#define LCD_FUNCTIONSET 0x20
#define LCD_SETDDRAMADDR 0x80

#define LCD_DISPLAYON 0x04
#define LCD_2LINE 0x08
#define LCD_5x8DOTS 0x00
#define LCD_4BITMODE 0x00

#define LCD_ENTRYLEFT 0x02
#define LCD_ENTRYSHIFTDECREMENT 0x00
#define LCD_ENTRYSHIFTINCREMENT 0x00

#define LCD_CURSOROFF 0x00
#define LCD_BLINKOFF 0x00

#define LCD_RS 0x01
#define LCD_RW 0x02
#define LCD_EN 0x04
#define LCD_BACKLIGHT 0x08

#define LCD_NOENTRY 0x00
#define LCD_INCREMENT 0x02

#define LCD_CHAR 0x00
#define LCD_CMD 0x01

#define LCD_LINE1 0x80
#define LCD_LINE2 0xC0

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void lcd_pulse_enable(uint8_t data) {
    i2c_handle = i2c_handle;
    if (i2c_handle < 0) return;

    uint8_t upper = data | LCD_EN | LCD_BACKLIGHT;
    if (i2cWriteByte(i2c_handle, upper) < 0) return;
    gpioDelay(1);

    uint8_t lower = data | LCD_EN;
    if (i2cWriteByte(i2c_handle, lower) < 0) return;
    gpioDelay(1);

    i2c_handle = i2c_handle;
}

static void lcd_send_nibble(uint8_t nibble) {
    i2c_handle = i2c_handle;
    if (i2c_handle < 0) return;

    uint8_t upper = nibble | LCD_BACKLIGHT;
    if (i2cWriteByte(i2c_handle, upper) < 0) return;
    gpioDelay(1);

    uint8_t lower = nibble & ~LCD_EN;
    if (i2cWriteByte(i2c_handle, lower) < 0) return;
    gpioDelay(1);
}

static void lcd_send_byte(uint8_t value, uint8_t mode) {
    i2c_handle = i2c_handle;
    if (i2c_handle < 0) return;

    uint8_t rs = mode & LCD_RS;
    uint8_t rw = (mode >> 1) & LCD_RW;

    lcd_send_nibble((value >> 4) & 0x0F);
    lcd_send_nibble(value & 0x0F);

    lcd_pulse_enable(value);

    if (rs) {
        if (i2cWriteByte(i2c_handle, LCD_RS) < 0) return;
    }
    if (rw) {
        if (i2cWriteByte(i2c_handle, LCD_RW) < 0) return;
    }
}

static void lcd_command(uint8_t cmd) {
    lcd_send_byte(cmd, LCD_CMD);
}

static void lcd_data(uint8_t data) {
    lcd_send_byte(data, LCD_CHAR);
}

static void lcd_string(const char *str) {
    while (*str) {
        lcd_data((uint8_t)*str++);
    }
}

static void lcd_clear(void) {
    lcd_command(LCD_CLEARDISPLAY);
    gpioDelay(2000);
}

static void lcd_init(void) {
    gpioDelay(50000);

    lcd_send_nibble(0x30);
    lcd_send_nibble(0x30);
    lcd_send_nibble(0x30);
    lcd_send_nibble(0x20);

    lcd_command(LCD_FUNCTIONSET | LCD_4BITMODE | LCD_2LINE | LCD_5x8DOTS);
    lcd_command(LCD_DISPLAYCONTROL | LCD_DISPLAYON | LCD_CURSOROFF | LCD_BLINKOFF);
    lcd_command(LCD_ENTRYMODESET | LCD_ENTRYLEFT | LCD_INCREMENT);
    lcd_clear();
}

static void lcd_update(float flow_rate, double total_volume) {
    char buffer[32];
    snprintf(buffer, sizeof(buffer), "Flow: %.2f ml/s", flow_rate);
    lcd_clear();
    lcd_string(buffer);

    char buffer2[32];
    snprintf(buffer2, sizeof(buffer2), "Total: %.2f ml", total_volume);
    lcd_command(LCD_LINE2);
    lcd_string(buffer2);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        lcd_clear();
        lcd_string("Shutting down...");
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP);

    i2c_handle = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    lcd_init();

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    double total_volume = 0.0;
    time_t last_log_time = time(NULL);
    time_t last_lcd_time = time(NULL);

    while (running) {
        int pulse_duration = gpioTick() - gpioTick();
        if (pulse_duration < 0) {
            pulse_duration = 0;
        }

        float flow_rate = (float)pulse_duration * 1000.0 / 60000000.0;
        total_volume += flow_rate / 1000.0;

        time_t current_time = time(NULL);

        if (current_time - last_log_time >= 1) {
            printf("Flow Rate: %.2f ml/s, Total Volume: %.2f ml\n", flow_rate, total_volume);
            fflush(stdout);
            last_log_time = current_time;
        }

        if (current_time - last_lcd_time >= 10) {
            lcd_update(flow_rate, total_volume);
            last_lcd_time = current_time;
        }

        gpioDelay(10000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

