#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/i2c-dev.h>

#define PULSE_PIN      17
#define SPI_DEVICE     "/dev/spidev0.0"
#define I2C_DEVICE     "/dev/i2c-1"
#define LCD_I2C_ADDR   0x27
#define LCD_WIDTH      16

#define SPI_SPEED_HZ   1000000
#define SPI_BITS        8
#define SPI_MODE       0

#define SAMPLE_WINDOW_MS 500
#define SAMPLE_WINDOW_US (SAMPLE_WINDOW_MS * 1000)

#define LCD_CHR  1
#define LCD_CMD  0

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void sleep_us(uint32_t us) {
    struct timespec ts = {
        .tv_sec  = us / 1000000,
        .tv_nsec = (long)(us % 1000000) * 1000
    };
    nanosleep(&ts, NULL);
}

static void sleep_ms(uint32_t ms) {
    sleep_us(ms * 1000);
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = len,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
        .tx_nbits      = 0,
        .rx_nbits      = 0,
        .pad           = 0
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        return -1;
    }
    return 0;
}

static int read_mcp3008(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    if (spi_transfer(fd, tx, rx, 3) < 0) {
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static void lcd_strobe(int fd, uint8_t data) {
    uint8_t tx[4] = {
        (uint8_t)(data | 0x01),
        (uint8_t)(data & 0xFF),
        0x00,
        0x00
    };
    uint8_t rx[4] = {0};
    spi_transfer(fd, tx, rx, 4);
    sleep_us(1);
}

static void lcd_byte(int fd, uint8_t bits, bool is_data) {
    uint8_t bits_high = (bits & 0xF0) | (is_data ? LCD_CHR : LCD_CMD);
    uint8_t bits_low  = ((bits << 4) & 0xF0) | (is_data ? LCD_CHR : LCD_CMD);

    lcd_strobe(fd, bits_high);
    lcd_strobe(fd, bits_low);
}

static void lcd_init(int fd) {
    sleep_ms(50);
    lcd_byte(fd, 0x33, false);
    lcd_byte(fd, 0x32, false);
    lcd_byte(fd, 0x28, false);
    lcd_byte(fd, 0x0C, false);
    lcd_byte(fd, 0x06, false);
    lcd_byte(fd, 0x01, false);
    sleep_ms(2);
}

static void lcd_string(int fd, const char *s) {
    while (*s) {
        lcd_byte(fd, (uint8_t)*s++, LCD_CHR);
    }
}

static void lcd_clear(int fd) {
    lcd_byte(fd, 0x01, false);
    sleep_ms(2);
}

static void lcd_set_cursor(int fd, int row, int col) {
    uint8_t addr = (row == 0) ? 0x80 : 0xC0;
    lcd_byte(fd, addr + col, false);
}

static void lcd_print(int fd, const char *speed_str, const char *dir_str) {
    lcd_clear(fd);
    lcd_set_cursor(fd, 0, 0);
    lcd_string(fd, speed_str);
    lcd_set_cursor(fd, 1, 0);
    lcd_string(fd, dir_str);
}

static void pulse_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
}

int main(void) {
    int spi_fd = -1;
    int i2c_fd = -1;
    int pulse_count = 0;
    int wind_speed = 0;
    char speed_str[16];
    char dir_str[16];
    int wind_direction = 0;
    int adc_value = 0;
    int consecutive_failures = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return 1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        goto cleanup_spi;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        goto cleanup_spi;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        goto cleanup_spi;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("open(" I2C_DEVICE ")");
        goto cleanup_spi;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LCD_I2C_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        goto cleanup_i2c;
    }

    lcd_init(i2c_fd);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        goto cleanup_i2c;
    }

    gpioSetMode(PULSE_PIN, PI_INPUT);
    gpioSetPullUpDown(PULSE_PIN, PI_PUD_DOWN);

    if (gpioSetISRFuncEx(PULSE_PIN, RISING_EDGE, 0, pulse_isr, NULL) < 0) {
        fprintf(stderr, "gpioSetISRFuncEx failed\n");
        goto cleanup_gpio;
    }

    printf("Anemometer and Wind Vane Monitoring Started...\n");

    while (g_running) {
        pulse_count = 0;
        sleep_ms(SAMPLE_WINDOW_MS);

        if (pulse_count == 0) {
            wind_speed = 0;
        } else {
            wind_speed = (int)((float)pulse_count / SAMPLE_WINDOW_MS * 60.0f);
        }

        adc_value = read_mcp3008(spi_fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "SPI read failed: %s\n", strerror(errno));
            consecutive_failures++;
            if (consecutive_failures > 10) {
                fprintf(stderr, "Too many SPI failures, aborting.\n");
                break;
            }
            wind_direction = -1;
        } else {
            if (adc_value == 0 || adc_value == 1023) {
                fprintf(stderr, "ADC reading at rail (%d) - sensor absent or wiring fault.\n", adc_value);
                wind_direction = -1;
            } else {
                wind_direction = (adc_value * 180) / 1023;
            }
        }

        snprintf(speed_str, sizeof(speed_str), "Speed: %d mph", wind_speed);
        snprintf(dir_str, sizeof(dir_str), "Dir: %d deg", wind_direction);

        lcd_print(i2c_fd, speed_str, dir_str);

        consecutive_failures = 0;
    }

cleanup_gpio:
    gpioSetISRFuncEx(PULSE_PIN, RISING_EDGE, 0, NULL, NULL);
    gpioTerminate();

cleanup_i2c:
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

cleanup_spi:
    if (spi_fd >= 0) {
        close(spi_fd);
    }

    printf("Exiting gracefully...\n");
    return 0;
}

