#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define LCD_I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_CHR 1
#define LCD_CMD 0
#define LCD_LINE_1 0x80
#define LCD_LINE_2 0xC0
#define LCD_BACKLIGHT 0x08
#define LCD_ENABLE 0x04

#define GPIO_PIN 17
#define SAMPLE_INTERVAL_SEC 1
#define MAX_FLOW_RATE 100.0
#define ZERO_PULSE_TIMEOUT_SEC 5

static volatile sig_atomic_t running = 1;
static volatile int pulse_count = 0;
static volatile uint32_t last_pulse_tick = 0;
static volatile int pulse_active = 0;

static int i2c_handle = -1;
static int lcd_initialized = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void pulse_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 1) {
        pulse_count++;
        last_pulse_tick = tick;
        pulse_active = 1;
    }
}

static int lcd_strobe(int handle, uint8_t data) {
    if (i2cWriteByte(handle, data | LCD_ENABLE) < 0) return -1;
    gpioDelay(1);
    if (i2cWriteByte(handle, data & ~LCD_ENABLE) < 0) return -1;
    gpioDelay(1);
    return 0;
}

static int lcd_byte(int handle, uint8_t bits, uint8_t mode) {
    uint8_t high = (bits & 0xF0) | mode | LCD_BACKLIGHT;
    uint8_t low = ((bits << 4) & 0xF0) | mode | LCD_BACKLIGHT;
    if (lcd_strobe(handle, high) < 0) return -1;
    if (lcd_strobe(handle, low) < 0) return -1;
    return 0;
}

static int lcd_init(int handle) {
    gpioDelay(50);
    if (lcd_byte(handle, 0x33, LCD_CMD) < 0) return -1;
    gpioDelay(50);
    if (lcd_byte(handle, 0x32, LCD_CMD) < 0) return -1;
    gpioDelay(50);
    if (lcd_byte(handle, 0x28, LCD_CMD) < 0) return -1;
    if (lcd_byte(handle, 0x0C, LCD_CMD) < 0) return -1;
    if (lcd_byte(handle, 0x06, LCD_CMD) < 0) return -1;
    if (lcd_byte(handle, 0x01, LCD_CMD) < 0) return -1;
    gpioDelay(2000);
    return 0;
}

static int lcd_string(int handle, const char *s) {
    while (*s) {
        if (lcd_byte(handle, (uint8_t)*s++, LCD_CHR) < 0) return -1;
    }
    return 0;
}

static int lcd_clear(int handle) {
    return lcd_byte(handle, 0x01, LCD_CMD);
}

static int lcd_set_cursor(int handle, uint8_t line) {
    return lcd_byte(handle, line, LCD_CMD);
}

static void cleanup(void) {
    if (lcd_initialized) {
        lcd_clear(i2c_handle);
        lcd_string(i2c_handle, "Shutting down...");
        gpioDelay(1000000);
        i2cClose(i2c_handle);
        lcd_initialized = 0;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, LCD_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d).\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (lcd_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: LCD initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    lcd_initialized = 1;

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input.\n", GPIO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(GPIO_PIN, pulse_callback) < 0) {
        fprintf(stderr, "Error: Failed to set alert on GPIO%d.\n", GPIO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Water flow monitoring started. Press Ctrl+C to exit.\n");

    int zero_pulse_count = 0;
    int zero_pulse_warned = 0;

    while (running) {
        uint32_t start_tick = gpioTick();
        int pulses = pulse_count;
        pulse_count = 0;
        uint32_t elapsed = gpioTick() - start_tick;

        if (elapsed == 0 || elapsed > SAMPLE_INTERVAL_SEC * 1000000) {
            fprintf(stderr, "Warning: sample interval out of range (%u us).\n", elapsed);
            continue;
        }

        double flow_rate = (double)pulses * 60.0 / SAMPLE_INTERVAL_SEC;

        if (flow_rate > MAX_FLOW_RATE) {
            flow_rate = MAX_FLOW_RATE;
        }

        char line1[17];
        char line2[17];
        snprintf(line1, sizeof(line1), "Flow Rate:");
