#include <pigpio.h>

#define DELAY_US 800
#define MATRIX_SIZE 8

/* Row pins (anodes) */
static const int row_pins[MATRIX_SIZE] = {17, 18, 27, 22, 23, 24, 25, 4};
/* Column pins (cathodes) */
static const int col_pins[MATRIX_SIZE] = {5, 6, 12, 13, 19, 16, 26, 20};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_mode(int pin, unsigned mode) {
    if (gpioSetMode(pin, mode) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", pin);
        return -1;
    }
    return 0;
}

static int safe_write(int pin, unsigned level) {
    if (gpioWrite(pin, level) < 0) {
        fprintf(stderr, "Error: gpioWrite failed for pin %d\n", pin);
        return -1;
    }
    return 0;
}

static void clear_matrix(void) {
    for (int i = 0; i < MATRIX_SIZE; i++) {
        safe_write(row_pins[i], 0);
        safe_write(col_pins[i], 1);
    }
}

static void render_row(int row_idx, int *row_state, int *col_state) {
    if (safe_write(row_pins[row_idx], 1) < 0) return;
    for (int c = 0; c < MATRIX_SIZE; c++) {
        if (safe_write(col_pins[c], 0) < 0) return;
        if (row_state[row_idx] == col_state[c]) {
            safe_write(col_pins[c], 1);
        }
    }
}

static void left_shift(int *row_state, int *col_state) {
    int temp[MATRIX_SIZE];
    for (int i = 0; i < MATRIX_SIZE; i++) {
        temp[i] = (i < MATRIX_SIZE - 1) ? col_state[i + 1] : col_state[0];
    }
    for (int i = 0; i < MATRIX_SIZE; i++) {
        col_state[i] = temp[i];
    }
    for (int i = 0; i < MATRIX_SIZE; i++) {
        row_state[i] = (i < MATRIX_SIZE - 1) ? row_state[i + 1] : row_state[MATRIX_SIZE - 1];
    }
}

static void right_shift(int *row_state, int *col_state) {
    int temp[MATRIX_SIZE];
    for (int i = 0; i < MATRIX_SIZE; i++) {
        temp[i] = (i > 0) ? col_state[i - 1] : col_state[MATRIX_SIZE - 1];
    }
    for (int i = 0; i < MATRIX_SIZE; i++) {
        col_state[i] = temp[i];
    }
    for (int i = 0; i < MATRIX_SIZE; i++) {
        row_state[i] = (i < MATRIX_SIZE - 1) ? row_state[i + 1] : row_state[0];
    }
}

int main(void) {
