        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < MATRIX_SIZE; i++) {
        if (safe_set_mode(row_pins[i], PI_OUTPUT) < 0 ||
            safe_set_mode(col_pins[i], PI_OUTPUT) < 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    int row_state[MATRIX_SIZE] = {0};
    int col_state[MATRIX_SIZE] = {0};

    for (int i = 0; i < MATRIX_SIZE; i++) {
        row_state[i] = (i % 2 == 0) ? 1 : 0;
        col_state[i] = (i % 2 == 0) ? 1 : 0;
    }

    while (running) {
        for (int i = 0; i < MATRIX_SIZE && running; i++) {
            render_row(i, row_state, col_state);
            gpioDelay(DELAY_US);
        }
        if (running) {
            left_shift(row_state, col_state);
        }
        for (int i = 0; i < MATRIX_SIZE && running; i++) {
            render_row(i, row_state, col_state);
            gpioDelay(DELAY_US);
        }
        if (running) {
            right_shift(row_state, col_state);
        }
    }

    clear_matrix();
    gpioTerminate();
    return EXIT_SUCCESS;
}

