#include <pigpio.h>

#define DELAY_MS 150
#define MATRIX_SIZE 8

/* Column cathodes (BCM numbering) */
static const int col_pins[MATRIX_SIZE] = {14, 15, 18, 23, 24, 25, 8, 7};
/* Row anodes (BCM numbering) */
static const int row_pins[MATRIX_SIZE] = {2, 3, 4, 17, 27, 22, 10, 9};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_mode(int pin, unsigned mode) {
    if (gpioSetMode(pin, mode) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", pin);
        return -1;
    }
    return 0;
}

static int safe_write(int pin, unsigned level) {
    if (gpioWrite(pin, level) < 0) {
        fprintf(stderr, "Error: gpioWrite failed for pin %d\n", pin);
        return -1;
    }
    return 0;
}

static int clear_matrix(void) {
    /* All column cathodes HIGH (inactive) */
    for (int i = 0; i < MATRIX_SIZE; i++) {
        if (safe_write(col_pins[i], 1) < 0) return -1;
    }
    /* All row anodes LOW (inactive) */
    for (int i = 0; i < MATRIX_SIZE; i++) {
        if (safe_write(row_pins[i], 0) < 0) return -1;
    }
    return 0;
}

static int display_column(int col) {
    /* Turn off previous column */
    if (safe_write(col_pins[col], 1) < 0) return -1;
    /* Light this column: cathode LOW, anodes HIGH */
    for (int i = 0; i < MATRIX_SIZE; i++) {
        if (safe_write(row_pins[i], 1) < 0) return -1;
    }
    gpioDelay(DELAY_MS * 1000);
    /* Turn off this column */
    if (safe_write(col_pins[col], 1) < 0) return -1;
    /* Turn off all anodes */
    for (int i = 0; i < MATRIX_SIZE; i++) {
        if (safe_write(row_pins[i], 0) < 0) return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Register signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
