    for (int i = 0; i < MATRIX_SIZE; i++) {
        if (safe_set_mode(col_pins[i], PI_OUTPUT) < 0 ||
            safe_set_mode(row_pins[i], PI_OUTPUT) < 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* Ensure matrix starts blank */
    if (clear_matrix() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Wave animation running. Press Ctrl+C to exit.\n");

    while (running) {
        for (int col = 0; col < MATRIX_SIZE && running; col++) {
            if (display_column(col) < 0) {
                fprintf(stderr, "Error during display, exiting.\n");
                break;
            }
        }
    }

    /* Clean shutdown: turn off all LEDs */
    for (int i = 0; i < MATRIX_SIZE; i++) {
        safe_write(row_pins[i], 0);
        safe_write(col_pins[i], 1);
    }
    gpioTerminate();
    printf("\nCleanup complete.\n");
    return EXIT_SUCCESS;
}

