            }
        }
    }

    /* Clean shutdown: turn off all LEDs */
    for (int i = 0; i < MATRIX_SIZE; i++) {
        safe_write(row_pins[i], 0);
        safe_write(col_pins[i], 1);
    }
    gpioTerminate();
    printf("\nCleanup complete.\n");
    return EXIT_SUCCESS;
}

