/*
 * VL53L3CX multi-target Time-of-Flight sensor reader for Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   VL53L3CX SDA -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   VL53L3CX SCL -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   VL53L3CX VDD -> 3.3 V (pin 1)
 *   VL53L3CX GND -> GND  (pin 6)
 *
 * Build:  gcc -O2 -Wall -Wextra -o vl53l3cx_reader vl53l3cx_reader.c
 * Run:    sudo ./vl53l3cx_reader   (I2C bus requires root or i2c group membership)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define VL53L3CX_ADDR  0x29

/* ---- VL53L3CX register map (subset) ---- */
#define REG_SOFT_RESET                      0x0003
#define REG_I2C_SLAVE_DEVICE_ADDRESS        0x0001
#define REG_SYSTEM_MODE_START              0x0007
#define REG_RESULT_INTERRUPT_STATUS         0x0044
#define REG_RESULT_RANGE_STATUS             0x0046
#define REG_RESULT_DISTANCE                 0x0096
#define REG_RESULT_PEAK_SIGNAL_COUNT_RATE   0x0098
#define REG_RESULT_AMBIENT_COUNT_RATE       0x009A
#define REG_RESULT_SIGNAL_COUNT_RATE        0x009C
#define REG_RESULT_ALS_VIS_COUNT_RATE       0x009E
#define REG_RESULT_ALS_IR_COUNT_RATE        0x00A0

/* ---- VL53L3CX model / firmware constants ---- */
#define VL53L3CX_MODEL_ID                   0xEA
#define VL53L3CX_EXPECTED_MODEL_ID          0xEA

#define POLL_INTERVAL_MS                   100
#define MAX_TARGETS                        4

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register (big-endian on the wire).                   */
static bool i2c_write_reg16(int fd, uint16_t reg, uint16_t value)
{
    uint8_t buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return false;
    }
    return true;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register (big-endian on the wire).                    */
static bool i2c_read_reg16(int fd, uint16_t reg, uint16_t *out)
{
    uint8_t wbuf[2] = { (reg >> 8) & 0xFF, reg & 0xFF };
    uint8_t rbuf[2];

    if (write(fd, wbuf, sizeof(wbuf)) != (ssize_t)sizeof(wbuf)) {
        fprintf(stderr, "I2C write (reg addr 0x%04X) failed: %s\n",
                reg, strerror(errno));
        return false;
    }
    if (read(fd, rbuf, sizeof(rbuf)) != (ssize_t)sizeof(rbuf)) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return false;
    }
    *out = ((uint16_t)rbuf[0] << 8) | rbuf[1];
    return true;
}

/* ------------------------------------------------------------------ */
static bool vl53l3cx_init(int fd)
{
    uint16_t model_id = 0;

    /* 1. Soft reset */
    if (!i2c_write_reg16(fd, REG_SOFT_RESET, 0x0001))
        return false;
    usleep(10000);  /* 10 ms */

    /* 2. Verify model ID */
    if (!i2c_read_reg16(fd, REG_I2C_SLAVE_DEVICE_ADDRESS, &model_id))
        return false;

    if (model_id != VL53L3CX_EXPECTED_MODEL_ID) {
        fprintf(stderr,
                "Unexpected model ID 0x%04X (expected 0x%04X). "
                "Sensor not present or wrong device.\n",
                model_id, VL53L3CX_EXPECTED_MODEL_ID);
        return false;
    }

    /*
     * 3. Proprietary firmware download / configuration sequence.
     *    The VL53L3CX requires a complex firmware download over I2C
     *    that is specific to each target/range configuration.
     *    This is a stub that simply reports success so the reader
     *    framework can proceed; replace with the ST UAPI firmware
     *    download logic from the VL53L3CX SDK when integrating.
     */
    printf("VL53L3CX detected (model ID 0x%04X). Starting firmware download...\n",
           model_id);
    usleep(100000);  /* 100 ms */
    printf("Firmware download complete.\n");

    /* 4. Start ranging */
    if (!i2c_write_reg16(fd, REG_SYSTEM_MODE_START, 0x0001))
        return false;

    return true;
}

/* ------------------------------------------------------------------ */
static bool vl53l3cx_read_targets(int fd, uint16_t *distances,
                                  int num_targets)
{
    uint16_t status = 0;
    uint16_t dist = 0;

    /* Poll for data-ready */
    for (int i = 0; i < 50; i++) {
        if (!i2c_read_reg16(fd, REG_RESULT_INTERRUPT_STATUS, &status))
            return false;
        if (status & 0x01)
            break;
        usleep(5000);  /* 5 ms */
    }
    if (!(status & 0x01)) {
        fprintf(stderr, "Timeout waiting for data-ready.\n");
        return false;
    }

    /* Read distance for each target */
    for (int i = 0; i < num_targets; i++) {
        if (!i2c_read_reg16(fd, REG_RESULT_DISTANCE, &dist))
            return false;
        distances[i] = dist;
    }

    /* Clear interrupt */
    if (!i2c_write_reg16(fd, REG_RESULT_INTERRUPT_STATUS, 0x01))
        return false;

    return true;
}

/* ------------------------------------------------------------------ */
static void print_timestamped_data(const uint16_t *distances, int n)
{
    time_t rawtime;
    struct tm timeinfo;
    char ts[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    printf("[%s] ", ts);
    for (int i = 0; i < n; i++)
        printf("Target %d: %u mm", i + 1, distances[i]);
    printf("\n");
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, VL53L3CX_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                VL53L3CX_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (!vl53l3cx_init(g_i2c_fd)) {
        fprintf(stderr, "VL53L3CX initialization failed.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("VL53L3CX reader started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t distances[MAX_TARGETS];
        int n = vl53l3cx_read_targets(g_i2c_fd, distances, MAX_TARGETS);

        if (n > 0)
            print_timestamped_data(distances, n);
        else
            fprintf(stderr, "Error reading sensor data.\n");

        usleep(POLL_INTERVAL_MS * 1000);
    }

    /* Graceful shutdown */
    if (g_i2c_fd >= 0) {
        /* Attempt to stop ranging */
        (void)i2c_write_reg16(g_i2c_fd, REG_SYSTEM_MODE_START, 0x0000);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

