#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX75031_ADDR 0x50
#define LOG_FILE "depth_log.csv"
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) return -1;
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int init_sensor(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MLX75031_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int read_distance(uint16_t *distance) {
    uint8_t reg = 0x00;
    uint8_t buf[2];

    if (i2c_write_byte(i2c_fd, reg) < 0) return -1;
    usleep(10000);
    if (i2c_read_bytes(i2c_fd, buf, 2) < 0) return -1;

    *distance = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static void log_data(FILE *fp, uint16_t distance) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%u\n", timestamp, distance);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (init_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen log file");
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Distance\n");
        fflush(log_file);
    }

    uint16_t distance;
    while (running) {
        if (read_distance(&distance) == 0) {
            log_data(log_file, distance);
        } else {
            fprintf(stderr, "Error reading distance. Attempting to re-initialize I2C.\n");
            if (i2c_fd >= 0) {
                close(i2c_fd);
                i2c_fd = -1;
            }
            if (init_sensor() < 0) {
                fprintf(stderr, "Re-initialization failed. Exiting.\n");
                break;
            }
            log_data(log_file, (uint16_t)-1);
        }
        usleep(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

