        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen log file");
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Distance\n");
        fflush(log_file);
    }

    uint16_t distance;
    while (running) {
        if (read_distance(&distance) == 0) {
            log_data(log_file, distance);
        } else {
            fprintf(stderr, "Error reading distance. Attempting to re-initialize I2C.\n");
            if (i2c_fd >= 0) {
                close(i2c_fd);
                i2c_fd = -1;
            }
            if (init_sensor() < 0) {
                fprintf(stderr, "Re-initialization failed. Exiting.\n");
                break;
            }
            log_data(log_file, (uint16_t)-1);
        }
        usleep(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

