        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("Error getting time");
        fclose(fp);
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&t, &tm_utc) == NULL) {
        perror("Error converting time to UTC");
        fclose(fp);
        return -1;
    }

