#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI1145_ADDR 0x60

#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_REV_ID 0x01
#define SI1145_REG_SEQ_ID 0x02
#define SI1145_REG_INT_CFG 0x03
#define SI1145_REG_IRQ_ENABLE 0x04
#define SI1145_REG_IRQ_MODE1 0x05
#define SI1145_REG_IRQ_MODE2 0x06
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_MEAS_RATE1 0x09
#define SI1145_REG_ALS_RATE 0x0A
#define SI1145_REG_ALS_IR_RATE 0x0B
#define SI1145_REG_PS_RATE 0x0C
#define SI1145_REG_PS_LED21 0x0D
#define SI1145_REG_PS_LED3 0x0E
#define SI1145_REG_PARAM_WR 0x17
#define SI1145_REG_COMMAND 0x18
#define SI1145_REG_RESPONSE 0x20
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_PS1_DATA0 0x24
#define SI1145_REG_PS1_DATA1 0x25

#define SI1145_CMD_RESET 0x01
#define SI1145_CMD_PARAM_SET 0x80
#define SI1145_CMD_ALS_FORCE 0x06
#define SI1145_CMD_PS_FORCE 0x05
#define SI1145_CMD_ALS_PS_FORCE 0x07
#define SI1145_CMD_NOP 0x00

#define SI1145_PART_ID 0x45
#define SI1145_HW_KEY_VAL 0x17

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %d\n", reg, val, rc);
    }
    return rc;
}

static int read_reg(uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int read_word(uint8_t reg_lo, uint16_t *val) {
    uint8_t lo, hi;
    if (read_reg(reg_lo, &lo) < 0) return -1;
    if (read_reg(reg_lo + 1, &hi) < 0) return -1;
    *val = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int wait_response(void) {
    for (int i = 0; i < 10; i++) {
        uint8_t resp;
        if (read_reg(SI1145_REG_RESPONSE, &resp) < 0) return -1;
        if ((resp & 0x0F) != 0) return 0;
        gpioDelay(10000);
    }
    fprintf(stderr, "Timeout waiting for Si1145 response\n");
    return -1;
}

static int send_command(uint8_t cmd) {
    if (write_reg(SI1145_REG_COMMAND, cmd) < 0) return -1;
    if (wait_response() < 0) return -1;
    return 0;
}

static int set_param(uint8_t param, uint8_t value) {
    if (write_reg(SI1145_REG_PARAM_WR, value) < 0) return -1;
    if (send_command(SI1145_CMD_PARAM_SET | (param & 0x1F)) < 0) return -1;
    return 0;
}

static int init_si1145(void) {
    uint8_t part_id;
    if (read_reg(SI1145_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Cannot read PART_ID - sensor may be absent\n");
        return -1;
    }
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, SI1145_PART_ID);
        return -1;
    }
    printf("Si1145 detected (PART_ID=0x%02X)\n", part_id);

    if (write_reg(SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) < 0) return -1;
    if (write_reg(SI1145_REG_MEAS_RATE0, 0x00) < 0) return -1;
    if (write_reg(SI1145_REG_MEAS_RATE1, 0x00) < 0) return -1;
    if (write_reg(SI1145_REG_ALS_RATE, 0x00) < 0) return -1;
    if (write_reg(SI1145_REG_ALS_IR_RATE, 0x00) < 0) return -1;
    if (write_reg(SI1145_REG_PS_RATE, 0x00) < 0) return -1;
    if (write_reg(SI1145_REG_PS_LED21, 0x0F) < 0) return -1;
    if (write_reg(SI1145_REG_PS_LED3, 0x00) < 0) return -1;
    if (write_reg(SI1145_REG_IRQ_ENABLE, 0x00) < 0) return -1;
    if (write_reg(SI1145_REG_IRQ_MODE1, 0x00) < 0) return -1;
    if (write_reg(SI1145_REG_IRQ_MODE2, 0x00) < 0) return -1;
    if (write_reg(SI1145_REG_INT_CFG, 0x00) < 0) return -1;

    if (send_command(SI1145_CMD_RESET) < 0) return -1;
    gpioDelay(10000);

    if (set_param(0x01, 0x77) < 0) return -1;
    if (set_param(0x02, 0x00) < 0) return -1;
    if (set_param(0x03, 0x00) < 0) return -1;
    if (set_param(0x04, 0x00) < 0) return -1;
    if (set_param(0x05, 0x00) < 0) return -1;
    if (set_param(0x06, 0x00) < 0) return -1;
    if (set_param(0x07, 0x00) < 0) return -1;
    if (set_param(0x08, 0x00) < 0) return -1;
    if (set_param(0x09, 0x00) < 0) return -1;
    if (set_param(0x0A, 0x00) < 0) return -1;
    if (set_param(0x0B, 0x00) < 0) return -1;
    if (set_param(0x0C, 0x00) < 0) return -1;
    if (set_param(0x0D, 0x00) < 0) return -1;
    if (set_param(0x0E, 0x00) < 0) return -1;
    if (set_param(0x0F, 0x00) < 0) return -1;
    if (set_param(0x10, 0x00) < 0) return -1;
    if (set_param(0x11, 0x00) < 0) return -1;
    if (set_param(0x12, 0x00) < 0) return -1;
    if (set_param(0x13, 0x00) < 0) return -1;
    if (set_param(0x14, 0x00) < 0) return -1;
    if (set_param(0x15, 0x00) < 0) return -1;
    if (set_param(0x16, 0x00) < 0) return -1;
    if (set_param(0x17, 0x00) < 0) return -1;
    if (set_param(0x18, 0x00) < 0) return -1;
    if (set_param(0x19, 0x00) < 0) return -1;
    if (set_param(0x1A, 0x00) < 0) return -1;
    if (set_param(0x1B, 0x00) < 0) return -1;
    if (set_param(0x1C, 0x00) < 0) return -1;
    if (set_param(0x1D, 0x00) < 0) return -1;
    if (set_param(0x1E, 0x00) < 0) return -1;
    if (set_param(0x1F, 0x00) < 0) return -1;

    return 0;
}

static int read_proximity(uint16_t *proximity) {
    if (send_command(SI1145_CMD_PS_FORCE) < 0) return -1;
    gpioDelay(10000);
    return read_word(SI1145_REG_PS1_DATA0, proximity);
}

static int read_ambient_light(uint16_t *ambient) {
    if (send_command(SI1145_CMD_ALS_FORCE) < 0) return -1;
    gpioDelay(10000);
    return read_word(SI1145_REG_ALS_VIS_DATA0, ambient);
}

static void log_data(uint16_t proximity, uint16_t ambient) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(log_file, "%s,%u,%u\n", timestamp, proximity, ambient);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, SI1145_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_si1145() < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("biometric_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Logging proximity and ambient light data to biometric_data.log (Ctrl+C to stop)...\n");

    while (!terminate) {
        uint16_t proximity = 0, ambient = 0;

        if (read_proximity(&proximity) < 0) {
            fprintf(stderr, "Error reading proximity data\n");
        } else if (read_ambient_light(&ambient) < 0) {
            fprintf(stderr, "Error reading ambient light data\n");
        } else {
            log_data(proximity, ambient);
        }

        gpioDelay(1000000);
    }

    printf("\nTerminating gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

