/*
 * HC-SR04 Ultrasonic Distance Sensor - Raspberry Pi Zero W
 *
 * Wiring:
 *   TRIGGER -> GPIO 17 (BCM)
 *   ECHO    -> GPIO 27 (BCM) via 1k/2k voltage divider (5V -> 3.3V)
 *
 * Build: gcc -Wall -Wextra -O2 -o hcsr04 hcsr04.c
 * Run:   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         27

#define TRIGGER_PULSE_US 10          /* 10 us trigger pulse            */
#define ECHO_TIMEOUT_US  30000       /* 30 ms max echo rise time      */
#define ECHO_PULSE_TIMEOUT_US 30000  /* 30 ms max echo pulse width    */
#define SAMPLE_INTERVAL_US 60000000 /* 60 s between logged samples    */
#define MIN_DISTANCE_CM   2.0
#define MAX_DISTANCE_CM   400.0
#define WATERING_THRESHOLD_CM 15.0

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1 || len < 20) {
        snprintf(buf, len, "UNKNOWN");
        return;
    }
    struct tm tmv;
    if (localtime_r(&now, &tmv) == NULL) {
        snprintf(buf, len, "UNKNOWN");
        return;
    }
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tmv);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_line(const char *msg)
{
    if (g_log_file == NULL)
        return;
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(g_log_file, "%s, %s\n", ts, msg);
    fflush(g_log_file);
}

static void log_distance(float distance_cm)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
        log_line("ERROR: Distance out of range");
        return;
    }

    if (distance_cm < WATERING_THRESHOLD_CM) {
        log_line("Time to water the plant!");
    } else {
        fprintf(g_log_file, "%s, Distance: %.2f cm\n", ts, distance_cm);
    }
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* HC-SR04 measurement                                                 */
/* ------------------------------------------------------------------ */
/*
 * Returns:
 *   >= 0  : distance in cm
 *   -1.0  : echo never went high (sensor absent / wiring fault)
 *   -2.0  : echo stayed high longer than ECHO_PULSE_TIMEOUT_US
 */
static float measure_distance(void)
{
    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        log_line("ERROR: gpioWrite(TRIGGER, 0) failed");
        return -1.0;
    }
    gpioDelay(5);

    /* 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        log_line("ERROR: gpioWrite(TRIGGER, 1) failed");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        log_line("ERROR: gpioWrite(TRIGGER, 0) failed");
        return -1.0;
    }

    uint32_t start_tick = gpioTick();
    if (start_tick == 0) {
        log_line("ERROR: gpioTick() returned 0 (clock error)");
        return -1.0;
    }

    /* Wait for echo rising edge */
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
            log_line("ERROR: Echo never went high (sensor absent?)");
            return -1.0;
        }
    }

    uint32_t echo_start = gpioTick();
    if (echo_start == 0) {
        log_line("ERROR: gpioTick() returned 0 (clock error)");
        return -1.0;
    }

    /* Wait for echo falling edge */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - echo_start) > ECHO_PULSE_TIMEOUT_US) {
            log_line("ERROR: Echo pulse exceeded timeout");
            return -2.0;
        }
    }

    uint32_t echo_end = gpioTick();
    if (echo_end == 0) {
        log_line("ERROR: gpioTick() returned 0 (clock error)");
        return -1.0;
    }

    uint32_t pulse_us = echo_end - echo_start;
    if (pulse_us == 0) {
        log_line("ERROR: Invalid pulse width");
        return -1.0;
    }

    /* speed of sound ~343 m/s => cm = (us * 343) / 2 / 1e6 */
    float distance = (float)pulse_us * 0.01715f;
    return distance;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        log_line("Program terminated");
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Fatal: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Fatal: gpioSetMode(TRIGGER) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Fatal: gpioSetMode(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Fatal: gpioWrite(TRIGGER, 0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen("distance_log.txt", "a");
    if (g_log_file == NULL) {
        perror("Fatal: Error opening distance_log.txt");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Fatal: sigaction failed");
        fclose(g_log_file);
        g_log_file = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance monitoring started. Press Ctrl+C to exit.\n");
    log_line("Program started");

    uint32_t next_sample = gpioTick();

    while (g_running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            /* Error already logged in measure_distance() */
            gpioDelay(100000); /* 100 ms back-off before retry */
            continue;
        }

        log_distance(distance);

        /* Schedule next sample 60 s from now */
        next_sample += SAMPLE_INTERVAL_US;
        uint32_t now = gpioTick();
        if (next_sample > now) {
            uint32_t remaining = next_sample - now;
            gpioDelay(remaining);
        } else {
            /* Fell behind schedule; reset to now */
            next_sample = now;
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

