code:
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define APDS9960_ADDR 0x39

#define APDS9960_ENABLE 0x80
#define APDS9960_ATIME 0x81
#define APDS9960_WTIME 0x83
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0x8F
#define APDS9960_CONFIG1 0x8D
#define APDS9960_CONFIG2 0x8E
#define APDS9960_PPGCONF 0x8E
#define APDS9960_CDATAL 0x94
#define APDS9960_CDATAH 0x95
#define APDS9960_RDATAL 0x96
#define APDS9960_RDATAH 0x97
#define APDS9960_GDATAL 0x98
#define APDS9960_GDATAH 0x99
#define APDS9960_BDATAL 0x9A
#define APDS9960_BDATAH 0x9B

#define PROXIMITY_THRESHOLD 200
#define LOG_FILE "color_proximity_log.csv"
#define POLL_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %d\n", reg, value, rc);
    }
    return rc;
}

static int i2c_read_byte(int handle, uint8_t reg) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %d\n", reg, rc);
    }
    return rc;
}

static int init_apds9960(int handle) {
    if (i2c_write_byte(handle, APDS9960_ENABLE, 0x00) < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_ATIME, 0xFF) < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_WTIME, 0xFF) < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_PPULSE, 0x40) < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_CONTROL, 0x03) < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_CONFIG1, 0x60) < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_CONFIG2, 0x00) < 0) return -1;
    if (i2c_write_byte(handle, APDS9960_PPGCONF, 0x00) < 0) return -1;
    return 0;
}

static int read_proximity(int handle) {
    int low = i2c_read_byte(handle, APDS9960_CDATAL);
    if (low < 0) return -1;
    int high = i2c_read_byte(handle, APDS9960_CDATAH);
    if (high < 0) return -1;
    return (high << 8) | low;
}

static int read_color(int handle, uint16_t *r, uint16_t *g, uint16_t *b) {
    int low = i2c_read_byte(handle, APDS9960_RDATAL);
    if (low < 0) return -1;
    int high = i2c_read_byte(handle, APDS9960_RDATAH);
    if (high < 0) return -1;
    *r = (high << 8) | low;

    low = i2c_read_byte(handle, APDS9960_GDATAL);
    if (low < 0) return -1;
    high = i2c_read_byte(handle, APDS9960_GDATAH);
    if (high < 0) return -1;
    *g = (high << 8) | low;

    low = i2c_read_byte(handle, APDS9960_BDATAL);
    if (low < 0) return -1;
    high = i2c_read_byte(handle, APDS9960_BDATAH);
    if (high < 0) return -1;
    *b = (high << 8) | low;

    return 0;
}

static void log_data(FILE *fp, uint16_t r, uint16_t g, uint16_t b, int prox) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%u,%u,%u,%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, r, g, b, prox);
    fflush(fp);
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
