#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1182_ADDR    0x60
#define SI1182_REG_PROX_L  0x18
#define SI1182_REG_PROX_H  0x19
#define SAMPLE_PERIOD_MS  100
#define CSV_FILENAME     "heartrate.csv"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *val)
{
    union i2c_smbus_data data;
    struct i2c_smbus_ioctl_data args;

    args.read_write = I2C_SMBUS_READ;
    args.command    = reg;
    args.size       = I2C_SMBUS_BYTE_DATA;
    args.data       = &data;

    if (ioctl(fd, I2C_SMBUS, &args) < 0)
        return -1;

    *val = data.byte;
    return 0;
}

static int read_proximity(int fd, uint16_t *prox)
{
    uint8_t lo, hi;

    if (i2c_read_byte(fd, SI1182_REG_PROX_L, &lo) < 0)
        return -1;
    if (i2c_read_byte(fd, SI1182_REG_PROX_H, &hi) < 0)
        return -1;

    *prox = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int calculate_bpm(uint16_t prox)
{
    return (int)(prox * 60 / 1000);
}

static void get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &timeinfo);
}

int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        goto cleanup;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open(" I2C_BUS ")");
        goto cleanup;
    }

    if (ioctl(fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        goto cleanup;
    }

    fp = fopen(CSV_FILENAME, "a");
    if (!fp) {
        perror("fopen(" CSV_FILENAME ")");
        goto cleanup;
    }

    while (running) {
        uint16_t prox;
        char ts[32];

        if (read_proximity(fd, &prox) < 0) {
            fprintf(stderr, "Warning: I2C read failed: %s\n", strerror(errno));
            usleep(SAMPLE_PERIOD_MS * 1000);
            continue;
        }

        int bpm = calculate_bpm(prox);
        get_timestamp(ts, sizeof(ts));

        if (fprintf(fp, "%s,%d\n", ts, bpm) < 0) {
            perror("fprintf");
            goto cleanup;
        }
        if (fflush(fp) != 0) {
            perror("fflush");
            goto cleanup;
        }

        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fp) {
        if (fclose(fp) != 0)
            perror("fclose");
    }
    if (fd >= 0) {
        if (close(fd) != 0)
            perror("close");
    }
    return rc;
}

