static int read_distance(int fd, uint16_t *distance) {
    uint8_t status = 0;
    if (i2c_read_reg8(fd, VL53L0X_REG_RESULT_INTERRUPT_STATUS, &status) < 0) {
        return -1;
    }
    if ((status & 0x01) == 0) {
        return 1;
    }
    if (i2c_write_reg8(fd, VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        return -1;
    }
    usleep(10000);
    uint16_t range = 0;
    if (i2c_read_reg16(fd, VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &range) < 0) {
        return -1;
    }
    *distance = range;
    return 0;
}

static void log_distance(FILE *fp, uint16_t distance) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%u\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, distance);
    fflush(fp);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VL53L0X_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (init_sensor(i2c_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    uint8_t gpio_config = (GPIO_PIN & 0x3F) | 0x80;
    if (i2c_write_reg8(i2c_fd, VL53L0X_REG_SYSTEM_INTERRUPT_CONFIG_GPIO, gpio_config) < 0) {
        fprintf(stderr, "Error configuring GPIO interrupt: %s\n", strerror(errno));
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        uint8_t status = 0;
        if (i2c_read_reg8(i2c_fd, VL53L0X_REG_RESULT_INTERRUPT_STATUS, &status) < 0) {
            fprintf(stderr, "Error reading interrupt status: %s\n", strerror(errno));
            break;
        }
        if ((status & 0x01) != 0) {
            uint16_t distance = 0;
            int ret = read_distance(i2c_fd, &distance);
            if (ret == 0) {
                log_distance(log_file, distance);
            } else if (ret < 0) {
                fprintf(stderr, "Error reading distance: %s\n", strerror(errno));
            }
        }
        usleep(10000);
    }

    printf("\nCleaning up...\n");
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    return 0;
}

