#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define CH101_ADDR     0x29
#define TRIGGER_REG    0x00
#define ECHO_REG       0x01
#define MEASURE_CMD    0x01
#define LOG_FILE       "distance_log.txt"
#define SAMPLE_US      200000   /* 200 ms between samples */
#define TRIGGER_US     50000    /* 50 ms after trigger */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Build a fixed-size timestamp buffer: "YYYY-MM-DD HH:MM:SS".
 * Returns 0 on success, -1 on failure.
 */
static int build_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm tm_info;

    if (time(&rawtime) == (time_t)-1)
        return -1;

    if (localtime_r(&rawtime, &tm_info) == NULL)
        return -1;

    if (strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info) == 0)
        return -1;

    return 0;
}

/*
 * Trigger a measurement and read the echo pulse width in microseconds.
 * Returns 0 on success, -1 on I2C error.
 */
static int read_distance(int handle, uint16_t *distance_mm)
{
    char trigger_cmd = (char)MEASURE_CMD;
    char echo_buf[2];
    int  rc;

    /* Trigger a single measurement */
    rc = i2cWriteDevice(handle, &trigger_cmd, 1);
    if (rc < 0) {
        fprintf(stderr, "I2C write error (trigger): %d\n", rc);
        return -1;
    }

    /* Wait for the measurement to complete (~50 ms) */
    gpioDelay(TRIGGER_US);

    /* Read 2 bytes from the echo register */
    rc = i2cReadDevice(handle, echo_buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read error (echo): expected 2 bytes, got %d\n", rc);
        return -1;
    }

    /*
     * CH101 returns the pulse width in microseconds.
     * The first byte is the high byte, the second byte is the low byte.
     */
    *distance_mm = ((uint16_t)(echo_buf[0] & 0xFF) << 8) | (uint16_t)(echo_buf[1] & 0xFF);

    return 0;
}

static void log_distance(FILE *fp, uint16_t distance_mm)
{
    char ts[32];

    if (build_timestamp(ts, sizeof(ts)) != 0) {
        fprintf(stderr, "Failed to build timestamp\n");
        return;
    }

    fprintf(fp, "%s, %u\n", ts, distance_mm);
    fflush(fp);
}

int main(void)
{
    int  handle;
    FILE *fp;

    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to CH101 */
    handle = i2cOpen(I2C_BUS, CH101_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, CH101_ADDR, handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Starting distance measurements (Ctrl+C to stop)...\n");

    while (g_running) {
        uint16_t distance_mm;

        if (read_distance(handle, &distance_mm) == 0) {
            log_distance(fp, distance_mm);
            printf("%s  Distance: %u mm\n",
                   __TIME__, distance_mm);
        } else {
            fprintf(stderr, "Skipping sample due to I2C error\n");
        }

        gpioDelay(SAMPLE_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    fclose(fp);
    i2cClose(handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

