        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        goto cleanup_gpio;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        goto cleanup_all;
    }

    printf("Proximity detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int s1 = read_sensor(SENSOR_1_PIN);
        int s2 = read_sensor(SENSOR_2_PIN);

        if (s1 >= 0 && s2 >= 0) {
            log_data(fp, s1, s2);
        } else {
            fprintf(stderr, "Error reading sensor data, skipping log entry.\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup_all:
    if (fp != NULL) {
        if (fclose(fp) != 0) {
            fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        }
    }

cleanup_gpio:
    gpioTerminate();

    return ret;
}

