/*
 * Raspberry Pi Zero W - ICU-20201 Ultrasonic ToF Distance Logger
 *
 * Reads distance from TDK InvenSense ICU-20201 on I2C bus 1 every 100 ms.
 * Lights an LED on GPIO 17 when distance < 20 cm.
 * Logs distance with ISO-8601 timestamps to distance_log.txt.
 *
 * Build: gcc -O2 -Wall -o distance_logger distance_logger.c -lpigpio -lrt
 * Run:   sudo ./distance_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x29          /* ICU-20201 default I2C address */
#define GPIO_LED       17            /* BCM pin for the LED */
#define DIST_THRESHOLD 20.0f         /* cm */
#define SAMPLE_US      100000        /* 100 ms between samples */
#define LOG_FILE       "distance_log.txt"

/* ICU-20201 register map (representative) */
#define REG_PRODUCT_ID  0x00
#define REG_DISTANCE    0x04
#define REG_MEAS_CTRL   0x08

#define PROD_ID_EXPECTED 0x20        /* ICU-20201 product ID */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0)
        return -1;
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_write_reg8(int handle, uint8_t reg, uint8_t val)
{
    return (i2cWriteByteData(handle, reg, val) < 0) ? -1 : 0;
}

/* ------------------------------------------------------------------ */
/* Sensor init                                                         */
/* ------------------------------------------------------------------ */
static int init_sensor(int handle)
{
    uint8_t prod_id = 0;

    if (i2c_read_reg8(handle, REG_PRODUCT_ID, &prod_id) != 0) {
        fprintf(stderr, "[ERROR] Failed to read PRODUCT_ID register.\n");
        return -1;
    }

    if (prod_id != PROD_ID_EXPECTED) {
        fprintf(stderr,
                "[ERROR] Unexpected PRODUCT_ID 0x%02X (expected 0x%02X). "
                "Sensor not present or wrong device.\n",
                prod_id, PROD_ID_EXPECTED);
        return -1;
    }

    /*
     * Minimal control-register setup: enable continuous measurement.
     * A full production driver would parse the datasheet and write
     * additional registers; this sequence is sufficient for the demo.
     */
    if (i2c_write_reg8(handle, REG_MEAS_CTRL, 0x01) != 0) {
        fprintf(stderr, "[ERROR] Failed to write MEAS_CTRL register.\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Distance read                                                       */
/* ------------------------------------------------------------------ */
static int read_distance(int handle, float *distance_cm)
{
    uint8_t raw = 0;

    if (i2c_read_reg8(handle, REG_DISTANCE, &raw) != 0)
        return -1;

    /*
     * ICU-20201 distance register: 16-bit value, 0.1 cm resolution.
     * pigpio i2cReadByteData returns a signed byte; for the demo we
     * treat negative as an error (sensor absent / bus error).
     */
    int16_t signed_raw = (int16_t)raw;
    if (signed_raw & 0x0080) {
        fprintf(stderr, "[WARN] Distance register out of range (0x%02X).\n", raw);
        return -1;
    }

    *distance_cm = (float)signed_raw * 0.1f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* LED control                                                         */
/* ------------------------------------------------------------------ */
static void control_led(float distance_cm)
{
    gpioWrite(GPIO_LED, (distance_cm < DIST_THRESHOLD) ? 1 : 0);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_distance(float distance_cm)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&t, &tm_info) != NULL &&
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) > 0) {
        fprintf(fp, "%s, Distance: %.2f cm\n", ts, distance_cm);
    } else {
        fprintf(fp, "<timestamp-error>, Distance: %.2f cm\n", distance_cm);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- GPIO setup --- */
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] Failed to set GPIO %d as output.\n", GPIO_LED);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_LED, 0);

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Sensor init --- */
    if (init_sensor(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] Sensor initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ICU-20201 distance logger started. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        float distance_cm = 0.0f;

        if (read_distance(g_i2c_handle, &distance_cm) == 0) {
            control_led(distance_cm);
            log_distance(distance_cm);
            printf("Distance: %.2f cm  LED: %s\n",
                   distance_cm,
                   (distance_cm < DIST_THRESHOLD) ? "ON" : "OFF");
        } else {
            fprintf(stderr, "[WARN] Distance read failed; LED off.\n");
            gpioWrite(GPIO_LED, 0);
        }

        gpioDelay(SAMPLE_US);   /* 100 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

