#define SI1182_REG_PS2_DATA 0x21
#define SI1182_REG_ALS_VIS_DATA 0x22
#define SI1182_REG_ALS_IR_DATA 0x23
#define SI1182_REG_COMMAND 0x30

/* Si1182 Commands */
#define SI1182_CMD_RESET 0x01
#define SI1182_CMD_PS_FORCE 0x05
#define SI1182_CMD_ALS_FORCE 0x06
#define SI1182_CMD_PSALS_FORCE 0x07

/* Global variables */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Function prototypes */
static int initialize_sensor(void);
static int read_sensor_data(uint16_t *proximity, uint16_t *ambient_light);
static void log_data(uint16_t proximity, uint16_t ambient_light);
static void signal_handler(int signal);
static void cleanup(void);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* Initializes the Si1182 sensor */
static int initialize_sensor(void) {
    int part_id;

    /* Verify sensor presence by reading PART_ID */
    part_id = i2cReadByteData(i2c_handle, SI1182_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID: %s\n", strerror(errno));
        return -1;
    }
    if ((part_id & 0x0F) != 0x02) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x02)\n", part_id);
        return -1;
    }

    /* Reset the sensor */
    if (i2cWriteByteData(i2c_handle, SI1182_REG_COMMAND, SI1182_CMD_RESET) < 0) {
        fprintf(stderr, "Error resetting sensor: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(10000); /* 10 ms delay for reset to complete */

    /* Write HW_KEY */
    if (i2cWriteByteData(i2c_handle, SI1182_REG_HW_KEY, 0x17) < 0) {
        fprintf(stderr, "Error writing HW_KEY: %s\n", strerror(errno));
        return -1;
    }

    /* Configure measurement rate (100 ms) */
    if (i2cWriteByteData(i2c_handle, SI1182_REG_MEAS_RATE, 0x08) < 0) {
        fprintf(stderr, "Error writing MEAS_RATE: %s\n", strerror(errno));
        return -1;
    }

    /* Configure ADCMUX for PS1 (visible photodiode) */
    if (i2cWriteByteData(i2c_handle, SI1182_REG_PS1_ADCMUX, 0x07) < 0) {
        fprintf(stderr, "Error writing PS1_ADCMUX: %s\n", strerror(errno));
        return -1;
    }

    /* Configure ADCMUX for ALS_VIS */
    if (i2cWriteByteData(i2c_handle, SI1182_REG_ALS_VIS_ADCMUX, 0x07) < 0) {
        fprintf(stderr, "Error writing ALS_VIS_ADCMUX: %s\n", strerror(errno));
        return -1;
    }

    /* Enable LED current for PS1 and PS2 */
    if (i2cWriteByteData(i2c_handle, SI1182_REG_PS_LED21, 0x0F) < 0) {
        fprintf(stderr, "Error writing PS_LED21: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, SI1182_REG_PS_LED3, 0x00) < 0) {
        fprintf(stderr, "Error writing PS_LED3: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* Reads proximity and ambient light data from the Si1182 sensor */
static int read_sensor_data(uint16_t *proximity, uint16_t *ambient_light) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        /* Trigger a forced measurement */
        if (i2cWriteByteData(i2c_handle, SI1182_REG_COMMAND, SI1182_CMD_PSALS_FORCE) < 0) {
            fprintf(stderr, "Error triggering measurement: %s\n", strerror(errno));
            retries++;
            gpioDelay(10000);
            continue;
        }

        gpioDelay(10000); /* 10 ms delay for measurement to complete */

        /* Read PS1 data (16-bit) */
        result = i2cReadWordData(i2c_handle, SI1182_REG_PS1_DATA);
        if (result >= 0) {
            *proximity = (uint16_t)result;
        } else {
            fprintf(stderr, "Error reading PS1 data: %s\n", strerror(errno));
            retries++;
            gpioDelay(10000);
            continue;
        }

        /* Read ALS_VIS data (16-bit) */
        result = i2cReadWordData(i2c_handle, SI1182_REG_ALS_VIS_DATA);
        if (result >= 0) {
            *ambient_light = (uint16_t)result;
            return 0;
        } else {
            fprintf(stderr, "Error reading ALS_VIS data: %s\n", strerror(errno));
            retries++;
            gpioDelay(10000);
        }
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
    return -1;
}

/* Logs the proximity and ambient light data to a file */
static void log_data(uint16_t proximity, uint16_t ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Proximity: %u, Ambient Light: %u\n", timestamp, proximity, ambient_light);
    fflush(log_file);
}

int main(void) {
    uint16_t proximity, ambient_light;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C connection */
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    /* Initialize the sensor */
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        cleanup();
        return 1;
    }

    /* Open the log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    /* Set up signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);

    /* Main loop */
    while (!terminate) {
        if (read_sensor_data(&proximity, &ambient_light) == 0) {
            log_data(proximity, ambient_light);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    cleanup();
    return 0;
}

