#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define LED_GPIO 17
#define LOG_FILE "tof_log.txt"
#define POLL_DELAY_US 50000
#define DEFAULT_THRESHOLD 100
#define ICU20201_WHO_AM_I 0x00
#define ICU20201_WHO_AM_I_VAL 0x01
#define ICU20201_REG_DISTANCE 0x01
#define ICU20201_REG_CONFIG 0x02
#define ICU20201_REG_MEAS_CTRL 0x03
#define ICU20201_REG_RESET 0x04
#define ICU20201_RESET_CMD 0x01

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *value) {
    if (i2cWriteDevice(handle, (char *)&reg, 1) != 1) {
        fprintf(stderr, "Error selecting reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (i2cReadDevice(handle, (char *)value, 1) != 1) {
        fprintf(stderr, "Error reading reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_sensor(int handle) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg(handle, ICU20201_WHO_AM_I, &who_am_i) != 0) {
        return -1;
    }
    if (who_am_i != ICU20201_WHO_AM_I_VAL) {
        fprintf(stderr, "Sensor not detected (WHO_AM_I=0x%02X, expected 0x%02X)\n", who_am_i, ICU20201_WHO_AM_I_VAL);
        return -1;
    }

    if (i2c_write_reg(handle, ICU20201_REG_RESET, ICU20201_RESET_CMD) != 0) {
        return -1;
    }
    gpioDelay(10000);

    if (i2c_write_reg(handle, ICU20201_REG_CONFIG, 0x00) != 0) {
        return -1;
    }
    if (i2c_write_reg(handle, ICU20201_REG_MEAS_CTRL, 0x01) != 0) {
        return -1;
    }
    return 0;
}

static int read_distance(int handle, uint16_t *distance) {
    uint8_t raw = 0;
    if (i2c_read_reg(handle, ICU20201_REG_DISTANCE, &raw) != 0) {
        return -1;
    }
    *distance = (uint16_t)raw;
    return 0;
}

static void log_data(uint16_t distance, int below_threshold) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Distance: %u mm, Threshold Breached: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            distance, below_threshold ? "YES" : "NO");
    fclose(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioSetMode(LED_GPIO, PI_INPUT);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int threshold = DEFAULT_THRESHOLD;
    if (argc > 1) {
        threshold = atoi(argv[1]);
        if (threshold <= 0) {
            fprintf(stderr, "Invalid threshold value. Using default: %d mm\n", DEFAULT_THRESHOLD);
            threshold = DEFAULT_THRESHOLD;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, 0x20, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (init_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting distance monitoring (threshold: %d mm). Press Ctrl+C to exit.\n", threshold);

    while (!terminate) {
        uint16_t distance = 0;
        if (read_distance(i2c_handle, &distance) == 0) {
            int below = (distance < (uint16_t)threshold) ? 1 : 0;
            gpioWrite(LED_GPIO, below);
            log_data(distance, below);
            printf("Distance: %u mm, Threshold Breached: %s\n", distance, below ? "YES" : "NO");
        } else {
            fprintf(stderr, "Failed to read distance. Retrying...\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

