/*
 * Raspberry Pi Zero W – Omron B5L-LD50-07050 3D TOF Intrusion Detector
 *
 * Wiring:
 *   B5L SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   B5L SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   B5L VDD  -> 3.3 V
 *   B5L GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o intrusion intrusion.c
 * Run:    ./intrusion   (Ctrl-C to stop)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define B5L_ADDR       0x29
#define LOG_FILE       "intrusion_log.txt"
#define DISTANCE_THRESHOLD_MM 1000
#define NUM_SAMPLES    10
#define SAMPLE_DELAY_MS 100
#define MEASURE_DELAY_MS 15

/* B5L measurement command (4 bytes, big-endian on the wire) */
static const uint8_t CMD_MEASURE[4] = {
    0x01, 0x00, 0x00, 0x00
};

/* B5L response header (1 byte) and distance fields (2 bytes) */
#pragma pack(push, 1)
typedef struct {
    uint8_t  header;
    uint16_t distance_mm;
} b5l_data_t;
#pragma pack(pop)

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, const uint8_t *buf, size_t len)
{
    ssize_t n = write(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C short write: %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_data(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C short read: %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_distance(int fd, uint16_t *distance_mm)
{
    if (i2c_write_cmd(fd, CMD_MEASURE, sizeof(CMD_MEASURE)) != 0)
        return -1;

    usleep(MEASURE_DELAY_MS * 1000);

    uint8_t resp[15];
    if (i2c_read_data(fd, resp, sizeof(resp)) != 0)
        return -1;

    if (resp[0] != 0x01) {
        fprintf(stderr, "Unexpected B5L header: 0x%02X (expected 0x01)\n", resp[0]);
        return -1;
    }

    b5l_data_t d;
    memcpy(&d, &resp[1], sizeof(d));
    *distance_mm = d.distance_mm;
    return 0;
}

/* ------------------------------------------------------------------ */
static int log_intrusion(float avg_mm)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Avg Distance: %.2f mm\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, avg_mm);
    } else {
        fprintf(fp, "(time error), Avg Distance: %.2f mm\n", avg_mm);
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, B5L_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                B5L_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("B5L-LD50-07050 intrusion detector started (Ctrl-C to stop)\n");

    while (g_running) {
        uint32_t sum = 0;
        int ok = 0;

        for (int i = 0; i < NUM_SAMPLES && g_running; i++) {
            uint16_t dist;
            if (read_distance(g_i2c_fd, &dist) == 0) {
                sum += dist;
                ok++;
            } else {
                fprintf(stderr, "Read failed (sensor absent or bus error)\n");
            }
            if (i < NUM_SAMPLES - 1)
                usleep(SAMPLE_DELAY_MS * 1000);
        }

        if (ok > 0) {
            float avg = (float)sum / ok;
            printf("Avg distance: %.2f mm\n", avg);
            if (avg < DISTANCE_THRESHOLD_MM) {
                printf("Intrusion detected!\n");
                if (log_intrusion(avg) != 0)
                    fprintf(stderr, "Failed to log intrusion event\n");
            }
        }

        if (g_running)
            usleep(500 * 1000); /* 500 ms between cycles */
    }

    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

