/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup — close I2C handle and terminate pigpio                    */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register from the Si1182             */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int read_proximity(uint16_t *prox)
{
    char buf[2];
    int  rc;

    /*
     * i2cReadI2CBlockData issues a write of the register pointer
     * (reg_addr & 0x7F) followed by a repeated-start read of 2 bytes.
     * Returns the number of bytes read, or < 0 on error.
     */
    rc = i2cReadI2CBlockData(g_i2c_handle, REG_PROX_DATA, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData failed (rc=%d)\n", rc);
        return -1;
    }

    *prox = (uint16_t)((uint8_t)buf[0] | ((uint8_t)buf[1] << 8));
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio ------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus 1 at the Si1182 address ----------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (handle=%d) — sensor may be absent\n",
                g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install SIGINT handler for clean shutdown ------------------ */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }

    printf("Si1182 Proximity Reader — I2C bus %d, addr 0x%02X\n",
           I2C_BUS, SI1182_ADDR);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* --- Main sampling loop ----------------------------------------- */
    while (g_running) {
        uint16_t prox;

        if (read_proximity(&prox) == 0) {
            printf("Proximity: %u\n", prox);
            fflush(stdout);
        } else {
            fprintf(stderr, "[WARN] Read failed — continuing\n");
        }

        /*
         * gpioDelay is a busy-wait; break it into 10 ms slices so
         * SIGINT is noticed promptly.
         */
        for (int i = 0; i < 50 && g_running; i++) {
            gpioDelay(10000);  /* 10 ms */
        }
    }

    /* --- Clean shutdown --------------------------------------------- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

