/*
 * OPT3101 Time-of-Flight sensor reader for Raspberry Pi Zero W.
 *
 * Wiring:
 *   OPT3101 SDA -> GPIO2 (I2C1 SDA, pin 3)
 *   OPT3101 SCL -> GPIO3 (I2C1 SCL, pin 5)
 *   OPT3101 VDD -> 3.3 V (pin 1)
 *   OPT3101 GND -> GND  (pin 6)
 *
 * Build:  gcc -O2 -Wall -Wextra -o opt3101_reader opt3101_reader.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define OPT3101_ADDR   0x60

/* OPT3101 register addresses (16-bit, big-endian on the bus) */
#define REG_CH0_DIST   0x000
#define REG_CH0_ALS    0x002
#define REG_CH0_ERR    0x004
#define REG_CH0_CTRL   0x006
#define REG_CH0_CFG    0x008
#define REG_CH0_STATUS 0x00A

#define SAMPLE_PERIOD_MS 500

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg16(int fd, uint16_t reg, uint16_t value)
{
    uint8_t buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint16_t *out)
{
    uint8_t addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (write(fd, addr, sizeof(addr)) != (ssize_t)sizeof(addr)) {
        fprintf(stderr, "I2C write (addr) for reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    uint8_t val[2];
    ssize_t n = read(fd, val, sizeof(val));
    if (n != (ssize_t)sizeof(val)) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: got %zd bytes, %s\n",
                reg, n, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)val[0] << 8) | val[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* OPT3101 configuration                                                */
/* ------------------------------------------------------------------ */
static int opt3101_init(int fd)
{
    /*
     * Channel 0: enable, continuous mode, 100 ms period.
     * CH0_CTRL = 0x0001  (CHEN=1, mode=0)
     * CH0_CFG  = 0x000A  (100 ms period, no averaging)
     */
    if (i2c_write_reg16(fd, REG_CH0_CTRL, 0x0001) != 0)
        return -1;
    if (i2c_write_reg16(fd, REG_CH0_CFG, 0x000A) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the OPT3101 slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, OPT3101_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                OPT3101_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Probe: try reading the distance register to confirm the sensor is present */
    uint16_t probe;
    if (i2c_read_reg16(g_i2c_fd, REG_CH0_DIST, &probe) != 0) {
        fprintf(stderr, "OPT3101 not detected at address 0x%02X on %s\n",
                OPT3101_ADDR, I2C_BUS);
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Configure the sensor */
    if (opt3101_init(g_i2c_fd) != 0) {
        fprintf(stderr, "OPT3101 initialization failed\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("OPT3101 initialized. Sampling every %d ms. Press Ctrl-C to exit.\n",
           SAMPLE_PERIOD_MS);

    /* Main sampling loop */
    while (g_running) {
        uint16_t dist = 0;
        uint16_t als  = 0;
        uint16_t err  = 0;
        bool read_ok = false;

        if (i2c_read_reg16(g_i2c_fd, REG_CH0_DIST, &dist) == 0 &&
            i2c_read_reg16(g_i2c_fd, REG_CH0_ALS,  &als)  == 0 &&
            i2c_read_reg16(g_i2c_fd, REG_CH0_ERR,  &err)  == 0) {
            read_ok = true;
        } else {
            fprintf(stderr, "I2C read error; continuing.\n");
        }

        if (read_ok) {
            printf("Distance: %u mm, Ambient Light: %u, Error: %u\n",
                   dist, als, err);
        } else {
            printf("Distance: N/A, Ambient Light: N/A, Error: N/A\n");
        }
        fflush(stdout);

        /* Sleep for the sample period (interruptible by signals) */
        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        /* Put the sensor in standby (disable channel 0) */
        (void)i2c_write_reg16(g_i2c_fd, REG_CH0_CTRL, 0x0000);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

