/*
 * HC-SR04 Ultrasonic Distance Sensor - Raspberry Pi 3 Model B+
 * Trigger: GPIO 17 (BCM) | Echo: GPIO 18 (BCM)
 *
 * NOTE: The HC-SR04 operates at 5 V. The Raspberry Pi GPIO pins are
 * 3.3 V tolerant. A 1 kΩ resistor must be used on the echo line to
 * protect the sensor and the Pi.
 *
 * Build: gcc -Wall -Wextra -O2 -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18

#define TRIGGER_PULSE_US  10
#define ECHO_TIMEOUT_US   200000   /* 200 ms max echo wait */
