#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define GPIO_LED 17
#define DISTANCE_THRESHOLD 1.0f
#define NUM_RANGE_BINS 64
#define RANGE_PROFILE_SIZE (NUM_RANGE_BINS * sizeof(uint16_t))
#define MAGIC_WORD_SIZE 8
#define FRAME_HEADER_SIZE 40
#define FRAME_PAYLOAD_SIZE (FRAME_HEADER_SIZE + RANGE_PROFILE_SIZE)
#define LOG_FILE "intrusion_log.csv"
#define ALERT_DURATION_SEC 2

static const uint8_t MAGIC_WORD[MAGIC_WORD_SIZE] = {0x02, 0x01, 0x03, 0x02, 0x04, 0x03, 0x04, 0x05};

static volatile sig_atomic_t program_running = 1;
static int uart_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_uart(const char *device, speed_t baud) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        perror("open() UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr()");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud);
    cfsetispeed(&tty, baud);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 1;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr()");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_exact(int fd, void *buf, size_t len) {
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, (uint8_t *)buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("read()");
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "UART read timeout (sensor absent?)\n");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

static int find_magic_word(int fd) {
    uint8_t buf[MAGIC_WORD_SIZE];
    for (;;) {
        if (read_exact(fd, buf, MAGIC_WORD_SIZE) != 0) return -1;
        if (memcmp(buf, MAGIC_WORD, MAGIC_WORD_SIZE) == 0) return 0;
    }
}

static int read_range_profile(int fd, uint16_t *profile) {
    if (read_exact(fd, profile, RANGE_PROFILE_SIZE) != 0) return -1;
    return 0;
}

static int detect_target(const uint16_t *profile, float threshold) {
    for (int i = 0; i < NUM_RANGE_BINS; i++) {
        float dist = (float)profile[i] * 0.001f;
        if (dist <= threshold) return 1;
    }
    return 0;
}

static int log_intrusion(float distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen() log");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r()");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", ts, distance) < 0) {
        perror("fprintf() log");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose() log");
        return -1;
    }
    return 0;
}

static void trigger_alert(int gpio) {
    if (gpioWrite(gpio, 1) < 0) {
        fprintf(stderr, "gpioWrite(1) failed\n");
        return;
    }
    sleep(ALERT_DURATION_SEC);
    if (gpioWrite(gpio, 0) < 0) {
        fprintf(stderr, "gpioWrite(0) failed\n");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction()");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", GPIO_LED);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_LED, 0);

    uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Intrusion detection started. Press Ctrl+C to exit.\n");

    while (program_running) {
        if (find_magic_word(uart_fd) != 0) {
            if (program_running) {
                fprintf(stderr, "Lost frame sync. Reconnecting...\n");
                close(uart_fd);
                sleep(1);
                uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
                if (uart_fd < 0) {
                    fprintf(stderr, "Reinit failed. Retrying...\n");
                }
            }
            continue;
        }

        uint16_t profile[NUM_RANGE_BINS];
        if (read_range_profile(uart_fd, profile) != 0) {
            fprintf(stderr, "Failed to read range profile.\n");
            continue;
        }

        if (detect_target(profile, DISTANCE_THRESHOLD)) {
            float distance = (float)profile[0] * 0.001f;
            printf("Intrusion detected! Distance: %.2f m\n", distance);

            if (log_intrusion(distance) != 0) {
                fprintf(stderr, "Failed to log intrusion.\n");
            }

            trigger_alert(GPIO_LED);
        }
    }

    printf("\nShutting down...\n");
    if (uart_fd >= 0) close(uart_fd);
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

