#define LOG_FILE "obstacle_log.txt"
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&t, &tm_info) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    } else {
        snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
    }

    fprintf(fp, "%s: %s\n", timestamp, event);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set sensor pin %d as input\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set buzzer pin %d as output\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise buzzer pin %d to LOW\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int last_state = -1;  /* -1 = unknown, forces initial log */

    while (running) {
        int sensor_value = gpioRead(SENSOR_PIN);
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor pin %d: %s\n", SENSOR_PIN, strerror(errno));
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* E18-D80NK is active-low: 0 = obstacle detected, 1 = clear */
        int obstacle_detected = (sensor_value == 0);

        if (gpioWrite(BUZZER_PIN, obstacle_detected ? 1 : 0) != 0) {
            fprintf(stderr, "Error writing to buzzer pin %d\n", BUZZER_PIN);
        }

        if (obstacle_detected != last_state) {
            if (obstacle_detected) {
                log_event("Obstacle detected - buzzer ON");
            } else {
                log_event("Obstacle cleared - buzzer OFF");
            }
            last_state = obstacle_detected;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Graceful shutdown */
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

