/*
 * Raspberry Pi 4 Model B - TDK Chirp ICU-20201 Ultrasonic ToF Sensor Monitor
 *
 * Reads distance from the ICU-20201 via I2C bus 1 every 100 ms, logs
 * timestamped readings to distance_log.txt, and asserts a GPIO alert
 * on BCM 17 when distance falls below 10.0 cm.
 *
 * Build:  gcc -O2 -Wall -Wextra -o chirp_monitor chirp_monitor.c -lpigpio -lrt
 * Run:    sudo ./chirp_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define I2C_ADDR             0x40          /* ICU-20201 default I2C address */
#define GPIO_ALERT_PIN       17            /* BCM 17 - physical pin 17 */
#define DISTANCE_THRESHOLD   10.0f         /* cm */
#define LOG_FILE             "distance_log.txt"
#define SAMPLE_PERIOD_US     100000        /* 100 ms */

/*
 * ICU-20201 register map (representative subset).
 * The device is read-only over I2C; writes below are placeholders for
 * the actual register-address byte + data-byte sequence required by
 * the sensor's SPI/I2C protocol.  Replace them with the exact values
 * from the datasheet once they are known.
 */
#define REG_DISTANCE_MSB     0x00          /* Distance MSB  (read-only)   */
#define REG_DISTANCE_LSB     0x01          /* Distance LSB  (read-only)   */
#define REG_TEMP_MSB        0x02          /* Temperature MSB (read-only)  */
#define REG_TEMP_LSB        0x03          /* Temperature LSB (read-only)  */

/* ------------------------------- Globals --------------------------------- */
static int      i2c_handle = -1;
static FILE    *log_file   = NULL;
static volatile sig_atomic_t terminate = 0;

/* --------------------------- Function prototypes ------------------------- */
static int  initialize_i2c(void);
static int  read_distance(float *distance_out);
static int  log_data(float distance);
static void check_threshold(float distance);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------- I2C init -------------------------------- */
static int initialize_i2c(void)
{
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

/* --------------------------- Read distance (cm) -------------------------- */
static int read_distance(float *distance_out)
{
    if (distance_out == NULL) {
        return -1;
    }

    /*
     * Read 2 bytes from the distance register.
     * i2cReadDevice returns the number of bytes read on success, or a
     * negative pigpio error code on failure.
     */
    char buf[2];
    int  bytes = i2cReadDevice(i2c_handle, buf, 2);
    if (bytes != 2) {
        if (bytes < 0) {
            fprintf(stderr, "[ERROR] i2cReadDevice failed: %d\n", bytes);
        } else {
            fprintf(stderr, "[ERROR] i2cReadDevice short read: %d bytes\n", bytes);
        }
        return -1;
    }

    /*
     * Assemble a 16-bit distance value (big-endian on the wire).
     * The ICU-20201 outputs distance in centimetres; no scaling factor
     * is required.
     */
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *distance_out = (float)raw;
    return 0;
}

/* ------------------------------- Log data -------------------------------- */
static int log_data(float distance)
{
    if (log_file == NULL) {
        fprintf(stderr, "[ERROR] Log file not open.\n");
        return -1;
    }

    time_t     now = time(NULL);
    struct tm  tm_buf;
    struct tm *tm_info = localtime_r(&now, &tm_buf);
    if (tm_info == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed.\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", tm_info) == 0) {
        fprintf(stderr, "[ERROR] strftime failed.\n");
        return -1;
    }

    if (fprintf(log_file, "%s, Distance: %.2f cm\n", ts, distance) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log file failed.\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "[WARN] fflush failed on log file.\n");
    }

    return 0;
}

/* --------------------------- Threshold check ----------------------------- */
static void check_threshold(float distance)
{
    if (distance < DISTANCE_THRESHOLD) {
        if (gpioWrite(GPIO_ALERT_PIN, 1) != 0) {
            fprintf(stderr, "[WARN] gpioWrite(ALERT, 1) failed.\n");
        }
    } else {
        if (gpioWrite(GPIO_ALERT_PIN, 0) != 0) {
            fprintf(stderr, "[WARN] gpioWrite(ALERT, 0) failed.\n");
        }
    }
}

/* --------------------------- Signal handler ------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    /* gpioTerminate is safe to call even if gpioInitialise failed */
    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise failed.\n");
        return EXIT_FAILURE;
    }

    /* --- GPIO alert pin --- */
    if (gpioSetMode(GPIO_ALERT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, OUTPUT) failed.\n", GPIO_ALERT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(GPIO_ALERT_PIN, 0) != 0) {
        fprintf(stderr, "[FATAL] gpioWrite(%d, 0) failed.\n", GPIO_ALERT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Sensor presence check --- */
    char probe[1];
    if (i2cReadDevice(i2c_handle, probe, 1) != 1) {
        fprintf(stderr, "[FATAL] No ICU-20201 detected at 0x%02X on bus %d.\n",
                I2C_ADDR, I2C_BUS);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("[FATAL] fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction");
    }

    printf("Chirp ICU-20201 monitoring started.  Threshold: %.1f cm  Log: %s\n",
           DISTANCE_THRESHOLD, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (!terminate) {
        float distance;

        if (read_distance(&distance) == 0) {
            if (log_data(distance) != 0) {
                fprintf(stderr, "[ERROR] Logging failed; continuing.\n");
            }
            check_threshold(distance);
        } else {
            fprintf(stderr, "[ERROR] Distance read failed; retrying.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);   /* 100 ms */
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

