/*
 * CH201 Ultrasonic Distance Sensor - LED Blink Frequency Correlation
 * Board:  Raspberry Pi 4 Model B
 * Library: pigpio (modern, actively maintained)
 *
 * Wiring:
 *   CH201 SDA  -> GPIO 2 (I2C bus 1 SDA)
 *   CH201 SCL  -> GPIO 3 (I2C bus 1 SCL)
 *   CH201 VDD  -> 3.3 V
 *   CH201 GND  -> GND
 *   LED anode -> GPIO 18 (BCM) via 330 ohm resistor to GND
 *
 * Behavior:
 *   Samples distance every 100 ms.  Each loop half-cycles the LED
 *   (on or off) so that the LED stays continuously visible while
 *   distance is measured.  Blink frequency increases as distance
 *   decreases.  I2C errors are retried up to 3 times; SIGINT/SIGTERM
 *   trigger clean shutdown.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x29          /* CH201 default I2C address */
#define LED_GPIO       18            /* BCM pin for LED */
#define SAMPLE_US      100000        /* 100 ms between samples */
#define RETRY_DELAY_US 10000         /* 10 ms between retries */
#define MAX_RETRIES    3

/* CH201 register addresses (16-bit, big-endian on the wire) */
#define REG_PRODUCT_ID      0x000
#define REG_SYSTEM_CONFIG   0x010
#define REG_RANGE_START     0x020
#define REG_RANGE_RESULT    0x030
#define REG_TEMP_RESULT     0x040

#define EXPECTED_PRODUCT_ID 0x201

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg16(int handle, uint16_t reg, uint16_t value)
{
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteDevice(handle, buf, 4);
        if (rc == 0)
            return 0;
        fprintf(stderr,
                "[I2C] write reg 0x%04X failed (attempt %d/%d): rc=%d\n",
                reg, attempt + 1, MAX_RETRIES, rc);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint16_t *out)
{
    char cmd[2];
    char data[2];
    cmd[0] = (reg >> 8) & 0xFF;
    cmd[1] = reg & 0xFF;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cWriteDevice(handle, cmd, 2) != 0) {
            fprintf(stderr,
                    "[I2C] write reg-addr 0x%04X failed (attempt %d/%d)\n",
                    reg, attempt + 1, MAX_RETRIES);
            if (attempt < MAX_RETRIES - 1)
                gpioDelay(RETRY_DELAY_US);
            continue;
        }
        if (i2cReadDevice(handle, data, 2) == 2) {
            *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
            return 0;
        }
        fprintf(stderr,
                "[I2C] read reg 0x%04X failed (attempt %d/%d)\n",
                reg, attempt + 1, MAX_RETRIES);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* CH201 driver                                                        */
/* ------------------------------------------------------------------ */
static int ch201_init(int handle)
{
    uint16_t product_id = 0;

    if (i2c_read_reg16(handle, REG_PRODUCT_ID, &product_id) != 0) {
        fprintf(stderr, "[CH201] Cannot read PRODUCT_ID - sensor absent or bus error\n");
        return -1;
    }

    if (product_id != EXPECTED_PRODUCT_ID) {
        fprintf(stderr,
                "[CH201] Unexpected PRODUCT_ID: 0x%04X (expected 0x%04X)\n",
                product_id, EXPECTED_PRODUCT_ID);
        return -1;
    }

    /*
     * System config (0x010):
     *   bit 0    = 0  -> continuous measurement mode
     *   bits 1-2 = 00 -> 100 ms measurement period (default)
     *   bits 3-5 = 000 -> 100 ms range start trigger
     *   bits 6-8 = 000 -> 100 ms range result valid time
     * Value = 0x000.
     */
    if (i2c_write_reg16(handle, REG_SYSTEM_CONFIG, 0x000) != 0) {
        fprintf(stderr, "[CH201] Failed to write SYSTEM_CONFIG\n");
        return -1;
    }

    /*
     * Range start (0x020): set to 0 to begin continuous measurement.
     */
    if (i2c_write_reg16(handle, REG_RANGE_START, 0x000) != 0) {
        fprintf(stderr, "[CH201] Failed to write RANGE_START\n");
        return -1;
    }

    return 0;
}

static int ch201_read_distance(int handle, uint16_t *distance_mm)
{
    /*
     * Range result (0x030): 16-bit value, bits [15:0] = distance (mm).
     * Poll until the result is valid (bit 15 = 1).
     */
    for (int i = 0; i < 50; i++) {
        uint16_t raw;
        if (i2c_read_reg16(handle, REG_RANGE_RESULT, &raw) != 0)
            return -1;
        if (raw & 0x8000) {
            *distance_mm = raw & 0x7FFF;
            return 0;
        }
        gpioDelay(2000);  /* 2 ms */
    }
    fprintf(stderr, "[CH201] Timeout waiting for range result\n");
    return -1;
}

/* ------------------------------------------------------------------ */
/* LED control                                                         */
/* ------------------------------------------------------------------ */
static void led_set(int gpio, bool on)
{
    if (gpioWrite(gpio, on ? 1 : 0) != 0)
        fprintf(stderr, "[LED] gpioWrite(%d, %d) failed\n", gpio, on ? 1 : 0);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Sensor init --- */
    if (ch201_init(g_i2c_handle) != 0) {
        fprintf(stderr, "CH201 initialization failed - check wiring and I2C address\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- LED GPIO setup --- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", LED_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    led_set(LED_GPIO, false);

    /* --- Signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("CH201 distance sensor ready. Sampling every %d ms. Ctrl+C to exit.\n",
           SAMPLE_US / 1000);

    /* --- Main loop --- */
    while (g_running) {
        uint16_t distance = 0;
        time_t now = time(NULL);
        struct tm tm_info;
        char ts[32];

        if (ch201_read_distance(g_i2c_handle, &distance) != 0) {
            fprintf(stderr, "[main] Distance read failed - continuing\n");
            led_set(LED_GPIO, false);
            gpioDelay(SAMPLE_US);
            continue;
        }

        localtime_r(&now, &tm_info);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

        /*
         * Blink frequency: 100 ms base, subtract distance-scaled fraction.
         * distance_mm * 1000 / 100000  -> 0..1  (scaled to 100 ms)
         * 100 ms - (distance/1000) * 100 ms  -> 0..100 ms
         */
        int half_period_us = SAMPLE_US - (distance / 1000) * 100;
        if (half_period_us < 1)
            half_period_us = 1;

        led_set(LED_GPIO, true);
        gpioDelay(half_period_us);
        led_set(LED_GPIO, false);
        gpioDelay(half_period_us);

        printf("%s  Distance: %u mm  LED half-period: %u us\n",
               ts, distance, half_period_us);
        fflush(stdout);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    led_set(LED_GPIO, false);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

