#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define DEBOUNCE_MS   50
#define POLL_MS       10
#define LOG_FILE      "proximity_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(int sensor_id, const char *event_type) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r() failed\n");
        return;
    }

    char ts_buf[32];
    if (strftime(ts_buf, sizeof(ts_buf), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (fprintf(log_file, "%s - Sensor %d - %s\n", ts_buf, sensor_id, event_type) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed\n");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_DOWN);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    int s1_state = gpioRead(SENSOR_1_GPIO);
    int s2_state = gpioRead(SENSOR_2_GPIO);

    if (s1_state < 0 || s2_state < 0) {
        fprintf(stderr, "Initial gpioRead failed (s1=%d, s2=%d)\n", s1_state, s2_state);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int s1_last = s1_state;
    int s2_last = s2_state;

    printf("Proximity detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int s1_current = gpioRead(SENSOR_1_GPIO);
        int s2_current = gpioRead(SENSOR_2_GPIO);

        if (s1_current < 0 || s2_current < 0) {
            fprintf(stderr, "gpioRead failed (s1=%d, s2=%d)\n", s1_current, s2_current);
            break;
        }

        if (s1_current != s1_last) {
            if (s1_current == 0) {
                log_event(1, "DETECTED");
            } else {
                log_event(1, "CLEARED");
            }
            s1_last = s1_current;
        }

        if (s2_current != s2_last) {
            if (s2_current == 0) {
                log_event(2, "DETECTED");
            } else {
                log_event(2, "CLEARED");
            }
            s2_last = s2_current;
        }

        gpioDelay(POLL_MS * 1000);
    }

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    gpioTerminate();
    printf("\nCleanup complete. Exiting.\n");
    return EXIT_SUCCESS;
}

