#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define CH101_ADDR     0x50
#define MEAS_STATUS    0x00
#define MEAS_READY_MASK 0x01
#define POLL_TIMEOUT_MS 50
#define SAMPLE_DELAY_MS 500
#define LOG_FILE       "distance_log.csv"

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write(reg 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t *val)
{
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int wait_for_measurement(int fd)
{
    uint8_t status = 0;
    int elapsed = 0;

    while (elapsed < POLL_TIMEOUT_MS) {
        if (i2c_write_byte(fd, MEAS_STATUS) < 0)
            return -1;
        if (i2c_read_byte(fd, &status) < 0)
            return -1;
        if (status & MEAS_READY_MASK)
            return 0;
        usleep(1000);
        elapsed++;
    }
    fprintf(stderr, "Timeout waiting for CH-101 measurement\n");
    return -1;
}

static int read_distance(int fd, uint16_t *distance_mm)
{
    uint8_t status = 0;
    uint8_t data[2] = {0, 0};

    if (i2c_write_byte(fd, MEAS_STATUS) < 0)
        return -1;
    if (i2c_read_byte(fd, &status) < 0)
        return -1;
    if (!(status & MEAS_READY_MASK)) {
        fprintf(stderr, "Measurement not ready\n");
        return -1;
    }
    if (i2c_read_byte(fd, &data[0]) < 0)
        return -1;
    if (i2c_read_byte(fd, &data[1]) < 0)
        return -1;
    *distance_mm = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

static void log_data(FILE *fp, uint16_t distance_mm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);
    fprintf(fp, "%s,%u\n", timestamp, distance_mm);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, CH101_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                CH101_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    fprintf(g_log_fp, "# timestamp,distance_mm\n");
    fflush(g_log_fp);

    while (g_running) {
        if (wait_for_measurement(g_i2c_fd) < 0) {
            if (!g_running)
                break;
            usleep(SAMPLE_DELAY_MS * 1000);
            continue;
        }
        uint16_t distance_mm = 0;
        if (read_distance(g_i2c_fd, &distance_mm) < 0) {
            if (!g_running)
                break;
            usleep(SAMPLE_DELAY_MS * 1000);
            continue;
        }
        log_data(g_log_fp, distance_mm);
        usleep(SAMPLE_DELAY_MS * 1000);
    }

    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

