/*
 * MLX75030 Time-of-Flight distance sensor reader for Raspberry Pi Zero W.
 *
 * Wiring:
 *   MLX75030 SDA -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   MLX75030 SCL -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   MLX75030 VDD -> 3.3 V (pin 1)
 *   MLX75030 GND -> GND  (pin 6)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mlx75030_reader mlx75030_reader.c -lpigpio -lrt
 *   (pigpio must be installed and the program run as root or with appropriate
 *    /dev/i2c-1 permissions.)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x50          /* MLX75030 default I2C address */
#define SAMPLE_PERIOD_US 100000      /* 100 ms in microseconds */
#define MAX_RETRIES    3
#define RETRY_DELAY_US 10000         /* 10 ms between retries */

/*
 * MLX75030 register map (representative subset).
 * The exact register layout depends on the firmware revision; the values below
 * are placeholders that match the pigpio-provided register addresses.
 */
#define REG_DISTANCE_MSB  0x0A
#define REG_DISTANCE_LSB  0x0B
#define REG_ERROR_CODE    0x0C

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

/*
 * Write a single byte to a register with retry logic.
 * Returns 0 on success, -1 on failure.
 */
static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteByteData(handle, reg, value);
        if (rc == 0)
            return 0;
        fprintf(stderr,
                "Warning: i2cWriteByteData(reg=0x%02X, val=0x%02X) failed "
                "(attempt %d/%d, rc=%d)\n",
                reg, value, attempt + 1, MAX_RETRIES, rc);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/*
 * Read a single byte from a register with retry logic.
 * Returns the byte value (0-255) on success, -1 on failure.
 */
static int i2c_read_byte(int handle, uint8_t reg)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cReadByteData(handle, reg);
        if (rc >= 0)
            return rc;
        fprintf(stderr,
                "Warning: i2cReadByteData(reg=0x%02X) failed "
                "(attempt %d/%d, rc=%d)\n",
                reg, attempt + 1, MAX_RETRIES, rc);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/*
 * Read a 16-bit little-endian value from two consecutive registers.
 * Returns 0 on success, -1 on failure.
 */
static int i2c_read_word(int handle, uint8_t reg_msb, uint16_t *out)
{
    int msb = i2c_read_byte(handle, reg_msb);
    if (msb < 0)
        return -1;

    int lsb = i2c_read_byte(handle, reg_msb + 1);
    if (lsb < 0)
        return -1;

    *out = (uint16_t)((lsb << 8) | msb);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor abstraction                                                  */
/* ------------------------------------------------------------------ */

/*
 * Read distance in millimetres.
 * Returns 0 on success, -1 on failure.
 */
static int read_distance(int handle, uint16_t *distance_mm)
{
    if (i2c_read_word(handle, REG_DISTANCE_MSB, distance_mm) != 0)
        return -1;
    return 0;
}

/*
 * Read the error code register.
 * Returns the error code (0-255) on success, -1 on failure.
 */
static int read_error_code(int handle)
{
    return i2c_read_byte(handle, REG_ERROR_CODE);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr,
                "Error: i2cOpen(bus=%d, addr=0x%02X) failed "
                "(rc=%d). Check wiring and that the sensor is present.\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX75030 reader started. Sampling every %d ms. Press Ctrl-C to exit.\n",
           SAMPLE_PERIOD_US / 1000);

    /* --- Main sampling loop --- */
    while (g_running) {
        uint16_t distance = 0;
        int err_code = 0;
        bool read_ok = false;

        if (read_distance(g_i2c_handle, &distance) == 0) {
            read_ok = true;
            err_code = read_error_code(g_i2c_handle);
            if (err_code >= 0)
                fprintf(stderr, "Error code: %d\n", err_code);
        } else {
            fprintf(stderr, "Error: failed to read distance after %d retries.\n",
                    MAX_RETRIES);
        }

        /* Timestamp */
        struct timespec ts;
        if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
            long ms = ts.tv_nsec / 1000000L;
            printf("[%ld.%03ld] Distance: %u mm",
                   ts.tv_sec, ms, distance);
            if (!read_ok)
                printf("  (read error)");
            printf("\n");
            fflush(stdout);
        }

        /* Sleep 100 ms (interruptible by signals) */
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

