#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L4CX_ADDR 0x29

#define VL53L4CX_SOFT_RESET 0x0003
#define VL53L4CX_SYSTEM_START 0x0008
#define VL53L4CX_GPIO_HV_MUX_CTRL 0x0030
#define VL53L4CX_GPIO_TIO_HV_STATUS 0x0031
#define VL53L4CX_RESULT_INTERRUPT_STATUS 0x0044
#define VL53L4CX_RESULT_RANGE_STATUS 0x0045
#define VL53L4CX_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050
#define VL53L4CX_RESULT_PEAK_SIGNAL_COUNT_RATE_CROSSTALK_CORRECTED 0x0052
#define VL53L4CX_RESULT_AMBIENT_COUNT_RATE 0x0054
#define VL53L4CX_RESULT_SIGMA_ESTIMATE 0x0056
#define VL53L4CX_RESULT_DISTANCE_MM_SD0 0x0058
#define VL53L4CX_RESULT_SIGNAL_RATE_RATIO 0x005A
#define VL53L4CX_RESULT_REFLECTED_POWER 0x005C
#define VL53L4CX_RESULT_REFLECTED_POWER_SPAD_RATE 0x005E
#define VL53L4CX_RESULT_REFLECTED_POWER_SPAD_SD0 0x0060
#define VL53L4CX_RESULT_REFLECTED_POWER_SPAD_SD1 0x0062
#define VL53L4CX_RESULT_REFLECTED_POWER_SPAD_SD2 0x0064
#define VL53L4CX_RESULT_REFLECTED_POWER_SPAD_SD3 0x0066
#define VL53L4CX_RESULT_REFLECTED_POWER_SPAD_SD4 0x0068
#define VL53L4CX_RESULT_REFLECTED_POWER_SPAD_SD5 0x006A
#define VL53L4CX_RESULT_REFLECTED_POWER_SPAD_SD6 0x006C
#define VL53L4CX_RESULT_REFLECTED_POWER_SPAD_SD7 0x006E
#define VL53L4CX_RESULT_REFLECTED_POWER_SPAD_SD8 0x0070
#define VL53L4CX_RESULT_REFLECTED_POWER_SPAD_SD9 0x0072
#define VL53L4CX_RESULT_REFLECTED_POWER_SPAD_SD10 0x0074
#define VL53L4CX_RESULT_REFLECTED_POWER_SPAD_SD11 0x0076

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "Error writing reg 0x%04X\n", reg);
        return -1;
    }
    return 0;
}

static int read_reg16(int handle, uint16_t reg, uint8_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing reg address 0x%04X\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, (char *)value, 1) != 1) {
        fprintf(stderr, "Error reading reg 0x%04X\n", reg);
        return -1;
    }
    return 0;
}

static int read_reg16_16bit(int handle, uint16_t reg, uint16_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing reg address 0x%04X\n", reg);
        return -1;
    }
    char read_buf[2];
    if (i2cReadDevice(handle, read_buf, 2) != 2) {
        fprintf(stderr, "Error reading 16-bit reg 0x%04X\n", reg);
        return -1;
    }
    *value = ((uint16_t)(read_buf[0] << 8)) | (uint8_t)read_buf[1];
    return 0;
}

static int init_sensor(int handle) {
    if (write_reg16(handle, VL53L4CX_SOFT_RESET, 0x00) != 0) return -1;
    gpioDelay(10000);
    if (write_reg16(handle, VL53L4CX_SOFT_RESET, 0x01) != 0) return -1;
    gpioDelay(10000);
    if (write_reg16(handle, VL53L4CX_SYSTEM_START, 0x01) != 0) return -1;
    gpioDelay(10000);
    if (write_reg16(handle, VL53L4CX_GPIO_HV_MUX_CTRL, 0x04) != 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int read_distance(int handle, uint16_t *distance) {
    uint8_t status = 0;
    if (read_reg16(handle, VL53L4CX_RESULT_INTERRUPT_STATUS, &status) != 0) return -1;
    if ((status & 0x01) == 0) return 1;
    if (read_reg16_16bit(handle, VL53L4CX_RESULT_DISTANCE_MM_SD0, distance) != 0) return -1;
    if (write_reg16(handle, VL53L4CX_RESULT_INTERRUPT_STATUS, 0x01) != 0) return -1;
    return 0;
}

static void get_timestamp(char *timestamp, size_t len) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), len - strlen(timestamp), ".%06ld", ts.tv_nsec / 1000);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, VL53L4CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (init_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    while (running) {
        uint16_t distance = 0;
        int ret = read_distance(i2c_handle, &distance);
        if (ret == 0) {
            char timestamp[32];
            get_timestamp(timestamp, sizeof(timestamp));
            printf("Timestamp: %s, Distance: %u mm\n", timestamp, distance);
            fflush(stdout);
        } else if (ret < 0) {
            fprintf(stderr, "Error reading distance\n");
        }
        gpioDelay(500000);
    }
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

