#define I2C_BUS 1
#define BUZZER_GPIO 22
#define DISTANCE_THRESHOLD 100 // mm
#define POLL_DELAY_US 500000   // 500 ms

// VL53L1X register addresses
#define VL53L1X_REG_SOFT_RESET 0x0000
#define VL53L1X_REG_I2C_SLAVE_DEVICE_ADDRESS 0x0001
#define VL53L1X_REG_SYSTEM_MODE_START 0x0008
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

// Write a 16-bit register on the VL53L1X
static int vl53l1x_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

// Read a 16-bit register on the VL53L1X
static int vl53l1x_read_reg16(int handle, uint16_t reg, uint8_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) < 0) return -1;
    if (i2cReadDevice(handle, (char *)value, 1) != 1) return -1;
    return 0;
}

// Read a 16-bit big-endian register on the VL53L1X
static int vl53l1x_read_reg16_be(int handle, uint16_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (vl53l1x_read_reg16(handle, reg, buf) < 0) return -1;
    *value = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

// Initialize the VL53L1X sensor
static int init_vl53l1x(int handle) {
    // Soft reset
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0) return -1;
    gpioDelay(1000); // 1 ms
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x01) < 0) return -1;
    gpioDelay(10000); // 10 ms

    // Set I2C address (7-bit)
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_I2C_SLAVE_DEVICE_ADDRESS, 0x29) < 0) return -1;

    // Start continuous ranging mode
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x40) < 0) return -1;

    return 0;
}

