static int read_distance(int handle, uint16_t *distance) {
    uint8_t status = 0;
    if (vl53l1x_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status) < 0) {
        return -1;
    }

    if ((status & 0x01) == 0) {
