        return 1;
    }

    if (vl53l1x_read_reg16_be(handle, VL53L1X_REG_RESULT_DISTANCE, distance) < 0) {
        return -1;
    }

    // Clear interrupt by writing to register 0x0061
    if (vl53l1x_write_reg16(handle, 0x0061, 0x01) < 0) {
        return -1;
    }

    return 0;
}

