    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("VL53L1X distance sensor running. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t distance = 0;
        int result = read_distance(i2c_handle, &distance);

        if (result == 0) {
