#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   17

#define MIN_DISTANCE_CM 2.0f
#define MAX_DISTANCE_CM 400.0f
#define MIN_ANGLE_DEG   -90.0f
#define MAX_ANGLE_DEG   90.0f

#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  50000
#define LOOP_DELAY_US    200000
#define LOG_FILE         "sensor_data.log"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static float read_distance(void) {
    uint32_t start_tick, end_tick, timeout_tick;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger low\n");
        return -1.0f;
    }
    gpioDelay(5);

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to write trigger high\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger low\n");
        return -1.0f;
    }

    /* Wait for echo rising edge (timeout 50 ms) */
    start_tick = gpioTick();
    timeout_tick = start_tick + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo never went high (timeout)\n");
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout 50 ms) */
    timeout_tick = start_tick + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo stuck high (timeout)\n");
            return -1.0f;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    float distance_cm = (float)pulse_us / 58.0f;

    if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range\n", distance_cm);
        return -1.0f;
    }
    return distance_cm;
}

static void set_servo_angle(float angle_deg) {
    if (angle_deg < MIN_ANGLE_DEG) angle_deg = MIN_ANGLE_DEG;
    if (angle_deg > MAX_ANGLE_DEG) angle_deg = MAX_ANGLE_DEG;

    float ratio = (angle_deg + 90.0f) / 180.0f;
    int pulse_width = (int)(500000.0f * ratio);

    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pin %d\n", SERVO_PIN);
    }
}

static void log_data(float distance_cm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %.2f cm\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, distance_cm);
    } else {
        fprintf(fp, "Timestamp error, Distance: %.2f cm\n", distance_cm);
    }
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Register signal handlers before any GPIO setup so cleanup runs even if init hangs */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set trigger pin %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: cannot set echo pin %d as input\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set servo pin %d as output\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50);

    /* Initialise servo to centre (90°) */
    set_servo_angle(0.0f);
    gpioDelay(500000);

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = read_distance();

        if (distance > 0.0f) {
            set_servo_angle((distance - MIN_DISTANCE_CM) /
                            (MAX_DISTANCE_CM - MIN_DISTANCE_CM) *
                            (MAX_ANGLE_DEG - MIN_ANGLE_DEG));
            log_data(distance);
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error: invalid distance reading\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Cleanup: stop servo pulses and release pigpio */
    gpioServo(SERVO_PIN, 0);
    gpioDelay(100000);
    gpioTerminate();

    printf("\nParking assist system stopped.\n");
    return EXIT_SUCCESS;
}

