    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: cannot set echo pin %d as input\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set servo pin %d as output\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50);

    /* Initialise servo to centre (90°) */
    set_servo_angle(0.0f);
    gpioDelay(500000);

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = read_distance();

        if (distance > 0.0f) {
            set_servo_angle((distance - MIN_DISTANCE_CM) /
                            (MAX_DISTANCE_CM - MIN_DISTANCE_CM) *
                            (MAX_ANGLE_DEG - MIN_ANGLE_DEG));
            log_data(distance);
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error: invalid distance reading\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Cleanup: stop servo pulses and release pigpio */
    gpioServo(SERVO_PIN, 0);
    gpioDelay(100000);
    gpioTerminate();

    printf("\nParking assist system stopped.\n");
    return EXIT_SUCCESS;
}

