    return 0;
}

static void log_distance(const char *message_queue_name, int distance) {
    mqd_t mq = mq_open(message_queue_name, O_CREAT | O_RDWR, 0666, NULL);
    if (mq == (mqd_t)-1) {
        fprintf(stderr, "Error opening message queue: %s\n", strerror(errno));
        return;
    }

    char message[MESSAGE_QUEUE_MSG_SIZE];
    snprintf(message, MESSAGE_QUEUE_MSG_SIZE, "%d", distance);

    if (mq_send(mq, message, strlen(message), 0) == -1) {
        fprintf(stderr, "Error sending message: %s\n", strerror(errno));
    }

    if (mq_close(mq) == -1) {
        fprintf(stderr, "Error closing message queue: %s\n", strerror(errno));
    }
}

int main() {
    int i2c_handle = -1;
    int distance = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", BUZZER_GPIO);
        gpioTerminate();
        return 1;
    }
    gpioWrite(BUZZER_GPIO, 0);

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        if (vl53l1x_read_distance(i2c_handle, &distance) == 0) {
            log_distance(MESSAGE_QUEUE_NAME, distance);
            if (distance < DISTANCE_THRESHOLD) {
                gpioWrite(BUZZER_GPIO, 1);
            } else {
                gpioWrite(BUZZER_GPIO, 0);
            }
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
            gpioWrite(BUZZER_GPIO, 0);
        }
        gpioDelay(50000);
    }

    gpioWrite(BUZZER_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

