/*
 * Parking sensor for Raspberry Pi 3 Model B+
 * HC-SR04 ultrasonic sensor:
 *   TRIGGER -> GPIO17 (BCM)
 *   ECHO    -> GPIO27 (BCM)
 * Buzzer:
 *   + -> GPIO22 (BCM)
 *   - -> GND
 *
 * Build: gcc -O2 -Wall -o parking_sensor parking_sensor.c -lpigpio -lrt
 * Run:   sudo ./parking_sensor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         27
#define BUZZER_PIN       22

#define SPEED_OF_SOUND   34300.0   /* cm/s at 20 °C */
#define DISTANCE_MIN     2.0       /* cm */
#define DISTANCE_MAX     400.0     /* cm */
#define BUZZER_THRESHOLD 30.0      /* cm */
#define SAMPLE_PERIOD_US 100000    /* 100 ms */
#define TRIGGER_PULSE_US 10        /* 10 µs */
#define ECHO_TIMEOUT_US  30000     /* 30 ms (~5 m round trip) */

/* ------------------------------------------------------------------ */
/* Shared state between ISR and main thread                            */
/* ------------------------------------------------------------------ */

typedef struct {
    volatile uint32_t start_tick;
    volatile uint32_t end_tick;
    volatile bool     got_rising;
    volatile bool     got_falling;
} echo_state_t;

static echo_state_t g_echo;
static volatile bool g_running = true;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = false;
}

/* ------------------------------------------------------------------ */
/* pigpio ISR callbacks                                                */
/* ------------------------------------------------------------------ */

static void echo_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    echo_state_t *st = (echo_state_t *)userdata;

    if (level == 1) {
        st->start_tick  = tick;
        st->got_rising  = true;
        st->got_falling = false;
    } else if (level == 0 && st->got_rising) {
        st->end_tick    = tick;
        st->got_falling = true;
    }
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

static uint32_t tick_diff(uint32_t start, uint32_t end)
{
    /* pigpio ticks are 32-bit microseconds and wrap every ~71.6 min */
    return end - start;  /* unsigned subtraction handles wraparound */
}

static double calculate_distance(uint32_t elapsed_us)
{
    return (elapsed_us / 1000000.0) * SPEED_OF_SOUND / 2.0;
}

static void control_buzzer(double distance)
{
    if (distance < BUZZER_THRESHOLD) {
        gpioWrite(BUZZER_PIN, 1);
    } else {
        gpioWrite(BUZZER_PIN, 0);
    }
}

static void log_distance(double distance)
{
    if (distance < DISTANCE_MIN || distance > DISTANCE_MAX) {
        printf("Distance: OUT OF RANGE (%.2f cm)\n", distance);
    } else {
        printf("Distance: %.2f cm\n", distance);
    }
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins ---- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: cannot set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: cannot set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: cannot set BUZZER_PIN %d as output.\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure known initial states */
    gpioWrite(TRIGGER_PIN, 0);
    gpioWrite(BUZZER_PIN, 0);

    /* ---- Register ISR on echo pin ---- */
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_isr, &g_echo) != 0) {
        fprintf(stderr, "Error: failed to register ISR on ECHO_PIN %d.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signal handling ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Parking sensor started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* ---- Main loop ---- */
    while (g_running) {
        /* Reset shared state */
        g_echo.start_tick  = 0;
        g_echo.end_tick    = 0;
        g_echo.got_rising  = false;
        g_echo.got_falling = false;

        /* Generate 10 µs trigger pulse */
        if (gpioWrite(TRIGGER_PIN, 1) != 0) {
            fprintf(stderr, "Error: failed to set TRIGGER_PIN high.\n");
            break;
        }
        gpioDelay(TRIGGER_PULSE_US);
        if (gpioWrite(TRIGGER_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to set TRIGGER_PIN low.\n");
            break;
        }

        /* Wait for echo with timeout (poll every 1 ms) */
        uint32_t waited = 0;
        while (!g_echo.got_falling && waited < ECHO_TIMEOUT_US && g_running) {
            gpioDelay(1000);
            waited += 1000;
        }

        if (!g_running) {
            break;
        }

        if (!g_echo.got_falling) {
            fprintf(stderr, "Error: echo timeout (no object detected or sensor absent).\n");
            gpioWrite(BUZZER_PIN, 0);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /* pigpio ticks are 32-bit and wrap every ~71.6 min; handle wrap */
        uint32_t elapsed = tick_diff(g_echo.start_tick, g_echo.end_tick);
        double distance = calculate_distance(elapsed);

        log_distance(distance);
        control_buzzer(distance);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ---- Cleanup ---- */
    gpioWrite(BUZZER_PIN, 0);
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);
    gpioTerminate();

    printf("\nParking sensor stopped.\n");
    return EXIT_SUCCESS;
}

