#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <pigpio.h>

#define I2C_BUS "/dev/i2c-1"
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define DISTANCE_THRESHOLD 20
#define LOG_FILE "gate_log.txt"
#define POLL_DELAY_US 100000
#define RETRY_DELAY_US 500000
#define MAX_RETRIES 3

#define VL53L1X_REG_SOFT_RESET 0x0000
#define VL53L1X_REG_SYSTEM_START 0x0001
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_DISTANCE 0x001E
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x0015

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    if (log_file) {
        fprintf(log_file, "[%s] %s\n", timestamp, message);
        fflush(log_file);
    }
    printf("[%s] %s\n", timestamp, message);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint16_t reg, uint8_t value) {
    uint8_t buf[3] = { (reg >> 8) & 0xFF, reg & 0xFF, value };
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint8_t *buf, int len) {
    uint8_t reg_buf[2] = { (reg >> 8) & 0xFF, reg & 0xFF };
    if (write(fd, reg_buf, 2) != 2) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int vl53l1x_init(int fd) {
    if (i2c_write_reg16(fd, VL53L1X_REG_SOFT_RESET, 0x00) < 0) return -1;
    gpioDelay(10000);
    if (i2c_write_reg16(fd, VL53L1X_REG_SOFT_RESET, 0x01) < 0) return -1;
    gpioDelay(10000);
    if (i2c_write_reg16(fd, VL53L1X_REG_SYSTEM_START, 0x01) < 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int vl53l1x_read_distance(int fd, int *distance) {
    uint8_t status = 0;
    uint8_t dist_buf[2] = {0};
    int timeout = 0;
    while (timeout < 100) {
        if (i2c_read_reg16(fd, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) < 0) return -1;
        if ((status & 0x01) != 0) break;
        gpioDelay(10000);
        timeout++;
    }
    if (timeout >= 100) return -1;
    if (i2c_read_reg16(fd, VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) < 0) return -1;
    *distance = (dist_buf[0] << 8) | dist_buf[1];
    if (i2c_write_reg16(fd, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) return -1;
    return 0;
}

static void control_servo(int position) {
    if (position < 0) position = 0;
    if (position > 180) position = 180;
    gpioServo(SERVO_PIN, position * 1000);
}

static void open_gate(void) {
    control_servo(180);
    log_event("Gate opened");
}

static void close_gate(void) {
    control_servo(0);
    log_event("Gate closed");
}

static void handle_remote_command(int command) {
    switch (command) {
        case 1: open_gate(); break;
        case 2: close_gate(); break;
        case 3: log_event("Gate status request: Closed"); break;
        default: log_event("Invalid remote command"); break;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return 1;
    }
    log_event("Starting gate control system");

    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        fclose(log_file);
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        log_event("Failed to open I2C bus");
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        log_event("Failed to acquire I2C bus access");
        close(i2c_fd);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    if (vl53l1x_init(i2c_fd) < 0) {
        log_event("VL53L1X initialization failed");
        close(i2c_fd);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }
    log_event("VL53L1X initialized");

    control_servo(0);
    log_event("Gate closed (initial state)");

    int distance, retries = 0;
    while (running) {
        if (vl53l1x_read_distance(i2c_fd, &distance) < 0) {
            log_event("Error reading distance");
            retries++;
            if (retries >= MAX_RETRIES) {
                log_event("Max retries reached, attempting reinit");
                if (vl53l1x_init(i2c_fd) < 0) {
                    log_event("Reinit failed, exiting");
                    break;
                }
                log_event("Reinit successful");
                retries = 0;
            }
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        retries = 0;

        if (distance > 0 && distance < DISTANCE_THRESHOLD) {
            if (control_servo(180) == 0) {
                log_event("Object detected, opening gate");
            } else {
                log_event("Error setting servo to open position");
            }
        } else {
            if (control_servo(0) == 0) {
                log_event("No object detected, closing gate");
            } else {
                log_event("Error setting servo to close position");
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    log_event("Shutting down");
    control_servo(0);
    if (i2c_fd >= 0) close(i2c_fd);
    gpioTerminate();
    if (log_file) fclose(log_file);
    return 0;
}

