/*
 * HC-SR04 Ultrasonic Distance Measurement — Raspberry Pi 4 Model B
 *
 * Wiring:
 *   TRIG -> GPIO23 (physical pin 16, BCM 23)
 *   ECHO -> GPIO24 (physical pin 18, BCM 24)  [5 V — level-shift to 3.3 V]
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24

#define TRIGGER_PULSE_US 10          /* 10 µs trigger pulse            */
#define SAMPLE_PERIOD_US 200000      /* 200 ms between measurements   */
#define MAX_PULSE_US     30000       /* >30 ms → no object / timeout   */
#define MIN_PULSE_US     100         /* <10 ms → noise                 */
#define ECHO_TIMEOUT_US  60000       /* 60 ms max echo wait            */

/* ------------------------------------------------------------------ */
/* Shared state between alert callback and main thread                */
/* ------------------------------------------------------------------ */

typedef struct {
    volatile uint32_t rising_tick;   /* pigpio tick when echo rose     */
    volatile uint32_t falling_tick;  /* pigpio tick when echo fell     */
    volatile bool     got_rising;    /* set when rising edge captured  */
    volatile bool     got_falling;   /* set when falling edge captured */
} echo_state_t;

static echo_state_t g_echo;
static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback — runs in pigpio notification thread          */
/* ------------------------------------------------------------------ */

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    echo_state_t *st = (echo_state_t *)userdata;

    if (level == 1) {
        st->rising_tick = tick;
        st->got_rising  = true;
    } else if (level == 0) {
        st->falling_tick = tick;
        st->got_falling  = true;
    }
    /* level == 2 indicates a timeout; ignore here. */
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/*
 * pigpio ticks are 32-bit microseconds and wrap every ~72 minutes.
 * Compute (b - a) modulo 2^32.
 */
static inline uint32_t tick_diff(uint32_t a, uint32_t b)
{
    return b - a;            /* unsigned subtraction wraps correctly */
}

static void get_iso_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tmv;
    localtime_r(&now, &tmv);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tmv);
}

static void log_reading(float distance_cm)
{
    char ts[32];
    get_iso_timestamp(ts, sizeof(ts));

    printf("[%s] Distance: %.2f cm\n", ts, distance_cm);

    if (g_log_fp) {
        fprintf(g_log_fp, "%s,%.2f\n", ts, distance_cm);
        fflush(g_log_fp);
    }
}

static void log_warning(const char *msg)
{
    char ts[32];
    get_iso_timestamp(ts, sizeof(ts));

    fprintf(stderr, "[%s] WARNING: %s\n", ts, msg);

    if (g_log_fp) {
        fprintf(g_log_fp, "%s,WARN,%s\n", ts, msg);
        fflush(g_log_fp);
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- Signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen("distance_log.txt", "a");
    if (!g_log_fp) {
        perror("fopen(distance_log.txt)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins ---- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(TRIGGER_PIN) failed\n");
        goto fail_init;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(ECHO_PIN) failed\n");
        goto fail_init;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(ECHO_PIN) failed\n");
        goto fail_init;
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite(TRIGGER_PIN, 0) failed\n");
        goto fail_init;
    }
    gpioDelay(5000);          /* 5 ms settle */

    /* ---- Register alert callback ---- */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, &g_echo) != 0) {
        fprintf(stderr, "gpioSetAlertFuncEx(ECHO_PIN) failed\n");
        goto fail_init;
    }

    printf("HC-SR04 ranging started.  TRIG=GPIO%d  ECHO=GPIO%d\n",
           TRIGGER_PIN, ECHO_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        /* Reset state before triggering */
        g_echo.rising_tick  = 0;
        g_echo.falling_tick = 0;
        g_echo.got_rising   = false;
        g_echo.got_falling  = false;

        /* Generate 10 µs trigger pulse */
        if (gpioTrigger(TRIGGER_PIN, TRIGGER_PULSE_US, 1) != 0) {
            fprintf(stderr, "gpioTrigger failed\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /* Wait for echo with timeout (60 ms) */
        uint32_t wait_start = gpioTick();
        while (!g_echo.got_falling && g_running) {
            if (tick_diff(wait_start, gpioTick()) > ECHO_TIMEOUT_US) {
                break;
            }
            gpioDelay(100);          /* poll every 100 µs */
        }

        if (!g_echo.got_rising) {
            log_warning("No rising edge detected (sensor absent or wiring fault)");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        if (!g_echo.got_falling) {
            log_warning("Timeout waiting for falling edge (no object or sensor fault)");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /*
         * Compute pulse duration with 32-bit wraparound correction.
         * pigpio ticks are microseconds and wrap every ~72 min.
         */
        uint32_t pulse_us = tick_diff(g_echo.rising_tick, g_echo.falling_tick);

        if (pulse_us < MIN_PULSE_US) {
            log_warning("Pulse too short (noise / invalid)");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        if (pulse_us > MAX_PULSE_US) {
            log_warning("Pulse too long (timeout / no object)");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /* distance = (pulse * speed_of_sound) / 2 */
        float distance_cm = (float)pulse_us * 0.0343f / 2.0f;

        log_reading(distance_cm);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ---- Cleanup ---- */
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);   /* unregister callback */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();

    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;

fail_init:
    gpioTerminate();
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    return EXIT_FAILURE;
}

