/*
 * Smart Parking Gate - Raspberry Pi 4 Model B
 * Sensor:  VL53L1X time-of-flight (I2C bus 1, shutdown=GPIO23, int=GPIO24)
 * Actuator: Servo motor (hardware PWM on GPIO18)
 *
 * Build:  gcc -O2 -Wall -o parking_gate parking_gate.c -lpigpio -lrt
 * Run:    sudo ./parking_gate
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define VL53L1X_ADDR         0x29
#define SHUTDOWN_PIN         23
#define INTERRUPT_PIN        24
#define SERVO_PIN            18

#define DISTANCE_THRESHOLD_OPEN  50.0f   /* cm - open gate when within this */
#define DISTANCE_THRESHOLD_CLOSE 60.0f   /* cm - close gate when above this */
#define SERVO_MIN_PULSE_US      500     /* microseconds (~0 deg) */
#define SERVO_MAX_PULSE_US      2500    /* microseconds (~180 deg) */
#define SERVO_CENTER_PULSE_US  1500    /* microseconds (~90 deg) */

#define LOG_FILE_NAME         "parking_log.txt"
#define POLL_DELAY_US         100000   /* 100 ms between readings */
#define INIT_DELAY_US         200000   /* 200 ms after power-up */

/* VL53L1X register addresses */
#define VL53L1X_REG_SOFT_RESET              0x0003
#define VL53L1X_REG_I2C_SLAVE_DEVICE_ADDR   0x0001
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR  0x0086
#define VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG 0x008A
#define VL53L1X_REG_SYSTEM_INTERRUPT_STATUS 0x0089
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x0089
#define VL53L1X_REG_RESULT_RANGE_STATUS     0x0089
#define VL53L1X_REG_RESULT_DISTANCE         0x0096
#define VL53L1X_REG_MODEL_ID                0x010F
#define VL53L1X_REG_RANGE_START             0x0080
#define VL53L1X_REG_RANGE_STOP              0x0085

#define VL53L1X_MODEL_ID_EXPECTED           0xEA

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  init_i2c(void);
static int  init_vl53l1x(void);
static int  read_distance(float *distance_out);
static void control_servo(float distance);
static void log_event(int gate_state, float distance);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- I2C / VL53L1X helpers --------------------- */
static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint8_t len)
{
    char cmd[2];
    cmd[0] = (reg >> 8) & 0xFF;
    cmd[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, cmd, 2) < 0)
        return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, VL53L1X_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int init_vl53l1x(void)
{
    uint8_t model_id = 0;

    /* Read model ID to confirm sensor is present and responding */
    if (i2c_read_reg16(g_i2c_handle, VL53L1X_REG_MODEL_ID, &model_id, 1) < 0) {
        fprintf(stderr, "[ERROR] Failed to read VL53L1X model ID (I2C bus error).\n");
        return -1;
    }
    if (model_id != VL53L1X_MODEL_ID_EXPECTED) {
        fprintf(stderr, "[ERROR] VL53L1X model ID mismatch: got 0x%02X, expected 0x%02X.\n",
                model_id, VL53L1X_MODEL_ID_EXPECTED);
        return -1;
    }
    printf("[INFO] VL53L1X detected (model ID 0x%02X).\n", model_id);

    /* Soft reset */
    if (i2c_write_reg16(g_i2c_handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "[ERROR] Soft reset write failed.\n");
        return -1;
    }
    gpioDelay(1000); /* 1 ms */

    /* Clear any pending interrupts */
    if (i2c_write_reg16(g_i2c_handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        fprintf(stderr, "[ERROR] Interrupt clear write failed.\n");
        return -1;
    }

    /* Configure interrupt: new sample ready */
    if (i2c_write_reg16(g_i2c_handle, VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG, 0x04) < 0) {
        fprintf(stderr, "[ERROR] Interrupt config write failed.\n");
        return -1;
    }

    /* Start continuous ranging */
    if (i2c_write_reg16(g_i2c_handle, VL53L1X_REG_RANGE_START, 0x01) < 0) {
        fprintf(stderr, "[ERROR] Range start write failed.\n");
        return -1;
    }

    printf("[INFO] VL53L1X initialized and ranging started.\n");
    return 0;
}

static int read_distance(float *distance_out)
{
    uint8_t status = 0;
    uint8_t data[2] = {0};

    /* Poll for new data-ready interrupt */
    for (int i = 0; i < 10; i++) {
        if (i2c_read_reg16(g_i2c_handle, VL53L1X_REG_SYSTEM_INTERRUPT_STATUS, &status, 1) < 0)
            return -1;
        if (status & 0x01)
            break;
        gpioDelay(1000); /* 1 ms */
    }
    if (!(status & 0x01)) {
        fprintf(stderr, "[WARN] VL53L1X data-ready timeout.\n");
        return -1;
    }

    /* Read 16-bit distance */
    if (i2c_read_reg16(g_i2c_handle, VL53L1X_REG_RESULT_DISTANCE, data, 2) < 0)
        return -1;

    uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
    *distance_out = (float)raw / 100.0f; /* mm -> cm */

    /* Clear interrupt so next measurement can trigger */
    if (i2c_write_reg16(g_i2c_handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0)
        return -1;

    return 0;
}

/* ----------------------------- Servo control ----------------------------- */
static void control_servo(float distance)
{
    int pulse_us;

    if (distance < DISTANCE_THRESHOLD_OPEN) {
        pulse_us = SERVO_MIN_PULSE_US; /* open gate */
    } else if (distance > DISTANCE_THRESHOLD_CLOSE) {
        pulse_us = SERVO_MAX_PULSE_US; /* close gate */
    } else {
        pulse_us = SERVO_CENTER_PULSE_US; /* hold position */
    }

    if (gpioServo(SERVO_PIN, pulse_us) < 0)
        fprintf(stderr, "[WARN] gpioServo failed for pin %d.\n", SERVO_PIN);
}

/* ----------------------------- Logging ----------------------------------- */
static void log_event(int gate_state, float distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s, Gate: %s, Distance: %.2f cm\n",
            timestamp, gate_state ? "OPEN" : "CLOSED", distance);
    fflush(g_log_file);
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    int gate_open = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(SHUTDOWN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(INTERRUPT_PIN,  PI_INPUT)  < 0 ||
        gpioSetMode(SERVO_PIN,     PI_OUTPUT) < 0) {
        fprintf(stderr, "[FATAL] gpioSetMode failed.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Power-cycle the VL53L1X */
    gpioWrite(SHUTDOWN_PIN, 0);
    gpioDelay(10000); /* 10 ms */
    gpioWrite(SHUTDOWN_PIN, 1);
    gpioDelay(10000); /* 10 ms */
    gpioWrite(SHUTDOWN_PIN, 0);
    gpioDelay(10000); /* 10 ms */

    /* Initialize I2C and sensor */
    if (init_i2c() < 0 || init_vl53l1x() < 0) {
        fprintf(stderr, "[FATAL] VL53L1X initialization failed.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'.\n", LOG_FILE_NAME);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("[INFO] Smart parking gate running. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        float distance = 0.0f;

        if (read_distance(&distance) < 0) {
            fprintf(stderr, "[WARN] Distance read failed; retrying.\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        control_servo(distance);

        if (distance < DISTANCE_THRESHOLD_OPEN && !gate_open) {
            gpioWrite(SHUTDOWN_PIN, 0);
            gpioDelay(10000); /* 10 ms settle */
            gpioServo(SERVO_PIN, SERVO_MIN_PULSE_US);
            gate_open = 1;
            log_event(gate_open, distance);
            printf("[INFO] Gate OPEN  (distance: %.2f cm)\n", distance);
        } else if (distance > DISTANCE_THRESHOLD_CLOSE && gate_open) {
            gpioWrite(SHUTDOWN_PIN, 1);
            gpioDelay(10000); /* 10 ms settle */
            gpioServo(SERVO_PIN, SERVO_MAX_PULSE_US);
            gate_open = 0;
            log_event(gate_open, distance);
            printf("[INFO] Gate CLOSED (distance: %.2f cm)\n", distance);
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Graceful shutdown */
    printf("\n[INFO] Shutting down...\n");
    gpioServo(SERVO_PIN, SERVO_CENTER_PULSE_US);
    gpioWrite(SHUTDOWN_PIN, 1);
    gpioDelay(100000); /* 100 ms */
    cleanup();
    printf("[INFO] Done.\n");
    return EXIT_SUCCESS;
}

