#define VL53L1X_VHV_CONFIG 0x0001
#define VL53L1X_PHASECAL_CONFIG 0x0002
#define VL53L1X_RANGE_CONFIG_A 0x000A
#define VL53L1X_RANGE_CONFIG_B 0x000B
#define VL53L1X_INTERMEASUREMENT_PERIOD 0x000C
#define VL53L1X_SYSTEM_INTERRUPT_CONFIG_GPIO 0x000A
#define VL53L1X_SYSTEM_INTERRUPT_CLEAR 0x000B
#define VL53L1X_RESULT_INTERRUPT_STATUS 0x0044
#define VL53L1X_RESULT_RANGE_STATUS 0x004D
#define VL53L1X_RESULT_DISTANCE 0x0062
#define VL53L1X_SYSTEM_START 0x0000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a 16-bit value to a 16-bit register address */
static int vl53l1x_write_reg16(int handle, uint16_t reg, uint16_t value) {
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteDevice(handle, buf, 4);
}

/* Read a 16-bit value from a 16-bit register address */
static int vl53l1x_read_reg16(int handle, uint16_t reg, uint16_t *value) {
    char reg_buf[2];
    char data_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) < 0) return -1;
    if (i2cReadDevice(handle, data_buf, 2) != 2) return -1;
    *value = ((uint16_t)(data_buf[0] << 8)) | (uint8_t)data_buf[1];
    return 0;
}

static int vl53l1x_init(int handle) {
    if (vl53l1x_write_reg16(handle, VL53L1X_SOFT_RESET, 0x0001) < 0) return -1;
    gpioDelay(10000);
    if (vl53l1x_write_reg16(handle, VL53L1X_SOFT_RESET, 0x0000) < 0) return -1;
    gpioDelay(10000);
    if (vl53l1x_write_reg16(handle, VL53L1X_VHV_CONFIG, 0x0001) < 0) return -1;
    if (vl53l1x_write_reg16(handle, VL53L1X_PHASECAL_CONFIG, 0x0001) < 0) return -1;
    if (vl53l1x_write_reg16(handle, VL53L1X_RANGE_CONFIG_A, 0x0000) < 0) return -1;
    if (vl53l1x_write_reg16(handle, VL53L1X_RANGE_CONFIG_B, 0x0000) < 0) return -1;
    if (vl53l1x_write_reg16(handle, VL53L1X_INTERMEASUREMENT_PERIOD, 0x0000) < 0) return -1;
    if (vl53l1x_write_reg16(handle, VL53L1X_SYSTEM_INTERRUPT_CONFIG_GPIO, 0x0001) < 0) return -1;
    if (vl53l1x_write_reg16(handle, VL53L1X_SYSTEM_START, 0x0001) < 0) return -1;
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm) {
    uint16_t status;
    uint16_t dist;
    if (vl53l1x_read_reg16(handle, VL53L1X_RESULT_INTERRUPT_STATUS, &status) < 0) return -1;
    if ((status & 0x01) == 0) return 1; /* data not ready */
    if (vl53l1x_read_reg16(handle, VL53L1X_RESULT_RANGE_STATUS, &status) < 0) return -1;
    if ((status & 0x01) == 0) return 2; /* range error */
    if (vl53l1x_read_reg16(handle, VL53L1X_RESULT_DISTANCE, &dist) < 0) return -1;
    *distance_mm = dist;
    if (vl53l1x_write_reg16(handle, VL53L1X_SYSTEM_INTERRUPT_CLEAR, 0x0001) < 0) return -1;
    return 0;
}

static void log_event(const char *event) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];
    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(GATE_OPEN_PIN, 0);
    gpioWrite(GATE_CLOSE_PIN, 1);
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    gpioSetMode(GATE_OPEN_PIN, PI_OUTPUT);
    gpioSetMode(GATE_CLOSE_PIN, PI_OUTPUT);
    gpioWrite(GATE_OPEN_PIN, 0);
    gpioWrite(GATE_CLOSE_PIN, 1);
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        cleanup();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    printf("Gate control system started. Press Ctrl+C to exit.\n");
    while (!terminate) {
        uint16_t distance;
        int ret = vl53l1x_read_distance(i2c_handle, &distance);
        if (ret == 0) {
            if (distance <= DISTANCE_THRESHOLD_MM) {
                gpioWrite(GATE_OPEN_PIN, 1);
                gpioWrite(GATE_CLOSE_PIN, 0);
                log_event("Gate opened");
            } else {
                gpioWrite(GATE_OPEN_PIN, 0);
                gpioWrite(GATE_CLOSE_PIN, 1);
                log_event("Gate closed");
            }
        } else if (ret < 0) {
            fprintf(stderr, "Error reading distance: %d\n", ret);
            log_event("Error reading distance");
            gpioWrite(GATE_OPEN_PIN, 0);
            gpioWrite(GATE_CLOSE_PIN, 1);
        }
        gpioDelay(POLL_DELAY_US);
    }
    cleanup();
    return 0;
}

