/*
 * VL53L1X distance-controlled robot on Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   VL53L1X SDA -> GPIO2 (I2C bus 1 SDA)
 *   VL53L1X SCL -> GPIO3 (I2C bus 1 SCL)
 *   VL53L1X VDD -> 3.3 V
 *   VL53L1X GND -> GND
 *   Motor +     -> GPIO17 (PWM via pigpio)
 *   Motor -     -> GPIO18 (PWM via pigpio)
 *   Trigger     -> GPIO24 (rising-edge ISR)
 *
 * Build:  gcc -O2 -Wall -Wextra -o vl53l1x_robot vl53l1x_robot.c -lpigpio -lrt
 * Run:    sudo ./vl53l1x_robot
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin / bus / sensor constants ---- */
#define I2C_BUS              1
#define VL53L1X_ADDR         0x29
#define TRIGGER_PIN          24
#define MOTOR_FORWARD_PIN    17
#define MOTOR_BACKWARD_PIN   18

#define DISTANCE_THRESHOLD_NEAR  100   /* mm */
#define DISTANCE_THRESHOLD_FAR   300   /* mm */

/* VL53L1X register addresses */
#define VL53L1X_REG_SOFT_RESET              0x0003
#define VL53L1X_REG_SYSTEM_MODE_START       0x0000
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x0044
#define VL53L1X_REG_RESULT_DISTANCE         0x0096

/* ---- Globals ---- */
static int           i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* ---- Prototypes ---- */
static void signal_handler(int sig);
static void trigger_isr(int gpio, int level, uint32_t tick, void *userdata);
static int  vl53l1x_write_reg16(uint8_t reg, uint16_t val);
static int  vl53l1x_read_reg16(uint8_t reg, uint16_t *val);
static int  vl53l1x_read_reg8(uint8_t reg, uint8_t *val);
static int  vl53l1x_init(void);
static int  vl53l1x_read_distance(uint16_t *distance_mm);
static void motor_forward(void);
static void motor_backward(void);
static void motor_stop(void);
static void log_data(uint16_t distance, const char *state);
static void cleanup(void);

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ---- ISR: rising edge on TRIGGER_PIN triggers a distance reading ---- */
static void trigger_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)level;
    (void)tick;
    (void)userdata;

    if (vl53l1x_read_distance(&distance) == 0) {
        log_data(distance, "reading");
        if (distance < DISTANCE_THRESHOLD_NEAR) {
            motor_forward();
            log_data(distance, "near->forward");
        } else if (distance > DISTANCE_THRESHOLD_FAR) {
            motor_backward();
            log_data(distance, "far->backward");
        } else {
            motor_stop();
            log_data(distance, "stopped");
        }
    } else {
        fprintf(stderr, "Error reading distance from sensor.\n");
    }
}

/* ---- VL53L1X register helpers (16-bit register addressing) ---- */
static int vl53l1x_write_reg16(uint8_t reg, uint16_t val)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(val & 0xFF);        /* LSB first */
    buf[2] = (char)((val >> 8) & 0xFF); /* MSB second */

    int rc = i2cWriteDevice(i2c_handle, buf, 3);
    if (rc < 0) {
        fprintf(stderr, "I2C write to reg 0x%02X failed (rc=%d).\n", reg, rc);
        return -1;
    }
    return 0;
}

static int vl53l1x_read_reg16(uint8_t reg, uint16_t *val)
{
    char reg_buf[1] = { (char)reg };
    int rc = i2cWriteDevice(i2c_handle, reg_buf, 1);
    if (rc < 0) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed (rc=%d).\n", reg, rc);
        return -1;
    }

    char data[2];
    rc = i2cReadDevice(i2c_handle, data, 2);
    if (rc < 0) {
        fprintf(stderr, "I2C read from reg 0x%02X failed (rc=%d).\n", reg, rc);
        return -1;
    }
    if (rc != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X short read (%d bytes).\n", reg, rc);
        return -1;
    }

    *val = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static int vl53l1x_read_reg8(uint8_t reg, uint8_t *val)
{
    char reg_buf[1] = { (char)reg };
    int rc = i2cWriteDevice(i2c_handle, reg_buf, 1);
    if (rc < 0) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed (rc=%d).\n", reg, rc);
        return -1;
    }

    char data[1];
    rc = i2cReadDevice(i2c_handle, data, 1);
    if (rc < 0) {
        fprintf(stderr, "I2C read from reg 0x%02X failed (rc=%d).\n", reg, rc);
        return -1;
    }
    if (rc != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X short read (%d bytes).\n", reg, rc);
        return -1;
    }

    *val = (uint8_t)data[0];
    return 0;
}

/* ---- VL53L1X initialization ---- */
static int vl53l1x_init(void)
{
    /* Soft reset: write 0x0001 to SOFT_RESET register */
    if (vl53l1x_write_reg16(VL53L1X_REG_SOFT_RESET, 0x0001) != 0) {
        fprintf(stderr, "VL53L1X soft reset failed.\n");
        return -1;
    }
    gpioDelay(1000); /* 1 ms */

    /* Start continuous measurement: write 0x0001 to SYSTEM_MODE_START */
    if (vl53l1x_write_reg16(VL53L1X_REG_SYSTEM_MODE_START, 0x0001) != 0) {
        fprintf(stderr, "VL53L1X start measurement failed.\n");
        return -1;
    }

    printf("VL53L1X initialized and continuous measurement started.\n");
    return 0;
}

/* ---- Read distance with retry and exponential backoff ---- */
static int vl53l1x_read_distance(uint16_t *distance_mm)
{
    int retries = 3;
    int delay_ms = 10;

    while (retries > 0) {
        uint16_t status = 0;
        if (vl53l1x_read_reg16(VL53L1X_REG_RESULT_INTERRUPT_STATUS, &status) != 0) {
            fprintf(stderr, "Failed to read interrupt status.\n");
            retries--;
            gpioDelay(delay_ms * 1000);
            delay_ms *= 2;
            continue;
        }

        if (status & 0x07) {
            /* Data ready bit (bit 0) is set */
            uint16_t dist = 0;
            if (vl53l1x_read_reg16(VL53L1X_REG_RESULT_DISTANCE, &dist) == 0) {
                *distance_mm = dist;
                return 0;
            }
            fprintf(stderr, "Failed to read distance register.\n");
        }

        retries--;
        gpioDelay(delay_ms * 1000);
        delay_ms *= 2;
    }

    fprintf(stderr, "VL53L1X read failed after retries.\n");
    return -1;
}

/* ---- Motor control ---- */
static void motor_forward(void)
{
    gpioWrite(MOTOR_FORWARD_PIN, 1);
    gpioWrite(MOTOR_BACKWARD_PIN, 0);
    printf("Motor: forward\n");
}

static void motor_backward(void)
{
    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_BACKWARD_PIN, 1);
    printf("Motor: backward\n");
}

static void motor_stop(void)
{
    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_BACKWARD_PIN, 0);
    printf("Motor: stopped\n");
}

/* ---- Logging ---- */
static void log_data(uint16_t distance, const char *state)
{
    printf("Distance: %u mm, %s\n", distance, state);
    fflush(stdout);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        /* Attempt a stop command before closing */
        (void)vl53l1x_write_reg16(VL53L1X_REG_SYSTEM_MODE_START, 0x0000);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }

    motor_stop();
    gpioTerminate();
    printf("Cleanup complete.\n");
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    gpioSetMode(MOTOR_FORWARD_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_BACKWARD_PIN, PI_OUTPUT);
    gpioSetMode(TRIGGER_PIN, PI_INPUT);

    /* Ensure motor is stopped initially */
    motor_stop();

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X (rc=%d).\n",
                I2C_BUS, VL53L1X_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize VL53L1X sensor */
    if (vl53l1x_init() != 0) {
        fprintf(stderr, "VL53L1X initialization failed. Check wiring and sensor presence.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register ISR on TRIGGER_PIN */
    if (gpioSetISRFuncEx(TRIGGER_PIN, RISING_EDGE, 0, trigger_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR on GPIO %d.\n", TRIGGER_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Robot running. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        gpioDelay(100000); /* 100 ms */
    }

    cleanup();
    return EXIT_SUCCESS;
}

