 *   VL53L1X SCL -> GPIO3 (I2C bus 1 SCL)
 *   VL53L1X VDD -> 3.3 V
 *   VL53L1X GND -> GND
 *   Motor +     -> GPIO17 (PWM via pigpio)
 *   Motor -     -> GPIO18 (PWM via pigpio)
 *   Trigger     -> GPIO24 (rising-edge ISR)
 *
 * Build:  gcc -O2 -Wall -Wextra -o vl53l1x_robot vl53l1x_robot.c -lpigpio -lrt
 * Run:    sudo ./vl53l1x_robot
 */

#include <stdio.h>
