#include <pigpio.h>

/* ---- Pin / bus / sensor constants ---- */
#define I2C_BUS              1
#define VL53L1X_ADDR         0x29
#define TRIGGER_PIN          24
#define MOTOR_FORWARD_PIN    17
#define MOTOR_BACKWARD_PIN   18

#define DISTANCE_THRESHOLD_NEAR  100   /* mm */
#define DISTANCE_THRESHOLD_FAR   300   /* mm */

/* VL53L1X register addresses */
#define VL53L1X_REG_SOFT_RESET              0x0003
#define VL53L1X_REG_SYSTEM_MODE_START       0x0000
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x0044
