    int rc = i2cWriteDevice(i2c_handle, buf, 3);
    if (rc < 0) {
        fprintf(stderr, "I2C write to reg 0x%02X failed (rc=%d).\n", reg, rc);
        return -1;
    }
    return 0;
}

static int vl53l1x_read_reg16(uint8_t reg, uint16_t *val)
{
    char reg_buf[1] = { (char)reg };
    int rc = i2cWriteDevice(i2c_handle, reg_buf, 1);
    if (rc < 0) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed (rc=%d).\n", reg, rc);
        return -1;
    }

    char data[2];
    rc = i2cReadDevice(i2c_handle, data, 2);
    if (rc < 0) {
        fprintf(stderr, "I2C read from reg 0x%02X failed (rc=%d).\n", reg, rc);
        return -1;
    }
    if (rc != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X short read (%d bytes).\n", reg, rc);
        return -1;
    }

