    if (vl53l1x_write_reg16(VL53L1X_REG_SYSTEM_MODE_START, 0x0001) != 0) {
        fprintf(stderr, "VL53L1X start measurement failed.\n");
        return -1;
    }

    printf("VL53L1X initialized and continuous measurement started.\n");
    return 0;
}

/* ---- Read distance with retry and exponential backoff ---- */
static int vl53l1x_read_distance(uint16_t *distance_mm)
{
    int retries = 3;
    int delay_ms = 10;

    while (retries > 0) {
        uint16_t status = 0;
        if (vl53l1x_read_reg16(VL53L1X_REG_RESULT_INTERRUPT_STATUS, &status) != 0) {
            fprintf(stderr, "Failed to read interrupt status.\n");
