    fflush(stdout);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        /* Attempt a stop command before closing */
        (void)vl53l1x_write_reg16(VL53L1X_REG_SYSTEM_MODE_START, 0x0000);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }

    motor_stop();
