/*
 * Proximity-based Interactive Art Installation
 * Board:  Raspberry Pi 3 Model B+
 * Sensor: MPR121 capacitive touch sensor (I2C /dev/i2c-1)
 * LEDs:   4-bit pattern on GPIO 17, 18, 27, 22 (BCM)
 *
 * Build:  gcc -O2 -Wall -o proximity_art proximity_art.c -lpigpio -lrt
 * Run:    sudo ./proximity_art
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* ---- MPR121 I2C ---- */
#define I2C_BUS        "/dev/i2c-1"
#define MPR121_ADDR    0x4D          /* SA0 tied to GND */

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L  0x00
#define MPR121_TOUCHSTATUS_H  0x01
#define MPR121_ELECONFIG      0x5E
#define MPR121_SOFTRESET      0x80

/* ---- LED GPIO (BCM) ---- */
#define LED_PIN_0 17
#define LED_PIN_1 18
#define LED_PIN_2 27
#define LED_PIN_3 22

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd   = -1;
static FILE    *g_log_file = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an MPR121 register; returns 0 on success, -1 on error. */
static int mpr121_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read one byte from an MPR121 register; returns 0 on success, -1 on error. */
static int mpr121_read_reg(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

/* ------------------------------------------------------------------ */
static int mpr121_init(int fd)
{
    /* Soft reset */
    if (mpr121_write_reg(fd, MPR121_SOFTRESET, 0x63) < 0)
        return -1;
    usleep(10000);  /* 10 ms settle */

    /*
     * Electrode configuration:
     *   ELE0-ELE3  enabled (0x0C)
     *   ELE4-ELE11 disabled (0x00)
     *   -> 0x0C | 0x00 = 0x0C
     */
    if (mpr121_write_reg(fd, MPR121_ELECONFIG, 0x0C) < 0)
        return -1;

    /* Verify the sensor is present by reading back the config register */
    uint8_t cfg;
    if (mpr121_read_reg(fd, MPR121_ELECONFIG, &cfg) < 0)
        return -1;
    if (cfg != 0x0C) {
        fprintf(stderr, "MPR121 not responding: config readback = 0x%02X\n", cfg);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static void set_led_pattern(uint8_t pattern)
{
    gpioWrite(LED_PIN_0, (pattern & 0x01) ? 1 : 0);
    gpioWrite(LED_PIN_1, (pattern & 0x02) ? 1 : 0);
    gpioWrite(LED_PIN_2, (pattern & 0x04) ? 1 : 0);
    gpioWrite(LED_PIN_3, (pattern & 0x08) ? 1 : 0);
}

/* ------------------------------------------------------------------ */
static void log_proximity_event(uint8_t electrode)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s - Electrode %u detected proximity\n",
            timestamp, electrode);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Turn off all LEDs */
    set_led_pattern(0x00);

    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handlers ---- */
    struct sigaction sa;
