    }

    /* ---- GPIO setup ---- */
    uint8_t led_pins[4] = { LED_PIN_0, LED_PIN_1, LED_PIN_2, LED_PIN_3 };
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(led_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %u as output\n", led_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        gpioWrite(led_pins[i], 0);
    }

    /* ---- I2C open ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                MPR121_ADDR, strerror(errno));
