    }

    /* ---- MPR121 init ---- */
    if (mpr121_init(g_i2c_fd) < 0) {
        fprintf(stderr, "MPR121 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Log file ---- */
    g_log_file = fopen("proximity_log.txt", "a");
    if (!g_log_file) {
        fprintf(stderr, "Cannot open log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Proximity art installation running. Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        uint8_t lo, hi;
        if (mpr121_read_reg(g_i2c_fd, MPR121_TOUCHSTATUS_L, &lo) < 0 ||
            mpr121_read_reg(g_i2c_fd, MPR121_TOUCHSTATUS_H, &hi) < 0) {
            fprintf(stderr, "Read error - continuing\n");
            usleep(50000);
            continue;
        }

        uint16_t touch_status = (uint16_t)((hi << 8) | lo);

        if (touch_status != 0) {
            uint8_t electrode = 0;
            for (int i = 0; i < 12; i++) {
