#define MPR121_ADDR 0x25
#define I2C_BUS 1
#define LED_PIN 27
#define LOG_FILE "proximity.log"

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECONFIG0 0x5E
#define MPR121_ELECONFIG1 0x5F
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_MHD_R 0x2B
#define MPR121_NHD_R 0x2C
#define MPR121_NCL_R 0x2D
#define MPR121_FDL_R 0x2E
#define MPR121_MHD_F 0x2F
#define MPR121_NHD_F 0x30
#define MPR121_NCL_F 0x31
#define MPR121_FDL_F 0x32
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_DEBOUNCE_R 0x5B
#define MPR121_CONFIG1_R 0x5C
#define MPR121_CONFIG2_R 0x5D
#define MPR121_MHD_R_F 0x2B
#define MPR121_NHD_R_F 0x2C
#define MPR121_NCL_R_F 0x2D
#define MPR121_FDL_R_F 0x2E
#define MPR121_MHD_F_F 0x2F
#define MPR121_NHD_F_F 0x30
#define MPR121_NCL_F_F 0x31
#define MPR121_FDL_F_F 0x32
#define MPR121_E0TTH_F 0x46
#define MPR121_E0RTH_F 0x47
#define MPR121_DEBOUNCE_F 0x5B
#define MPR121_CONFIG1_F 0x5C
#define MPR121_CONFIG2_F 0x5D
#define MPR121_ELECONFIG0_F 0x5E
#define MPR121_ELECONFIG1_F 0x5F
#define MPR121_SOFTRESET 0x80
#define MPR121_DEVICE_ID 0x5C

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int mpr121_write_reg(uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(i2c_handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

int mpr121_read_reg(uint8_t reg) {
    int result = i2cReadByteData(i2c_handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

int mpr121_init() {
    if (mpr121_write_reg(MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(10000);

    if (mpr121_write_reg(MPR121_ELECONFIG0, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_ELECONFIG1, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_CONFIG1, 0x10) < 0) return -1;
    if (mpr121_write_reg(MPR121_CONFIG2, 0x20) < 0) return -1;
    if (mpr121_write_reg(MPR121_MHD_R, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHD_R, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCL_R, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDL_R, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_MHD_F, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHD_F, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCL_F, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDL_F, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_E0TTH, 0x0F) < 0) return -1;
    if (mpr121_write_reg(MPR121_E0RTH, 0x0A) < 0) return -1;
    if (mpr121_write_reg(MPR121_DEBOUNCE_R, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_CONFIG1_R, 0x10) < 0) return -1;
    if (mpr121_write_reg(MPR121_CONFIG2_R, 0x20) < 0) return -1;
    if (mpr121_write_reg(MPR121_MHD_R_F, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHD_R_F, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCL_R_F, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDL_R_F, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_MHD_F_F, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHD_F_F, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCL_F_F, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDL_F_F, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_E0TTH_F, 0x0F) < 0) return -1;
    if (mpr121_write_reg(MPR121_E0RTH_F, 0x0A) < 0) return -1;
    if (mpr121_write_reg(MPR121_DEBOUNCE_F, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_CONFIG1_F, 0x10) < 0) return -1;
    if (mpr121_write_reg(MPR121_CONFIG2_F, 0x20) < 0) return -1;
    if (mpr121_write_reg(MPR121_ELECONFIG0_F, 0x0C) < 0) return -1;
    if (mpr121_write_reg(MPR121_ELECONFIG1_F, 0x0C) < 0) return -1;

    return 0;
}

int read_touch_data() {
    int low = mpr121_read_reg(MPR121_TOUCHSTATUS_L);
    if (low < 0) return -1;
    int high = mpr121_read_reg(MPR121_TOUCHSTATUS_H);
    if (high < 0) return -1;
    return (high << 8) | low;
}

void log_proximity_event() {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - Proximity detected!\n", s);
    fclose(fp);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    int device_id = mpr121_read_reg(MPR121_DEVICE_ID);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (device_id != 0x33) {
        fprintf(stderr, "Incorrect device ID: 0x%02X (expected 0x33)\n", device_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Proximity detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int touch_data = read_touch_data();
        if (touch_data < 0) {
            fprintf(stderr, "Error reading touch data, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        if (touch_data & 0x01) {
            printf("Proximity detected!\n");
            gpioWrite(LED_PIN, 1);
            log_proximity_event();
            gpioDelay(1000000);
            gpioWrite(LED_PIN, 0);
        }

        gpioDelay(50000);
    }

    gpioWrite(LED_PIN, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

