/*
 * HC-SR04 Ultrasonic Distance Measurement — Raspberry Pi Zero W
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO17 (BCM)
 *   HC-SR04 ECHO -> GPIO18 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c
 *
 * Run:
 *   ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18
#define LOG_FILE         "distance_log.txt"
#define SAMPLE_PERIOD_S  1
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  30000   /* 30 ms max echo wait */
#define SAMPLE_WAIT_US   30000   /* 30 ms post-trigger settle */
#define MIN_DISTANCE_CM  2.0f
#define MAX_DISTANCE_CM  400.0f
#define SPEED_OF_SOUND   34300.0f /* cm/s at ~20 C */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Returns 0 on success, -1 on timeout or error.                       */
static int trigger_pulse(int trigger_pin)
{
    if (gpioWrite(trigger_pin, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -1;
    }
    gpioDelay(5);                       /* 5 us settle */

    if (gpioWrite(trigger_pin, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 1) failed\n");
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US);        /* 10 us pulse */

    if (gpioWrite(trigger_pin, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Returns distance in cm, or -1.0f on timeout / error.                 */
static float measure_distance(int trigger_pin, int echo_pin)
{
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t deadline;

    /* Wait for echo rising edge */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(echo_pin) == 0) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: echo rising edge timeout "
                            "(sensor absent or wiring fault)\n");
            return -1.0f;
        }
        gpioDelay(20);
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    deadline = start_tick + ECHO_TIMEOUT_US;
    while (gpioRead(echo_pin) == 1) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: echo falling edge timeout "
                            "(stuck high or out of range)\n");
            return -1.0f;
        }
        gpioDelay(20);
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    float distance = (float)pulse_us * SPEED_OF_SOUND / 2000000.0f;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range "
                    "(2–400 cm)\n", distance);
        return -1.0f;
    }
    return distance;
}

/* ------------------------------------------------------------------ */
static void log_distance(FILE *fp, float distance)
{
    time_t rawtime;
    struct tm tm_info;
    char timestamp[32];

    time(&rawtime);
    gmtime_r(&rawtime, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_info);

    if (distance < 0.0f) {
        fprintf(fp, "%s, ERROR\n", timestamp);
    } else {
        fprintf(fp, "%s, %.2f\n", timestamp, distance);
    }
    fflush(fp);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- GPIO configuration ------------------------------------------ */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(50);                       /* 50 us settle */

    /* --- Open log file ----------------------------------------------- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handling --------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Error: sigaction(SIGINT) failed");
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.  Press Ctrl+C to stop.\n");

    /* --- Main loop --------------------------------------------------- */
    while (g_running) {
        if (trigger_pulse(TRIGGER_PIN) < 0) {
            fprintf(stderr, "Error: trigger pulse failed\n");
        } else {
            float distance = measure_distance(TRIGGER_PIN, ECHO_PIN);
            log_distance(g_log_fp, distance);
        }

        /* Sleep SAMPLE_PERIOD_S, but wake early on signal */
        for (int i = 0; i < SAMPLE_PERIOD_S && g_running; i++) {
            sleep(1);
        }
    }

    /* --- Cleanup ----------------------------------------------------- */
    printf("\nShutting down...\n");
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    return EXIT_SUCCESS;
}

