/*
 * HC-SR04 Ultrasonic Distance Measurement — Raspberry Pi Zero W
 *
 * Wiring:
 *   TRIG -> GPIO17 (BCM)
 *   ECHO -> GPIO18 (BCM) via 1k/2k voltage divider (1000/2000 ohms)
 *     so the echo pulse is scaled to ~3.3 V on the Pi input.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18
#define TRIGGER_PULSE_US 10          /* 10 us trigger pulse            */
#define SAMPLE_PERIOD_US 1000000     /* 1 s between measurements       */
#define LOG_FILE         "distance_log.txt"

/*
 * HC-SR04 timing constants.
 *
 * Speed of sound 343 m/s  =>  34300 cm/s  =>  0.0343 cm/us
 * Round-trip time  =  2 * distance_cm / 34300
 * Pulse width       =  2 * distance_cm / 34300  (us)
 *
 * Min/max round-trip times for the HC-SR04:
 *   t_min = 2 * 1 cm / 34300  =  58 us
 *   t_max = 2 * 4 m / 34300  =  25 ms
 * Pulse-width window: 58 us .. 25 ms  =>  0.058 .. 25.0 ms
 */
#define MIN_PULSE_US  58.0
#define MAX_PULSE_US  25000.0

/* ------------------------------------------------------------------ */
/* Globals                                                            */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;
static FILE                 *g_log_fp  = NULL;

/*
 * ISR state.  pigpio delivers edge events on a dedicated thread, so
 * we guard the shared pulse-width value with a simple spinlock-style
 * atomic exchange; the ISR itself is single-threaded and pigpio
 * serialises callbacks for a given GPIO, so no heavy locking is
 * required.
 */
static volatile uint32_t g_pulse_us = 0;
static volatile bool     g_pulse_valid = false;

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* ISR callback — runs in pigpio's ISR thread                         */
/* ------------------------------------------------------------------ */

static void echo_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        g_pulse_us = tick;
        g_pulse_valid = false;
    } else if (level == 0) {
        /* Falling edge: echo pulse ends */
        uint32_t pulse = tick - g_pulse_us;  /* handles 32-bit wrap */

        if (pulse > 0) {
            g_pulse_us = pulse;
            g_pulse_valid = true;
        }
    }
    /* level == 2 (timeout) is ignored */
}

/* ------------------------------------------------------------------ */
/* Helpers                                                            */
/* ------------------------------------------------------------------ */

/*
 * Convert pulse width (us) to distance (cm).
 * Returns false if the pulse width is outside the HC-SR04 window.
 */
static bool pulse_to_distance(uint32_t pulse_us, float *distance_cm)
{
    if (pulse_us < MIN_PULSE_US || pulse_us > MAX_PULSE_US) {
        return false;
    }

    *distance_cm = (float)pulse_us * 0.0343f;  /* cm per us at 343 m/s */
    return true;
}

/*
 * Append a timestamped distance reading to the log file.
 * Returns 0 on success, -1 on failure.
 */
static int log_distance(float distance_cm)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       ts[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(g_log_fp, "%s, Distance: %.2f cm\n", ts, distance_cm) < 0) {
        perror("fprintf to log file failed");
        return -1;
    }
    if (fflush(g_log_fp) != 0) {
        perror("fflush on log file failed");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                            */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    /* Disable ISR */
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);

    /* Close log file */
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    /* Release pigpio resources */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* --- Initialise pigpio ----------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --------------------------------------- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n",
                TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n",
                ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /*
     * Start with the trigger line low.  The HC-SR04 needs a clean
     * 10 us trigger pulse; pigpio's gpioTrigger() generates a
     * well-defined pulse, so we leave it to the library.
     */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(5000);  /* 5 ms settle */

    /* --- Open log file --------------------------------------------- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Register ISR ---------------------------------------------- */
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0,
                         echo_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to register ISR on ECHO_PIN %d.\n",
                ECHO_PIN);
        fclose(g_log_fp);
        g_log_fp = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers ------------------------------------------- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 ranging started.  TRIG=GPIO%d  ECHO=GPIO%d\n",
           TRIGGER_PIN, ECHO_PIN);
    printf("Logging to '%s'.  Press Ctrl+C to stop.\n", LOG_FILE);

    /* --- Main loop ------------------------------------------------- */
    while (g_running) {
        /* Reset ISR state before triggering */
        g_pulse_us = 0;
        g_pulse_valid = false;

        /* Generate 10 us trigger pulse */
        if (gpioTrigger(TRIGGER_PIN, TRIGGER_PULSE_US, 1) != 0) {
            fprintf(stderr, "Warning: gpioTrigger failed on pin %d.\n",
                    TRIGGER_PIN);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /*
         * Wait for the echo pulse to arrive.  The HC-SR04 needs
         * ~8 us to start echoing after trigger, then ~70 us for
         * the shortest round trip (1 cm).  We poll with a 100 us
         * step, checking for a valid pulse each iteration.
         */
        uint32_t waited = 0;
        const uint32_t poll_step = 100;

        while (g_running && !g_pulse_valid && waited < SAMPLE_PERIOD_US) {
            gpioDelay(poll_step);
            waited += poll_step;
        }

        if (!g_running) {
            break;  /* signal received during wait */
        }

        if (!g_pulse_valid) {
            /* No echo received — sensor absent or out of range */
            fprintf(stderr, "Warning: no echo received (sensor absent or "
                            "out of range).\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /*
         * Measurement complete.  g_pulse_us holds the pulse width
         * (handles 32-bit tick wrap-around via the ISR callback).
         */
        float distance_cm;
        if (pulse_to_distance(g_pulse_us, &distance_cm)) {
            printf("Distance: %.2f cm\n", distance_cm);
            if (log_distance(distance_cm) != 0) {
                fprintf(stderr, "Warning: failed to log distance.\n");
            }
        }

        /*
         * Sleep for the remainder of the 1 s sample period.
         * gpioDelay is non-blocking with respect to ISR delivery,
         * so we still receive echo events during the sleep.
         */
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Clean shutdown -------------------------------------------- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
