#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define XSHUT_PIN 27
#define POLL_DELAY_US 100000

/* VL53L1X register addresses */
#define VL53L1X_SOFT_RESET 0x0000
#define VL53L1X_VHV_CONFIG 0x0001
#define VL53L1X_PHASECAL 0x0002
#define VL53L1X_RANGE_CONFIG 0x000A
#define VL53L1X_INTERMEASUREMENT 0x000B
#define VL53L1X_SYSTEM_START 0x000C
#define VL53L1X_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_RESULT_DISTANCE 0x0096

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        syslog(LOG_ERR, "I2C write failed at reg 0x%04X", reg);
        return -1;
    }
    return 0;
}

static int read_reg16(int handle, uint16_t reg, uint8_t *buf, int len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) != 2) {
        syslog(LOG_ERR, "I2C write (reg select) failed at 0x%04X", reg);
        return -1;
    }
    if (i2cReadDevice(handle, (char *)buf, len) != len) {
        syslog(LOG_ERR, "I2C read failed at reg 0x%04X", reg);
        return -1;
    }
    return 0;
}

static int vl53l1x_init(int handle) {
    if (write_reg16(handle, VL53L1X_SOFT_RESET, 0x00) != 0) return -1;
    gpioDelay(1000);
    if (write_reg16(handle, VL53L1X_SOFT_RESET, 0x01) != 0) return -1;
    gpioDelay(1000);
    if (write_reg16(handle, VL53L1X_VHV_CONFIG, 0x01) != 0) return -1;
    if (write_reg16(handle, VL53L1X_PHASECAL, 0x00) != 0) return -1;
    if (write_reg16(handle, VL53L1X_RANGE_CONFIG, 0x00) != 0) return -1;
    if (write_reg16(handle, VL53L1X_INTERMEASUREMENT, 0x00) != 0) return -1;
    if (write_reg16(handle, VL53L1X_SYSTEM_START, 0x01) != 0) return -1;
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance, uint8_t *status) {
    uint8_t buf[2];
    if (read_reg16(handle, VL53L1X_RESULT_RANGE_STATUS, buf, 1) != 0) return -1;
    *status = buf[0];
    if (read_reg16(handle, VL53L1X_RESULT_DISTANCE, buf, 2) != 0) return -1;
    *distance = (buf[0] << 8) | buf[1];
    return 0;
}

static void log_distance(uint16_t distance, uint8_t status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(status == 0 ? LOG_INFO : LOG_ERR, "%s Distance: %u mm, Status: %u",
           timestamp, distance, status);
}

int main(void) {
    openlog("vl53l1x_sensor", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    gpioSetMode(XSHUT_PIN, PI_OUTPUT);
    gpioWrite(XSHUT_PIN, 1);
    gpioDelay(1000);

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device at bus %d addr 0x%02X", I2C_BUS, VL53L1X_ADDR);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(i2c_handle) != 0) {
        syslog(LOG_ERR, "VL53L1X initialization failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        uint16_t distance = 0;
        uint8_t status = 0;
        if (vl53l1x_read_distance(i2c_handle, &distance, &status) == 0) {
            log_distance(distance, status);
        } else {
            syslog(LOG_ERR, "Failed to read distance from VL53L1X");
        }
        gpioDelay(POLL_DELAY_US);
    }

    syslog(LOG_INFO, "Shutting down gracefully...");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

