#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define SERVO_MIN_PULSE_US 500
#define SERVO_MAX_PULSE_US 2500
#define SERVO_MID_ANGLE_DEG 90
#define SERVO_RANGE_DEG 180
#define FILTER_SIZE 5
#define ECHO_TIMEOUT_US 30000
#define TRIGGER_INTERVAL_US 100000
#define LOOP_DELAY_US 10000

static volatile uint32_t pulse_start = 0;
static volatile uint32_t pulse_end = 0;
static volatile bool new_pulse = false;
static volatile bool running = true;

static double distance_history[FILTER_SIZE];
static int history_index = 0;
static int history_count = 0;

static FILE *log_file = NULL;

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)userdata;
    if (level == 1) {
        pulse_start = tick;
    } else if (level == 0) {
        pulse_end = tick;
        new_pulse = true;
    }
}

static double moving_average(double new_value) {
    double sum = 0.0;
    for (int i = 0; i < FILTER_SIZE; i++) {
        sum += distance_history[i];
    }
    distance_history[history_index] = new_value;
    history_index = (history_index + 1) % FILTER_SIZE;
    if (history_count < FILTER_SIZE) history_count++;
    return sum / (double)FILTER_SIZE;
}

static int set_servo_angle(int angle) {
    if (angle < 0 || angle > SERVO_RANGE_DEG) {
        fprintf(stderr, "Error: Invalid servo angle %d\n", angle);
        return -1;
    }
    int pulse_width = (int)(SERVO_MIN_PULSE_US +
        ((double)angle / SERVO_RANGE_DEG) * (SERVO_MAX_PULSE_US - SERVO_MIN_PULSE_US));
    int result = servo(SERVO_PIN, pulse_width);
    if (result != 0) {
        fprintf(stderr, "Error: servo(%d, %d) failed with code %d\n", SERVO_PIN, pulse_width, result);
        return -1;
    }
    return 0;
}

static void signal_handler(int sig) {
    (void)sig;
    running = false;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set TRIGGER_PIN %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set ECHO_PIN %d as input\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set SERVO_PIN %d as output\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < FILTER_SIZE; i++) {
        distance_history[i] = 0.0;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set alert function for ECHO_PIN %d\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: Failed to set pull-down on ECHO_PIN %d\n", ECHO_PIN);
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler\n");
    }

    log_file = fopen("distance_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open distance_log.csv for writing\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,Distance_cm,Servo_Angle_deg\n");
    fflush(log_file);

    if (set_servo_angle(SERVO_MID_ANGLE_DEG) != 0) {
        fprintf(stderr, "Error: Failed to initialize servo to %d degrees\n", SERVO_MID_ANGLE_DEG);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        pulse_start = 0;
        pulse_end = 0;
        new_pulse = false;

        if (gpioWrite(TRIGGER_PIN, 1) != 0) {
            fprintf(stderr, "Error: Failed to set TRIGGER_PIN high\n");
            break;
        }
        gpioDelay(10);
        if (gpioWrite(TRIGGER_PIN, 0) != 0) {
            fprintf(stderr, "Error: Failed to set TRIGGER_PIN low\n");
            break;
        }

        uint32_t start_tick = gpioTick();
        while (!new_pulse && running) {
            if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
                break;
            }
            gpioDelay(100);
        }

        double distance = -1.0;
        if (new_pulse) {
            uint32_t diff = pulse_end - pulse_start;
            distance = (double)diff * SPEED_OF_SOUND_CM_PER_US / 2.0;
        }

        if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
            distance = -1.0;
        }

        double filtered_distance = moving_average(distance);

        int servo_angle = SERVO_MID_ANGLE_DEG;
        if (filtered_distance >= 0.0) {
            servo_angle = (int)(SERVO_MID_ANGLE_DEG +
                ((filtered_distance - MIN_DISTANCE_CM) /
                (MAX_DISTANCE_CM - MIN_DISTANCE_CM)) * SERVO_RANGE_DEG);
            if (servo_angle < 0) servo_angle = 0;
            if (servo_angle > SERVO_RANGE_DEG) servo_angle = SERVO_RANGE_DEG;
        }

        if (set_servo_angle(servo_angle) != 0) {
            fprintf(stderr, "Warning: Failed to update servo angle\n");
        }

        time_t rawtime;
        time(&rawtime);
        struct tm *timeinfo = localtime(&rawtime);
        char timestamp[80];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s,%.2f,%d\n", timestamp, filtered_distance, servo_angle);
        fflush(log_file);

        printf("%s, Distance: %.2f cm, Servo Angle: %d deg\n", timestamp, filtered_distance, servo_angle);

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

