#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_LED 17
#define DISTANCE_THRESHOLD 200
#define BUFFER_SIZE 10
#define POLL_DELAY_US 50000

/* VL53L1X register addresses */
#define REG_SOFT_RESET 0x0000
#define REG_I2C_SLAVE_DEVICE_ADDRESS 0x0001
#define REG_SYSTEM_MODE_START 0x0007
#define REG_RANGE_CONFIG_A 0x005E
#define REG_RANGE_CONFIG_B 0x0061
#define REG_INTERMEASUREMENT_PERIOD 0x006B
#define REG_SYSTEM_INTERRUPT_CONFIG_GPIO 0x0046
#define REG_GPIO_HV_MUX_ACTIVE_HIGH 0x0047
#define REG_SYSTEM_INTERRUPT_CLEAR 0x0086
#define REG_RESULT_INTERRUPT_STATUS 0x0089
#define REG_RESULT_RANGE_STATUS 0x0089
#define REG_RESULT_DISTANCE 0x0096

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "Error writing reg 0x%04X\n", reg);
        return -1;
    }
    return 0;
}

static int read_reg16(int handle, uint16_t reg, uint8_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error setting read reg 0x%04X\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, (char *)value, 1) != 1) {
        fprintf(stderr, "Error reading reg 0x%04X\n", reg);
        return -1;
    }
    return 0;
}

static int read_reg16_16bit(int handle, uint16_t reg, uint16_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error setting read reg 0x%04X\n", reg);
        return -1;
    }
    char read_buf[2];
    if (i2cReadDevice(handle, read_buf, 2) != 2) {
        fprintf(stderr, "Error reading 16-bit reg 0x%04X\n", reg);
        return -1;
    }
    *value = ((uint8_t)read_buf[0] << 8) | (uint8_t)read_buf[1];
    return 0;
}

static int init_vl53l1x(int handle) {
    /* Soft reset */
    if (write_reg16(handle, REG_SOFT_RESET, 0x00) != 0) return -1;
    gpioDelay(1000);
    if (write_reg16(handle, REG_SOFT_RESET, 0x01) != 0) return -1;
    gpioDelay(1000);

    /* Set I2C address (7-bit) */
    if (write_reg16(handle, REG_I2C_SLAVE_DEVICE_ADDRESS, VL53L1X_ADDR) != 0) return -1;

    /* Set timing budget to 20 ms (0x0014) */
    if (write_reg16(handle, REG_RANGE_CONFIG_A, 0x00) != 0) return -1;
    if (write_reg16(handle, REG_RANGE_CONFIG_B, 0x14) != 0) return -1;

    /* Set inter-measurement period to 50 ms (0x0032) */
    if (write_reg16(handle, REG_INTERMEASUREMENT_PERIOD, 0x00) != 0) return -1;
    if (write_reg16(handle, REG_INTERMEASUREMENT_PERIOD + 1, 0x32) != 0) return -1;

    /* Configure signal rate and ambient rate */
    if (write_reg16(handle, 0x0044, 0x00) != 0) return -1;
    if (write_reg16(handle, 0x0045, 0x00) != 0) return -1;
    if (write_reg16(handle, 0x0046, 0x01) != 0) return -1;
    if (write_reg16(handle, 0x0047, 0x01) != 0) return -1;

    /* Start ranging */
    if (write_reg16(handle, REG_SYSTEM_MODE_START, 0x01) != 0) return -1;

    return 0;
}

static int read_distance(int handle, uint16_t *distance_mm) {
    uint8_t status = 0;
    if (read_reg16(handle, REG_RESULT_INTERRUPT_STATUS, &status) != 0) return -1;
    if ((status & 0x07) == 0) return 1; /* No new data yet */

    if (read_reg16_16bit(handle, REG_RESULT_DISTANCE, distance_mm) != 0) return -1;

    if (write_reg16(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) return -1;
    return 0;
}

static void control_led(int gpio, int state) {
    gpioWrite(gpio, state);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_vl53l1x(i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    int buffer[BUFFER_SIZE];
    int head = 0, count = 0;

    while (running) {
        uint16_t distance = 0;
        int rc = read_distance(i2c_handle, &distance);

        if (rc == 0) {
            buffer[head] = (int)distance;
            head = (head + 1) % BUFFER_SIZE;
            if (count < BUFFER_SIZE) count++;

            if (distance < DISTANCE_THRESHOLD) {
                control_led(GPIO_LED, 1);
            } else {
                control_led(GPIO_LED, 0);
            }

            printf("Distance: %u mm\n", distance);
        } else if (rc < 0) {
            fprintf(stderr, "Error reading distance, continuing...\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    control_led(GPIO_LED, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

