#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DEFAULT_I2C_ADDRESS 0x60
#define DEFAULT_THRESHOLD 1000
#define GPIO_PIN 27
#define LOG_FILE "proximity.log"
#define I2C_BUS 1

/* Si1102 register addresses (from datasheet) */
#define SI1102_REG_IRQ_ENABLE 0x01
#define SI1102_REG_HW_KEY     0x07
#define SI1102_REG_PROX_DATA  0x26
#define SI1102_REG_COMMAND    0x30

/* Si1102 command codes (from datasheet) */
#define SI1102_CMD_RESET      0x01
#define SI1102_CMD_PROX_START 0x0A

/* Si1102 HW_KEY value (from datasheet) */
#define SI1102_HW_KEY_VALUE  0x17

/* Global state */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;
static volatile sig_atomic_t proximity_event = 0;
static int threshold = DEFAULT_THRESHOLD;
static int i2c_address = DEFAULT_I2C_ADDRESS;

/* Function prototypes */
static int initialize_sensor(void);
static int read_proximity(void);
static void log_data(int proximity_value, int alert);
static void interrupt_handler(int gpio, int level, uint32_t tick, void *userdata);
static void signal_handler(int signal);
static void cleanup(void);

/*
 * Initializes the Si1102 sensor.
 * Returns 0 on success, -1 on failure.
 */
static int initialize_sensor(void) {
    /* Reset the sensor */
    if (i2cWriteByteData(i2c_handle, SI1102_REG_COMMAND, SI1102_CMD_RESET) < 0) {
        fprintf(stderr, "Error: Failed to reset Si1102.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms delay after reset */

    /* Write HW_KEY to enable proper operation */
    if (i2cWriteByteData(i2c_handle, SI1102_REG_HW_KEY, SI1102_HW_KEY_VALUE) < 0) {
        fprintf(stderr, "Error: Failed to write HW_KEY to Si1102.\n");
        return -1;
    }

    /* Start proximity measurement */
    if (i2cWriteByteData(i2c_handle, SI1102_REG_COMMAND, SI1102_CMD_PROX_START) < 0) {
        fprintf(stderr, "Error: Failed to start proximity measurement.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms delay for measurement to stabilize */

    return 0;
}

/*
 * Reads the proximity value from the Si1102 sensor.
 * Returns the proximity value (0-65535) on success, -1 on failure.
 */
static int read_proximity(void) {
    int proximity = i2cReadWordData(i2c_handle, SI1102_REG_PROX_DATA);
    if (proximity < 0) {
        fprintf(stderr, "Error: Failed to read proximity data.\n");
        return -1;
    }
    return proximity;
}

/*
 * Logs the proximity data to a file.
 */
static void log_data(int proximity_value, int alert) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: Failed to get local time.\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%d,%s\n", timestamp, proximity_value, alert ? "ALERT" : "SAFE") < 0) {
        fprintf(stderr, "Error: Failed to write to log file.\n");
    } else {
        fflush(log_file);
    }
}

/*
 * Interrupt handler for the Si1102 sensor.
 * This handler only sets a flag to defer the actual work to the main loop
 * (using a flag + loop polling is acceptable for a non-blocking interrupt).
 */
static void interrupt_handler(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)level;
    (void)tick;
    (void)userdata;
    proximity_event = 1;
}

/*
 * Signal handler for Ctrl+C.
 */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/*
 * Cleanup resources.
 */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    /* Parse command-line arguments */
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 0);
                if (i2c_address <= 0 || i2c_address > 0x7F) {
                    fprintf(stderr, "Error: Invalid I2C address.\n");
                    return 1;
                }
                break;
            case 't':
                threshold = atoi(optarg);
                if (threshold <= 0) {
                    fprintf(stderr, "Error: Invalid threshold.\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    /* Open I2C device */
    i2c_handle = i2cOpen(I2C_BUS, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X.\n", i2c_address);
        gpioTerminate();
        return 1;
    }

    /* Initialize the sensor */
    if (initialize_sensor() < 0) {
        fprintf(stderr, "Error: Sensor initialization failed.\n");
        cleanup();
        return 1;
    }

    /* Set GPIO pin as input */
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO pin %d as input.\n", GPIO_PIN);
        cleanup();
        return 1;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        cleanup();
        return 1;
    }

    /* Register interrupt handler */
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register interrupt handler on GPIO %d.\n", GPIO_PIN);
        cleanup();
        return 1;
    }

    /* Register signal handler */
    signal(SIGINT, signal_handler);

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");
    printf("I2C Address: 0x%02X, Threshold: %d\n", i2c_address, threshold);

    /* Main loop */
    while (program_running) {
        if (proximity_event) {
            proximity_event = 0;
            int proximity_value = read_proximity();
            if (proximity_value >= 0) {
                int alert = (proximity_value > threshold) ? 1 : 0;
                log_data(proximity_value, alert);
            }
        }
        gpioDelay(10000); /* 10 ms delay to prevent busy-waiting */
    }

    /* Cleanup */
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

