static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/*
 * Cleanup resources.
 */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    /* Parse command-line arguments */
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 0);
                if (i2c_address <= 0 || i2c_address > 0x7F) {
                    fprintf(stderr, "Error: Invalid I2C address.\n");
                    return 1;
                }
                break;
            case 't':
                threshold = atoi(optarg);
                if (threshold <= 0) {
                    fprintf(stderr, "Error: Invalid threshold.\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    /* Open I2C device */
    i2c_handle = i2cOpen(I2C_BUS, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X.\n", i2c_address);
        gpioTerminate();
        return 1;
    }

    /* Initialize the sensor */
    if (initialize_sensor() < 0) {
        fprintf(stderr, "Error: Sensor initialization failed.\n");
        cleanup();
        return 1;
    }

    /* Set GPIO pin as input */
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO pin %d as input.\n", GPIO_PIN);
        cleanup();
        return 1;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        cleanup();
        return 1;
    }

    /* Register interrupt handler */
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register interrupt handler on GPIO %d.\n", GPIO_PIN);
        cleanup();
        return 1;
    }

    /* Register signal handler */
    signal(SIGINT, signal_handler);

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");
    printf("I2C Address: 0x%02X, Threshold: %d\n", i2c_address, threshold);

    /* Main loop */
    while (program_running) {
        if (proximity_event) {
            proximity_event = 0;
            int proximity_value = read_proximity();
            if (proximity_value >= 0) {
                int alert = (proximity_value > threshold) ? 1 : 0;
                log_data(proximity_value, alert);
            }
        }
        gpioDelay(10000); /* 10 ms delay to prevent busy-waiting */
    }

    /* Cleanup */
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

