/*
 * Raspberry Pi Zero W - HC-SR04 Ultrasonic Theremin
 *
 * Reads distance from an HC-SR04 ultrasonic sensor and drives an 8-ohm
 * speaker via hardware PWM on GPIO18 (PWM0) to produce a theremin-like
 * pitch that varies with distance.
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO23 (BCM)
 *   HC-SR04 ECHO -> GPIO24 (BCM)
 *   Speaker +    -> GPIO18 (BCM) via a logic-level MOSFET or 60W PWM driver
 *   Speaker -    -> GND
 *
 * Build: gcc -O2 -Wall -o theremin theremin.c -lpigpio -lrt
 * Run:   sudo ./theremin
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define PWM_PIN          18

#define MIN_DISTANCE_CM  2.0f
#define MAX_DISTANCE_CM  200.0f
#define MIN_FREQUENCY_HZ 200.0f
#define MAX_FREQUENCY_HZ 2000.0f

#define ECHO_TIMEOUT_US  200000   /* 200 ms timeout for echo pulse */
#define TRIGGER_PULSE_US 10       /* 10 us trigger pulse width */
#define LOOP_DELAY_US    50000    /* 50 ms between readings */

#define PWM_DUTY_50      500000   /* 50 % of 1,000,000 (pigpio range) */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* HC-SR04 helpers                                                     */
/* ------------------------------------------------------------------ */

/*
 * Measure distance in centimetres.
 * Returns >= 0 on success, -1.0 on timeout / error.
 */
static float measure_distance(void)
{
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t timeout_tick;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1.0f;
    }
    gpioDelay(5);

    /* 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1.0f;
    }

    /* Wait for echo rising edge (timeout) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: Echo start timeout\n");
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: Echo end timeout\n");
            return -1.0f;
        }
    }
    end_tick = gpioTick();

    /* distance = (pulse_width * speed_of_sound) / 2 */
    float pulse_us = (float)(end_tick - start_tick);
    float distance = (pulse_us * 34300.0f) / 2000000.0f;

    /* Sanity-check against sensor's rated range */
    if (distance < 2.0f || distance > 400.0f) {
        fprintf(stderr, "Warning: Distance %.2f cm out of sensor range\n", distance);
        return -1.0f;
    }

    return distance;
}

/* ------------------------------------------------------------------ */
/* Frequency mapping                                                   */
/* ------------------------------------------------------------------ */
static float map_distance_to_frequency(float distance)
{
    if (distance <= MIN_DISTANCE_CM)
        return MIN_FREQUENCY_HZ;
    if (distance >= MAX_DISTANCE_CM)
        return MAX_FREQUENCY_HZ;

    /* Logarithmic mapping: closer -> higher frequency */
    float ratio = (distance - MIN_DISTANCE_CM) / (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    float freq = MIN_FREQUENCY_HZ * powf(MAX_FREQUENCY_HZ / MIN_FREQUENCY_HZ, ratio);
    return freq;
}

/* ------------------------------------------------------------------ */
/* PWM control                                                         */
/* ------------------------------------------------------------------ */
static int set_pwm_frequency(float frequency)
{
    if (frequency <= 0.0f) {
        fprintf(stderr, "Error: Invalid frequency %.2f Hz\n", frequency);
        return -1;
    }

    /* pigpio hardware PWM on GPIO18 uses a 1 MHz base; frequency in Hz */
    if (gpioHardwarePWM(PWM_PIN, (uint32_t)frequency, PWM_DUTY_50) < 0) {
        fprintf(stderr, "Error: gpioHardwarePWM(%u, %.2f) failed\n",
                PWM_PIN, frequency);
        return -1;
    }
    return 0;
}

static void stop_pwm(void)
{
    /* 0 Hz turns off the PWM signal */
    if (gpioHardwarePWM(PWM_PIN, 0, 0) < 0)
        fprintf(stderr, "Warning: gpioHardwarePWM(0) failed during stop\n");
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int rc;
    float distance, frequency;

    /* Initialise pigpio */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d)\n", rc);
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER) failed\n");
        goto fail_init;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO) failed\n");
        goto fail_init;
    }
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(PWM) failed\n");
        goto fail_init;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) init failed\n");
        goto fail_init;
    }

    /* Install signal handlers for clean shutdown */
    install_signal_handlers();

    printf("HC-SR04 Theremin started. Press Ctrl+C to exit.\n");
    printf("Distance: %.1f cm -> Frequency: %.1f Hz\n",
           MIN_DISTANCE_CM, MIN_FREQUENCY_HZ);

    /* Main loop */
    while (g_running) {
        distance = measure_distance();

        if (distance < 0.0f) {
            /* Error already reported; preserve previous frequency */
            continue;
        }

        frequency = map_distance_to_frequency(distance);

        if (set_pwm_frequency(frequency) != 0) {
            /* Error already reported; continue loop */
            continue;
        }

        printf("Distance: %6.2f cm | Frequency: %6.2f Hz\n", distance, frequency);

        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    stop_pwm();
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;

fail_init:
    gpioTerminate();
    return EXIT_FAILURE;
}

