#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define BUZZER_PIN  18

#define MIN_DISTANCE_CM 5.0f
#define MAX_DISTANCE_CM 50.0f
#define MIN_FREQUENCY_HZ 200
#define MAX_FREQUENCY_HZ 2000

#define ECHO_TIMEOUT_US 100000
#define LOOP_DELAY_US   10000
#define TRIGGER_PULSE_US 10

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set BUZZER_PIN %d as output.\n", BUZZER_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize TRIGGER_PIN low.\n");
        gpioTerminate();
        return -1;
    }

    if (gpioPWM(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize PWM on BUZZER_PIN.\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void) {
    gpioPWM(BUZZER_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
}

static float measure_distance(void) {
    uint32_t start_tick, end_tick, timeout_tick;

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(2);

    if (gpioWrite(TRIGGER_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN high.\n");
        return -1.0f;
    }

    gpioDelay(TRIGGER_PULSE_US);

    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN low.\n");
        return -1.0f;
    }

    start_tick = gpioTick();
    timeout_tick = start_tick + ECHO_TIMEOUT_US;

    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo start timeout (sensor absent or wiring fault).\n");
            return -1.0f;
        }
    }

    start_tick = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo end timeout (sensor stuck or out of range).\n");
            return -1.0f;
        }
    }

    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;

    if (diff == 0) {
        fprintf(stderr, "Error: zero pulse width measured.\n");
        return -1.0f;
    }

    float distance = (diff / 1000000.0f) * 34300.0f / 2.0f;

    if (distance < 0.0f || distance > 400.0f) {
        fprintf(stderr, "Warning: distance out of valid range (%.2f cm).\n", distance);
        return -1.0f;
    }

    return distance;
}

static int map_distance_to_frequency(float distance) {
    if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;

    float ratio = (distance - MIN_DISTANCE_CM) / (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    int freq = (int)(MIN_FREQUENCY_HZ + ratio * (MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ));

    if (freq < MIN_FREQUENCY_HZ) freq = MIN_FREQUENCY_HZ;
    if (freq > MAX_FREQUENCY_HZ) freq = MAX_FREQUENCY_HZ;

    return freq;
}

static void generate_tone(int frequency) {
    if (frequency > 0) {
        if (gpioSetPWMfrequency(BUZZER_PIN, frequency) < 0) {
            fprintf(stderr, "Error: failed to set PWM frequency to %d Hz.\n", frequency);
        }
    } else {
        gpioPWM(BUZZER_PIN, 0);
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Error: distance measurement failed.\n");
            generate_tone(0);
        } else {
            int frequency = map_distance_to_frequency(distance);
            generate_tone(frequency);
            printf("Distance: %.2f cm, Frequency: %d Hz\n", distance, frequency);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    cleanup_gpio();
    printf("\nTheremin stopped.\n");

    return EXIT_SUCCESS;
}

