#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18

#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define MIN_DISTANCE_CM          2.0
#define MAX_DISTANCE_CM          400.0
#define TOO_CLOSE_THRESHOLD_CM   10.0
#define ECHO_TIMEOUT_US          50000   /* 50 ms */
#define LOOP_DELAY_US            500000 /* 500 ms */
#define TRIGGER_PULSE_US         10

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/*
 * Measure the echo pulse duration in microseconds.
 * Returns the duration on success, or -1 on timeout / error.
 */
static long measure_echo_pulse(void)
{
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t timeout_start = gpioTick();

    /* Wait for echo rising edge */
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - timeout_start) > ECHO_TIMEOUT_US) {
            return -1;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
            return -1;
        }
    }
    end_tick = gpioTick();

    return (long)(end_tick - start_tick);
}

/*
 * Trigger the HC-SR04: 10 us high pulse on the trigger pin.
 */
static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

/*
 * Convert echo pulse duration (us) to distance (cm).
 * Returns -1.0 if the pulse duration is invalid.
 */
static float calculate_distance(long pulse_duration_us)
{
    if (pulse_duration_us < 0) {
        return -1.0;
    }
    return (float)pulse_duration_us * SPEED_OF_SOUND_CM_PER_US / 2.0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure trigger pin as output, echo pin as input */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set echo pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(5000); /* 5 ms settle */

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler.\n");
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("Trigger: GPIO%d, Echo: GPIO%d\n", TRIGGER_PIN, ECHO_PIN);
    printf("Press Ctrl+C to exit.\n");

