        trigger_sensor();
        long pulse_duration = measure_echo_pulse();

        if (pulse_duration < 0) {
            fprintf(stderr, "Error: echo measurement timeout or read error.\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        float distance = calculate_distance(pulse_duration);

        if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
            printf("Invalid reading: %.2f cm\n", distance);
            if (distance < TOO_CLOSE_THRESHOLD_CM) {
                printf("Too close!\n");
            }
        } else {
            printf("Distance: %.2f cm", distance);
            if (distance < TOO_CLOSE_THRESHOLD_CM) {
                printf("  Too close!");
            }
            printf("\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

