#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define CS_PIN      8        /* BCM 8 (CE0) */
#define LOG_FILE    "distance_log.csv"
#define READ_DELAY_US 100000 /* 100 ms */

/* ICU-20201 SPI command opcodes (16-bit, big-endian on wire) */
#define ICU_CMD_READ_REG  0x8001
#define ICU_CMD_WRITE_REG 0xA001
#define ICU_CMD_READ_DIST 0x0001

/* Register addresses (16-bit, big-endian on wire) */
#define REG_CHIP_ID      0x0000
#define REG_DISTANCE     0x0001
#define REG_CONFIG       0x0002

#define EXPECTED_CHIP_ID 0x0001

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — graceful shutdown                                  */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Low-level SPI helpers                                               */
/* ------------------------------------------------------------------ */
static int spi_xfer(int handle, const char *tx, char *rx, int len)
{
    int ret = spiXfer(handle, (char *)tx, rx, len);
    if (ret != len) {
        fprintf(stderr, "SPI transfer failed (ret=%d, expected=%d)\n",
                ret, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor driver functions (big-endian 16-bit opcodes, big-endian     */
/* register addresses)                                                */
/* ------------------------------------------------------------------ */
static int icu_write_reg(int handle, uint16_t reg, uint16_t value)
{
    char tx[4] = {
        (char)(reg >> 8),
        (char)(reg & 0xFF),
        (char)(value >> 8),
        (char)(value & 0xFF)
    };
    char rx[4] = {0};
    return spi_xfer(handle, tx, rx, sizeof(tx));
}

static int icu_read_reg(int handle, uint16_t reg, uint16_t *value)
{
    char tx[4] = {
        (char)(reg >> 8),
        (char)(reg & 0xFF),
        0x00, 0x00
    };
    char rx[4] = {0};
    if (spi_xfer(handle, tx, rx, sizeof(tx)) != 0)
        return -1;
    *value = ((uint16_t)(uint8_t)rx[2] << 8) | (uint8_t)rx[3];
    return 0;
}

static int icu_read_distance(int handle, uint16_t *distance_mm)
{
    char tx[2] = {0x00, 0x00};
    char rx[2] = {0};
    if (spi_xfer(handle, tx, rx, sizeof(tx)) != 0)
        return -1;
    *distance_mm = ((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, uint16_t distance_mm)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, distance_mm);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open SPI --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); /* mode 0 */
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE ")");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- verify chip ID --- */
    uint16_t chip_id = 0;
    if (icu_read_reg(g_spi_handle, REG_CHIP_ID, &chip_id) != 0) {
        fprintf(stderr, "Failed to read chip ID (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (chip_id != EXPECTED_CHIP_ID) {
        fprintf(stderr, "Unexpected chip ID: 0x%04X (expected 0x%04X)\n",
                chip_id, EXPECTED_CHIP_ID);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- configure sensor --- */
    /* Example configuration: enable continuous ranging, set output rate */
    if (icu_write_reg(g_spi_handle, REG_CONFIG, 0x0002) != 0) {
        fprintf(stderr, "Failed to write config register\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- main loop --- */
    while (g_running) {
        uint16_t distance = 0;
        if (icu_read_distance(g_spi_handle, &distance) != 0) {
            fprintf(stderr, "Failed to read distance\n");
        } else {
            log_data(g_log_file, distance);
        }
        gpioDelay(READ_DELAY_US);
    }

    /* --- graceful exit --- */
    cleanup();
    return EXIT_SUCCESS;
}

