        perror("fopen(" LOG_FILE ")");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- verify chip ID --- */
    uint16_t chip_id = 0;
    if (icu_read_reg(g_spi_handle, REG_CHIP_ID, &chip_id) != 0) {
        fprintf(stderr, "Failed to read chip ID (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (chip_id != EXPECTED_CHIP_ID) {
        fprintf(stderr, "Unexpected chip ID: 0x%04X (expected 0x%04X)\n",
                chip_id, EXPECTED_CHIP_ID);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- configure sensor --- */
    /* Example configuration: enable continuous ranging, set output rate */
    if (icu_write_reg(g_spi_handle, REG_CONFIG, 0x0002) != 0) {
        fprintf(stderr, "Failed to write config register\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- main loop --- */
    while (g_running) {
        uint16_t distance = 0;
        if (icu_read_distance(g_spi_handle, &distance) != 0) {
            fprintf(stderr, "Failed to read distance\n");
        } else {
            log_data(g_log_file, distance);
        }
        gpioDelay(READ_DELAY_US);
    }

    /* --- graceful exit --- */
    cleanup();
    return EXIT_SUCCESS;
}

