#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI1175_ADDR        0x60
#define SI1175_REG_ALS_VIS 0x22
#define SI1175_REG_COMMAND 0x30
#define SI1175_CMD_RESET   0x01
#define SI1175_CMD_ALS_FORCE 0x06
#define I2C_BUS            "/dev/i2c-1"
#define LOG_FILE           "proximity_log.csv"
#define SAMPLE_INTERVAL_S  5

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int si1175_init(int fd) {
    if (i2c_write_reg8(fd, SI1175_REG_COMMAND, SI1175_CMD_RESET) < 0) return -1;
    usleep(10000);
    return 0;
}

static int si1175_read_als(int fd, uint16_t *als_vis) {
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, SI1175_REG_ALS_VIS, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, SI1175_REG_ALS_VIS + 1, &hi) < 0) return -1;
    *als_vis = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int log_data(FILE *fp, uint16_t als_vis) {
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%u\n", ts, als_vis) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    int fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        goto cleanup;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n", SI1175_ADDR, strerror(errno));
        goto cleanup;
    }

    if (si1175_init(fd) < 0) {
        fprintf(stderr, "Si1175 initialization failed (sensor may be absent or bus error)\n");
        goto cleanup;
    }

    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    if (ftell(fp) == 0) {
        fprintf(fp, "timestamp,als_visible\n");
        fflush(fp);
    }

    printf("Si1175 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t als_vis;
        if (si1175_read_als(fd, &als_vis) < 0) {
            fprintf(stderr, "ALS read failed; continuing after backoff.\n");
            sleep(1);
            continue;
        }
        if (log_data(fp, als_vis) < 0) {
            fprintf(stderr, "Logging failed; continuing after backoff.\n");
            sleep(1);
            continue;
        }
        printf("ALS (visible): %u\n", als_vis);
        sleep(SAMPLE_INTERVAL_S);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fp) fclose(fp);
    if (fd >= 0) close(fd);
    return rc;
}

