#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* Si1120 I2C address (7-bit) */
#define SI1120_ADDR 0x60

/* Si1120 register addresses (from datasheet) */
#define SI1120_REG_PART_ID      0x00
#define SI1120_REG_REV_ID       0x01
#define SI1120_REG_SEQ_ID       0x02
#define SI1120_REG_INT_CFG      0x03
#define SI1120_REG_IRQ_ENABLE   0x04
#define SI1120_REG_IRQ_MODE1    0x05
#define SI1120_REG_IRQ_MODE2    0x06
#define SI1120_REG_HW_KEY       0x07
#define SI1120_REG_MEAS_RATE0   0x08
#define SI1120_REG_MEAS_RATE1   0x09
#define SI1120_REG_ALS_RATE     0x0A
#define SI1120_REG_ALS_IR_ADCMUX 0x10
#define SI1120_REG_PS_LED21     0x11
#define SI1120_REG_PS_LED3      0x12
#define SI1120_REG_PS1_ADCMUX   0x13
#define SI1120_REG_PS2_ADCMUX   0x14
#define SI1120_REG_PS3_ADCMUX   0x15
#define SI1120_REG_PS_ADC_GAIN  0x16
#define SI1120_REG_PS_ADC_MISC  0x17
#define SI1120_REG_PS1_DATA     0x18
#define SI1120_REG_PS2_DATA     0x19
#define SI1120_REG_PS3_DATA     0x1A
#define SI1120_REG_ALS_VIS_DATA0 0x20
#define SI1120_REG_ALS_VIS_DATA1 0x21
#define SI1120_REG_ALS_IR_DATA0  0x22
#define SI1120_REG_ALS_IR_DATA1  0x23
#define SI1120_REG_COMMAND      0x30

/* Si1120 command codes (from datasheet) */
#define SI1120_CMD_RESET        0x01
#define SI1120_CMD_PS_FORCE     0x05
#define SI1120_CMD_ALS_FORCE    0x06
#define SI1120_CMD_PSALS_FORCE  0x07

/* Expected part ID for Si1120 */
#define SI1120_PART_ID          0x20

/* Retry parameters */
#define I2C_RETRIES             3
#define I2C_RETRY_DELAY_US      10000  /* 10 ms */

/* Sampling interval */
#define SAMPLE_INTERVAL_US      500000 /* 500 ms */

/* Global resources for signal handler cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a byte to a register with retry */
static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result;
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        result = i2cWriteByteData(handle, reg, value);
        if (result == 0) {
            return 0;
        }
        fprintf(stderr, "I2C write error (reg 0x%02X, val 0x%02X, attempt %d/%d): %d\n",
                reg, value, attempt + 1, I2C_RETRIES, result);
        if (attempt < I2C_RETRIES - 1) {
            gpioDelay(I2C_RETRY_DELAY_US);
        }
    }
    return -1;
}

/* Read a byte from a register with retry */
static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result;
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        result = i2cReadByteData(handle, reg);
        if (result >= 0) {
            *value = (uint8_t)result;
            return 0;
        }
        fprintf(stderr, "I2C read error (reg 0x%02X, attempt %d/%d): %d\n",
                reg, attempt + 1, I2C_RETRIES, result);
        if (attempt < I2C_RETRIES - 1) {
            gpioDelay(I2C_RETRY_DELAY_US);
        }
    }
    return -1;
}

/* Read a 16-bit little-endian value from two consecutive registers */
static int read_register16(int handle, uint8_t reg_low, uint16_t *value) {
    uint8_t low, high;
    if (read_register(handle, reg_low, &low) != 0) {
        return -1;
    }
    if (read_register(handle, reg_low + 1, &high) != 0) {
        return -1;
    }
    *value = (uint16_t)((high << 8) | low);
    return 0;
}

/* Initialize the Si1120 sensor */
static int initialize_sensor(int handle) {
    uint8_t part_id;

    /* Reset the sensor */
    if (write_register(handle, SI1120_REG_COMMAND, SI1120_CMD_RESET) != 0) {
        fprintf(stderr, "Failed to reset Si1120\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle after reset */

    /* Verify part ID */
    if (read_register(handle, SI1120_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Failed to read Si1120 part ID\n");
        return -1;
    }
    if (part_id != SI1120_PART_ID) {
        fprintf(stderr, "Unexpected Si1120 part ID: 0x%02X (expected 0x%02X)\n",
                part_id, SI1120_PART_ID);
        return -1;
    }

    /* Configure measurement rate (0 = continuous) */
    if (write_register(handle, SI1120_REG_MEAS_RATE0, 0x00) != 0) {
        fprintf(stderr, "Failed to set Si1120 measurement rate\n");
        return -1;
    }
    if (write_register(handle, SI1120_REG_MEAS_RATE1, 0x00) != 0) {
        fprintf(stderr, "Failed to set Si1120 measurement rate high byte\n");
        return -1;
    }

    /* Configure ALS IR ADC mux */
    if (write_register(handle, SI1120_REG_ALS_IR_ADCMUX, 0x00) != 0) {
        fprintf(stderr, "Failed to set Si1120 ALS IR ADC mux\n");
        return -1;
    }

    /* Configure PS LED 21 (visible) */
    if (write_register(handle, SI1120_REG_PS_LED21, 0x0F) != 0) {
        fprintf(stderr, "Failed to set Si1120 PS LED 21\n");
        return -1;
    }

    /* Configure PS ADC gain */
    if (write_register(handle, SI1120_REG_PS_ADC_GAIN, 0x00) != 0) {
        fprintf(stderr, "Failed to set Si1120 PS ADC gain\n");
        return -1;
    }

    /* Configure PS ADC misc */
    if (write_register(handle, SI1120_REG_PS_ADC_MISC, 0x00) != 0) {
        fprintf(stderr, "Failed to set Si1120 PS ADC misc\n");
        return -1;
    }

    return 0;
}

/* Read ambient light and proximity data */
static int read_sensor_data(int handle, uint16_t *ambient_light, uint16_t *proximity) {
    /* Trigger a forced measurement of both ALS and PS */
    if (write_register(handle, SI1120_REG_COMMAND, SI1120_CMD_PSALS_FORCE) != 0) {
        fprintf(stderr, "Failed to trigger Si1120 measurement\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms for conversion */

    /* Read ALS visible (registers 0x20-0x21) */
    if (read_register16(handle, SI1120_REG_ALS_VIS_DATA0, ambient_light) != 0) {
        fprintf(stderr, "Failed to read ALS visible data\n");
        return -1;
    }

    /* Read proximity (registers 0x18-0x1A) */
    if (read_register16(handle, SI1120_REG_PS1_DATA, proximity) != 0) {
        fprintf(stderr, "Failed to read proximity data\n");
        return -1;
    }

    return 0;
}

/* Log sensor data with timestamp */
static void log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(fp, "%s, Ambient Light: %u, Proximity: %u\n", timestamp, ambient_light, proximity);
    fflush(fp);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the Si1120 address */
    i2c_handle = i2cOpen(1, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at address 0x%02X: %d\n",
                SI1120_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (initialize_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open the log file */
    log_file = fopen("si1120_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handler for graceful shutdown */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t ambient_light, proximity;

    /* Main sampling loop */
    while (!terminate) {
        if (read_sensor_data(i2c_handle, &ambient_light, &proximity) == 0) {
            log_data(log_file, ambient_light, proximity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

