#define I2C_DEVICE    "/dev/i2c-1"
#define LOG_FILE      "biometric_log.txt"
#define SAMPLE_MS    100

/* Si1182-A-GM register addresses (from datasheet) */
#define REG_PART_ID        0x00
#define REG_MEAS_RATE      0x08
#define REG_ALS_VIS_DATA0  0x22
#define REG_PS1_DATA0      0x24

#define EXPECTED_PART_ID   0x82
#define MEAS_RATE_100MS    0x08  /* 100 ms measurement rate */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int init_sensor(int fd)
{
    uint8_t part_id = 0;

    if (i2c_read_reg8(fd, REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Cannot read Part ID — sensor may be absent or bus error.\n");
        return -1;
    }

    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected Part ID 0x%02X (expected 0x%02X).\n",
                part_id, EXPECTED_PART_ID);
        return -1;
    }

    printf("Si1182-A-GM detected (Part ID 0x%02X).\n", part_id);

    if (i2c_write_reg8(fd, REG_MEAS_RATE, MEAS_RATE_100MS) != 0) {
        fprintf(stderr, "Failed to set measurement rate.\n");
        return -1;
    }

    printf("Sensor initialized successfully.\n");
    return 0;
}

static void get_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    struct tm tm_info;

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(buf + strlen(buf), len - strlen(buf), ".%03ld", ts.tv_nsec / 1000000);
}

static void log_data(FILE *fp, const char *timestamp, float lux, uint16_t proximity)
{
    fprintf(fp, "%s,%.2f,%u\n", timestamp, lux, proximity);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, 0x82) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x82: %s\n", strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    if (init_sensor(g_i2c_fd) != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("Logging to %s every %d ms. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_MS);

    while (g_running) {
        char timestamp[32];
        uint16_t proximity = 0;
        float lux = 0.0f;

        get_timestamp(timestamp, sizeof(timestamp));

        if (i2c_read_reg16(g_i2c_fd, REG_ALS_VIS_DATA0, &proximity) != 0) {
            fprintf(stderr, "%s: ALS read error.\n", timestamp);
        } else if (i2c_read_reg16(g_i2c_fd, REG_PS1_DATA0, &lux) != 0) {
            fprintf(stderr, "%s: Proximity read error.\n", timestamp);
        } else {
            log_data(g_log_fp, timestamp, lux, proximity);
            printf("%s,%.2f,%u\n", timestamp, lux, proximity);
        }

        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down...\n");

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    printf("Resources released. Goodbye.\n");
    return EXIT_SUCCESS;
}

