#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI1145_ADDR 0x60

#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_REV_ID 0x01
#define SI1145_REG_SEQ_ID 0x02
#define SI1145_REG_INT_CFG 0x03
#define SI1145_REG_IRQ_ENABLE 0x04
#define SI1145_REG_IRQ_MODE1 0x05
#define SI1145_REG_IRQ_MODE2 0x06
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_MEAS_RATE1 0x09
#define SI1145_REG_PS_RATE 0x0A
#define SI1145_REG_PS_LED21 0x0F
#define SI1145_REG_PS_LED3 0x10
#define SI1145_REG_PS1_DATA0 0x18
#define SI1145_REG_PS1_DATA1 0x19
#define SI1145_REG_COMMAND 0x1A

#define SI1145_CMD_RESET 0x01
#define SI1145_CMD_PS_FORCE 0x05
#define SI1145_CMD_PS_AUTO 0x0D

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int read_reg(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int init_si1145(int handle) {
    uint8_t part_id;
    if (read_reg(handle, SI1145_REG_PART_ID, &part_id) < 0) return -1;
    if (part_id != 0x45) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x45)\n", part_id);
        return -1;
    }

    if (write_reg(handle, SI1145_REG_COMMAND, SI1145_CMD_RESET) < 0) return -1;
    gpioDelay(10000);

    if (write_reg(handle, SI1145_REG_HW_KEY, 0x17) < 0) return -1;

    if (write_reg(handle, SI1145_REG_MEAS_RATE0, 0x00) < 0) return -1;
    if (write_reg(handle, SI1145_REG_MEAS_RATE1, 0x00) < 0) return -1;
    if (write_reg(handle, SI1145_REG_PS_RATE, 0x0A) < 0) return -1;
    if (write_reg(handle, SI1145_REG_PS_LED21, 0x0F) < 0) return -1;
    if (write_reg(handle, SI1145_REG_IRQ_MODE1, 0x00) < 0) return -1;
