#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define BUZZER_PIN  27

#define DISTANCE_THRESHOLD_CM 20.0
#define TRIGGER_PULSE_US      10
#define SAMPLE_INTERVAL_S     1

/* Speed of sound at 20 °C ≈ 343 m/s */
#define SPEED_OF_SOUND_CM_PER_US 0.0343

static volatile sig_atomic_t g_running = 1;

/*
 * Echo pulse measurement state.
 * Updated from the alert callback (runs in pigpio thread).
 */
static volatile uint32_t g_rise_tick = 0;
static volatile uint32_t g_fall_tick = 0;
static volatile int      g_echo_done = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * pigpio alert callback for the echo pin.
 * level: 1 = rising edge, 0 = falling edge, 2 = timeout.
 */
static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        g_rise_tick = tick;
    } else if (level == 0) {
        g_fall_tick = tick;
        g_echo_done = 1;
    }
}

static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static double measure_distance_cm(void)
{
    g_echo_done = 0;
    g_rise_tick = 0;
    g_fall_tick = 0;

    trigger_sensor();

    /*
     * Wait for the echo callback to complete.
     * Timeout after ~30 ms (max round-trip ~5 m).
     */
    for (int i = 0; i < 30000 && !g_echo_done; i++) {
        gpioDelay(100);
    }

    if (!g_echo_done) {
        fprintf(stderr, "Warning: echo timeout (no object detected or sensor error)\n");
        return -1.0;
    }

    uint32_t rise = g_rise_tick;
    uint32_t fall = g_fall_tick;

    /* pigpio ticks are 32-bit microseconds; handle wrap-around */
    if (fall >= rise) {
        return (double)(fall - rise) * SPEED_OF_SOUND_CM_PER_US / 2.0;
    }

    return (double)(0xFFFFFFFFu - rise + fall + 1u) * SPEED_OF_SOUND_CM_PER_US / 2.0;
}

static void control_buzzer(double distance_cm)
{
    int level = (distance_cm < DISTANCE_THRESHOLD_CM) ? 1 : 0;
    gpioWrite(BUZZER_PIN, level);
}

int main(void)
{
    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set BUZZER_PIN %d as output\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure known initial states */
    gpioWrite(TRIGGER_PIN, 0);
    gpioWrite(BUZZER_PIN, 0);

    /* Register alert callback for echo pin */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to set alert function on ECHO_PIN %d\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Ultrasonic distance measurement started.\n");
    printf("  Trigger: BCM GPIO%d | Echo: BCM GPIO%d | Buzzer: BCM GPIO%d\n",
           TRIGGER_PIN, ECHO_PIN, BUZZER_PIN);
    printf("  Threshold: %.1f cm | Sample interval: %d s\n",
           DISTANCE_THRESHOLD_CM, SAMPLE_INTERVAL_S);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        double distance = measure_distance_cm();

        if (distance < 0.0) {
            /* Error already reported; ensure buzzer is off */
            gpioWrite(BUZZER_PIN, 0);
        } else {
            printf("Distance: %.2f cm\n", distance);
            control_buzzer(distance);
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    /* Clean shutdown */
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

