#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN    17
#define SERVO_PIN   18

#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define MAX_DISTANCE_CM          200.0
#define MIN_DISTANCE_CM          20.0
#define MAX_DISTANCE_MM          110
#define MIN_DISTANCE_MM          20

#define SERVO_MIN_PULSE_US 500
#define SERVO_MAX_PULSE_US 2500
#define SERVO_MID_PULSE_US 1500

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set SERVO_PIN %d as output.\n", SERVO_PIN);
        gpioTerminate();
        return -1;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(10000); /* 10 ms settle */

    return 0;
}

static void trigger_sensor(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); /* 10 us trigger pulse */
    gpioWrite(TRIGGER_PIN, 0);
}

/*
 * Measures distance in centimetres.
 * Returns distance on success, or -1.0 on timeout / error.
 */
static float measure_distance(void) {
    trigger_sensor();

    /* Wait for echo rising edge (timeout 30 ms) */
    uint32_t start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start_tick) > 30000) {
            fprintf(stderr, "Warning: echo start timeout.\n");
            return -1.0;
        }
    }
    uint32_t echo_start = gpioTick();

    /* Wait for echo falling edge (timeout 30 ms) */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - echo_start) > 30000) {
            fprintf(stderr, "Warning: echo end timeout.\n");
            return -1.0;
        }
    }
    uint32_t echo_end = gpioTick();

    uint32_t pulse_width = echo_end - echo_start;
    float distance = (pulse_width * SPEED_OF_SOUND_CM_PER_US) / 2.0f;

    return distance;
}

static int set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;

    int pulse_width = SERVO_MIN_PULSE_US +
        (int)((float)angle / 180.0f * (SERVO_MAX_PULSE_US - SERVO_MIN_PULSE_US));

    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pin %d.\n", SERVO_PIN);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    gpioServo(SERVO_PIN, 0); /* stop servo PWM */
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Parking Assist System started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Error: distance measurement failed, retrying...\n");
            gpioDelay(100000); /* 100 ms backoff */
            continue;
        }

        int angle;
        if (distance <= MIN_DISTANCE_CM) {
            angle = 180;
        } else if (distance >= MAX_DISTANCE_CM) {
            angle = 0;
        } else {
            angle = (int)((MAX_DISTANCE_MM - distance) * 90.0f / (MAX_DISTANCE_MM - MIN_DISTANCE_MM));
        }

        if (set_servo_angle(angle) != 0) {
            fprintf(stderr, "Error: failed to set servo angle.\n");
        }

        printf("Distance: %.2f cm, Servo Angle: %d\n", distance, angle);

        gpioDelay(100000); /* 100 ms loop delay */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

