#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define DISTANCE_THRESHOLD_CLOSE 200
#define DISTANCE_THRESHOLD_FAR 250
#define SERVO_PULSE_CLOSE 2000
#define SERVO_PULSE_FAR 1000
#define LOG_FILE "gate_log.txt"

#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_MODE_START_STOP 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_DISTANCE 0x001E
#define VL53L1X_REG_SOFT_RESET 0x0000
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x0086
#define VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG_GPIO 0x008A
#define VL53L1X_REG_GPIO_HV_MUX_ACTIVE_HIGH 0x0084
#define VL53L1X_REG_RANGE_CONFIG_A 0x005A
#define VL53L1X_REG_RANGE_CONFIG_B 0x005C
#define VL53L1X_REG_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x005B
#define VL53L1X_REG_RANGE_CONFIG_TIMEOUT_MACROP_LO 0x005C
#define VL53L1X_REG_INTERMEASUREMENT_PERIOD 0x001B
#define VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG_GPIO_HV 0x008A
#define VL53L1X_REG_GPIO_TIO_HV_STATUS 0x0089
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x0013
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_INTERRUPT_CLEAR 0x0015

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint8_t len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) != 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int vl53l1x_init(int handle) {
    uint8_t model_id = 0;
    if (i2c_read_reg16(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) != 1) {
        fprintf(stderr, "Error: Failed to read model ID.\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Invalid model ID 0x%02X (expected 0xEA).\n", model_id);
        return -1;
    }
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) != 0) return -1;
    gpioDelay(10000);
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x01) != 0) return -1;
    gpioDelay(10000);
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG_GPIO, 0x04) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_GPIO_HV_MUX_ACTIVE_HIGH, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_A, 0x0C) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_B, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_TIMEOUT_MACROP_HI, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_TIMEOUT_MACROP_LO, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_INTERMEASUREMENT_PERIOD, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG_GPIO_HV, 0x04) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START_STOP, 0x00) != 0) return -1;
    return 0;
}

static int vl53l1x_start_ranging(int handle) {
    return i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START_STOP, 0x01);
}

static int vl53l1x_read_distance(int handle, uint16_t *distance) {
    uint8_t status = 0;
    uint8_t data[2] = {0};
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS, &status, 1) != 1) return -1;
    if ((status & 0x07) == 0) return 1;
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, data, 2) != 2) return -1;
    *distance = (data[0] << 8) | data[1];
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) return -1;
    return 0;
}

static void set_servo_pulse(int pin, int pulse_width) {
    if (pulse_width < 500) pulse_width = 500;
    if (pulse_width > 2500) pulse_width = 2500;
    gpioServo(pin, pulse_width);
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d).\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (vl53l1x_start_ranging(i2c_handle) != 0) {
        fprintf(stderr, "Error: Failed to start ranging.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    int gate_open = 0;
    int prev_gate_open = 0;
    while (running) {
        uint16_t distance = 0;
        int ret = vl53l1x_read_distance(i2c_handle, &distance);
        if (ret == 0) {
            if (distance > DISTANCE_THRESHOLD_FAR && !gate_open) {
                set_servo_pulse(SERVO_PIN, SERVO_PULSE_FAR);
                gate_open = 1;
                log_event("Gate opened");
            } else if (distance < DISTANCE_THRESHOLD_CLOSE && gate_open) {
                set_servo_pulse(SERVO_PIN, SERVO_PULSE_CLOSE);
                gate_open = 0;
                log_event("Gate closed");
            }
        } else if (ret < 0) {
            fprintf(stderr, "Warning: I2C read error.\n");
        }
        if (gate_open != prev_gate_open) {
            prev_gate_open = gate_open;
        }
        gpioDelay(100000);
    }
    set_servo_pulse(SERVO_PIN, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

