/*
 * HC-SR04 ultrasonic distance measurement with SG90 servo control.
 *
 * Board:  Raspberry Pi 4 Model B
 * Trigger: GPIO23 (BCM)  -> HC-SR04 TRIG
 * Echo:    GPIO24 (BCM)  -> HC-SR04 ECHO
 * Servo:   GPIO18 (BCM)  -> SG90 signal (5 V supply, common ground)
 *
 * Build:  gcc -O2 -Wall -Wextra -o hcsr04_servo hcsr04_servo.c -lservo
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

#include "servo.h"

/* ----------------------------- Configuration ----------------------------- */
#define TRIGGER_PIN      23          /* BCM 23 - HC-SR04 TRIG */
#define ECHO_PIN         24          /* BCM 24 - HC-SR04 ECHO */
#define SERVO_PIN        18          /* BCM 18 - SG90 signal */

#define TRIGGER_PULSE_US 10          /* HC-SR04 trigger pulse width (µs) */
#define ECHO_TIMEOUT_US  50000       /* 50 ms timeout for echo pulse     */
#define LOOP_DELAY_US    100000      /* 100 ms between measurements     */
#define MIN_DISTANCE_CM  2.0         /* HC-SR04 minimum range (cm)       */
#define MAX_DISTANCE_CM  400.0       /* HC-SR04 maximum range (cm)       */
#define MIN_ANGLE_DEG    0
#define MAX_ANGLE_DEG    180
#define SERVO_MIN_US     500         /* SG90 0° pulse width (µs)         */
#define SERVO_MAX_US     2500        /* SG90 180° pulse width (µs)       */
#define SERVO_STOP_US    0           /* SG90 stop / no-signal pulse     */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;

/* --------------------------- Signal handling ----------------------------- */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_sigint_handler(void)
{
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    return sigaction(SIGINT, &sa, NULL);
}

/* --------------------------- Timing helpers ------------------------------ */
static uint64_t now_us(void)
{
