        fprintf(stderr, "Error: servo angle %d out of range [%d, %d].\n",
                angle, MIN_ANGLE_DEG, MAX_ANGLE_DEG);
        return -1;
    }

    int pulse_us = SERVO_MIN_US +
                   (int)((long)angle * (SERVO_MAX_US - SERVO_MIN_US) /
                         (MAX_ANGLE_DEG - MIN_ANGLE_DEG));

    int rc = servo_set_pulse_width(pulse_us);
