/*
 * Measure distance in centimetres.
 * Returns:
 *   > 0  : valid distance (cm)
 *   -1.0: timeout waiting for echo pulse
 *   -2.0: sensor not responding (no echo ever seen)
 */
static float hcsr04_measure(void)
{
