    if (gpio_write(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpio_write(TRIGGER, 0) failed.\n");
        return -2.0;
    }
    sleep_us(2);

    /* 10 µs trigger pulse */
    if (gpio_write(TRIGGER_PIN, 1) != 0) {
        fprintf(stderr, "Error: gpio_write(TRIGGER, 1) failed.\n");
        return -2.0;
    }
    sleep_us(TRIGGER_PULSE_US);
    if (gpio_write(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpio_write(TRIGGER, 0) failed.\n");
        return -2.0;
