    /* Wait for echo rising edge (timeout) */
    uint64_t t0 = now_us();
    while (gpio_read(ECHO_PIN) == 0) {
        if (now_us() - t0 > ECHO_TIMEOUT_US) {
            return -1.0;          /* no echo start within timeout */
        }
    }
    uint64_t echo_start = now_us();

    /* Wait for echo falling edge (timeout) */
    while (gpio_read(ECHO_PIN) == 1) {
        if (now_us() - echo_start > ECHO_TIMEOUT_US) {
            return -1.0;          /* echo stuck high within timeout */
        }
    }
    uint64_t echo_end = now_us();

    uint64_t pulse_us = echo_end - echo_start;

    /* distance = (pulse_us * speed_of_sound) / 2 */
    float distance_cm = (float)pulse_us * 0.0343f / 2.0f;

    /* Sanity-check against HC-SR04 operating range */
    if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
        return -2.0;              /* out of range / noise */
    }

    return distance_cm;
}

