 * Map distance to servo angle.
 *   < 20 cm  -> 0°
 *   > 200 cm -> 180°
 *   20-200 cm -> linear interpolation
 */
static int distance_to_angle(float distance_cm)
{
    if (distance_cm < MIN_DISTANCE_CM) {
        return MIN_ANGLE_DEG;
    }
    if (distance_cm > MAX_DISTANCE_CM) {
        return MAX_ANGLE_DEG;
    }

    float ratio = (distance_cm - MIN_DISTANCE_CM) /
