int main(void)
{
    /* Initialise servo driver */
    if (servo_init() != 0) {
        fprintf(stderr, "Error: servo_init() failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    if (install_sigint_handler() != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler.\n");
    }

    printf("HC-SR04 + SG90 servo control started.\n");
    printf("Trigger: BCM %d | Echo: BCM %d | Servo: BCM %d\n",
           TRIGGER_PIN, ECHO_PIN, SERVO_PIN);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        float distance = hcsr04_measure();

        if (distance < 0.0f) {
            if (distance == -1.0f) {
                fprintf(stderr, "Warning: echo timeout (no object or sensor error).\n");
            } else {
                fprintf(stderr, "Warning: sensor not responding (no echo).\n");
            }
            /* Stop servo on error for safety */
            (void)servo_stop();
        } else {
            int angle = distance_to_angle(distance);
            if (servo_set_angle(angle) != 0) {
                fprintf(stderr, "Warning: servo_set_angle(%d) failed.\n", angle);
            }
            printf("Distance: %6.2f cm  |  Angle: %3d°\n", distance, angle);
        }

        sleep_us(LOOP_DELAY_US);
    }

    /* --------------------------- Cleanup --------------------------------- */
    printf("\nShutting down...\n");
    (void)servo_stop();
    servo_shutdown();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

