#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

/* Si7005 I2C address (7-bit) */
#define SI7005_ADDR 0x76

/* Si7005 register addresses */
#define SI7005_REG_TEMP_HOLD  0xE0
#define SI7005_REG_HUMID_HOLD 0xE5
#define SI7005_REG_CONFIG     0x80

/* Si7005 CONFIG register bits */
#define SI7005_CONFIG_1HZ    0x00
#define SI7005_CONFIG_128HZ  0x08
#define SI7005_CONFIG_256HZ  0x10
#define SI7005_CONFIG_512HZ  0x18
#define SI7005_CONFIG_1004HZ 0x20
#define SI7005_CONFIG_1024HZ 0x28
#define SI7005_CONFIG_2048HZ 0x30
#define SI7005_CONFIG_4096HZ 0x38

/* Global variables for signal handling and cleanup */
static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Function to initialize the Si7005 sensor */
static int init_si7005(int handle) {
    /*
     * The Si7005 requires the CONFIG register to be written before it can
     * begin measuring.  A safe default is 1 Hz update rate.
     */
    if (i2cWriteByteData(handle, SI7005_REG_CONFIG, SI7005_CONFIG_1HZ) < 0) {
        fprintf(stderr, "Error: Failed to write CONFIG register (1 Hz).\n");
        return -1;
    }
    return 0;
}

/* Function to read a 16-bit value from the Si7005 */
static int read_si7005(int handle, uint8_t reg, uint16_t *value) {
    char buf[2];

    /* Write the register address to point to the desired register */
    if (i2cWriteByte(handle, reg) < 0) {
        fprintf(stderr, "Error: Failed to write register address 0x%02X.\n", reg);
        return -1;
    }

    /* Wait for the conversion to complete (per datasheet timing) */
    gpioDelay(10000); /* 10 ms */

    /* Read 2 bytes of data */
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read data from register 0x%02X.\n", reg);
        return -1;
    }

    /* Combine the two bytes into a 16-bit value (MSB first) */
    *value = ((uint16_t)buf[0] << 8) | (uint16_t)buf[1];

    return 0;
}

/* Function to read temperature from the Si7005 */
static int read_temperature(int handle, float *temperature) {
    uint16_t raw_temp;

    if (read_si7005(handle, SI7005_REG_TEMP_HOLD, &raw_temp) < 0) {
        return -1;
    }

    /*
     * The Si7005 temperature conversion formula is:
     *   temperature = (raw_temp / 65536.0) - 0.0065 * raw_temp
     * For 14-bit resolution, the raw value is left-justified in 16 bits.
     */
    *temperature = ((float)raw_temp / 65536.0f) - (0.0065f * (float)raw_temp);

    return 0;
}

/* Function to read humidity from the Si7005 */
static int read_humidity(int handle, float *humidity) {
    uint16_t raw_humidity;

    if (read_si7005(handle, SI7005_REG_HUMID_HOLD, &raw_humidity) < 0) {
        return -1;
    }

    /*
     * The Si7005 humidity conversion formula is:
     *   humidity = (raw_humidity / 65536.0) - 0.0065 * raw_humidity
     * For 14-bit resolution, the raw value is left-justified in 16 bits.
     */
    *humidity = ((float)raw_humidity / 65536.0f) - (0.0065f * (float)raw_humidity);

    return 0;
}

int main(void) {
    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the Si7005 address */
    i2c_handle = i2cOpen(1, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at address 0x%02X (code %d).\n",
                SI7005_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the Si7005 sensor */
    if (init_si7005(i2c_handle) < 0) {
        fprintf(stderr, "Error: Si7005 initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    /* Main loop */
    while (running) {
        float temperature, humidity;

        /* Read temperature and humidity */
        if (read_temperature(i2c_handle, &temperature) < 0 ||
            read_humidity(i2c_handle, &humidity) < 0) {
            fprintf(stderr, "Error: Failed to read sensor data. Re-initializing I2C.\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(1000000); /* Wait 1 second before retrying */
            i2c_handle = i2cOpen(1, SI7005_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: Failed to re-open I2C bus. Exiting.\n");
                break;
            }
            if (init_si7005(i2c_handle) < 0) {
                fprintf(stderr, "Error: Si7005 re-initialization failed. Exiting.\n");
                break;
            }
            continue;
        }

        /* Print temperature and humidity to the console */
        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);

        /* Wait for 2 seconds */
        gpioDelay(2000000);
    }

    /* Cleanup */
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

