            gpioDelay(1000000); /* Wait 1 second before retrying */
            i2c_handle = i2cOpen(1, SI7005_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: Failed to re-open I2C bus. Exiting.\n");
                break;
            }
            if (init_si7005(i2c_handle) < 0) {
                fprintf(stderr, "Error: Si7005 re-initialization failed. Exiting.\n");
                break;
            }
            continue;
        }

        /* Print temperature and humidity to the console */
        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);

        /* Wait for 2 seconds */
        gpioDelay(2000000);
    }

    /* Cleanup */
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

