/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define MPU6050_WHO_AM_I   0x75
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H  0x43

/* Expected WHO_AM_I value for MPU-6050 */
#define MPU6050_WHO_AM_I_VAL 0x68

/* Scaling factors (full-scale ±250°/s, ±2g) */
#define ACCEL_SCALE 16384.0f
#define GYRO_SCALE  131.0f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int mpu6050_init(int handle)
{
    int who = i2cReadByteData(handle, MPU6050_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error: I2C read failed for WHO_AM_I (pigpio error %d)\n", who);
        return -1;
    }
    if (who != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X). Sensor not present?\n",
                who, MPU6050_WHO_AM_I_VAL);
        return -1;
    }

    /* Wake up the MPU-6050 (clear SLEEP bit) */
    if (i2cWriteByteData(handle, MPU6050_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake MPU-6050 (I2C write failed)\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms stabilization */
    return 0;
}

static int read_mpu6050_data(int handle,
                             float *ax, float *ay, float *az,
                             float *gx, float *gy, float *gz)
{
    char buf[14];

    /*
     * pigpio's i2cReadI2CBlockData issues a repeated-start read of the
     * specified length from the given register.  The MPU-6050 auto-increments
     * its register pointer, so starting at ACCEL_XOUT_H reads 14 bytes
     * containing accel(6) + temp(2) + gyro(6).
     */
    int bytes = i2cReadI2CBlockData(handle, MPU6050_ACCEL_XOUT_H, buf, 14);
    if (bytes != 14) {
        fprintf(stderr, "Error: I2C block read failed (got %d bytes, expected 14)\n", bytes);
        return -1;
    }

    int16_t raw_ax = (int16_t)((buf[0]  << 8) | (uint8_t)buf[1]);
    int16_t raw_ay = (int16_t)((buf[2]  << 8) | (uint8_t)buf[3]);
    int16_t raw_az = (int16_t)((buf[4]  << 8) | (uint8_t)buf[5]);
    /* buf[6..7] = temperature (skipped) */
    int16_t raw_gx = (int16_t)((buf[8]  << 8) | (uint8_t)buf[9]);
    int16_t raw_gy = (int16_t)((buf[10] << 8) | (uint8_t)buf[11]);
    int16_t raw_gz = (int16_t)((buf[12] << 8) | (uint8_t)buf[13]);

    *ax = (float)raw_ax / ACCEL_SCALE;
    *ay = (float)raw_ay / ACCEL_SCALE;
    *az = (float)raw_az / ACCEL_SCALE;
    *gx = (float)raw_gx / GYRO_SCALE;
    *gy = (float)raw_gy / GYRO_SCALE;
    *gz = (float)raw_gz / GYRO_SCALE;

    return 0;
}

