{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    g_i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus 1 at address 0x%02X (pigpio error %d)\n",
                MPU6050_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpu6050_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MPU-6050 ready. Logging accelerometer and gyroscope data every 100 ms...\n");
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float ax, ay, az, gx, gy, gz;

        if (read_mpu6050_data(g_i2c_handle, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            printf("Accel: X=%.2f g, Y=%.2f g, Z=%.2f g  |  Gyro: X=%.2f deg/s, Y=%.2f deg/s, Z=%.2f deg/s\n",
                   ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Warning: read failed, continuing...\n");
        }

        gpioDelay(100000); /* 100 ms */
    }

    /* Clean shutdown */
    i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

