        return -1;
    }

    uint16_t raw_temp = ((uint16_t)(buf[0] & 0xFF) << 8) | (uint8_t)buf[1];
    *temperature = -45.0f + (175.0f * (float)raw_temp / 65535.0f);
    return 0;
}

static int log_temperature(const char *filename, float temperature) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] Temperature: %.2f C\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temperature);
    fclose(fp);
    return 0;
}

