/*
 * SDP810-125Pa differential pressure sensor logger for Raspberry Pi Zero W.
 *
 * Wiring:
 *   SDP810 VDD  -> Pi 3V3 (Pin 1)
 *   SDP810 GND  -> Pi GND (Pin 9)
 *   SDP810 SDA  -> Pi GPIO2 / I2C bus 1 SDA (Pin 3)
 *   SDP810 SCL  -> Pi GPIO3 / I2C bus 1 SCL (Pin 5)
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp810_logger sdp810_logger.c
 * Run:    ./sdp810_logger   (requires r/w access to /dev/i2c-1)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP810_ADDR    0x24
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_PERIOD  1          /* seconds between samples */
#define MEAS_DELAY_US  1000       /* 1 ms measurement settle delay */

/* SDP810 command bytes (MSB first) */
static const uint8_t CMD_START_CONT[2] = {0x36, 0x08};
static const uint8_t CMD_MEASURE[2]   = {0x36, 0x02};

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (polynomial 0x31, init 0xFF) — Sensirion convention            */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write(int fd, const uint8_t *buf, size_t len)
{
    ssize_t n = write(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C short write: %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C short read: %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor operations                                                   */
/* ------------------------------------------------------------------ */
static int sdp810_start_continuous(int fd)
{
    if (i2c_write(fd, CMD_START_CONT, sizeof(CMD_START_CONT)) != 0)
        return -1;
    /* Datasheet: start continuous measurement needs up to 1 ms */
    usleep(1000);
    return 0;
}

static int sdp810_read_measurement(int fd,
                                   float *pressure_pa,
                                   float *temperature_c)
{
    uint8_t data[9];

    if (i2c_write(fd, CMD_MEASURE, sizeof(CMD_MEASURE)) != 0)
        return -1;

    usleep(MEAS_DELAY_US);

    if (i2c_read(fd, data, sizeof(data)) != 0)
        return -1;

    /* CRC validation for each 2-byte data word */
    if (crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "CRC mismatch on pressure word\n");
        return -1;
    }
    if (crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "CRC mismatch on temperature word\n");
        return -1;
    }
    if (crc8(&data[6], 2) != data[8]) {
        fprintf(stderr, "CRC mismatch on scale-factor word\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_temp     = (int16_t)((data[3] << 8) | data[4]);
    int16_t scale_factor = (int16_t)((data[6] << 8) | data[7]);

    if (scale_factor == 0) {
        fprintf(stderr, "Invalid scale factor (0) from sensor\n");
        return -1;
    }

    *pressure_pa    = (float)raw_pressure / (float)scale_factor;
    *temperature_c  = (float)raw_temp / 200.0f;   /* SDP810 scale: 1 LSB = 0.5 °C */

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(const char *filename,
                    float pressure_pa,
                    float temperature_c)
{
    /* Check whether file exists / is empty to decide on header */
    int need_header = 0;
    FILE *chk = fopen(filename, "r");
    if (!chk) {
        need_header = 1;                 /* file does not exist yet */
    } else {
        fseek(chk, 0, SEEK_END);
        if (ftell(chk) == 0)
            need_header = 1;
        fclose(chk);
    }

    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", filename, strerror(errno));
        return -1;
    }

    if (need_header)
        fprintf(fp, "timestamp_utc,pressure_pa,temperature_c\n");

    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure_pa, temperature_c);
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SDP810_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                SDP810_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Probe: try a zero-length read to confirm the sensor is present */
    uint8_t probe;
    if (i2c_read(g_i2c_fd, &probe, 0) != 0) {
        fprintf(stderr, "No ACK from sensor at 0x%02X — check wiring/address\n",
                SDP810_ADDR);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (sdp810_start_continuous(g_i2c_fd) != 0) {
        fprintf(stderr, "Failed to start continuous measurement\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("SDP810 logger started. Logging to %s every %d s. Press Ctrl-C to stop.\n",
           LOG_FILE, SAMPLE_PERIOD);

    while (g_running) {
        float pressure_pa, temperature_c;

        if (sdp810_read_measurement(g_i2c_fd, &pressure_pa, &temperature_c) != 0) {
            fprintf(stderr, "Read error — continuing after 1 s\n");
            sleep(SAMPLE_PERIOD);
            continue;
        }

        if (log_data(LOG_FILE, pressure_pa, temperature_c) != 0) {
            fprintf(stderr, "Logging error — continuing\n");
        }

        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly...\n");
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    return EXIT_SUCCESS;
}

