/*
 * SHT40 humidity & temperature logger for Raspberry Pi 3 Model B+
 * I2C bus 1, SDA = GPIO2 (BCM), SCL = GPIO3 (BCM)
 * SHT40 7-bit address: 0x75 (datasheet default)
 *
 * Build:  gcc -O2 -Wall -Wextra -o sht40_logger sht40_logger.c
 * Run:    ./sht40_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SHT40_ADDR     0x75
#define SHT40_CMD_MSB  0x2C   /* high repeatability, clock stretching disabled */
#define SHT40_CMD_LSB  0x06   /* measurement command */
#define SHT40_MEAS_MS  10     /* datasheet: wait >= 10 ms after command */
#define LOG_FILE       "sht40_log.txt"
#define SAMPLE_MS     5000

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log   = NULL;

/* ---- Sensirion CRC-8 (poly 0x31, init 0xFF) ---- */
static uint8_t sht40_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_log) { fclose(g_log); g_log = NULL; }
    if (g_i2c_fd >= 0) { close(g_i2c_fd); g_i2c_fd = -1; }
}

/*
 * Read SHT40: writes command, waits, reads 6 bytes, validates CRCs.
 * Returns 0 on success, -1 on error.
 */
static int sht40_read(int fd, float *temp_c, float *rh)
{
    uint8_t cmd[2] = { SHT40_CMD_MSB, SHT40_CMD_LSB };
    ssize_t w = write(fd, cmd, sizeof(cmd));
    if (w != (ssize_t)sizeof(cmd)) {
        fprintf(stderr, "write(cmd) failed: %s\n", strerror(errno));
        return -1;
    }

    usleep(SHT40_MEAS_MS * 1000);

    uint8_t raw[6];
    ssize_t r = read(fd, raw, sizeof(raw));
    if (r != (ssize_t)sizeof(raw)) {
        fprintf(stderr, "read failed: got %zd bytes, expected %zu (%s)\n",
                r, sizeof(raw), r < 0 ? strerror(errno) : "short read");
        return -1;
    }

    /* CRC checks: [T_MSB, T_LSB, T_CRC], [RH_MSB, RH_LSB, RH_CRC] */
    if (sht40_crc8(&raw[0], 2) != raw[2]) {
        fprintf(stderr, "temperature CRC mismatch\n");
        return -1;
    }
    if (sht40_crc8(&raw[3], 2) != raw[5]) {
        fprintf(stderr, "humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = ((uint16_t)raw[0] << 8) | raw[1];
    uint16_t h_raw = ((uint16_t)raw[3] << 8) | raw[4];

    *temp_c = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *rh     = 100.0f * (float)h_raw / 65535.0f;
    return 0;
}

static void log_reading(FILE *f, float temp_c, float rh)
{
    time_t now = time(NULL);
    struct tm tmv;
    char ts[32];
    localtime_r(&now, &tmv);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv);
    fprintf(f, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", ts, temp_c, rh);
    fflush(f);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SHT40_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("SHT40 logger started. Logging to %s every %d ms. Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_MS);

    while (g_running) {
        float temp_c, rh;
        if (sht40_read(g_i2c_fd, &temp_c, &rh) == 0) {
            log_reading(g_log, temp_c, rh);
            printf("%s  T=%.2f C  RH=%.2f %%\n",
                   "sample", temp_c, rh);
        } else {
            fprintf(stderr, "read failed; will retry next cycle\n");
        }
        /* sleep SAMPLE_MS but wake early on signal */
        for (int ms = 0; ms < SAMPLE_MS && g_running; ms += 100)
            usleep(100 * 1000);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

