#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x25
#define LOG_FILE       "airflow.log"
#define SAMPLE_US      100000   /* 100 ms */
#define MEAS_DELAY_US  1000     /* 1 ms   */
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ---- CRC-8 (Sensirion polynomial 0x31, init 0xFF) ---- */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ---- Trigger continuous measurement ---- */
static int trigger_measurement(int handle)
{
    uint8_t cmd[3] = {0x36, 0x08, 0x00};
    int rc = i2cWriteDevice(handle, (char *)cmd, 3);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice (trigger) failed: %d\n", rc);
        return -1;
    }
    return 0;
}

/* ---- Read 6-byte measurement frame ---- */
static int read_measurement(int handle, uint8_t *buf)
{
    int rc = i2cReadDevice(handle, (char *)buf, 6);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed: %d\n", rc);
        return -1;
    }
    if (rc != 6) {
        fprintf(stderr, "[ERROR] Short read: got %d bytes, expected 6\n", rc);
        return -1;
    }
    return 0;
}

/* ---- Convert raw bytes to physical values ---- */
static void convert(const uint8_t *buf, float *pressure_pa, float *temp_c)
{
    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temp     = (int16_t)((buf[3] << 8) | buf[4]);

    *pressure_pa = (float)raw_pressure / 60.0f;   /* SDP31 ±500 Pa, scale factor 60 */
    *temp_c      = (float)raw_temp / 200.0f;      /* SDP31 temperature, scale factor 200 */
}

/* ---- Append a CSV line to the log ---- */
static int log_data(FILE *fp, float pressure_pa, float temp_c)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return -1;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure_pa, temp_c) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "[ERROR] fflush failed\n");
        return -1;
    }
    return 0;
}

/* ---- Retry wrapper for I²C operations ---- */
static int i2c_write_retry(int handle, const uint8_t *buf, int len)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteDevice(handle, (char *)buf, len);
        if (rc == 0)
            return 0;
        fprintf(stderr, "[WARN] i2cWriteDevice attempt %d failed: %d\n",
                attempt + 1, rc);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(10000 << attempt);   /* 10 ms, 20 ms, 40 ms */
    }
    return -1;
}

static int i2c_read_retry(int handle, uint8_t *buf, int len)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cReadDevice(handle, (char *)buf, len);
        if (rc == len)
            return 0;
        fprintf(stderr, "[WARN] i2cReadDevice attempt %d failed: %d\n",
                attempt + 1, rc);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(10000 << attempt);
    }
    return -1;
}

int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I²C ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "[FATAL] Cannot open %s\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    fprintf(stderr, "[INFO] SDP31 logging started (bus %d, addr 0x%02X, %s)\n",
            I2C_BUS, I2C_ADDR, LOG_FILE);

    /* ---- Main loop ---- */
    while (g_running) {
        uint8_t buf[6];

        if (trigger_measurement(g_i2c_handle) != 0) {
            fprintf(stderr, "[ERROR] Measurement trigger failed; retrying next cycle\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        gpioDelay(MEAS_DELAY_US);

        if (i2c_read_retry(g_i2c_handle, buf, 6) != 0) {
            fprintf(stderr, "[ERROR] Measurement read failed; retrying next cycle\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        float pressure_pa, temp_c;
        convert(buf, &pressure_pa, &temp_c);

        if (log_data(g_log_file, pressure_pa, temp_c) != 0)
            fprintf(stderr, "[ERROR] Logging failed\n");

        gpioDelay(SAMPLE_US);
    }

    fprintf(stderr, "[INFO] Shutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

