#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x18
#define CMD_TEMP_HOLD  0xE3
#define CMD_HUM_HOLD   0xE5
#define CMD_READ_ID    0xFA0F
#define LOG_FILE       "sensor_data.txt"
#define SAMPLE_US      5000000  /* 5 seconds */
#define MEASURE_US     20000    /* 20 ms max measurement wait */
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a 16-bit big-endian measurement from the Si7015.
 * Returns 0 on success, -1 on failure.
 */
static int read_measurement(int handle, uint8_t cmd, uint16_t *out)
{
    char buf[2];
    int rc;

    rc = i2cWriteByte(handle, cmd);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByte(0x%02X) failed: %d\n", cmd, rc);
        return -1;
    }

    /*
     * In No Hold Master mode the sensor holds the clock low during the
     * conversion, so a plain i2cReadDevice would block forever.  We poll
     * until we read two bytes or until the bus idles (~20 ms).
     */
    int attempts = 0;
    while (attempts < MAX_RETRIES) {
        int n = i2cReadDevice(handle, buf, 2);
        if (n == 2) {
            *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            return 0;
        }
        if (n < 0) {
            fprintf(stderr, "[ERROR] i2cReadDevice after cmd 0x%02X failed: %d\n",
                    cmd, n);
        } else {
            fprintf(stderr, "[ERROR] i2cReadDevice after cmd 0x%02X returned %d (bus idle)\n",
                    cmd, n);
        }
        attempts++;
        gpioDelay(1000); /* 1 ms */
    }
    return -1;
}

static int read_temperature(int handle, float *temp)
{
    uint16_t raw;
    if (read_measurement(handle, CMD_TEMP_HOLD, &raw) != 0)
        return -1;
    *temp = (175.72f * (float)raw / 65536.0f) - 46.85f;
    return 0;
}

static int read_humidity(int handle, float *hum)
{
    uint16_t raw;
    if (read_measurement(handle, CMD_HUM_HOLD, &raw) != 0)
        return -1;
    *hum = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (*hum < 0.0f)   *hum = 0.0f;
    if (*hum > 100.0f) *hum = 100.0f;
    return 0;
}

static int verify_sensor(int handle)
{
    char buf[8];
    int rc;

    rc = i2cWriteByteData(handle, 0, CMD_READ_ID);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] Failed to write ID command: %d\n", rc);
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    int n = i2cReadDevice(handle, buf, 8);
    if (n != 8) {
        fprintf(stderr, "[ERROR] Failed to read Si7015 ID (got %d bytes): %d\n",
                n, n);
        return -1;
    }
    /* The ID byte sequence is 0x14 0x03 0x00 0x00 0x00 0x00 0x00 0x00 */
    if (buf[0] != 0x14 || buf[1] != 0x03) {
        fprintf(stderr, "[ERROR] Unexpected Si7015 ID: %02X %02X\n",
                (unsigned char)buf[0], (unsigned char)buf[1]);
        return -1;
    }
    return 0;
}

static void log_data(FILE *fp, float temp, float hum)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    } else {
        strncpy(ts, "UNKNOWN", sizeof(ts));
        ts[sizeof(ts) - 1] = '\0';
    }
    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", ts, temp, hum);
    fflush(fp);
}

int main(void)
{
    float temperature, humidity;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (verify_sensor(g_i2c_handle) != 0) {
        fprintf(stderr, "[ERROR] Si7015 sensor not detected at 0x%02X on bus %d\n",
                I2C_ADDR, I2C_BUS);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "[ERROR] Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si7015 sensor detected at 0x%02X on bus %d. Logging to %s every 5 s.\n",
           I2C_ADDR, I2C_BUS, LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        if (read_temperature(g_i2c_handle, &temperature) != 0) {
            fprintf(stderr, "[WARN] Temperature read failed; skipping cycle.\n");
            gpioDelay(SAMPLE_US);
            continue;
        }
        if (read_humidity(g_i2c_handle, &humidity) != 0) {
            fprintf(stderr, "[WARN] Humidity read failed; skipping cycle.\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        log_data(fp, temperature, humidity);
        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down cleanly...\n");
    fclose(fp);
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

