#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x25
#define LOG_FILE       "airflow_data.txt"
#define SAMPLE_MS      100
#define MEAS_DELAY_MS  45

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* CRC-8 polynomial 0x31, init 0xFF, as used by Sensirion */
static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write(int fd, const uint8_t *buf, size_t len) {
    if (write(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: expected %zu, got %zd (%s)\n",
                len, n, strerror(errno));
        return -1;
    }
    return 0;
}

static int sdp800_trigger(int fd) {
    uint8_t cmd[2] = {0x36, 0x08};
    return i2c_write(fd, cmd, sizeof(cmd));
}

static int sdp800_read(int fd, float *pressure, float *temperature) {
    uint8_t raw[9];
    if (i2c_read(fd, raw, sizeof(raw)) != 0)
        return -1;

    /* Bytes 0-2: differential pressure (MSB, LSB, CRC) */
    if (crc8(&raw[0], 2) != raw[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    /* Bytes 3-5: temperature (MSB, LSB, CRC) */
    if (crc8(&raw[3], 2) != raw[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    /* Bytes 6-8: scale factor (MSB, LSB, CRC) */
    if (crc8(&raw[6], 2) != raw[8]) {
