/*
 * STS30-DIS Temperature Logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   STS30-DIS VDD  -> Pi 3.3V (Pin 1)
 *   STS30-DIS GND  -> Pi GND  (Pin 9)
 *   STS30-DIS SDA  -> Pi GPIO2 / I2C1 SDA (Pin 3)
 *   STS30-DIS SCL  -> Pi GPIO3 / I2C1 SCL (Pin 5)
 *
 * Build: gcc -O2 -Wall -o sts30_logger sts30_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define STS30_ADDR     0x29
#define MEASURE_CMD    0x3625  /* Single-shot, high repeatability, clock stretching disabled */
#define CONV_TIME_US   15000   /* 15 ms conversion time */
#define SAMPLE_PERIOD  60      /* Seconds between samples */
#define LOG_FILE       "enclosure_temp_log.txt"
#define ERR_FILE       "error_log.txt"

static volatile sig_atomic_t g_terminate = 0;
static FILE *g_log_fp = NULL;
static FILE *g_err_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (polynomial 0x31, init 0xFF) per Sensirion STS3x datasheet     */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Timestamped logging                                                 */
/* ------------------------------------------------------------------ */
static void log_message(FILE *fp, const char *level, const char *msg)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    } else {
        strncpy(ts, "UNKNOWN", sizeof(ts));
        ts[sizeof(ts) - 1] = '\0';
    }

    if (fp) {
        fprintf(fp, "%s [%s] %s\n", ts, level, msg);
        fflush(fp);
    }
    fprintf(stderr, "%s [%s] %s\n", ts, level, msg);
}

/* ------------------------------------------------------------------ */
/* Read temperature from STS30-DIS                                     */
/* Returns 0 on success (temp stored in *out_temp), -1 on error        */
/* ------------------------------------------------------------------ */
static int read_sts30(int handle, float *out_temp)
{
    uint8_t cmd[2] = {
        (uint8_t)((MEASURE_CMD >> 8) & 0xFF),
        (uint8_t)(MEASURE_CMD & 0xFF)
    };
    uint8_t buf[3];
    int rc;

    /* Send measurement command */
    rc = i2cWriteDevice(handle, (char *)cmd, 2);
    if (rc < 0) {
        log_message(g_err_fp, "ERROR", "I2C write failed");
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(CONV_TIME_US);

    /* Read 3 bytes: MSB, LSB, CRC */
    rc = i2cReadDevice(handle, (char *)buf, 3);
    if (rc < 0) {
        log_message(g_err_fp, "ERROR", "I2C read failed");
        return -1;
    }
    if (rc != 3) {
        log_message(g_err_fp, "ERROR", "Short read from STS30");
        return -1;
    }

    /* Validate CRC */
    if (crc8(buf, 2) != buf[2]) {
        log_message(g_err_fp, "ERROR", "CRC mismatch on temperature data");
        return -1;
    }

    /* Convert raw to Celsius */
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *out_temp = (float)raw / 100.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int handle;
    float temperature;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open log files */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("Failed to open " LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_err_fp = fopen(ERR_FILE, "a");
    if (!g_err_fp) {
        perror("Failed to open " ERR_FILE);
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Open I2C bus */
    handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (handle < 0) {
        log_message(g_err_fp, "ERROR", "Failed to open I2C device");
        fclose(g_log_fp);
        fclose(g_err_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_message(g_log_fp, "INFO", "STS30 logger started");

    /* Main sampling loop */
    while (!g_terminate) {
        if (read_sts30(handle, &temperature) == 0) {
            char ts[32];
            time_t t = time(NULL);
            struct tm tm;
            localtime_r(&t, &tm);
            strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

            fprintf(g_log_fp, "%s, %.2f\n", ts, temperature);
            fflush(g_log_fp);
        } else {
            log_message(g_err_fp, "ERROR", "Failed to read temperature");
        }

        /* Sleep in 100 ms increments so SIGINT is responsive */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && !g_terminate; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    /* Cleanup */
    log_message(g_log_fp, "INFO", "Shutting down");
    i2cClose(handle);
    fclose(g_log_fp);
    fclose(g_err_fp);
    gpioTerminate();

    return EXIT_SUCCESS;
}

