#define LOG_FILE       "sht40_log.txt"
#define MEASURE_CMD    0x24C8        /* High repeatability, clock stretching disabled */
#define MEASURE_DELAY  9000          /* microseconds (datasheet: typ 8.5 ms) */
#define SAMPLE_PERIOD  5             /* seconds between samples */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Sensirion CRC-8 (polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t sht40_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Millisecond sleep                                                   */
/* ------------------------------------------------------------------ */
static void delay_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_reading(float temp_c, float rh_pct)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(g_log_fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
            ts, temp_c, rh_pct);
    fflush(g_log_fp);
}

static void log_error(const char *msg)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(g_log_fp, "%s, ERROR: %s\n", ts, msg);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* SHT40 measurement                                                   */
/* ------------------------------------------------------------------ */
static int sht40_measure(int fd, float *temp_c, float *rh_pct)
{
    uint8_t cmd[2] = {
        (uint8_t)((MEASURE_CMD >> 8) & 0xFF),
        (uint8_t)( MEASURE_CMD        & 0xFF)
    };
    uint8_t data[6];

    /* Send measurement command */
    if (write(fd, cmd, sizeof(cmd)) != (ssize_t)sizeof(cmd)) {
        return -1;
    }

    /* Wait for conversion (datasheet: typ 8.5 ms) */
    delay_ms(MEASURE_DELAY);

    /* Read 6 bytes: T_MSB, T_LSB, T_CRC, RH_MSB, RH_LSB, RH_CRC */
    ssize_t n = read(fd, data, sizeof(data));
    if (n != (ssize_t)sizeof(data)) {
        return -1;
    }

    /* Validate CRCs */
    if (sht40_crc8(&data[0], 2) != data[2]) {
        return -2;  /* Temperature CRC mismatch */
    }
    if (sht40_crc8(&data[3], 2) != data[5]) {
        return -2;  /* Humidity CRC mismatch */
    }

    /* Convert raw values */
    uint16_t t_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t rh_raw = ((uint16_t)data[3] << 8) | data[4];

    *temp_c = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *rh_pct = 100.0f * (float)rh_raw / 65535.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire SHT40 slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                SHT40_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Register signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction failed: %s\n", strerror(errno));
    }

    printf("SHT40 greenhouse monitor started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        float temp_c, rh_pct;
        int rc = sht40_measure(g_i2c_fd, &temp_c, &rh_pct);

        if (rc == 0) {
            log_reading(temp_c, rh_pct);
            printf("%s  T=%.2f C  RH=%.2f %%\n",
                   __func__ ? "" : "", temp_c, rh_pct);
        } else if (rc == -1) {
            log_error("I2C read/write failure");
            fprintf(stderr, "I2C error: %s\n", strerror(errno));
        } else {
            log_error("SHT40 CRC mismatch");
            fprintf(stderr, "SHT40 CRC error (code %d)\n", rc);
        }

        /* Sleep SAMPLE_PERIOD seconds, but wake early on signal */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

