/*
 * SDP800-500Pa differential pressure sensor reader for Raspberry Pi 3 B+.
 *
 * Wiring:
 *   SDP800 VDD  -> Pi 3.3 V (pin 1)
 *   SDP800 GND  -> Pi GND  (pin 9)
 *   SDP800 SDA  -> Pi GPIO2 / I2C1 SDA (pin 3)
 *   SDP800 SCL  -> Pi GPIO3 / I2C1 SCL (pin 5)
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp800_reader sdp800_reader.c
 * Run:    ./sdp800_reader   (creates / appends to airflow_data.txt)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x25
#define LOG_FILE       "airflow_data.txt"
#define SAMPLE_PERIOD_US 1000000   /* 1 s */
#define MEAS_DELAY_US  1000        /* 1 ms */

/* SDP800 continuous measurement command (mass flow / differential pressure) */
static const uint8_t CMD_CONT_MEAS[2] = { 0x36, 0x08 };

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write(int fd, const uint8_t *buf, size_t len)
{
    ssize_t n = write(fd, buf, len);
    if (n < 0)
        perror("i2c write");
    else if ((size_t)n != len)
        fprintf(stderr, "i2c write: short write (%zd of %zu bytes)\n", n, len);
    return (n >= 0) ? 0 : -1;
}

static int i2c_read(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0)
        perror("i2c read");
    else if ((size_t)n != len)
        fprintf(stderr, "i2c read: short read (%zd of %zu bytes)\n", n, len);
    return (n >= 0) ? 0 : -1;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
static int read_sdp800(int fd, float *pressure, float *temperature)
{
    uint8_t data[6];

    /* Trigger continuous measurement */
    if (i2c_write(fd, CMD_CONT_MEAS, sizeof(CMD_CONT_MEAS)) != 0)
        return -1;

    usleep(MEAS_DELAY_US);

    /* Read 6 bytes: pressure(2)+crc, temperature(2)+crc */
    if (i2c_read(fd, data, sizeof(data)) != 0)
        return -1;

    /* Validate CRC for pressure (bytes 0-1, CRC byte 2) */
    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "CRC error: pressure\n");
        return -1;
    }

    /* Validate CRC for temperature (bytes 3-4, CRC byte 5) */
    if (crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "CRC error: temperature\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_temp     = (int16_t)((data[3] << 8) | data[4]);

    /* SDP800-500Pa scale factors (from datasheet) */
    const float scale_pressure = 1.0f;
    const float scale_temp     = 1.0f;

    *pressure    = (float)raw_pressure * scale_pressure;
    *temperature = (float)raw_temp     * scale_temp;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float pressure, float temperature)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handling for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen " LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("SDP800 reader started. Logging to %s. Press Ctrl+C to stop.\n",
           LOG_FILE);

    while (g_running) {
        float pressure = 0.0f, temperature = 0.0f;

        if (read_sdp800(g_i2c_fd, &pressure, &temperature) == 0) {
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n",
                   pressure, temperature);
            if (log_data(g_log_fp, pressure, temperature) != 0)
                fprintf(stderr, "Logging failed\n");
        } else {
            fprintf(stderr, "Sensor read failed (absent or bus error)\n");
        }

        /* Sleep in small increments so SIGINT is caught promptly */
        for (int i = 0; i < 10 && g_running; i++)
            usleep(SAMPLE_PERIOD_US / 10);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

