#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x76
#define FAN_GPIO       18
#define BUFFER_SIZE    60
#define TEMP_HIGH      28.0f
#define TEMP_LOW       27.0f
#define READ_INTERVAL  2.0
#define FAN_DELAY      0.01
#define MAX_RETRIES    3
#define SENSOR_ERROR   -1000.0f

typedef struct {
    time_t timestamp;
    float  temperature;
} Reading;

typedef struct {
    Reading buffer[BUFFER_SIZE];
    int     head;
    int     count;
} CircularBuffer;

static int           i2c_handle = -1;
static CircularBuffer temp_buffer;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void init_circular_buffer(CircularBuffer *cb) {
    cb->head  = 0;
    cb->count = 0;
}

static void add_reading(CircularBuffer *cb, float temperature) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time");
        return;
    }
    cb->buffer[cb->head].timestamp  = now;
    cb->buffer[cb->head].temperature = temperature;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static void print_buffer(const CircularBuffer *cb) {
    printf("\n--- Temperature Log (%d entries) ---\n", cb->count);
    int start = (cb->count == BUFFER_SIZE) ? cb->head : 0;
    for (int i = 0; i < cb->count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char time_str[32];
        struct tm tm_info;
        if (localtime_r(&cb->buffer[idx].timestamp, &tm_info) != NULL) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", &tm_info);
            printf("[%s] Temperature: %.2f C\n", time_str, cb->buffer[idx].temperature);
        } else {
            printf("[unknown] Temperature: %.2f C\n", cb->buffer[idx].temperature);
        }
    }
    printf("--- End of Log ---\n\n");
    fflush(stdout);
}

static int read_temperature(float *temperature) {
    char buf[2];
    int  result;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            unsigned int raw = ((unsigned int)(uint8_t)buf[0] << 8) | (unsigned int)(uint8_t)buf[1];
            *temperature = (float)raw / 100.0f - 40.0f;
            return 0;
        }
        fprintf(stderr, "I2C read attempt %d/%d failed (rc=%d)\n", attempt + 1, MAX_RETRIES, result);
        if (attempt < MAX_RETRIES - 1) gpioDelay(100000); /* 100 ms backoff */
    }
    return -1;
}

static void control_fan(float temperature) {
    static bool fan_on = false;

    if (temperature > TEMP_HIGH && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = true;
            printf("Fan ON  (Temperature: %.2f C)\n", temperature);
        } else {
            fprintf(stderr, "Failed to turn fan ON\n");
        }
    } else if (temperature < TEMP_LOW && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = false;
            printf("Fan OFF (Temperature: %.2f C)\n", temperature);
        } else {
            fprintf(stderr, "Failed to turn fan OFF\n");
        }
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(FAN_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    float temperature;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    init_circular_buffer(&temp_buffer);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Si7021 monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_temperature(&temperature) == 0) {
            add_reading(&temp_buffer, temperature);
            control_fan(temperature);
            printf("Temperature: %.2f C\n", temperature);
        } else {
            fprintf(stderr, "Sensor read failed after %d retries. Temperature: %.2f C\n", MAX_RETRIES, SENSOR_ERROR);
            add_reading(&temp_buffer, SENSOR_ERROR);
            if (gpioWrite(FAN_GPIO, 0) != 0) {
                fprintf(stderr, "Warning: failed to turn fan off after sensor error\n");
            }
        }
        gpioDelay((uint32_t)(READ_INTERVAL * 1000000.0));
    }

    printf("\nShutting down...\n");
    print_buffer(&temp_buffer);
    cleanup();
    return EXIT_SUCCESS;
}

