#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD40_I2C_ADDR 0x50
#define I2C_BUS 1
#define LOG_FILE "air_quality.log"
#define POLL_INTERVAL_SEC 5
#define MEASUREMENT_DELAY_SEC 1

/* SCD40 commands (16-bit, big-endian on the bus) */
#define CMD_START_PERIODIC_MEASUREMENT 0x0010
#define CMD_STOP_PERIODIC_MEASUREMENT  0x0104
#define CMD_GET_DATA_READY_STATUS     0x0202

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* CRC-8 as used by Sensirion: poly 0x31, init 0xFF, no final XOR       */
/* ------------------------------------------------------------------ */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit command to the SCD40                                 */
/* ------------------------------------------------------------------ */
static int scd40_write_command(int handle, uint16_t command)
{
    uint8_t buf[2];
    buf[0] = (uint8_t)(command >> 8);
    buf[1] = (uint8_t)(command & 0xFF);

    int result = i2cWriteDevice(handle, (char *)buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing command 0x%04X (pigpio rc=%d)\n", command, result);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read N bytes from the SCD40                                         */
/* ------------------------------------------------------------------ */
static int scd40_read_bytes(int handle, uint8_t *buf, size_t len)
{
    int result = i2cReadDevice(handle, (char *)buf, len);
    if (result != (int)len) {
        fprintf(stderr, "Error reading %zu bytes (got %d)\n", len, result);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Check whether data is ready (returns 1 if ready, 0 if not, -1 err)  */
/* ------------------------------------------------------------------ */
static int scd40_data_ready(int handle)
{
    if (scd40_write_command(handle, CMD_GET_DATA_READY_STATUS) != 0)
        return -1;

    gpioDelay(2000); /* 2 ms processing delay */

    uint8_t buf[3];
    if (scd40_read_bytes(handle, buf, sizeof(buf)) != 0)
        return -1;

    if (sensirion_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on data-ready word\n");
        return -1;
    }

    uint16_t word = (uint16_t)((buf[0] << 8) | buf[1]);
    return (word & 0x07FF) ? 1 : 0;
}

/* ------------------------------------------------------------------ */
/* Read one 9-byte measurement block and parse                         */
/* ------------------------------------------------------------------ */
static int scd40_read_measurement(int handle, uint16_t *co2,
                                  float *temperature, float *humidity)
{
    if (scd40_write_command(handle, CMD_GET_DATA_READY_STATUS) != 0)
        return -1;

    gpioDelay(2000); /* 2 ms processing delay */

    uint8_t buf[9];
    if (scd40_read_bytes(handle, buf, sizeof(buf)) != 0)
        return -1;

    /* Verify CRC for each 2-byte word */
    for (int i = 0; i < 3; i++) {
        if (sensirion_crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    uint16_t co2_raw  = (uint16_t)((buf[0] << 8) | buf[1]);
    uint16_t temp_raw = (uint16_t)((buf[3] << 8) | buf[4]);
    uint16_t rh_raw   = (uint16_t)((buf[6] << 8) | buf[7]);

    *co2  = co2_raw;
    *temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    *humidity = 100.0f * (float)rh_raw / 65535.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a CSV line to the log file                                   */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, uint16_t co2, float temperature, float humidity)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%u,%.2f,%.2f\n", ts, co2, temperature, humidity);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        scd40_write_command(i2c_handle, CMD_STOP_PERIODIC_MEASUREMENT);
        gpioDelay(2000); /* allow stop command to take effect */
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X (rc=%d)\n",
                I2C_BUS, SCD40_I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Start periodic measurement */
    if (scd40_write_command(i2c_handle, CMD_START_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Failed to start periodic measurement\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* First measurement is ready after 1 second */
    sleep(MEASUREMENT_DELAY_SEC);

    printf("SCD40 air-quality monitor started. Logging to %s every %d s.\n",
           LOG_FILE, POLL_INTERVAL_SEC);
    printf("Press Ctrl+C to stop.\n");

    while (!terminate) {
        int ready = scd40_data_ready(i2c_handle);
        if (ready < 0) {
            fprintf(stderr, "Error checking data-ready status\n");
        } else if (ready == 1) {
            uint16_t co2;
            float temperature, humidity;
            if (scd40_read_measurement(i2c_handle, &co2, &temperature, &humidity) == 0) {
                printf("CO2: %u ppm | Temp: %.2f C | RH: %.2f %%\n",
                       co2, temperature, humidity);
                log_data(log_file, co2, temperature, humidity);
            } else {
                fprintf(stderr, "Error reading measurement data\n");
            }
        }
        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

