#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SCD40_ADDR 0x50
#define GPIO_LED 17
#define CO2_THRESHOLD 1000
#define BUFFER_SIZE 20
#define READ_INTERVAL_SEC 5

#define CMD_START_PERIODIC_MEASUREMENT 0x0010
#define CMD_READ_MEASUREMENT 0x0026
#define CMD_STOP_PERIODIC_MEASUREMENT 0x0104

#define MEASUREMENT_INTERVAL_MS 5000

typedef struct {
    time_t timestamp;
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static int i2c_handle = -1;
static circular_buffer_t buffer;
static volatile sig_atomic_t terminate = 0;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, SCD40_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int start_periodic_measurement(void) {
    uint8_t cmd[2] = { (CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF, CMD_START_PERIODIC_MEASUREMENT & 0xFF };
    int rc = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "Error starting periodic measurement: %d\n", rc);
        return -1;
    }
    return 0;
}

static int read_measurement(uint16_t *co2, float *temperature, float *humidity) {
    uint8_t cmd[2] = { (CMD_READ_MEASUREMENT >> 8) & 0xFF, CMD_READ_MEASUREMENT & 0xFF };
    int rc = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "Error sending read measurement command: %d\n", rc);
        return -1;
    }

    gpioDelay(MEASUREMENT_INTERVAL_MS * 1000);

    uint8_t buf[9];
    rc = i2cReadDevice(i2c_handle, (char *)buf, 9);
    if (rc != 9) {
        fprintf(stderr, "Error reading measurement data: expected 9 bytes, got %d\n", rc);
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "CRC error on CO2 data\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "CRC error on temperature data\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "CRC error on humidity data\n");
        return -1;
    }

    *co2 = (buf[0] << 8) | buf[1];
    *temperature = -45.0f + 175.0f * (buf[3] / 65535.0f);
    *humidity = 100.0f * (buf[6] / 65535.0f);

    return 0;
}

static int stop_periodic_measurement(void) {
    uint8_t cmd[2] = { (CMD_STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF, CMD_STOP_PERIODIC_MEASUREMENT & 0xFF };
    int rc = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "Error stopping periodic measurement: %d\n", rc);
        return -1;
    }
    return 0;
}

static void init_circular_buffer(circular_buffer_t *cb) {
    cb->head = 0;
    cb->count = 0;
}

static void add_to_buffer(circular_buffer_t *cb, sensor_data_t data) {
    cb->data[cb->head] = data;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static void print_buffer(const circular_buffer_t *cb) {
    printf("\n--- Sensor Data (Latest to Oldest) ---\n");
    for (int i = 0; i < cb->count; i++) {
        int idx = (cb->head - cb->count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char time_str[32];
        struct tm *tm_info = localtime(&cb->data[idx].timestamp);
        if (tm_info) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        } else {
            strncpy(time_str, "INVALID", sizeof(time_str));
        }
        printf("[%s] CO2: %u ppm, Temp: %.2f C, RH: %.2f %%\n",
               time_str, cb->data[idx].co2, cb->data[idx].temperature, cb->data[idx].humidity);
    }
    printf("--- End of Buffer ---\n\n");
}

static void control_led(uint16_t co2) {
    gpioWrite(GPIO_LED, (co2 > CO2_THRESHOLD) ? 1 : 0);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        stop_periodic_measurement();
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(GPIO_LED, 0);
    gpioSetMode(GPIO_LED, PI_INPUT);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, 0);

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (start_periodic_measurement() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    init_circular_buffer(&buffer);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t co2;
    float temperature, humidity;

    while (!terminate) {
        if (read_measurement(&co2, &temperature, &humidity) == 0) {
            sensor_data_t data;
            data.timestamp = time(NULL);
            data.co2 = co2;
            data.temperature = temperature;
            data.humidity = humidity;

            add_to_buffer(&buffer, data);
            printf("CO2: %u ppm, Temp: %.2f C, RH: %.2f %%\n", co2, temperature, humidity);
            control_led(co2);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        for (int i = 0; i < READ_INTERVAL_SEC && !terminate; i++) {
            sleep(1);
        }
    }

    print_buffer(&buffer);
    cleanup();
    return EXIT_SUCCESS;
}

