#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TMP05_GPIO 4
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_S 5
#define TIMEOUT_US 50000
#define VALID_TEMP_MIN -40.0
#define VALID_TEMP_MAX 150.0
#define MAX_CONSECUTIVE_ERRORS 3

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(TMP05_GPIO, PI_INPUT);
    return 0;
}

static double read_temperature(void) {
    uint32_t start_tick, end_tick, high_tick, low_tick;
    int level;

    start_tick = gpioTick();
    while ((level = gpioRead(TMP05_GPIO)) == 0) {
        if ((gpioTick() - start_tick) > TIMEOUT_US) {
            fprintf(stderr, "Error: Timeout waiting for TMP05 high pulse\n");
            return -273.15;
        }
    }
    high_tick = gpioTick();

    while ((level = gpioRead(TMP05_GPIO)) == 1) {
        if ((gpioTick() - high_tick) > TIMEOUT_US) {
            fprintf(stderr, "Error: Timeout waiting for TMP05 low pulse\n");
            return -273.15;
        }
    }
    end_tick = gpioTick();
    low_tick = end_tick - high_tick;

    if (low_tick == 0) {
        fprintf(stderr, "Error: Zero low time, cannot compute temperature\n");
        return -273.15;
    }

    double temperature = (double)(low_tick) / 1000000.0;
    if (temperature < VALID_TEMP_MIN || temperature > VALID_TEMP_MAX) {
        fprintf(stderr, "Error: Temperature out of valid range: %.2f\n", temperature);
        return -273.15;
    }
    return temperature;
}

static void log_temperature(double temperature) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (temperature < VALID_TEMP_MIN || temperature > VALID_TEMP_MAX) {
