#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASURE_CMD_HIGH_REP 0x2450
#define MEASURE_DELAY_US 15000
#define RETRY_COUNT 3
#define RETRY_DELAY_US 1000000
#define LOG_INTERVAL_S 5
#define SINUSOIDAL_PERIOD_S 3600
#define SINUSOIDAL_AMPLITUDE_C 2.0
#define SINUSOIDAL_AMPLITUDE_RH 5.0

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float temperature;
    float humidity;
} SensorData;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static int initialize_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at bus %d, addr 0x%02X (pigpio error %d).\n",
                I2C_BUS, SHT35_ADDR, i2c_handle);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_sensor_data(SensorData *data) {
    uint8_t cmd[2] = { (MEASURE_CMD_HIGH_REP >> 8) & 0xFF, MEASURE_CMD_HIGH_REP & 0xFF };
    uint8_t buf[6];

    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "Warning: I2C write failed (attempt %d/%d).\n", attempt + 1, RETRY_COUNT);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        gpioDelay(MEASURE_DELAY_US);

        if (i2cReadDevice(i2c_handle, (char *)buf, 6) != 6) {
            fprintf(stderr, "Warning: I2C read failed (attempt %d/%d).\n", attempt + 1, RETRY_COUNT);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        if (crc8(&buf[0], 2) != buf[2]) {
            fprintf(stderr, "Warning: Temperature CRC mismatch (attempt %d/%d).\n", attempt + 1, RETRY_COUNT);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        if (crc8(&buf[3], 2) != buf[5]) {
            fprintf(stderr, "Warning: Humidity CRC mismatch (attempt %d/%d).\n", attempt + 1, RETRY_COUNT);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        uint16_t temp_raw = (buf[0] << 8) | buf[1];
        uint16_t hum_raw = (buf[3] << 8) | buf[4];

        data->temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
        data->humidity = 100.0f * (float)hum_raw / 65535.0f;

        if (data->humidity > 100.0f) data->humidity = 100.0f;
        if (data->humidity < 0.0f) data->humidity = 0.0f;

        return 0;
    }

    fprintf(stderr, "Error: Failed to read sensor data after %d attempts.\n", RETRY_COUNT);
    return -1;
}

static float apply_sinusoidal_offset(float value, float period_s) {
    float time_elapsed = (float)time(NULL) / (float)period_s;
    float phase = fmodf(time_elapsed, 1.0f);
    float offset = (phase * 2.0f * M_PI) - M_PI_2;
    return value + (offset * SINUSOIDAL_AMPLITUDE_C) * 0.1f;
}

static int log_data(const SensorData *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: Failed to get UTC time.\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (isnan(data->temperature) || isnan(data->humidity)) {
        fprintf(log_file, "%s,Temperature,NaN,Humidity,NaN\n", timestamp);
    } else {
        float temp_offset = apply_sinusoidal_offset(data->temperature, SINUSOIDAL_PERIOD_S);
        float rh_offset = apply_sinusoidal_offset(data->humidity, SINUSOIDAL_PERIOD_S);
        fprintf(log_file, "%s,Temperature,%.2f,Humidity,%.2f\n", timestamp, temp_offset, rh_offset);
    }

    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: Failed to register signal handler");
        return 1;
    }

    if (initialize_i2c() != 0) {
        return 1;
    }

    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        perror("Error: Failed to open log file");
        cleanup();
        return 1;
    }

    fprintf(log_file, "# Greenhouse environmental data log started\n");
    fflush(log_file);

    SensorData sensor_data;

    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            if (log_data(&sensor_data) != 0) {
                fprintf(stderr, "Warning: Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Warning: Sensor read failed, logging NaN values.\n");
            if (log_data(&sensor_data) != 0) {
                fprintf(stderr, "Warning: Failed to log NaN values.\n");
            }
        }

        for (int i = 0; i < LOG_INTERVAL_S && !terminate; i++) {
            sleep(1);
        }
    }

    cleanup();
    return 0;
}

