/*
 * SDP810-125Pa differential pressure sensor reader for Raspberry Pi 3 B+.
 *
 * Wiring:
 *   VDD  -> 3.3 V (Pin 1)
 *   GND  -> GND  (Pin 9)
 *   SDA  -> GPIO2 / I2C bus 1 SDA (Pin 3)
 *   SCL  -> GPIO3 / I2C bus 1 SCL (Pin 5)
 *
 * I2C address: 0x25 (7-bit)
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp810_logger sdp810_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP810_ADDR    0x25
#define CSV_FILENAME   "airflow.csv"
#define SAMPLE_PERIOD  1          /* seconds between samples */
#define CONV_TIME_MS   45         /* SDP810 continuous-measurement conversion time */

/* SDP810 continuous measurement command (mass flow / differential pressure) */
static const uint8_t CMD_CONT_MEAS[2] = { 0x36, 0x08 };

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                         */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write(int fd, const uint8_t *buf, size_t len)
{
    ssize_t n = write(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C short write: %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C short read: %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor data structure                                               */
/* ------------------------------------------------------------------ */
typedef struct {
    float pressure;     /* Pa */
    float temperature;  /* °C */
} sensor_data_t;

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
static int read_sensor_data(int fd, sensor_data_t *data)
{
    uint8_t buf[9];

    /* Send continuous-measurement command */
    if (i2c_write(fd, CMD_CONT_MEAS, sizeof(CMD_CONT_MEAS)) != 0)
        return -1;

    /* Wait for conversion to complete */
    struct timespec ts = { 0, CONV_TIME_MS * 1000000L };
    nanosleep(&ts, NULL);

    /* Read 9 bytes: pressure(2)+crc, temp(2)+crc, scale(2)+crc */
    if (i2c_read(fd, buf, sizeof(buf)) != 0)
        return -1;

    /* Validate CRCs */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "CRC error: pressure\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "CRC error: temperature\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "CRC error: scale factor\n");
        return -1;
    }

    /* Raw values are big-endian, signed */
    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temp     = (int16_t)((buf[3] << 8) | buf[4]);
