#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SHT35_ADDR     0x44
#define MEASURE_CMD    0x2435
#define MEASURE_DELAY_US 15000   /* 15 ms — datasheet max for high repeatability */
#define SAMPLE_INTERVAL_S 5
#define CSV_FILENAME   "environment.csv"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- CRC-8 (Sensirion polynomial 0x31, init 0xFF) ---- */
static uint8_t sht35_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ---- Timestamp helper ---- */
static int get_timestamp(char *buf, size_t buflen)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) return -1;
    struct tm tmv;
    if (localtime_r(&t, &tmv) == NULL) return -1;
    if (strftime(buf, buflen, "%Y-%m-%dT%H:%M:%S", &tmv) == 0) return -1;
    return 0;
}

/* ---- CSV logging ---- */
static int log_data(float temp_c, float rh_pct)
{
    char ts[32];
    if (get_timestamp(ts, sizeof(ts)) != 0) {
        fprintf(stderr, "Error: failed to generate timestamp\n");
        return -1;
    }

    /* Check whether file exists / is empty to decide on header */
    int need_header = 0;
    FILE *chk = fopen(CSV_FILENAME, "r");
    if (!chk) {
        need_header = 1;                 /* file does not exist yet */
    } else {
        fseek(chk, 0, SEEK_END);
        if (ftell(chk) == 0) need_header = 1;
        fclose(chk);
    }

    FILE *fp = fopen(CSV_FILENAME, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", CSV_FILENAME, strerror(errno));
        return -1;
    }

    if (need_header)
        fprintf(fp, "timestamp,temperature_c,humidity_pct\n");

    fprintf(fp, "%s,%.2f,%.2f\n", ts, temp_c, rh_pct);
    fclose(fp);
    return 0;
}

/* ---- Sensor read ---- */
static int read_sensor(float *temp_c, float *rh_pct)
{
    uint8_t cmd[2] = {
        (uint8_t)((MEASURE_CMD >> 8) & 0xFF),
        (uint8_t)(MEASURE_CMD & 0xFF)
    };
    uint8_t data[6];

    if (i2cWriteDevice(g_i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(MEASURE_DELAY_US);          /* 15 ms max conversion time */

    if (i2cReadDevice(g_i2c_handle, (char *)data, 6) != 6) {
        fprintf(stderr, "Error: i2cReadDevice failed: %s\n", strerror(errno));
        return -1;
    }

    /* Validate CRC-8 for temperature (bytes 0-1, CRC byte 2) */
    if (sht35_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Error: temperature CRC mismatch\n");
        return -1;
    }
    /* Validate CRC-8 for humidity (bytes 3-4, CRC byte 5) */
    if (sht35_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Error: humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t h_raw = ((uint16_t)data[3] << 8) | data[4];

    *temp_c = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *rh_pct = 100.0f * (float)h_raw / 65535.0f;

    /* Sanity range checks */
    if (*temp_c < -40.0f || *temp_c > 125.0f ||
        *rh_pct < 0.0f   || *rh_pct > 100.0f) {
        fprintf(stderr, "Warning: reading out of range (T=%.2f C, RH=%.2f %%)\n",
                *temp_c, *rh_pct);
    }

    return 0;
}

/* ---- Main ---- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d): %s\n",
                g_i2c_handle, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Sensor presence check: try a zero-length write to the address */
    if (i2cWriteDevice(g_i2c_handle, (char *)NULL, 0) != 0) {
        fprintf(stderr, "Error: SHT35 not responding at 0x%02X on bus %d\n",
                SHT35_ADDR, I2C_BUS);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("SHT35-DIS-B logger started. Logging to %s every %d s. Ctrl+C to stop.\n",
           CSV_FILENAME, SAMPLE_INTERVAL_S);

    while (g_running) {
        float temp_c, rh_pct;
        if (read_sensor(&temp_c, &rh_pct) == 0) {
            printf("%s  T=%.2f C  RH=%.2f %%\n",
                   __TIME__, temp_c, rh_pct);
            if (log_data(temp_c, rh_pct) != 0)
                fprintf(stderr, "Warning: failed to log data\n");
        } else {
            fprintf(stderr, "Warning: sensor read failed, will retry next cycle\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++)
            gpioDelay(100000);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

