#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI7021_ADDR    0x76
#define LOG_FILE       "environment.log"
#define POLL_TIMEOUT_MS 100
#define SAMPLE_PERIOD_S 5

/* Si7021 commands */
#define CMD_MEASURE_TEMP_HOLD   0xE3
#define CMD_MEASURE_HUMID_HOLD  0xE5
#define CMD_RESET               0xFE

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Write a single command byte to the sensor.
 * Returns 0 on success, -1 on error.
 */
static int si7021_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write(0x%02X) failed: %s\n",
                cmd, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read `len` bytes from the sensor into `buf`.
 * Returns 0 on success, -1 on error.
 */
static int si7021_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C read short: got %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

/*
 * Reset the Si7021 and wait for power-up (~15 ms).
 * Returns 0 on success, -1 on error.
 */
static int si7021_reset(int fd)
{
    if (si7021_write_cmd(fd, CMD_RESET) < 0)
        return -1;
    usleep(15000);
    return 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (polynomial 0x31, init 0x00, no final XOR) per Si7021 datasheet */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
/*
 * Read a measurement: send command, poll until data is available or
 * timeout, read 3 bytes (MSB, LSB, CRC), verify CRC, return raw value.
 * Returns 0 on success and fills *out_raw; returns -1 on error.
 */
static int si7021_read_raw(int fd, uint8_t cmd, uint16_t *out_raw)
{
    uint8_t buf[3];

    if (si7021_write_cmd(fd, cmd) < 0)
        return -1;

    /*
     * Si7021 hold-master measurements are ready in ~12 ms (temp) or
     * ~10 ms (humidity).  Poll every 1 ms; after ~100 ms, data is
     * either ready or the sensor is absent/unresponsive.
     */
    for (int waited = 0; waited < POLL_TIMEOUT_MS; waited++) {
        if (si7021_read_bytes(fd, buf, 3) == 0) {
            if (crc8(buf, 2) == buf[2]) {
                *out_raw = ((uint16_t)buf[0] << 8) | buf[1];
                return 0;
            }
            fprintf(stderr, "CRC mismatch on command 0x%02X (got 0x%02X)\n",
                    cmd, crc8(buf, 2));
            return -1;
        }
        usleep(1000);
    }

    fprintf(stderr, "Timeout waiting for measurement 0x%02X (sensor absent?)\n",
            cmd);
    return -1;
}

static float raw_to_celsius(uint16_t raw)
{
    return (175.72f * raw / 65536.0f) - 46.85f;
}

static float raw_to_humidity(uint16_t raw)
{
    float h = (125.0f * raw / 65536.0f) - 6.0f;
    if (h < 0.0f)   h = 0.0f;
    if (h > 100.0f) h = 100.0f;
    return h;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_open(const char *path)
{
    FILE *f = fopen(path, "a");
    if (!f) {
        fprintf(stderr, "fopen(%s) failed: %s\n", path, strerror(errno));
        return -1;
    }
    /* Write header only if file is empty */
    if (fseek(f, 0, SEEK_END) == 0) {
        long sz = ftell(f);
        if (sz == 0) {
            fprintf(f, "timestamp,temperature_C,humidity_percent\n");
            fflush(f);
        }
    }
    return 0;
}

static void log_line(FILE *f, const char *ts, float temp, float hum)
{
    if (!f) return;
    fprintf(f, "%s,%.2f,%.2f\n", ts, temp, hum);
    fflush(f);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() < 0)
        return EXIT_FAILURE;

    g_i2c_fd = i2c_open(I2C_BUS, SI7021_ADDR);
    if (g_i2c_fd < 0)
        return EXIT_FAILURE;

    if (log_open(LOG_FILE) < 0) {
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    fprintf(stderr, "Greenhouse monitor started.  Logging to %s every %d s.\n",
            LOG_FILE, SAMPLE_PERIOD_S);

    while (g_running) {
        uint16_t raw_t = 0, raw_h = 0;
        int ok_t = 0, ok_h = 0;

        if (si7021_read_raw(g_i2c_fd, CMD_MEASURE_TEMP_HOLD, &raw_t) == 0) {
            ok_t = 1;
        } else {
            fprintf(stderr, "Temperature read failed; resetting sensor.\n");
            if (si7021_reset(g_i2c_fd) < 0)
                fprintf(stderr, "Sensor reset failed.\n");
        }

        if (si7021_read_raw(g_i2c_fd, CMD_MEASURE_HUMID_HOLD, &raw_h) == 0) {
            ok_h = 1;
        } else {
            fprintf(stderr, "Humidity read failed; resetting sensor.\n");
            if (si7021_reset(g_i2c_fd) < 0)
                fprintf(stderr, "Sensor reset failed.\n");
        }

        time_t now = time(NULL);
        struct tm tm_buf;
        char ts[32];
        if (localtime_r(&now, &tm_buf) == NULL) {
            fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        } else {
            strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_buf);
        }

        if (ok_t && ok_h) {
            log_line(NULL, ts, raw_to_celsius(raw_t), raw_to_humidity(raw_h));
            fprintf(stderr, "%s  T=%.2f C  H=%.2f %%\n", ts,
                    raw_to_celsius(raw_t), raw_to_humidity(raw_h));
        } else {
            fprintf(stderr, "%s  ERROR: sensor data unavailable\n", ts);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD_S * 10 && g_running; i++)
            usleep(100000);
    }

    fprintf(stderr, "\nShutting down cleanly.\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

