        gpioTerminate();
        return 1;
    }

    if (init_lps33hw() != 0) {
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    while (running) {
        float pressure, temperature;
        if (read_pressure(&pressure) == 0 && read_temperature(&temperature) == 0) {
            log_data(pressure, temperature);
        } else {
            time_t now = time(NULL);
            struct tm tm_info;
            char timestamp[20];
            localtime_r(&now, &tm_info);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
            fprintf(stderr, "%s, Error: Failed to read sensor data.\n", timestamp);
            fprintf(log_file, "%s, Error: Failed to read sensor data.\n", timestamp);
            fflush(log_file);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

