#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x49
#define LED_GPIO       17
#define BUFFER_SIZE    10
#define TEMP_THRESHOLD 28.0f
#define SAMPLE_PERIOD  1.0

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

static float read_temperature(int handle) {
    char buf[2];
    int rc = i2cReadDevice(handle, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read failed (rc=%d)\n", rc);
        return -1000.0f;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    return (float)raw * 0.0625f;
}

static void update_buffer(float temp, float buffer[], int *idx, int size) {
    buffer[*idx] = temp;
    *idx = (*idx + 1) % size;
}

static float calculate_average(const float buffer[], int size) {
    float sum = 0.0f;
    for (int i = 0; i < size; i++) sum += buffer[i];
    return sum / (float)size;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "I2C open failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temp_buffer[BUFFER_SIZE];
    int buffer_index = 0;

    while (g_running) {
        float temp = read_temperature(g_i2c_handle);
        if (temp < -999.0f) {
            fprintf(stderr, "Skipping iteration due to read failure\n");
        } else {
            update_buffer(temp, temp_buffer, &buffer_index, BUFFER_SIZE);
            float avg = calculate_average(temp_buffer, BUFFER_SIZE);
            int led_state = (avg > TEMP_THRESHOLD) ? 1 : 0;
            gpioWrite(LED_GPIO, led_state);
            printf("Temp: %.2f C, Avg: %.2f C, LED: %s\n",
                   temp, avg, led_state ? "ON" : "OFF");
        }
        time_sleep(SAMPLE_PERIOD);
    }

    cleanup();
    return EXIT_SUCCESS;
}

