#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SCD30_ADDR 0x50
#define LOG_FILE "air_quality.log"
#define CO2_LOW_THRESHOLD 800
#define CO2_HIGH_THRESHOLD 1200
#define HUMIDITY_MAX 100.0f
#define TEMPERATURE_MAX 50.0f
#define SAMPLE_INTERVAL_SEC 5
#define MAX_RETRIES 3
#define MEAS_DELAY_US 2000000

#define CMD_START_PERIODIC_MEASUREMENT 0x0010
#define CMD_STOP_PERIODIC_MEASUREMENT 0x0104
#define CMD_GET_DATA_READY 0x0202
#define CMD_READ_MEASUREMENT 0x0300

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int scd30_write_command(uint16_t cmd) {
    char buf[2] = { (char)(cmd >> 8), (char)(cmd & 0xFF) };
    return i2cWriteDevice(i2c_handle, buf, 2);
}

static int scd30_write_command_data(uint16_t cmd, const char *data, uint16_t len) {
    char buf[2 + 256];
    if (len > 254) len = 254;
    buf[0] = (char)(cmd >> 8);
    buf[1] = (char)(cmd & 0xFF);
    memcpy(buf + 2, data, len);
    int total = 2 + len;
    return i2cWriteDevice(i2c_handle, buf, total);
}

static int scd30_read_data(char *data, uint16_t len) {
    return i2cReadDevice(i2c_handle, data, len);
}

static int scd30_read_data_ready(int *ready) {
    char data[3];
    if (scd30_write_command(CMD_GET_DATA_READY) != 0) return -1;
    gpioDelay(2000);
    if (scd30_read_data(data, 3) != 3) return -1;
    uint8_t crc = 0xFF;
    crc ^= (uint8_t)data[0];
    for (int i = 1; i < 2; i++) {
        crc += (uint8_t)data[i];
    }
    crc = (crc & 0xFF) + ((crc >> 8) & 0xFF);
    crc ^= (uint8_t)data[2];
    for (int i = 3; i < 4; i++) {
        crc += (uint8_t)data[i];
    }
    crc = (crc & 0xFF) + ((crc >> 8) & 0xFF);
    crc ^= (uint8_t)data[4];
    for (int i = 5; i < 6; i++) {
        crc += (uint8_t)data[i];
    }
    if (crc != (uint8_t)data[6]) return -1;
    *ready = ((data[4] << 8) | data[5]) & 0x07FF;
    return 0;
}

static int scd30_read_measurement(float *co2, float *temperature, float *humidity) {
    char data[18];
    if (scd30_write_command(CMD_READ_MEASUREMENT) != 0) return -1;
    gpioDelay(MEAS_DELAY_US);
    if (scd30_read_data(data, 18) != 18) return -1;
    uint8_t crc = 0xFF;
    crc ^= (uint8_t)data[0];
    for (int i = 1; i < 2; i++) {
        crc += (uint8_t)data[i];
    }
    crc = (crc & 0xFF) + ((crc >> 8) & 0xFF);
    crc ^= (uint8_t)data[2];
    for (int i = 3; i < 4; i++) {
        crc += (uint8_t)data[i];
    }
    crc = (crc & 0xFF) + ((crc >> 8) & 0xFF);
    crc ^= (uint8_t)data[4];
    for (int i = 5; i < 6; i++) {
        crc += (uint8_t)data[i];
    }
    crc = (crc & 0xFF) + ((crc >> 8) & 0xFF);
    crc ^= (uint8_t)data[6];
    for (int i = 7; i < 8; i++) {
        crc += (uint8_t)data[i];
    }
    crc = (crc & 0xFF) + ((crc >> 8) & 0xFF);
    crc ^= (uint8_t)data[8];
    for (int i = 9; i < 10; i++) {
        crc += (uint8_t)data[i];
    }
    crc = (crc & 0xFF) + ((crc >> 8) & 0xFF);
    crc ^= (uint8_t)data[10];
    for (int i = 11; i < 12; i++) {
        crc += (uint8_t)data[i];
    }
    crc = (crc & 0xFF) + ((crc >> 8) & 0xFF);
    crc ^= (uint8_t)data[12];
    for (int i = 13; i < 14; i++) {
        crc += (uint8_t)data[i];
    }
    crc = (crc & 0xFF) + ((crc >> 8) & 0xFF);
    crc ^= (uint8_t)data[14];
    for (int i = 15; i < 16; i++) {
        crc += (uint8_t)data[i];
    }
    crc = (crc & 0xFF) + ((crc >> 8) & 0xFF);
    crc ^= (uint8_t)data[16];
    for (int i = 17; i < 18; i++) {
        crc += (uint8_t)data[i];
    }
    if (crc != (uint8_t)data[17]) return -1;
    *co2 = ((data[10] << 8) | data[11]) / 10.0f;
    *temperature = ((data[12] << 8) | data[13]) / 100.0f;
    *humidity = ((data[14] << 8) | data[15]) / 100.0f;
    return 0;
}

static void control_ventilation(float co2) {
    if (co2 < CO2_LOW_THRESHOLD) {
        printf("CO2: %5.1f ppm - Ventilation: OFF\n", co2);
    } else if (co2 < CO2_HIGH_THRESHOLD) {
        printf("CO2: %5.1f ppm - Ventilation: LOW\n", co2);
    } else {
        printf("CO2: %5.1f ppm - Ventilation: HIGH\n", co2);
    }
}

static void log_data(float co2, float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];
    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, co2, temperature, humidity);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        scd30_write_command(CMD_STOP_PERIODIC_MEASUREMENT);
        gpioDelay(2000000);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, SCD30_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    if (scd30_write_command(CMD_START_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Error starting periodic measurement: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    printf("SCD30 periodic measurement started. Sampling every %d seconds.\n", SAMPLE_INTERVAL_SEC);
    while (running) {
        int ready = 0;
        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (scd30_read_data_ready(&ready) == 0 && ready) break;
            gpioDelay(100000);
        }
        if (!running) break;
        if (!ready) {
            fprintf(stderr, "Data not ready after %d attempts.\n", MAX_RETRIES);
            continue;
        }
        float co2, temperature, humidity;
        int read_ok = 1;
        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (scd30_read_measurement(&co2, &temperature, &humidity) == 0) break;
            gpioDelay(100000);
        }
        if (!running) break;
        if (read_ok) {
            if (co2 >= 0.0f && co2 <= 10000.0f && temperature >= -40.0f && temperature <= 85.0f && humidity >= 0.0f && humidity <= HUMIDITY_MAX) {
                log_data(co2, temperature, humidity);
                control_ventilation(co2);
            } else {
                fprintf(stderr, "Out of range: CO2=%.2f T=%.2f H=%.2f\n", co2, temperature, humidity);
            }
        } else {
            fprintf(stderr, "Measurement read failed after %d attempts.\n", MAX_RETRIES);
        }
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            gpioDelay(1000000);
        }
    }
    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

