/*
 * SDP32 differential pressure sensor reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   SDP32 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP32 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP32 VDD  -> 3.3 V
 *   SDP32 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp32_reader sdp32_reader.c
 * Run:    ./sdp32_reader [sampling_interval_ms]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SDP32_ADDR     0x24
#define READ_LEN       9
#define CRC8_POLY      0x31
#define CRC8_INIT      0xFF

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                         */
/* ------------------------------------------------------------------ */

static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80) {
                crc = (uint8_t)((crc << 1) ^ CRC8_POLY);
            } else {
                crc = (uint8_t)(crc << 1);
            }
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int init_i2c(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SDP32_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", g_i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void close_i2c(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/*
 * Read one measurement frame from the SDP32.
 * Returns 0 on success, -1 on I2C error, -2 on sensor-absent (no ACK).
 */
static int read_sdp32(int16_t *pressure, int16_t *temperature,
                      int16_t *scale_factor)
{
    uint8_t buf[READ_LEN];

    int bytes_read = i2cReadDevice(g_i2c_handle, (char *)buf, READ_LEN);
    if (bytes_read != READ_LEN) {
        if (bytes_read < 0) {
            fprintf(stderr, "Error: i2cReadDevice failed (pigpio error %d).\n",
                    bytes_read);
        } else {
            fprintf(stderr, "Error: short read (%d of %d bytes).\n",
                    bytes_read, READ_LEN);
        }
        return -1;
    }

    /* Verify CRC for each 3-byte word */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: pressure CRC mismatch (calc=0x%02X, got=0x%02X).\n",
                crc8(&buf[0], 2), buf[2]);
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: temperature CRC mismatch (calc=0x%02X, got=0x%02X).\n",
                crc8(&buf[3], 2), buf[5]);
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "Error: scale-factor CRC mismatch (calc=0x%02X, got=0x%02X).\n",
                crrc8(&buf[6], 2), buf[8]);
        return -1;
    }

    *pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (int16_t)((buf[3] << 8) | buf[4]);
    *scale_factor = (int16_t)((buf[6] << 8) | buf[7]);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(int argc, char *argv[])
{
    int interval_ms = 1000;

    if (argc > 1) {
        interval_ms = atoi(argv[1]);
        if (interval_ms <= 0) {
            fprintf(stderr, "Warning: invalid interval '%s'; using default 1000 ms.\n",
                    argv[1]);
            interval_ms = 1000;
        }
    }

    install_signal_handlers();

    if (init_i2c() != 0) {
        return EXIT_FAILURE;
    }

    printf("SDP32 reader started. Sampling every %d ms. Press Ctrl+C to exit.\n",
           interval_ms);

    while (g_running) {
        int16_t pressure, temperature, scale_factor;

        if (read_sdp32(&pressure, &temperature, &scale_factor) == 0) {
            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];

            if (localtime_r(&now, &tm_info) != NULL) {
                strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
            } else {
                snprintf(ts, sizeof(ts), "unknown-time");
            }

            printf("[%s] Pressure: %+d Pa, Temperature: %+d C, Scale: %d\n",
                   ts, pressure, temperature, scale_factor);
            fflush(stdout);
        } else {
            /*
             * I2C error: check whether the sensor is present by
             * attempting a zero-length read.  If that also fails, the
             * bus is dead or the sensor is absent.
             */
            int probe = i2cReadDevice(g_i2c_handle, NULL, 0);
            if (probe < 0) {
                fprintf(stderr, "Error: sensor not responding on I2C bus %d addr 0x%02X.\n",
                        I2C_BUS, SDP32_ADDR);
                close_i2c();
                return EXIT_FAILURE;
            }
            fprintf(stderr, "Error: I2C read failed; will retry next cycle.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < interval_ms / 100 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nShutting down cleanly.\n");
    close_i2c();
    return EXIT_SUCCESS;
}

