#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define HDC1000_ADDR   0x40
#define TEMP_REG       0x00
#define HUMID_REG      0x01
#define CONV_REG       0x00
#define CONV_CMD       0x66   /* 14-bit temp + 14-bit humidity, no clock stretching */
#define CONV_TIME_MS   20    /* datasheet: max ~12.5 ms for 14-bit T+RH */
#define POLL_MS        5000  /* 5-second sampling interval */

static volatile sig_atomic_t g_running = 1;
static int g_fd = -1;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte)
{
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "i2c_write_byte(0x%02X) failed: %s\n", byte, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "i2c_read_bytes failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "i2c_read_bytes short read: got %zd, expected %zu\n", n, len);
        return -1;
    }
    return 0;
}

static int hdc1000_trigger_and_read(int fd, float *temp_c, float *rh_pct)
{
    /* Point to conversion register and issue measurement command */
    if (i2c_write_byte(fd, CONV_CMD) < 0)
        return -1;

    /* Wait for conversion to complete (datasheet: ~12.5 ms for 14-bit T+RH) */
    usleep(CONV_TIME_MS * 1000);

    /* Read 4 bytes: 2 for temperature, 2 for humidity (each 16-bit, 14-bit data) */
    uint8_t buf[4];
    if (i2c_read_bytes(fd, buf, sizeof(buf)) < 0)
        return -1;

    uint16_t raw_t  = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t raw_rh = ((uint16_t)buf[2] << 8) | buf[3];

    *temp_c = ((float)raw_t / 65536.0f) * 165.0f - 40.0f;
    *rh_pct = ((float)raw_rh / 65536.0f) * 100.0f;

    /* Sanity-check ranges */
    if (*temp_c < -40.0f || *temp_c > 125.0f || *rh_pct < 0.0f || *rh_pct > 100.0f) {
        fprintf(stderr, "HDC1000 reading out of range: T=%.2f C, RH=%.2f %%\n",
                *temp_c, *rh_pct);
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_fd = open(I2C_BUS, O_RDWR);
    if (g_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                HDC1000_ADDR, strerror(errno));
        close(g_fd);
        g_fd = -1;
        return EXIT_FAILURE;
    }

    printf("HDC1000 sensor reader started on %s (addr 0x%02X). Press Ctrl+C to exit.\n",
           I2C_BUS, HDC1000_ADDR);

    while (g_running) {
        float temp_c, rh_pct;

        if (hdc1000_trigger_and_read(g_fd, &temp_c, &rh_pct) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp_c, rh_pct);
        } else {
            fprintf(stderr, "Failed to read HDC1000 data.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < POLL_MS / 100 && g_running; i++)
            usleep(100 * 1000);
    }

    if (g_fd >= 0) {
        close(g_fd);
        g_fd = -1;
    }
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

