/*
 * Si7051 Temperature Sensor Reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   Si7051 SDA -> GPIO2 (BCM 2, physical pin 3)
 *   Si7051 SCL -> GPIO3 (BCM 3, physical pin 5)
 *   Si7051 VDD -> 3.3 V
 *   Si7051 GND -> GND
 *
 * I2C bus 1 is enabled by default on the Pi 4.  The Si7051 uses a 4-wire
 * SPI-compatible interface over I2C, so the sensor appears as a standard
 * I2C device at address 0x49.
 *
 * Build:  gcc -O2 -Wall -Wextra -o si7051_reader si7051_reader.c -lpigpio -lrt
 * Run:    sudo ./si7051_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7051_ADDR    0x49

/* Si7051 command codes (upper nibble = 0x2E, lower nibble = command) */
#define CMD_TEMP_HOLD  0x2E00  /* Hold master mode, temperature result */
#define CMD_RESET      0x3E00  /* Soft reset / factory reset */

#define SAMPLE_PERIOD_S 5
#define MAX_RETRIES     3
#define RETRY_DELAY_US  100000  /* 100 ms between retries */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("warning: sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("warning: sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

/*
 * Write a 16-bit command to the Si7051.
 * Returns 0 on success, -1 on failure.
 */
static int si7051_write_cmd(int handle, uint16_t cmd)
{
    char buf[2];
    buf[0] = (char)(cmd >> 8);
    buf[1] = (char)(cmd & 0xFF);

    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "[ERROR] I2C write failed (cmd 0x%04X)\n", cmd);
        return -1;
    }
    return 0;
}

/*
 * Read `len` bytes from the Si7051.
 * Returns 0 on success, -1 on failure.
 */
static int si7051_read_data(int handle, char *buf, int len)
{
    if (i2cReadDevice(handle, buf, len) != len) {
        fprintf(stderr, "[ERROR] I2C read failed (expected %d bytes)\n", len);
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit big-endian value from the Si7051.
 * Returns 0 on success, -1 on failure.
 */
static int si7051_read_u16(int handle, uint16_t *out)
{
    char buf[2];
    if (si7051_read_data(handle, buf, 2) != 0)
        return -1;
    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/*
 * Read a signed 16-bit big-endian value from the Si7051.
 * Returns 0 on success, -1 on failure.
 */
static int si7051_read_s16(int handle, int16_t *out)
{
    char buf[2];
    if (si7051_read_data(handle, buf, 2) != 0)
        return -1;
    *out = (int16_t)(((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1]);
    return 0;
}

/*
 * Read the temperature in degrees Celsius from the Si7051.
 * Returns 0 on success, -1 on failure.
 */
static int si7051_read_temperature(int handle, float *temperature)
{
    uint16_t raw;

    if (si7051_read_u16(handle, &raw) != 0)
        return -1;

    /*
     * Si7051 temperature formula (hold master mode):
     *   T(°C) = (raw / 65536.0) * 175.72 - 46.85
     *
     * The raw value is a 16-bit signed integer representing two's
     * complement fractions in [0, 1).  The Si7051 datasheet states
     * that the resolution is 1/128 °C, so the LSB is worth 1/128 °C.
     */
    *temperature = ((float)raw / 65536.0f) * 175.72f - 46.85f;
    return 0;
}

/*
 * Reset the Si7051 and wait for it to stabilise.
 * Returns 0 on success, -1 on failure.
 */
static int si7051_reset(int handle)
{
    if (si7051_write_cmd(handle, CMD_RESET) != 0)
        return -1;

    /*
     * The Si7051 requires between 15 ms (after soft reset) and
     * 100 ms to complete a reset and be ready for further commands.
     */
    gpioDelay(100000); /* 100 ms */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    int rc = EXIT_SUCCESS;

    /* --- Initialise pigpio ------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus 1 at the Si7051 address ------------------------ */
    g_i2c_handle = i2cOpen(I2C_BUS, SI7051_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, SI7051_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Verify sensor presence with a reset command ---------------- */
    if (si7051_reset(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] Si7051 not responding at address 0x%02X\n",
                SI7051_ADDR);
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    /* --- Install signal handlers for graceful shutdown -------------- */
    install_signal_handlers();

    printf("Si7051 temperature reader started (bus %d, addr 0x%02X).\n",
           I2C_BUS, SI7051_ADDR);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main sampling loop ----------------------------------------- */
    while (g_running) {
        float temperature;
        int retries = 0;
        bool success = false;

        /*
         * Retry loop: attempt up to MAX_RETRIES times to read the
         * temperature register.  A short back-off between retries
         * helps avoid hammering the bus if the sensor is momentarily
         * unresponsive.
         */
        while (retries < MAX_RETRIES && g_running) {
            if (si7051_read_temperature(g_i2c_handle, &temperature) == 0) {
                success = true;
                break;
            }
            retries++;
            if (retries < MAX_RETRIES)
                gpioDelay(RETRY_DELAY_US);
        }

        if (success) {
            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];

            localtime_r(&now, &tm_info);
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

            printf("[%s] Temperature: %.2f °C\n", ts, temperature);
            fflush(stdout);
        } else {
            fprintf(stderr, "[ERROR] Temperature read failed after %d retries.\n",
                    MAX_RETRIES);
        }

        /*
         * Sleep in 100 ms increments so that SIGINT/SIGTERM is
         * noticed promptly.
         */
        for (int i = 0; i < SAMPLE_PERIOD_S * 10 && g_running; i++)
            gpioDelay(100000);
    }

cleanup:
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    if (rc == EXIT_SUCCESS)
        printf("\nExiting gracefully.\n");

    return rc;
}

