static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

static int read_sensor_data(float *temperature, float *pressure)
{
    char cmd = MEASURE_CMD;
    char buf[6];
    int16_t raw_t, raw_p;

    if (i2cWriteDevice(g_i2c_handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to write measurement command to I2C device.\n");
        return -1;
    }

    gpioDelay(MEASURE_DELAY);

    if (i2cReadDevice(g_i2c_handle, buf, 6) != 6) {
        fprintf(stderr, "Error: failed to read 6 bytes from I2C device.\n");
        return -1;
    }

    /* Check for sensor-absent / bus-error: all bytes equal default 0x00 */
    if ((buf[0] == 0x00 && buf[1] == 0x00 && buf[2] == 0x00 &&
         buf[3] == 0x00 && buf[4] == 0x00 && buf[5] == 0x00)) {
        fprintf(stderr, "Error: sensor not responding (all bytes 0x00).\n");
        return -1;
    }

    raw_t = (int16_t)((buf[0] << 8) | buf[1]);
    raw_p = (int16_t)((buf[2] << 8) | buf[3]);

    *temperature = (float)raw_t / 100.0f;
    *pressure    = (float)raw_p / 100.0f;

    return 0;
}

static void log_data(float temperature, float pressure)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n",
           timestamp, temperature, pressure);
    fflush(stdout);
}

