    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C device at bus %d, addr 0x%02X (code %d).\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (g_running) {
        if (read_sensor_data(&temperature, &pressure) == 0) {
            log_data(temperature, pressure);
        } else {
            fprintf(stderr, "Warning: sensor read failed, continuing.\n");
        }
        gpioDelay(LOOP_DELAY);
    }

    cleanup();
    return EXIT_SUCCESS;
}

