#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

#define I2C_BUS 1
#define HIH6130_ADDR 0x28
#define LOG_FILE "environmental_data.log"
#define LOG_FILE_SIZE_LIMIT (1024 * 1024)
#define SAMPLE_INTERVAL_SEC 5
#define MEASUREMENT_DELAY_US 40000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hih6130(int handle, float *temperature, float *humidity) {
    char buf[4];
    int result;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        result = i2cWriteByte(handle, 0x00);
        if (result < 0) {
            fprintf(stderr, "Error triggering measurement (attempt %d): %s\n", attempt + 1, pigpio_error(result));
            gpioDelay(100000);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        result = i2cReadDevice(handle, buf, 4);
        if (result != 4) {
            fprintf(stderr, "Error reading data (attempt %d): %s\n", attempt + 1, result < 0 ? pigpio_error(result) : "short read");
            continue;
        }

        uint16_t status = (uint16_t)((buf[0] << 8) | buf[1]);
        if ((status & 0x03) != 0x00) {
            fprintf(stderr, "Sensor status error: 0x%04X\n", status);
            return -1;
        }

        uint16_t raw_humidity = (uint16_t)((buf[2] << 8) | buf[3]);
        uint16_t raw_temperature = (uint16_t)((buf[0] << 8) | buf[1]);

        *humidity = (float)raw_humidity / 16383.0f * 100.0f;
        *temperature = (float)raw_temperature / 16383.0f * 165.0f - 40.0f;

        return 0;
    }

    return -1;
}

static int log_data(float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    struct stat st;
    if (fstat(fileno(fp), &st) == 0) {
        if (st.st_size > LOG_FILE_SIZE_LIMIT) {
            if (ftruncate(fileno(fp), 0) != 0) {
                perror("Error truncating log file");
                fclose(fp);
                return -1;
            }
        }
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("Error getting local time");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", pigpio_error(i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error setting SIGINT handler");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    float temperature, humidity;

    while (running) {
        if (read_hih6130(i2c_handle, &temperature, &humidity) == 0) {
            if (log_data(temperature, humidity) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

