/*
 * MLX90824 SENT Brake Pressure Sensor Reader
 * Board:  Raspberry Pi 3 Model B+
 * Sensor: Melexis MLX90824 (SENT protocol)
 * Wiring: SENT bus -> GPIO4 (BCM), 3.3 V logic, common ground
 *
 * Build:  gcc -O2 -Wall -o brake_pressure brake_pressure.c -lpigpio -lrt
 * Run:    sudo ./brake_pressure
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENT_GPIO          4
#define LOG_FILE           "pressure_log.txt"
#define SENT_TICK_US       3.0f   /* 3 µs nominal tick time */
#define SYNC_TICKS         56     /* Sync pulse = 176 µs */
#define MIN_NIBBLE_TICKS   12     /* 36 µs low, 3 µs high */
#define MAX_NIBBLE_TICKS   271    /* 813 µs low, 3 µs high */
#define MAX_PULSE_COUNT    64     /* 128 ticks × 2 edges = 256 µs window */
#define READ_TIMEOUT_US    200000 /* 200 ms max wait for a frame */
#define POLL_DELAY_US      1000   /* 1 ms between edge polls */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Convert SENT pulse width (ticks × tick_us) to pressure (Pa).        */
/* MLX90824: 12 ticks ≈ 0 Pa, 271 ticks ≈ 15000 Pa (linear, datasheet). */
static float ticks_to_pressure(int ticks)
{
    const float ticks_min = 12.0f;
    const float ticks_max = 271.0f;
    const float p_max     = 15000.0f;
    return (ticks - ticks_min) * (p_max - 0.0f) / (ticks_max - ticks_min) + 0.0f;
}

/* ------------------------------------------------------------------ */
/* Read one SENT frame from the bus.                                   */
/* Returns 0 on success, -1 on timeout, -2 on checksum error.          */
static int read_sent_frame(int gpio, float *pressure_out)
{
    uint32_t edge_times[MAX_PULSE_COUNT];
    int      edge_count = 0;
    uint32_t start_tick = gpioTick();

    /* ---- Phase 1: wait for falling edge (sync pulse) ---- */
    while (g_running) {
        if ((gpioTick() - start_tick) > READ_TIMEOUT_US) {
            fprintf(stderr, "Error: SENT sync pulse timeout (no falling edge within %d µs)\n",
                    READ_TIMEOUT_US);
            return -1;
        }
        if (gpioRead(gpio) == 0) {
            edge_times[0] = gpioTick();
            edge_count = 1;
            break;
        }
        gpioDelay(POLL_DELAY_US);
    }
    if (!g_running) return -1;

    /* ---- Phase 2: capture rising edges ---- */
    while (g_running) {
        if (edge_count >= MAX_PULSE_COUNT) {
            fprintf(stderr, "Error: SENT frame exceeded %d pulse limit\n", MAX_PULSE_COUNT);
            return -1;
        }
        if ((gpioTick() - start_tick) > READ_TIMEOUT_US) {
            fprintf(stderr, "Error: SENT frame timeout (%d edges captured)\n", edge_count);
            return -1;
        }
        if (gpioRead(gpio) == 1) {
            edge_times[edge_count++] = gpioTick();
        }
        gpioDelay(POLL_DELAY_US);
    }
    if (!g_running) return -1;

    /* ---- Phase 3: validate nibbles ---- */
    if (edge_count < 5) {
        fprintf(stderr, "Error: SENT frame too short (%d edges)\n", edge_count);
        return -1;
    }

    /* Nibble 0: status (always 0x0F = idle / no fault) */
    uint8_t status = 0x0F;
    /* Nibble 1: data (MSB) */
    uint8_t data_msb = (edge_times[1] - edge_times[0]) / (uint32_t)SENT_TICK_US;
    if (data_msb < MIN_NIBBLE_TICKS || data_msb > MAX_NIBBLE_TICKS) {
        fprintf(stderr, "Error: SENT data MSB out of range (%u ticks)\n", data_msb);
        return -2;
    }
    /* Nibble 2: data (LSB) */
    uint8_t data_lsb = (edge_times[2] - edge_times[1]) / (uint32_t)SENT_TICK_US;
    if (data_lsb < MIN_NIBBLE_TICKS || data_lsb > MAX_NIBBLE_TICKS) {
        fprintf(stderr, "Error: SENT data LSB out of range (%u ticks)\n", data_lsb);
        return -2;
    }
    /* Nibble 3: data (LSB of LSB) */
    uint8_t data_data = (edge_times[3] - edge_times[2]) / (uint32_t)SENT_TICK_US;
    if (data_data < MIN_NIBBLE_TICKS || data_data > MAX_NIBBLE_TICKS) {
        fprintf(stderr, "Error: SENT data data nibble out of range (%u ticks)\n", data_data);
        return -2;
    }
    /* Nibble 4: checksum */
    uint8_t checksum = (edge_times[4] - edge_times[3]) / (uint32_t)SENT_TICK_US;
    if (checksum < MIN_NIBBLE_TICKS || checksum > MAX_NIBBLE_TICKS) {
        fprintf(stderr, "Error: SENT checksum nibble out of range (%u ticks)\n", checksum);
        return -2;
    }

    /* Assemble 12-bit pressure value (big-endian) */
    uint16_t raw = ((uint16_t)data_msb << 8) | ((uint16_t)data_lsb << 4) | (uint16_t)data_data;
    *pressure_out = ticks_to_pressure(raw);

    /* ---- Phase 4: validate checksum ---- */
    uint8_t calc_checksum = (uint8_t)(status + data_msb + data_lsb + data_data);
    if (calc_checksum != checksum) {
        fprintf(stderr, "Error: SENT checksum mismatch (calc=0x%X, recv=0x%X)\n",
                calc_checksum, checksum);
        return -2;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static void log_pressure(float pressure)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Pressure: %.2f Pa\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, pressure);
    } else {
        fprintf(fp, "Pressure: %.2f Pa\n", pressure);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO ---- */
    if (gpioSetMode(SENT_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", SENT_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioSetPullUpDown(SENT_GPIO, PI_PUD_UP); /* SENT bus idles high */

    printf("MLX90824 SENT Brake Pressure Reader\n");
    printf("GPIO %d, logging to %s\n", SENT_GPIO, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        float pressure = 0.0f;
        int rc = read_sent_frame(SENT_GPIO, &pressure);

        if (rc == 0) {
            log_pressure(pressure);
            printf("Pressure: %.2f Pa\n", pressure);
        } else if (rc == -1) {
            fprintf(stderr, "Warning: SENT read timeout (sensor absent or bus error)\n");
        } else {
            fprintf(stderr, "Warning: SENT checksum error\n");
        }

        /* 100 ms cadence */
        gpioDelay(100000);
    }

    /* ---- Cleanup ---- */
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
