#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TMP117_REG_TEMP 0x00
#define TMP117_REG_CONFIG 0x01
#define TMP117_REG_DEVICE_ID 0x0F
#define TMP117_DEVICE_ID 0x17
#define LOG_FILE "greenhouse_temps.dat"
#define SAMPLE_INTERVAL_SEC 60

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_temperature(float *temperature) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(g_i2c_handle, TMP117_REG_TEMP, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -1;
    }

    int16_t raw_temp = (int16_t)((buf[1] << 8) | buf[0]);
    *temperature = (float)raw_temp / 100.0f;
    return 0;
}

static int log_temperature(float temperature) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error getting time\n");
        return -1;
    }

    struct tm *tstruct = localtime(&now);
    if (tstruct == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tstruct);

    float data_to_write = temperature;
    char *data_ptr = (char *)&data_to_write;

    size_t bytes_written = fwrite(data_ptr, sizeof(float), 1, g_log_file);
    if (bytes_written != 1) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }

    fflush(g_log_file);
    return 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int device_id = i2cReadByteData(g_i2c_handle, TMP117_REG_DEVICE_ID);
    if (device_id != TMP117_DEVICE_ID) {
        fprintf(stderr, "Error: Invalid device ID: 0x%02X (expected 0x%02X)\n",
                device_id & 0xFF, TMP117_DEVICE_ID);
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "ab");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGTERM handler\n");
    }

    printf("Greenhouse temperature monitoring started. Logging to %s every %d seconds.\n",
           LOG_FILE, SAMPLE_INTERVAL_SEC);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature;

        if (read_temperature(&temperature) == 0) {
            printf("Temperature: %.2f °C\n", temperature);
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Error logging temperature.\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature. Retrying in %d seconds.\n",
                    SAMPLE_INTERVAL_SEC);
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

