#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x76
#define MEASURE_TEMP_HUMIDITY 0x2C
#define LOG_FILE "environmental_data.txt"
#define SAMPLE_INTERVAL_US 5000000  /* 5 seconds */
#define CONVERSION_DELAY_US 10000   /* 10 ms (datasheet: typ 8.5 ms) */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* CRC-8 as used by Sensirion SHT4x: poly 0x31, init 0xFF */
static uint8_t sht40_crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_sht40(int handle, float *temperature, float *humidity) {
    uint8_t cmd = MEASURE_TEMP_HUMIDITY;
    uint8_t data[6];

    if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to write measurement command to SHT40.\n");
        return -1;
    }

    gpioDelay(CONVERSION_DELAY_US);

    if (i2cReadDevice(handle, (char *)data, 6) != 6) {
        fprintf(stderr, "Error: failed to read 6 bytes from SHT40.\n");
        return -1;
    }

    if (sht40_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Error: temperature CRC mismatch.\n");
        return -1;
    }
    if (sht40_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Error: humidity CRC mismatch.\n");
        return -1;
    }

    uint16_t temp_raw = (uint16_t)((data[0] << 8) | data[1]);
    uint16_t hum_raw  = (uint16_t)((data[3] << 8) | data[4]);

    *temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    *humidity    = 100.0f * (float)hum_raw  / 65535.0f;

    return 0;
}

static int log_data(FILE *fp, float temperature, float humidity) {
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error: time() failed.\n");
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r() failed.\n");
        return -1;
    }

