#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SHTC3_ADDR     0x44
#define LOG_FILE       "shtc3_environment.log"
#define SAMPLE_PERIOD  5.0
#define CONV_DELAY     0.0124

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Sensirion CRC-8: polynomial 0x31, init 0xFF */
static uint8_t shtc3_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int shtc3_soft_reset(int handle)
{
    uint8_t cmd = 0x94;
    if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "[ERROR] Soft reset write failed\n");
        return -1;
    }
    time_sleep(0.002);
    return 0;
}

static int shtc3_measure(int handle, uint8_t cmd, uint8_t *buf, size_t len)
{
    if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "[ERROR] Measurement command 0x%02X failed\n", cmd);
        return -1;
    }
    time_sleep(CONV_DELAY);
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) {
        fprintf(stderr, "[ERROR] Measurement read failed\n");
        return -1;
    }
    return 0;
}

static int shtc3_read(int handle, float *temp, float *hum)
{
    uint8_t buf[6];
    uint8_t cmd = 0x24; /* high-repeatability, clock-stretching disabled */

    if (shtc3_measure(handle, cmd, buf, sizeof(buf)) != 0)
        return -1;

    if (shtc3_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -1;
    }
    if (shtc3_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[ERROR] Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = (uint16_t)((buf[0] << 8) | buf[1]);
    uint16_t h_raw = (uint16_t)((buf[3] << 8) | buf[4]);

    *temp = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *hum  = 100.0f * (float)h_raw / 65535.0f;

    if (*temp < -40.0f || *temp > 125.0f || *hum < 0.0f || *hum > 100.0f) {
        fprintf(stderr, "[ERROR] Out-of-range: T=%.2f C, H=%.2f %%\n", *temp, *hum);
        return -1;
    }
    return 0;
}

static void log_data(float temp, float hum)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "[ERROR] Cannot open %s: ", LOG_FILE);
        perror("");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, temp, hum);
    fclose(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SHTC3_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (shtc3_soft_reset(g_i2c_handle) != 0) {
        fprintf(stderr, "[ERROR] Soft reset failed; continuing anyway\n");
    }

    while (g_running) {
        float temp, hum;
        if (shtc3_read(g_i2c_handle, &temp, &hum) == 0) {
            log_data(temp, hum);
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, hum);
        }
        time_sleep(SAMPLE_PERIOD);
    }

    /* Cleanup */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

