#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* Si7202 I2C address (7-bit) */
#define SI7202_ADDR 0x36

/* Si7202 register addresses */
#define SI7202_REG_DEVICE_ID 0x00
#define SI7202_REG_TEMP_LSB 0x01
#define SI7202_REG_TEMP_MSB 0x02
#define SI7202_REG_SPEED_LSB 0x03
#define SI7202_REG_SPEED_MSB 0x04
#define SI7202_REG_CONFIG 0x05

/* Expected device ID for Si7202 */
#define SI7202_DEVICE_ID 0x02

/* I2C bus on Raspberry Pi 3 Model B+ */
#define I2C_BUS 1

/* Sampling interval in microseconds (1 second) */
#define SAMPLE_INTERVAL_US 1000000

/* Global variables for signal handling and cleanup */
static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

/* Structure to hold sensor data */
typedef struct {
    double speed;
    double temperature;
} sensor_data_t;

/* Signal handler for Ctrl+C */
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

/* Function to initialize the I2C interface */
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, SI7202_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

/* Function to read a 16-bit register from the Si7202 */
int read_register16(int handle, uint8_t reg, int16_t *value) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (int16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

/* Function to read sensor data from the Si7202 */
int read_sensor_data(sensor_data_t *data) {
    int16_t temp_lsb, temp_msb, speed_lsb, speed_msb;

    if (read_register16(i2c_handle, SI7202_REG_TEMP_LSB, &temp_lsb) != 0) {
        return -1;
    }
    if (read_register16(i2c_handle, SI7202_REG_TEMP_MSB, &temp_msb) != 0) {
        return -1;
    }
    if (read_register16(i2c_handle, SI7202_REG_SPEED_LSB, &speed_lsb) != 0) {
        return -1;
    }
    if (read_register16(i2c_handle, SI7202_REG_SPEED_MSB, &speed_msb) != 0) {
        return -1;
    }

    /* Convert raw temperature data to Celsius */
    int16_t temp_raw = (temp_msb << 8) | temp_lsb;
    data->temperature = (double)temp_raw / 100.0;

    /* Convert raw speed data to RPM */
    int16_t speed_raw = (speed_msb << 8) | speed_lsb;
    data->speed = (double)speed_raw / 1000.0;

    return 0;
}

/* Function to log sensor data to a CSV file */
int log_sensor_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.speed, data.temperature);
    fflush(log_file);
    return 0;
}

/* Function to handle errors and log them to a file */
void handle_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(stderr, "%s - ERROR: %s\n", timestamp, message);

    if (log_file != NULL) {
        fprintf(log_file, "%s - ERROR: %s\n", timestamp, message);
        fflush(log_file);
    }
}

int main() {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Initialize I2C */
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    /* Open the log file in append mode */
    log_file = fopen("mag_temp_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Write the header row if the file is new */
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Speed (RPM),Temperature (C)\n");
        fflush(log_file);
    }

    /* Set up signal handling for Ctrl+C */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    sensor_data_t sensor_data;

    /* Main loop */
    while (running) {
        if (read_sensor_data(&sensor_data) == 0) {
            if (log_sensor_data(sensor_data) != 0) {
                handle_error("Failed to log sensor data.");
            }
        } else {
            handle_error("Failed to read sensor data.");
            if (log_file != NULL) {
                fprintf(log_file, "ERROR - Sensor read failed, Speed: NaN, Temperature: NaN\n");
                fflush(log_file);
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

