     * TMP117 register pointer 0x00 holds the 16-bit two's-complement
     * temperature value (MSB first).  A zero-length write to the
     * register selects it; a subsequent read returns the two bytes.
     */
    bytes = i2cWriteDevice(g_i2c_handle, buf, 0);
    if (bytes < 0) {
        fprintf(stderr, "I2C write (reg select) failed: %d\n", bytes);
        return TEMP_ERROR;
    }

    bytes = i2cReadDevice(g_i2c_handle, buf, 2);
    if (bytes != 2) {
        fprintf(stderr, "I2C read failed: expected 2 bytes, got %d\n", bytes);
        return TEMP_ERROR;
    }

    /* Assemble 16-bit two's-complement value (big-endian on the wire). */
    int16_t raw = (int16_t)(((uint16_t)(uint8_t)buf[0] << 8) |
                            (uint16_t)(uint8_t)buf[1]);

    /*
     * TMP117 default range is ±125 °C; 1 LSB = 0.0625 °C.
     * Negative temperatures are indicated by the sign bit (bit 15).
     */
    return (float)raw * 0.0625f;
}

/*
 * Attempt to recover the I2C bus after a failure.
 * Returns 0 on success, -1 on failure.
 */
static int recover_i2c(void)
{
    int attempt;

    for (attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        fprintf(stderr, "Attempting I2C recovery (%d/%d)...\n",
                attempt + 1, MAX_RETRIES);
        if (init_i2c() == 0) {
            fprintf(stderr, "Recovery successful.\n");
            return 0;
        }
        time_sleep(0.5);
    }

    fprintf(stderr, "I2C recovery failed after %d attempts.\n", MAX_RETRIES);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static void log_temperature(float temperature)
{
    FILE *fp;
    time_t t;
    struct tm tm_info;
    char timestamp[32];

    t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        return;
    }

    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    fprintf(fp, "%s, Temperature: %.2f C\n", timestamp, temperature);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    struct sigaction sa;

    /* Install SIGINT handler for graceful shutdown. */
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize I2C bus and target the TMP117. */
    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(stderr, "TMP117 logger started. Logging to %s every %.1f s.\n",
            LOG_FILE, SAMPLE_PERIOD);
    fprintf(stderr, "Press Ctrl+C to stop.\n");

    /* Main sampling loop. */
    while (g_running) {
        float temperature = read_temperature();

        if (temperature == TEMP_ERROR) {
            fprintf(stderr, "Temperature read failed; attempting recovery...\n");
            if (recover_i2c() != 0) {
                fprintf(stderr, "Recovery failed; exiting.\n");
                break;
            }
            continue;
        }

        log_temperature(temperature);
        time_sleep(SAMPLE_PERIOD);
    }

    /* Clean shutdown. */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    fprintf(stderr, "Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

