/*
 * Raspberry Pi Zero W – Honeywell HAFUHH0025PA3 flow sensor logger
 *
 * Reads a 4-byte payload from the sensor over I2C (no register pointer
 * write is required on the Honeywell HAF family), extracts a 14-bit
 * flow value and a 12-bit temperature value, and logs timestamped
 * measurements to flow_log.txt once per second.
 *
 * Wiring:
 *   HAFUHH0025PA3 VCC  -> Pi 3V3 (Pin 1)
 *   HAFUHH0025PA3 GND  -> Pi GND (Pin 9)
 *   HAFUHH0025PA3 SDA  -> Pi GPIO2 / I2C SDA (Pin 3)
 *   HAFUHH0025PA3 SCL  -> Pi GPIO3 / I2C SCL (Pin 5)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o flow_logger flow_logger.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./flow_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Constants ----------------------------- */
#define I2C_BUS              1       /* /dev/i2c-1 on the Pi Zero W      */
#define I2C_ADDR             0x40    /* HAFUHH0025PA3 default I2C address */
#define LOG_FILE             "flow_log.txt"
#define SAMPLE_PERIOD_US     1000000 /* 1 second                          */
#define MAX_RETRIES          3
#define RETRY_DELAY_US       200000  /* 200 ms between retries             */

/* --------------------------- Global state ---------------------------- */
static int      i2c_handle = -1;
static FILE    *log_file   = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------- Function prototypes ------------------------ */
static int  initialize_i2c(void);
static int  read_sensor_data(uint8_t *buf, size_t len);
static void process_sensor_data(const uint8_t *buf, float *flow_slpm,
                                float *temp_c);
static void log_data(float flow_slpm, float temp_c);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------ I2C init ----------------------------- */
static int initialize_i2c(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (bus=%d addr=0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

/* --------------------------- Sensor read ----------------------------- */
/*
 * The Honeywell HAF family returns a 4-byte payload when the master
 * issues a read without a preceding register pointer write.  The
 * first two bytes are the 14-bit flow value (MSB first), the next
 * two bytes are the 12-bit temperature value (MSB first).
 */
static int read_sensor_data(uint8_t *buf, size_t len)
{
    int bytes_read = i2cReadDevice(i2c_handle, (char *)buf, len);
    if (bytes_read < 0) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed: %d\n", bytes_read);
        return -1;
    }
    if (bytes_read != (int)len) {
        fprintf(stderr, "[ERROR] Short read: got %d of %zu bytes\n",
                bytes_read, len);
        return -1;
    }
    return 0;
}

/* --------------------- Data processing / conversion ------------------- */
static void process_sensor_data(const uint8_t *buf, float *flow_slpm,
                                float *temp_c)
{
    /*
     * 14-bit flow value in the high 14 bits of the first two bytes.
     * 12-bit temperature in the high 12 bits of the last two bytes.
     */
    uint16_t raw_flow = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t raw_temp = ((uint16_t)buf[2] << 8) | buf[3];

    *flow_slpm = (float)(raw_flow & 0x3FFF) / 10.0f;
    *temp_c    = (float)(raw_temp & 0x0FFF) / 10.0f;
}

/* ------------------------------ Logging ------------------------------- */
static void log_data(float flow_slpm, float temp_c)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(log_file, "%s, Flow: %.2f SLPM, Temperature: %.2f °C\n",
            timestamp, flow_slpm, temp_c);
    fflush(log_file);
}

/* --------------------------- Signal handler --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------ Cleanup ------------------------------- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* --------------------------------- Main ------------------------------- */
int main(void)
{
    uint8_t  buf[4];
    float    flow_slpm, temp_c;
    int      consecutive_failures = 0;

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("[FATAL] fopen(" LOG_FILE ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Initialize I2C --- */
    if (initialize_i2c() != 0) {
        fprintf(stderr, "[FATAL] I2C initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Register signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("HAFUHH0025PA3 flow logger started.  Logging to %s\n", LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    /*
     * First two reads after power-up may return stale data.
     * Discard them and wait for the sensor to stabilize.
     */
    (void)read_sensor_data(buf, sizeof(buf));
    (void)read_sensor_data(buf, sizeof(buf));
    gpioDelay(500000); /* 500 ms */

    /* --- Main sampling loop --- */
    while (!terminate) {
        if (read_sensor_data(buf, sizeof(buf)) == 0) {
            consecutive_failures = 0;
            process_sensor_data(buf, &flow_slpm, &temp_c);
            log_data(flow_slpm, temp_c);
        } else {
            consecutive_failures++;
            fprintf(stderr, "[WARN] Read failure #%d\n", consecutive_failures);

            if (consecutive_failures >= MAX_RETRIES) {
                fprintf(stderr,
                        "[ERROR] %d consecutive failures – re-initializing I2C.\n",
                        consecutive_failures);
                if (initialize_i2c() != 0) {
                    fprintf(stderr,
                            "[FATAL] I2C re-initialisation failed – aborting.\n");
                    break;
                }
                consecutive_failures = 0;
            }

            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Graceful cleanup --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

