#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>

#define DHT11_GPIO 4
#define LOG_FILE "dht11_readings.txt"
#define MAX_RETRIES 3
#define READ_INTERVAL_S 2

/* DHT11 timing constants (microseconds) */
#define DHT_START_LOW_US   20000   /* >= 18 ms */
#define DHT_START_HIGH_US  40      /* 20-40 us */
#define DHT_RESP_LOW_US    80
#define DHT_RESP_HIGH_US   80
#define DHT_BIT_LOW_US     50
#define DHT_BIT_THRESHOLD  50      /* > 50 us high => '1', else '0' */
#define DHT_TIMEOUT_US     1000

enum dht_status {
    DHT_OK = 0,
    DHT_ERROR_TIMEOUT,
    DHT_ERROR_CHECKSUM,
    DHT_ERROR_STUCK_HIGH,
    DHT_ERROR_STUCK_LOW,
    DHT_ERROR_GPIO_INIT,
    DHT_ERROR_FILE_OPEN
};

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/*
 * Wait for the line to reach the given level or until timeout (microseconds).
 * Returns 0 on success, -1 on timeout.
 */
static int wait_level(int gpio, int level, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    while (gpioRead(gpio) != level) {
        if ((gpioTick() - start) > timeout_us)
            return -1;
    }
    return 0;
}

/*
 * Measure the duration (microseconds) that the line stays at the given level.
 * Returns duration in us, or -1 on timeout.
 */
static int measure_level(int gpio, int level, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    while (gpioRead(gpio) == level) {
        if ((gpioTick() - start) > timeout_us)
            return -1;
    }
    return (int)(gpioTick() - start);
}

/*
 * Read 40 bits from the DHT11.
 * Returns DHT_OK on success and fills data[5];
 * returns a DHT_ERROR code on failure.
 */
static int read_dht11(int gpio, float *temperature, float *humidity) {
    uint8_t data[5] = {0};
    int i;

    /* --- Start signal: pull low for >= 18 ms, then release --- */
    if (gpioSetMode(gpio, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(output) failed\n");
        return DHT_ERROR_GPIO_INIT;
    }
    if (gpioWrite(gpio, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(0) failed\n");
        return DHT_ERROR_GPIO_INIT;
    }
    gpioDelay(DHT_START_LOW_US);

    /* Release the line: switch to input (external pull-up brings it high) */
    if (gpioSetMode(gpio, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(input) failed\n");
        return DHT_ERROR_GPIO_INIT;
    }

    /* Sensor response: ~80 us low, ~80 us high */
    if (wait_level(gpio, 0, DHT_TIMEOUT_US) < 0) {
        fprintf(stderr, "Error: DHT11 response low timeout\n");
        return DHT_ERROR_TIMEOUT;
    }
    if (wait_level(gpio, 1, DHT_TIMEOUT_US) < 0) {
        fprintf(stderr, "Error: DHT11 response high timeout\n");
        return DHT_ERROR_TIMEOUT;
    }

    /* Read 40 data bits */
    for (i = 0; i < 40; i++) {
        /* Low preamble (~50 us) */
        if (wait_level(gpio, 0, DHT_TIMEOUT_US) < 0) {
            fprintf(stderr, "Error: DHT11 bit %d low timeout\n", i);
            return DHT_ERROR_TIMEOUT;
        }

        /* Measure high duration: ~26-28 us = '0', ~70 us = '1' */
        int high_us = measure_level(gpio, 1, DHT_TIMEOUT_US);
        if (high_us < 0) {
            fprintf(stderr, "Error: DHT11 bit %d high timeout\n", i);
            return DHT_ERROR_TIMEOUT;
        }

        data[i / 8] <<= 1;
        if (high_us > DHT_BIT_THRESHOLD) {
            data[i / 8] |= 1;
        }
    }

    /* Checksum */
    uint8_t checksum = (uint8_t)(data[0] + data[1] + data[2] + data[3]);
    if (checksum != data[4]) {
        fprintf(stderr, "Error: DHT11 checksum mismatch (calc=%u, recv=%u)\n",
                checksum, data[4]);
        return DHT_ERROR_CHECKSUM;
    }

    /* Parse humidity: data[0] = integer, data[1] = decimal (always 0) */
    uint16_t raw_humidity = (uint16_t)((data[0] << 8) | data[1]);
    /* Parse temperature: data[2] = integer, data[3] = decimal (always 0) */
    uint16_t raw_temp = (uint16_t)((data[2] << 8) | data[3]);

    *humidity = (float)raw_humidity / 10.0f;
    *temperature = (float)raw_temp / 10.0f;
    if (raw_temp & 0x8000) {
        *temperature = -*temperature;
    }

    return DHT_OK;
}

static void log_reading(float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
