#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SHT31_ADDR     0x44
#define MEASURE_CMD    0x2C06
#define LOG_FILE       "sht31d_data.log"
#define SAMPLE_PERIOD  5
#define MAX_RETRIES    3
#define MEASURE_DELAY  15000   /* microseconds */

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

/* CRC-8 polynomial 0x31, init 0xFF — matches Sensirion SHT3x spec */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_sensor_data(sensor_data_t *data) {
    uint8_t cmd[2] = { (uint8_t)(MEASURE_CMD >> 8), (uint8_t)(MEASURE_CMD & 0xFF) };
    uint8_t buf[6];
    int rc;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        rc = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
        if (rc < 0) {
            fprintf(stderr, "I2C write failed (attempt %d/%d, rc=%d)\n",
                    attempt + 1, MAX_RETRIES, rc);
            gpioDelay(MEASURE_DELAY);
            continue;
        }

        gpioDelay(MEASURE_DELAY);

        rc = i2cReadDevice(i2c_handle, (char *)buf, 6);
        if (rc < 0) {
            fprintf(stderr, "I2C read failed (attempt %d/%d, rc=%d)\n",
                    attempt + 1, MAX_RETRIES, rc);
            continue;
        }
        if (rc != 6) {
            fprintf(stderr, "I2C read short: got %d bytes (attempt %d/%d)\n",
                    rc, attempt + 1, MAX_RETRIES);
            continue;
        }

        /* Validate CRC-8 for temperature and humidity words */
        if (crc8(&buf[0], 2) != buf[2]) {
            fprintf(stderr, "Temperature CRC mismatch (attempt %d/%d)\n",
                    attempt + 1, MAX_RETRIES);
            continue;
        }
        if (crc8(&buf[3], 2) != buf[5]) {
            fprintf(stderr, "Humidity CRC mismatch (attempt %d/%d)\n",
                    attempt + 1, MAX_RETRIES);
            continue;
        }

        uint16_t t_raw = (uint16_t)((buf[0] << 8) | buf[1]);
        uint16_t h_raw = (uint16_t)((buf[3] << 8) | buf[4]);

        data->temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
        data->humidity   = 100.0f * (float)h_raw / 65535.0f;

        return 0;
    }

    return -1;
}

static void log_data(const sensor_data_t *data) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(log_file, "%s,%.2f,%.2f\n", ts, data->temperature, data->humidity);
    fflush(log_file);
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(log_file, "%s,ERROR,%s\n", ts, msg);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (init_i2c() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(&sensor_data);
        } else {
            log_error("read_sensor_data failed");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && !terminate; i++) {
            gpioDelay(100000);
        }
    }

    cleanup();
    return 0;
}

