#define ADPD105_ADDR_1 0x50
#define ADPD105_ADDR_2 0x51

#define REG_MODE 0x00
#define REG_DATA 0x01
#define REG_CONFIG 0x0A

#define MODE_CONTINUOUS 0x01
#define CONFIG_DEFAULT 0x00

#define SAMPLE_DELAY_US 100000
#define LOG_INTERVAL_S 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int adpd105_write_reg(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "Error: I2C write to reg 0x%02X failed on handle %d\n", reg, handle);
        return -1;
    }
    return 0;
}

static int adpd105_read_reg(int handle, uint8_t reg, uint8_t *value) {
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(handle, reg_buf, 1) != 0) {
        fprintf(stderr, "Error: I2C write (reg select) 0x%02X failed on handle %d\n", reg, handle);
        return -1;
    }
    char data_buf[1];
    if (i2cReadDevice(handle, data_buf, 1) != 1) {
        fprintf(stderr, "Error: I2C read from reg 0x%02X failed on handle %d\n", reg, handle);
        return -1;
    }
    *value = (uint8_t)data_buf[0];
    return 0;
}

static int adpd105_init(int handle) {
    if (adpd105_write_reg(handle, REG_MODE, MODE_CONTINUOUS) != 0) return -1;
    if (adpd105_write_reg(handle, REG_CONFIG, CONFIG_DEFAULT) != 0) return -1;
    return 0;
}

static int adpd105_read_data(int handle, uint16_t *ch1, uint16_t *ch2) {
    char reg_buf[1] = { (char)REG_DATA };
    if (i2cWriteDevice(handle, reg_buf, 1) != 0) {
        fprintf(stderr, "Error: I2C write (reg select) failed for data read\n");
        return -1;
    }
    char data_buf[4];
    if (i2cReadDevice(handle, data_buf, 4) != 4) {
        fprintf(stderr, "Error: I2C read failed for data read\n");
        return -1;
    }
    *ch1 = ((uint16_t)(uint8_t)data_buf[0] << 8) | (uint8_t)data_buf[1];
    *ch2 = ((uint16_t)(uint8_t)data_buf[2] << 8) | (uint8_t)data_buf[3];
    return 0;
}

static float calculate_cct(uint16_t ch1, uint16_t ch2) {
    if (ch1 == 0) return 0.0f;
    float ratio = (float)ch2 / (float)ch1;
    float cct = 400.0f * (1.0f - powf(ratio, 0.333333f));
    if (cct < 0.0f) cct = 0.0f;
    if (cct > 100000.0f) cct = 100000.0f;
    return cct;
}

static int log_cct(float avg_cct) {
    FILE *fp = fopen("cct_log.csv", "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open cct_log.csv for appending\n");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, avg_cct);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int handle1 = i2cOpen(I2C_BUS, ADPD105_ADDR_1, 0);
    if (handle1 < 0) {
        fprintf(stderr, "Error: Could not open I2C device at 0x%02X (err=%d)\n", ADPD105_ADDR_1, handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int handle2 = i2cOpen(I2C_BUS, ADPD105_ADDR_2, 0);
    if (handle2 < 0) {
        fprintf(stderr, "Error: Could not open I2C device at 0x%02X (err=%d)\n", ADPD105_ADDR_2, handle2);
        i2cClose(handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (adpd105_init(handle1) != 0) {
        fprintf(stderr, "Error: Failed to initialize ADPD105 at 0x%02X\n", ADPD105_ADDR_1);
        i2cClose(handle1);
        i2cClose(handle2);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (adpd105_init(handle2) != 0) {
        fprintf(stderr, "Error: Failed to initialize ADPD105 at 0x%02X\n", ADPD105_ADDR_2);
        adpd105_init(handle1);
        i2cClose(handle1);
        i2cClose(handle2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *fp = fopen("cct_log.csv", "r");
    int file_exists = (fp != NULL);
    if (fp) fclose(fp);

    if (!file_exists) {
        fp = fopen("cct_log.csv", "w");
        if (fp) {
            fprintf(fp, "Timestamp,Average_CCT\n");
            fclose(fp);
        } else {
            fprintf(stderr, "Error: Could not create cct_log.csv\n");
            i2cClose(handle1);
            i2cClose(handle2);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    while (running) {
        uint16_t ch1_val = 0, ch2_val = 0;
        int read_ok = 1;

        if (adpd105_read_data(handle1, &ch1_val, &ch2_val) != 0) {
            read_ok = 0;
        }
        if (read_ok && adpd105_read_data(handle2, &ch1_val, &ch2_val) != 0) {
            read_ok = 0;
        }

        if (read_ok) {
            float cct1 = calculate_cct(ch1_val, ch2_val);
            float cct2 = calculate_cct(ch1_val, ch2_val);
            float avg_cct = (cct1 + cct2) / 2.0f;
            if (log_cct(avg_cct) != 0) {
                fprintf(stderr, "Warning: Failed to log CCT value\n");
            }
        } else {
            fprintf(stderr, "Warning: Sensor read error, skipping log entry\n");
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    i2cClose(handle1);
    i2cClose(handle2);
    gpioTerminate();
    return EXIT_SUCCESS;
}

