#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define LOG_FILE "pressure_log.txt"
#define READ_INTERVAL_SEC 2

/* MLX90824 register addresses (command byte + 0x80 for read) */
#define REG_PRESSURE_MSB 0x00
#define REG_PRESSURE_LSB 0x01
#define REG_TEMP_MSB    0x02
#define REG_TEMP_LSB    0x03
#define REG_STATUS      0x04

/* Status register bit masks */
#define STATUS_FAULT    0x01
#define STATUS_READY    0x00

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void get_timestamp(char *buf, size_t len) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm);
}

static void log_message(const char *msg) {
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    if (g_log_file) {
        fprintf(g_log_file, "%s, %s\n", ts, msg);
        fflush(g_log_file);
    }
    fprintf(stderr, "%s, %s\n", ts, msg);
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/*
 * Read a 16-bit big-endian register pair from the MLX90824.
 * Returns 0 on success, -1 on I2C error, -2 on sensor fault.
 */
static int read_register16(int handle, uint8_t reg_msb, uint8_t reg_lsb, uint16_t *out) {
    int msb = i2cReadByteData(handle, reg_msb);
    if (msb < 0) {
        return -1;
    }
    int lsb = i2cReadByteData(handle, reg_lsb);
    if (lsb < 0) {
        return -1;
    }
    *out = ((uint16_t)msb << 8) | (uint16_t)lsb;
    return 0;
}

static int read_sensor(int handle, float *pressure, float *temperature) {
    uint16_t raw_p, raw_t;
    int status;

    /* Read status register to check for fault */
    status = i2cReadByteData(handle, REG_STATUS);
    if (status < 0) {
        return -1;
    }
    if (status & STATUS_FAULT) {
        return -2;
    }

    /* Read pressure (registers 0x00/0x01, big-endian) */
    if (read_register16(handle, REG_PRESSURE_MSB, REG_PRESSURE_LSB, &raw_p) != 0) {
        return -1;
    }

    /* Read temperature (registers 0x02/0x03, big-endian) */
    if (read_register16(handle, REG_TEMP_MSB, REG_TEMP_LSB, &raw_t) != 0) {
        return -1;
    }

    /* Convert raw values to physical units (per datasheet) */
    *pressure = (float)raw_p * 0.0078125f;          /* Pa */
    *temperature = (float)raw_t * 0.01f - 40.0f;     /* °C */

    return 0;
}

int main(void) {
    float pressure, temperature;
    char ts[32];

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (code %d). Sensor may be absent at 0x%02X.\n",
                g_i2c_handle, I2C_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90824 pressure logger started. Logging to '%s' every %d s.\n",
           LOG_FILE, READ_INTERVAL_SEC);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        int rc = read_sensor(g_i2c_handle, &pressure, &temperature);

        get_timestamp(ts, sizeof(ts));

        if (rc == 0) {
            fprintf(g_log_file, "%s, %.2f Pa, %.2f C\n", ts, pressure, temperature);
            printf("%s, %.2f Pa, %.2f C\n", ts, pressure, temperature);
        } else if (rc == -2) {
            fprintf(g_log_file, "%s, ERROR: sensor fault (status 0x%02X)\n", ts, status);
            fprintf(stderr, "Error: sensor fault (status 0x%02X).\n", status);
        } else {
            fprintf(g_log_file, "%s, ERROR: I2C read failure\n", ts);
            fprintf(stderr, "Error: I2C read failure.\n");
        }
        fflush(g_log_file);

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < READ_INTERVAL_SEC * 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

