    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90824 pressure logger started. Logging to '%s' every %d s.\n",
           LOG_FILE, READ_INTERVAL_SEC);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        int rc = read_sensor(g_i2c_handle, &pressure, &temperature);

        get_timestamp(ts, sizeof(ts));

        if (rc == 0) {
