/*
 * SDP810-500Pa differential pressure logger for Raspberry Pi Zero W.
 *
 * Wiring:
 *   SDP810 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP810 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP810 VDD  -> 3.3 V
 *   SDP810 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o airflow airflow.c -lpigpio -lrt
 * Run:    sudo ./airflow
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x25
#define LOG_FILE       "airflow.log"
#define SAMPLE_PERIOD  1.0          /* seconds between samples */
#define MEAS_DELAY     0.045        /* 45 ms first-measurement delay */
#define PRESSURE_THRESHOLD 5.0      /* Pa */
#define READ_LEN       9            /* SDP810 measurement frame: 3 × (2 data + 1 CRC) */

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Sensirion CRC-8  (polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read one measurement frame from the SDP810                          */
/* Returns 0 on success, -1 on I2C error, -2 on CRC mismatch.          */
/* ------------------------------------------------------------------ */
static int read_sdp810(float *pressure, float *temperature)
{
    uint8_t cmd[2] = { 0x36, 0x08 };   /* continuous measurement, average */
    uint8_t buf[READ_LEN];

    /* Issue continuous-measurement command */
    if (i2cWriteDevice(g_i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "[ERROR] I2C write failed (cmd 0x3608)\n");
        return -1;
    }

    /* Wait for the first conversion to complete (~45 ms) */
    time_sleep(MEAS_DELAY);

    /* Read 9 bytes: pressure(2)+crc, temperature(2)+crc, scale(2)+crc */
    int n = i2cReadDevice(g_i2c_handle, (char *)buf, READ_LEN);
    if (n != READ_LEN) {
        fprintf(stderr, "[ERROR] I2C read failed: got %d bytes, expected %d\n",
                n, READ_LEN);
        return -1;
    }

    /* CRC checks */
    if (sensirion_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] CRC mismatch on pressure word\n");
        return -2;
    }
    if (sensirion_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[ERROR] CRC mismatch on temperature word\n");
        return -2;
    }
    if (sensirion_crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "[ERROR] CRC mismatch on scale factor word\n");
        return -2;
    }

    /* Raw values are big-endian, signed 16-bit */
    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temp     = (int16_t)((buf[3] << 8) | buf[4]);

    /* Conversion formulas (SDP810-500Pa datasheet) */
    *pressure    = (float)raw_pressure / 100.0f;   /* Pa */
    *temperature = (float)raw_temp     / 200.0f;   /* °C */

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one reading to CSV                                              */
/* ------------------------------------------------------------------ */
static void log_data(float pressure, float temperature)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_file, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("[FATAL] fopen(" LOG_FILE ")");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SDP810 airflow logger started.  Logging to %s  (Ctrl-C to stop)\n",
           LOG_FILE);

    /* --- main loop --- */
    while (g_running) {
        float pressure, temperature;

        int rc = read_sdp810(&pressure, &temperature);
        if (rc == 0) {
            log_data(pressure, temperature);
            if (pressure > PRESSURE_THRESHOLD)
                fprintf(stderr,
                        "[WARN] Pressure exceeds %.1f Pa: %.2f Pa\n",
                        PRESSURE_THRESHOLD, pressure);
        } else if (rc == -2) {
            /* CRC error — sensor may be absent or bus noise */
            fprintf(stderr, "[WARN] Sensor CRC error (code %d); "
                            "check wiring and I2C address\n", rc);
        } else {
            /* I2C error */
            fprintf(stderr, "[WARN] I2C read error (code %d)\n", rc);
        }

        time_sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

