#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define STTS2004_ADDR  0x48
#define GPIO_LED       17
#define TEMP_HIGH      28.0f
#define TEMP_LOW       27.0f
#define POLL_DELAY_US  1000000
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_temp(int fd, float *temp_out)
{
    uint8_t reg = 0x00;
    uint8_t buf[2];
    ssize_t w, r;

    w = write(fd, &reg, 1);
    if (w != 1) {
        fprintf(stderr, "I2C write (reg select) failed: %s\n", strerror(errno));
        return -1;
    }

    r = read(fd, buf, 2);
    if (r != 2) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *temp_out = (float)raw / 100.0f;
    return 0;
}

static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    float temperature;
    int led_state = 0;
    int consecutive_failures = 0;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, STTS2004_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                STTS2004_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_LED);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_LED, 0);

    while (g_running) {
        if (i2c_read_temp(g_i2c_fd, &temperature) == 0) {
            consecutive_failures = 0;

            if (temperature > TEMP_HIGH && led_state == 0) {
                if (gpioWrite(GPIO_LED, 1) == 0) {
                    led_state = 1;
                    printf("Temperature: %.2f C, LED ON\n", temperature);
                } else {
                    fprintf(stderr, "Failed to set GPIO %d high: %s\n",
                            GPIO_LED, strerror(errno));
                }
            } else if (temperature < TEMP_LOW && led_state == 1) {
                if (gpioWrite(GPIO_LED, 0) == 0) {
                    led_state = 0;
                    printf("Temperature: %.2f C, LED OFF\n", temperature);
                } else {
                    fprintf(stderr, "Failed to set GPIO %d low: %s\n",
                            GPIO_LED, strerror(errno));
                }
            } else {
                printf("Temperature: %.2f C\n", temperature);
            }
        } else {
            consecutive_failures++;
            fprintf(stderr, "Failed to read temperature (attempt %d/%d)\n",
                    consecutive_failures, MAX_RETRIES);
            if (consecutive_failures >= MAX_RETRIES) {
                fprintf(stderr, "Max consecutive I2C failures reached. Exiting.\n");
                break;
            }
        }

        usleep(POLL_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

