#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define MEASUREMENT_DELAY_US 45000
#define LOG_FILE "flow_data.txt"

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float differential_pressure;
    float temperature;
} sensor_data_t;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc = (crc << 1);
            }
        }
    }
    return crc;
}

static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

static int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_sensor_data(sensor_data_t *data) {
    char cmd[2] = {0x36, 0x08};
    char buffer[9];
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", result);
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    result = i2cReadDevice(i2c_handle, buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", result);
        return -1;
    }

    if (crc8((uint8_t *)buffer, 2) != (uint8_t)buffer[2]) {
        fprintf(stderr, "CRC check failed for differential pressure\n");
        return -1;
    }

    if (crc8((uint8_t *)buffer + 3, 2) != (uint8_t)buffer[5]) {
        fprintf(stderr, "CRC check failed for temperature\n");
        return -1;
    }

    int16_t dp_raw = (buffer[0] << 8) | buffer[1];
    int16_t temp_raw = (buffer[3] << 8) | buffer[4];
    int16_t scale_factor = (buffer[6] << 8) | buffer[7];

    if (scale_factor == 0) {
        fprintf(stderr, "Invalid scale factor (0)\n");
        return -1;
    }

    data->differential_pressure = (float)dp_raw / scale_factor;
    data->temperature = (float)temp_raw / scale_factor;

    return 0;
}

static int log_data(const sensor_data_t *data) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Differential Pressure: %.2f Pa, Temperature: %.2f C\n",
            timestamp, data->differential_pressure, data->temperature);

    fclose(fp);
    return 0;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register signal handler\n");
        return 1;
    }

    if (initialize_i2c() != 0) {
        return 1;
    }

    sensor_data_t sensor_data;

    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            if (log_data(&sensor_data) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(1000000);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

