#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x76
#define LOG_FILE       "environment.log"
#define SAMPLE_PERIOD  60
#define MAX_RETRIES    3
#define MEAS_DELAY_US  20000   /* 20 ms for no-hold measurement */

/* Si7021 commands (no register addressing) */
#define CMD_MEASURE_RH_NOHOLD  0xF5
#define CMD_MEASURE_TEMP_NOHOLD 0xF3
#define CMD_READ_TEMP_PREV     0xE0

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int handle, uint8_t cmd)
{
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        int rc = i2cWriteByte(handle, cmd);
        if (rc == 0)
            return 0;
        gpioDelay(1000);   /* 1 ms back-off */
    }
    return -1;
}

static int i2c_read_bytes(int handle, uint8_t *buf, uint32_t len)
{
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        int rc = i2cReadDevice(handle, (char *)buf, len);
        if (rc == (int)len)
            return 0;
        gpioDelay(1000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Sensor presence check                                               */
/* ------------------------------------------------------------------ */
static int check_sensor_present(int handle)
{
    /* Read firmware revision byte (0x84) or electronic ID (0xFA) */
    if (i2c_write_cmd(handle, 0xFA) != 0) {
        fprintf(stderr, "Error: cannot write 0xFA (Si7021 not responding?)\n");
        return -1;
    }
    gpioDelay(10000);   /* 10 ms for command processing */

    uint8_t rev;
    if (i2c_read_bytes(handle, &rev, 1) != 0) {
        fprintf(stderr, "Error: cannot read Si7021 electronic ID\n");
        return -1;
    }
    printf("Si7021 detected (electronic ID = 0x%02X)\n", rev);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read temperature from previous RH measurement                      */
/* ------------------------------------------------------------------ */
static int read_temperature_from_prev_rh(int handle, float *temp_c)
{
    if (i2c_write_cmd(handle, CMD_READ_TEMP_PREV) != 0)
        return -1;
    gpioDelay(MEAS_DELAY_US);

    uint8_t buf[2];
    if (i2c_read_bytes(handle, buf, 2) != 0)
        return -1;

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *temp_c = (175.72f * raw / 65536.0f) - 46.85f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read humidity from a no-hold measurement                            */
/* ------------------------------------------------------------------ */
static int read_humidity_nohold(int handle, float *hum_pct)
{
    if (i2c_write_cmd(handle, CMD_MEASURE_RH_NOHOLD) != 0)
        return -1;
    gpioDelay(MEAS_DELAY_US);

    uint8_t buf[2];
    if (i2c_read_bytes(handle, buf, 2) != 0)
        return -1;

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *hum_pct = (125.0f * raw / 65536.0f) - 6.0f;
    if (*hum_pct < 0.0f)   *hum_pct = 0.0f;
    if (*hum_pct > 100.0f) *hum_pct = 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float temp_c, float hum_pct)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, temp_c, hum_pct);
    fflush(fp);
}

static void log_error(FILE *fp, const char *msg)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(stderr, "%s ERROR: %s\n", ts, msg);
    fprintf(fp, "%s,ERROR,%s\n", ts, msg);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (check_sensor_present(g_i2c_handle) != 0) {
        log_error(g_log_file, "Sensor not detected");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Si7021 logger started. Sampling every %d s. Ctrl+C to stop.\n",
           SAMPLE_PERIOD);

    while (g_running) {
        float temp_c, hum_pct;

