#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define STS40_ADDR     0x40
#define LOG_FILE       "temperature_log.txt"
#define SAMPLE_PERIOD  5
#define CONV_DELAY_MS  10

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Sensirion CRC-8: polynomial 0x31, init 0xFF */
static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_open(const char *bus, uint8_t addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("open I2C bus");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return -1;
    }
    return fd;
}

static int read_temperature(int fd, float *temp_out) {
    uint8_t cmd = 0x3F;
    ssize_t w = write(fd, &cmd, 1);
    if (w != 1) {
        fprintf(stderr, "I2C write trigger failed (wrote %zd bytes)\n", w);
        return -1;
    }

    usleep(CONV_DELAY_MS * 1000);

    uint8_t buf[3];
    ssize_t r = read(fd, buf, sizeof(buf));
    if (r != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read failed (got %zd bytes, expected %zu)\n", r, sizeof(buf));
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on temperature data\n");
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *temp_out = -45.0f + (175.0f * (float)raw / 65535.0f);
    return 0;
}

static void log_temperature(FILE *fp, float temp) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];
    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);
    fprintf(fp, "%s, %.2f\n", ts, temp);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = i2c_open(I2C_BUS, STS40_ADDR);
    if (g_i2c_fd < 0)
        return EXIT_FAILURE;

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen log file");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    while (g_running) {
        float temp;
        if (read_temperature(g_i2c_fd, &temp) == 0) {
            log_temperature(g_log_fp, temp);
        } else {
            fprintf(stderr, "Read failed; continuing.\n");
        }
        sleep(SAMPLE_PERIOD);
    }

    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

