#define I2C_BUS        1
#define I2C_ADDR       0x25
#define LOG_FILE       "hvac_pressure_log.txt"
#define SAMPLE_PERIOD  1.0
#define MEAS_DELAY     0.05
#define MAX_RETRIES    3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float pressure;
    float temperature;
    int   valid;
} sensor_data_t;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int init_log(void) {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

static int read_sensor_data(sensor_data_t *data) {
    uint8_t cmd[2] = {0x36, 0x08};
    uint8_t buf[9];
    int rc;

    rc = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "I2C write error: %d\n", rc);
        return -1;
    }

    time_sleep(MEAS_DELAY);

    rc = i2cReadDevice(i2c_handle, (char *)buf, 9);
    if (rc != 9) {
        fprintf(stderr, "I2C read error: expected 9 bytes, got %d\n", rc);
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "Scale-factor CRC mismatch\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temp     = (int16_t)((buf[3] << 8) | buf[4]);
    uint16_t scale       = (uint16_t)((buf[6] << 8) | buf[7]);

    if (scale == 0) {
        fprintf(stderr, "Invalid scale factor (0)\n");
        return -1;
    }

    data->pressure    = (float)raw_pressure / (float)scale;
    data->temperature = (float)raw_temp / 200.0f;
    data->valid       = 1;
    return 0;
}

static void log_data(const sensor_data_t *data) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (data->valid) {
        fprintf(log_file, "%s,%.2f,%.2f\n", ts, data->pressure, data->temperature);
        printf("%s,%.2f Pa,%.2f C\n", ts, data->pressure, data->temperature);
    } else {
        fprintf(log_file, "%s,ERROR,I2C/CRC read failure\n", ts);
        fprintf(stderr, "%s,ERROR,I2C/CRC read failure\n", ts);
    }
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0 || init_log() != 0) {
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;
    int consecutive_errors = 0;

    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            consecutive_errors = 0;
            log_data(&sensor_data);
        } else {
            consecutive_errors++;
            if (consecutive_errors >= MAX_RETRIES) {
                fprintf(stderr, "Max consecutive errors (%d) reached, aborting.\n",
                        MAX_RETRIES);
                break;
            }
        }
        time_sleep(SAMPLE_PERIOD);
    }

    cleanup();
    return 0;
}

