#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SCD40_ADDR 0x50
#define BUFFER_SIZE 100
#define LOG_INTERVAL_SEC 60
#define READ_INTERVAL_SEC 5
#define LOG_DIR "/var/log/scd40_data"
#define ERROR_LOG_FILE "/var/log/scd40_error.log"
#define CSV_FILE_PREFIX "scd40_data_"
#define CSV_FILE_SUFFIX ".csv"
#define CMD_START_PERIODIC 0x21B1
#define CMD_STOP_PERIODIC 0x3F86
#define CMD_GET_DATA_READY 0xE582
#define CMD_READ_MEASUREMENT 0xEC05
#define CMD_SOFT_RESET 0xFEB6
#define MEASUREMENT_INTERVAL_MS 5000
#define MAX_RETRIES 10

typedef struct {
    time_t timestamp;
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

static int i2c_handle = -1;
static circular_buffer_t buffer;
static volatile sig_atomic_t running = 1;
static pthread_t logging_thread;
static int logging_thread_created = 0;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (!fp) {
        perror("fopen error log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static int create_log_file(const char *filename) {
    struct stat st;
    if (stat(LOG_DIR, &st) == -1) {
        if (mkdir(LOG_DIR, 0755) == -1) {
            perror("mkdir");
            return -1;
        }
    }
    char path[512];
    snprintf(path, sizeof(path), "%s/%s", LOG_DIR, filename);
    FILE *fp = fopen(path, "w");
    if (!fp) {
        perror("fopen");
        return -1;
    }
    fprintf(fp, "Timestamp,CO2 (ppm),Temperature (C),Humidity (%%RH)\n");
    fclose(fp);
    return 0;
}

static int write_to_buffer(circular_buffer_t *buf, sensor_data_t data) {
    pthread_mutex_lock(&buf->mutex);
    buf->data[buf->head] = data;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count == BUFFER_SIZE) {
        buf->tail = (buf->tail + 1) % BUFFER_SIZE;
    } else {
        buf->count++;
    }
    pthread_mutex_unlock(&buf->mutex);
    return 0;
}

static int read_from_buffer(circular_buffer_t *buf, sensor_data_t *data, int index) {
    pthread_mutex_lock(&buf->mutex);
    if (index < 0 || index >= buf->count) {
        pthread_mutex_unlock(&buf->mutex);
        return -1;
    }
    int actual_index = (buf->tail + index) % BUFFER_SIZE;
    *data = buf->data[actual_index];
    pthread_mutex_unlock(&buf->mutex);
    return 0;
}

static int init_scd40(void) {
    if (i2cWriteByteData(i2c_handle, CMD_SOFT_RESET, 0x00) < 0) {
        log_error("Soft reset write failed");
        return -1;
    }
    gpioDelay(10000);
    if (i2cWriteByteData(i2c_handle, CMD_START_PERIODIC, 0x00) < 0) {
        log_error("Start periodic measurement failed");
        return -1;
    }
    return 0;
}

static int read_scd40_data(sensor_data_t *data) {
    uint8_t ready = 0;
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (i2cWriteByteData(i2c_handle, CMD_GET_DATA_READY, 0x00) < 0) {
            log_error("Write data ready command failed");
            return -1;
        }
        gpioDelay(2000);
        if (i2cReadDevice(i2c_handle, (char *)&ready, 1) != 1) {
            log_error("Read data ready failed");
            return -1;
        }
        if (ready & 0x01) break;
        gpioDelay(2000);
    }
    if (!(ready & 0x01)) {
        log_error("Data not ready after retries");
        return -1;
    }
    uint8_t cmd[2] = {(CMD_READ_MEASUREMENT >> 8) & 0xFF, CMD_READ_MEASUREMENT & 0xFF};
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 2) {
        log_error("Write read measurement command failed");
        return -1;
    }
    gpioDelay(MEASUREMENT_INTERVAL_MS * 1000);
    uint8_t buf[9];
    if (i2cReadDevice(i2c_handle, (char *)buf, 9) != 9) {
        log_error("Read measurement data failed");
        return -1;
    }
    if (crc8(&buf[0], 2) != buf[2]) {
        log_error("CO2 CRC mismatch");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        log_error("Temperature CRC mismatch");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        log_error("Humidity CRC mismatch");
        return -1;
    }
    data->co2 = (buf[0] << 8) | buf[1];
    data->temperature = (buf[3] << 8) | buf[4];
    data->humidity = (buf[6] << 8) | buf[7];
    return 0;
}

static void *logging_thread_func(void *arg) {
    (void)arg;
    while (running) {
        sensor_data_t data;
        int written = 0;
        for (int i = 0; i < BUFFER_SIZE && running; i++) {
            if (read_from_buffer(&buffer, &data, i) == 0) {
                char filename[256];
                snprintf(filename, sizeof(filename), "%s/%s%03d%s", LOG_DIR, CSV_FILE_PREFIX, i, CSV_FILE_SUFFIX);
                if (create_log_file(filename) != 0) {
                    log_error("Failed to create log file");
                }
                FILE *fp = fopen(filename, "a");
                if (!fp) {
                    log_error("Failed to open log file");
                    continue;
                }
                struct tm tm = *localtime(&data.timestamp);
                fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%.2f\n",
                        tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                        tm.tm_hour, tm.tm_min, tm.tm_sec,
                        data.co2, data.temperature, data.humidity);
                fclose(fp);
                written = 1;
            }
        }
        if (written) {
            sleep(LOG_INTERVAL_SEC);
        } else {
            sleep(1);
        }
    }
    return NULL;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cWriteByteData(i2c_handle, CMD_STOP_PERIODIC, 0x00);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (logging_thread_created) {
        pthread_join(logging_thread, NULL);
        logging_thread_created = 0;
    }
    pthread_mutex_destroy(&buffer.mutex);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    buffer.head = 0;
    buffer.tail = 0;
    buffer.count = 0;
    pthread_mutex_init(&buffer.mutex, NULL);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    if (init_scd40() != 0) {
        log_error("SCD40 init failed");
        cleanup();
        return 1;
    }
    if (pthread_create(&logging_thread, NULL, logging_thread_func, NULL) != 0) {
        perror("pthread_create");
        cleanup();
        return 1;
    }
    logging_thread_created = 1;
    printf("SCD40 logging started. Press Ctrl+C to stop.\n");
    while (running) {
        sensor_data_t data;
        if (read_scd40_data(&data) == 0) {
            write_to_buffer(&buffer, data);
        }
        sleep(READ_INTERVAL_SEC);
    }
    printf("\nShutting down...\n");
    pthread_mutex_lock(&buffer.mutex);
    int remaining = buffer.count;
    int start = buffer.tail;
    sensor_data_t final_data[BUFFER_SIZE];
    int written = 0;
    while (remaining > 0) {
        read_from_buffer(&buffer, &final_data[written], start);
        written++;
        start = (start + 1) % BUFFER_SIZE;
        remaining--;
    }
    pthread_mutex_unlock(&buffer.mutex);
    char filename[256];
    snprintf(filename, sizeof(filename), "%s/%s%03d%s", LOG_DIR, CSV_FILE_PREFIX, buffer.count, CSV_FILE_SUFFIX);
    if (create_log_file(filename) != 0) {
        log_error("Failed to create final log file");
    }
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        log_error("Failed to open final log file");
    } else {
        for (int i = 0; i < written; i++) {
            struct tm tm = *localtime(&final_data[i].timestamp);
            fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%.2f\n",
                    tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                    tm.tm_hour, tm.tm_min, tm.tm_sec,
                    final_data[i].co2, final_data[i].temperature, final_data[i].humidity);
        }
        fclose(fp);
    }
    cleanup();
    printf("Data flushed to %s\n", filename);
    return 0;
}

