#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x25
#define LOG_FILE       "sdp810_log.txt"
#define SAMPLE_PERIOD  1000000   /* microseconds (1 s) */
#define MEASURE_DELAY  45000     /* microseconds (45 ms) */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ---- CRC-8 (Sensirion: poly 0x31, init 0xFF) ---- */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/*
 * Read one differential-pressure sample from the SDP810.
 * Returns 0 on success, -1 on I/O error, -2 on CRC mismatch.
 */
static int read_sdp810(int handle, float *pressure, float *temperature)
{
    uint8_t cmd[2] = {0x36, 0x2F};   /* trigger continuous measurement */
    uint8_t buf[9];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed\n");
        return -1;
    }

    gpioDelay(MEASURE_DELAY);

    int n = i2cReadDevice(handle, (char *)buf, 9);
    if (n != 9) {
        fprintf(stderr, "[ERROR] i2cReadDevice returned %d (expected 9)\n", n);
        return -1;
    }

    /* CRC checks: [dp_msb, dp_lsb, dp_crc], [t_msb, t_lsb, t_crc], [s_msb, s_lsb, s_crc] */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] CRC mismatch on differential pressure\n");
        return -2;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[ERROR] CRC mismatch on temperature\n");
        return -2;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "[ERROR] CRC mismatch on scale factor\n");
        return -2;
    }

    int16_t raw_dp = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_t  = (int16_t)((buf[3] << 8) | buf[4]);
    uint16_t scale = (uint16_t)((buf[6] << 8) | buf[7]);

    if (scale == 0) {
        fprintf(stderr, "[ERROR] Scale factor is zero, invalid sample\n");
        return -2;
    }

    *pressure    = (float)raw_dp / (float)scale;
    *temperature = (float)raw_t / 200.0f;   /* SDP810-500Pa: 200 LSB/°C */

    return 0;
}

static void log_sample(FILE *fp, float pressure, float temperature)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(g_log_file, "# timestamp,pressure_Pa,temperature_C\n");

    while (g_running) {
        float pressure, temperature;
        int rc = read_sdp810(g_i2c_handle, &pressure, &temperature);
        if (rc == 0) {
            log_sample(g_log_file, pressure, temperature);
        } else if (rc == -1) {
            fprintf(stderr, "[WARN] I2C communication error, continuing\n");
        } else {
            fprintf(stderr, "[WARN] CRC error, continuing\n");
        }
        gpioDelay(SAMPLE_PERIOD);
    }

    cleanup();
    return EXIT_SUCCESS;
}

