#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ICP_10110_ADDR 0x20
#define TRIGGER_REG 0x00
#define PRESSURE_REG 0x02
#define TEMPERATURE_REG 0x04
#define SAMPLE_INTERVAL_SEC 5
#define TRIGGER_DELAY_US 10000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_register(int handle, uint8_t reg, uint16_t *value) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int read_sensor_data(int handle, float *pressure, float *temperature) {
    uint16_t raw_pressure, raw_temperature;

    if (read_register(handle, PRESSURE_REG, &raw_pressure) != 0) {
        return -1;
    }
    if (read_register(handle, TEMPERATURE_REG, &raw_temperature) != 0) {
        return -1;
    }

    *pressure = (float)raw_pressure / 65536.0f;
    *temperature = (float)raw_temperature / 65536.0f;
    return 0;
}

static void log_data(FILE *file, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ICP_10110_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    float pressure, temperature;

    while (!terminate) {
        if (read_sensor_data(i2c_handle, &pressure, &temperature) == 0) {
            log_data(log_file, pressure, temperature);
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

