#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define I2C_ADDR       0x29
#define GPIO_LED       17
#define PRESSURE_THRESHOLD 95000.0f
#define POLL_DELAY_US  1000000
#define TRIGGER_DELAY_US 20000
#define BLINK_HALF_US  500000
#define FAST_BLINK_HALF_US 100000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else           crc <<= 1;
        }
    }
    return crc;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    int total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            return -1;
        }
        if (n == 0) return -1;
        total += (int)n;
    }
    return 0;
}

static int read_sensor(int fd, float *pressure, float *temperature) {
    uint8_t data[6];
    if (i2c_read_bytes(fd, data, 6) != 0) {
        fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        return -1;
    }
    if (crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    uint16_t raw_p = ((uint16_t)data[0] << 8) | data[1];
    uint16_t raw_t = ((uint16_t)data[3] << 8) | data[4];
    *pressure    = (float)raw_p / 65536.0f * 100.0f;
    *temperature = (float)raw_t / 65536.0f * 165.0f - 40.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", I2C_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", GPIO_LED);
        close(g_i2c_fd);
        gpioTerminate();
        return 1;
    }

    printf("Monitoring pressure... Press Ctrl+C to exit.\n");

    while (g_running) {
        float pressure, temperature;
        if (read_sensor(g_i2c_fd, &pressure, &temperature) != 0) {
            gpioDelay(TRIGGER_DELAY_US);
            continue;
        }

        printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);

        if (pressure < PRESSURE_THRESHOLD) {
            gpioWrite(GPIO_LED, 1);
            gpioDelay(FAST_BLINK_HALF_US);
            gpioWrite(GPIO_LED, 0);
            gpioDelay(FAST_BLINK_HALF_US);
        } else {
            gpioWrite(GPIO_LED, 1);
            gpioDelay(BLINK_HALF_US);
            gpioWrite(GPIO_LED, 0);
            gpioDelay(BLINK_HALF_US);
        }

        gpioDelay(POLL_DELAY_US);
    }

    gpioWrite(GPIO_LED, 0);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return 0;
}

