#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x49
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 30.0
#define TEMP_THRESHOLD_LOW 28.0
#define LOG_FILE "temperature_log.txt"
#define READ_INTERVAL_SEC 2
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000

#define MLX90614_REG_AMBIENT_TEMP 0x03
#define MLX90614_REG_OBJECT_TEMP 0x05
#define MLX90614_REG_CONFIG 0x02

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register_retry(int handle, uint8_t reg, uint16_t *value) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int raw = i2cReadWordData(handle, reg);
        if (raw >= 0) {
            *value = (uint16_t)raw;
            return 0;
        }
        fprintf(stderr, "I2C read error (reg 0x%02X, attempt %d/%d): %s\n",
                reg, attempt + 1, MAX_RETRIES, strerror(errno));
        if (attempt < MAX_RETRIES - 1) {
            gpioDelay(RETRY_DELAY_US);
        }
    }
    return -1;
}

static int write_register_retry(int handle, uint8_t reg, uint16_t value) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteWordData(handle, reg, value);
        if (rc == 0) {
            return 0;
        }
        fprintf(stderr, "I2C write error (reg 0x%02X, attempt %d/%d): %s\n",
                reg, attempt + 1, MAX_RETRIES, strerror(errno));
        if (attempt < MAX_RETRIES - 1) {
            gpioDelay(RETRY_DELAY_US);
        }
    }
    return -1;
}

static int read_temperature(int handle, float *ambient, float *object) {
    uint16_t raw_amb, raw_obj;

    if (read_register_retry(handle, MLX90614_REG_AMBIENT_TEMP, &raw_amb) != 0) {
        fprintf(stderr, "Failed to read ambient temperature after %d retries.\n", MAX_RETRIES);
        return -1;
    }
    if (read_register_retry(handle, MLX90614_REG_OBJECT_TEMP, &raw_obj) != 0) {
        fprintf(stderr, "Failed to read object temperature after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    *ambient = (float)raw_amb * 0.02 - 273.15f;
    *object = (float)raw_obj * 0.02 - 273.15f;
    return 0;
}

static void log_temperature(float ambient, float object) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Ambient: %.2f C, Object: %.2f C\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                ambient, object);
    } else {
        fprintf(fp, "[timestamp error], Ambient: %.2f C, Object: %.2f C\n", ambient, object);
    }

    fclose(fp);
}

static void control_fan(float object_temp) {
    static int fan_on = 0;

    if (object_temp > TEMP_THRESHOLD_HIGH && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = 1;
            printf("Fan ON (Object Temp: %.2f C)\n", object_temp);
        } else {
            fprintf(stderr, "Failed to turn fan ON: %s\n", strerror(errno));
        }
    } else if (object_temp < TEMP_THRESHOLD_LOW && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = 0;
            printf("Fan OFF (Object Temp: %.2f C)\n", object_temp);
        } else {
            fprintf(stderr, "Failed to turn fan OFF: %s\n", strerror(errno));
        }
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(FAN_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %s\n", FAN_GPIO, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float ambient, object;

        if (read_temperature(i2c_handle, &ambient, &object) == 0) {
            log_temperature(ambient, object);
            control_fan(object);
            printf("Ambient: %.2f C, Object: %.2f C\n", ambient, object);
        } else {
            fprintf(stderr, "Sensor read failed; skipping log and fan control.\n");
        }

        if (running) {
            gpioDelay(READ_INTERVAL_SEC * 1000000);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

