#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0x243E
#define SERVER_PORT 8080
#define MAX_RETRIES 3
#define MEASURE_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int server_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sht40(int handle, float *temp, float *hum) {
    char cmd[2] = { (MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF };
    char buf[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(handle, cmd, 2) != 0) {
            fprintf(stderr, "I2C write failed (attempt %d/%d): %s\n", retries + 1, MAX_RETRIES, strerror(errno));
            retries++;
            usleep(10000);
            continue;
        }

        usleep(MEASURE_DELAY_US);

        if (i2cReadDevice(handle, buf, 6) != 6) {
            fprintf(stderr, "I2C read failed (attempt %d/%d): %s\n", retries + 1, MAX_RETRIES, strerror(errno));
            retries++;
            usleep(10000);
            continue;
        }

        unsigned int t_raw = ((unsigned char)buf[0] << 8) | (unsigned char)buf[1];
        unsigned int h_raw = ((unsigned char)buf[3] << 8) | (unsigned char)buf[4];

        *temp = -45.0f + 175.0f * (float)t_raw / 65535.0f;
        *hum = 100.0f * (float)h_raw / 65535.0f;

        if (*hum < 0.0f) *hum = 0.0f;
        if (*hum > 100.0f) *hum = 100.0f;

        return 0;
    }

    return -1;
}

static void handle_client(int client_fd) {
    float temp, hum;
    char html[512];

    if (read_sht40(i2c_handle, &temp, &hum) != 0) {
        snprintf(html, sizeof(html),
                 "<!DOCTYPE html><html><head><title>SHT40 Error</title>"
                 "<meta http-equiv=\"refresh\" content=\"2\"></head><body>"
                 "<h1>SHT40 Sensor Read Error</h1>"
                 "<p>Temperature: N/A</p>"
                 "<p>Humidity: N/A</p>"
                 "<p>Please refresh the page.</p>"
                 "</body></html>");
    } else {
        snprintf(html, sizeof(html),
                 "<!DOCTYPE html><html><head><title>SHT40</title>"
                 "<meta http-equiv=\"refresh\" content=\"2\"></head><body>"
                 "<h1>SHT40 Sensor Data</h1>"
                 "<p>Temperature: %.2f &deg;C</p>"
                 "<p>Humidity: %.2f %%</p>"
                 "</body></html>", temp, hum);
    }

    char response[1024];
    int n = snprintf(response, sizeof(response),
                     "HTTP/1.1 200 OK\r\n"
                     "Content-Type: text/html; charset=utf-8\r\n"
                     "Content-Length: %zu\r\n"
                     "Connection: close\r\n"
                     "\r\n"
                     "%s", strlen(html), html);

    if (n < 0 || (size_t)n >= sizeof(response)) {
        const char *e = "HTTP/1.1 500 Internal Server Error\r\n"
                        "Content-Type: text/html; charset=utf-8\r\n"
                        "Connection: close\r\n"
                        "\r\n"
                        "Internal Error";
        send(client_fd, e, strlen(e), 0);
        return;
    }

    if (send(client_fd, response, (size_t)n, 0) < 0) {
        perror("send");
    }
}

static void cleanup(void) {
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d addr 0x%02X: %s\n",
                I2C_BUS, SHT40_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket");
        cleanup();
        return EXIT_FAILURE;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(SERVER_PORT);

    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind");
        cleanup();
        return EXIT_FAILURE;
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("SHT40 sensor data server listening on port %d...\n", SERVER_PORT);

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);

        if (client_fd < 0) {
            if (errno == EINTR && !running) break;
            perror("accept");
            continue;
        }

        handle_client(client_fd);
        close(client_fd);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

