 * Board:  Raspberry Pi Zero W
 * Bus:    I2C-1 (GPIO2=SDA, GPIO3=SCL), address 0x48
 * Build:  gcc -O2 -Wall -o hdc2010 hdc2010.c -lpigpio -lrt
 * Run:    sudo ./hdc2010
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define HDC2010_ADDR        0x48
#define REG_TEMP_LOW        0x00
#define REG_HUMID_LOW       0x02
#define REG_MEAS_CONFIG     0x0E
#define REG_INT_CONFIG      0x0B
#define REG_MANUFACTURER_ID 0xFE

#define MEAS_CONFIG_TRIGGER 0x01
#define MEAS_CONFIG_MODE    0x00
#define MEAS_CONFIG_T_RES   0x00
#define MEAS_CONFIG_H_RES   0x00
#define MEAS_CONFIG_T_EN    0x01
#define MEAS_CONFIG_H_EN    0x01

#define I2C_BUS             1
#define POLL_TIMEOUT_MS     500
#define POLL_POLL_US        2000
#define SAMPLE_INTERVAL_S   5
#define MAX_RETRIES         3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

static int read_reg8(int handle, uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int write_reg8(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, val, rc);
        return -1;
    }
    return 0;
}

static int read_reg16_le(int handle, uint8_t reg, uint16_t *val)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadWordData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *val = (uint16_t)rc;
    return 0;
}

static int wait_measurement(int handle, uint32_t timeout_ms)
{
    uint32_t elapsed = 0;
    uint8_t  cfg;

    while (elapsed < timeout_ms) {
        if (read_reg8(handle, REG_MEAS_CONFIG, &cfg) < 0)
            return -1;
        if ((cfg & MEAS_CONFIG_T_EN) == 0 && (cfg & MEAS_CONFIG_H_EN) == 0)
            return 0;
        usleep(POLL_POLL_US);
        elapsed += POLL_POLL_US / 1000;
    }
    fprintf(stderr, "[WARN] Measurement timeout (%u ms)\n", timeout_ms);
    return -1;
}

static int read_hdc2010(int handle, float *temp_c, float *hum_pct)
{
    uint8_t  t_low, t_high, h_low, h_high;
    uint16_t raw_t, raw_h;

    /* Trigger a single measurement */
    if (write_reg8(handle, REG_MEAS_CONFIG, MEAS_CONFIG_T_EN | MEAS_CONFIG_H_EN) < 0)
        return -1;

    if (wait_measurement(handle, POLL_TIMEOUT_MS) < 0)
        return -1;

    if (read_reg16_le(handle, REG_TEMP_LOW, &raw_t) < 0)
        return -1;
    if (read_reg16_le(handle, REG_HUMID_LOW, &raw_h) < 0)
        return -1;

    *temp_c = ((float)raw_t / 65536.0f) * 165.0f - 40.0f;
    *hum_pct = ((float)raw_h / 65536.0f) * 100.0f;
    return 0;
}

