#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x25
#define READ_INTERVAL  500000   /* microseconds (500 ms) */
#define MEASURE_DELAY  45000    /* microseconds (45 ms) */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- Signal handler ---------------------------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- CRC-8 (Sensirion polynomial 0x31, init 0xFF) ---------------------- */
static bool crc8_check(const uint8_t *data, uint8_t len, uint8_t checksum)
{
    uint8_t crc = 0xFF;
    for (uint8_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (uint8_t b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return (crc == checksum);
}

/* ---- Read one measurement frame --------------------------------------- */
static int read_measurement(int handle, int16_t *pressure, int16_t *temperature)
{
    uint8_t buf[6];
    int bytes_read;

    /*
     * The SDP8xx family uses a continuous-measurement mode.  A master
     * write of the command byte 0x36 (read pressure) or 0x2E (read
     * pressure + temperature) triggers a measurement; the sensor then
     * returns the 6-byte frame on the next read.  We use command 0x2E
     * to get both pressure and temperature in one transaction.
     */
    uint8_t cmd = 0x2E;
    bytes_read = i2cWriteDevice(handle, (char *)&cmd, 1);
    if (bytes_read != 1) {
        fprintf(stderr, "Error: i2cWriteDevice failed (returned %d)\n", bytes_read);
        return -1;
    }

    /* Wait for the conversion to complete (datasheet: typ 36.65 ms) */
    gpioDelay(MEASURE_DELAY);

    bytes_read = i2cReadDevice(handle, (char *)buf, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error: i2cReadDevice failed (returned %d)\n", bytes_read);
        return -1;
    }

    /* Validate CRCs */
    if (!crc8_check(&buf[0], 2, buf[2])) {
        fprintf(stderr, "Error: pressure CRC mismatch\n");
        return -1;
    }
    if (!crc8_check(&buf[3], 2, buf[5])) {
        fprintf(stderr, "Error: temperature CRC mismatch\n");
        return -1;
    }

    *pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (int16_t)((buf[3] << 8) | buf[4]);
    return 0;
}

/* ---- Main -------------------------------------------------------------- */
int main(void)
{
    int16_t pressure, temperature;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle %d) — sensor may be absent\n",
                g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SDP800-500Pa reader started (I2C bus %d, addr 0x%02X). Ctrl+C to stop.\n",
           I2C_BUS, I2C_ADDR);

    while (g_running) {
        if (read_measurement(g_i2c_handle, &pressure, &temperature) == 0) {
            printf("Pressure: %d Pa, Temperature: %d °C\n",
                   pressure, temperature);
        } else {
            fprintf(stderr, "Warning: read failed, continuing...\n");
        }
        gpioDelay(READ_INTERVAL);
    }

    /* Clean shutdown */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

