#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SSR_GPIO 17
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"

#define KP 1.0
#define KI 0.1
#define KD 0.01

#define MAX_DUTY 1.0
#define MIN_DUTY 0.0

#define SAMPLE_INTERVAL_US 1000000
#define PID_PERIOD_US 1000000

#define MAX6675_CONFIG_REG 0x01
#define MAX6675_TEMP_REG 0x04
#define MAX6675_READ_BIT 0x80

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = SPI_SPEED;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl SPI_IOC_WR_MODE");
        close(spi_fd); spi_fd = -1; return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl SPI_IOC_WR_BITS_PER_WORD");
        close(spi_fd); spi_fd = -1; return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl SPI_IOC_WR_MAX_SPEED_HZ");
        close(spi_fd); spi_fd = -1; return -1;
    }
    return 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl SPI_IOC_MESSAGE");
        return -1;
    }
    return 0;
}

static int max6675_write_reg(uint8_t reg, uint8_t value) {
    uint8_t tx[2] = { (uint8_t)(reg | 0x40), value };
    uint8_t rx[2] = {0};
    return spi_transfer(tx, rx, 2);
}

static int max6675_read_temp(float *temp) {
    uint8_t tx[2] = { (uint8_t)(MAX6675_TEMP_REG | 0x40 | MAX6675_READ_BIT), 0x00 };
    uint8_t rx[2] = {0};

    if (spi_transfer(tx, rx, 2) < 0) return -1;

    uint16_t raw = ((uint16_t)rx[0] << 8) | rx[1];
    raw &= 0x3FFF;
    *temp = (float)raw * 0.25f;
    return 0;
}

static int read_profile(float *profile, int *profile_size) {
    FILE *fp = fopen(PROFILE_FILE, "r");
    if (!fp) {
        perror("fopen profile");
        return -1;
    }

    char line[256];
    *profile_size = 0;
    while (fgets(line, sizeof(line), fp)) {
        float t;
        if (sscanf(line, "%f", &t) == 1) {
            profile[*profile_size] = t;
            (*profile_size)++;
        }
    }
    fclose(fp);
    if (*profile_size < 2) {
        fprintf(stderr, "Profile file too small\n");
        return -1;
    }
    return 0;
}

static float pid_control(float setpoint, float actual, float *integral, float *prev_error, float dt) {
    float error = setpoint - actual;
    *integral += error * dt;
    float derivative = (error - *prev_error) / dt;
    float output = KP * error + KI * (*integral) + KD * derivative;
    *prev_error = error;
    if (output < MIN_DUTY) output = MIN_DUTY;
    if (output > MAX_DUTY) output = MAX_DUTY;
    return output;
}

static void log_data(float temp, float setpoint, float pid_out) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", ts, temp, setpoint, pid_out);
    fflush(log_file);
}

static void cleanup(void) {
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

