    char val[8];
    snprintf(val, sizeof(val), "%d", gpio);
    return write_file(path, val);
}

static int gpio_set_direction(int gpio, const char *dir) {
    char path[128];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", gpio);
    return write_file(path, dir);
}

static int gpio_set_value(int gpio, int value) {
    char path[128];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", gpio);
    char val[2];
    snprintf(val, sizeof(val), "%d", value);
    return write_file(path, val);
}

static int gpio_init(int gpio, const char *dir) {
    if (gpio_export(gpio) != 0) {
        fprintf(stderr, "Failed to export GPIO %d\n", gpio);
        return -1;
    }
    usleep(100000);
    if (gpio_set_direction(gpio, dir) != 0) {
        fprintf(stderr, "Failed to set GPIO %d direction\n", gpio);
        gpio_unexport(gpio);
        return -1;
    }
    return 0;
}

static int gpio_cleanup(int gpio) {
    gpio_unexport(gpio);
    return 0;
}

static int read_temperature(float *temp) {
    char path[256];
    char buf[256];
    snprintf(path, sizeof(path), "%s/%s/w1_slave", W1_DEVICES_DIR, W1_SLAVE_FILE);
    if (read_file(path, buf, sizeof(buf)) != 0) {
        fprintf(stderr, "Failed to read DS18B20 data\n");
        return -1;
    }
    if (strstr(buf, "YES") == NULL) {
        fprintf(stderr, "DS18B20 CRC check failed\n");
        return -1;
    }
    char *t = strstr(buf, "t=");
    if (t == NULL) {
        fprintf(stderr, "Temperature data not found in DS18B20 output\n");
        return -1;
    }
    long raw = strtol(t + 2, NULL, 10);
    *temp = (float)raw / 1000.0f;
    return 0;
}

static void log_data(float avg_temp, float setpoint, float pid_out, int duty_cycle) {
    time_t now = time(NULL);
    struct tm tm_info;
    localtime_r(&now, &tm_info);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(g_log_fp, "%s,%.2f,%.2f,%.2f,%d\n", ts, avg_temp, setpoint, pid_out, duty_cycle);
    fflush(g_log_fp);
}

static void cleanup(void) {
    gpio_set_value(RELAY_GPIO, 0);
    pwm_set_duty(0);
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    pwm_cleanup();
}

int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki>\n", argv[0]);
        return 1;
    }
    float setpoint = atof(argv[1]);
    float Kp = atof(argv[2]);
    float Ki = atof(argv[3]);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpio_init(RELAY_GPIO, "out") != 0) return 1;
    if (gpio_init(PWM_GPIO, "out") != 0) {
        gpio_cleanup(RELAY_GPIO);
        return 1;
    }
    if (pwm_init() != 0) {
        gpio_cleanup(PWM_GPIO);
        gpio_cleanup(RELAY_GPIO);
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return 1;
    }

    float integral = 0.0f;
    float prev_error = 0.0f;
    int relay_state = 0;

    while (g_running) {
        float temp;
        if (read_temperature(&temp) != 0) {
            fprintf(stderr, "Sensor read error; skipping cycle\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        float pid_out = Kp * (setpoint - temp) + integral * (setpoint - temp) + Ki * (setpoint - temp);
        int duty = (int)pid_out;
        if (duty < 0) duty = 0;
        if (duty > 100) duty = 100;

        if (pwm_set_duty(duty * PWM_PERIOD_NS / 100) != 0) {
            fprintf(stderr, "PWM write failed\n");
        }

        if (duty > 0) {
            if (relay_state == 0) {
                if (gpio_set_value(RELAY_GPIO, 1) != 0) {
                    fprintf(stderr, "Failed to set relay HIGH\n");
                } else {
                    relay_state = 1;
                }
            }
        } else {
            if (relay_state == 1) {
                if (gpio_set_value(RELAY_GPIO, 0) != 0) {
                    fprintf(stderr, "Failed to set relay LOW\n");
                } else {
                    relay_state = 0;
                }
            }
        }

        integral += (setpoint - temp);
        prev_error = setpoint - temp;

        float avg = 0.0f;
        int count = 0;
        char path[256];
        char buf[256];
        snprintf(path, sizeof(path), "%s/%s/w1_slave", W1_DEVICES_DIR, W1_SLAVE_FILE);
        while (count < SAMPLE_INTERVAL && g_running) {
            if (read_file(path, buf, sizeof(buf)) == 0) {
                if (strstr(buf, "YES") != NULL) {
                    float t;
                    if (read_temperature(&t) == 0) {
                        avg += t;
                        count++;
                    }
                }
            }
            sleep(1);
        }
        if (count > 0) {
            avg /= count;
            log_data(avg, setpoint, pid_out, duty);
        }
    }

    cleanup();
    return 0;
}

