/*
 * AHT20 humidity monitor with dehumidifier relay control on Raspberry Pi 5.
 *
 * Wiring:
 *   AHT20 SDA -> GPIO2 (I2C1 SDA)
 *   AHT20 SCL -> GPIO3 (I2C1 SCL)
 *   AHT20 VDD -> 3.3 V
 *   AHT20 GND -> GND
 *   Relay IN  -> GPIO17 (active-high)
 *   Relay VCC -> 3.3 V or 5 V (per relay module spec)
 *   Relay GND -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o aht20_monitor aht20_monitor.c -lpigpio -lrt
 * Run:    sudo ./aht20_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS          "/dev/i2c-1"
#define AHT20_ADDR       0x38
#define AHT20_REG_ID     0x0C
#define AHT20_REG_STATUS 0x00
#define AHT20_REG_DATA   0x07
#define AHT20_CMD_MEASURE 0xAC

#define GPIO_RELAY       17
#define HUMIDITY_HIGH    60.0f
#define HUMIDITY_LOW     55.0f
#define POLL_INTERVAL_S  5
#define MEASURE_DELAY_MS 80
#define MAX_RETRIES      3
#define RETRY_DELAY_MS   10

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        if (write(fd, buf, sizeof(buf)) == (ssize_t)sizeof(buf))
            return 0;
        fprintf(stderr, "I2C write to reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, attempt + 1, MAX_RETRIES, strerror(errno));
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "I2C write (reg select 0x%02X) failed (attempt %d/%d): %s\n",
                    reg, attempt + 1, MAX_RETRIES, strerror(errno));
            if (attempt < MAX_RETRIES - 1)
                gpioDelay(RETRY_DELAY_MS * 1000);
            continue;
        }
        ssize_t n = read(fd, buf, len);
        if (n == (ssize_t)len)
            return 0;
        fprintf(stderr, "I2C read from reg 0x%02X failed (attempt %d/%d): got %zd of %zu (%s)\n",
                reg, attempt + 1, MAX_RETRIES, n, len,
                n < 0 ? strerror(errno) : "short read");
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* AHT20 sensor                                                        */
/* ------------------------------------------------------------------ */
static int aht20_read_humidity(int fd, float *humidity)
{
    uint8_t status = 0;
    uint8_t data[6];

    /* Trigger measurement */
    if (i2c_write_byte(fd, AHT20_REG_ID, AHT20_CMD_MEASURE) != 0)
        return -1;

    gpioDelay(MEASURE_DELAY_MS * 1000);

    /* Read status byte */
    if (i2c_read_block(fd, AHT20_REG_STATUS, &status, 1) != 0)
        return -1;

    /* Bit 7 = busy, bit 6 = calibrated */
    if ((status & 0xC0) != 0x80) {
        fprintf(stderr, "AHT20 not calibrated or still busy (status=0x%02X)\n", status);
        return -1;
    }

    /* Read 6 bytes: [status][hum_msb][hum_lsb][temp_msb][temp_lsb][crc] */
    if (i2c_read_block(fd, AHT20_REG_DATA, data, sizeof(data)) != 0)
        return -1;

    uint16_t raw_hum = ((uint16_t)data[1] << 8) | data[0];
    *humidity = (float)raw_hum / 1024.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Relay control                                                       */
/* ------------------------------------------------------------------ */
static void relay_set(int state)
{
    if (gpioWrite(GPIO_RELAY, state) != 0)
        fprintf(stderr, "Warning: gpioWrite(%d) failed\n", GPIO_RELAY);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_humidity(float humidity)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] Humidity: %.2f %%\n", ts, humidity);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioWrite(GPIO_RELAY, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* pigpio init */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Relay pin */
    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", GPIO_RELAY);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_RELAY, 0);

    /* I2C open */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                AHT20_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Verify sensor presence by reading the ID register */
    uint8_t id = 0;
    if (i2c_read_block(g_i2c_fd, AHT20_REG_ID, &id, 1) != 0) {
        fprintf(stderr, "AHT20 not detected at address 0x%02X on %s\n",
                AHT20_ADDR, I2C_BUS);
        cleanup();
        return EXIT_FAILURE;
    }
    printf("AHT20 detected (ID=0x%02X). Polling every %d s.\n", id, POLL_INTERVAL_S);

    bool relay_on = false;

    while (g_running) {
        float humidity = 0.0f;

        if (aht20_read_humidity(g_i2c_fd, &humidity) == 0) {
            log_humidity(humidity);

            if (humidity > HUMIDITY_HIGH && !relay_on) {
                relay_set(1);
                relay_on = true;
                printf("Dehumidifier ON (humidity %.2f %%)\n", humidity);
            } else if (humidity < HUMIDITY_LOW && relay_on) {
                relay_set(0);
                relay_on = false;
                printf("Dehumidifier OFF (humidity %.2f %%)\n", humidity);
            }
        } else {
            fprintf(stderr, "Failed to read humidity from AHT20\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_S * 10 && g_running; ++i)
            gpioDelay(100 * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

