#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <stdint.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/socket.h>

#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x2C
#define API_ENDPOINT "http://api.example.com/humidity"
#define POLL_INTERVAL 60
#define MEASUREMENT_DELAY_MS 20

#define CMD_TEMP_HOLD   0xE3
#define CMD_HUMID_HOLD  0xE5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_measurement(int fd, uint8_t cmd, uint16_t *raw) {
    if (write(fd, &cmd, 1) != 1) {
        syslog(LOG_ERR, "I2C write failed for cmd 0x%02X: %s", cmd, strerror(errno));
        return -1;
    }
    usleep(MEASUREMENT_DELAY_MS * 1000);

    uint8_t buf[3];
    ssize_t n = read(fd, buf, 3);
    if (n != 3) {
        syslog(LOG_ERR, "I2C read failed for cmd 0x%02X (got %zd bytes): %s", cmd, n, strerror(errno));
        return -1;
    }

    uint16_t crc = (buf[0] << 8) | buf[1];
    uint16_t data = (buf[1] << 8) | buf[2];
    if (crc != ((crc >> 8) ^ data) + 1) {
        syslog(LOG_ERR, "CRC mismatch for cmd 0x%02X: calc=0x%04X recv=0x%04X", cmd, crc, data);
        return -1;
    }
    *raw = data;
    return 0;
}

static float read_humidity(int fd) {
    uint16_t raw;
    if (i2c_read_measurement(fd, CMD_HUMID_HOLD, &raw) != 0) {
        return -1.0f;
    }
    return (125.0f * raw / 65536.0f) - 6.0f;
}

static int post_humidity(float humidity) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        syslog(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        return -1;
    }

    struct sockaddr_in servaddr;
    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(80);
    if (inet_pton(AF_INET, "192.168.1.100", &servaddr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        syslog(LOG_ERR, "Connection to %s failed: %s", API_ENDPOINT, strerror(errno));
        close(sockfd);
        return -1;
    }

    char request[256];
    int req_len = snprintf(request, sizeof(request),
        "POST %s HTTP/1.1\r\n"
        "Host: api.example.com\r\n"
        "Content-Type: application/json\r\n"
        "Content-Length: 16\r\n"
        "Connection: close\r\n"
        "\r\n"
        "{\"humidity\": %.2f}",
        API_ENDPOINT, humidity);

    if (req_len < 0 || (size_t)req_len >= sizeof(request)) {
        syslog(LOG_ERR, "Request buffer too small");
        close(sockfd);
        return -1;
    }

    ssize_t sent = 0;
    while (sent < req_len) {
        ssize_t w = write(sockfd, request + sent, req_len - sent);
        if (w < 0) {
            if (errno == EINTR) continue;
            syslog(LOG_ERR, "HTTP write failed: %s", strerror(errno));
            close(sockfd);
            return -1;
        }
        sent += w;
    }

    char response[1024];
    ssize_t r = read(sockfd, response, sizeof(response) - 1);
    if (r < 0) {
        syslog(LOG_ERR, "HTTP read failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }
    response[r] = '\0';

    int status_code = 0;
    if (sscanf(response, "HTTP/1.%*d %d", &status_code) != 1) {
        syslog(LOG_ERR, "Invalid HTTP response: %s", response);
        close(sockfd);
        return -1;
    }

    if (status_code != 200) {
        syslog(LOG_ERR, "HTTP POST returned status %d", status_code);
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

int main(void) {
    openlog("humidity_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set signal handlers: %s", strerror(errno));
        closelog();
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open %s: %s", I2C_BUS, strerror(errno));
        closelog();
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address 0x%02X: %s", HTU21D_ADDR, strerror(errno));
        close(fd);
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "HTU21D monitor started on %s (addr 0x%02X)", I2C_BUS, HTU21D_ADDR);

    while (running) {
        float humidity = read_humidity(fd);
        if (humidity >= 0.0f) {
            syslog(LOG_INFO, "Humidity: %.2f%%", humidity);
            if (post_humidity(humidity) != 0) {
                syslog(LOG_ERR, "Failed to post humidity data");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity");
        }

        for (int i = 0; i < POLL_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    syslog(LOG_INFO, "Shutting down gracefully");
    close(fd);
    closelog();
    return 0;
}

