#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_REG_CHIP_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_CALIB_00 0x88
#define BMP280_CHIP_ID 0x58
#define PRESSURE_THRESHOLD_HIGH 1020.0
#define PRESSURE_THRESHOLD_LOW 980.0
#define SAMPLE_INTERVAL_SEC 2
#define CONVERSION_DELAY_US 10000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

static bmp280_calib_data calib;
static int32_t t_fine;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration_data(int handle, bmp280_calib_data *cal) {
    uint8_t data[24];
    if (i2cReadI2CBlockData(handle, BMP280_REG_CALIB_00, (char *)data, 24) != 24) {
        fprintf(stderr, "Error: Failed to read calibration data\n");
        return -1;
    }
    cal->dig_T1 = (uint16_t)(data[0] | (data[1] << 8));
    cal->dig_T2 = (int16_t)(data[2] | (data[3] << 8));
    cal->dig_T3 = (int16_t)(data[4] | (data[5] << 8));
    cal->dig_P1 = (uint16_t)(data[6] | (data[7] << 8));
    cal->dig_P2 = (int16_t)(data[8] | (data[9] << 8));
    cal->dig_P3 = (int16_t)(data[10] | (data[11] << 8));
    cal->dig_P4 = (int16_t)(data[12] | (data[13] << 8));
    cal->dig_P5 = (int16_t)(data[14] | (data[15] << 8));
    cal->dig_P6 = (int16_t)(data[16] | (data[17] << 8));
    cal->dig_P7 = (int16_t)(data[18] | (data[19] << 8));
    cal->dig_P8 = (int16_t)(data[20] | (data[21] << 8));
    cal->dig_P9 = (int16_t)(data[22] | (data[23] << 8));
    return 0;
}

static int read_raw_data(int handle, int32_t *raw_press, int32_t *raw_temp) {
    uint8_t data[6];
    if (i2cReadI2CBlockData(handle, BMP280_REG_PRESS_MSB, (char *)data, 6) != 6) {
        fprintf(stderr, "Error: Failed to read raw data\n");
        return -1;
    }
    *raw_press = (int32_t)((data[0] << 12) | (data[1] << 4) | (data[2] >> 4));
    *raw_temp = (int32_t)((data[3] << 12) | (data[4] << 4) | (data[5] >> 4));
    return 0;
}

static double compensate_temperature(int32_t raw_temp) {
    double var1 = ((double)raw_temp / 16384.0 - (double)calib.dig_T1 / 1024.0) * (double)calib.dig_T2;
    double var2 = ((double)raw_temp / 131072.0 - (double)calib.dig_T1 / 8192.0) *
                 ((double)raw_temp / 131072.0 - (double)calib.dig_T1 / 8192.0) * (double)calib.dig_T3;
    t_fine = (int32_t)(var1 + var2);
    return (var1 + var2) / 5120.0;
}

static double compensate_pressure(int32_t raw_press) {
    double var1 = (double)t_fine / 2.0 - 64000.0;
    double var2 = var1 * var1 * (double)calib.dig_P6 / 32768.0;
    var2 = var2 + var1 * (double)calib.dig_P5 * 2.0;
    var2 = (var2 / 4.0) + ((double)calib.dig_P4 * 65536.0);
    var1 = ((double)calib.dig_P3 * var1 * var1 / 524288.0 + (double)calib.dig_P2 * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * (double)calib.dig_P1;
    if (var1 == 0.0) return 0.0;
    double p = 1048576.0 - (double)raw_press;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = (double)calib.dig_P9 * p * p / 2147483648.0;
    var2 = p * (double)calib.dig_P8 / 32768.0;
    p = p + (var1 + var2 + (double)calib.dig_P7) / 16.0;
    return p;
}

static int log_pressure(double pressure) {
    FILE *fp = fopen("pressure_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open pressure_log.txt\n");
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, %.2f\n", ts, pressure);
    fclose(fp);
    return 0;
}

static int init_bmp280(void) {
    if (i2cWriteByteData(i2c_handle, BMP280_REG_RESET, 0xB6) < 0) {
        fprintf(stderr, "Error: Failed to reset BMP280\n");
        return -1;
    }
    gpioDelay(2000);
    int chip_id = i2cReadByteData(i2c_handle, BMP280_REG_CHIP_ID);
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x%02X)\n", chip_id, BMP280_CHIP_ID);
        return -1;
    }
    if (read_calibration_data(i2c_handle, &calib) != 0) return -1;
    if (i2cWriteByteData(i2c_handle, BMP280_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write config register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, BMP280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error: Failed to write ctrl_meas register\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at 0x%02X\n", BMP280_I2C_ADDR);
        gpioTerminate();
        return 1;
    }
    if (init_bmp280() != 0) {
        fprintf(stderr, "Error: BMP280 initialisation failed\n");
        cleanup();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    int retries = 0;
    while (running) {
        int32_t raw_press, raw_temp;
        if (read_raw_data(i2c_handle, &raw_press, &raw_temp) == 0) {
            double temp = compensate_temperature(raw_temp);
            double press = compensate_pressure(raw_press);
            if (press > PRESSURE_THRESHOLD_HIGH || press < PRESSURE_THRESHOLD_LOW) {
                if (log_pressure(press) != 0) {
                    fprintf(stderr, "Warning: Failed to log pressure\n");
                }
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor data. Retrying...\n");
            if (retries < MAX_RETRIES) {
                i2cClose(i2c_handle);
                i2c_handle = -1;
                gpioDelay(1000000);
                i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
                if (i2c_handle < 0) {
                    fprintf(stderr, "Error: Failed to reopen I2C bus\n");
                } else if (init_bmp280() != 0) {
                    fprintf(stderr, "Error: BMP280 reinitialisation failed\n");
                }
                retries++;
            } else {
                fprintf(stderr, "Error: Max retries reached. Exiting.\n");
                break;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000);
    }
    cleanup();
    return 0;
}

