/*
 * Raspberry Pi 4B environmental logger.
 *
 * Sensors:
 *   - TMP117 temperature sensor  (I2C 0x48, bus /dev/i2c-1)
 *   - AHT20 humidity/temperature sensor (I2C 0x38, bus /dev/i2c-1)
 *   - PIR motion sensor (GPIO17, gpiochip4 line 17, input)
 *
 * Build: gcc -o logger logger.c -lgpiod -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS          "/dev/i2c-1"
#define TMP117_ADDR      0x48
#define AHT20_ADDR       0x38
#define PIR_GPIO_CHIP    "gpiochip4"
#define PIR_GPIO_LINE    17
#define LOG_FILE_PREFIX "env_log_"
#define SAMPLE_INTERVAL  1
#define MAX_RETRIES      3
#define RETRY_DELAY_MS   10

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a 16-bit big-endian register from an I2C device with retries.
 * Returns 0 on success and stores the value in *out; -1 on failure.
 */
static int i2c_read_reg16(int fd, uint8_t reg, int *out)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "I2C write reg 0x%02X failed (attempt %d/%d): %s\n",
                    reg, attempt + 1, MAX_RETRIES, strerror(errno));
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        uint8_t buf[2];
        ssize_t n = read(fd, buf, 2);
        if (n != 2) {
            fprintf(stderr, "I2C read reg 0x%02X failed (attempt %d/%d): got %zd bytes: %s\n",
                    reg, attempt + 1, MAX_RETRIES, n, n < 0 ? strerror(errno) : "short read");
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        *out = (buf[0] << 8) | buf[1];
        return 0;
    }
    return -1;
}

/*
 * Read temperature from TMP117.
 * Returns 0 on success and stores Celsius in *temp; -1 on failure.
 */
static int read_temperature(int fd, float *temp)
{
    int raw;
    if (i2c_read_reg16(fd, 0x00, &raw) != 0)
        return -1;
    *temp = (float)raw / 100.0f;
    return 0;
}

/*
 * Read humidity from AHT20.
 * Returns 0 on success and stores %RH in *hum; -1 on failure.
 */
static int read_humidity(int fd, float *hum)
{
    int raw;
    if (i2c_read_reg16(fd, 0x07, &raw) != 0)
        return -1;
    *hum = (float)raw / 1024.0f;
    return 0;
}

/*
 * Read motion state from PIR sensor via gpiod.
 * Returns 1 if motion detected, 0 if not, -1 on error.
 */
static int read_motion(struct gpiod_line *line)
{
    int val = gpiod_line_get_value(line);
    if (val < 0)
        fprintf(stderr, "PIR read failed: %s\n", strerror(errno));
    return val;
}

/*
 * Open a daily log file.
 * Returns a valid fd on success, -1 on failure.
 */
static int open_log_file(void)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (!t) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    char filename[64];
    snprintf(filename, sizeof(filename), "%s%04d%02d%02d.csv",
             LOG_FILE_PREFIX, t->tm_year + 1900, t->tm_mon + 1, t->tm_mday);

    int fd = open(filename, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", filename, strerror(errno));
        return -1;
    }

    /* Write header only if the file is empty */
    if (lseek(fd, 0, SEEK_END) == 0) {
        const char *header = "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n";
        if (write(fd, header, strlen(header)) != (ssize_t)strlen(header)) {
            fprintf(stderr, "write header failed: %s\n", strerror(errno));
            close(fd);
            return -1;
        }
    }

    return fd;
}

/*
 * Log a data record to the open file fd.
 * Returns 0 on success, -1 on failure.
 */
static int log_data(int fd, float temp, float hum, int motion)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (!t) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    char line[128];
    int len = snprintf(line, sizeof(line), "%s,%.2f,%.2f,%d\n",
                       ts, temp, hum, motion);
    if (len < 0 || (size_t)len >= sizeof(line)) {
        fprintf(stderr, "snprintf failed or truncated\n");
        return -1;
    }

    if (write(fd, line, len) != len) {
        fprintf(stderr, "write to log failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire TMP117 and AHT20 */
    if (ioctl(i2c_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                TMP117_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                AHT20_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Open PIR GPIO line via gpiod */
    struct gpiod_chip *chip = gpiod_chip_open_by_name(PIR_GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s) failed: %s\n",
                PIR_GPIO_CHIP, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *pir_line = gpiod_chip_get_line(chip, PIR_GPIO_LINE);
    if (!pir_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                PIR_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(pir_line, "pir-sensor") < 0) {
        fprintf(stderr, "gpiod_line_request_input failed: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Open initial log file */
    int log_fd = open_log_file();
    if (log_fd < 0) {
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Environmental logger started. Logging to %s\n",
           log_fd >= 0 ? "current log file" : "no log file");

    /* Main sampling loop */
    while (g_running) {
        float temp = 0.0f, hum = 0.0f;
        int motion = 0;
        int ok = 1;

        if (read_temperature(i2c_fd, &temp) != 0)
            ok = 0;
        if (read_humidity(i2c_fd, &hum) != 0)
            ok = 0;
        if (read_motion(pir_line) != 0)
            ok = 0;

        if (ok) {
            if (log_data(log_fd, temp, hum, motion) != 0)
                fprintf(stderr, "Logging failed; continuing.\n");
        } else {
            fprintf(stderr, "Sensor read failure; skipping log entry.\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    /* Cleanup */
    if (log_fd >= 0)
        close(log_fd);
    gpiod_line_release(pir_line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    printf("Logger stopped.\n");
    return EXIT_SUCCESS;
}

