#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27
#define PWM_RANGE 255
#define SAMPLE_US 500000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_cpu_load(void) {
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        fprintf(stderr, "Error opening /proc/stat: %s\n", strerror(errno));
        return -1;
    }

    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    int matched = fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
                         &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice);
    fclose(fp);

    if (matched != 10) {
        fprintf(stderr, "Error parsing /proc/stat (got %d fields)\n", matched);
        return -1;
    }

    static unsigned long long prev_total = 0;
    static unsigned long long prev_idle = 0;

    unsigned long long total = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;
    unsigned long long idle_total = idle + iowait;

    if (prev_total == 0) {
        prev_total = total;
        prev_idle = idle_total;
        return 0;
    }

    unsigned long long total_diff = total - prev_total;
    unsigned long long idle_diff  = idle_total - prev_idle;

    if (total_diff == 0) return 0;

    float load = (float)(total_diff - idle_diff) / total_diff * 100.0f;
    if (load > 100.0f) load = 100.0f;
    if (load < 0.0f)   load = 0.0f;

    prev_total = total;
    prev_idle  = idle_total;
    return (int)(load + 0.5f);
}

static void set_rgb(int r, int g, int b) {
    /* Common-anode: invert values (0 = full on, 255 = off) */
    gpioPWM(RED_PIN,   PWM_RANGE - r);
    gpioPWM(GREEN_PIN, PWM_RANGE - g);
    gpioPWM(BLUE_PIN,  PWM_RANGE - b);
}

static void led_off(void) {
    /* Common-anode: all channels off = full brightness */
    gpioPWM(RED_PIN,   PWM_RANGE);
    gpioPWM(GREEN_PIN, PWM_RANGE);
    gpioPWM(BLUE_PIN,  PWM_RANGE);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(RED_PIN,   PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN,  PI_OUTPUT);

    gpioSetPWMrange(RED_PIN,   PWM_RANGE);
    gpioSetPWMrange(GREEN_PIN, PWM_RANGE);
    gpioSetPWMrange(BLUE_PIN,  PWM_RANGE);

    led_off();

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        led_off();
        gpioTerminate();
        return 1;
    }

    while (running) {
        int load = read_cpu_load();
        if (load < 0) {
            led_off();
            gpioTerminate();
            return 1;
        }

        int r, g, b;
        if (load < 50) {
            r = (load * 255) / 100;
            g = 255;
            b = 0;
        } else {
            r = 255;
            g = (255 - (load - 50) * 255) / 50;
            b = 0;
        }

        set_rgb(r, g, b);
        usleep(SAMPLE_US);
    }

    led_off();
    gpioTerminate();
    return 0;
}

