#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>

#define BMP280_I2C_ADDR 0x76
#define I2C_BUS "/dev/i2c-1"
#define UDP_IP "192.168.1.100"
#define UDP_PORT 5000
#define SAMPLE_INTERVAL_SEC 5

#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_PRESSURE_MSB 0xF7
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_ID 0xD0

#define BMP280_CHIP_ID 0x58
#define BMP280_RESET_CMD 0xB6

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int udp_sock = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_reg16_le(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (uint16_t)buf[1] << 8 | buf[0];
    return 0;
}

static int bmp280_init(int fd) {
    uint8_t id;
    if (i2c_read_reg8(fd, BMP280_REG_ID, &id) < 0) {
        fprintf(stderr, "Error reading chip ID: %s\n", strerror(errno));
        return -1;
    }
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "Invalid chip ID: 0x%02X (expected 0x%02X)\n", id, BMP280_CHIP_ID);
        return -1;
    }

    if (i2c_write_reg8(fd, BMP280_REG_RESET, BMP280_RESET_CMD) < 0) {
        fprintf(stderr, "Error resetting BMP280: %s\n", strerror(errno));
        return -1;
    }
    usleep(2000);

    uint8_t config = (0x04 << 5) | (0x02 << 2) | 0x00; // t_sb=0.5ms, filter=4, spi3w_en=0
    if (i2c_write_reg8(fd, BMP280_REG_CONFIG, config) < 0) {
        fprintf(stderr, "Error writing config register: %s\n", strerror(errno));
        return -1;
    }

    uint8_t ctrl_meas = (0x02 << 5) | (0x05 << 2) | 0x00; // osrs_t=x1, osrs_p=x1, mode=normal
    if (i2c_write_reg8(fd, BMP280_REG_CTRL_MEAS, ctrl_meas) < 0) {
        fprintf(stderr, "Error writing ctrl_meas register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int bmp280_read_data(int fd, float *temperature, float *pressure) {
    uint8_t data[6];
    uint8_t reg = BMP280_REG_PRESSURE_MSB;

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error setting read pointer: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, data, 6) != 6) {
        fprintf(stderr, "Error reading data: %s\n", strerror(errno));
        return -1;
    }

    uint32_t raw_pressure = ((uint32_t)data[0] << 12) | ((uint32_t)data[1] << 4) | ((uint32_t)data[2] >> 4);
    uint32_t raw_temp = ((uint32_t)data[3] << 12) | ((uint32_t)data[4] << 4) | ((uint32_t)data[5] >> 4);

    *temperature = ((float)raw_temp / 1048576.0f) - 273.15f;
    *pressure = ((float)raw_pressure / 1048576.0f) * 100.0f;

    return 0;
}

static int send_udp_data(const char *data) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(UDP_PORT);
    if (inet_pton(AF_INET, UDP_IP, &addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address: %s\n", UDP_IP);
        return -1;
    }

    if (sendto(udp_sock, data, strlen(data), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "Error sending UDP data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C address 0x%02X: %s\n", BMP280_I2C_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (bmp280_init(i2c_fd) < 0) {
        fprintf(stderr, "BMP280 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    udp_sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_sock < 0) {
        fprintf(stderr, "Error creating UDP socket: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    while (running) {
        float temperature, pressure;

        if (bmp280_read_data(i2c_fd, &temperature, &pressure) == 0) {
            char json_data[128];
            snprintf(json_data, sizeof(json_data), "{\"temperature\":%.2f,\"pressure\":%.2f}", temperature, pressure);

            if (send_udp_data(json_data) < 0) {
                fprintf(stderr, "Failed to send UDP data.\n");
            } else {
                printf("Sent: %s\n", json_data);
            }
        } else {
            fprintf(stderr, "Failed to read BMP280 data.\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    if (i2c_fd >= 0) close(i2c_fd);
    if (udp_sock >= 0) close(udp_sock);
    return 0;
}

