#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO          18
#define SPI_CHANNEL       0
#define SPI_SPEED         500000
#define PWM_FREQUENCY     1000
#define PWM_RANGE         255
#define BUFFER_SIZE       20
#define SAMPLE_PERIOD_US  1000000

#define TEMP_THRESHOLD_1 25.0f
#define TEMP_THRESHOLD_2 40.0f
#define TEMP_THRESHOLD_3 60.0f

typedef struct {
    time_t timestamp;
    float  temperature;
    int    duty_cycle;
} TemperatureData;

static TemperatureData temperature_buffer[BUFFER_SIZE];
static int               buffer_index = 0;

static volatile sig_atomic_t program_running = 1;
static int               spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void add_to_buffer(time_t timestamp, float temperature, int duty_cycle) {
    temperature_buffer[buffer_index].timestamp          = timestamp;
    temperature_buffer[buffer_index].temperature        = temperature;
    temperature_buffer[buffer_index].duty_cycle         = duty_cycle;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void print_buffer(void) {
    printf("\n--- Temperature Data Log ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (buffer_index + i) % BUFFER_SIZE;
        char time_str[32];
        struct tm *tm_info = localtime(&temperature_buffer[idx].timestamp);
        if (tm_info) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        } else {
            snprintf(time_str, sizeof(time_str), "<invalid>");
        }
        printf("[%s] Temp: %.2f C, Duty: %d\n", time_str,
               temperature_buffer[idx].temperature,
               temperature_buffer[idx].duty_cycle);
    }
    printf("--- End of Log ---\n\n");
}

static int calculate_duty_cycle(float temperature) {
    if (temperature < TEMP_THRESHOLD_1) {
        return 0;
    } else if (temperature < TEMP_THRESHOLD_2) {
        return (int)((temperature - TEMP_THRESHOLD_1) * 50.0f);
    } else if (temperature < TEMP_THRESHOLD_3) {
        return (int)((temperature - TEMP_THRESHOLD_2) * 150.0f + 50.0f);
    } else {
        return 255;
    }
}

static int set_fan_speed(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    if (gpioPWM(FAN_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "Error: gpioPWM failed for duty cycle %d\n", duty_cycle);
        return -1;
    }
    return 0;
}

static int read_temperature(float *temperature) {
    char tx_buf[4] = {0, 0, 0, 0};
    char rx_buf[4] = {0, 0, 0, 0};

    if (spiXfer(spi_handle, tx_buf, rx_buf, 4) != 4) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx_buf[0] << 24) |
                   ((uint32_t)(uint8_t)rx_buf[1] << 16) |
                   ((uint32_t)(uint8_t)rx_buf[2] << 8)  |
                   ((uint32_t)(uint8_t)rx_buf[3]);

    if (raw & 0x00010000) {
        fprintf(stderr, "Error: MAX31855 fault detected (raw=0x%08X)\n", raw);
        return -1;
    }

    int16_t temp_raw = (int16_t)(raw >> 18);
    *temperature = (float)temp_raw * 0.25f;
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for FAN_GPIO\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }

    printf("Temperature monitoring and fan control started.\n");
    printf("SPI channel %d, %d Hz, Fan PWM on GPIO%d (%d Hz, range %d).\n",
           SPI_CHANNEL, SPI_SPEED, FAN_GPIO, PWM_FREQUENCY, PWM_RANGE);
    printf("Press Ctrl+C to exit.\n\n");

    while (program_running) {
        float temperature = 0.0f;

        if (read_temperature(&temperature) != 0) {
            fprintf(stderr, "Error: Temperature read failed, skipping cycle.\n");
        } else {
            int duty_cycle = calculate_duty_cycle(temperature);
            if (set_fan_speed(duty_cycle) != 0) {
                fprintf(stderr, "Error: Fan speed set failed, skipping cycle.\n");
            } else {
                time_t now = time(NULL);
                add_to_buffer(now, temperature, duty_cycle);
                printf("Temp: %.2f C, Duty: %d/%d  | ", temperature, duty_cycle, PWM_RANGE);
                fflush(stdout);
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    print_buffer();
    cleanup();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

