#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR 0x76
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define OSS 3

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t logging_active = 0;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) return -1;
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_write_reg8(int handle, uint8_t reg, uint8_t val) {
    return i2cWriteByteData(handle, reg, val);
}

static int i2c_read_reg16(int handle, uint8_t reg, int16_t *val) {
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) return -1;
    *val = (int16_t)rc;
    return 0;
}

static int i2c_read_reg16u(int handle, uint8_t reg, uint16_t *val) {
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) return -1;
    *val = (uint16_t)rc;
    return 0;
}

static int read_calibration_data(void) {
    if (i2c_read_reg16(i2c_handle, BMP180_REG_CAL_AC1, &ac1) < 0) return -1;
    if (i2c_read_reg16(i2c_handle, BMP180_REG_CAL_AC2, &ac2) < 0) return -1;
    if (i2c_read_reg16(i2c_handle, BMP180_REG_CAL_AC3, &ac3) < 0) return -1;
    if (i2c_read_reg16u(i2c_handle, BMP180_REG_CAL_AC4, &ac4) < 0) return -1;
    if (i2c_read_reg16u(i2c_handle, BMP180_REG_CAL_AC5, &ac5) < 0) return -1;
    if (i2c_read_reg16u(i2c_handle, BMP180_REG_CAL_AC6, &ac6) < 0) return -1;
    if (i2c_read_reg16(i2c_handle, BMP180_REG_CAL_B1, &b1) < 0) return -1;
    if (i2c_read_reg16(i2c_handle, BMP180_REG_CAL_B2, &b2) < 0) return -1;
    if (i2c_read_reg16(i2c_handle, BMP180_REG_CAL_MB, &mb) < 0) return -1;
    if (i2c_read_reg16(i2c_handle, BMP180_REG_CAL_MC, &mc) < 0) return -1;
    if (i2c_read_reg16(i2c_handle, BMP180_REG_CAL_MD, &md) < 0) return -1;
    return 0;
}

static int read_raw_temperature(int32_t *ut) {
    if (i2c_write_reg8(i2c_handle, BMP180_REG_CONTROL, 0x2E) < 0) return -1;
    gpioDelay(5000);
    int rc = i2cReadWordData(i2c_handle, BMP180_REG_MSB);
    if (rc < 0) return -1;
    *ut = (int32_t)rc;
    return 0;
}

static int read_raw_pressure(int32_t *up) {
    if (i2c_write_reg8(i2c_handle, BMP180_REG_CONTROL, 0x34 + (OSS << 6)) < 0) return -1;
    gpioDelay(2000 + (3000 << OSS));
    int rc = i2cReadWordData(i2c_handle, BMP180_REG_MSB);
    if (rc < 0) return -1;
    *up = (int32_t)rc;
    return 0;
}

static int calculate_b5(int32_t ut, int32_t *b5_out) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    *b5_out = b5;
    return 0;
}

static int read_temperature(float *temp) {
    int32_t ut, b5;
    if (read_raw_temperature(&ut) < 0) return -1;
    if (calculate_b5(ut, &b5) < 0) return -1;
    int32_t t = (b5 + 8) >> 4;
    *temp = (float)t / 10.0f;
    return 0;
}

static int read_pressure(float *press) {
    int32_t up, b5;
