#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BME280_I2C_ADDR 0x76
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "bme280_log.csv"

#define BME280_REG_ID 0xD0
#define BME280_REG_RESET 0xE0
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_STATUS 0xF3
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_DATA 0xF7

#define BME280_CHIP_ID 0x60
#define BME280_RESET_CMD 0xB6

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int bme280_init(int fd) {
    uint8_t id;
    if (i2c_read_reg(fd, BME280_REG_ID, &id) < 0) {
        fprintf(stderr, "Error: Failed to read chip ID.\n");
        return -1;
    }
    if (id != BME280_CHIP_ID) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x%02X).\n", id, BME280_CHIP_ID);
        return -1;
    }

    if (i2c_write_reg(fd, BME280_REG_RESET, BME280_RESET_CMD) < 0) {
        fprintf(stderr, "Error: Failed to reset sensor.\n");
        return -1;
    }
    usleep(2000);

    uint8_t status;
    int retries = 10;
    do {
        if (i2c_read_reg(fd, BME280_REG_STATUS, &status) < 0) {
            fprintf(stderr, "Error: Failed to read status register.\n");
            return -1;
        }
        if (--retries == 0) {
            fprintf(stderr, "Error: Sensor not ready after reset.\n");
            return -1;
        }
        usleep(2000);
    } while (status & 0x01);

    if (i2c_write_reg(fd, BME280_REG_CTRL_HUM, 0x01) < 0) return -1;
    if (i2c_write_reg(fd, BME280_REG_CONFIG, 0xA0) < 0) return -1;
    if (i2c_write_reg(fd, BME280_REG_CTRL_MEAS, 0x27) < 0) return -1;

    return 0;
}

static int bme280_read(int fd, float *temp, float *hum, float *press) {
    uint8_t data[8];
    if (i2c_read_burst(fd, BME280_REG_DATA, data, 8) < 0) {
        fprintf(stderr, "Error: Failed to read sensor data.\n");
        return -1;
    }

    int32_t raw_p = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    int32_t raw_t = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);
    int32_t raw_h = (data[6] << 8) | data[7];

    *press = (float)raw_p / 100.0f;
    *temp = (float)raw_t / 100.0f;
    *hum = (float)raw_h / 1000.0f;

    return 0;
}

static void log_data(FILE *fp, float temp, float hum, float press) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temp, hum, press);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Error: Failed to open I2C bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        perror("Error: Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    if (bme280_init(fd) < 0) {
        fprintf(stderr, "Error: BME280 initialization failed.\n");
        close(fd);
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error: Failed to open log file");
        close(fd);
        return 1;
    }

    while (running) {
        float temp, hum, press;
        if (bme280_read(fd, &temp, &hum, &press) == 0) {
            log_data(fp, temp, hum, press);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, skipping log entry.\n");
        }
        sleep(5);
    }

    fclose(fp);
    close(fd);
    return 0;
}

