#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

#define TEMPERATURE_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"
#define GPIO_PIN 18
#define PWM_FREQUENCY 25000
#define PWM_RANGE 255
#define SLEEP_INTERVAL 5

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

int read_temperature(float *temperature) {
    FILE *fp = fopen(TEMPERATURE_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening temperature file: %s\n", strerror(errno));
        return -1;
    }

    int temp_raw;
    if (fscanf(fp, "%d", &temp_raw) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    *temperature = (float)temp_raw / 1000.0f;
    return 0;
}

int calculate_duty_cycle(float temperature) {
    if (temperature < 40.0f) {
        return 0;
    } else if (temperature > 70.0f) {
        return PWM_RANGE;
    } else {
        return (int)(((temperature - 40.0f) / (70.0f - 40.0f)) * PWM_RANGE);
    }
}

int log_data(float temperature, int duty_cycle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Temperature: %.2f C, Duty Cycle: %d\n", timestamp, temperature, duty_cycle);
    fclose(fp);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_PIN, PWM_RANGE);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("Fan control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        float temperature;
        if (read_temperature(&temperature) != 0) {
            fprintf(stderr, "Failed to read temperature, skipping iteration.\n");
            sleep(SLEEP_INTERVAL);
            continue;
        }

        int duty_cycle = calculate_duty_cycle(temperature);
        gpioPWM(GPIO_PIN, duty_cycle);

        if (log_data(temperature, duty_cycle) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        printf("Temperature: %.2f C, Duty Cycle: %d\n", temperature, duty_cycle);
        sleep(SLEEP_INTERVAL);
    }

    gpioPWM(GPIO_PIN, 0);
    gpioTerminate();
    printf("Fan control program terminated.\n");
    return 0;
}

