    c->dig_P3 = (int16_t)(d[10] | (d[11] << 8));
    c->dig_P4 = (int16_t)(d[12] | (d[13] << 8));
    c->dig_P5 = (int16_t)(d[14] | (d[15] << 8));
    c->dig_P6 = (int16_t)(d[16] | (d[17] << 8));
    c->dig_P7 = (int16_t)(d[18] | (d[19] << 8));
    c->dig_P8 = (int16_t)(d[20] | (d[21] << 8));
    c->dig_P9 = (int16_t)(d[22] | (d[23] << 8));
    return 0;
}

static int bmp280_init(int fd, bmp280_calib_t *c) {
    uint8_t id;
    if (i2c_read_reg(fd, BMP280_REG_ID, &id, 1) != 0) {
        fprintf(stderr, "Error: cannot read chip ID register: %s\n", strerror(errno));
        return -1;
