#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS         "/dev/i2c-1"
#define LM75_ADDR       0x49
#define GPIO_LED        18
#define BUFFER_SIZE     60
#define TEMP_THRESHOLD  28.0f
#define SAMPLE_PERIOD_S 1

#define LM75_REG_TEMP   0x00
#define LM75_REG_CONFIG 0x01

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static pthread_mutex_t g_buf_mtx;
static float g_buf[BUFFER_SIZE];
static int   g_buf_idx = 0;
static int   g_buf_count = 0;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: got %zd bytes (%s)\n",
                reg, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int init_i2c(void)
{
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, LM75_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", LM75_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }
    /* Disable the LM75 comparator so it acts as a simple temperature-only sensor. */
    if (i2c_write_reg8(g_i2c_fd, LM75_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to configure LM75 (sensor absent or bus error).\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int read_temperature(float *temp_out)
{
    int16_t raw;
    if (i2c_read_reg16(g_i2c_fd, LM75_REG_TEMP, &raw) < 0)
        return -1;
    *temp_out = (float)raw / 16.0f;
    return 0;
}

static void buffer_add(float temp)
{
    pthread_mutex_lock(&g_buf_mtx);
    g_buf[g_buf_idx] = temp;
    g_buf_idx = (g_buf_idx + 1) % BUFFER_SIZE;
    if (g_buf_count < BUFFER_SIZE)
        g_buf_count++;
    pthread_mutex_unlock(&g_buf_mtx);
}

static float buffer_avg(void)
{
    pthread_mutex_lock(&g_buf_mtx);
    if (g_buf_count == 0) {
        pthread_mutex_unlock(&g_buf_mtx);
        return 0.0f;
    }
    float sum = 0.0f;
    for (int i = 0; i < g_buf_count; i++)
        sum += g_buf[i];
    pthread_mutex_unlock(&g_buf_mtx);
    return sum / (float)g_buf_count;
}

static void led_set(bool on)
{
    if (gpioWrite(GPIO_LED, on ? 1 : 0) < 0)
        fprintf(stderr, "Warning: gpioWrite(%d) failed\n", GPIO_LED);
}

static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    led_set(false);
    gpioTerminate();
    pthread_mutex_destroy(&g_buf_mtx);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Cannot set GPIO %d as output\n", GPIO_LED);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    led_set(false);

    if (init_i2c() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (pthread_mutex_init(&g_buf_mtx, NULL) != 0) {
        fprintf(stderr, "Mutex init failed\n");
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < BUFFER_SIZE; i++)
        g_buf[i] = 0.0f;

    pthread_t led_thread;
    if (pthread_create(&led_thread, NULL, led_thread_func, NULL) != 0) {
        fprintf(stderr, "Cannot create LED thread: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    while (g_running) {
        float temp;
        if (read_temperature(&temp) < 0) {
            fprintf(stderr, "Temperature read failed; re-initialising I2C.\n");
            close(g_i2c_fd);
            g_i2c_fd = -1;
            sleep(1);
            if (init_i2c() < 0)
                fprintf(stderr, "I2C re-init failed; will retry next cycle.\n");
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        buffer_add(temp);
        float avg = buffer_avg();

        printf("Temperature: %.2f C | Running Average: %.2f C\n", temp, avg);

        if (temp > TEMP_THRESHOLD)
            led_set(true);
        else
            led_set(false);

        sleep(SAMPLE_PERIOD_S);
    }

    pthread_join(led_thread, NULL);
    cleanup();
    return EXIT_SUCCESS;
}

static void *led_thread_func(void *arg)
{
    (void)arg;
    while (g_running)
        sleep(1);
    return NULL;
}

