#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define CONFIG_FILE "config.json"
#define SPI_DEVICE "/dev/spidev0.0"
#define PWM_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define MAX_DUTY 1000
#define SAMPLE_INTERVAL_US 100000
#define FAILSAFE_TEMP 80.0
#define R_REF 430.0
#define R_NOMINAL 100.0
#define A 3.9083e-3
#define B 5.775e-7
#define C 2.09698e-12

typedef struct {
    double target;
    double kp;
    double ki;
    double kd;
} PIDParams;

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static PIDParams pid_params = {25.0, 1.0, 0.1, 0.01};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_config(const char *filename, PIDParams *params) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open config file '%s': %s. Using defaults.\n", filename, strerror(errno));
        return -1;
    }
    char buffer[512];
    size_t n = fread(buffer, 1, sizeof(buffer) - 1, fp);
    fclose(fp);
    buffer[n] = '\0';
    double target = 25.0;
    double kp = 1.0, ki = 0.1, kd = 0.01;
    if (sscanf(buffer, "{\"target\": %lf, \"kp\": %lf, \"ki\": %lf, \"kd\": %lf}", &target, &kp, &ki, &kd) != 4) {
        fprintf(stderr, "Warning: Invalid JSON in config. Using defaults.\n");
    }
    if (target > 0) params->target = target;
    if (kp > 0) params->kp = kp;
    if (ki > 0) params->ki = ki;
    if (kd > 0) params->kd = kd;
    return 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }
    uint8_t mode = SPI_MODE_1;
    uint8_t bits = 8;
    uint32_t speed = 500000;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 || ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 || ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI mode/bits/speed: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1;
        return -1;
    }
    return 0;
}

static int read_max31865(uint8_t *data) {
    if (spi_fd < 0) return -1;
    struct spi_ioc_transfer tr = {0};
    tr.tx_buf = 0;
    tr.rx_buf = (unsigned long)data;
    tr.len = 4;
    tr.speed_hz = 500000;
    tr.bits_per_word = 8;
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static double read_temperature(void) {
    uint8_t raw[4];
    if (read_max31865(raw) < 0) return -1000.0;
    uint32_t val = ((uint32_t)raw[0] << 24) | ((uint32_t)raw[1] << 16) | ((uint32_t)raw[2] << 8) | raw[3];
    if (val & 0x00010000) {
        fprintf(stderr, "MAX31865 fault detected (0x%08X).\n", val);
        return -1000.0;
    }
    int16_t rtd = (int16_t)(val >> 18);
    double rtd_resistance = (double)rtd * R_REF / 32768.0;
    double temp = A + B * rtd_resistance + C * rtd_resistance * rtd_resistance;
    return temp;
}

static double pid_calculate(double setpoint, double actual, const PIDParams *params) {
    double error = setpoint - actual;
    double integral = 0.0;
    static double prev_error = 0.0;
    integral += error * params->ki;
    double derivative = error - prev_error;
    double output = params->kp * error + params->ki * integral + params->kd * derivative;
    prev_error = error;
    if (output < 0) output = 0;
    if (output > MAX_DUTY) output = MAX_DUTY;
    return output;
}

static void set_pwm(int duty) {
    if (gpioPWM(PWM_GPIO, duty) < 0) {
        fprintf(stderr, "Warning: gpioPWM failed: %s\n", pigpio_error(gpioGetMode(PWM_GPIO)));
    }
}

static void failsafe(void) {
    fprintf(stderr, "Failsafe triggered! Heater OFF.\n");
    set_pwm(0);
    if (spi_fd >= 0) close(spi_fd);
    gpioTerminate();
    exit(1);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    if (spi_init() < 0) {
        gpioTerminate();
        return 1;
    }
    read_config(CONFIG_FILE, &pid_params);
    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);
    set_pwm(0);
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    while (running) {
        double temp = read_temperature();
        if (temp < -900.0) {
            failsafe();
        }
        if (temp > FAILSAFE_TEMP) {
            fprintf(stderr, "Temperature %.2f exceeds failsafe %.2f! Shutting down.\n", temp, FAILSAFE_TEMP);
            failsafe();
        }
        double duty = pid_calculate(pid_params.target, temp, &pid_params);
        set_pwm((int)duty);
        printf("Temp: %.2f C, Target: %.2f C, Duty: %d\n", temp, pid_params.target, (int)duty);
        usleep(SAMPLE_INTERVAL_US);
    }
    set_pwm(0);
    if (spi_fd >= 0) close(spi_fd);
    gpioTerminate();
    return 0;
}

