#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define BMP180_ADDR    0x77
#define BREACH_LOG     "breach_log.txt"
#define SAMPLE_DELAY_S 1
#define MAX_RETRIES    3

/* BMP180 register addresses */
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB     0xF6
#define BMP180_REG_LSB     0xF7
#define BMP180_REG_XLSB    0xF8

/* Calibration coefficients (signed/unsigned 16-bit) */
typedef struct {
    int16_t  ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Read a single byte register; returns -1 on error */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

/* Write a single byte register; returns -1 on error */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

/* Read a 16-bit big-endian register; returns -1 on error */
static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* Read a 16-bit big-endian register; returns -1 on error */
static int i2c_read_reg16u(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* Read a signed 16-bit calibration coefficient with retries */
static int read_cal_signed(int fd, uint8_t reg, int16_t *out) {
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (i2c_read_reg16(fd, reg, out) == 0) return 0;
        usleep(10000);
    }
    return -1;
}

/* Read an unsigned 16-bit calibration coefficient with retries */
static int read_cal_unsigned(int fd, uint8_t reg, uint16_t *out) {
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (i2c_read_reg16u(fd, reg, out) == 0) return 0;
        usleep(10000);
    }
    return -1;
}

/* Read raw temperature; returns -1 on error */
static int read_raw_temp(int fd, int32_t *out) {
    if (i2c_write_reg8(fd, BMP180_REG_CONTROL, 0x2E) < 0) return -1;
    usleep(5000);
    uint8_t msb, lsb;
    if (i2c_read_reg8(fd, BMP180_REG_MSB, &msb) < 0) return -1;
    if (i2c_read_reg8(fd, BMP180_REG_LSB, &lsb) < 0) return -1;
    *out = (int32_t)((msb << 8) | lsb);
    return 0;
}

/* Read raw pressure; returns -1 on error */
static int read_raw_pressure(int fd, int32_t *out) {
    if (i2c_write_reg8(fd, BMP180_REG_CONTROL, 0x34) < 0) return -1;
    usleep(5000);
    uint8_t msb, lsb, xlsb;
    if (i2c_read_reg8(fd, BMP180_REG_MSB, &msb) < 0) return -1;
    if (i2c_read_reg8(fd, BMP180_REG_LSB, &lsb) < 0) return -1;
    if (i2c_read_reg8(fd, BMP180_REG_XLSB, &xlsb) < 0) return -1;
    *out = ((int32_t)msb << 16) | ((int32_t)lsb << 8) | (int32_t)xlsb;
    *out >>= (8 - 0); /* OSS = 0 */
    return 0;
}

/* Compute B5 (integer) without powf */
static int32_t compute_b5(int32_t ut, const bmp180_cal_t *c) {
    int32_t x1 = ((ut - (int32_t)c->ac6) * (int32_t)c->ac5) >> 15;
    int32_t x2 = ((int32_t)c->mc << 11) / (x1 + (int32_t)c->md);
    return x1 + x2;
}

/* Compute temperature in 0.1 deg C (integer) */
static int32_t compute_temp_x10(int32_t ut, const bmp180_cal_t *c) {
    int32_t b5 = compute_b5(ut, c);
    return (b5 + 8) >> 4;
}

/* Compute pressure in Pa (integer) */
static int32_t compute_pressure_pa(int32_t up, int32_t ut, const bmp180_cal_t *c) {
    int32_t b5 = compute_b5(ut, c);
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)c->b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)c->ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)c->ac1 * 4 + x3) << 0) + 2) >> 2);
    x1 = ((int32_t)c->ac3 * b6) >> 13;
    x2 = ((int32_t)c->b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)c->ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 0);
    int32_t p;
    if (b7 < 0x80000000UL) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;
    return p;
}

/* Log a breach with timestamp */
static void log_breach(const char *type, float value, const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", filename, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - %s: %.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, type, value);
    }
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave 0x%02X: %s\n", BMP180_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Probe sensor presence by reading chip ID register 0xD0 */
    uint8_t chip_id;
    if (i2c_read_reg8(g_i2c_fd, 0xD0, &chip_id) < 0) {
        fprintf(stderr, "BMP180 not detected at 0x%02X on %s\n", BMP180_ADDR, I2C_BUS);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    if (chip_id != 0x55) {
        fprintf(stderr, "Unexpected chip ID 0x%02X (expected 0x55) - not a BMP180\n", chip_id);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    bmp180_cal_t cal;
    if (read_cal_signed(g_i2c_fd, 0xAA, &cal.ac1) < 0 ||
