        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    if (chip_id != 0x55) {
        fprintf(stderr, "Unexpected chip ID 0x%02X (expected 0x55) - not a BMP180\n", chip_id);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    bmp180_cal_t cal;
    if (read_cal_signed(g_i2c_fd, 0xAA, &cal.ac1) < 0 ||
        read_cal_signed(g_i2c_fd, 0xAC, &cal.ac2) < 0 ||
        read_cal_signed(g_i2c_fd, 0xAE, &cal.ac3) < 0 ||
        read_cal_signed(g_i2c_fd, 0xB0, &cal.ac4) < 0 ||
        read_cal_signed(g_i2c_fd, 0xB2, &cal.ac5) < 0 ||
        read_cal_signed(g_i2c_fd, 0xB4, &cal.ac6) < 0 ||
        read_cal_signed(g_i2c_fd, 0xB6, &cal.b1)  < 0 ||
        read_cal_signed(g_i2c_fd, 0xB8, &cal.b2)  < 0 ||
        read_cal_signed(g_i2c_fd, 0xBA, &cal.mb)  < 0 ||
        read_cal_signed(g_i2c_fd, 0xBC, &cal.mc)  < 0 ||
        read_cal_signed(g_i2c_fd, 0xBE, &cal.md)  < 0) {
        fprintf(stderr, "Failed to read BMP180 calibration data\n");
