        return EXIT_FAILURE;
    }

    printf("BMP180 initialized. Logging breaches to %s\n", BREACH_LOG);

    while (g_running) {
        int32_t ut, up;

        if (read_raw_temp(g_i2c_fd, &ut) < 0) {
            fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
            sleep(SAMPLE_DELAY_S);
            continue;
        }

        if (read_raw_pressure(g_i2c_fd, &up) < 0) {
            fprintf(stderr, "Error reading pressure: %s\n", strerror(errno));
            sleep(SAMPLE_DELAY_S);
            continue;
        }

        int32_t t_x10 = compute_temp_x10(ut, &cal);
        float temp_c = t_x10 / 10.0f;
        float press_hpa = (float)up / 100.0f;

