    float temp = calculate_temperature(ut, &b5);

    if (read_raw_pressure(&up) != 0) {
        fprintf(stderr, "Timer: pressure read failed\n");
        return;
    }

    b5 = (float)b5;
    float pres = calculate_pressure(up, b5);

    SensorData sd;
    sd.timestamp   = time(NULL);
    sd.temperature = temp;
    sd.pressure    = pres;

    buffer_add(&buffer, sd);

    if (temp > TEMP_THRESHOLD) {
        fan_set(1);
    } else {
        fan_set(0);
    }

    printf("Timestamp: %ld, Temperature: %.2f C, Pressure: %.2f Pa\n",
           (long)sd.timestamp, sd.temperature, sd.pressure);
}

static int read_calibration(void) {
    uint8_t buf[BMP180_CAL_WORDS * 2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_START, (char *)buf, sizeof(buf)) != (int)sizeof(buf)) {
        fprintf(stderr, "Failed to read calibration data\n");
        return -1;
    }

    ac1 = (int16_t)((buf[0]  << 8) | buf[1]);
    ac2 = (int16_t)((buf[2]  << 8) | buf[3]);
    ac3 = (int16_t)((buf[4]  << 8) | buf[5]);
    ac4 = (uint16_t)((buf[6]  << 8) | buf[7]);
    ac5 = (uint16_t)((buf[8]  << 8) | buf[9]);
    ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    b1  = (int16_t)((buf[12] << 8) | buf[13]);
    b2  = (int16_t)((buf[14] << 8) | buf[15]);
    mb  = (int16_t)((buf[16] << 8) | buf[17]);
    mc  = (int16_t)((buf[18] << 8) | buf[19]);
    md  = (int16_t)((buf[20] << 8) | buf[21]);

    return 0;
}

static int read_raw_temperature(int32_t *ut) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E) != 0) {
        fprintf(stderr, "Failed to write temperature command\n");
        return -1;
    }
    gpioDelay(5000);

    uint8_t buf[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)buf, 2) != 2) {
        fprintf(stderr, "Failed to read raw temperature\n");
        return -1;
    }
    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int32_t *up) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34) != 0) {
        fprintf(stderr, "Failed to write pressure command\n");
        return -1;
    }
    gpioDelay(5000);

    uint8_t buf[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)buf, 3) != 3) {
        fprintf(stderr, "Failed to read raw pressure\n");
        return -1;
    }
    *up = ((int32_t)buf[0] << 16 | (int32_t)buf[1] << 8 | (int32_t)buf[2]) >> 8;
    return 0;
}

static float calculate_temperature(int32_t ut, int32_t *b5_out) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    if (b5_out) *b5_out = b5;
    return ((b5 + 8) >> 4) / 10.0f;
}

static float calculate_pressure(int32_t up, int32_t b5) {
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << 0) + 2) >> 2;

    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 0);

    int32_t p;
    if (b7 < 0x80000000UL) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;

    return (float)p;
}

static void buffer_add(CircularBuffer *cb, SensorData sd) {
    cb->data[cb->head] = sd;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static void fan_set(int on) {
    if (gpioWrite(FAN_GPIO, on ? 1 : 0) != 0) {
        fprintf(stderr, "Warning: failed to set fan GPIO\n");
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X\n", BMP180_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (read_calibration() != 0) {
        fprintf(stderr, "BMP180 calibration read failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    fan_set(0);

    buffer.head  = 0;
    buffer.count = 0;

    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_US, timer_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set timer\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("BMP180 monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000);
    }

    gpioSetTimerFuncEx(0, 0, NULL, NULL);
    fan_set(0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nCleanup complete.\n");
    return EXIT_SUCCESS;
}

