#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define GPIO_INTERRUPT 27
#define DEBOUNCE_DELAY_US 200000
#define LOG_INTERVAL_US 2000000
#define I2C_BUS 1

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t logging_enabled = 0;
static int i2c_handle = -1;

typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static bmp180_cal_t cal;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    static uint32_t last_tick = 0;
    uint32_t diff = tick - last_tick;
    if (diff > DEBOUNCE_DELAY_US) {
        logging_enabled = !logging_enabled;
        printf("Data logging %s\n", logging_enabled ? "enabled" : "disabled");
        last_tick = tick;
    }
}

static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *val) {
    if (i2cWriteByte(handle, reg) < 0) return -1;
    int b = i2cReadByte(handle);
    if (b < 0) return -1;
    *val = (uint8_t)b;
    return 0;
}

static int i2c_read_reg16(int handle, uint8_t reg, int16_t *val) {
    if (i2cWriteByte(handle, reg) < 0) return -1;
    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *val = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int i2c_read_reg24(int handle, uint8_t reg, int32_t *val) {
    if (i2cWriteByte(handle, reg) < 0) return -1;
    char buf[3];
    if (i2cReadDevice(handle, buf, 3) != 3) return -1;
    *val = ((int32_t)(buf[0] << 16) | (buf[1] << 8) | buf[2]) >> 8;
    return 0;
}

static int read_calibration_data(int handle, bmp180_cal_t *c) {
    if (i2c_read_reg16(handle, BMP180_REG_CAL_AC1, &c->ac1) < 0) return -1;
    if (i2c_read_reg16(handle, BMP180_REG_CAL_AC2, &c->ac2) < 0) return -1;
    if (i2c_read_reg16(handle, BMP180_REG_CAL_AC3, &c->ac3) < 0) return -1;
    if (i2c_read_reg16(handle, BMP180_REG_CAL_AC4, (int16_t*)&c->ac4) < 0) return -1;
    if (i2c_read_reg16(handle, BMP180_REG_CAL_AC5, (int16_t*)&c->ac5) < 0) return -1;
    if (i2c_read_reg16(handle, BMP180_REG_CAL_AC6, (int16_t*)&c->ac6) < 0) return -1;
    if (i2c_read_reg16(handle, BMP180_REG_CAL_B1, &c->b1) < 0) return -1;
    if (i2c_read_reg16(handle, BMP180_REG_CAL_B2, &c->b2) < 0) return -1;
    if (i2c_read_reg16(handle, BMP180_REG_CAL_MB, &c->mb) < 0) return -1;
    if (i2c_read_reg16(handle, BMP180_REG_CAL_MC, &c->mc) < 0) return -1;
    if (i2c_read_reg16(handle, BMP180_REG_CAL_MD, &c->md) < 0) return -1;
    return 0;
}

static int read_raw_temperature(int handle, int32_t *ut) {
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, 0x2E) < 0) return -1;
    gpioDelay(5000);
    return i2c_read_reg16(handle, BMP180_REG_MSB, (int16_t*)ut);
}

static int read_raw_pressure(int handle, int32_t *up) {
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, 0x34) < 0) return -1;
    gpioDelay(5000);
    return i2c_read_reg24(handle, BMP180_REG_MSB, up);
}

static int32_t compute_b5(int32_t ut, const bmp180_cal_t *c) {
    int32_t x1 = ((ut - (int32_t)c->ac6) * (int32_t)c->ac5) >> 15;
    int32_t x2 = ((int32_t)c->mc << 11) / (x1 + (int32_t)c->md);
    return x1 + x2;
}

static int32_t compute_pressure(int32_t up, int32_t b5, const bmp180_cal_t *c) {
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)c->b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)c->ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)c->ac1 * 4 + x3) << 0) + 2) >> 2);
    x1 = ((int32_t)c->ac3 * b6) >> 13;
    x2 = ((int32_t)c->b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)c->ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 0);
    int32_t p;
    if (b7 < 0x80000000UL) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return p;
}

static void log_pressure(int32_t pressure) {
    FILE *fp = fopen("pressure_log.txt", "a");
    if (!fp) { perror("fopen"); return; }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, %d Pa\n", ts, pressure);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (read_calibration_data(i2c_handle, &cal) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(GPIO_INTERRUPT, PI_INPUT);
    gpioSetPullUpDown(GPIO_INTERRUPT, PI_PUD_UP);
    if (gpioSetISRFuncEx(GPIO_INTERRUPT, FALLING_EDGE, 0, interrupt_handler, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    printf("BMP180 logger ready. Press button on GPIO27 to toggle logging.\n");
    while (running) {
        if (logging_enabled) {
            int32_t ut, up;
            if (read_raw_temperature(i2c_handle, &ut) == 0 && read_raw_pressure(i2c_handle, &up) == 0) {
                int32_t b5 = compute_b5(ut, &cal);
                int32_t p = compute_pressure(up, b5, &cal);
                printf("Pressure: %d Pa\n", p);
                log_pressure(p);
            } else {
                fprintf(stderr, "I2C read error\n");
            }
        }
        gpioDelay(LOG_INTERVAL_US);
    }
    gpioSetISRFuncEx(GPIO_INTERRUPT, FALLING_EDGE, 0, NULL, NULL);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    printf("Exiting cleanly.\n");
    return 0;
}

