            if (read_raw_temperature(i2c_handle, &ut) == 0 && read_raw_pressure(i2c_handle, &up) == 0) {
                int32_t b5 = compute_b5(ut, &cal);
                int32_t p = compute_pressure(up, b5, &cal);
                printf("Pressure: %d Pa\n", p);
