#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 2000000
#define HEATER_GPIO 17
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define TARGET_TEMPERATURE 25.0
#define MAX_DUTY_CYCLE 0.8
#define SAMPLE_INTERVAL_US 1000000
#define LOG_FILE "heater_log.csv"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *msg) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s,%s\n", ts, msg);
    fflush(log_file);
}

static int read_max31855(int handle, float *temp_out) {
    char rx[4] = {0};
    int bytes = spiRead(handle, rx, 4);
    if (bytes != 4) {
        log_message("SPI read failed or incomplete");
        return -1;
    }
    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);
    if (raw & 0x00010000) {
        log_message("MAX31855 fault detected");
        return -2;
    }
    int16_t therm_data = (int16_t)(raw >> 18);
    *temp_out = therm_data * 0.25f;
    return 0;
}

static float calculate_duty_cycle(float temp, float target, float max_duty) {
    float error = target - temp;
    float proportional = error;
    static float integral = 0.0f;
    integral += error;
    if (integral > 100.0f) integral = 100.0f;
    if (integral < -100.0f) integral = -100.0f;
    float duty = proportional + (integral * max_duty);
    if (duty > max_duty) duty = max_duty;
    if (duty < -max_duty) duty = -max_duty;
    integral -= error;
    return duty;
}

static void set_heater(int gpio, float duty) {
    if (duty < 0.0f) duty = 0.0f;
    if (duty > 100.0f) duty = 100.0f;
    int pwm = (int)(duty * (PWM_RANGE / 100.0f));
    gpioPWM(gpio, pwm);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioPWM(HEATER_GPIO, 0);
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    log_message("System started");
    while (running) {
        float temp = 0.0f;
        int rc = read_max31855(spi_handle, &temp);
        if (rc == 0) {
            float duty = calculate_duty_cycle(temp, TARGET_TEMPERATURE, MAX_DUTY_CYCLE);
            set_heater(HEATER_GPIO, duty);
            char msg[128];
            snprintf(msg, sizeof(msg), "Temp: %.2f, Duty: %.2f%%", temp, duty * 100.0f);
            log_message(msg);
        } else if (rc == -1) {
            set_heater(HEATER_GPIO, 0.0f);
            log_message("Error: SPI read failure");
        } else {
            set_heater(HEATER_GPIO, 0.0f);
            log_message("Error: MAX31855 fault");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    log_message("Shutting down");
    cleanup();
    return 0;
}

