#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27
#define TEMP_FILE  "/sys/class/thermal/thermal_zone0/temp"
#define PWM_RANGE  255
#define POLL_US    500000  /* 0.5 s */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read CPU temperature in millidegrees Celsius.
 * Returns 0 on success, -1 on error.
 */
static int read_cpu_temp(int *temp_out)
{
    FILE *fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }

    int temp;
    int rc = fscanf(fp, "%d", &temp);
    int saved_errno = errno;
    fclose(fp);

    if (rc != 1) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(saved_errno));
        return -1;
    }

    *temp_out = temp;
    return 0;
}

/*
 * Set RGB LED color using pigpio hardware PWM.
 * Common-anode: 0 = fully on (cathode tied to GND), 255 = off (cathode at 3.3 V).
 * Returns 0 on success, -1 on error.
 */
static int set_rgb_color(int red, int green, int blue)
{
    /* Red cathode on GPIO17 */
    if (gpioPWM(RED_PIN, red) != 0) {
        fprintf(stderr, "Error setting PWM on GPIO%d (red): %s\n", RED_PIN, pigpio_error(0));
        return -1;
    }
    /* Green cathode on GPIO18 */
    if (gpioPWM(GREEN_PIN, green) != 0) {
        fprintf(stderr, "Error setting PWM on GPIO%d (green): %s\n", GREEN_PIN, pigpio_error(0));
        return -1;
    }
    /* Blue cathode on GPIO27 */
    if (gpioPWM(BLUE_PIN, blue) != 0) {
        fprintf(stderr, "Error setting PWM on GPIO%d (blue): %s\n", BLUE_PIN, pigpio_error(0));
        return -1;
    }
    return 0;
}

/*
 * Map temperature to RGB color.
 * Below 40000 m°C -> Blue (0,0,255)
 * 40000-59999 m°C -> Green (0,255,0)
 * 60000 m°C and above -> Red (255,0,0)
 */
static void temp_to_color(int temp_mC, int *red, int *green, int *blue)
{
    if (temp_mC < 40000) {
        *red = 0;
        *green = 0;
        *blue = 255;
    } else if (temp_mC < 60000) {
        *red = 0;
        *green = 255;
        *blue = 0;
    } else {
        *red = 255;
        *green = 0;
        *blue = 0;
    }
}

int main(void)
{
    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Set GPIO modes to output */
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM range (0-255) */
    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(BLUE_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error setting PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure LED starts off (cathodes at 3.3 V) */
    if (set_rgb_color(PWM_RANGE, PWM_RANGE, PWM_RANGE) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("CPU Temperature Monitoring and RGB LED Control\n");
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int temp_mC = 0;
        if (read_cpu_temp(&temp_mC) != 0) {
            /* Error already printed; skip this cycle */
            usleep(POLL_US);
            continue;
        }

        int red, green, blue;
        temp_to_color(temp_mC, &red, &green, &blue);

        if (set_rgb_color(red, green, blue) != 0) {
            /* Error already printed; skip this cycle */
            usleep(POLL_US);
            continue;
        }

        printf("Temperature: %d m°C, RGB: (%d, %d, %d)\n", temp_mC, red, green, blue);
        fflush(stdout);

        usleep(POLL_US);
    }

    /* Graceful shutdown: turn off all channels and release pigpio */
    set_rgb_color(PWM_RANGE, PWM_RANGE, PWM_RANGE);
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

