#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>

#define DHT22_GPIO 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3
#define DHT22_TIMEOUT_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_level(int gpio, int level, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    while (gpioRead(gpio) != level) {
        if ((gpioTick() - start) > timeout_us) return -1;
    }
    return 0;
}

static int read_dht22(float *humidity, float *temperature) {
    uint8_t data[5] = {0};
    int i;

    memset(data, 0, sizeof(data));

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(2000);
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30);
    gpioSetMode(DHT22_GPIO, PI_INPUT);

    if (wait_for_level(DHT22_GPIO, 0, 1000) < 0) return -1;
    if (wait_for_level(DHT22_GPIO, 1, 1000) < 0) return -1;

    for (i = 0; i < 40; i++) {
        if (wait_for_level(DHT22_GPIO, 0, DHT22_TIMEOUT_US) < 0) return -1;

        uint32_t start = gpioTick();
        if (wait_for_level(DHT22_GPIO, 1, DHT22_TIMEOUT_US) < 0) return -1;

        uint32_t duration = gpioTick() - start;

        if (duration > 50) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    uint8_t checksum = data[0] + data[1] + data[2] + data[3];
    if (checksum != data[4]) {
        fprintf(stderr, "Checksum error: %d + %d + %d + %d = %d, expected %d\n",
                data[0], data[1], data[2], data[3], checksum, data[4]);
        return -1;
    }

    *humidity = (float)((data[0] << 8) | data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature *= -1.0;
    }

    return 0;
}

static int post_data(float humidity, float temperature) {
    char json_string[128];
    snprintf(json_string, sizeof(json_string),
             "{\"humidity\":%.2f,\"temperature\":%.2f}", humidity, temperature);

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        char error_buffer[256];
        snprintf(error_buffer, sizeof(error_buffer),
                 "HTTP POST attempt %d/%d: %s", attempt + 1, MAX_RETRIES, json_string);

        int result = system(error_buffer);
