#define DHT22_GPIO 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3
#define DHT22_TIMEOUT_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_level(int gpio, int level, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    while (gpioRead(gpio) != level) {
        if ((gpioTick() - start) > timeout_us) return -1;
    }
    return 0;
}

static int read_dht22(float *humidity, float *temperature) {
    uint8_t data[5] = {0};
    int i;

    memset(data, 0, sizeof(data));

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(2000);
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30);
    gpioSetMode(DHT22_GPIO, PI_INPUT);

    if (wait_for_level(DHT22_GPIO, 0, 1000) < 0) return -1;
    if (wait_for_level(DHT22_GPIO, 1, 1000) < 0) return -1;

    for (i = 0; i < 40; i++) {
        if (wait_for_level(DHT22_GPIO, 0, DHT22_TIMEOUT_US) < 0) return -1;

        uint32_t start = gpioTick();
        if (wait_for_level(DHT22_GPIO, 1, DHT22_TIMEOUT_US) < 0) return -1;

