#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR             0x77
#define BMP180_REG_CONTROL      0xF4
#define BMP180_REG_MSB          0xF6
#define BMP180_REG_LSB          0xF7
#define BMP180_REG_XLSB         0xF8
#define BMP180_REG_CAL_AC1      0xAA
#define BMP180_REG_CAL_AC2      0xAC
#define BMP180_REG_CAL_AC3      0xAE
#define BMP180_REG_CAL_AC4      0xB0
#define BMP180_REG_CAL_AC5      0xB2
#define BMP180_REG_CAL_AC6      0xB4
#define BMP180_REG_CAL_B1       0xB6
#define BMP180_REG_CAL_B2       0xB8
#define BMP180_REG_CAL_MB       0xBA
#define BMP180_REG_CAL_MC       0xBC
#define BMP180_REG_CAL_MD       0xBE
#define OSS                     3
#define LOG_FILE               "pressure_log.txt"
#define BUTTON_GPIO            4
#define DEBOUNCE_US            200000
#define CONVERSION_DELAY_US    26000
#define SAMPLE_INTERVAL_US     2000000

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t logging_enabled = 0;
static int i2c_handle = -1;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void button_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)userdata;
    static uint32_t last_tick = 0;
    if (level != 0) return;
    uint32_t diff = tick - last_tick;
    if (diff > DEBOUNCE_US) {
        logging_enabled = !logging_enabled;
        printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
        fflush(stdout);
        last_tick = tick;
    }
}

static int read_s16(int handle, uint8_t reg, int16_t *out) {
    char buf[2];
    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) return -1;
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_u16(int handle, uint8_t reg, uint16_t *out) {
    char buf[2];
    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) return -1;
    *out = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_calibration(void) {
    if (read_s16(i2c_handle, BMP180_REG_CAL_AC1, &ac1) < 0) return -1;
    if (read_s16(i2c_handle, BMP180_REG_CAL_AC2, &ac2) < 0) return -1;
    if (read_s16(i2c_handle, BMP180_REG_CAL_AC3, &ac3) < 0) return -1;
    if (read_u16(i2c_handle, BMP180_REG_CAL_AC4, &ac4) < 0) return -1;
    if (read_u16(i2c_handle, BMP180_REG_CAL_AC5, &ac5) < 0) return -1;
    if (read_u16(i2c_handle, BMP180_REG_CAL_AC6, &ac6) < 0) return -1;
    if (read_s16(i2c_handle, BMP180_REG_CAL_B1, &b1) < 0) return -1;
    if (read_s16(i2c_handle, BMP180_REG_CAL_B2, &b2) < 0) return -1;
    if (read_s16(i2c_handle, BMP180_REG_CAL_MB, &mb) < 0) return -1;
    if (read_s16(i2c_handle, BMP180_REG_CAL_MC, &mc) < 0) return -1;
    if (read_s16(i2c_handle, BMP180_REG_CAL_MD, &md) < 0) return -1;
    if (ac1 == 0 && ac2 == 0 && ac3 == 0) return -1;
    return 0;
}

static int read_raw_temperature(int *raw_temp) {
    char cmd[2] = {BMP180_REG_CONTROL, 0x2E};
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 0) return -1;
    gpioDelay(5000);
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2) != 2) return -1;
    *raw_temp = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int *raw_pressure) {
    char cmd[2] = {BMP180_REG_CONTROL, 0x34 + (OSS << 6)};
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 0) return -1;
    gpioDelay(CONVERSION_DELAY_US);
    char buf[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3) return -1;
    *raw_pressure = ((int32_t)(buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - OSS);
    return 0;
}

static int32_t compute_b5(int raw_temp) {
    int32_t x1 = ((int32_t)raw_temp - (int32_t)ac6) * (int32_t)ac5 >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + md);
    return x1 + x2;
}

static int32_t compute_pressure(int raw_pressure, int raw_temp) {
    int32_t b5 = compute_b5(raw_temp);
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << OSS) + 2) >> 2;
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)raw_pressure - b3) * (50000 >> OSS);
    int32_t p;
    if (b7 < 0x80000000UL) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return p;
}

static void log_pressure(int32_t pressure_pa) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) { perror("fopen"); return; }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Pressure: %.2f hPa\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            pressure_pa / 100.0);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X: %d\n", BMP180_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (read_calibration() < 0) {
        fprintf(stderr, "Error reading BMP180 calibration data (sensor absent or bus error)\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);
    if (gpioSetISRFuncEx(BUTTON_GPIO, FALLING_EDGE, 0, button_isr, NULL) != 0) {
        fprintf(stderr, "Error setting ISR for button on GPIO %d\n", BUTTON_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    printf("Pressure logger ready. Press button on GPIO %d to toggle logging.\n", BUTTON_GPIO);
    while (running) {
        if (logging_enabled) {
            int raw_temp, raw_pressure;
            if (read_raw_temperature(&raw_temp) == 0 && read_raw_pressure(&raw_pressure) == 0) {
                int32_t pressure_pa = compute_pressure(raw_pressure, raw_temp);
                printf("Pressure: %d hPa\n", pressure_pa / 100.0);
                log_pressure(pressure_pa);
            } else {
                fprintf(stderr, "Error reading sensor data\n");
            }
        } else {
            printf("Logging disabled. Press button to enable.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    gpioSetISRFuncEx(BUTTON_GPIO, FALLING_EDGE, 0, NULL, NULL);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    printf("Exiting cleanly.\n");
    return 0;
}

