#define DEFAULT_URL "http://your-the-librarys-api-call.com/api/humidity"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

typedef struct {
    float humidity;
    float temperature;
    int status;
} DHT22Data;

static int read_dht22(int pin, DHT22Data *data) {
    int i, j;
    int bits[40] = {0};
    int laststate = 1;
    int counter = 0;
    int checksum = 0;

    data->humidity = -1.0;
    data->temperature = -1.0;
    data->status = -1;

    gpioSetMode(pin, PI_OUTPUT);
    gpioWrite(pin, 0);
    usleep(2000);
    gpioWrite(pin, 1);
    usleep(30);
    gpioSetMode(pin, PI_INPUT);

    for (i = 0; i < 85; i++) {
        counter = 0;
        while (gpioRead(pin) == laststate) {
            counter++;
            usleep(1);
            if (counter == 255) break;
        }
        laststate = gpioRead(pin);

        if (counter == 255) break;

        if ((i >= 4) && (i % 2 == 0)) {
            bits[i / 2] = counter - 1;
        }
    }

    if (counter == 255) return -1;

    for (j = 0; j < 40; j++) {
        if ((bits[j] > 16) || (bits[j] < 11)) return -1;
        if (j < 8) {
            checksum = checksum + bits[j];
        } else if (j % 2 == 0) {
            checksum = checksum + bits[j];
        }
    }

    if (checksum != ((bits[0] + bits[1] + bits[2] + bits[3]) & 0xFF)) {
        return -1;
    }

    data->humidity = (float)(((bits[0] << 8) + bits[1]) / 10.0);
    data->temperature = (float)(((bits[2] << 8) + bits[3]) / 10.0);
    data->status = 0;

    if (data->humidity > 100.0) return -1;
    if (data->temperature > 100.0) return -1;

    return 0;
}

static char *format_json(float humidity, float temperature) {
    char *json_string = malloc(100);
    if (json_string == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for JSON string");
        return NULL;
    }
    snprintf(json_string, 100, "{\"humidity\": %.1f, \"temperature\": %.1f}", humidity, temperature);
    return json_string;
}

static int post_data(const char *url, const char *json_string) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;
    int retries = 0;

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if (!curl) {
        syslog(LOG_ERR, "Failed to initialize curl");
        curl_global_cleanup();
        return -1;
    }

    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        syslog(LOG_ERR, "Failed to create HTTP headers");
        curl_easy_cleanup(curl);
        curl_global_cleanup();
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_string);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);

    do {
        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            syslog(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
            retries++;
            if (retries <= MAX_RETRIES) {
                sleep(2);
            }
        }
    } while (res != CURLE_OK && retries <= MAX_RETRIES);

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    curl_global_cleanup();

    if (res != CURLE_OK) {
        syslog(LOG_ERR, "Failed to post data after %d retries", MAX_RETRIES);
        return -1;
    }

    long http_code = 0;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
    if (http_code < 200 || http_code >= 300) {
        syslog(LOG_ERR, "HTTP request failed with status code: %ld", http_code);
        return -1;
    }

    syslog(LOG_INFO, "Data posted successfully with status code: %ld", http_code);
    return 0;
}

int main(int argc, char *argv[]) {
    const char *url = DEFAULT_URL;
    int opt;

    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s url]\n", argv[0]);
                return 1;
        }
    }

    openlog("dht22_logger", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "Starting DHT22 logger with URL: %s", url);

    while (running) {
        DHT22Data data;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && running) {
            if (read_dht22(DHT22_PIN, &data) == 0) {
                success = 1;
                break;
            }
            syslog(LOG_WARNING, "DHT22 read failed, retrying (%d/%d)", retries + 1, MAX_RETRIES);
            retries++;
            if (retries < MAX_RETRIES) {
                sleep(2);
            }
        }

        if (success) {
            char *json_string = format_json(data.humidity, data.temperature);
            if (json_string != NULL) {
                if (post_data(url, json_string) == 0) {
                    syslog(LOG_INFO, "Humidity: %.1f%%, Temperature: %.1f°C", data.humidity, data.temperature);
                } else {
                    syslog(LOG_ERR, "Failed to post data to server");
                }
                free(json_string);
            }
        } else {
            syslog(LOG_ERR, "Failed to read DHT22 sensor after %d retries", MAX_RETRIES);
        }

        for (int i = 0; i < READ_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    syslog(LOG_INFO, "Exiting gracefully");
    closelog();
    return 0;
}

