#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_FILE  "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE  "/var/log/fan_control.log"
#define POLL_INTERVAL_SEC 5

#define FAN_SPEED_OFF  0
#define FAN_SPEED_LOW  1
#define FAN_SPEED_MED  2
#define FAN_SPEED_HIGH 3

#define TEMP_THRESHOLD_LOW  45000
#define TEMP_THRESHOLD_MED  55000
#define TEMP_THRESHOLD_HIGH 65000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_cpu_temp(void) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }

    int temp = -1;
    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error reading temperature from %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp;
}

static int read_fan_speed(void) {
    FILE *fp = fopen(FAN_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", FAN_FILE, strerror(errno));
        return -1;
    }

    int speed = -1;
    if (fscanf(fp, "%d", &speed) != 1) {
        fprintf(stderr, "Error reading fan speed from %s\n", FAN_FILE);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return speed;
}

static int write_fan_speed(int speed) {
    FILE *fp = fopen(FAN_FILE, "w");
    if (!fp) {
        fprintf(stderr, "Error opening %s for writing: %s\n", FAN_FILE, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%d", speed) < 0) {
        fprintf(stderr, "Error writing fan speed to %s: %s\n", FAN_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", FAN_FILE, strerror(errno));
        return -1;
    }

    return 0;
}

static int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s for writing: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    return 0;
}

static int set_fan_speed(int temp) {
    int speed;

    if (temp < TEMP_THRESHOLD_LOW) {
        speed = FAN_SPEED_OFF;
    } else if (temp < TEMP_THRESHOLD_MED) {
        speed = FAN_SPEED_LOW;
    } else if (temp < TEMP_THRESHOLD_HIGH) {
        speed = FAN_SPEED_MED;
    } else {
        speed = FAN_SPEED_HIGH;
    }

    if (speed == g_current_fan_speed) {
        return 0;
    }

    if (write_fan_speed(speed) != 0) {
        return -1;
    }

    g_current_fan_speed = speed;

    char log_message[128];
    snprintf(log_message, sizeof(log_message), "Fan speed set to %d (temp=%d)", speed, temp);
    log_event(log_message);

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    FILE *fp = fopen(FAN_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error: Cannot read cooling_device0 max_state: %s. Creating default log entry.\n", strerror(errno));
        log_event("Fan control service started. Initializing cooling_device0 max_state.");
    } else {
        int max_state = -1;
        if (fscanf(fp, "%d", &max_state) != 1) {
            fprintf(stderr, "Error reading cooling_device0 max_state from %s. Assuming default max_state of 3.\n", FAN_FILE);
            max_state = 3;
        }
        fclose(fp);

        if (max_state < FAN_SPEED_OFF || max_state > FAN_SPEED_HIGH) {
            max_state = FAN_SPEED_HIGH;
            fprintf(stderr, "Warning: max_state out of range, setting to default max_state=%d\n", max_state);
        }
    }

    g_current_fan_speed = FAN_SPEED_OFF;

    log_event("Fan control service started.");

    while (g_running) {
        int temp = read_cpu_temp();
        if (temp < 0) {
            fprintf(stderr, "Error reading CPU temperature. Retrying in %d seconds.\n", POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        int current_speed = read_fan_speed();
        if (current_speed < 0) {
            fprintf(stderr, "Error reading current fan speed. Retrying in %d seconds.\n", POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        if (set_fan_speed(temp) != 0) {
            fprintf(stderr, "Error setting fan speed. Retrying in %d seconds.\n", POLL_INTERVAL_SEC);
        }

        sleep(POLL_INTERVAL_SEC);
    }

    if (write_fan_speed(FAN_SPEED_OFF) != 0) {
        fprintf(stderr, "Warning: Failed to set fan to off during shutdown.\n");
    }

    log_event("Fan control service stopped.");

    return 0;
}

