    FILE *fp = fopen(FAN_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error: Cannot read cooling_device0 max_state: %s. Creating default log entry.\n", strerror(errno));
        log_event("Fan control service started. Initializing cooling_device0 max_state.");
    } else {
        int max_state = -1;
        if (fscanf(fp, "%d", &max_state) != 1) {
            fprintf(stderr, "Error reading cooling_device0 max_state from %s. Assuming default max_state of 3.\n", FAN_FILE);
            max_state = 3;
        }
        fclose(fp);

        if (max_state < FAN_SPEED_OFF || max_state > FAN_SPEED_HIGH) {
            max_state = FAN_SPEED_HIGH;
            fprintf(stderr, "Warning: max_state out of range, setting to default max_state=%d\n", max_state);
        }
    }

    g_current_fan_speed = FAN_SPEED_OFF;

    log_event("Fan control service started.");

    while (g_running) {
        int temp = read_cpu_temp();
        if (temp < 0) {
            fprintf(stderr, "Error reading CPU temperature. Retrying in %d seconds.\n", POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        int current_speed = read_fan_speed();
        if (current_speed < 0) {
            fprintf(stderr, "Error reading current fan speed. Retrying in %d seconds.\n", POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        if (set_fan_speed(temp) != 0) {
            fprintf(stderr, "Error setting fan speed. Retrying in %d seconds.\n", POLL_INTERVAL_SEC);
        }

        sleep(POLL_INTERVAL_SEC);
    }

    if (write_fan_speed(FAN_SPEED_OFF) != 0) {
        fprintf(stderr, "Warning: Failed to set fan to off during shutdown.\n");
    }

    log_event("Fan control service stopped.");

    return 0;
}

