/*
 * PID temperature controller for Raspberry Pi Zero W.
 *
 * Hardware:
 *   - MAX31855 thermocouple amplifier on SPI0:
 *       CLK  -> GPIO11 (SPI0_SCLK)
 *       CS   -> GPIO8  (SPI0_CE0)
 *       DO   -> GPIO9  (SPI0_MISO)
 *   - Resistive heater on GPIO18 (hardware PWM, 1 kHz, 0-100% duty)
 *
 * Build:
 *   gcc -O2 -Wall -o heater_pid heater_pid.c -lpigpio -lrt
 * Run:
 *   sudo ./heater_pid
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define HEATER_GPIO          18
#define PWM_FREQUENCY        1000          /* Hz  */
#define PWM_RANGE            100           /* 0-100 % */
#define SPI_CHANNEL          0             /* SPI0 */
#define SPI_SPEED            500000        /* 500 kHz */
#define SPI_FLAGS            0             /* Mode 0, active-low CE */

#define TARGET_TEMPERATURE   50.0f
#define MAX_TEMPERATURE      100.0f
#define MIN_TEMPERATURE      0.0f
#define SAMPLE_INTERVAL_S    1.0
#define LOG_FILE             "heater_log.txt"

#define KP                   1.0f
#define KI                   0.1f
#define KD                   0.01f

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

/* PID state */
static float g_integral   = 0.0f;
static float g_prev_error = 0.0f;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static void log_data(float temp, float duty, float pid_out);
static void log_error(const char *msg);
static int  read_max31855(float *temp_out);
static void set_heater(float duty);
static float pid_compute(float temp);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Logging ----------------------------------- */
static void log_data(float temp, float duty, float pid_out)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_file, "%s, Temp: %.2f C, Duty: %.2f %%, PID: %.2f\n",
            ts, temp, duty, pid_out);
    fflush(g_log_file);
}

static void log_error(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(stderr, "[%s] ERROR: %s\n", ts, msg);
    if (g_log_file) {
        fprintf(g_log_file, "%s, ERROR: %s\n", ts, msg);
        fflush(g_log_file);
    }
}

/* ----------------------------- MAX31855 read ----------------------------- */
/*
 * MAX31855 32-bit SPI payload (MSB first):
 *   D[31:18]  Thermocouple temperature (14-bit signed, 0.25 C/LSB)
 *   D[17]     Reserved
 *   D[16]     Fault bit (1 = fault)
 *   D[15:4]   Internal reference-junction temp (12-bit signed, 0.0625 C/LSB)
 *   D[3]      Reserved
 *   D[2]      SCV fault  (short to VCC)
 *   D[1]      SCG fault  (short to GND)
 *   D[0]      OC  fault   (open circuit)
 */
static int read_max31855(float *temp_out)
{
    char rx[4] = {0, 0, 0, 0};
    int  bytes;

    bytes = spiRead(g_spi_handle, rx, 4);
    if (bytes != 4) {
        log_error("SPI read failed or incomplete");
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] <<  8) |
                   ((uint32_t)(uint8_t)rx[3]);

    /* Fault bit (D16) */
    if (raw & 0x00010000) {
        if (raw & 0x00000004) {
            log_error("MAX31855 fault: short to VCC");
        } else if (raw & 0x00000002) {
            log_error("MAX31855 fault: short to GND");
        } else if (raw & 0x00000001) {
            log_error("MAX31855 fault: open circuit");
        } else {
            log_error("MAX31855 fault: unknown");
        }
        return -1;
    }

    /* Thermocouple temperature: bits 31..18 (14-bit signed, 0.25 C/LSB) */
    int16_t therm = (int16_t)((raw >> 18) & 0x3FFF);
    if (therm & 0x2000) {
        therm |= 0xC000;          /* sign-extend 14 -> 16 bits */
    }
    *temp_out = (float)therm * 0.25f;
    return 0;
}

/* ----------------------------- Heater PWM -------------------------------- */
static void set_heater(float duty)
{
    if (duty < 0.0f) duty = 0.0f;
    if (duty > 100.0f) duty = 100.0f;

    int pwm = (int)(duty + 0.5f);
    if (gpioPWM(HEATER_GPIO, pwm) < 0) {
        log_error("gpioPWM failed");
    }
}

/* ----------------------------- PID --------------------------------------- */
static float pid_compute(float temp)
{
    float error = TARGET_TEMPERATURE - temp;

    /* Proportional */
    float p = KP * error;

    /* Integral with anti-windup clamp */
    g_integral += error;
    if (g_integral > 100.0f) g_integral = 100.0f;
    if (g_integral < 0.0f)   g_integral = 0.0f;
    float i = g_integral;

    /* Derivative */
    float d = KD * (error - g_prev_error);
    g_prev_error = error;

    return p + i + d;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    /* Heater off */
    gpioPWM(HEATER_GPIO, 0);

    /* Close SPI */
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    /* Close log */
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure heater GPIO for PWM */
    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", HEATER_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    gpioPWM(HEATER_GPIO, 0);

    /* Open SPI */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel %d, %d Hz): %s\n",
                SPI_CHANNEL, SPI_SPEED, pigpio_error(g_spi_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE ")");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("PID controller started. Target: %.1f C. Ctrl+C to exit.\n",
           TARGET_TEMPERATURE);

    while (g_running) {
        float temp = 0.0f;

        if (read_max31855(&temp) != 0) {
            /* Sensor fault: disable heater, reset PID, log and wait */
            set_heater(0.0f);
            g_integral = 0.0f;
            g_prev_error = 0.0f;
            time_sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        if (temp < MIN_TEMPERATURE || temp > MAX_TEMPERATURE) {
            log_error("Temperature out of safe range (< 0 C or > 100 C)");
            set_heater(0.0f);
            g_integral = 0.0f;
            g_prev_error = 0.0f;
            time_sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        float pid = pid_compute(temp);
        set_heater(pid);
        log_data(temp, pid, pid);

        time_sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

