code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define LOG_FILE "cooling_log.csv"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_data(float temperature, int duty_cycle_percent) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("Error getting time");
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("Error converting time");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle_percent) < 0) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }

    return 0;
}

static int set_fan_speed(float temperature) {
    int duty_cycle_percent;

    if (temperature < 40.0f) {
        duty_cycle_percent = 0;
    } else if (temperature >= 70.0f) {
        duty_cycle_percent = 100;
    } else {
        duty_cycle_percent = (int)(((temperature - 40.0f) / (70.0f - 40.0f)) * 100.0f);
    }

    int duty_cycle = (duty_cycle_percent * 1000000) / 100;

    if (gpioPWM(FAN_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle to %d\n", duty_cycle);
        return -1;
    }

    return duty_cycle_percent;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error registering SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error registering SIGTERM handler");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO%d as output\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error setting PWM frequency to %d Hz\n", PWM_FREQUENCY);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(FAN_GPIO, 1000000) != 0) {
        fprintf(stderr, "Error setting PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(FAN_GPIO, 0) != 0) {
        fprintf(stderr, "Error initializing PWM to 0\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "r");
    if (fp == NULL) {
        fp = fopen(LOG_FILE, "w");
        if (fp == NULL) {
            perror("Error creating log file");
            gpioPWM(FAN_GPIO, 0);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (fprintf(fp, "Timestamp,Temperature (C),PWM Duty Cycle (%%)\n") < 0) {
            perror("Error writing header to log file");
            fclose(fp);
            gpioPWM(FAN_GPIO, 0);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (fclose(fp) != 0) {
            perror("Error closing log file after header write");
            gpioPWM(FAN_GPIO, 0);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    } else {
        if (fclose(fp) != 0) {
            perror("Error closing log file after checking existence");
            gpioPWM(FAN_GPIO, 0);
            gpioTerminate();
            return EXIT_FAILURE;
