#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define ENCODER_A 17
#define ENCODER_B 18
#define LOG_FILE "encoder_log.txt"
#define PULSES_PER_REVOLUTION 360

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(ENCODER_A, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", ENCODER_A);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(ENCODER_B, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", ENCODER_B);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(ENCODER_A, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", ENCODER_A);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(ENCODER_B, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", ENCODER_B);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_encoder_state(void) {
    int a = gpioRead(ENCODER_A);
    int b = gpioRead(ENCODER_B);
    if (a < 0 || b < 0) {
        fprintf(stderr, "Error: failed to read GPIO state (A=%d, B=%d).\n", a, b);
        return -1;
    }
    return (a << 1) | b;
}

static double calculate_angle(int state) {
    static int last_state = -1;
    if (last_state == -1) {
        last_state = state;
        return 0.0;
    }

    int delta = state - last_state;
    if (delta < 0) delta += (1 << 2);

    double angle = (delta * 360.0) / (1 << 2);
    last_state = state;
    return angle;
}

static int log_angle(double angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed.\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, %.2f\n", timestamp, angle) < 0) {
        fprintf(stderr, "Error: failed to write to log file.\n");
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: failed to flush log file.\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Encoder monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int state = read_encoder_state();
        if (state < 0) {
            fprintf(stderr, "Error: encoder read failed, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        double angle = calculate_angle(state);

        if (log_angle(angle) != 0) {
            fprintf(stderr, "Error: logging failed, continuing...\n");
        }

        gpioDelay(1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

