/*
 * ADPD144RI Red/IR Photometric Sensor Logger
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL), address 0x50
 * LED:    GPIO17 (active-high)
 *
 * Build:  gcc -O2 -Wall -o adpd144ri_log adpd144ri_log.c -lpigpio -lrt
 * Run:    sudo ./adpd144ri_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADPD144RI constants (from ADI datasheet) ---- */
#define ADPD144RI_I2C_ADDR      0x50
#define ADPD144RI_REG_MODE      0x00
#define ADPD144RI_REG_DATA      0x01
#define ADPD144RI_MODE_CONTIN   0x01
#define ADPD144RI_MODE_SLEEP    0x00

/* ---- Application constants ---- */
