static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        /* Put sensor into sleep mode so it consumes no power */
        if (i2cWriteByteData(g_i2c_fd, ADPD144RI_REG_MODE,
                             ADPD144RI_MODE_SLEEP) < 0) {
            fprintf(stderr, "Warning: failed to put ADPD144RI to sleep\n");
        }
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
    }

    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }

    /* Ensure LED is off before releasing pigpio */
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Write a timestamped CSV row.  Returns 0 on success, -1 on error.   */
static int log_data(FILE *fp, int red, int ir)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }

    struct tm tm_local;
    if (localtime_r(&ts.tv_sec, &tm_local) == NULL) {
        perror("localtime_r");
        return -1;
    }

    char ts_str[40];
    if (strftime(ts_str, sizeof(ts_str), "%Y-%m-%d %H:%M:%S", &tm_local) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s.%09ld,%d,%d\n", ts_str, ts.tv_nsec, red, ir) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
