        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return -1;
    }
    gpioWrite(LED_GPIO, 0);

    g_i2c_fd = i2cOpen(I2C_BUS, ADPD144RI_I2C_ADDR, 0);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, ADPD144RI_I2C_ADDR, g_i2c_fd);
        gpioTerminate();
        return -1;
    }

    /* Probe: try a read of the data register to confirm the sensor is present */
    char probe = 0;
    if (i2cReadByteData(g_i2c_fd, ADPD144RI_REG_DATA) < 0) {
        fprintf(stderr, "ADPD144RI not responding on I2C bus %d addr 0x%02X\n",
                I2C_BUS, ADPD144RI_I2C_ADDR);
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
        gpioTerminate();
        return -1;
    }

    /* Start continuous conversion mode */
    if (i2cWriteByteData(g_i2c_fd, ADPD144RI_REG_MODE,
                         ADPD144RI_MODE_CONTIN) < 0) {
        fprintf(stderr, "Failed to start ADPD144RI continuous mode\n");
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
        gpioTerminate();
        return -1;
    }

