#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS         "/dev/i2c-1"
#define ADPD144RI_ADDR  0x50
#define GPIO_LED        17
#define IR_THRESHOLD    2000
#define LOG_FILE        "adpd144ri_log.txt"
#define SAMPLE_DELAY_US 100000  /* 100 ms */

/* ADPD144RI register addresses (16-bit, big-endian on the bus) */
#define REG_MODE        0x0002
#define REG_DATA        0x0004
#define REG_RESET       0x0008

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg16(int fd, uint16_t reg, uint16_t value)
{
    uint8_t buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint16_t *value)
{
    uint8_t addr[2];
    uint8_t data[2];

    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (write(fd, addr, sizeof(addr)) != (ssize_t)sizeof(addr)) {
        fprintf(stderr, "I2C write (addr) for reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }

    if (read(fd, data, sizeof(data)) != (ssize_t)sizeof(data)) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }

    *value = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

static int adpd144ri_init(int fd)
{
    /* Software reset */
    if (i2c_write_reg16(fd, REG_RESET, 0x0001) < 0)
        return -1;
    usleep(10000); /* 10 ms settle */

    /* Program mode: continuous sampling */
    if (i2c_write_reg16(fd, REG_MODE, 0x0001) < 0)
        return -1;

    return 0;
}

static int read_adpd144ri(int fd, uint16_t *red, uint16_t *ir)
{
    if (i2c_read_reg16(fd, REG_DATA, red) < 0)
        return -1;
    if (i2c_read_reg16(fd, REG_DATA + 2, ir) < 0)
        return -1;
    return 0;
}

static void log_data(FILE *fp, uint16_t red, uint16_t ir)
