#define REG_MODE        0x0002
#define REG_DATA        0x0004
#define REG_RESET       0x0008

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
