#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x25
#define LOG_FILE       "flow_log.csv"
#define SAMPLE_US      1000000  /* 1 second */
#define FLOW_SCALE     0.001    /* SLF3S-4000B: raw * 0.001 = uL/min */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ---- CRC-8 (Sensirion polynomial 0x31, init 0xFF) ---- */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int read_flow_rate(float *flow_rate_ul_min)
{
    uint8_t cmd[2] = {0x36, 0x08};  /* continuous measurement, 1 Hz */
    uint8_t buf[3];

    if (i2cWriteDevice(g_i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed\n");
        return -1;
    }

    /* SLF3S-4000B needs ~1 ms before data is ready */
    gpioDelay(2000);

    if (i2cReadDevice(g_i2c_handle, (char *)buf, 3) != 3) {
        fprintf(stderr, "Error: i2cReadDevice failed\n");
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch (calc=0x%02X recv=0x%02X)\n",
                crc8(buf, 2), buf[2]);
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *flow_rate_ul_min = (float)raw * FLOW_SCALE;
    return 0;
}

static int log_flow_rate(float flow_rate)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%04d-%02d-%02d %02d:%02d:%02d,%.3f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, flow_rate) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Error: fflush failed\n");
        return -1;
    }
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,flow_rate_uL_min\n");
        fflush(g_log_file);
    }

    while (g_running) {
        float flow_rate;
        if (read_flow_rate(&flow_rate) == 0) {
            if (log_flow_rate(flow_rate) != 0) {
                fprintf(stderr, "Warning: logging failed for this sample\n");
            }
        } else {
            fprintf(stderr, "Warning: read_flow_rate failed, retrying next cycle\n");
        }
        gpioDelay(SAMPLE_US);
    }

    /* Graceful cleanup */
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

