#define I2C_BUS 1
#define I2C_ADDR 0x29
#define LOG_FILE "air_quality_log.csv"
#define READ_INTERVAL_SEC 5

/* MICS-VZ-89TE register map (16-bit registers, big-endian on the bus) */
#define REG_STATUS 0x00
#define REG_TVOC   0x02
#define REG_ECO2   0x04
#define REG_TEMP   0x06
#define REG_HUMID  0x08

#define STATUS_OK 0x0000
#define STATUS_ERR 0xFFFF

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_register16(int handle, uint8_t reg, uint16_t *out) {
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (rc != 2) {
        return -1;
    }
    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int read_sensor(int handle, uint16_t *tvoc, uint16_t *eco2) {
    uint16_t status;
    if (read_register16(handle, REG_STATUS, &status) != 0) {
        return -1;
    }
    if (status == STATUS_ERR) {
        return -2; /* sensor reports an error condition */
    }
    if (read_register16(handle, REG_TVOC, tvoc) != 0) {
        return -1;
    }
    if (read_register16(handle, REG_ECO2, eco2) != 0) {
        return -1;
    }
    return 0;
}

static float calculate_iaq(uint16_t tvoc, uint16_t eco2) {
    /*
     * Placeholder linear model:
     *   IAQ = 100 - 0.5 * (TVOC_ppb + eCO2_ppm)
     * Replace with a calibrated model from the Honeywell MICS-VZ-89TE datasheet
     * once the sensor is physically connected and the calibration constants are known.
     */
    return 100.0f - 0.5f * ((float)tvoc + (float)eco2);
}

static void log_data(FILE *fp, float iaq, uint16_t tvoc, uint16_t eco2) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, iaq, tvoc, eco2);
    fflush(fp);
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if the file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,iaq,tvoc_ppb,eco2_ppm\n");
        fflush(g_log_file);
    }

    printf("MICS-VZ-89TE air quality logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t tvoc = 0, eco2 = 0;
        int rc = read_sensor(g_i2c_handle, &tvoc, &eco2);

        if (rc == -1) {
            fprintf(stderr, "I2C read error (sensor may be absent or bus fault)\n");
        } else if (rc == -2) {
            fprintf(stderr, "Sensor status error (0x%04X) — sensor may be in fault mode\n",
                    STATUS_ERR);
        } else {
            float iaq = calculate_iaq(tvoc, eco2);
            log_data(g_log_file, iaq, tvoc, eco2);
            printf("TVOC: %u ppb, eCO2: %u ppm, IAQ: %.2f\n", tvoc, eco2, iaq);
        }

        /* Sleep in 1-second increments so SIGINT is caught promptly */
        for (int i = 0; i < READ_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

