#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_GPIO 17
#define POLL_INTERVAL_US  100000   /* 100 ms */
#define ALERT_THRESHOLD_S 5        /* seconds */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Returns 1 if the sensor is currently HIGH (touched), 0 if LOW (released),
 * and -1 on read error.
 */
static int read_touch_sensor(int gpio_pin)
{
    int level = gpioRead(gpio_pin);
    if (level < 0) {
        fprintf(stderr, "gpioRead failed on GPIO %d: %s\n",
                gpio_pin, strerror(errno));
        return -1;
    }
    return level;
}

int main(void)
{
    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Configure the touch sensor GPIO as input --- */
    if (gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed on GPIO %d: %s\n",
                TOUCH_SENSOR_GPIO, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Give the sensor a brief settle period after power-up --- */
    gpioDelay(500000);  /* 500 ms */

    /* --- Main monitoring loop --- */
    int touched = 0;
    int alert_sent = 0;
    time_t touched_since = 0;

    while (g_running) {
        int level = read_touch_sensor(TOUCH_SENSOR_GPIO);
        if (level < 0) {
            /* Read error — exit cleanly */
            break;
        }

        if (level == 1) {
            if (!touched) {
                touched = 1;
                touched_since = time(NULL);
            } else {
                /*
                 * Sensor remains continuously HIGH.  If we have not yet
                 * alerted and the elapsed time exceeds the threshold,
                 * print an alert and reset the timer so the same touch
                 * does not repeat the alert.
                 */
                if (!alert_sent &&
                    (time(NULL) - touched_since) > ALERT_THRESHOLD_S) {
                    printf("INTRUSION DETECTED: Touch sensor on GPIO %d "
                           "has been continuously HIGH for %d seconds.\n",
                           TOUCH_SENSOR_GPIO, ALERT_THRESHOLD_S);
                    fflush(stdout);
                    alert_sent = 1;
                }
            }
        } else {
            /* LOW — touch released */
            touched = 0;
            alert_sent = 0;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* --- Cleanup --- */
    gpioTerminate();
    return EXIT_SUCCESS;
}

