/*
 * Raspberry Pi 4 Model B - INMP441 I2S MEMS Microphone Capture
 *
 * Captures 16-bit PCM audio from an INMP441 via the I2S bus using ALSA
 * and writes it to audio_capture.pcm. Drives GPIO 17 (BCM) to select the
 * left channel (L/R select line).
 *
 * Build: gcc -O2 -Wall -o audio_capture audio_capture.c -lm
 * Run:   ./audio_capture
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/soundcard.h>

#define I2S_DEVICE      "/dev/snd/pcmC0D0c"
#define GPIO_CH_SELECT  17          /* BCM pin for L/R channel select */
#define SAMPLE_RATE     44100       /* Hz */
#define BITS_PER_SAMPLE 16
#define CHANNELS        1           /* Mono capture (left channel) */
#define BUFFER_SIZE     4096
#define CAPTURE_FILE    "audio_capture.pcm"

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
