#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define FAN_PWM_PIN 18
#define PWM_FREQUENCY 100
#define DEBOUNCE_DELAY_US 50000
#define POLL_DELAY_US 50000
#define FAN_PWM_DUTY_CYCLE 128
#define LOG_FILE_NAME "flame_log.txt"
#define SENSOR_TIMEOUT_SEC 5

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static void log_event(const char *event_type) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char timestamp[32];
    if (t == NULL) {
        strncpy(timestamp, "UNKNOWN", sizeof(timestamp));
        timestamp[sizeof(timestamp) - 1] = '\0';
    } else {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    }
    fprintf(log_file, "%s: %s\n", timestamp, event_type);
    fflush(log_file);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set flame sensor pin mode.\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(FAN_PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set fan PWM pin mode.\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(FAN_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency.\n");
        gpioTerminate();
        return -1;
    }
    if (gpioPWM(FAN_PWM_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise PWM duty cycle.\n");
        gpioTerminate();
        return -1;
    }
    return 0;
}

static void cleanup_gpio(void) {
    gpioPWM(FAN_PWM_PIN, 0);
    gpioSetMode(FAN_PWM_PIN, PI_INPUT);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    log_event("System started");

    if (initialize_gpio() != 0) {
        log_event("GPIO initialization failed");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    int last_flame_state = 1;
    int flame_active = 0;
    time_t flame_start_time = 0;
    int sensor_ok = 1;

    while (program_running) {
        int flame_sensor_value = gpioRead(FLAME_SENSOR_PIN);
        if (flame_sensor_value < 0) {
            fprintf(stderr, "Error: failed to read flame sensor pin.\n");
            log_event("Error: failed to read flame sensor");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (flame_sensor_value != last_flame_state) {
            gpioDelay(DEBOUNCE_DELAY_US);
            int confirmed_value = gpioRead(FLAME_SENSOR_PIN);
            if (confirmed_value < 0) {
                fprintf(stderr, "Error: failed to read flame sensor during debounce.\n");
                log_event("Error: failed to read flame sensor during debounce");
                last_flame_state = flame_sensor_value;
                continue;
            }
            if (confirmed_value == flame_sensor_value) {
                last_flame_state = flame_sensor_value;
            }
        }

        if (flame_sensor_value == 0 && last_flame_state == 1) {
            flame_active = 1;
            flame_start_time = time(NULL);
            log_event("Flame detected");
        } else if (flame_sensor_value == 1 && last_flame_state == 0) {
            if (flame_active) {
                log_event("Flame ended");
                flame_active = 0;
            }
        }

        if (flame_active) {
            if (gpioPWM(FAN_PWM_PIN, FAN_PWM_DUTY_CYCLE) != 0) {
                fprintf(stderr, "Error: failed to start PWM.\n");
                log_event("Error: failed to start PWM");
            }
        } else {
            if (gpioPWM(FAN_PWM_PIN, 0) != 0) {
                fprintf(stderr, "Error: failed to stop PWM.\n");
                log_event("Error: failed to stop PWM");
            }
        }

        if (flame_sensor_value == 1) {
            sensor_ok = 0;
        } else {
            sensor_ok = 1;
        }

        if (sensor_ok && (time(NULL) - flame_start_time > SENSOR_TIMEOUT_SEC)) {
            fprintf(stderr, "Error: sensor timeout - sensor may be absent or disconnected.\n");
            log_event("Error: sensor timeout - sensor may be absent or disconnected");
            sensor_ok = 0;
        }

        gpioDelay(POLL_DELAY_US);
    }

    log_event("System shutting down");
    cleanup_gpio();
    fclose(log_file);
    return EXIT_SUCCESS;
}

