static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl SPI_IOC_WR_MODE");
        close(spi_fd); spi_fd = -1; return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl SPI_IOC_WR_BITS_PER_WORD");
        close(spi_fd); spi_fd = -1; return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl SPI_IOC_WR_MAX_SPEED_HZ");
        close(spi_fd); spi_fd = -1; return -1;
    }

    return 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {0};
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl SPI_IOC_MESSAGE");
        return -1;
    }
    return 0;
}

static int gpio_init(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(FRAME_TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(DATA_READY_PIN, PI_INPUT);
    gpioWrite(FRAME_TRIGGER_PIN, 0);

    return 0;
}

static void gpio_cleanup(void) {
    gpioWrite(FRAME_TRIGGER_PIN, 0);
    gpioTerminate();
}

static int log_init(void) {
    log_file = fopen("radar_log.bin", "wb");
    if (!log_file) {
        perror("fopen radar_log.bin");
        return -1;
    }
    return 0;
}

static void log_cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static int log_write_header(const MmwHeader *hdr) {
    uint8_t hdr_buf[HEADER_SIZE];
    memcpy(hdr_buf, hdr, sizeof(*hdr));
    if (fwrite(hdr_buf, 1, HEADER_SIZE, log_file) != HEADER_SIZE) {
        perror("fwrite header");
        return -1;
    }
    return 0;
}

static int log_write_frame(uint32_t frame_num, uint32_t cpu_cycles, const uint8_t *data, size_t data_len) {
    FrameHeader fh;
    fh.frameNumber = frame_num;
    fh.timeCpuCycles = cpu_cycles;

    uint8_t packet[HEADER_SIZE + data_len];
    memcpy(packet, &fh, sizeof(fh));
    memcpy(packet + sizeof(fh), data, data_len);

    if (fwrite(packet, 1, HEADER_SIZE + data_len, log_file) != (size_t)(HEADER_SIZE + data_len)) {
        perror("fwrite frame");
        return -1;
    }
    return 0;
}

static int log_flush(void) {
    if (fflush(log_file) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

