/*
 * OPT3001 Ambient Light Sensor Logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   OPT3001 SDA -> GPIO2 (I2C bus 1 SDA)
 *   OPT3001 SCL -> GPIO3 (I2C bus 1 SCL)
 *   OPT3001 VDD -> 3.3 V
 *   OPT3001 GND -> GND
 *
 * Build: gcc -O2 -Wall -o opt3001_logger opt3001_logger.c -lpigpio -lrt
 * Run:   sudo ./opt3001_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- OPT3001 register definitions (verified against TI datasheet) ---- */
#define OPT3001_I2C_ADDR      0x44
#define REG_RESULT           0x00
#define REG_CONFIGURATION    0x01
#define REG_MANUFACTURER_ID  0x7E
#define REG_DEVICE_ID        0x7F

/*
 * Configuration register (0x01) value:
 *   Bits 15-12 : Range number (0000 = auto-range, 1000 = 1 lx)
 *   Bits 11-10 : Conversion time (00 = 256 ms, 10 = 100 ms)
 *   Bit  9     : Reserved
 *   Bit  8     : Operational mode (0 = power-down, 1 = continuous)
 *   Bits 7-4   : Reserved
 *   Bit  3     : Latch (0 = normal, 1 = latch)
 *   Bit  2     : Reserved
 *   Bit  1     : Polarity (0 = normal, 1 = inverted)
 *   Bit  0     : Reserved
 *
 * Value = 0x0001 -> auto-range, 100 ms conversion, continuous mode, normal polarity.
 */
#define CONFIG_VALUE         0x0001

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to an OPT3001 register (big-endian on the bus). */
static int opt3001_write_reg(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "[ERROR] i2cWriteDevice to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from an OPT3001 register (big-endian on the bus). */
static int opt3001_read_reg(int handle, uint8_t reg, uint16_t *out)
{
    char reg_buf[1] = { (char)reg };
    char data[2]   = {0, 0};

    if (i2cWriteDevice(handle, reg_buf, 1) != 1) {
        fprintf(stderr, "[ERROR] i2cWriteDevice (reg select 0x%02X) failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice from reg 0x%02X failed\n", reg);
        return -1;
    }
    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
static int opt3001_init(int handle)
{
    uint16_t manuf_id = 0, dev_id = 0;

    /* Verify sensor presence by reading manufacturer / device ID registers. */
    if (opt3001_read_reg(handle, REG_MANUFACTURER_ID, &manuf_id) != 0) {
        fprintf(stderr, "[ERROR] Cannot read manufacturer ID – sensor absent or bus error\n");
        return -1;
    }
    if (manuf_id != 0x5449) {          /* 'TI' expected for OPT3001 */
        fprintf(stderr, "[ERROR] Unexpected manufacturer ID 0x%04X (expected 'TI')\n", manuf_id);
        return -1;
    }

    if (opt3001_read_reg(handle, REG_DEVICE_ID, &dev_id) != 0) {
        fprintf(stderr, "[ERROR] Cannot read device ID\n");
        return -1;
    }
    if (dev_id != 0x0001) {           /* OPT3001 device ID is 0x0001 */
        fprintf(stderr, "[ERROR] Unexpected device ID 0x%04X (expected 0x0001)\n", dev_id);
        return -1;
    }

    /* Configure for auto-range, 100 ms conversion, continuous mode. */
    if (opt3001_write_reg(handle, REG_CONFIGURATION, CONFIG_VALUE) != 0) {
        fprintf(stderr, "[ERROR] Failed to configure OPT3001\n");
        return -1;
    }

    /* Allow first conversion to complete (100 ms conversion time). */
    gpioDelay(150000);  /* microseconds */
    return 0;
}

/* ------------------------------------------------------------------ */
/*
 * Read lux value from the OPT3001 result register.
 * Returns 0 on success and stores lux in *lux_out; returns -1 on error.
 */
static int opt3001_read_lux(int handle, float *lux_out)
{
    uint16_t raw = 0;

    if (opt3001_read_reg(handle, REG_RESULT, &raw) != 0) {
        return -1;
    }

    /*
     * Result register format (16-bit, big-endian):
     *   Bits 15-12 : Exponent (0-3)
     *   Bits 11-0  : Mantissa (0-4095)
     * Lux = mantissa * 0.01 * (2^exponent)
     */
    uint8_t exponent = (raw >> 12) & 0x0F;
    uint16_t mantissa = raw & 0x0FFF;
    *lux_out = (float)mantissa * 0.01f * (float)(1u << exponent);
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float lux)
{
    time_t t = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "[ERROR] strftime failed\n");
        return;
    }

    if (fprintf(fp, "%s, %.2f lux\n", timestamp, lux) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log file failed\n");
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "[ERROR] fflush failed\n");
    }
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio library. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the OPT3001 address. */
    g_i2c_handle = i2cOpen(1, OPT3001_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor. */
    if (opt3001_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] OPT3001 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode. */
    g_log_file = fopen("light_data.txt", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open light_data.txt for appending\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed\n");
    }

    printf("OPT3001 logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop. */
    while (g_running) {
        float lux = 0.0f;

        if (opt3001_read_lux(g_i2c_handle, &lux) == 0) {
            log_data(g_log_file, lux);
        } else {
            fprintf(stderr, "[WARN] Read error – will retry next cycle\n");
        }

        /*
         * OPT3001 conversion time is 100 ms.  Sleep 150 ms to avoid
         * hammering the sensor and to stay within a 100 ms cadence.
         */
        gpioDelay(150000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

