#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN  17
#define CENTER_SENSOR_PIN 18
#define RIGHT_SENSOR_PIN  27
#define POLL_DELAY_US     50000  /* 50 ms */

static volatile sig_atomic_t g_terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

int main(void)
{
    int rc;

    /* --- Install signal handlers for graceful shutdown --- */
    rc = signal(SIGINT, signal_handler);
    if (rc == SIG_ERR) {
        perror("signal(SIGINT)");
        return EXIT_FAILURE;
    }
    rc = signal(SIGTERM, signal_handler);
    if (rc == SIG_ERR) {
        perror("signal(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "pigpio initialisation failed (code %d)\n", rc);
        return EXIT_FAILURE;
    }

    /* --- Configure sensor pins as inputs --- */
    rc = gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    if (rc != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input (code %d)\n",
                LEFT_SENSOR_PIN, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    rc = gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT);
    if (rc != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input (code %d)\n",
                CENTER_SENSOR_PIN, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    rc = gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    if (rc != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input (code %d)\n",
                RIGHT_SENSOR_PIN, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Main polling loop --- */
    while (!g_terminate) {
        int left   = gpioRead(LEFT_SENSOR_PIN);
        int center = gpioRead(CENTER_SENSOR_PIN);
        int right  = gpioRead(RIGHT_SENSOR_PIN);

        if (left < 0 || center < 0 || right < 0) {
            fprintf(stderr, "gpioRead failed (left=%d, center=%d, right=%d)\n",
                    left, center, right);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        printf("Left: %d, Center: %d, Right: %d\n", left, center, right);
        fflush(stdout);

        usleep(POLL_DELAY_US);
    }

    /* --- Graceful shutdown --- */
    gpioTerminate();
    return EXIT_SUCCESS;
}

