#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define NUM_CHANNELS 8
#define POLL_DELAY_US 100000  /* 100 ms */

/* TTP226 OUT1..OUT8 mapped to BCM GPIO 2,3,4,5,6,7,8,9 */
static const int channel_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

int main(void)
{
    int rc;
    int gpio_values[NUM_CHANNELS];
    int previous_values[NUM_CHANNELS];
    int first_read = 1;
    int read_error = 0;

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", rc);
        fprintf(stderr, "       Is the pigpio daemon running? Try: sudo killall pigpiod\n");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip that controls BCM GPIO 2-9 (gpiochip0 on Pi Zero W) */
    int chip_handle = gpioOpen(0, 0);
    if (chip_handle < 0) {
        fprintf(stderr, "Error: failed to open gpiochip0 (code %d).\n", chip_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Request each channel as an input */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int pin = channel_pins[i];
        rc = gpioSetMode(pin, PI_INPUT);
        if (rc != 0) {
            fprintf(stderr, "Error: failed to set BCM GPIO %d as input (code %d).\n", pin, rc);
            goto cleanup;
        }
    }

    /* Read initial states so we can detect changes */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int pin = channel_pins[i];
        int value = gpioRead(pin);
        if (value < 0) {
            fprintf(stderr, "Error: failed to read BCM GPIO %d (code %d).\n", pin, value);
            read_error = 1;
            goto cleanup;
        }
        previous_values[i] = value;
    }

    printf("TTP226 touch sensor monitoring started.\n");
    printf("Pins: OUT1=BCM2, OUT2=BCM3, OUT3=BCM4, OUT4=BCM5, OUT5=BCM6, OUT6=BCM7, OUT7=BCM8, OUT8=BCM9\n");
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (program_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int pin = channel_pins[i];
            int value = gpioRead(pin);
            if (value < 0) {
                fprintf(stderr, "Error: failed to read BCM GPIO %d (code %d).\n", pin, value);
                read_error = 1;
                break;
            }
            if (value != previous_values[i]) {
                printf("%s - Channel %d: %d\n",
                       first_read ? "" : "  ",
                       i + 1,
                       value);
                fflush(stdout);
                previous_values[i] = value;
                first_read = 0;
            }
        }
        if (!first_read && !read_error) {
            printf("  " "No changes on channels 2-9\n");
            fflush(stdout);
        }
        first_read = 0;
        usleep(POLL_DELAY_US);
    }

cleanup:
    /* Release all line requests and close the chip */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpioSetMode(channel_pins[i], PI_INPUT);  /* release mode */
    }
    gpioClose(chip_handle);

    if (read_error) {
        fprintf(stderr, "Warning: sensor read error encountered. Exiting.\n");
    }

    gpioTerminate();
    return (read_error || !program_running) ? EXIT_FAILURE : EXIT_SUCCESS;
}

