#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */

static const int channel_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

int main(void)
{
    int rc;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize the pigpio library */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", rc);
        return EXIT_FAILURE;
    }

    /* Configure each channel pin as an input with pull-down resistor */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(channel_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as input.\n", channel_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(channel_pins[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Error: failed to set pull-down on GPIO %d.\n", channel_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* Main sampling loop */
    while (program_running) {
        int states[NUM_CHANNELS];
        int read_failed = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            states[i] = gpioRead(channel_pins[i]);
            if (states[i] < 0) {
                fprintf(stderr, "Error: gpioRead failed on GPIO %d.\n", channel_pins[i]);
                read_failed = 1;
                break;
            }
        }

        if (read_failed) {
            break;
        }

        /* Print the state of each channel */
        printf("[+1234 ms] CH1=%d CH2=%d ... CH8=%d\n",
               states[0], states[1], states[2], states[3],
               states[4], states[5], states[6], states[7]);
        fflush(stdout);

        /* Sleep for the sample interval; gpioDelay is microsecond-accurate */
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Clean up: terminate the pigpio library */
    gpioTerminate();
    return EXIT_SUCCESS;
}

