/*
 * Raspberry Pi 3 Model B+ — Dual TMAG5110 Hall-Effect Latch Sensor Reader
 *
 * Wiring:
 *   Sensor 1 OUT -> BCM GPIO4 (physical pin 7)
 *   Sensor 2 OUT -> BCM GPIO5 (physical pin 10)
 *   Both sensors: VCC -> 3.3 V, GND -> GND, VSH -> 3.3 V (external pull-up enabled)
 *
 * The TMAG5110 output is open-drain with the pull-up enabled, so an
 * unmagnetized output reads HIGH and a magnet-detected assertion reads LOW.
 *
 * Build:
 *   gcc -Wall -o hall_effect hall_effect.c -lthe_driver_library -lrt
 *
 * Run:
 *   ./hall_effect
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <stdbool.h>
#include <the_driver_library.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 5
#define POLL_INTERVAL_US 500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Initialize the driver library */
    if (the_driver_library_init() != 0) {
        fprintf(stderr, "Error: the_driver_library_init() failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure sensor pins as inputs */
    if (gpio_set_mode(SENSOR1_PIN, GPIO_MODE_INPUT) != 0) {
        fprintf(stderr, "Error: gpio_set_mode(%d, INPUT) failed.\n", SENSOR1_PIN);
        the_driver_library_terminate();
        return EXIT_FAILURE;
    }
    if (gpio_set_mode(SENSOR2_PIN, GPIO_MODE_INPUT) != 0) {
        fprintf(stderr, "Error: gpio_set_mode(%d, INPUT) failed.\n", SENSOR2_PIN);
        the_driver_library_terminate();
        return EXIT_FAILURE;
    }

    printf("TMAG5110 Hall-Effect Sensor Reader\n");
    printf("  Sensor 1: BCM GPIO%d (physical pin 7)\n", SENSOR1_PIN);
    printf("  Sensor 2: BCM GPIO%d (physical pin 10)\n", SENSOR2_PIN);
    printf("  Poll interval: %d ms\n", POLL_INTERVAL_US / 1000);
    printf("  Press Ctrl+C to exit.\n\n");

    while (g_running) {
        int s1 = gpio_read(SENSOR1_PIN);
        int s2 = gpio_read(SENSOR2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Error: gpio_read failed (s1=%d, s2=%d).\n", s1, s2);
            break;
        }

        /* TMAG5110 open-drain: LOW = magnet detected, HIGH = unmagnetized */
        printf("Sensor 1: %s | Sensor 2: %s\n",
               s1 == 0 ? "HIGH (no magnet)" : "LOW (magnet detected)",
               s2 == 0 ? "HIGH (no magnet)" : "LOW (magnet detected)");

        usleep(POLL_INTERVAL_US);
    }

    /* Clean resource release on all exit paths */
    the_driver_library_terminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

