#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define POLL_DELAY_US 50000  /* 50 ms */

/* TTP226 channel 0 -> BCM pin 2, channel 7 -> BCM pin 22 */
static const int channel_pins[NUM_CHANNELS] = {2, 3, 4, 17, 27, 22, 10, 9};

static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

static void get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &timeinfo);
}

int main(void)
{
    int rc;
    char timestamp[32];
    int states[NUM_CHANNELS];
    int gpio_initialized = 0;
    int pigpio_ready = 0;

    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "pigpio initialisation failed (code %d)\n", rc);
        return EXIT_FAILURE;
    }
    gpio_initialized = 1;
    pigpio_ready = 1;

    /* --- Configure each channel as an input --- */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(channel_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set BCM pin %d as input\n", channel_pins[i]);
            goto cleanup;
        }
        /* TTP226 has an on-chip pull-up; disable the Pi's internal pull so
           the line level reflects the sensor output cleanly. */
        if (gpioSetPullUpDown(channel_pins[i], PI_PUD_OFF) != 0) {
            fprintf(stderr, "Failed to set pull-up/down on BCM pin %d\n", channel_pins[i]);
            goto cleanup;
        }
    }

    /* --- Main polling loop --- */
    while (!terminate) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            states[i] = gpioRead(channel_pins[i]);
            if (states[i] < 0) {
                fprintf(stderr, "Failed to read BCM pin %d\n", channel_pins[i]);
                goto cleanup;
            }
        }

        get_timestamp(timestamp, sizeof(timestamp));
        printf("%s,%d,%d,%d,%d,%d,%d,%d,%d\n",
               timestamp,
               states[0], states[1], states[2], states[3],
               states[4], states[5], states[6], states[7]);
        fflush(stdout);

        gpioDelay(POLL_DELAY_US);
    }

cleanup:
    /* --- Release every line request --- */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpioSetPullUpDown(channel_pins[i], PI_PUD_OFF);
        gpioSetMode(channel_pins[i], PI_INPUT);
    }

    if (pigpio_ready) {
        gpioTerminate();
    }
    if (gpio_initialized) {
        fprintf(stderr, "pigpio terminated.\n");
    }

    return (terminate ? EXIT_SUCCESS : EXIT_FAILURE);
}

