#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TILT_SENSOR_GPIO 4
#define POLL_DELAY_US    100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    int rc;
    int last_state = -1;

    /* --- Install SIGINT handler for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", rc);
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO4 as input with internal pull-up --- */
    rc = gpioSetMode(TILT_SENSOR_GPIO, PI_INPUT);
    if (rc != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d (code %d).\n",
                TILT_SENSOR_GPIO, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    rc = gpioSetPullUpDown(TILT_SENSOR_GPIO, PI_PUD_UP);
    if (rc != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d (code %d).\n",
                TILT_SENSOR_GPIO, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Print startup banner --- */
    printf("Tilt sensor monitoring started on GPIO%d.\n", TILT_SENSOR_GPIO);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* --- Main polling loop --- */
    while (g_running) {
        int level = gpioRead(TILT_SENSOR_GPIO);

        if (level < 0) {
            fprintf(stderr, "Error: gpioRead failed for GPIO %d (code %d).\n",
                    TILT_SENSOR_GPIO, level);
            break;
        }

        if (level != last_state) {
            if (level == 0) {
                printf("\n*** Tilted ***\n");
            } else {
                printf("\n*** Not Tilted ***\n");
            }
            fflush(stdout);
            last_state = level;
        }

        usleep(POLL_DELAY_US);
    }

    /* --- Clean shutdown --- */
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

