#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI1145_ADDR 0x60
#define I2C_BUS "/dev/i2c-1"

#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_REV_ID 0x01
#define SI1145_REG_SEQ_ID 0x02
#define SI1145_REG_INT_CFG 0x03
#define SI1145_REG_IRQ_ENABLE 0x04
#define SI1145_REG_IRQ_MODE1 0x05
#define SI1145_REG_IRQ_MODE2 0x06
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_MEAS_RATE1 0x09
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_UVINDEX0 0x2C
#define SI1145_REG_UVINDEX1 0x2D

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int init_si1145(int fd) {
    uint8_t part_id;
    if (i2c_read_reg8(fd, SI1145_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Error: Failed to read PART_ID register.\n");
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Error: Unexpected PART_ID 0x%02X (expected 0x45). Sensor not present.\n", part_id);
        return -1;
    }

    if (i2c_write_reg8(fd, SI1145_REG_HW_KEY, 0x17) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_MEAS_RATE0, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_MEAS_RATE1, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_IRQ_ENABLE, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_INT_CFG, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_IRQ_MODE1, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_IRQ_MODE2, 0x00) < 0) return -1;

    return 0;
}

static int read_uv_index(int fd, float *uv_index) {
    uint8_t uv_lo, uv_hi;
    if (i2c_read_reg8(fd, SI1145_REG_UVINDEX0, &uv_lo) < 0) return -1;
    if (i2c_read_reg8(fd, SI1145_REG_UVINDEX1, &uv_hi) < 0) return -1;
    uint16_t raw_uv = (uv_hi << 8) | uv_lo;
    *uv_index = (float)raw_uv / 100.0f;
    return 0;
}

static int read_als_visible(int fd, uint16_t *als_visible) {
    uint8_t vis_lo, vis_hi;
    if (i2c_read_reg8(fd, SI1145_REG_ALS_VIS_DATA0, &vis_lo) < 0) return -1;
    if (i2c_read_reg8(fd, SI1145_REG_ALS_VIS_DATA1, &vis_hi) < 0) return -1;
    *als_visible = (vis_hi << 8) | vis_lo;
    return 0;
}

static void log_data(FILE *fp, float uv_index, uint16_t als_visible) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, uv_index, als_visible);
    fflush(fp);
}

int main(void) {
    int fd = -1;
    FILE *fp = NULL;
    int ret_code = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
