    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, uv_index, als_visible);
    fflush(fp);
}

int main(void) {
    int fd = -1;
    FILE *fp = NULL;
    int ret_code = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        goto cleanup;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus " I2C_BUS);
        goto cleanup;
    }

    if (ioctl(fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("Failed to acquire I2C bus access / talk to slave");
        goto cleanup;
    }

    if (init_si1145(fd) < 0) {
        fprintf(stderr, "Failed to initialize Si1145 sensor.\n");
        goto cleanup;
    }

    fp = fopen("uv_als_log.csv", "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        goto cleanup;
    }

    while (running) {
        float uv_index;
        uint16_t als_visible;

        if (read_uv_index(fd, &uv_index) < 0) {
            fprintf(stderr, "Error reading UV index.\n");
        } else if (read_als_visible(fd, &als_visible) < 0) {
            fprintf(stderr, "Error reading ALS visible.\n");
        } else {
