#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS         "/dev/i2c-1"
#define SENSOR1_ADDR    0x20
#define SENSOR2_ADDR    0x21
#define ALARM_GPIO      17
#define FLOW_THRESHOLD  0.5f
#define LOG_FILE        "flow_log.txt"
#define SAMPLE_PERIOD_S 1
#define STARTUP_DELAY_US 100000

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ---- Sensirion CRC-8 (polynomial 0x31, init 0xFF) ---- */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- I2C helpers ---- */
static int i2c_write_cmd(int fd, uint8_t addr, uint8_t cmd)
{
    if (ioctl(fd, I2C_SLAVE, addr) < 0) return -1;
    if (write(fd, &cmd, 1) != 1) return -1;
    return 0;
}

static int i2c_read_block(int fd, uint8_t addr, uint8_t *buf, size_t len)
{
    if (ioctl(fd, I2C_SLAVE, addr) < 0) return -1;
    ssize_t n = read(fd, buf, len);
    return (n == (ssize_t)len) ? 0 : -1;
}

/* ---- Sensor read ---- */
static int read_flow_rate(int fd, float *out)
{
    uint8_t buf[9];
    if (i2c_read_block(fd, SENSOR1_ADDR, buf, sizeof(buf)) < 0)
        return -1;

    /* Measurement ready bit (buf[0] & 0x01) must be 1 */
    if (!(buf[0] & 0x01)) return -1;

    /* CRC covers the 2-byte status + 6-byte flow data */
    if (sensirion_crc8(&buf[0], 2) != buf[2]) return -2;
    if (sensirion_crc8(&buf[3], 6) != buf[9]) return -2;

    int16_t raw = (int16_t)((buf[3] << 8) | buf[4]);
    *out = (float)raw / 60.0f;   /* ml/min */
    return 0;
}

/* ---- Logging ---- */
static void log_flow_rate(FILE *fp, float r1, float r2, float avg, int ok1, int ok2)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, S1: %s, S2: %s, Avg: %.2f ml/min\n",
            ts,
            ok1 ? "OK" : "ERR",
            ok2 ? "OK" : "ERR",
            ok1 && ok2 ? avg : -1.0f);
    fflush(fp);
}

/* ---- Alarm ---- */
static void set_alarm(int gpio, int on)
{
    gpioWrite(gpio, on ? 1 : 0);
}

/* ---- Signal handler ---- */
static void on_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    /* pigpio init */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen " LOG_FILE);
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure alarm GPIO */
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    set_alarm(ALARM_GPIO, 0);

    /* Start sensors */
    if (i2c_write_cmd(g_i2c_fd, SENSOR1_ADDR, 0x3608) < 0 ||
        i2c_write_cmd(g_i2c_fd, SENSOR2_ADDR, 0x3608) < 0)
    {
        fprintf(stderr, "Failed to start sensors\n");
        cleanup();
        return EXIT_FAILURE;
    }
    usleep(STARTUP_DELAY_US);

    /* Signals */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Flow monitoring started. Ctrl+C to exit.\n");

    while (g_running) {
        float r1 = 0.0f, r2 = 0.0f;
        int   ok1 = 0, ok2 = 0;

        if (read_flow_rate(g_i2c_fd, &r1) == 0) { ok1 = 1; }
        if (read_flow_rate(g_i2c_fd, &r2) == 0) { ok2 = 1; }

        float avg = (ok1 && ok2) ? (r1 + r2) / 2.0f : -1.0f;

        log_flow_rate(g_log_fp, r1, r2, avg, ok1, ok2);

        set_alarm(ALARM_GPIO, avg > FLOW_THRESHOLD ? 0 : 1);

        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down...\n");
    set_alarm(ALARM_GPIO, 0);
    cleanup();
    return EXIT_SUCCESS;
}

