#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_PIN      4
#define BUFFER_SIZE     100
#define POLL_DELAY_US   50000   /* 50 ms */
#define DEBOUNCE_US     200000  /* 200 ms */

typedef struct {
    time_t timestamp;
    int    value;
} Detection;

typedef struct {
    Detection buffer[BUFFER_SIZE];
    int       head;
    int       count;
} CircularBuffer;

static CircularBuffer detections;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void init_buffer(CircularBuffer *cb)
{
    cb->head  = 0;
    cb->count = 0;
}

static void add_detection(CircularBuffer *cb, int value)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time");
        return;
    }

    cb->buffer[cb->head].timestamp = now;
    cb->buffer[cb->head].value    = value;

    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

static void dump_buffer(const CircularBuffer *cb)
{
    printf("\n--- Detections (%d total) ---\n", cb->count);
    for (int i = 0; i < cb->count; i++) {
        int idx = (cb->head - cb->count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts[32];
        struct tm tm_info;
        if (localtime_r(&cb->buffer[idx].timestamp, &tm_info) != NULL) {
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        } else {
            snprintf(ts, sizeof(ts), "<unknown>");
        }
        printf("[%s] Value: %d\n", ts, cb->buffer[idx].value);
    }
    fflush(stdout);
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Warning: failed to enable pull-up on GPIO%d\n", SENSOR_PIN);
    }

    init_buffer(&detections);

    printf("KY-033 obstacle detection started on GPIO%d. Press Ctrl+C to exit.\n",
           SENSOR_PIN);
    fflush(stdout);

    bool last_state = false;
    uint32_t last_change_tick = gpioTick();

    while (running) {
        int level = gpioRead(SENSOR_PIN);
        if (level < 0) {
            fprintf(stderr, "Warning: gpioRead failed on GPIO%d\n", SENSOR_PIN);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        bool obstacle = (level == 0);

        uint32_t now_tick = gpioTick();
        if (obstacle && !last_state &&
            (now_tick - last_change_tick) >= DEBOUNCE_US) {
            add_detection(&detections, obstacle ? 0 : 1);
            printf("Obstacle detected!\n");
            fflush(stdout);
            last_change_tick = now_tick;
        }

        last_state = obstacle;
        gpioDelay(POLL_DELAY_US);
    }

    dump_buffer(&detections);
    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

