#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define CSV_FILE       "fan_health.csv"
#define POLL_INTERVAL  500000   /* microseconds (500 ms) */
#define INIT_TIMEOUT   1000000  /* microseconds (1 s) */
#define MAX_RETRIES    3

/* D7S register addresses (16-bit, big-endian on the bus) */
#define D7S_REG_X_AXIS_LSB  0x04
#define D7S_REG_X_AXIS_MSB  0x05
#define D7S_REG_Y_AXIS_LSB  0x06
#define D7S_REG_Y_AXIS_MSB  0x07
#define D7S_REG_Z_AXIS_LSB  0x08
#define D7S_REG_Z_AXIS_MSB  0x09
#define D7S_REG_MODE        0x02
#define D7S_MODE_NORMAL     0x00
#define D7S_MODE_SLEEP      0x01
#define D7S_MODE_RESET      0x02

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_csv = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value >> 8);
    buf[2] = (uint8_t)(value & 0xFF);
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t reg_buf = reg;
    uint8_t data[2];
    if (write(fd, &reg_buf, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

static int d7s_init(int fd)
{
    /* Wake the sensor from sleep mode */
    if (i2c_write_reg16(fd, D7S_REG_MODE, D7S_MODE_NORMAL) < 0)
        return -1;
    usleep(10000); /* 10 ms settle */
    return 0;
}

static int d7s_read_axis(int fd, uint8_t lsb_reg, int16_t *value)
{
    uint16_t raw;
    if (i2c_read_reg16(fd, lsb_reg, &raw) < 0)
        return -1;
    *value = (int16_t)raw;
    return 0;
}

static int log_data(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
        fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_csv != NULL) {
        fclose(g_csv);
        g_csv = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, 0x28) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x28 failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Probe: try a register read to confirm the sensor is present */
    uint16_t probe;
    if (i2c_read_reg16(g_i2c_fd, D7S_REG_X_AXIS_LSB, &probe) < 0) {
        fprintf(stderr, "D7S not responding on 0x28\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (d7s_init(g_i2c_fd) < 0) {
        fprintf(stderr, "D7S init failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open CSV; write header if the file is new/empty */
    int file_exists = (access(CSV_FILE, F_OK) == 0);
    g_csv = fopen(CSV_FILE, "a");
    if (g_csv == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", CSV_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (!file_exists) {
        if (fseek(g_csv, 0, SEEK_END) != 0) {
            fprintf(stderr, "fseek failed: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        long sz = ftell(g_csv);
        if (sz == 0) {
            fprintf(g_csv, "timestamp,x,y,z\n");
            fflush(g_csv);
        }
    }

    printf("D7S initialized. Logging to %s every %d ms. Press Ctrl+C to stop.\n",
           CSV_FILE, POLL_INTERVAL / 1000);

    while (g_running) {
        int16_t x = 0, y = 0, z = 0;
        int ok = 1;
        if (d7s_read_axis(g_i2c_fd, D7S_REG_X_AXIS_LSB, &x) < 0) ok = 0;
        if (d7s_read_axis(g_i2c_fd, D7S_REG_Y_AXIS_LSB, &y) < 0) ok = 0;
        if (d7s_read_axis(g_i2c_fd, D7S_REG_Z_AXIS_LSB, &z) < 0) ok = 0;

        if (ok) {
            if (log_data(g_csv, x, y, z) < 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Sensor read error; will retry next cycle.\n");
        }

        usleep(POLL_INTERVAL);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

