    int led_state = 0;

    while (g_running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Error: failed to read sensor GPIOs (s1=%d, s2=%d).\n", s1, s2);
            break;
        }

        /* KY-032 is active-LOW: 0 => obstacle detected */
        int obstacle = (s1 == 0 || s2 == 0) ? 1 : 0;

        if (obstacle && !led_state) {
            if (gpioWrite(LED_PIN, 1) == 0) {
                led_state = 1;
                printf("Obstacle detected! LED ON.\n");
            } else {
                fprintf(stderr, "Error: failed to turn LED on (GPIO%d).\n", LED_PIN);
                break;
            }
        } else if (!obstacle && led_state) {
            if (gpioWrite(LED_PIN, 0) == 0) {
                led_state = 0;
                printf("No obstacle. LED OFF.\n");
            } else {
                fprintf(stderr, "Error: failed to turn LED off (GPIO%d).\n", LED_PIN);
                break;
            }
        }

        usleep(POLL_DELAY_US);
    }

    /* Clean shutdown: ensure LED is off and release pigpio resources */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("Obstacle avoidance system stopped.\n");
    return EXIT_SUCCESS;
}

