        if (is_stall_confirmed()) {
            if (log_stall_event() != 0) {
                fprintf(stderr, "Failed to log stall event\n");
            }
        }
        gpioDelay(100000);
    }

    gpioTerminate();
    printf("\nExiting gracefully...\n");
    return EXIT_SUCCESS;
}

