#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* TMAG5170-Q1 I2C 3D Hall-Effect sensor */
#define I2C_BUS        1
#define I2C_ADDR       0x1F   /* Default I2C address (A0=A1=GND) */

/* TMAG5170 register addresses */
#define REG_DEVICE_CONFIG_1  0x00
#define REG_DEVICE_CONFIG_2  0x01
#define REG_SENSOR_CONFIG_1  0x02
#define REG_SENSOR_CONFIG_2  0x03
#define REG_X_MSB           0x04
#define REG_X_LSB           0x05
#define REG_Y_MSB           0x06
#define REG_Y_LSB           0x07
#define REG_Z_MSB           0x08
#define REG_Z_LSB           0x09

/*
 * Device Config 1 (REG_DEVICE_CONFIG_1):
 *   Bit 15    = 0  (reserved)
 *   Bits 14:12 = 000 (range = 50 mT)
 *   Bits 11:10 = 00  (reserved)
 *   Bit  9    = 0  (reserved)
 *   Bits  7:6  = 00  (reserved)
 *   Bit  5    = 0  (reserved)
 *   Bits  3:2  = 00  (reserved)
 *   Bit  1    = 0  (reserved)
 *   Bit  0    = 0  (reserved)
 *   Value = 0x0000
 */
#define DEVICE_CONFIG_1_VAL 0x0000

/*
 * Device Config 2 (REG_DEVICE_CONFIG_2):
 *   Bit 15    = 0  (reserved)
 *   Bits 14:12 = 000 (conversion mode = continuous)
 *   Bits 11:10 = 00  (reserved)
 *   Bit  9    = 0  (reserved)
 *   Bits  7:6  = 00  (reserved)
 *   Bit  5    = 0  (reserved)
 *   Bits  3:2  = 00  (reserved)
 *   Bit  1    = 0  (reserved)
 *   Bit  0    = 0  (reserved)
 *   Value = 0x0000
 */
#define DEVICE_CONFIG_2_VAL 0x0000

/*
 * Sensor Config 1 (REG_SENSOR_CONFIG_1):
 *   Bit 15    = 0  (reserved)
 *   Bits 14:12 = 000 (X axis enabled)
 *   Bits 11:10 = 00  (reserved)
 *   Bit  9    = 0  (reserved)
 *   Bits  7:6  = 00  (reserved)
 *   Bit  5    = 0  (reserved)
 *   Bits  3:2  = 00  (reserved)
 *   Bit  1    = 0  (reserved)
 *   Bit  0    = 0  (reserved)
 *   Value = 0x0000
 */
#define SENSOR_CONFIG_1_VAL 0x0000

/*
 * Sensor Config 2 (REG_SENSOR_CONFIG_2):
 *   Bit 15    = 0  (reserved)
 *   Bits 14:12 = 000 (Y axis enabled)
 *   Bits 11:10 = 00  (reserved)
 *   Bit  9    = 0  (reserved)
 *   Bits  7:6  = 00  (reserved)
 *   Bit  5    = 0  (reserved)
 *   Bits  3:2  = 00  (reserved)
 *   Bit  1    = 0  (reserved)
 *   Bit  0    = 0  (reserved)
 *   Value = 0x0000
 */
#define SENSOR_CONFIG_2_VAL 0x0000

/*
 * Conversion time for 50 mT range is ~1.5 ms.
 * 100 ms polling interval is well above this.
 */
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly                */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a TMAG5170 register                         */
/* ------------------------------------------------------------------ */
static int tmag5170_write_reg16(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "[ERROR] I2C write to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from a TMAG5170 register                        */
/* ------------------------------------------------------------------ */
static int tmag5170_read_reg16(int handle, uint8_t reg, uint16_t *value)
{
    char reg_buf[1] = { (char)reg };
    char data[2]   = { 0, 0 };

    if (i2cWriteDevice(handle, reg_buf, 1) != 1) {
        fprintf(stderr, "[ERROR] I2C write (reg select 0x%02X) failed\n", reg);
        return -1;
    }

    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "[ERROR] I2C read from reg 0x%02X failed\n", reg);
        return -1;
    }

    *value = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the TMAG5170 sensor                                      */
/* ------------------------------------------------------------------ */
static int tmag5170_init(int handle)
{
    if (tmag5170_write_reg16(handle, REG_DEVICE_CONFIG_1,
                             DEVICE_CONFIG_1_VAL) != 0)
        return -1;

    if (tmag5170_write_reg16(handle, REG_DEVICE_CONFIG_2,
                             DEVICE_CONFIG_2_VAL) != 0)
        return -1;

    if (tmag5170_write_reg16(handle, REG_SENSOR_CONFIG_1,
                             SENSOR_CONFIG_1_VAL) != 0)
        return -1;

    if (tmag5170_write_reg16(handle, REG_SENSOR_CONFIG_2,
                             SENSOR_CONFIG_2_VAL) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read X, Y, Z magnetic field values (16-bit signed)                  */
/* ------------------------------------------------------------------ */
static int tmag5170_read_xyz(int handle, int16_t *x, int16_t *y, int16_t *z)
{
    uint16_t x_raw, y_raw, z_raw;

    if (tmag5170_read_reg16(handle, REG_X_MSB, &x_raw) != 0)
        return -1;
    if (tmag5170_read_reg16(handle, REG_Y_MSB, &y_raw) != 0)
        return -1;
    if (tmag5170_read_reg16(handle, REG_Z_MSB, &z_raw) != 0)
        return -1;

    *x = (int16_t)x_raw;
    *y = (int16_t)y_raw;
    *z = (int16_t)z_raw;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one data row to the CSV file                                    */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "[ERROR] strftime failed\n");
        return;
    }

    fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup all resources                                               */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    /*
     * TMAG5170-Q1 requires a power-down command after normal operation
     * ends.  The library provides a dedicated function for this.
     */
    (void)tmag5170_write_reg16(g_i2c_handle, REG_DEVICE_CONFIG_1,
                               DEVICE_CONFIG_1_VAL);
    (void)tmag5170_write_reg16(g_i2c_handle, REG_DEVICE_CONFIG_2,
                               DEVICE_CONFIG_2_VAL);
    (void)tmag5170_write_reg16(g_i2c_handle, REG_SENSOR_CONFIG_1,
                               SENSOR_CONFIG_1_VAL);
    (void)tmag5170_write_reg16(g_i2c_handle, REG_SENSOR_CONFIG_2,
                               SENSOR_CONFIG_2_VAL);

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int16_t x, y, z;

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Initialize sensor --- */
    if (tmag5170_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] TMAG5170 initialization failed "
                        "(sensor may be absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Open log file (append); write header if new --- */
    g_log_file = fopen("magnetic_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open magnetic_log.csv: ");
        perror("");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header only if file is empty */
    if (fseek(g_log_file, 0, SEEK_END) == 0) {
        long sz = ftell(g_log_file);
        if (sz == 0) {
            fprintf(g_log_file, "timestamp,x,y,z\n");
            fflush(g_log_file);
        }
    }

    /* --- Register signal handlers for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("TMAG5170 logging started. Press Ctrl-C to stop.\n");

    /* --- Main polling loop --- */
    while (g_running) {
        if (tmag5170_read_xyz(g_i2c_handle, &x, &y, &z) == 0) {
            log_data(g_log_file, x, y, z);
        } else {
            fprintf(stderr, "[WARN] Read error — continuing\n");
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

