#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_PIN 23
#define LOG_FILE "flood_log.txt"
#define POLL_INTERVAL_SEC 2
#define REINIT_DELAY_SEC 60

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static void trigger_alert(void) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d ALERT: Water detected\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec);
    fclose(fp);
    printf("ALERT: Water detected!\n");
    fflush(stdout);
}

static void log_error(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d ERROR: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        log_error("pigpio initialisation failed");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_PIN);
        log_error("Failed to set GPIO as input");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO%d\n", SENSOR_PIN);
        log_error("Failed to set pull-down");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Water level monitoring started on GPIO%d. Press Ctrl+C to exit.\n", SENSOR_PIN);
    fflush(stdout);

    while (running) {
        int level = gpioRead(SENSOR_PIN);
        if (level < 0) {
            fprintf(stderr, "Error reading GPIO%d\n", SENSOR_PIN);
            log_error("Error reading GPIO");
            sleep(REINIT_DELAY_SEC);
            if (gpioInitialise() < 0) {
                fprintf(stderr, "pigpio re-initialisation failed\n");
                log_error("pigpio re-initialisation failed");
            } else {
                if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
                    fprintf(stderr, "Failed to reset GPIO%d as input\n", SENSOR_PIN);
                    log_error("Failed to reset GPIO as input");
                    gpioTerminate();
                } else if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_DOWN) != 0) {
                    fprintf(stderr, "Failed to reset pull-down on GPIO%d\n", SENSOR_PIN);
                    log_error("Failed to reset pull-down");
                    gpioTerminate();
                }
            }
            continue;
        }

        if (level == 1) {
            trigger_alert();
        }

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    gpioTerminate();
    printf("Water level monitoring stopped.\n");
    return EXIT_SUCCESS;
}

