static void log_rotation(const char *direction) {
    pthread_mutex_lock(&log_mutex);
    if (log_file) {
        struct timespec ts;
        if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
            struct tm tm_info;
            localtime_r(&ts.tv_sec, &tm_info);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
            fprintf(log_file, "%s.%03ld %s\n", timestamp, ts.tv_nsec / 1000000, direction);
            fflush(log_file);
        } else {
            fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        }
    } else {
        fprintf(stderr, "Log file not open.\n");
    }
    pthread_mutex_unlock(&log_mutex);
}

static void sensor_callback(void *user_data, int gpio, int level, uint32_t tick) {
    (void)user_data;
    (void)tick;

    struct gpiod_line *line_a = (struct gpiod_line *)gpiod_line_get_value(SENSOR_A_PIN);
    struct gpiod_line *line_b = (struct gpiod_line *)gpiod_line_get_value(SENSOR_B_PIN);
    if (!line_a || !line_b) {
        return;
    }

    int a_val = gpiod_line_get_value(SENSOR_A_PIN);
    int b_val = gpiod_line_get_value(SENSOR_B_PIN);
    if (a_val < 0 || b_val < 0) {
        return;
    }

    int prev_a = (int)line_a->value;
    int prev_b = (int)line_b->value;

    if (level == 1) {
        if (a_val == 1 && b_val == 0) {
            if (prev_a == 0 && prev_b == 1) {
                log_rotation("Clockwise");
            }
        } else if (a_val == 0 && b_val == 1) {
            if (prev_a == 1 && prev_b == 0) {
                log_rotation("Counter-Clockwise");
            }
        }
    }
}

