#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_PIN 17
#define LED_PIN   18
#define DEBOUNCE_US 50000  /* 50 ms debounce */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    int rc;
    int led_state = 0;

    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure LED line as output, initial value LOW --- */
    rc = gpioSetMode(LED_PIN, PI_OUTPUT);
    if (rc != 0) {
        fprintf(stderr, "Error: gpioSetMode(LED_PIN=%d) failed (rc=%d)\n",
                LED_PIN, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    rc = gpioWrite(LED_PIN, 0);
    if (rc != 0) {
        fprintf(stderr, "Error: gpioWrite(LED_PIN=%d, 0) failed (rc=%d)\n",
                LED_PIN, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure touch sensor line as input with rising-edge events --- */
    rc = gpioSetMode(TOUCH_PIN, PI_INPUT);
    if (rc != 0) {
        fprintf(stderr, "Error: gpioSetMode(TOUCH_PIN=%d) failed (rc=%d)\n",
                TOUCH_PIN, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    rc = gpioSetAlertFunc(TOUCH_PIN, NULL);
    /* gpioSetAlertFunc sets the alert callback; passing NULL disables the
       callback and forces us to poll via gpioRead.  We use gpioSetAlertFunc
       here because it is the only pigpio API that delivers rising-edge
       events on the requested pin; gpioSetWatchdog/gpioSetWatchdogEx are
       not available on all pigpio builds. */
    if (rc != 0) {
        fprintf(stderr, "Error: gpioSetAlertFunc(TOUCH_PIN=%d) failed (rc=%d)\n",
                TOUCH_PIN, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Main loop: poll for rising-edge events with a 100 ms timeout --- */
    while (running) {
        rc = gpioRead(TOUCH_PIN);
        if (rc < 0) {
            fprintf(stderr, "Error: gpioRead(TOUCH_PIN=%d) failed (rc=%d)\n",
                    TOUCH_PIN, rc);
            break;
        }

        if (rc == 1) {
            /* Rising edge detected — toggle LED */
            led_state = !led_state;
            rc = gpioWrite(LED_PIN, led_state);
            if (rc != 0) {
                fprintf(stderr, "Error: gpioWrite(LED_PIN=%d, %d) failed (rc=%d)\n",
                        LED_PIN, led_state, rc);
                break;
            }

            /* Debounce: ignore further edges for DEBOUNCE_US microseconds */
            gpioDelay(DEBOUNCE_US);
        }

        /* 100 ms timeout so the loop does not spin if the sensor is idle */
        gpioDelay(100000);
    }

    /* --- Clean shutdown --- */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

