#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN    27
#define LED_2_PIN    22
#define LOG_SIZE     100
#define POLL_DELAY_US 50000  /* 50 ms */

typedef struct {
    int    sensor_pin;
    time_t timestamp;
    bool   state;
} LogEntry;

typedef struct {
    LogEntry entries[LOG_SIZE];
    int      head;
    int      count;
} CircularBuffer;

static volatile sig_atomic_t g_running = 1;
static CircularBuffer g_log;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void buffer_init(CircularBuffer *buf)
{
    buf->head  = 0;
    buf->count = 0;
}

static void buffer_add(CircularBuffer *buf, int sensor_pin, bool state)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time()");
        return;
    }

    buf->entries[buf->head].sensor_pin = sensor_pin;
    buf->entries[buf->head].timestamp  = now;
    buf->entries[buf->head].state      = state;

    buf->head = (buf->head + 1) % LOG_SIZE;
    if (buf->count < LOG_SIZE) {
        buf->count++;
    }
}

static void log_event(int sensor_pin, bool state)
{
    buffer_add(&g_log, sensor_pin, state);
}

static void print_log(const CircularBuffer *buf)
{
    printf("\n--- Event Log (%d entries) ---\n", buf->count);
    for (int i = 0; i < buf->count; i++) {
        int idx = (buf->head - buf->count + i + LOG_SIZE) % LOG_SIZE;
        printf("  [%d] Sensor %d -> %s  (ts=%ld)\n",
               i, buf->entries[idx].sensor_pin,
               buf->entries[idx].state ? "TOUCHED" : "released",
               (long)buf->entries[idx].timestamp);
    }
    printf("--- End of Log ---\n\n");
}

static void cleanup(void)
{
    gpioWrite(LED_1_PIN, 0);
    gpioWrite(LED_2_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(LED_1_PIN, 0);
    gpioWrite(LED_2_PIN, 0);

    buffer_init(&g_log);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started.\n");
    printf("  Sensor 1: GPIO%d | LED: GPIO%d\n", SENSOR_1_PIN, LED_1_PIN);
    printf("  Sensor 2: GPIO%d | LED: GPIO%d\n", SENSOR_2_PIN, LED_2_PIN);
    printf("Press Ctrl+C to exit.\n");

    bool prev1 = false, prev2 = false;

    while (g_running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Warning: gpioRead failed (s1=%d, s2=%d).\n", s1, s2);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        bool cur1 = (s1 == 1);
        bool cur2 = (s2 == 1);

        if (cur1 != prev1) {
            log_event(SENSOR_1_PIN, cur1);
            if (gpioWrite(LED_1_PIN, cur1) != 0) {
                fprintf(stderr, "Warning: gpioWrite(LED1) failed.\n");
            }
            prev1 = cur1;
        }
        if (cur2 != prev2) {
            log_event(SENSOR_2_PIN, cur2);
            if (gpioWrite(LED_2_PIN, cur2) != 0) {
                fprintf(stderr, "Warning: gpioWrite(LED2) failed.\n");
            }
            prev2 = cur2;
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    print_log(&g_log);
    cleanup();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

