#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define DEBOUNCE_DELAY_US 5000
#define LOG_FILE "shaft_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio_pin, pigpio_error(value));
        return -1;
    }
    return value;
}

static void log_data(int sensor1_state, int sensor2_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error converting time to local time\n");
        fclose(fp);
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s,%d,%d\n", timestamp, sensor1_state, sensor2_state) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }
}

static double calculate_rpm(unsigned long time_delta_us) {
    if (time_delta_us == 0) {
        return 0.0;
    }
    return 60000000.0 / (double)time_delta_us;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int sensor1_state = read_sensor(SENSOR_1_GPIO);
    int sensor2_state = read_sensor(SENSOR_2_GPIO);

    if (sensor1_state < 0 || sensor2_state < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    unsigned long time_delta_us = 0;
    int previous_sensor1_state = sensor1_state;
    int previous_sensor2_state = sensor2_state;

    printf("Monitoring shaft RPM. Press Ctrl+C to exit.\n");

    while (running) {
        sensor1_state = read_sensor(SENSOR_1_GPIO);
        sensor2_state = read_sensor(SENSOR_2_GPIO);

        if (sensor1_state < 0 || sensor2_state < 0) {
            break;
        }

        if (sensor1_state != previous_sensor1_state) {
            gpioDelay(DEBOUNCE_DELAY_US);
            sensor1_state = read_sensor(SENSOR_1_GPIO);
            if (sensor1_state != previous_sensor1_state) {
                log_data(previous_sensor1_state, sensor2_state);
                previous_sensor1_state = sensor1_state;
            }
        }

        if (sensor2_state != previous_sensor2_state) {
            gpioDelay(DEBOUNCE_DELAY_US);
            sensor2_state = read_sensor(SENSOR_2_GPIO);
            if (sensor2_state != previous_sensor2_state) {
                log_data(previous_sensor1_state, sensor2_state);
                previous_sensor2_state = sensor2_state;
            }
        }

        time_delta_us = gpioTick() - time_delta_us;
        double current_rpm = calculate_rpm(time_delta_us);
        printf("RPM: %.2f\n", current_rpm);
    }

    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

