#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI1182_ADDR 0x60

#define SI1182_REG_HW_KEY 0x01
#define SI1182_REG_MEAS_RATE 0x08
#define SI1182_REG_ALS_IR_DATA0 0x22
#define SI1182_REG_ALS_IR_DATA1 0x23
#define SI1182_REG_ALS_VIS_DATA0 0x24
#define SI1182_REG_ALS_VIS_DATA1 0x25
#define SI1182_REG_PS1_DATA0 0x26
#define SI1182_REG_PS1_DATA1 0x27

#define SI1182_HW_KEY_VAL 0x17
#define SI1182_MEAS_RATE_100MS 0x08

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %d\n", reg, rc);
    }
    return rc;
}

static int read_reg(uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int init_si1182(void) {
    if (write_reg(SI1182_REG_HW_KEY, SI1182_HW_KEY_VAL) < 0) return -1;
    if (write_reg(SI1182_REG_MEAS_RATE, SI1182_MEAS_RATE_100MS) < 0) return -1;
    return 0;
}

static int read_heart_rate(int *heart_rate) {
    uint8_t data0, data1;
    if (read_reg(SI1182_REG_ALS_IR_DATA0, &data0) < 0) return -1;
    if (read_reg(SI1182_REG_ALS_IR_DATA1, &data1) < 0) return -1;
    *heart_rate = (data1 << 8) | data0;
    return 0;
}

static int read_spo2(int *spo2) {
    uint8_t data0, data1;
    if (read_reg(SI1182_REG_ALS_VIS_DATA0, &data0) < 0) return -1;
    if (read_reg(SI1182_REG_ALS_VIS_DATA1, &data1) < 0) return -1;
    *spo2 = (data1 << 8) | data0;
    return 0;
}

static void log_data(int heart_rate, int spo2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, heart_rate, spo2);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_si1182() < 0) {
        fprintf(stderr, "Error initializing Si1182 sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        int heart_rate, spo2;

        if (read_heart_rate(&heart_rate) == 0 && read_spo2(&spo2) == 0) {
            log_data(heart_rate, spo2);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        sleep(1);
    }

    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

