#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN    27

#define POLL_DELAY_US  100000   /* 100 ms */
#define ALARM_THRESHOLD_S 2     /* seconds */
#define LOG_FILE_NAME "bridge_integrity.log"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a timestamped message to the log file and stdout              */
/* ------------------------------------------------------------------ */
static void log_message(const char *msg)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time()");
        return;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        perror("localtime_r()");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (g_log_file != NULL) {
        fprintf(g_log_file, "%s %s\n", ts, msg);
        fflush(g_log_file);
    }
    printf("%s %s\n", ts, msg);
}

/* ------------------------------------------------------------------ */
/* Read a sensor pin; returns 0 or 1, or -1 on error                   */
/* ------------------------------------------------------------------ */
static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead(%d) failed: %s\n", pin, pigpio_error(v));
        return -1;
    }
    return v;
}

/* ------------------------------------------------------------------ */
/* Activate the alarm (HIGH) or deactivate (LOW)                       */
/* ------------------------------------------------------------------ */
static void set_alarm(int state)
{
    int rc = gpioWrite(ALARM_PIN, state);
    if (rc < 0) {
        fprintf(stderr, "gpioWrite(%d, %d) failed: %s\n",
                ALARM_PIN, state, pigpio_error(rc));
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                        */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    set_alarm(0);

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor pins as inputs with pull-down ---- */
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_DOWN) failed\n", SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_DOWN) failed\n", SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Configure alarm pin as output and start LOW ---- */
    if (gpioSetMode(ALARM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", ALARM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(ALARM_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(%d, 0) failed\n", ALARM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE_NAME, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    log_message("Bridge monitoring started");

    /* ---- State tracking ---- */
    int s1_tilt = 0;          /* 1 = tilted (HIGH) */
    int s2_tilt = 0;
    time_t s1_start = 0;
    time_t s2_start = 0;
    int alarm_active = 0;

    /* ---- Main polling loop ---- */
    while (g_running) {
        int v1 = read_sensor(SENSOR_1_PIN);
        int v2 = read_sensor(SENSOR_2_PIN);

        if (v1 < 0 || v2 < 0) {
            log_message("Error reading sensor data");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* Sensor 1 */
        if (v1 == 1) {
            if (s1_tilt == 0) {
                log_message("Tilt start — sensor 1");
                s1_start = time(NULL);
                s1_tilt = 1;
            } else if (s1_tilt == 1 && (time(NULL) - s1_start) >= ALARM_THRESHOLD_S) {
                if (!alarm_active) {
                    set_alarm(1);
                    alarm_active = 1;
                    log_message("Alarm activated");
                }
            }
        } else {
            if (s1_tilt == 1) {
                log_message("Tilt end — sensor 1");
                s1_tilt = 0;
            }
        }

        /* Sensor 2 */
        if (v2 == 1) {
            if (s2_tilt == 0) {
                log_message("Tilt start — sensor 2");
                s2_start = time(NULL);
                s2_tilt = 1;
            } else if (s2_tilt == 1 && (time(NULL) - s2_start) >= ALARM_THRESHOLD_S) {
                if (!alarm_active) {
                    set_alarm(1);
                    alarm_active = 1;
                    log_message("Alarm activated");
                }
            }
        } else {
            if (s2_tilt == 1) {
                log_message("Tilt end — sensor 2");
                s2_tilt = 0;
            }
        }

        /* ---- Check if both sensors are tilted and alarm can be deactivated ---- */
        if (s1_tilt == 1 && s2_tilt == 1 && alarm_active) {
            set_alarm(0);
            alarm_active = 0;
            log_message("Alarm deactivated");
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* ---- Graceful shutdown ---- */
    log_message("Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

