/*
 * seismic.c — Raspberry Pi 3 Model B+
 * Omron D7S-A0011 seismic sensor on I2C bus 1 (SDA=GPIO2, SCL=GPIO3)
 * Alert LED on GPIO17 (BCM)
 *
 * Build: gcc -O2 -Wall -o seismic seismic.c -lomron_driver -lm -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x28
#define CTRL1_REG      0x10
#define CTRL1_PWR_DOWN 0x80
#define CTRL1_VAL      0x00   /* clear power-down, default mode */
#define STATUS_REG     0x00
#define STATUS_READY   0x01
#define DATA_REG       0x01
#define DATA_LEN       6
#define THRESHOLD      500
#define ALERT_LED_PIN  17
#define POLL_MS        100
#define MAX_RETRIES    3
#define LOG_FILE       "seismic_events.log"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log = NULL;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, buf, 2) == 2)
            return 0;
        if (errno == EINTR)
            continue;
        usleep(10000);
    }
    return -1;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, &reg, 1) != 1) {
            if (errno == EINTR)
                continue;
            usleep(10000);
            continue;
        }
        if (read(fd, val, 1) == 1)
            return 0;
        if (errno == EINTR)
            continue;
        usleep(10000);
    }
    return -1;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, &reg, 1) != 1) {
            if (errno == EINTR)
                continue;
            usleep(10000);
            continue;
        }
        if (read(fd, buf, len) == len)
            return 0;
        if (errno == EINTR)
            continue;
        usleep(10000);
    }
    return -1;
}

static int d7s_init(int fd)
{
    uint8_t ctrl1;
    if (i2c_read_reg8(fd, CTRL1_REG, &ctrl1) < 0) {
        fprintf(stderr, "D7S: cannot read CTRL1 (sensor absent or bus error)\n");
        return -1;
    }
    if (ctrl1 & CTRL1_PWR_DOWN) {
        if (i2c_write_reg8(fd, CTRL1_REG, CTRL1_VAL) < 0) {
            fprintf(stderr, "D7S: failed to clear power-down bit\n");
            return -1;
        }
        usleep(10000);
    }
    return 0;
}

static int d7s_read_data(int fd, int32_t *x, int32_t *y, int32_t *z)
{
    uint8_t status;
    if (i2c_read_reg8(fd, STATUS_REG, &status) < 0)
        return -1;
    if (!(status & STATUS_READY))
        return 1;  /* not ready yet */

    uint8_t data[DATA_LEN];
    if (i2c_read_block(fd, DATA_REG, data, DATA_LEN) < 0)
        return -1;

    *x = (int32_t)((data[0] << 8) | data[1]);
    *y = (int32_t)((data[2] << 8) | data[3]);
    *z = (int32_t)((data[4] << 8) | data[5]);
    return 0;
}

static double calc_magnitude(int32_t x, int32_t y, int32_t z)
{
    double dx = (double)x;
    double dy = (double)y;
    double dz = (double)z;
    return sqrt(dx * dx + dy * dy + dz * dz);
}

static void log_event(double mag)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(g_log, "%s,%.2f\n", ts, mag);
    fflush(g_log);
}

static void alert_led(int pin)
{
    gpio_set_mode(pin, PI_OUTPUT);
    gpio_write(pin, 1);
    usleep(1000000);
