#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define SENSOR_3_PIN 27
#define SENSOR_4_PIN 22
#define LED_PIN     18

#define POLL_DELAY_US 50000  /* 50 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read all four sensor pins.
 * The KY-032 is active-low: 0 => object detected, 1 => no object.
 * Returns a bitmask where bit i corresponds to sensor i+1 (1..4).
 */
static unsigned int read_sensors(void)
{
    unsigned int result = 0;

    if (gpioRead(SENSOR_1_PIN) == 0)
        result |= (1u << 1);
    if (gpioRead(SENSOR_2_PIN) == 0)
        result |= (1u << 2);
    if (gpioRead(SENSOR_3_PIN) == 0)
        result |= (1u << 3);
    if (gpioRead(SENSOR_4_PIN) == 0)
        result |= (1u << 4);

    return result;
}

static void control_led(unsigned int sensor_data)
{
    /* Turn LED on if any sensor detects an obstacle. */
    if (gpioWrite(LED_PIN, (sensor_data != 0) ? 1 : 0) < 0) {
        fprintf(stderr, "Warning: failed to write LED pin %d\n", LED_PIN);
    }
}

int main(void)
{
    int ret = EXIT_SUCCESS;

    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n",
                gpioInitialise());
        return EXIT_FAILURE;
    }

    /* --- Configure sensor pins as inputs --- */
    int sensor_pins[] = {SENSOR_1_PIN, SENSOR_2_PIN, SENSOR_3_PIN, SENSOR_4_PIN};
    for (size_t i = 0; i < sizeof(sensor_pins) / sizeof(sensor_pins[0]); ++i) {
        if (gpioSetMode(sensor_pins[i], PI_INPUT) < 0) {
            fprintf(stderr, "Error: failed to set GPIO%d as input.\n",
                    sensor_pins[i]);
            ret = EXIT_FAILURE;
            goto cleanup;
        }
    }

    /* --- Configure LED pin as output and ensure it starts OFF --- */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_PIN);
        ret = EXIT_FAILURE;
        goto cleanup;
    }
    if (gpioWrite(LED_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize LED pin %d to LOW.\n",
                LED_PIN);
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    printf("Obstacle detection started. Press Ctrl+C to exit.\n");

    /* --- Main polling loop --- */
    while (g_running) {
        unsigned int sensor_data = read_sensors();
        control_led(sensor_data);
        gpioDelay(POLL_DELAY_US);
    }

cleanup:
    /* --- Clean shutdown: turn LED off and release pigpio --- */
    if (gpioWrite(LED_PIN, 0) < 0) {
        fprintf(stderr, "Warning: failed to turn off LED during cleanup.\n");
    }
    gpioTerminate();

    if (ret == EXIT_SUCCESS)
        printf("\nExiting cleanly.\n");

    return ret;
}

