/*
 * Flame sensor monitor for Raspberry Pi 3 Model B+
 * Sensors : Keyes KY-026 (digital OUT)
 * Pins    : BCM 2, 3, 4, 17, 27  (physical 3, 5, 7, 11, 13)
 * Log     : /var/log/flame_events.log
 * Logging : syslog (facility LOG_USER, ident "flame_monitor")
 * Build   : gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/file.h>
#include <syslog.h>
#include <gpiod.h>

#define NUM_SENSORS      5
#define DEBOUNCE_MS      50
#define POLL_INTERVAL_S  1
#define LOG_FILE         "/var/log/flame_events.log"
#define GPIO_CHIP_NAME   "gpiochip4"   /* BCM GPIO bank on Pi 3B+ */

static const unsigned int sensor_pins[NUM_SENSORS] = {2, 3, 4, 17, 27};
static const char *sensor_ids[NUM_SENSORS] = {"S1", "S2", "S3", "S4", "S5"};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/*
 * Append a timestamped event line to the log file.
 * Returns 0 on success, -1 on error (message already logged).
 */
static int log_event(int sensor_id, unsigned int pin, const char *event)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        syslog(LOG_ERR, "fopen(%s): %s", LOG_FILE, strerror(errno));
        return -1;
    }

    if (flock(fileno(fp), LOCK_EX) == -1) {
        syslog(LOG_ERR, "flock: %s", strerror(errno));
        fclose(fp);
        return -1;
    }

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        syslog(LOG_ERR, "time(): %s", strerror(errno));
        flock(fileno(fp), LOCK_UN);
        fclose(fp);
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        syslog(LOG_ERR, "gmtime_r failed");
        flock(fileno(fp), LOCK_UN);
        fclose(fp);
        return -1;
    }

    char ts_buf[32];
    if (strftime(ts_buf, sizeof(ts_buf), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        syslog(LOG_ERR, "strftime failed");
        flock(fileno(fp), LOCK_UN);
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Sensor ID: %s (GPIO %u) - %s\n",
                ts_buf, sensor_ids[sensor_id], pin, event) < 0) {
        syslog(LOG_ERR, "fprintf: %s", strerror(errno));
        flock(fileno(fp), LOCK_UN);
        fclose(fp);
        return -1;
    }

    if (fflush(fp) == EOF) {
        syslog(LOG_ERR, "fflush: %s", strerror(errno));
        flock(fileno(fp), LOCK_UN);
        fclose(fp);
        return -1;
    }

    if (flock(fileno(fp), LOCK_UN) == -1) {
        syslog(LOG_WARNING, "flock unlock: %s", strerror(errno));
    }

    if (fclose(fp) == EOF) {
        syslog(LOG_ERR, "fclose: %s", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGINT): %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGTERM): %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        syslog(LOG_ERR, "gpiod_chip_open_by_name(%s): %s",
               GPIO_CHIP_NAME, strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *lines[NUM_SENSORS];
    int lines_acquired = 0;
    int ret_code = EXIT_SUCCESS;

    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!lines[i]) {
            syslog(LOG_ERR, "gpiod_chip_get_line(%u): %s",
                   sensor_pins[i], strerror(errno));
            ret_code = EXIT_FAILURE;
            goto cleanup;
        }
        if (gpiod_line_request_input(lines[i], "flame_monitor") < 0) {
            syslog(LOG_ERR, "gpiod_line_request_input(%u): %s",
                   sensor_pins[i], strerror(errno));
            ret_code = EXIT_FAILURE;
            goto cleanup;
        }
        lines_acquired++;
    }

    syslog(LOG_INFO, "Flame sensor monitoring started (BCM pins: %u, %u, %u, %u, %u)",
           sensor_pins[0], sensor_pins[1], sensor_pins[2],
           sensor_pins[3], sensor_pins[4]);

    while (program_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                syslog(LOG_ERR, "gpiod_line_get_value(%u): %s",
                       sensor_pins[i], strerror(errno));
                continue;
            }

            if (val == 1) {
                /* HIGH → LOW transition: flame just detected */
                usleep(DEBOUNCE_MS * 1000);
                val = gpiod_line_get_value(lines[i]);
                if (val < 0) {
                    syslog(LOG_ERR, "gpiod_line_get_value(%u): %s",
                           sensor_pins[i], strerror(errno));
                    continue;
                }
                if (val == 0) {
                    if (log_event(i, sensor_pins[i], "Flame Detected") == 0) {
                        syslog(LOG_INFO, "Flame detected on sensor %s (GPIO %u)",
                               sensor_ids[i], sensor_pins[i]);
                    }
                }
            }
        }
        sleep(POLL_INTERVAL_S);
    }

cleanup:
    syslog(LOG_INFO, "Shutting down, releasing lines...");
    for (int i = 0; i < lines_acquired; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();
    return ret_code;
}

