/*
 * TTP226 8-channel capacitive touch sensor reader for Raspberry Pi 3 B+
 *
 * Wiring (TTP226 OUT0..OUT7 -> Raspberry Pi BCM GPIO):
 *   OUT0 -> GPIO5   OUT1 -> GPIO6   OUT2 -> GPIO13  OUT3 -> GPIO19
 *   OUT4 -> GPIO26  OUT5 -> GPIO12  OUT6 -> GPIO16  OUT7 -> GPIO20
 *
 * Build:  gcc -Wall -Wextra -O2 -o ttp226_reader ttp226_reader.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 50

static const unsigned int gpio_pins[NUM_CHANNELS] = {
    5, 6, 13, 19, 26, 12, 16, 20
};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time");
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        perror("localtime_r");
        return;
    }

    char buf[32];
    if (strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    printf("[%s] ", buf);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_bulk lines;
    struct gpiod_line *lines_ptr[NUM_CHANNELS];
    int prev_state[NUM_CHANNELS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_CHANNELS; i++)
        lines_ptr[i] = NULL;

    gpiod_line_bulk_init(&lines);

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi 3 B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Resolve each GPIO line */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines_ptr[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (lines_ptr[i] == NULL) {
            fprintf(stderr, "Failed to get GPIO line for pin %u: %s\n",
                    gpio_pins[i], strerror(errno));
            goto cleanup;
        }
        gpiod_line_bulk_add(&lines, lines_ptr[i]);
    }

    /* Request all lines as inputs in one bulk operation */
    if (gpiod_line_request_bulk_input(&lines, "ttp226-reader") < 0) {
        fprintf(stderr, "Failed to request GPIO lines as inputs: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* Read initial states so we only log on change */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int val = gpiod_line_get_value(lines_ptr[i]);
        if (val < 0) {
            fprintf(stderr, "Failed to read initial state for pin %u: %s\n",
                    gpio_pins[i], strerror(errno));
            goto cleanup;
        }
        prev_state[i] = val;
    }

    printf("TTP226 touch sensor reader started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (program_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(lines_ptr[i]);
            if (val < 0) {
                print_timestamp();
                fprintf(stderr, "Error reading GPIO pin %u: %s\n",
                        gpio_pins[i], strerror(errno));
                goto cleanup;
            }

            if (val != prev_state[i]) {
                print_timestamp();
                printf("Channel %d (GPIO %u): %s\n",
                       i, gpio_pins[i],
                       val ? "Touched" : "Released");
                fflush(stdout);
                prev_state[i] = val;
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release the bulk request */
    if (gpiod_line_bulk_num_lines(&lines) > 0)
        gpiod_line_release_bulk(&lines);

    if (chip)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nExiting gracefully.\n");

    return ret;
}

