#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <pigpio.h>

#define I2C_BUS "/dev/i2c-1"
#define VEML7700_ADDR 0x48
#define LED_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define LOG_FILE "grow_log.txt"
#define SAMPLE_INTERVAL_SEC 1

#define LUX_THRESHOLD_HIGH 1000
#define LUX_THRESHOLD_MED 500
#define LUX_THRESHOLD_LOW 100

#define ERROR_NONE 0
#define ERROR_I2C -1
#define ERROR_PWM -2
#define ERROR_LOG -3

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int veml7700_init(int fd) {
    if (ioctl(fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        perror("Failed to acquire I2C bus access");
        return -1;
    }

    /*
     * VEML7700 register 0x00 (ALS_CONF) controls the ALS channel.
     * Setting bit 0 (bit-field ALS_EN) to 1 enables the ALS channel.
     * Setting bits 1-2 (ALS_INT_EN) to 0 disables interrupts.
     * Setting bits 3-4 (ALS_PERS) to 0 selects 100 ms integration time.
     * Setting bits 5-6 (ALS_GAIN) to 0 selects a gain of 1x.
     * Setting bit 7 (ALS_SHUTDOWN) to 0 keeps the sensor powered on.
     */
    uint8_t config = 0x01; /* ALS_EN = 1 */
    if (write(fd, &config, 1) != 1) {
        perror("Failed to write ALS_CONF register");
        return -1;
    }

    /*
     * VEML7700 register 0x01 (ALS_DATA_CFG) controls the ALS data read.
     * Setting bit 0 (ALS_DATA_READ) to 1 enables data read.
     */
    config = 0x01;
    if (write(fd, &config, 1) != 1) {
        perror("Failed to write ALS_DATA_CFG register");
        return -1;
    }

    return 0;
}

static int veml7700_read_lux(int fd, float *lux_out) {
    uint8_t buf[2];
    ssize_t bytes = read(fd, buf, 2);
    if (bytes != 2) {
        if (bytes < 0) {
            perror("I2C read error");
        } else {
            fprintf(stderr, "I2C read incomplete: %zd bytes\n", bytes);
        }
        return ERROR_I2C;
    }

    uint16_t raw = ((uint16_t)buf[1] << 8) | buf[0];
    /*
     * VEML7700 ALS resolution is 1 lx per count at 100 ms integration.
     * The 16-bit ALS_DATA register holds the 14-bit ALS value in bits [13:0].
     * Mask out the 2 LSBs to get the 14-bit value, then scale by 1.0.
     */
    uint16_t als_data = raw & 0x3FFF;
    *lux_out = (float)als_data / 1.0f;
    return ERROR_NONE;
}

static int set_led_brightness(int gpio, int brightness) {
    if (gpioPWM(gpio, brightness) != 0) {
        fprintf(stderr, "Failed to set PWM on GPIO %d\n", gpio);
        return ERROR_PWM;
    }
    return ERROR_NONE;
}

static int map_lux_to_brightness(float lux) {
    if (lux < LUX_THRESHOLD_LOW) {
        return 100;
    } else if (lux < LUX_THRESHOLD_MED) {
        return 75;
    } else if (lux < LUX_THRESHOLD_HIGH) {
        return 50;
    } else {
        return 25;
    }
}

static int log_data(FILE *fp, float lux, int brightness, int error_code) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r failed");
        return ERROR_LOG;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return ERROR_LOG;
    }

    if (fprintf(fp, "%s,%.2f,%d,%d\n", timestamp, lux, brightness, error_code) < 0) {
        perror("fprintf failed");
        return ERROR_LOG;
    }

    if (fflush(fp) != 0) {
        perror("fflush failed");
        return ERROR_LOG;
    }

    return ERROR_NONE;
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT) failed");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM) failed");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(LED_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", LED_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(LED_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", LED_GPIO);
        gpioTerminate();
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus " I2C_BUS);
        gpioTerminate();
        return 1;
    }

    if (veml7700_init(i2c_fd) != 0) {
        fprintf(stderr, "VEML7700 initialization failed; check wiring and sensor presence\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file " LOG_FILE);
        cleanup();
        return 1;
    }

    printf("Grow light system started. Logging to %s. Press Ctrl+C to exit.\n", LOG_FILE);

    while (running) {
        float lux = 0.0f;
        int error_code = ERROR_NONE;

        int rc = veml7700_read_lux(i2c_fd, &lux);
        if (rc != ERROR_NONE) {
            error_code = rc;
            lux = -1.0f;
        }

        int brightness = map_lux_to_brightness(lux);
        if (set_led_brightness(LED_GPIO, brightness) != ERROR_NONE) {
            error_code = ERROR_PWM;
        }

        if (log_data(log_file, lux, brightness, error_code) != ERROR_NONE) {
            error_code = ERROR_LOG;
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");

    set_led_brightness(LED_GPIO, 0);
    cleanup();

    return 0;
}

