#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define NUM_CHANNELS 8
#define LED_PIN 17
#define POLL_DELAY_US 50000  /* 50 ms */
#define DEBOUNCE_DELAY_US 200000 /* 200 ms */

static const int touch_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_touch_event(int channel) {
    FILE *fp = fopen("touch_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening touch_log.txt: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error converting time: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s – Channel %d Touched\n", timestamp, channel) < 0) {
        fprintf(stderr, "Error writing to touch_log.txt: %s\n", strerror(errno));
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing touch_log.txt: %s\n", strerror(errno));
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure touch sensor pins as inputs with pull-down resistors */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(touch_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", touch_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(touch_pins[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Failed to set pull-down on GPIO %d\n", touch_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* Configure LED pin as output and ensure it is off */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Failed to write to GPIO %d\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    int prev_touch_states[NUM_CHANNELS] = {0};
    int debounce_timestamps[NUM_CHANNELS] = {0};

    while (running) {
        int touch_states[NUM_CHANNELS];
        int read_error = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpioRead(touch_pins[i]);
            if (val < 0) {
                fprintf(stderr, "Error reading GPIO %d\n", touch_pins[i]);
                read_error = 1;
                break;
            }
            touch_states[i] = val;
        }

        if (read_error) {
            break;
        }

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int current_time = gpioTick();
            if (current_time < 0) {
                fprintf(stderr, "Error getting gpioTick\n");
                break;
            }

            /* Debounce: only act on a stable high reading */
            if (touch_states[i] == 1 && prev_touch_states[i] == 0) {
                if (current_time - debounce_timestamps[i] >= DEBOUNCE_DELAY_US) {
                    log_touch_event(i + 1);
                    debounce_timestamps[i] = current_time;
                }
            }

            prev_touch_states[i] = touch_states[i];
        }

        /* Turn LED on if any channel is touched, off otherwise */
        int led_state = (prev_touch_states[0] == 1 || prev_touch_states[1] == 1 ||
                         prev_touch_states[2] == 1 || prev_touch_states[3] == 1 ||
                         prev_touch_states[4] == 1 || prev_touch_states[5] == 1 ||
                         prev_touch_states[6] == 1 || prev_touch_states[7] == 1) ? 1 : 0;

        if (gpioWrite(LED_PIN, led_state) != 0) {
            fprintf(stderr, "Error writing to GPIO %d\n", LED_PIN);
            break;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Cleanup */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully...\n");
    return EXIT_SUCCESS;
}

