#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define OPT3001_ADDR   0x51
#define LOG_FILE       "light_data.txt"
#define SAMPLE_PERIOD  1   /* seconds */
#define CONFIG_DELAY   0.1 /* seconds */

/* OPT3001 register addresses */
#define REG_RESULT     0x00
#define REG_CONFIG     0x01
#define REG_MANUF_ID   0x7E

/* Expected manufacturer ID for OPT3001 */
#define OPT3001_MFR_ID 0x5449

/*
 * Configuration register value:
 *   Bits 15-12 : RN[3:0] = 0x0000  (no range scaling)
 *   Bits 11-10 : M[1:0] = 0x00      (average mode)
 *   Bit  9     : CT = 0            (no comparator)
 *   Bit  8     : OVF = 0           (no overflow flag)
 *   Bit  7     : POL = 0           (active low)
 *   Bit  6     : ME = 0            (no mask)
 *   Bit  5     : FC = 0            (no fault count)
 *   Bit  4     : FL = 0            (no fault latch)
 *   Bit  3     : IG = 0            (no interrupt gen)
 *   Bit  2     : IF = 0            (no interrupt flag)
 *   Bit  1     : CR = 0            (no CR fault)
 *   Bit  0     : L = 0             (no latch)
 * => 0x0000
 */
#define CONFIG_VALUE   0x0000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg16(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value & 0xFF);        /* low byte first */
    buf[2] = (uint8_t)((value >> 8) & 0xFF); /* high byte second */

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        perror("i2c_write_reg16: write");
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t reg_buf = reg;
    uint8_t data[2];

    if (write(fd, &reg_buf, 1) != 1) {
        perror("i2c_read_reg16: write reg");
        return -1;
    }
    if (read(fd, data, 2) != 2) {
        perror("i2c_read_reg16: read data");
        return -1;
    }
    /* OPT3001 sends MSB first */
    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* OPT3001 driver                                                      */
/* ------------------------------------------------------------------ */
static int opt3001_init(int fd)
{
    uint16_t mfr_id = 0;

    if (i2c_read_reg16(fd, REG_MANUF_ID, &mfr_id) != 0) {
        fprintf(stderr, "Failed to read manufacturer ID\n");
        return -1;
    }
    if (mfr_id != OPT3001_MFR_ID) {
        fprintf(stderr, "Unexpected manufacturer ID: 0x%04X (expected 0x%04X)\n",
                mfr_id, OPT3001_MFR_ID);
        return -1;
    }

    if (i2c_write_reg16(fd, REG_CONFIG, CONFIG_VALUE) != 0) {
        fprintf(stderr, "Failed to write configuration register\n");
        return -1;
    }

    /* Wait for the configuration to take effect (datasheet: ~100 ms) */
    (void)usleep((useconds_t)(CONFIG_DELAY * 1e6));
    return 0;
}

static int opt3001_read_lux(int fd, float *lux_out)
{
    uint16_t raw = 0;

    if (i2c_read_reg16(fd, REG_RESULT, &raw) != 0) {
        return -1;
    }

    /* OPT3001 result register: big-endian, 16-bit signed */
    int16_t signed_raw = (int16_t)raw;
    *lux_out = (float)signed_raw / 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float lux)
{
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[32];

    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s, %.2f\n", timestamp, lux) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return EXIT_FAILURE;
    }

    if (opt3001_init(g_i2c_fd) != 0) {
        fprintf(stderr, "OPT3001 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen " LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("OPT3001 greenhouse monitor started. Logging to %s\n", LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float lux = 0.0f;

        if (opt3001_read_lux(g_i2c_fd, &lux) != 0) {
            fprintf(stderr, "Failed to read lux value; skipping iteration\n");
        } else {
            if (log_data(g_log_fp, lux) != 0) {
                fprintf(stderr, "Failed to log data; skipping iteration\n");
            } else {
                printf("%s  Lux: %.2f\n",
                       __TIME__, lux); /* quick console echo */
            }
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++) {
            (void)usleep(100000); /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

