#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define I2C_BUS        1
#define I2C_ADDR       0x25
#define CSV_FILENAME   "cooling_log.csv"
#define SAMPLE_PERIOD  1   /* seconds */
#define MEASURE_DELAY  2000 /* microseconds (2 ms) */
#define FLOW_MIN       0.0f
#define FLOW_MAX       100.0f
#define FLOW_ERROR     (-1.0f)

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_csv_file = NULL;

/* ---- CRC-8 (Sensirion polynomial 0x31, init 0xFF) ---- */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C initialization ---- */
static int i2c_init(void)
{
    g_i2c_handle = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "open(\"/dev/i2c-1\"): %s\n", strerror(errno));
