 * Sends the continuous-measurement command 0x3608, waits, then reads 3 bytes:
 *   [MSB][LSB][CRC8]
 * Returns flow in ml/min on success, FLOW_ERROR on I2C failure,
 * or a negative value when the CRC is invalid.
 */
static float read_flow_rate(void)
{
    uint8_t cmd[2] = { 0x36, 0x08 };
    uint8_t buf[3];
    ssize_t w, r;

    w = write(g_i2c_handle, cmd, sizeof(cmd));
