        return FLOW_ERROR;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on flow data\n");
        return FLOW_ERROR;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    float flow = (float)raw;

    if (flow < FLOW_MIN || flow > FLOW_MAX) {
        fprintf(stderr, "Flow out of range: %.2f ml/min\n", flow);
        return FLOW_ERROR;
    }
    return flow;
}

