#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN    17
#define MIDDLE_SENSOR_PIN  27
#define RIGHT_SENSOR_PIN   22
#define LOG_FILE_NAME      "path_log.csv"
#define SAMPLE_INTERVAL_US 50000  /* 50 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Write one CSV row:  "timestamp,left,middle,right\n"
 * left/middle/right are 0 or 1.
 */
static int write_log_row(FILE *fp, int left, int middle, int right)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, left, middle, right) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure sensor pins as inputs --- */
    int pins[3] = {LEFT_SENSOR_PIN, MIDDLE_SENSOR_PIN, RIGHT_SENSOR_PIN};
    for (int i = 0; i < 3; i++) {
        if (gpioSetMode(pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "gpioSetMode failed for pin %d\n", pins[i]);
            goto cleanup_gpio;
        }
    }

    /* --- Open log file --- */
    fp = fopen(LOG_FILE_NAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        goto cleanup_gpio;
    }

    /* Write CSV header if the file is newly created (size == 0) */
    long pos = ftell(fp);
    if (pos == 0) {
        if (fprintf(fp, "timestamp,left,middle,right\n") < 0 ||
            fflush(fp) != 0) {
            fprintf(stderr, "Error writing CSV header: %s\n", strerror(errno));
            goto cleanup_all;
        }
    }

    printf("Logging KY-033 sensor data to %s (Ctrl+C to stop)\n", LOG_FILE_NAME);

    /* --- Main sampling loop --- */
    while (g_running) {
        int left   = gpioRead(LEFT_SENSOR_PIN);
        int middle = gpioRead(MIDDLE_SENSOR_PIN);
        int right  = gpioRead(RIGHT_SENSOR_PIN);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "gpioRead error (l=%d m=%d r=%d)\n",
                    left, middle, right);
            break;
        }

        if (write_log_row(fp, left, middle, right) != 0) {
            fprintf(stderr, "Logging failed; aborting.\n");
            break;
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down cleanly...\n");
    ret = EXIT_SUCCESS;

cleanup_all:
    if (fp != NULL) {
        if (fclose(fp) != 0) {
            fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        }
    }

cleanup_gpio:
    /* gpioTerminate is safe to call even if gpioInitialise failed */
    gpioTerminate();

    return ret;
}

