/*
 * Flame Sensor Monitor for Raspberry Pi 5
 * Sensor: Keyes KY-026 Flame Sensor (digital output, active-low)
 * Wiring:
 *   KY-026 VCC -> 3.3V (Pin 1)
 *   KY-026 GND -> GND  (Pin 9)
 *   KY-026 D0  -> GPIO4 (Pin 7, BCM 4)
 *
 * Build: gcc -Wall -Wextra -O2 -o flame_monitor flame_monitor.c -lpigpio -lrt
 * Run:   sudo ./flame_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 4          /* BCM 4 */
#define LOG_FILE          "flame_events.txt"
#define POLL_DELAY_US     100000     /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped event to the log file                          */
/* ------------------------------------------------------------------ */
static void log_event(const char *message)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time() failed");
        fclose(fp);
        return;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r() failed");
        fclose(fp);
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Send an alert to stdout with a timestamp                             */
/* ------------------------------------------------------------------ */
static void send_alert(const char *message)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time() failed");
        printf("ALERT: %s\n", message);
        return;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r() failed");
        printf("ALERT: %s\n", message);
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        printf("ALERT: %s\n", message);
        return;
    }

    printf("%s: ALERT: %s\n", timestamp, message);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers early ------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT) failed");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM) failed");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio ------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO 4 as input with internal pull-up ------------- */
    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP) != 0) {
