        perror("sigaction(SIGTERM) failed");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio ------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO 4 as input with internal pull-up ------------- */
    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Optional: enable internal pull-up after sensor is connected --- */
    /* The KY-026 has an on-board pull-up, but the Pi pull-up provides    */
    /* an extra layer of protection against floating inputs.            */

    /* --- Read initial state to confirm sensor is present -------------- */
    int initial_state = gpioRead(FLAME_SENSOR_GPIO);
    if (initial_state < 0) {
        fprintf(stderr, "Failed to read GPIO %d\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initial_state == 1) {
        printf("Flame sensor monitoring started on GPIO %d (initial state: HIGH).\n",
               FLAME_SENSOR_GPIO);
        fflush(stdout);
    } else {
        printf("Flame sensor monitoring started on GPIO %d (initial state: LOW).\n",
               FLAME_SENSOR_GPIO);
        fflush(stdout);
        send_alert("Flame detected at startup (sensor may be absent or shorted)");
        log_event("Flame detected at startup (sensor may be absent or shorted)");
    }

    /* --- Main polling loop ------------------------------------------ */
    while (g_running) {
        int level = gpioRead(FLAME_SENSOR_GPIO);
        if (level < 0) {
            fprintf(stderr, "Error reading GPIO %d\n", FLAME_SENSOR_GPIO);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* KY-026 is active-low: 0 => flame detected, 1 => no flame */
        if (level == 0) {
            send_alert("Flame detected!");
            log_event("Flame detected!");
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Clean shutdown --------------------------------------------- */
    printf("\nShutting down...\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

