/*
 * touch_lamp.c — Raspberry Pi 5 touch-activated LED lamp
 *
 * Hardware:
 *   TTP223 capacitive touch sensor  -> GPIO23 (BCM 23, input, active-high)
 *   LED + 330 Ω resistor            -> GPIO24 (BCM 24, output)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o touch_lamp touch_lamp.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./touch_lamp
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define TOUCH_PIN  23          /* BCM 23 — TTP223 OUT (input)  */
#define LED_PIN    24          /* BCM 24 — LED control (output) */
#define GPIO_CHIP  "gpiochip4" /* RP1 GPIO controller on Pi 5 */
#define LOG_FILE   "touch_log.txt"
#define POLL_US    1000000     /* 1 s poll timeout for libevent */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void log_event(int led_state)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_buf;
    struct tm *tm = localtime_r(&now, &tm_buf);
    if (tm == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S%z", tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (fprintf(g_log, "%s LED=%d\n", ts, led_state) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(g_log) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ------------------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open log file -------------------------------------------- */
    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        fclose(g_log);
        g_log = NULL;
        return EXIT_FAILURE;
    }

    /* ---- Request GPIO lines --------------------------------------- */
    int rc = gpioSetMode(TOUCH_PIN, PI_INPUT);
    if (rc != 0) {
        fprintf(stderr, "gpioSetMode(TOUCH=%d) failed: %s\n",
                TOUCH_PIN, pigpio_error(rc));
        goto cleanup_gpio;
    }

    rc = gpioSetMode(LED_PIN, PI_OUTPUT);
    if (rc != 0) {
        fprintf(stderr, "gpioSetMode(LED=%d) failed: %s\n",
                LED_PIN, pigpio_error(rc));
        goto cleanup_gpio;
    }

    /* Start with LED off */
    rc = gpioWrite(LED_PIN, 0);
    if (rc != 0) {
        fprintf(stderr, "gpioWrite(LED=%d, 0) failed: %s\n",
                LED_PIN, pigpio_error(rc));
        goto cleanup_gpio;
    }

    /* ---- Main event loop ------------------------------------------ */
    int led_state = 0;
    int last_touch = gpioRead(TOUCH_PIN);
    if (last_touch < 0) {
        fprintf(stderr, "Initial gpioRead(TOUCH=%d) failed: %s\n",
                TOUCH_PIN, pigpio_error(last_touch));
        goto cleanup_gpio;
    }

    printf("Touch lamp started.  Touch=BCM%d  LED=BCM%d  Log=%s\n",
           TOUCH_PIN, LED_PIN, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int touch = gpioRead(TOUCH_PIN);
        if (touch < 0) {
            fprintf(stderr, "gpioRead(TOUCH=%d) failed: %s\n",
                    TOUCH_PIN, pigpio_error(touch));
            break;
        }

        /* Rising edge: 0 -> 1 */
        if (touch == 1 && last_touch == 0) {
            led_state = !led_state;
            rc = gpioWrite(LED_PIN, led_state);
            if (rc != 0) {
                fprintf(stderr, "gpioWrite(LED=%d, %d) failed: %s\n",
                        LED_PIN, led_state, pigpio_error(rc));
                break;
            }
            log_event(led_state);
        }

        last_touch = touch;
        gpioDelay(POLL_US);   /* 1 s poll timeout */
    }

    /* ---- Graceful shutdown ---------------------------------------- */
    printf("\nShutting down...\n");

    rc = gpioWrite(LED_PIN, 0);
    if (rc != 0) {
        fprintf(stderr, "gpioWrite(LED=%d, 0) on exit failed: %s\n",
                LED_PIN, pigpio_error(rc));
    }

    gpioTerminate();

    if (g_log != NULL) {
        if (fclose(g_log) != 0) {
            fprintf(stderr, "fclose(log) failed: %s\n", strerror(errno));
        }
        g_log = NULL;
    }

    return EXIT_SUCCESS;

cleanup_gpio:
    gpioTerminate();
    if (g_log != NULL) {
        fclose(g_log);
        g_log = NULL;
    }
    return EXIT_FAILURE;
}

