/*
 * Flame Detection Safety System — Raspberry Pi 3 Model B+
 * Sensor : Keyes KY-026 flame sensor (digital output, active-low)
 *   DO   -> GPIO17 (BCM, physical pin 11)
 *   VCC  -> 3.3 V
 *   GND  -> GND
 * Buzzer : active buzzer on GPIO18 (BCM, physical pin 12)
 *   +    -> GPIO18
 *   -    -> GND
 *
 * Behaviour:
 *   - Polls the sensor every 500 ms.
 *   - On a HIGH -> LOW transition (flame detected) logs a timestamped
 *     "FLAME DETECTED" entry to alert_log.txt and drives the buzzer
 *     HIGH for 2 s.
 *   - Writes a "System started" entry at startup and a "System stopped"
 *     entry on clean shutdown.
 *   - Responds promptly to SIGINT / SIGTERM: buzzer off, resources
 *     released, exit code 0.
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o flame_alert flame_alert.c -lgpiod
 */

#include <errno.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>

#define FLAME_PIN    17          /* BCM 17 — KY-026 DO */
#define BUZZER_PIN   18          /* BCM 18 — buzzer control */
#define LOG_FILE     "alert_log.txt"
#define POLL_MS      500         /* main loop poll interval  */
#define BUZZER_MS    2000        /* buzzer on duration       */
#define SLICE_MS     100         /* granularity for signals   */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void log_event(const char *msg)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char ts[64];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (fprintf(g_log, "%s: %s\n", ts, msg) < 0)
        perror("fprintf(log)");
    if (fflush(g_log) == EOF)
        perror("fflush(log)");
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *flame = NULL;
    struct gpiod_line *buzzer = NULL;
    int ret = EXIT_FAILURE;

    /* ---- signal handlers ------------------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- open log file -------------------------------------------- */
    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }

    log_event("System started");

    /* ---- open GPIO chip ------------------------------------------- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    flame = gpiod_chip_get_line(chip, FLAME_PIN);
    if (flame == NULL) {
        perror("gpiod_chip_get_line(flame)");
        goto cleanup;
    }

    buzzer = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (buzzer == NULL) {
        perror("gpiod_chip_get_line(buzzer)");
        goto cleanup;
    }

    /* ---- request lines -------------------------------------------- */
    if (gpiod_line_request_input(flame, "flame_alert") < 0) {
        perror("gpiod_line_request_input(flame)");
        goto cleanup;
    }

    if (gpiod_line_request_output(buzzer, "flame_alert", 0) < 0) {
        perror("gpiod_line_request_output(buzzer)");
        goto cleanup;
    }

    /* ---- main loop ------------------------------------------------ */
    int last_state = gpiod_line_get_value(flame);
    if (last_state < 0) {
        perror("gpiod_line_get_value(initial flame)");
        goto cleanup;
    }

    if (last_state == 1) {
        log_event("FLAME DETECTED");
        if (gpiod_line_set_value(buzzer, 1) < 0) {
            perror("gpiod_line_set_value(buzzer ON)");
            goto cleanup;
        }
    }

    while (g_running) {
        int val = gpiod_line_get_value(flame);
        if (val < 0) {
            perror("gpiod_line_get_value(flame)");
            break;
        }

        /* Edge-trigger: only act on HIGH -> LOW transition */
        if (val == 0 && last_state == 1) {
            log_event("FLAME DETECTED");
            if (gpiod_line_set_value(buzzer, 1) < 0) {
                perror("gpiod_line_set_value(buzzer ON)");
                break;
            }
            /*
             * Hold buzzer HIGH for 2 s, but break the wait into
             * 100 ms slices so signals are caught promptly.
             */
            for (int i = 0; i < (BUZZER_MS / SLICE_MS) && g_running; i++)
                usleep(SLICE_MS * 1000);
            if (gpiod_line_set_value(buzzer, 0) < 0) {
                perror("gpiod_line_set_value(buzzer OFF)");
                break;
            }
        }

        last_state = val;
        usleep(POLL_MS * 1000);
    }

    /* ---- graceful shutdown ---------------------------------------- */
    if (buzzer)
        gpiod_line_set_value(buzzer, 0);

    log_event("System stopped");
    ret = EXIT_SUCCESS;

cleanup:
    if (flame)
        gpiod_line_release(flame);
    if (buzzer)
        gpiod_line_release(buzzer);
    if (chip)
        gpiod_chip_close(chip);
    if (g_log)
        fclose(g_log);

    return ret;
}

