#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define LED_PIN          17
#define DEBOUNCE_MS      200
#define POLL_DELAY_US    10000   /* 10 ms */
#define LOG_FILE         "touch_log.txt"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly             */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Append a UTC ISO-8601 timestamp line to the log file                */
/* ------------------------------------------------------------------ */
static int log_touch_event(void)
{
    time_t rawtime;
    struct tm tm_info;
    char timestamp[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &tm_info) == NULL) {
        fprintf(stderr, "Error: gmtime_r() failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%SZ", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Warning: failed to write to log file\n");
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "Warning: fflush() failed on log file\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                        */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    /* pigpio's gpioTerminate() is safe to call even if init failed */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int last_state = 0;
    int current_state;
    uint32_t last_touch_tick = 0;

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- configure GPIO pins ---- */
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(TOUCH_SENSOR_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(LED_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Start with LED off */
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(LED_PIN, 0) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed\n");
    }

    printf("Touch sensor logging started. Press Ctrl+C to exit.\n");

    /* ---- main polling loop ---- */
    while (g_running) {
        current_state = gpioRead(TOUCH_SENSOR_PIN);
        if (current_state < 0) {
            fprintf(stderr, "Error: gpioRead(TOUCH_SENSOR_PIN) failed\n");
            break;
        }

        /* Rising edge: LOW -> HIGH */
        if (last_state == 0 && current_state == 1) {
            uint32_t now = gpioTick();
            if (now == 0) {
                fprintf(stderr, "Warning: gpioTick() returned 0\n");
            } else if ((now - last_touch_tick) >= (uint32_t)(DEBOUNCE_MS * 1000)) {
                last_touch_tick = now;

                /* Toggle LED */
                int led_state = gpioRead(LED_PIN);
                if (led_state < 0) {
                    fprintf(stderr, "Error: gpioRead(LED_PIN) failed\n");
                } else {
                    if (gpioWrite(LED_PIN, !led_state) != 0) {
                        fprintf(stderr, "Error: gpioWrite(LED_PIN, !%d) failed\n", led_state);
                    }
                }

                if (log_touch_event() != 0) {
                    fprintf(stderr, "Error: failed to log touch event\n");
                }
            }
        }

        last_state = current_state;
        gpioDelay(POLL_DELAY_US);
    }

    /* ---- graceful shutdown ---- */
    gpioWrite(LED_PIN, 0);
    cleanup();
    printf("Touch sensor logging stopped.\n");
    return EXIT_SUCCESS;
}

