/*
 * TMAG5110A1 Hall-Effect Latch Sensor Monitor
 * Board:  Raspberry Pi 4 Model B
 * Library: pigpio (modern, actively maintained)
 *
 * Wiring (BCM numbering):
 *   Sensor 1 OUT -> GPIO4
 *   Sensor 2 OUT -> GPIO17
 *   Sensor 3 OUT -> GPIO27
 *
 * The TMAG5110A1 has an open-drain output:
 *   - Logic high  -> magnet absent (release state)
 *   - Logic low   -> magnet present  (latch / capture state)
 *
 * Build:  gcc -Wall -Wextra -O2 -o magnet_monitor magnet_monitor.c -lpigpio -lrt
 * Run:    sudo ./magnet_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define SENSOR_3_PIN 27

#define LOG_FILE_NAME "magnet_log.txt"
#define POLL_DELAY_US 100000  /* 100 ms */

/* ------------------------------------------------------------------ */
/* Global state                                                        */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/*
 * Write an ISO-8601 timestamp into buf (size >= 25).
 * Returns 0 on success, -1 on failure.
 */
static int get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        return -1;
    }

    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S%z", &tm_info) == 0) {
        return -1;
    }

    return 0;
}

/*
 * Append a state-change record to the log file.
 * Returns 0 on success, -1 on failure.
 */
static int log_event(int sensor_id, int state)
{
    char ts[32];
    if (get_timestamp(ts, sizeof(ts)) != 0) {
        fprintf(stderr, "Error: failed to generate timestamp.\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s - Sensor %d: %s\n",
                ts, sensor_id, state ? "MAGNET_PRESENT" : "MAGNET_ABSENT") < 0) {
        fprintf(stderr, "Error: failed to write to log file.\n");
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed on log file.\n");
    }

    return 0;
}

/*
 * Configure a GPIO pin as input with internal pull-up.
 * Returns 0 on success, -1 on failure.
 */
static int setup_sensor_pin(int pin)
{
    if (gpioSetMode(pin, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed.\n", pin);
        return -1;
    }

    if (gpioSetPullUpDown(pin, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%d, PI_PUD_UP) failed.\n", pin);
        return -1;
    }

    return 0;
}

/*
 * Read a sensor pin.
 * Returns 0 or 1 on success, -1 on error.
 */
static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead(%d) failed.\n", pin);
        return -1;
    }
    return v;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* --- Install signal handlers early ------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio ------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Open log file ---------------------------------------------- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure sensor pins -------------------------------------- */
    int pins[] = {SENSOR_1_PIN, SENSOR_2_PIN, SENSOR_3_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (setup_sensor_pin(pins[i]) != 0) {
            fprintf(stderr, "Error: failed to configure GPIO%d.\n", pins[i]);
            fclose(g_log_file);
            g_log_file = NULL;
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("Monitoring TMAG5110A1 sensors on GPIO%d, GPIO%d, GPIO%d.\n",
           SENSOR_1_PIN, SENSOR_2_PIN, SENSOR_3_PIN);
    printf("Logging state changes to '%s'. Press Ctrl+C to exit.\n",
           LOG_FILE_NAME);

    /* --- Main polling loop ------------------------------------------ */
    int prev_state[3] = {-1, -1, -1};  /* -1 = uninitialized */

    while (g_running) {
        int s1 = read_sensor(SENSOR_1_PIN);
        int s2 = read_sensor(SENSOR_2_PIN);
        int s3 = read_sensor(SENSOR_3_PIN);

        /*
         * TMAG5110A1 latches: the output pulls the line low when a
         * south pole is present, and releases it high when the magnet
         * is absent.  We log on any transition so we capture both
         * magnet-present -> absent and absent -> present.
         */
        if (s1 >= 0 && s1 != prev_state[0]) {
            if (log_event(1, s1) != 0) {
                fprintf(stderr, "Warning: failed to log sensor 1 event.\n");
            }
            prev_state[0] = s1;
        }
        if (s2 >= 0 && s2 != prev_state[1]) {
            if (log_event(2, s2) != 0) {
                fprintf(stderr, "Warning: failed to log sensor 2 event.\n");
            }
            prev_state[1] = s2;
        }
        if (s3 >= 0 && s3 != prev_state[2]) {
            if (log_event(3, s3) != 0) {
                fprintf(stderr, "Warning: failed to log sensor 3 event.\n");
            }
            prev_state[2] = s3;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Clean shutdown --------------------------------------------- */
    printf("\nShutting down...\n");

    if (g_log_file != NULL) {
        if (fclose(g_log_file) != 0) {
            perror("Warning: fclose failed on log file");
        }
        g_log_file = NULL;
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

