#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* Si1182-A-GM I2C address (7-bit) */
#define SI1182_I2C_ADDR 0x60

/* Si1182 register addresses */
#define SI1182_REG_PART_ID      0x00
#define SI1182_REG_HW_REV       0x01
#define SI1182_REG_SEQ_ID       0x02
#define SI1182_REG_INT_CFG      0x03
#define SI1182_REG_IRQ_ENABLE   0x04
#define SI1182_REG_IRQ_MODE1    0x05
#define SI1182_REG_IRQ_MODE2    0x06
#define SI1182_REG_HW_KEY       0x07
#define SI1182_REG_MEAS_RATE0   0x08
#define SI1182_REG_MEAS_RATE1   0x09
#define SI1182_REG_ALS_RATE     0x0A
#define SI1182_REG_ALS_IR_DATA0 0x10
#define SI1182_REG_ALS_IR_DATA1 0x11
#define SI1182_REG_HR_DATA0     0x12
#define SI1182_REG_HR_DATA1     0x13

/* Expected PART_ID and HW_REV for Si1182-A-GM */
#define SI1182_PART_ID_EXPECTED 0x82
#define SI1182_HW_REV_EXPECTED  0x01

/* Moving-average window size */
#define MOVING_AVG_WINDOW 5

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1

/* Global resources for signal-safe cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    int data[MOVING_AVG_WINDOW];
    int index;
    int sum;
} MovingAverageFilter;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void moving_average_filter_init(MovingAverageFilter *filter) {
    memset(filter, 0, sizeof(*filter));
}

static void moving_average_filter_update(MovingAverageFilter *filter, int new_value) {
    filter->sum -= filter->data[filter->index];
    filter->data[filter->index] = new_value;
    filter->sum += new_value;
    filter->index = (filter->index + 1) % MOVING_AVG_WINDOW;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int initialize_sensor(int handle) {
    uint8_t part_id, hw_rev;

    if (read_register(handle, SI1182_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Failed to read PART_ID\n");
        return -1;
    }
    if (read_register(handle, SI1182_REG_HW_REV, &hw_rev) < 0) {
        fprintf(stderr, "Failed to read HW_REV\n");
        return -1;
    }

    if (part_id != SI1182_PART_ID_EXPECTED || hw_rev != SI1182_HW_REV_EXPECTED) {
        fprintf(stderr, "Sensor not detected: PART_ID=0x%02X, HW_REV=0x%02X (expected 0x%02X, 0x%02X)\n",
                part_id, hw_rev, SI1182_PART_ID_EXPECTED, SI1182_HW_REV_EXPECTED);
        return -1;
    }

    /* Reset the device */
    if (write_register(handle, SI1182_REG_HW_KEY, 0x00) < 0) return -1;
    gpioDelay(10000); /* 10 ms settle */

    /* Configure measurement rate (0x0808 = 100 ms period) */
    if (write_register(handle, SI1182_REG_MEAS_RATE0, 0x08) < 0) return -1;
    if (write_register(handle, SI1182_REG_MEAS_RATE1, 0x08) < 0) return -1;

    /* Clear any pending interrupts */
    if (write_register(handle, SI1182_REG_IRQ_MODE1, 0x00) < 0) return -1;
    if (write_register(handle, SI1182_REG_IRQ_MODE2, 0x00) < 0) return -1;
    if (write_register(handle, SI1182_REG_INT_CFG, 0x00) < 0) return -1;
    if (write_register(handle, SI1182_REG_IRQ_ENABLE, 0x00) < 0) return -1;

    return 0;
}

static int read_heart_rate(int handle, int *heart_rate) {
    uint8_t hr_data0, hr_data1;

    if (read_register(handle, SI1182_REG_HR_DATA0, &hr_data0) < 0) {
        return -1;
    }
    if (read_register(handle, SI1182_REG_HR_DATA1, &hr_data1) < 0) {
        return -1;
    }

    /* Si1182 HR data is 16-bit, little-endian */
    *heart_rate = (int)((uint16_t)((hr_data1 << 8) | hr_data0));
    return 0;
}

static int log_data(FILE *file, int heart_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(file, "%s,%d\n", timestamp, heart_rate) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }

    if (fflush(file) != 0) {
        fprintf(stderr, "Error flushing log file\n");
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    MovingAverageFilter hr_filter;
    moving_average_filter_init(&hr_filter);
    int heart_rate;
    int consecutive_errors = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, SI1182_I2C_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (initialize_sensor(i2c_handle) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        perror("Error opening heart_rate.csv");
        cleanup();
        return 1;
    }

    printf("Heart rate monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_heart_rate(i2c_handle, &heart_rate) == 0) {
            consecutive_errors = 0;

            moving_average_filter_update(&hr_filter, heart_rate);
            int filtered_hr = hr_filter.sum / MOVING_AVG_WINDOW;

            if (filtered_hr >= 30 && filtered_hr <= 220) {
                if (log_data(log_file, filtered_hr) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
            } else {
                fprintf(stderr, "Invalid heart rate: %d BPM (out of range 30-220)\n", filtered_hr);
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "Error reading heart rate (attempt %d)\n", consecutive_errors);
            if (consecutive_errors >= 5) {
                fprintf(stderr, "Too many consecutive I2C errors, aborting.\n");
                break;
            }
            gpioDelay(100000); /* 100 ms backoff before retry */
            continue;
        }

        gpioDelay(1000000); /* 1 second */
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

