/*
 * KY-026 Flame Sensor Monitor for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   KY-026 VCC  -> 3.3 V (pin 1)
 *   KY-026 GND  -> GND   (pin 9)
 *   KY-026 DO   -> GPIO17 (pin 11)
 *
 * The KY-026 digital output (DO) is active-low: it reads LOW (0) when a
 * flame is detected and HIGH (1) when no flame is present.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lpigpio -lrt
 * Run:
 *   sudo ./flame_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 17          /* BCM 17, physical pin 11 */
#define POLL_INTERVAL_US  100000      /* 100 ms */
#define LOG_FILE_NAME     "flame_log.txt"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static int log_event(FILE *fp)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        perror("localtime_r");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime: buffer too small\n");
        return -1;
    }

    if (fprintf(fp, "%s - FLAME DETECTED\n", timestamp) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO setup                                                          */
/* ------------------------------------------------------------------ */

static int setup_gpio(void)
{
    int ret;

    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "pigpio initialisation failed (code %d)\n", ret);
        return -1;
    }

    /*
     * gpioSetMode with the correct flag value is the portable way to
     * request a line as input or output.  We use the internal pull-up
     * so the line is defined when the sensor is disconnected.
     */
    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n",
                FLAME_SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for GPIO %d\n",
                FLAME_SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    int last_state = 1;          /* assume no flame at startup (HIGH) */
    int first_read = 1;

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE_NAME ")");
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        fclose(g_log_file);
        g_log_file = NULL;
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started on GPIO%d.\n",
           FLAME_SENSOR_GPIO);
    printf("Logging to '%s'. Press Ctrl+C to exit.\n", LOG_FILE_NAME);

    while (g_running) {
        int level = gpioRead(FLAME_SENSOR_GPIO);
        if (level < 0) {
            fprintf(stderr, "gpioRead failed on GPIO %d (code %d)\n",
                    FLAME_SENSOR_GPIO, level);
            break;
        }

        if (first_read) {
            last_state = level;
            first_read = 0;
        }

        /* Falling edge: HIGH -> LOW (active-low sensor) */
        if (last_state == 1 && level == 0) {
            printf("FLAME DETECTED\n");
            fflush(stdout);

            if (log_event(g_log_file) != 0) {
                fprintf(stderr, "Warning: failed to log event.\n");
            }
        }

        last_state = level;
        usleep(POLL_INTERVAL_US);
    }

    /* ---- Graceful shutdown ---- */
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_OFF);
    gpioTerminate();

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

