/*
 * TTP226 8-channel capacitive touch sensor reader with binary counter.
 *
 * Board:  Raspberry Pi Zero W
 * Library: libgpiod (modern Linux GPIO character-device API)
 *
 * Sensor OUT1..OUT8 -> BCM 5,6,7,8,9,10,11,12
 * Counter bits      -> BCM 17..24 (bit0=17, bit7=24)
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_counter touch_counter.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <gpiod.h>

#define NUM_CHANNELS 8
#define COUNTER_BITS 8
#define POLL_INTERVAL_US 10000   /* 10 ms */
#define STABILIZE_US     200000  /* 200 ms */
#define LOG_FILE         "touch_log.txt"

static const unsigned int sensor_pins[NUM_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};
static const unsigned int counter_pins[COUNTER_BITS] = {17, 18, 19, 20, 21, 22, 23, 24};

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int log_touch_event(FILE *fp, int channel, int counter_value)
{
    time_t rawtime;
    struct tm tm_info;
    char timestamp[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &tm_info) == NULL) {
        fprintf(stderr, "gmtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter_value) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    printf("Touch on channel %d | Counter: %d\n", channel, counter_value);
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor_lines[NUM_CHANNELS];
    struct gpiod_line *counter_lines[COUNTER_BITS];
    int ret = EXIT_FAILURE;
    int counter_value = 0;
    FILE *log_fp = NULL;

    for (int i = 0; i < NUM_CHANNELS; i++)
        sensor_lines[i] = NULL;
    for (int i = 0; i < COUNTER_BITS; i++)
        counter_lines[i] = NULL;

    if (install_signal_handlers() != 0)
        goto cleanup;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        goto cleanup;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        sensor_lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (sensor_lines[i] == NULL) {
            fprintf(stderr, "Failed to get sensor line for BCM %u: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(sensor_lines[i], "ttp226_sensor") != 0) {
            fprintf(stderr, "Failed to request sensor line %u as input: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    for (int i = 0; i < COUNTER_BITS; i++) {
        counter_lines[i] = gpiod_chip_get_line(chip, counter_pins[i]);
        if (counter_lines[i] == NULL) {
            fprintf(stderr, "Failed to get counter line for BCM %u: %s\n",
                    counter_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_output(counter_lines[i], "ttp226_counter", 0) != 0) {
            fprintf(stderr, "Failed to request counter line %u as output: %s\n",
                    counter_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Warning: cannot open %s: %s — stdout logging only.\n",
                LOG_FILE, strerror(errno));
    }

    /* Allow sensor outputs to settle. */
    usleep(STABILIZE_US);

    printf("TTP226 touch counter running. Press Ctrl+C to exit.\n");

    while (g_running) {
        int prev_counter = counter_value;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(sensor_lines[i]);
            if (val < 0) {
                fprintf(stderr, "Error reading sensor channel %d (BCM %u): %s\n",
                        i + 1, sensor_pins[i], strerror(errno));
                continue;
            }

            if (val == 1) {
                counter_value = (counter_value + 1) & 0xFF;

                for (int j = 0; j < COUNTER_BITS; j++) {
                    if (gpiod_line_set_value(counter_lines[j],
                                             (counter_value >> j) & 1) != 0) {
                        fprintf(stderr, "Error writing counter bit %d (BCM %u): %s\n",
                                j, counter_pins[j], strerror(errno));
                    }
                }

                if (log_fp != NULL) {
                    if (log_touch_event(log_fp, i + 1, counter_value) != 0)
                        fprintf(stderr, "Logging failed for channel %d\n", i + 1);
                }
            }
        }

        if (prev_counter != counter_value) {
            for (int j = 0; j < COUNTER_BITS; j++) {
                if (gpiod_line_set_value(counter_lines[j],
                                         (prev_counter >> j) & 1) != 0) {
                    fprintf(stderr, "Error restoring counter bit %d (BCM %u): %s\n",
                            j, counter_pins[j], strerror(errno));
                }
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Reset all output pins to 0 before releasing. */
    for (int i = 0; i < COUNTER_BITS; i++) {
        if (counter_lines[i] != NULL) {
            if (gpiod_line_set_value(counter_lines[i], 0) != 0)
                fprintf(stderr, "Warning: failed to reset counter line %d: %s\n",
                        i, strerror(errno));
            gpiod_line_release(counter_lines[i]);
        }
    }
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (sensor_lines[i] != NULL)
            gpiod_line_release(sensor_lines[i]);
    }
    if (chip != NULL)
        gpiod_chip_close(chip);
    if (log_fp != NULL)
        fclose(log_fp);

    if (ret == EXIT_SUCCESS)
        printf("\nShutdown complete.\n");
    return ret;
}

