    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Reset all output pins to 0 before releasing. */
    for (int i = 0; i < COUNTER_BITS; i++) {
        if (counter_lines[i] != NULL) {
            if (gpiod_line_set_value(counter_lines[i], 0) != 0)
                fprintf(stderr, "Warning: failed to reset counter line %d: %s\n",
                        i, strerror(errno));
            gpiod_line_release(counter_lines[i]);
        }
    }
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (sensor_lines[i] != NULL)
            gpiod_line_release(sensor_lines[i]);
    }
    if (chip != NULL)
        gpiod_chip_close(chip);
    if (log_fp != NULL)
        fclose(log_fp);

    if (ret == EXIT_SUCCESS)
        printf("\nShutdown complete.\n");
    return ret;
}

