static int log_data(FILE *fp, int s1, int s2, int s3, int s4) {
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%d,%d,%d,%d\n", ts, s1, s2, s3, s4) < 0) {
        fprintf(stderr, "fprintf() failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

