        if (s1 < 0 || s2 < 0 || s3 < 0 || s4 < 0) {
            fprintf(stderr, "Sensor read error — continuing.\n");
        } else {
            fp = fopen(LOG_FILE, "a");
            if (fp == NULL) {
                fprintf(stderr, "Error re-opening %s: %s\n", LOG_FILE, strerror(errno));
            } else {
