                if (fclose(fp) != 0) {
                    fprintf(stderr, "fclose() failed: %s\n", strerror(errno));
                }
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    gpioTerminate();
