#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define MIC_PIN      4
#define LED_PIN      17
#define SAMPLE_US    125          /* 125 µs → 8 kHz polling */
#define LED_ON_MS    100          /* LED on duration per peak */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void print_timestamp_ms(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    printf("%04d-%02d-%02d %02d:%02d:%02d.%03ld\n",
           tm_info.tm_year + 1900, tm_info.tm_mon + 1, tm_info.tm_mday,
           tm_info.tm_hour, tm_info.tm_min, tm_info.tm_sec,
           ts.tv_nsec / 1000000L);
}

int main(void)
{
    /* --- pigpio library init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n",
                gpioInitialise());
        return EXIT_FAILURE;
    }

    /* --- signal handling (async-signal-safe) --- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- GPIO configuration --- */
    if (gpioSetMode(MIC_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(MIC_PIN=%d, PI_INPUT) failed.\n",
                MIC_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(LED_PIN=%d, PI_OUTPUT) failed.\n",
                LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(LED_PIN=%d, 0) failed.\n",
                LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Microphone sampling started on GPIO%d. LED on GPIO%d.\n",
           MIC_PIN, LED_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* --- main sampling loop --- */
    while (g_running) {
        int level = gpioRead(MIC_PIN);
        if (level < 0) {
            fprintf(stderr, "Error: gpioRead(MIC_PIN=%d) failed (code %d).\n",
                    MIC_PIN, level);
            break;
        }

        if (level == 1) {
            print_timestamp_ms();

            if (gpioWrite(LED_PIN, 1) != 0) {
                fprintf(stderr, "Error: gpioWrite(LED_PIN=%d, 1) failed.\n",
                        LED_PIN);
                break;
            }
            gpioDelay(LED_ON_MS * 1000);   /* µs */
            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "Error: gpioWrite(LED_PIN=%d, 0) failed.\n",
                        LED_PIN);
                break;
            }
        }

        gpioDelay(SAMPLE_US);
    }

    /* --- graceful cleanup --- */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

