#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN  17
#define CENTER_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN  22
#define POLL_DELAY_US     100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_sensor(int pin)
{
    int level = gpioRead(pin);
    if (level < 0) {
        fprintf(stderr, "Error reading GPIO%d: %s\n", pin, pigpio_error(level));
        return -1;
    }
    return level;
}

int main(void)
{
    int left_state, center_state, right_state;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure sensor pins as inputs with internal pull-up resistors */
    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", LEFT_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", CENTER_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", RIGHT_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", LEFT_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(CENTER_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", CENTER_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", RIGHT_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Allow pull-up resistors to settle */
    gpioDelay(10000); /* 10 ms */

    /* Main polling loop */
    while (g_running) {
        left_state  = read_sensor(LEFT_SENSOR_PIN);
        center_state = read_sensor(CENTER_SENSOR_PIN);
        right_state = read_sensor(RIGHT_SENSOR_PIN);

        if (left_state < 0 || center_state < 0 || right_state < 0) {
            fprintf(stderr, "Sensor read error; aborting.\n");
            break;
        }

        printf("Left: %d, Center: %d, Right: %d\n", left_state, center_state, right_state);
        fflush(stdout);

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean up and terminate pigpio */
    gpioTerminate();
    return EXIT_SUCCESS;
}

