/*
 * Si1175 ALS Data Reader for Raspberry Pi 4 Model B
 *
 * Reads the Visible Ambient Light Sensor (ALS) data from a Silicon Labs
 * Si1175 optical heart-rate sensor on I2C bus 1 at 100 ms intervals.
 *
 * Wiring:
 *   Si1175 SDA -> GPIO 2 (I2C1 SDA, pin 3)
 *   Si1175 SCL -> GPIO 3 (I2C1 SCL, pin 5)
 *   Si1175 VDD -> 3.3 V (pin 1)
 *   Si1175 GND -> GND (pin 6)
 *
 * Build: gcc -O2 -Wall -o si1175_als si1175_als.c -lpigpio -lrt
 * Run:   sudo ./si1175_als
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Constants ------------------------------- */
#define I2C_BUS              1
#define SI1175_ADDR          0x60          /* Si1175 default I2C address */

/* Si1175 register addresses (command-register format) */
#define SI1175_REG_COMMAND   0x46          /* Command register address */
#define SI1175_REG_RESPONSE  0x48          /* Response register address */
#define SI1175_REG_ALS_LSB   0x22          /* ALS LSB result register */
#define SI1175_REG_ALS_MSB   0x23          /* ALS MSB result register */

/*
 * Command-register opcodes for the Si1175.
 * The command register is written with the command byte ORed with
 * 0x80 to force a command execution cycle, then the response register
 * is read to verify completion and optionally fetch any result data.
 */
#define SI1175_CMD_RESET     0x01          /* Software reset */
#define SI1175_CMD_ALS_FORCE 0x06          /* Force ALS measurement */

/* --------------------------- Global State ------------------------------ */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------- Signal Handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------- I2C Helpers --------------------------------- */

/*
 * Write a single byte to a Si1175 register.
 * Returns 0 on success, -1 on failure.
 */
static int si1175_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/*
 * Read a single byte from a Si1175 register.
 * Returns the byte value (0-255) on success, -1 on failure.
 */
static int si1175_read_reg(int handle, uint8_t reg)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    return rc;
}

/*
 * Send a command to the Si1175 command register and read the response.
 * Returns 0 on success, -1 on failure.
 */
static int si1175_send_command(int handle, uint8_t cmd)
{
    /* Write command byte to command register (ORed with 0x80) */
    if (si1175_write_reg(handle, SI1175_REG_COMMAND, cmd | 0x80) < 0)
        return -1;

    /* Small delay to let the sensor process the command */
    gpioDelay(10000); /* 10 ms */

    /* Read response register to verify completion */
    int resp = si1175_read_reg(handle, SI1175_REG_RESPONSE);
    if (resp < 0)
        return -1;

    /*
     * The response register typically contains the status of the
     * previous command. A non-zero value usually indicates an error.
     */
    if (resp != 0) {
        fprintf(stderr, "[ERROR] Si1175 response register = 0x%02X (cmd=0x%02X)\n",
                resp, cmd);
        return -1;
    }

    return 0;
}

/*
 * Read a 16-bit ALS value from the Si1175.
 * Returns 0 on success and stores the raw value in *out, -1 on failure.
 */
static int si1175_read_als(int handle, uint16_t *out)
{
    int lsb = si1175_read_reg(handle, SI1175_REG_ALS_LSB);
    if (lsb < 0)
        return -1;

    int msb = si1175_read_reg(handle, SI1175_REG_ALS_MSB);
    if (msb < 0)
        return -1;

    *out = (uint16_t)((msb << 8) | lsb);
    return 0;
}

/* --------------------------- Sensor Init ------------------------------- */
static int si1175_init(int handle)
{
    /*
     * Software reset to ensure a known state.
     * The sensor may still be present even if the reset fails, but
     * subsequent operations will fail if the device is not responding.
     */
    if (si1175_send_command(handle, SI1175_CMD_RESET) < 0) {
        fprintf(stderr, "[ERROR] Si1175 reset command failed (sensor may be absent)\n");
        return -1;
    }

    /* Allow time for the reset to complete */
    gpioDelay(20000); /* 20 ms */

    /*
     * Force an ALS measurement so the device is in a known state.
     * This also exercises the I2C bus and verifies the sensor is
     * responding at the expected address.
     */
    if (si1175_send_command(handle, SI1175_CMD_ALS_FORCE) < 0) {
        fprintf(stderr, "[ERROR] Si1175 ALS force command failed\n");
        return -1;
    }

    return 0;
}

/* ------------------------------ Main ----------------------------------- */
int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the Si1175 default address */
    g_i2c_handle = i2cOpen(I2C_BUS, SI1175_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SI1175_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the Si1175 sensor */
    if (si1175_init(g_i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] Si1175 initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si1175 ALS reader started. Press Ctrl+C to stop.\n");

    /* Main acquisition loop */
    while (g_running) {
        uint16_t als_value = 0;

        if (si1175_read_als(g_i2c_handle, &als_value) < 0) {
            fprintf(stderr, "[WARN] Failed to read ALS data; continuing\n");
        } else {
            printf("ALS Raw Value: %u\n", als_value);
        }

        /*
         * Sleep 100 ms between samples.
         * gpioDelay is a microsecond-level delay that does not block
         * signals, so we can exit promptly on Ctrl+C.
         */
        gpioDelay(100000); /* 100 ms */
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    i2cClose(g_i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

