    sa.sa_flags = 0;
    return sigaction(SIGINT, &sa, NULL);
}

static int read_sensor(int pin, int *value)
{
    int rc;

    rc = gpioRead(pin);
    if (rc < 0) {
        fprintf(stderr, "gpioRead failed on pin %d: %s\n", pin, strerror(errno));
        return -1;
    }

    *value = rc;
    return 0;
}

static int setup_sensor_pin(int pin)
{
    int rc;

    rc = gpioSetMode(pin, PI_INPUT);
    if (rc < 0) {
        fprintf(stderr, "gpioSetMode failed on pin %d: %s\n", pin, strerror(errno));
        return -1;
    }

    return 0;
}

