{
    int left_value, middle_value, right_value;
    int rc;

    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (install_signal_handler() != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (setup_sensor_pin(LEFT_SENSOR_PIN)  != 0 ||
        setup_sensor_pin(MIDDLE_SENSOR_PIN) != 0 ||
        setup_sensor_pin(RIGHT_SENSOR_PIN) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        if (read_sensor(LEFT_SENSOR_PIN,  &left_value)  != 0 ||
            read_sensor(MIDDLE_SENSOR_PIN, &middle_value) != 0 ||
            read_sensor(RIGHT_SENSOR_PIN, &right_value) != 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }

        printf("L:%d M:%d R:%d\n", left_value, middle_value, right_value);
        fflush(stdout);

        gpioDelay(POLL_DELAY_US);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

