/*
 * TTP226 8-channel capacitive touch sensor poller for Raspberry Pi 3 B+.
 *
 * Wiring (TTP226 OUT -> Raspberry Pi BCM GPIO):
 *   TP1 -> GPIO5   TP5 -> GPIO26
 *   TP2 -> GPIO6   TP6 -> GPIO12
 *   TP3 -> GPIO13  TP7 -> GPIO16
 *   TP4 -> GPIO19  TP8 -> GPIO20
 *
 * Build: gcc -o touch_poll touch_poll.c -lrt
 * Run:   ./touch_poll
 */
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_US 200000  /* 200 ms */

static const int channel_pins[NUM_CHANNELS] = {
    5, 6, 13, 19, 26, 12, 16, 20
};

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void print_timestamp(double seconds)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    printf("[%06.3f s] ", seconds);
}

int main(void)
{
    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure all 8 channel pins as inputs --- */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(channel_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO%d as input.\n",
                    channel_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* --- Request a single line handle for each channel --- */
    int line_handles[NUM_CHANNELS];
    for (int i = 0; i < NUM_CHANNELS; i++) {
        line_handles[i] = gpioGetLine(channel_pins[i]);
        if (line_handles[i] < 0) {
            fprintf(stderr, "Error: failed to get line handle for GPIO%d.\n",
                    channel_pins[i]);
            for (int j = 0; j < i; j++)
                gpioTerminateLine(line_handles[j]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* --- Main polling loop --- */
    while (g_running) {
        bool read_failed = false;
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpioRead(line_handles[i]);
            if (val < 0) {
                fprintf(stderr, "Error: failed to read GPIO%d.\n",
                        channel_pins[i]);
                read_failed = true;
                break;
            }
        }

        if (read_failed) {
            break;
        }

        double elapsed;
        struct timespec now;
        if (clock_gettime(CLOCK_MONOTONIC, &now) != 0) {
            perror("clock_gettime");
            break;
        }
        elapsed = (double)(now.tv_sec)
                + (double)(now.tv_nsec) / 1.0e9;

        print_timestamp(elapsed);

        /*
         * TTP226 outputs 0 or 1 for each channel.
         * Print only if the value is non-zero to keep the console
         * readable; a value of 0 is implicitly not touched.
         */
        printf("CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
               gpioRead(line_handles[0]),
               gpioRead(line_handles[1]),
               gpioRead(line_handles[2]),
               gpioRead(line_handles[3]),
               gpioRead(line_handles[4]),
               gpioRead(line_handles[5]),
               gpioRead(line_handles[6]),
               gpioRead(line_handles[7]));
        fflush(stdout);

        usleep(POLL_INTERVAL_US);
    }

    /* --- Cleanup --- */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpioTerminateLine(line_handles[i]);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

