#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27

#define PWM_FREQUENCY 1000
#define PWM_RANGE     255
#define FADE_STEPS    50
#define FADE_DURATION 5.0
#define STEP_DELAY    0.1

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void cleanup(void) {
    /* Turn off LED channels */
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);

    /* Release PWM resources */
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);
    gpioSetPWMfrequency(RED_PIN, 0);
    gpioSetPWMfrequency(GREEN_PIN, 0);
    gpioSetPWMfrequency(BLUE_PIN, 0);
    gpioSetMode(RED_PIN, PI_INPUT);
    gpioSetMode(GREEN_PIN, PI_INPUT);
    gpioSetMode(BLUE_PIN, PI_INPUT);

    gpioTerminate();
    closelog();
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set RED_PIN %d as output", RED_PIN);
        return -1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GREEN_PIN %d as output", GREEN_PIN);
        return -1;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set BLUE_PIN %d as output", BLUE_PIN);
        return -1;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency for RED_PIN %d", RED_PIN);
        return -1;
    }
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency for GREEN_PIN %d", GREEN_PIN);
        return -1;
    }
    if (gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency for BLUE_PIN %d", BLUE_PIN);
        return -1;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) != PWM_RANGE) {
        syslog(LOG_ERR, "Failed to set PWM range for RED_PIN %d", RED_PIN);
        return -1;
    }
    if (gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != PWM_RANGE) {
        syslog(LOG_ERR, "Failed to set PWM range for GREEN_PIN %d", GREEN_PIN);
        return -1;
    }
    if (gpioSetPWMrange(BLUE_PIN, PWM_RANGE) != PWM_RANGE) {
        syslog(LOG_ERR, "Failed to set PWM range for BLUE_PIN %d", BLUE_PIN);
        return -1;
    }

    /* Start with LED off */
    if (gpioPWM(RED_PIN, 0) != 0 || gpioPWM(GREEN_PIN, 0) != 0 || gpioPWM(BLUE_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to initialise PWM duty cycle to 0");
        return -1;
    }

    syslog(LOG_INFO, "GPIO initialised: RED=%d, GREEN=%d, BLUE=%d", RED_PIN, GREEN_PIN, BLUE_PIN);
    return 0;
}

static void hsl_to_rgb(float h, float s, float l, int *r, int *g, int *b) {
    if (s <= 0.0f) {
        *r = *g = *b = (int)(h * 255.0f);
        return;
    }

    float q = l < 0.5f ? (l * (1.0f + s)) : (l + s - l * s);
    float p = 2.0f * l - q;

    float hue_f = h / 360.0f;
    int i = (int)floorf(hue_f);
    float f = hue_f - i;
    float h_p = (i % 6) / 6.0f;

    float rf, gf, bf;
    switch (i) {
        case 0:  rf = q; gf = p; bf = 0; break;
        case 1:  rf = p; gf = q; bf = 0; break;
        case 2:  rf = 0; gf = q; bf = p; break;
        case 3:  rf = 0; gf = p; bf = q; break;
        case 4:  rf = p; gf = 0; bf = q; break;
        default: rf = q; gf = 0; bf = p; break;
    }

    rf = rf + h_p * (1.0f - f) * s;
    gf = gf + h_p * f * s;
    bf = bf + (1.0f - h_p) * f * s;

    *r = (int)(rf * 255.0f);
    *g = (int)(gf * 255.0f);
    *b = (int)(bf * 255.0f);
}

static void fade_led(int r_start, int g_start, int b_start,
                     int r_end, int g_end, int b_end) {
    float step = FADE_DURATION / (float)FADE_STEPS;
    float r = (float)r_start;
    float g = (float)g_start;
    float b = (float)b_start;

    for (int i = 0; i < FADE_STEPS && g_running; i++) {
        hsl_to_rgb(r, 1.0f, g, &r, &g, &b);
        r = r + (r_end - r_start) * step;
        g = g + (g_end - g_start) * step;
        b = b + (b_end - b_start) * step;

        if (gpioPWM(RED_PIN, (int)r) != 0 ||
            gpioPWM(GREEN_PIN, (int)g) != 0 ||
            gpioPWM(BLUE_PIN, (int)b) != 0) {
            syslog(LOG_ERR, "Failed to set PWM duty cycle");
            return;
        }

        time_sleep(STEP_DELAY);
    }

    /* Ensure final colour is reached */
    if (g_running) {
        hsl_to_rgb(r, 1.0f, g, &r, &g, &b);
        gpioPWM(RED_PIN, (int)r);
        gpioPWM(GREEN_PIN, (int)g);
        gpioPWM(BLUE_PIN, (int)b);
    }
}

int main(void) {
    openlog("rgb_fade", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to register SIGINT handler: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to register SIGTERM handler: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialisation failed, exiting");
        closelog();
        return EXIT_FAILURE;
    }

    srand((unsigned int)time(NULL));

    syslog(LOG_INFO, "Starting RGB fade loop");

    while (g_running) {
        int r = rand() % 256;
        int g = rand() % 256;
        int b = rand() % 256;

        syslog(LOG_INFO, "New hue: R=%d G=%d B=%d", r, g, b);

        fade_led(r, g, b, r, g, b);
    }

    syslog(LOG_INFO, "Shutting down gracefully");
    cleanup();
    return EXIT_SUCCESS;
}

