#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define TCS34725_ADDR  0x29

#define TCS34725_ENABLE  0x80
#define TCS34725_ATIME   0x81
#define TCS34725_CDATA   0x94
#define TCS34725_RDATA   0x96
#define TCS34725_GDATA   0x98
#define TCS34725_BDATA   0x9A

#define LED_PIN          17
#define RED_THRESHOLD    200
#define POLL_DELAY_US    200000
#define INTEGRATION_MS   154

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int tcs34725_init(int fd) {
    if (i2c_write_reg8(fd, TCS34725_ENABLE, 0x01) < 0) return -1;
    usleep(3000);
    if (i2c_write_reg8(fd, TCS34725_ATIME, INTEGRATION_MS) < 0) return -1;
    if (i2c_write_reg8(fd, TCS34725_ENABLE, 0x03) < 0) return -1;
    return 0;
}

static int tcs34725_read_data(int fd, uint16_t *r, uint16_t *g, uint16_t *b, uint16_t *c) {
    uint8_t r_l, r_h, g_l, g_h, b_l, b_h, c_l, c_h;
    if (i2c_read_reg8(fd, TCS34725_CDATA, &c_l) < 0) return -1;
    if (i2c_read_reg8(fd, TCS34725_CDATA + 1, &c_h) < 0) return -1;
    if (i2c_read_reg8(fd, TCS34725_RDATA, &r_l) < 0) return -1;
    if (i2c_read_reg8(fd, TCS34725_RDATA + 1, &r_h) < 0) return -1;
    if (i2c_read_reg8(fd, TCS34725_GDATA, &g_l) < 0) return -1;
    if (i2c_read_reg8(fd, TCS34725_GDATA + 1, &g_h) < 0) return -1;
    if (i2c_read_reg8(fd, TCS34725_BDATA, &b_l) < 0) return -1;
    if (i2c_read_reg8(fd, TCS34725_BDATA + 1, &b_h) < 0) return -1;
    *c = (uint16_t)((c_h << 8) | c_l);
    *r = (uint16_t)((r_h << 8) | r_l);
    *g = (uint16_t)((g_h << 8) | g_l);
    *b = (uint16_t)((b_h << 8) | b_l);
    return 0;
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        i2c_write_reg8(i2c_fd, TCS34725_ENABLE, 0x00);
        close(i2c_fd);
        i2c_fd = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (tcs34725_init(i2c_fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    uint16_t r, g, b, c;
    while (running) {
        if (tcs34725_read_data(i2c_fd, &r, &g, &b, &c) == 0) {
            printf("R: %5u, G: %5u, B: %5u, C: %5u\n", r, g, b, c);
            if (r > RED_THRESHOLD) {
                gpioWrite(LED_PIN, 1);
            } else {
                gpioWrite(LED_PIN, 0);
            }
        } else {
            fprintf(stderr, "Read failed; re-initializing sensor...\n");
            tcs34725_init(i2c_fd);
        }
        usleep(POLL_DELAY_US);
    }

    gpioWrite(LED_PIN, 0);
    cleanup();
    return EXIT_SUCCESS;
}

