#include <linux/i2c.h>
#include <pigpio.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x5C
#define BH1750_CONT_HIGH_RES_MODE 0x10
#define WS2812B_GPIO 18
#define NUM_LEDS 10
#define MAX_LUX 10000.0
#define MIN_LUX 0.0
#define LOG_BASE 10.0
#define LOG_MAX 10.0
#define LOG_MIN 0.0
#define MEASUREMENT_DELAY_US 180000
#define LOOP_DELAY_US 100000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint16_t *value) {
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int bh1750_init(int fd) {
    if (i2c_write_byte(fd, BH1750_CONT_HIGH_RES_MODE) < 0) {
        return -1;
    }
    usleep(MEASUREMENT_DELAY_US);
    return 0;
}

static int bh1750_read_lux(int fd, float *lux) {
    uint16_t raw;
    if (i2c_read_word(fd, &raw) < 0) {
        return -1;
    }
    *lux = (float)raw / 1.2;
    return 0;
}

static void ws2812b_send_bit(int gpio, int bit) {
    if (bit) {
        gpioWaveTxAddGeneric(1, 0, 1, 0);
    } else {
        gpioWaveTxAddGeneric(1, 0, 0, 1);
    }
}

static void ws2812b_send_byte(int gpio, uint8_t byte, int bit_start) {
    for (int i = 7; i >= 0; i--) {
        ws2812b_send_bit(gpio, (byte >> i) & 0x01);
    }
}

static void ws2812b_send_led(int gpio, uint8_t r, uint8_t g, uint8_t b) {
    uint8_t grb[3] = {g, r, b};
    for (int i = 0; i < 24; i++) {
        ws2812b_send_bit(gpio, (grb[i / 8] >> (7 - (i % 8))) & 0x01);
    }
    ws2812b_send_bit(gpio, 0);
}

static void ws2812b_strip_set(int gpio, uint8_t r, uint8_t g, uint8_t b) {
    for (int i = 0; i < NUM_LEDS; i++) {
        ws2812b_send_led(gpio, r, g, b);
    }
}

static void ws2812b_strip_clear(int gpio) {
    ws2812b_strip_set(gpio, 0, 0, 0);
}

static void ws2812b_render(int gpio) {
    gpioWaveClear();
    gpioWaveTxSend();
    while (gpioWaveTxBusy()) {
        usleep(10);
    }
    gpioWaveDelete();
}

static float map_lux_to_brightness(float lux) {
    if (lux <= MIN_LUX) {
        return 0.0;
    }
    if (lux >= MAX_LUX) {
        return 1.0;
    }
    float log_lux = log10f(lux);
    float log_max = log10f(MAX_LUX);
    float log_min = log10f(MIN_LUX);
    float brightness = (log_lux - log_min) / (log_max - log_min);
    if (brightness < 0.0) {
        brightness = 0.0;
    }
    if (brightness > 1.0) {
        brightness = 1.0;
    }
    return brightness;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to acquire I2C bus access");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed (sensor may be absent)\n");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(WS2812B_GPIO, PI_OUTPUT);
    gpioSetPullUpDown(WS2812B_GPIO, PI_PUD_UP);

    while (running) {
        float lux = 0.0;
        int retries = 0;
        bool success = false;

        while (retries < MAX_RETRIES && running) {
            if (bh1750_read_lux(i2c_fd, &lux) == 0) {
                success = true;
                break;
            }
            retries++;
            fprintf(stderr, "BH1750 read failed (attempt %d/%d)\n", retries, MAX_RETRIES);
            usleep(100000);
        }

        if (!success) {
            fprintf(stderr, "BH1750 read failed after %d retries. Skipping frame.\n", MAX_RETRIES);
            usleep(LOOP_DELAY_US);
            continue;
        }

        float brightness = map_lux_to_brightness(lux);

        ws2812b_strip_clear(WS2812B_GPIO);
        ws2812b_render(WS2812B_GPIO);

        uint8_t r = (uint8_t)(brightness * 255.0);
        uint8_t g = (uint8_t)((brightness * 255.0) / 2.0);
        uint8_t b = (uint8_t)((brightness * 255.0) / 2.0);
        ws2812b_strip_set(WS2812B_GPIO, r, g, b);
        ws2812b_render(WS2812B_GPIO);

        usleep(LOOP_DELAY_US);
    }

    ws2812b_strip_clear(WS2812B_GPIO);
    gpioWaveClear();
    gpioTerminate();
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return EXIT_SUCCESS;
}

