/*
 * Raspberry Pi Zero W – BH1750 ambient light sensor → APA102 LED strip controller
 *
 * Hardware:
 *   - BH1750 on /dev/i2c-1, address 0x5C (ADDR pin low)
 *   - APA102 on /dev/spidev0.0, MOSI/MISO/SCLK/CS, 1 MHz SPI clock
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o light_led light_led.c -lm
 *
 * Run:
 *   ./light_led   (Ctrl-C to exit)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SPI_BUS        "/dev/spidev0.0"
#define BH1750_ADDR    0x5C
#define APA102_NUM_LEDS 10
#define SPI_SPEED_HZ   1000000U
#define BH1750_CONV_MS 120
#define LOOP_DELAY_MS  100

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * BH1750 power-on reset, then continuous high-resolution mode.
 * Returns 0 on success, -1 on error.
 */
static int bh1750_init(int fd)
{
    /* Power on / reset */
    if (write(fd, (uint8_t[]){0x10}, 1) != 1) {
        fprintf(stderr, "BH1750 power-on write: %s\n", strerror(errno));
        return -1;
    }
    usleep(10000);  /* 10 ms settle */

    /* Continuous high-resolution mode (0x10 | 0x00 = 0x10) */
    if (write(fd, (uint8_t[]){0x10}, 1) != 1) {
        fprintf(stderr, "BH1750 mode write: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read the 2-byte conversion result.
 * Returns 0 on success and stores the raw value in *out; -1 on error.
 */
static int bh1750_read(int fd, uint16_t *out)
{
    uint8_t buf[2];
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        if (n < 0)
            fprintf(stderr, "BH1750 read: %s\n", strerror(errno));
        else
            fprintf(stderr, "BH1750 read: short read (%zd bytes)\n", n);
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */

static int spi_open(const char *bus, uint32_t speed_hz)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_hz) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Build an APA102 frame:
 *   [0x00000000]  start frame
 *   [0x00xxxxxx]  per-LED frames (brightness, B, G, R)
 *   [0xFFFFFFFF]  end frame
 * Returns 0 on success, -1 on error.
 */
static int apa102_build(int spi_fd, uint8_t brightness,
                        uint8_t r, uint8_t g, uint8_t b)
{
    size_t end_len = 4;
    size_t frame_len = 5;   /* 0x00 + 0x00 + r + g + b + 0xFF */
    size_t total = (size_t)APA102_NUM_LEDS * frame_len + end_len;
    uint8_t *data = malloc(total);
    if (!data) {
        fprintf(stderr, "malloc: %s\n", strerror(errno));
        return -1;
    }

    size_t idx = 0;
    memset(&data[idx], 0x00, 4); idx += 4;

    for (int i = 0; i < APA102_NUM_LEDS; i++) {
        data[idx++] = brightness;
        data[idx++] = b;
        data[idx++] = g;
        data[idx++] = r;
    }

    memset(&data[idx], 0xFF, 4); idx += 4;

    ssize_t written = write(spi_fd, data, total);
    free(data);

    if (written < 0 || (size_t)written != total) {
        fprintf(stderr, "SPI write: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int i2c_fd = i2c_open(I2C_BUS, BH1750_ADDR);
    if (i2c_fd < 0)
        return EXIT_FAILURE;

    int spi_fd = spi_open(SPI_BUS, SPI_SPEED_HZ);
    if (spi_fd < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 init failed – sensor may be absent or wired incorrectly\n");
        close(spi_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("BH1750 initialised on %s (0x%02X). LED strip on %s (%d LEDs, 1 MHz).\n",
           I2C_BUS, BH1750_ADDR, SPI_BUS, APA102_NUM_LEDS);
    printf("Press Ctrl-C to exit.\n");

    while (g_running) {
        uint16_t raw = 0;
        if (bh1750_read(i2c_fd, &raw) < 0) {
            fprintf(stderr, "BH1750 read failed – continuing after 1 s\n");
            sleep(1);
            continue;
        }

        /* Convert raw 16-bit value to a scaled brightness (0–255).
         * The BH1750 high-resolution mode outputs 1 lx per LSB. */
        uint8_t brightness = (uint8_t)(raw / 1.0f);
        if (brightness > 255) brightness = 255;
        if (brightness < 0)   brightness = 0;

        /* Scale brightness to a per-LED value for the APA102 frame.
         * APA102 expects per-LED frames to be 5 bytes (0x00 + r + g + b + 0xFF). */
        uint8_t per_led = (uint8_t)((float)brightness / APA102_NUM_LEDS);
        if (per_led > 255) per_led = 255;
        if (per_led < 0)   per_led = 0;

        if (apa102_build(spi_fd, per_led, 0, 0, 0) < 0) {
            fprintf(stderr, "APA102 update failed – continuing after 1 s\n");
            sleep(1);
            continue;
        }

        usleep(BH1750_CONV_MS * 1000);
        usleep(LOOP_DELAY_MS * 1000);
    }

    /* Graceful shutdown: turn off all LEDs and release resources. */
    printf("\nShutting down...\n");
    apa102_build(spi_fd, 0, 0, 0, 0);  /* 0 brightness → all LEDs off */
    close(spi_fd);
    close(i2c_fd);
    printf("Done.\n");
    return EXIT_SUCCESS;
}

