code:
/*
 * Raspberry Pi 3 Model B+ — BH1750 ambient-light sensor → APA102 RGB LED strip.
 *
 * Hardware:
 *   - BH1750 x 3 on I2C bus 1, addresses 0x5C (ADDR pin low) and 0x5D (ADDR high).
 *   - APA102 RGB LED strip: MOSI (GPIO10 / BCM 19) and SCLK (GPIO11 / BCM 23).
 *
 * Behaviour:
 *   - Reads light from up to three BH1750 sensors every 100 ms.
 *   - Averages valid readings; skips sensors that report I2C errors.
 *   - Fades LED strip brightness to the average over 500 ms.
 *   - On SIGINT: turns LEDs off, closes I2C handles, closes SPI, terminates
 *     libraries, and exits cleanly.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define I2C_BUS          "/dev/i2c-1"
#define SPI_DEVICE       "/dev/spidev0.0"
#define NUM_SENSORS      3
#define BH1750_ADDR_LOW  0x5C
#define BH1750_ADDR_HIGH 0x5D
#define BH1750_CMD_POWER_ON  0x01
#define BH1750_CMD_CONT_HRES  0x10
#define BH1750_CONV_MS      180
#define APA102_NUM_LEDS    100
#define FADE_MS           500
#define LOOP_MS           100
#define MAX_BRIGHTNESS    0xFF

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

typedef struct {
    int fd;
    bool present;
} sensor_t;

static int i2c_open(uint8_t addr)
{
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int bh1750_init(sensor_t *s)
{
    s->fd = -1;
    s->present = false;

    s->fd = i2c_open(BH1750_ADDR_LOW);
    if (s->fd >= 0) {
        if (ioctl(s->fd, I2C_SLAVE, BH1750_ADDR_LOW) < 0) {
            fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                    BH1750_ADDR_LOW, strerror(errno));
            close(s->fd);
            s->fd = -1;
            return -1;
        }
        if (write(s->fd, &(uint8_t){BH1750_CMD_POWER_ON}, 1) != 1) {
            fprintf(stderr, "BH1750 power-on write: %s\n", strerror(errno));
            close(s->fd);
            s->fd = -1;
            return -1;
        }
        if (write(s->fd, &(uint8_t){BH1750_CMD_CONT_HRES}, 1) != 1) {
            fprintf(stderr, "BH1750 mode set: %s\n", strerror(errno));
            close(s->fd);
            s->fd = -1;
            return -1;
        }
        s->present = true;
        printf("BH1750 at 0x%02X initialised.\n", BH1750_ADDR_LOW);
        return 0;
    }

    s->fd = i2c_open(BH1750_ADDR_HIGH);
    if (s->fd >= 0) {
        if (ioctl(s->fd, I2C_SLAVE, BH1750_ADDR_HIGH) < 0) {
            fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                    BH1750_ADDR_HIGH, strerror(errno));
            close(s->fd);
            s->fd = -1;
            return -1;
        }
        if (write(s->fd, &(uint8_t){BH1750_CMD_POWER_ON}, 1) != 1) {
            fprintf(stderr, "BH1750 power-on write: %s\n", strerror(errno));
            close(s->fd);
            s->fd = -1;
            return -1;
        }
        if (write(s->fd, &(uint8_t){BH1750_CMD_CONT_HRES}, 1) != 1) {
            fprintf(stderr, "BH1750 mode set: %s\n", strerror(errno));
            close(s->fd);
            s->fd = -1;
            return -1;
        }
        s->present = true;
        printf("BH1750 at 0x%02X initialised.\n", BH1750_ADDR_HIGH);
        return 0;
    }

    fprintf(stderr, "No BH1750 at 0x%02X or 0x%02X.\n",
            BH1750_ADDR_LOW, BH1750_ADDR_HIGH);
    return -1;
}

static int bh1750_read(sensor_t *s, uint16_t *lux)
{
    if (!s->present || s->fd < 0)
        return -1;

    /* Trigger a one-shot conversion (no register write needed in continuous mode). */
    usleep(BH1750_CONV_MS * 1000);

    uint8_t buf[2];
    ssize_t n = read(s->fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "BH1750 read: expected 2 bytes, got %zd (%s)\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux = raw & 0xFFFF;  /* 16-bit result, MSB first */
    return 0;
}

static int apa102_init(int spi_fd)
{
    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = 1000000; /* 1 MHz */

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI mode: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI bits: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI speed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int apa102_frame(int spi_fd, uint8_t brightness)
{
    size_t len = APA102_NUM_LEDS * 4 + 8;
    uint8_t *frame = malloc(len);
    if (!frame) {
        fprintf(stderr, "malloc: %s\n", strerror(errno));
        return -1;
    }

    memset(frame, 0x00, 8);
    for (int i = 0; i < APA102_NUM_LEDS; i++) {
        frame[2 * i + 0] = 0xE0 | (brightness & 0x1F);
        frame[2 * i + 1] = 0x00;
    }

    ssize_t written = 0;
    while (written < (ssize_t)len) {
        ssize_t w = write(spi_fd, frame + written, len - written);
        if (w < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "SPI write: %s\n", strerror(errno));
            free(frame);
            return -1;
        }
        written += w;
    }
    free(frame);
    return 0;
}

static int apa102_fade(int spi_fd, uint8_t target)
{
    uint8_t steps = 5;
    uint32_t delay_us = (uint32_t)(FADE_MS * 1000);
    uint8_t inc = (target > 0) ? 1 : -1;

    for (int i = 0; i < steps && g_running; i++) {
        uint8_t val = (uint8_t)(target + inc * i);
        if (val > MAX_BRIGHTNESS) val = MAX_BRIGHTNESS;
        if (val < 0) val = 0;
        if (apa102_frame(spi_fd, val) < 0) return -1;
        usleep(delay_us);
    }
    return 0;
}

static void cleanup(int spi_fd, sensor_t s[NUM_SENSORS])
{
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (s[i].fd >= 0) {
            close(s[i].fd);
            s[i].fd = -1;
        }
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return 1;
    }

    sensor_t sensors[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++) {
        sensors[i].fd = -1;
        sensors[i].present = false;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return 1;
    }

    if (apa102_init(spi_fd) < 0) {
        fprintf(stderr, "APA102 init failed.\n");
        cleanup(spi_fd, sensors);
        return 1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (bh1750_init(&sensors[i]) < 0) {
            fprintf(stderr, "BH1750 init failed for sensor %d.\n", i);
        }
    }

    uint8_t target = 0;

    while (g_running) {
        uint32_t sum = 0;
        int valid = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            uint16_t lux;
            if (bh1750_read(&sensors[i], &lux) == 0) {
                sum += lux;
                valid++;
            }
        }

        if (valid > 0) {
            uint32_t avg = sum / (uint32_t)valid;
            if (avg > MAX_BRIGHTNESS) avg = MAX_BRIGHTNESS;
            if (avg < 0) avg = 0;
            target = (uint8_t)avg;
        } else {
            fprintf(stderr, "No valid BH1750 readings this cycle.\n");
        }

        if (apa102_fade(spi_fd, target) < 0) {
            fprintf(stderr, "Fade failed.\n");
        }

        usleep(LOOP_MS * 1000);
    }

    printf("\nShutting down...\n");
    apa102_frame(spi_fd, 0);
    cleanup(spi_fd, sensors);
    return 0;
}

