#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define VEML7700_ADDR 0x40
#define VEML7700_REG_CONF 0x00
#define VEML7700_REG_ALS 0x04
#define I2C_BUS "/dev/i2c-1"

#define WS2812B_GPIO 18
#define NUM_LEDS 10
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100
#define LOOP_DELAY_MS 200
#define MAX_LUX 10000.0f

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int veml7700_init(int fd) {
    if (i2c_write_reg8(fd, VEML7700_REG_CONF, 0x00) < 0) {
        return -1;
    }
    usleep(10000);
    return 0;
}

static int veml7700_read_lux(int fd, float *lux_out) {
    uint16_t als;
    if (i2c_read_reg16(fd, VEML7700_REG_ALS, &als) < 0) {
        return -1;
    }
    *lux_out = (float)als / 100.0f;
    return 0;
}

static float gamma_correct(float lux) {
    float gamma = 0.45f;
    return powf(lux, gamma);
}

static void ws2812b_set_led(int gpio, int led_index, uint8_t r, uint8_t g, uint8_t b) {
    if (led_index < 0 || led_index >= NUM_LEDS) return;
    uint8_t color_code = (r << 16) | (g << 8) | b;
    uint32_t mask = 1 << led_index;
    uint32_t data = 0;
    for (int i = 23; i >= 0; i--) {
        if ((color_code >> i) & 1) {
            data |= mask;
        }
    }
    uint32_t local_data = data;
    for (int i = 0; i < 24; i++) {
        int bit = (local_data >> i) & 1;
        gpioWrite(gpio, bit);
        usleep(1);
    }
    gpioWrite(gpio, 0);
    usleep(60);
}

static void ws2812b_set_brightness(int gpio, float brightness) {
    if (brightness < 0.0f) brightness = 0.0f;
    if (brightness > 1.0f) brightness = 1.0f;
    uint8_t r = (uint8_t)(brightness * 255.0f);
    uint8_t g = (uint8_t)((brightness - r) * 510.0f / (1.0f - r));
    uint8_t b = (uint8_t)((1.0f - r) * 353.0f / (1.0f - r));
    for (int i = 0; i < NUM_LEDS; i++) {
        ws2812b_set_led(gpio, i, r, g, b);
    }
}

static void ws2812b_off(int gpio) {
    for (int i = 0; i < NUM_LEDS; i++) {
        ws2812b_set_led(gpio, i, 0, 0, 0);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", VEML7700_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (veml7700_init(i2c_fd) < 0) {
        fprintf(stderr, "Error initializing VEML7700: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing GPIO: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    gpioSetMode(WS2812B_GPIO, PI_OUTPUT);
    ws2812b_off(WS2812B_GPIO);

    while (running) {
        float lux = 0.0f;
        int retries = 0;
        int success = 0;

        while (retries < RETRY_COUNT && running) {
            if (veml7700_read_lux(i2c_fd, &lux) == 0) {
                success = 1;
                break;
            }
            retries++;
            if (retries < RETRY_COUNT) {
                usleep(RETRY_DELAY_MS * 1000);
            }
        }

        if (!success) {
            fprintf(stderr, "Error reading lux after %d retries: %s\n", RETRY_COUNT, strerror(errno));
            lux = 0.0f;
        }

        float brightness = gamma_correct(lux);
        ws2812b_set_brightness(WS2812B_GPIO, brightness);

        printf("Lux: %.2f, Brightness: %.2f\n", lux, brightness);
        fflush(stdout);

        usleep(LOOP_DELAY_MS * 1000);
    }

    ws2812b_off(WS2812B_GPIO);
    gpioTerminate();
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    printf("\nExiting gracefully...\n");
    return 0;
}

