#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN      17
#define LED_PIN         18

#define POLL_INTERVAL_US  50000   /* 50 ms */
#define TEST_DELAY_US     100000  /* 100 ms */
#define TEST_CYCLES       5
#define ERROR_BLINK_US    100000  /* 100 ms */
#define ERROR_BEEP_US     200000  /* 200 ms */
#define ERROR_BEEP_COUNT  3
#define ALARM_ON_US       1000000 /* 1 s */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", ts, msg);
    fflush(stdout);
}

static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) < 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static int safe_read(unsigned pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead(%u) failed\n", pin);
        return -1;
    }
    return v;
}

static void self_test(void)
{
    log_event("Starting self-test...");

    /* Blink LED twice: 500ms on / 500ms off */
    for (int i = 0; i < 2; i++) {
        if (safe_write(LED_PIN, 1) < 0) goto test_failed;
        gpioDelay(500000);
        if (safe_write(LED_PIN, 0) < 0) goto test_failed;
        gpioDelay(500000);
    }

    /* Read flame sensor 5 times at 100ms intervals */
    int flame_count = 0;
    for (int i = 0; i < TEST_CYCLES; i++) {
        int val = safe_read(FLAME_SENSOR_PIN);
        if (val < 0) {
            log_event("Error: Failed to read flame sensor during self-test");
            goto test_failed;
        }
        if (val == 0) flame_count++; /* LOW = flame detected */
        if (i < TEST_CYCLES - 1) {
            gpioDelay(TEST_DELAY_US);
        }
    }

    if (flame_count == TEST_CYCLES) {
        log_event("Self-test failed: flame detected on all 5 samples");
        goto test_failed;
    }

    log_event("Self-test passed");

test_failed:
    /* Error indication: rapid LED blink + buzzer beep pattern */
    log_event("Error indication: rapid LED blink + buzzer pattern");
    for (int i = 0; i < 5; i++) {
        if (safe_write(LED_PIN, 1) < 0) break;
        gpioDelay(ERROR_BLINK_US);
        if (safe_write(LED_PIN, 0) < 0) break;
        gpioDelay(ERROR_BLINK_US);
    }

    /* Buzzer: short-short-long-short, repeated 3 times */
    for (int b = 0; b < ERROR_BEEP_COUNT; b++) {
        if (safe_write(BUZZER_PIN, 1) < 0) break;
        gpioDelay(ERROR_BEEP_US);
        if (safe_write(BUZZER_PIN, 0) < 0) break;
        gpioDelay(ERROR_BEEP_US);
        if (b < ERROR_BEEP_COUNT - 1) {
            if (safe_write(BUZZER_PIN, 1) < 0) break;
            gpioDelay(ERROR_BEEP_US);
