#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x5C
#define BH1750_CONT_HIGHRES 0x10
#define GPIO_LED 17
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL_US 1000000
#define MAX_LUX 1000.0f

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int bh1750_init(int fd) {
    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to set I2C slave address 0x%02X: %s\n",
                BH1750_ADDR, strerror(errno));
        return -1;
    }
    if (write(fd, (uint8_t[]){BH1750_CONT_HIGHRES}, 1) != 1) {
        fprintf(stderr, "Error: Failed to write measurement command to BH1750: %s\n",
                strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_read_lux(int fd, float *lux_out) {
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "Error: I2C read failed (got %zd bytes): %s\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void update_circular_buffer(float buffer[], int size, int index, float value) {
    buffer[index] = value;
}

static float calculate_average(float buffer[], int size) {
    float sum = 0.0f;
    for (int i = 0; i < size; i++) {
        sum += buffer[i];
    }
    return sum / (float)size;
}

static void control_led_blink(float lux) {
    float frequency = 0.5f + (lux / MAX_LUX) * 4.5f;
    if (frequency > 5.0f) frequency = 5.0f;
    if (frequency < 0.5f) frequency = 0.5f;

    float period_us = 1000000.0f / frequency;
    float half_period_us = period_us / 2.0f;

    gpioWrite(GPIO_LED, 1);
    gpioDelay((uint32_t)half_period_us);
    gpioWrite(GPIO_LED, 0);
    gpioDelay((uint32_t)half_period_us);
}

int main(void) {
    float lux_buffer[BUFFER_SIZE];
    int buffer_index = 0;
    int buffer_filled = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", GPIO_LED);
        gpioTerminate();
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (bh1750_init(i2c_fd) != 0) {
        fprintf(stderr, "Error: BH1750 initialisation failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    while (running) {
        float lux;
        if (bh1750_read_lux(i2c_fd, &lux) == 0) {
            update_circular_buffer(lux_buffer, BUFFER_SIZE, buffer_index, lux);
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
            if (buffer_filled < BUFFER_SIZE) buffer_filled++;

            float avg = calculate_average(lux_buffer, buffer_filled);
            printf("Lux: %.2f, Average: %.2f\n", lux, avg);
            control_led_blink(lux);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, skipping sample\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return 0;
}

