void shift_out(unsigned char data) {
    for (int i = 7; i >= 0; i--) {
        if (gpioWrite(DATA_PIN, (data >> i) & 1) < 0) {
            fprintf(stderr, "Error writing to DATA_PIN\n");
            keep_running = 0;
            return;
        }
        if (gpioWrite(CLOCK_PIN, 1) < 0) {
            fprintf(stderr, "Error writing to CLOCK_PIN\n");
            keep_running = 0;
            return;
        }
        gpioDelay(1); /* 1 us clock high */
        if (gpioWrite(CLOCK_PIN, 0) < 0) {
            fprintf(stderr, "Error writing to CLOCK_PIN\n");
            keep_running = 0;
            return;
        }
        gpioDelay(1); /* 1 us clock low */
    }
}

/* Latch data into the 74HC595 output registers */
void latch_data(void) {
    if (gpioWrite(LATCH_PIN, 1) < 0) {
        fprintf(stderr, "Error writing to LATCH_PIN\n");
        keep_running = 0;
        return;
    }
    gpioDelay(1); /* 1 us latch pulse */
    if (gpioWrite(LATCH_PIN, 0) < 0) {
        fprintf(stderr, "Error writing to LATCH_PIN\n");
        keep_running = 0;
        return;
    }
    gpioDelay(1);
}

/* Display a digit (0-9) on the seven-segment display */
void display_digit(int digit) {
    unsigned char pattern;
    switch (digit) {
        case 0: pattern = 0x3F; break;
        case 1: pattern = 0x06; break;
        case 2: pattern = 0x5B; break;
        case 3: pattern = 0x4F; break;
        case 4: pattern = 0x66; break;
        case 5: pattern = DIGIT_5_PATTERN; break;
        case 6: pattern = 0x6D; break;
        case 7: pattern = 0x7F; break;
        case 8: pattern = 0x79; break;
        case 9: pattern = 0x71; break;
        default: pattern = 0x00; break;
    }
    shift_out(pattern);
    latch_data();
}

int main(void) {
    /* Register signal handler for clean exit */
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Request GPIO pins as outputs */
    if (gpioSetMode(DATA_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting DATA_PIN as output\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(CLOCK_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting CLOCK_PIN as output\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LATCH_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting LATCH_PIN as output\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set initial output states */
    gpioWrite(DATA_PIN, 0);
    gpioWrite(CLOCK_PIN, 0);
    gpioWrite(LATCH_PIN, 0);

    /* Main loop: blink digit '5' repeatedly */
    while (keep_running) {
        display_digit(5);
        gpioDelay(500000); /* 500 ms on */
        if (!keep_running) break;
        gpioWrite(LATCH_PIN, 1);
        gpioDelay(1);
        gpioWrite(LATCH_PIN, 0);
        gpioDelay(500000); /* 500 ms off */
    }

    /* Clean up: ensure latch is low and release all pins */
    gpioWrite(LATCH_PIN, 0);
    gpioWrite(DATA_PIN, 0);
    gpioWrite(CLOCK_PIN, 0);
    gpioSetMode(DATA_PIN, PI_INPUT);
    gpioSetMode(CLOCK_PIN, PI_INPUT);
    gpioSetMode(LATCH_PIN, PI_INPUT);
    gpioTerminate();

    return EXIT_SUCCESS;
}

