/*
 * blink_button.c — Raspberry Pi GPIO17 LED blink with GPIO18 button interrupt.
 *
 * Build:  gcc -O2 -Wall -Wextra -o blink_button blink_button.c -lgpiod
 * Run:    ./blink_button
 *
 * Wiring (BCM numbering):
 *   GPIO17 (pin 11) — LED anode via ~330 Ω resistor; cathode to GND.
 *   GPIO18 (pin 12) — momentary push button to GND (internal pull-up).
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define LED_PIN    17
#define BUTTON_PIN 18
#define CHIP_NAME  "gpiochip0"

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    struct gpiod_line *button_line = NULL;
    struct gpiod_line_event event;
    struct timespec ts = { 1, 0 };   /* 1 s timeout for event wait */
    int ret;

    /* Install SIGINT handler for clean shutdown on Ctrl-C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the LED line (GPIO17) */
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line (LED)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Get the button line (GPIO18) */
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("gpiod_chip_get_line (button)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request LED line as output, initial value LOW */
    ret = gpiod_line_request_output(led_line, "blink_button", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (LED)");
        goto cleanup;
    }

    /* Request button line as input with pull-up and falling-edge events */
    ret = gpiod_line_request_input_flags(button_line, "blink_button",
                                          GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        perror("gpiod_line_request_input_flags (button)");
        goto cleanup;
    }

    ret = gpiod_line_request_falling_edge_events(button_line, "blink_button");
    if (ret < 0) {
        perror("gpiod_line_request_falling_edge_events");
        goto cleanup;
    }

    printf("Blinking LED on GPIO%d. Press button on GPIO%d to exit.\n",
           LED_PIN, BUTTON_PIN);
    fflush(stdout);

    /* Main blink loop */
    while (g_running) {
        ret = gpiod_line_set_value(led_line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (LED on)");
            break;
        }
        nanosleep(&ts, NULL);

        if (!g_running)
            break;

        ret = gpiod_line_set_value(led_line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (LED off)");
            break;
        }
        nanosleep(&ts, NULL);
    }

    /* Wait for button press with 1 s timeout */
    ret = gpiod_line_event_wait(button_line, &((struct timespec){1, 0}));
    if (ret < 0) {
        perror("gpiod_line_event_wait");
        goto cleanup;
    }
    if (ret == 0) {
        /* Timeout — loop exited via g_running */
        goto cleanup;
    }

    /* Read the event to clear it */
    ret = gpiod_line_event_read(button_line, &event);
    if (ret < 0) {
        perror("gpiod_line_event_read");
        goto cleanup;
    }

    printf("\nButton pressed! Exiting.\n");
    fflush(stdout);

    /* Ensure LED is off before releasing */
    gpiod_line_set_value(led_line, 0);

cleanup:
    if (led_line)
        gpiod_line_release(led_line);
    if (button_line)
        gpiod_line_release(button_line);
    if (chip)
        gpiod_chip_close(chip);

    return (ret < 0) ? EXIT_FAILURE : EXIT_SUCCESS;
}

