#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LED_PIN 5
#define DELAY_MS 750

static volatile sig_atomic_t running = 1;

static void sigint_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Set GPIO5 as output */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure LED is off at start */
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Failed to write to GPIO%d\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("LED OFF\n");
    fflush(stdout);

    while (running) {
        /* Turn LED on */
        if (gpioWrite(LED_PIN, 1) != 0) {
            fprintf(stderr, "Failed to write to GPIO%d\n", LED_PIN);
            break;
        }
        printf("LED ON\n");
        fflush(stdout);

        /* Wait 750 ms (pigpio delay is in microseconds) */
        gpioDelay(DELAY_MS * 1000);

        /* Turn LED off */
        if (gpioWrite(LED_PIN, 0) != 0) {
            fprintf(stderr, "Failed to write to GPIO%d\n", LED_PIN);
            break;
        }
        printf("LED OFF\n");
        fflush(stdout);

        /* Wait 750 ms more */
        gpioDelay(DELAY_MS * 1000);
    }

    /* Clean up: turn LED off and release resources */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();

    printf("LED OFF (final)\n");
    fflush(stdout);

    return EXIT_SUCCESS;
}

