#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LED_PIN    24
#define BUTTON_PIN 22
#define BLINK_US   500000  /* 500 ms */

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int setup_gpio(void)
{
    int rc;

    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", rc);
        return -1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", BUTTON_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: failed to set pull-down on GPIO%d.\n", BUTTON_PIN);
        /* Non-fatal: internal pull-down is not strictly required if the
           external 10 kΩ resistor is present. */
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED state on GPIO%d.\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    /* Best-effort cleanup; ignore return values during shutdown. */
    (void)gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Press and hold the button (GPIO%d) to blink the LED (GPIO%d).\n",
           BUTTON_PIN, LED_PIN);
    printf("Press Ctrl-C to exit.\n");
    fflush(stdout);

    while (running) {
        int button_state = gpioRead(BUTTON_PIN);
        if (button_state < 0) {
            fprintf(stderr, "Error: failed to read GPIO%d.\n", BUTTON_PIN);
            break;
        }

        if (button_state == 1) {
            if (gpioWrite(LED_PIN, 1) != 0) {
                fprintf(stderr, "Error: failed to turn LED on (GPIO%d).\n", LED_PIN);
                break;
            }
            gpioDelay(BLINK_US);
            if (!running) break;

            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "Error: failed to turn LED off (GPIO%d).\n", LED_PIN);
                break;
            }
            gpioDelay(BLINK_US);
        } else {
            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "Error: failed to keep LED off (GPIO%d).\n", LED_PIN);
                break;
            }
            gpioDelay(10000);  /* 10 ms idle poll */
        }
    }

    cleanup_gpio();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

