#define RED_PIN   24
#define GREEN_PIN 23
#define BLUE_PIN  18

#define PWM_PERIOD_NS 10000000  /* 10 ms = 100 Hz */
#define PWM_STEP_NS   10000     /* 10 µs per step */
#define COLOR_CHANGE_MS 100

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_line(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int pwm_step(unsigned pin, int intensity)
{
    if (intensity < 0) intensity = 0;
    if (intensity > 100) intensity = 100;

    unsigned duty = (unsigned)(intensity * 1000000 / 100);  /* 0..1000000 */
    unsigned pulse = duty + (PWM_PERIOD_NS / 2);             /* centre-aligned */

    if (gpioPWM(pin, pulse) != 0) {
        fprintf(stderr, "Error: gpioPWM(%u, %u) failed\n", pin, pulse);
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (set_line(RED_PIN, PI_OUTPUT) != 0 ||
        set_line(GREEN_PIN, PI_OUTPUT) != 0 ||
        set_line(BLUE_PIN, PI_OUTPUT) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n", strerror(errno));
    }

    srand((unsigned)time(NULL));

    int red_intensity   = 0;
    int green_intensity = 0;
    int blue_intensity  = 0;

    while (g_running) {
        int new_red   = rand() % 101;
        int new_green = rand() % 101;
        int new_blue  = rand() % 101;

        if (new_red == red_intensity && new_green == green_intensity && new_blue == blue_intensity) {
            /* No change — advance PWM loop without re-setting intensities */
            struct timespec ts = { 0, PWM_STEP_NS };
            continue;
        }

        red_intensity   = new_red;
        green_intensity = new_green;
        blue_intensity  = new_blue;

        /* Change colour every 100 ms */
        struct timespec change_ts = { 0, (long)COLOR_CHANGE_MS * 1000000L };
        nanosleep(&change_ts, NULL);

        /* Busy-wait PWM loop: 10 ms period, 10 µs per step */
        struct timespec pwm_ts = { 0, PWM_STEP_NS };
        while (g_running) {
            if (pwm_step(RED_PIN, red_intensity)   != 0) break;
            if (pwm_step(GREEN_PIN, green_intensity) != 0) break;
            if (pwm_step(BLUE_PIN, blue_intensity)  != 0) break;
            nanosleep(&pwm_ts, NULL);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

