#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* LSM303DLHC accelerometer I2C address (SA0 tied to VDD) */
#define LSM303_ACCEL_ADDR 0x19

/* LSM303DLHC accelerometer register addresses */
#define LSM303_ACCEL_CTRL_REG1_A 0x20
#define LSM303_ACCEL_OUT_X_L_A   0x28

/* GPIO pin for impact interrupt (BCM numbering) */
#define IMPACT_GPIO 17

/* Default impact threshold (in G) */
#define DEFAULT_IMPACT_THRESHOLD 2.0f

/* Global variables */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;
static float impact_threshold = DEFAULT_IMPACT_THRESHOLD;

/* Structure to hold accelerometer data */
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

/* Function prototypes */
static int initialize_i2c(void);
static int initialize_gpio(void);
static int read_accelerometer_data(accelerometer_data_t *data);
static float calculate_magnitude(const accelerometer_data_t *data);
static void trigger_impact_interrupt(void);
static void log_data(const accelerometer_data_t *data, float magnitude);
static void signal_handler(int signal);
static void cleanup(void);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    /* Ensure GPIO is left in a safe state */
    gpioWrite(IMPACT_GPIO, 0);
    gpioSetMode(IMPACT_GPIO, PI_INPUT);
    gpioTerminate();
}

/* Initializes the I2C interface */
static int initialize_i2c(void) {
    i2c_handle = i2cOpen(1, LSM303_ACCEL_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X: %d\n",
                LSM303_ACCEL_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

/* Initializes the GPIO pin for the impact interrupt */
static int initialize_gpio(void) {
    if (gpioSetMode(IMPACT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", IMPACT_GPIO);
        return -1;
    }
    if (gpioWrite(IMPACT_GPIO, 0) != 0) {
        fprintf(stderr, "Error initializing GPIO %d to LOW\n", IMPACT_GPIO);
        return -1;
    }
    return 0;
}

/* Reads raw accelerometer data from the LSM303DLHC */
static int read_accelerometer_data(accelerometer_data_t *data) {
    char buffer[6];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, LSM303_ACCEL_OUT_X_L_A, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading accelerometer data: %d\n", result);
        return -1;
    }

    /* LSM303DLHC accelerometer: little-endian, 16-bit, two's complement */
    data->x = (int16_t)((buffer[1] << 8) | (uint8_t)buffer[0]);
    data->y = (int16_t)((buffer[3] << 8) | (uint8_t)buffer[2]);
    data->z = (int16_t)((buffer[5] << 8) | (uint8_t)buffer[4]);

    return 0;
}

/* Calculates the magnitude of the acceleration vector in G */
static float calculate_magnitude(const accelerometer_data_t *data) {
    float x = (float)data->x;
    float y = (float)data->y;
    float z = (float)data->z;
    return sqrtf(x * x + y * y + z * z);
}

/* Triggers the impact interrupt by pulsing the GPIO pin */
static void trigger_impact_interrupt(void) {
    gpioWrite(IMPACT_GPIO, 1);
    gpioDelay(50000); /* 50 ms in microseconds */
    gpioWrite(IMPACT_GPIO, 0);
}

/* Logs the accelerometer data to a file */
static void log_data(const accelerometer_data_t *data, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d, Magnitude: %.2f G\n",
            timestamp, data->x, data->y, data->z, magnitude);
    fflush(log_file);
}

int main(int argc, char *argv[]) {
    int opt;

    /* Parse command-line arguments */
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                impact_threshold = atof(optarg);
                if (impact_threshold <= 0.0f) {
                    fprintf(stderr, "Invalid threshold value. Using default: %.2f G\n",
                            DEFAULT_IMPACT_THRESHOLD);
                    impact_threshold = DEFAULT_IMPACT_THRESHOLD;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (initialize_gpio() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open the log file */
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set up signal handling */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Impact detection started. Threshold: %.2f G\n", impact_threshold);
    printf("Press Ctrl+C to exit.\n");

    /* Main loop */
    while (program_running) {
        accelerometer_data_t data;

        if (read_accelerometer_data(&data) == 0) {
            float magnitude = calculate_magnitude(&data);

            if (magnitude > impact_threshold) {
                trigger_impact_interrupt();
                log_data(&data, magnitude);
            }
        } else {
            fprintf(stderr, "Error reading accelerometer data. Retrying...\n");
        }

        gpioDelay(100000); /* 100 ms delay (10 Hz polling rate) */
    }

    /* Cleanup */
    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

