#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define LED_GPIO 18
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define SAMPLE_INTERVAL_US 500000
#define RETRY_DELAY_US 100000

#define REG_ALS_LSB 0x00
#define REG_ALS_MSB 0x01
#define REG_RED_LSB 0x02
#define REG_RED_MSB 0x03
#define REG_GREEN_LSB 0x04
#define REG_GREEN_MSB 0x05
#define REG_BLUE_LSB 0x06
#define REG_BLUE_MSB 0x07
#define REG_CONFIG 0x08

#define CONFIG_DEFAULT 0x00

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_reg(uint8_t reg, uint8_t value) {
    char buf[2] = {(char)reg, (char)value};
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error: I2C write to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *value) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 0) {
        fprintf(stderr, "Error: I2C write (reg select 0x%02X) failed\n", reg);
        return -1;
    }
    char data_buf[1];
    if (i2cReadDevice(i2c_handle, data_buf, 1) != 1) {
        fprintf(stderr, "Error: I2C read from reg 0x%02X failed\n", reg);
        return -1;
    }
    *value = (uint8_t)data_buf[0];
    return 0;
}

static int read_sensor_data(uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t als_lsb, als_msb, red_lsb, red_msb, green_lsb, green_msb, blue_lsb, blue_msb;

    if (i2c_read_reg(REG_ALS_LSB, &als_lsb) != 0) return -1;
    if (i2c_read_reg(REG_ALS_MSB, &als_msb) != 0) return -1;
    if (i2c_read_reg(REG_RED_LSB, &red_lsb) != 0) return -1;
    if (i2c_read_reg(REG_RED_MSB, &red_msb) != 0) return -1;
    if (i2c_read_reg(REG_GREEN_LSB, &green_lsb) != 0) return -1;
    if (i2c_read_reg(REG_GREEN_MSB, &green_msb) != 0) return -1;
    if (i2c_read_reg(REG_BLUE_LSB, &blue_lsb) != 0) return -1;
    if (i2c_read_reg(REG_BLUE_MSB, &blue_msb) != 0) return -1;

    *als = ((uint16_t)als_msb << 8) | als_lsb;
    *red = ((uint16_t)red_msb << 8) | red_lsb;
    *green = ((uint16_t)green_msb << 8) | green_lsb;
    *blue = ((uint16_t)blue_msb << 8) | blue_lsb;
    return 0;
}

static int log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, als, red, green, blue) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

