#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* FXOS8700CQ I2C address (SA0 tied to VDD on Adafruit breakout) */
#define FXOS8700_ADDRESS 0x53

/* FXOS8700CQ register addresses */
#define FXOS8700_WHO_AM_I   0x0D
#define FXOS8700_CTRL_REG1  0x2A
#define FXOS8700_CTRL_REG2  0x2B
#define FXOS8700_XYZ_DATA_CFG 0x0E
#define FXOS8700_OUT_X_MSB  0x01
#define FXOS8700_M_OUT_MSB  0x33

/* Expected WHO_AM_I value for FXOS8700CQ */
#define FXOS8700_WHO_AM_I_VAL 0xC7

/* Impact threshold magnitude (g) */
#define IMPACT_THRESHOLD 2.0

/* Sampling interval (microseconds) */
#define SAMPLE_INTERVAL_US 50000

/* Globals for signal-safe cleanup */
static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Read a single byte from an FXOS8700 register; returns -1 on error */
static int fxos_read_reg(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error on reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

/* Write a single byte to an FXOS8700 register; returns -1 on error */
static int fxos_write_reg(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write error on reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

/* Read a 6-byte block starting at OUT_X_MSB; returns -1 on error */
static int fxos_read_block(int handle, uint8_t reg, uint8_t *buf, int len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != len) {
        fprintf(stderr, "I2C block read error on reg 0x%02X: got %d, expected %d\n",
                reg, rc, len);
        return -1;
    }
    return 0;
}

/* Initialize the FXOS8700CQ: verify WHO_AM_I, configure standby, range, ODR, then activate */
static int fxos8700_init(int handle) {
    uint8_t who_am_i = 0;

    if (fxos_read_reg(handle, FXOS8700_WHO_AM_I, &who_am_i) < 0) {
        return -1;
    }

    if (who_am_i != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode: clear ACTIVE bit in CTRL_REG1 */
    if (fxos_write_reg(handle, FXOS8700_CTRL_REG1, 0x00) < 0) {
        return -1;
    }

    /* Set range to +/-2g (FS=0) */
    if (fxos_write_reg(handle, FXOS8700_XYZ_DATA_CFG, 0x00) < 0) {
        return -1;
    }

    /* 200 Hz output data rate (ODR=0100) */
    if (fxos_write_reg(handle, FXOS8700_CTRL_REG2, 0x02) < 0) {
        return -1;
    }

    /* Activate: set ACTIVE bit in CTRL_REG1 */
    if (fxos_write_reg(handle, FXOS8700_CTRL_REG1, 0x01) < 0) {
        return -1;
    }

    return 0;
}

/* Read acceleration data; returns -1 on error */
static int fxos8700_read_accel(int handle, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];

    if (fxos_read_block(handle, FXOS8700_OUT_X_MSB, buf, 6) < 0) {
        return -1;
    }

    /* FXOS8700CQ is left-justified: 14-bit data in 16-bit fields */
    *x = (int16_t)((buf[0] << 8) | buf[1]) >> 2;
    *y = (int16_t)((buf[2] << 8) | buf[3]) >> 2;
    *z = (int16_t)((buf[4] << 8) | buf[5]) >> 2;

    return 0;
}

/* Compute magnitude of acceleration vector */
static double compute_magnitude(int16_t x, int16_t y, int16_t z) {
    double fx = (double)x;
    double fy = (double)y;
    double fz = (double)z;
    return sqrt(fx * fx + fy * fy + fz * fz);
}

/* Append impact event to log file */
static void log_impact(int16_t x, int16_t y, int16_t z, double mag) {
    FILE *fp = fopen("impact_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening impact_log.txt for appending\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%d,%d,%d,%.3f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                x, y, z, mag);
    } else {
        fprintf(fp, "timestamp_error,%d,%d,%d,%.3f\n", x, y, z, mag);
    }

    fclose(fp);
}

int main(void) {
    int16_t x = 0, y = 0, z = 0;
    double mag = 0.0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at FXOS8700 address */
    i2c_handle = i2cOpen(1, FXOS8700_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (fxos8700_init(i2c_handle) < 0) {
        fprintf(stderr, "FXOS8700 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("Impact detection started. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (running) {
        if (fxos8700_read_accel(i2c_handle, &x, &y, &z) == 0) {
            mag = compute_magnitude(x, y, z);

            if (mag > IMPACT_THRESHOLD) {
                log_impact(x, y, z, mag);
                printf("Impact detected! Magnitude: %.3f g\n", mag);
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Graceful cleanup */
    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

