/*
 * GY-50 L3G4200D Gyroscope Logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   GY-50 VCC  -> Pi 3V3 (Pin 1)
 *   GY-50 GND  -> Pi GND (Pin 9)
 *   GY-50 SDA  -> Pi GPIO2 / I2C bus 1 SDA (Pin 3)
 *   GY-50 SCL  -> Pi GPIO3 / I2C bus 1 SCL (Pin 5)
 *
 * Build:  gcc -O2 -Wall -o gyro_logger gyro_logger.c -lm
 * Run:    ./gyro_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- L3G4200D constants (verified against STM L3G4200D datasheet) ---- */
#define L3G4200D_ADDRESS          0x29
#define L3G4200D_WHO_AM_I         0x0F
#define L3G4200D_WHO_AM_I_VAL     0xD3
#define L3G4200D_CTRL_REG1        0x20
#define L3G4200D_CTRL_REG4        0x23
#define L3G4200D_OUT_X_L          0x28
#define L3G4200D_OUT_X_H          0x29
#define L3G4200D_OUT_Y_L          0x2A
#define L3G4200D_OUT_Y_H          0x2B
#define L3G4200D_OUT_Z_L          0x2C
#define L3G4200D_OUT_Z_H          0x2D

#define I2C_BUS                   "/dev/i2c-1"
#define LOG_FILE                  "gyro_log.txt"
#define SAMPLE_PERIOD_MS          50
#define ALERT_THRESHOLD_DPS       50.0f
#define CALIBRATION_SAMPLES       100
#define GYRO_SENSITIVITY_245_DPS  0.00875f   /* LSB/dps at FS = 245 dps */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C burst write (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int gyro_init(int fd)
{
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, L3G4200D_WHO_AM_I, &who_am_i) != 0)
        return -1;

    if (who_am_i != L3G4200D_WHO_AM_I_VAL) {
        fprintf(stderr,
                "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X "
                "(sensor absent or wrong device).\n",
                who_am_i, L3G4200D_WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL_REG1: ODR = 100 Hz (0x0F) */
    if (i2c_write_reg8(fd, L3G4200D_CTRL_REG1, 0x0F) != 0)
        return -1;

    /* CTRL_REG4: FS = 245 dps (0x80), High-resolution mode (0x08) -> 0x88 */
    if (i2c_write_reg8(fd, L3G4200D_CTRL_REG4, 0x88) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_gyro_data(int fd, float *x, float *y, float *z)
{
    uint8_t raw[6];
    if (i2c_read_burst(fd, L3G4200D_OUT_X_L, raw, sizeof(raw)) != 0)
        return -1;

    int16_t x_raw = (int16_t)((raw[1] << 8) | raw[0]);
    int16_t y_raw = (int16_t)((raw[3] << 8) | raw[2]);
    int16_t z_raw = (int16_t)((raw[5] << 8) | raw[4]);

    *x = (float)x_raw * GYRO_SENSITIVITY_245_DPS;
    *y = (float)y_raw * GYRO_SENSITIVITY_245_DPS;
    *z = (float)z_raw * GYRO_SENSITIVITY_245_DPS;
    return 0;
}

/* ------------------------------------------------------------------ */
static int calibrate_gyro(int fd, float *x_off, float *y_off, float *z_off)
{
    float x_sum = 0.0f, y_sum = 0.0f, z_sum = 0.0f;
    float x, y, z;

    printf("Calibrating gyroscope (keep sensor stationary)...\n");

    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        if (read_gyro_data(fd, &x, &y, &z) != 0) {
            fprintf(stderr, "Calibration read failed at sample %d\n", i);
            return -1;
        }
        x_sum += x;
        y_sum += y;
        z_sum += z;
        usleep(1000);
    }

    *x_off = x_sum / (float)CALIBRATION_SAMPLES;
    *y_off = y_sum / (float)CALIBRATION_SAMPLES;
    *z_off = z_sum / (float)CALIBRATION_SAMPLES;

    printf("Calibration complete. Offsets: X=%.2f, Y=%.2f, Z=%.2f dps\n",
           *x_off, *y_off, *z_off);
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float x, float y, float z, float x_off,
                     float y_off, float z_off)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    fprintf(fp, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            ts, x, y, z, x_off, y_off, z_off);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void check_alert(float x, float y, float z, float x_off,
                        float y_off, float z_off)
{
    if (fabsf(x) > ALERT_THRESHOLD_DPS)
        fprintf(stderr, "ALERT: X-axis angular velocity exceeds %.0f dps "
                        "(%.2f dps)\n", ALERT_THRESHOLD_DPS, x);
    if (fabsf(y) > ALERT_THRESHOLD_DPS)
        fprintf(stderr, "ALERT: Y-axis angular velocity exceeds %.0f dps "
                        "(%.2f dps)\n", ALERT_THRESHOLD_DPS, y);
    if (fabsf(z) > ALERT_THRESHOLD_DPS)
        fprintf(stderr, "ALERT: Z-axis angular velocity exceeds %.0f dps "
                        "(%.2f dps)\n", ALERT_THRESHOLD_DPS, z);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, L3G4200D_ADDRESS) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                L3G4200D_ADDRESS, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gyro_init(g_i2c_fd) != 0) {
        fprintf(stderr, "Gyroscope initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    float x_off = 0.0f, y_off = 0.0f, z_off = 0.0f;
    if (calibrate_gyro(g_i2c_fd, &x_off, &y_off, &z_off) != 0) {
        fprintf(stderr, "Calibration failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging to %s at 20 Hz. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        float x, y, z;

        if (read_gyro_data(g_i2c_fd, &x, &y, &z) != 0) {
            fprintf(stderr, "Read error, continuing...\n");
            usleep(SAMPLE_PERIOD_MS * 1000);
            continue;
        }

        x -= x_off;
        y -= y_off;
        z -= z_off;

        log_data(g_log_fp, x, y, z, x_off, y_off, z_off);
        check_alert(x, y, z, x_off, y_off, z_off);

        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

