#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

/* ADXL345 I2C address (ALT ADDRESS tied to GND) */
#define ADXL345_ADDRESS 0x53

/* ADXL345 registers */
#define ADXL345_DEVID       0x00
#define ADXL345_POWER_CTL   0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0      0x32

/* Expected device ID */
#define ADXL345_DEVID_VAL   0xE5

/* GPIO pin for LED (BCM numbering) */
#define LED_PIN 17

/* Sampling interval in microseconds (100 ms) */
#define SAMPLE_INTERVAL_US 100000

/* Full-resolution sensitivity for ±2 g range: 4 mg/LSB */
#define FULL_RES_SENSITIVITY 0.004f

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %d\n",
                reg, value, rc);
    }
    return rc;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %d\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* ADXL345 initialization                                              */
/* ------------------------------------------------------------------ */
static int adxl345_init(int handle)
{
    uint8_t devid = 0;

    /* Read and verify device ID */
    if (i2c_read_byte(handle, ADXL345_DEVID, &devid) != 0) {
        fprintf(stderr, "Cannot read DEVID register.\n");
        return -1;
    }
    if (devid != ADXL345_DEVID_VAL) {
        fprintf(stderr, "Unexpected DEVID: 0x%02X (expected 0x%02X). "
                        "Wrong device or wiring?\n",
                devid, ADXL345_DEVID_VAL);
        return -1;
    }

    /* Standby mode to allow configuration changes */
    if (i2c_write_byte(handle, ADXL345_POWER_CTL, 0x00) < 0)
        return -1;

    /* Full resolution, ±2 g range (0x0B) */
    if (i2c_write_byte(handle, ADXL345_DATA_FORMAT, 0x0B) < 0)
        return -1;

    /* Measurement mode */
    if (i2c_write_byte(handle, ADXL345_POWER_CTL, 0x08) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read acceleration in g                                              */
/* ------------------------------------------------------------------ */
static int read_acceleration(int handle, float *x, float *y, float *z)
{
    uint8_t x_raw = 0, y_raw = 0, z_raw = 0;

    if (i2c_read_byte(handle, ADXL345_DATAX0, &x_raw) != 0)
        return -1;
    if (i2c_read_byte(handle, ADXL345_DATAY1, &y_raw) != 0)
        return -1;
    if (i2c_read_byte(handle, ADXL345_DATAZ2, &z_raw) != 0)
        return -1;

    /* Left-justified two's complement: shift right 4 to get signed 12-bit */
    int16_t x_signed = (int16_t)((x_raw << 8) | 0x00) >> 4;
    int16_t y_signed = (int16_t)((y_raw << 8) | 0x00) >> 4;
    int16_t z_signed = (int16_t)((z_raw << 8) | 0x00) >> 4;

    *x = (float)x_signed * FULL_RES_SENSITIVITY;
    *y = (float)y_signed * FULL_RES_SENSITIVITY;
    *z = (float)z_signed * FULL_RES_SENSITIVITY;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log data to file                                                    */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float x, float y, float z)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Threshold LED control                                               */
/* ------------------------------------------------------------------ */
static void control_led(float x, float y, float z)
{
    bool exceed = (fabsf(x) > 2.0f || fabsf(y) > 2.0f || fabsf(z) > 2.0f);
    gpioWrite(LED_PIN, exceed ? 1 : 0);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at ADXL345 address */
    g_i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
