/*
 * GY-51 LSM303DLHC compass logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   LSM303DLHC SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   LSM303DLHC SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   LSM303DLHC VDD  -> 3.3 V
 *   LSM303DLHC GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o compass compass.c -lm -lrt -lpigpio -lrt
 *   (pigpio must be installed; run as root or with appropriate gpio permissions)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- LSM303DLHC I2C addresses ---- */
#define LSM303_ACCEL_ADDR 0x19
#define LSM303_MAG_ADDR   0x1E

/* ---- LSM303DLHC register addresses ---- */
#define LSM303_ACCEL_CTRL_REG1_A 0x20
#define LSM303_ACCEL_OUT_X_L_A   0x28
#define LSM303_MAG_MR_REG_M      0x02
#define LSM303_MAG_OUT_X_H_M     0x03

/* ---- Scaling factors ---- */
#define ACCEL_SCALE 0.000244f   /* 1 mg / LSB -> g */
#define MAG_SCALE   0.00014f    /* 1 mgauss / LSB -> gauss */

#define I2C_BUS 1
#define SAMPLE_PERIOD_US 100000 /* 100 ms */
#define LOG_FILE "compass_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_accel = -1;
static int g_i2c_mag   = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_accel >= 0) {
        i2cClose(g_i2c_accel);
        g_i2c_accel = -1;
    }
    if (g_i2c_mag >= 0) {
        i2cClose(g_i2c_mag);
        g_i2c_mag = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
static int init_accelerometer(void)
{
    /* CTRL_REG1_A: 100 Hz ODR, all axes enabled, normal mode */
    if (i2cWriteByteData(g_i2c_accel, LSM303_ACCEL_CTRL_REG1_A, 0x57) < 0) {
        fprintf(stderr, "Error: failed to write accelerometer CTRL_REG1_A\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_magnetometer(void)
{
    /* MR_REG_M: temperature sensor enabled, 10 Hz ODR, high performance */
    if (i2cWriteByteData(g_i2c_mag, LSM303_MAG_MR_REG_M, 0x14) < 0) {
        fprintf(stderr, "Error: failed to write magnetometer MR_REG_M\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_accelerometer(float *x, float *y, float *z)
{
    char buffer[6];

    if (i2cReadI2CBlockData(g_i2c_accel, LSM303_ACCEL_OUT_X_L_A | 0x80,
                            buffer, 6) != 6) {
        fprintf(stderr, "Error: failed to read accelerometer data\n");
        return -1;
    }

    int16_t raw_x = (int16_t)((buffer[1] << 8) | (uint8_t)buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | (uint8_t)buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | (uint8_t)buffer[4]);

    *x = (float)raw_x * ACCEL_SCALE;
    *y = (float)raw_y * ACCEL_SCALE;
    *z = (float)raw_z * ACCEL_SCALE;
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_magnetometer(float *x, float *y, float *z)
{
    char buffer[6];

    if (i2cReadI2CBlockData(g_i2c_mag, LSM303_MAG_OUT_X_H_M,
                            buffer, 6) != 6) {
        fprintf(stderr, "Error: failed to read magnetometer data\n");
        return -1;
    }

    int16_t raw_x = (int16_t)((buffer[0] << 8) | (uint8_t)buffer[1]);
    int16_t raw_z = (int16_t)((buffer[2] << 8) | (uint8_t)buffer[3]);
    int16_t raw_y = (int16_t)((buffer[4] << 8) | (uint8_t)buffer[5]);

    *x = (float)raw_x * MAG_SCALE;
    *y = (float)raw_y * MAG_SCALE;
    *z = (float)raw_z * MAG_SCALE;
    return 0;
}

/* ------------------------------------------------------------------ */
static float calculate_heading(float ax, float ay, float az,
                               float mx, float my, float mz)
{
    /* Tilt-compensated heading: ignore vertical components */
    float pitch = atan2f(ay, az);
    float roll  = atan2f(ax, sqrtf(ay * ay + az * az));

    float cos_pitch = cosf(pitch);
    float cos_roll  = cosf(roll);

    float x_h = mx * cos_pitch + mz * cos_roll * sin_pitch - my * sin_roll * sin_pitch;
    float y_h = mx * sin_pitch + mz * cos_roll * cos_pitch + my * sin_roll * cos_pitch;

    float heading = atan2f(y_h, x_h) * 180.0f / (float)M_PI;
    if (heading < 0.0f)
        heading += 360.0f;
    return heading;
}

/* ------------------------------------------------------------------ */
static int log_data(float heading, float ax, float ay, float az,
                    float mx, float my, float mz)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s for appending\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            heading, ax, ay, az, mx, my, mz);

    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_accel = i2cOpen(I2C_BUS, LSM303_ACCEL_ADDR, 0);
    if (g_i2c_accel < 0) {
        fprintf(stderr, "Error: cannot open I2C bus %d at address 0x%02X (code %d)\n",
                I2C_BUS, LSM303_ACCEL_ADDR, g_i2c_accel);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_i2c_mag = i2cOpen(I2C_BUS, LSM303_MAG_ADDR, 0);
    if (g_i2c_mag < 0) {
        fprintf(stderr, "Error: cannot open I2C bus %d at address 0x%02X (code %d)\n",
                I2C_BUS, LSM303_MAG_ADDR, g_i2c_mag);
        i2cClose(g_i2c_accel);
        g_i2c_accel = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_accelerometer() != 0 || init_magnetometer() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is new/empty */
    {
        FILE *fp = fopen(LOG_FILE, "r");
        if (!fp) {
            fp = fopen(LOG_FILE, "w");
            if (fp) {
                fprintf(fp, "timestamp,heading_deg,accel_x_g,accel_y_g,accel_z_g,"
                                "mag_x_gauss,mag_y_gauss,mag_z_gauss\n");
                fclose(fp);
            } else {
                fprintf(stderr, "Warning: cannot create %s\n", LOG_FILE);
            }
        } else {
            fclose(fp);
        }
    }

    printf("Compass logger started. Logging to %s every 100 ms. Press Ctrl+C to stop.\n",
           LOG_FILE);

    while (g_running) {
        float ax, ay, az, mx, my, mz;

        if (read_accelerometer(&ax, &ay, &az) != 0) {
            fprintf(stderr, "Warning: accelerometer read failed, skipping sample\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        if (read_magnetometer(&mx, &my, &mz) != 0) {
            fprintf(stderr, "Warning: magnetometer read failed, skipping sample\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float heading = calculate_heading(ax, ay, az, mx, my, mz);

        if (log_data(heading, ax, ay, az, mx, my, mz) != 0) {
            fprintf(stderr, "Warning: logging failed for this sample\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

