/*
 * VL6180X Time-of-Flight distance sensor reader for Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   VL6180X SDA -> GPIO2 (pin 3, I2C bus 1 SDA)
 *   VL6180X SCL -> GPIO3 (pin 5, I2C bus 1 SCL)
 *   VL6180X VDD -> 3.3 V
 *   VL6180X GND -> GND
 *
 * Build:  gcc -O2 -Wall -o vl6180x_door vl6180x_door.c -lpigpio -lrt
 * Run:    sudo ./vl6180x_door
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- VL6180X register map (subset) ---- */
#define VL6180X_REG_IDENTIFICATION_MODEL_ID    0x000
#define VL6180X_REG_SYSTEM_FRESH_OUT_OF_RESET  0x016
#define VL6180X_REG_SYSRANGE_START             0x018
#define VL6180X_REG_RESULT_RANGE_VAL           0x062
#define VL6180X_REG_RESULT_INTERRUPT_STATUS    0x04F
#define VL6180X_REG_RESULT_INTERRUPT_CLEAR     0x015

#define VL6180X_I2C_ADDR                      0x29
#define VL6180X_MODEL_ID                      0xB4
#define VL6180X_RESET_CMD                     0x01

#define I2C_BUS                               1
#define SAMPLE_PERIOD_US                     100000   /* 100 ms */
#define DOOR_THRESHOLD_MM                    100
#define LOG_FILE                             "distance_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[I2C] write 0x%02X <- 0x%02X failed (pigpio rc=%d)\n",
                reg, value, rc);
    }
    return rc;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[I2C] read 0x%02X failed (pigpio rc=%d)\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

static int i2c_read_word(int handle, uint8_t reg, uint16_t *out)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[I2C] read 0x%02X failed (pigpio rc=%d)\n", reg, rc);
        return -1;
    }
    *out = (uint16_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* VL6180X initialization                                              */
/* ------------------------------------------------------------------ */
static int vl6180x_init(int handle)
{
    uint8_t model_id = 0;

    /* 1. Verify sensor identity */
    if (i2c_read_byte(handle, VL6180X_REG_IDENTIFICATION_MODEL_ID, &model_id) < 0)
        return -1;

    if (model_id != VL6180X_MODEL_ID) {
        fprintf(stderr,
                "[VL6180X] Model ID mismatch: got 0x%02X, expected 0x%02X "
                "(sensor absent or wrong device)\n",
                model_id, VL6180X_MODEL_ID);
        return -1;
    }

    /* 2. Mandatory reset */
    if (i2c_write_byte(handle, VL6180X_REG_SYSTEM_FRESH_OUT_OF_RESET,
                       VL6180X_RESET_CMD) < 0)
        return -1;

    /* 3. Wait for reset to complete (max ~10 ms) */
    gpioDelay(10000);

    /* 4. Mandatory register configuration (excerpt from ST datasheet) */
    struct {
        uint8_t reg;
        uint8_t val;
    } cfg[] = {
        {0x020, 0x01}, {0x021, 0x02}, {0x022, 0x01}, {0x024, 0x01},
        {0x025, 0x00}, {0x026, 0x07}, {0x027, 0x01}, {0x028, 0x00},
        {0x029, 0x00}, {0x031, 0xFF}, {0x032, 0x00}, {0x033, 0x00},
        {0x035, 0x00}, {0x036, 0x00}, {0x037, 0xFD}, {0x038, 0x00},
        {0x039, 0x00}, {0x040, 0x00}, {0x041, 0x00}, {0x042, 0x00},
        {0x043, 0x00}, {0x044, 0x00}, {0x045, 0x00}, {0x046, 0x00},
        {0x047, 0x00}, {0x048, 0x00}, {0x049, 0x00}, {0x050, 0x00},
        {0x051, 0x00}, {0x052, 0x00}, {0x053, 0x00}, {0x054, 0x00},
        {0x055, 0x00}, {0x056, 0x00}, {0x057, 0x00}, {0x058, 0x00},
        {0x059, 0x00}, {0x060, 0x00}, {0x061, 0x00}, {0x062, 0x00},
        {0x063, 0x00}, {0x064, 0x00}, {0x065, 0x00}, {0x066, 0x00},
        {0x067, 0x00}, {0x068, 0x00}, {0x069, 0x00}, {0x070, 0x00},
        {0x071, 0x00}, {0x072, 0x00}, {0x073, 0x00}, {0x074, 0x00},
        {0x075, 0x00}, {0x076, 0x00}, {0x077, 0x00}, {0x078, 0x00},
        {0x079, 0x00}, {0x080, 0x00}, {0x081, 0x00}, {0x082, 0x00},
        {0x083, 0x00}, {0x084, 0x00}, {0x085, 0x00}, {0x086, 0x00},
        {0x087, 0x00}, {0x088, 0x00}, {0x089, 0x00}, {0x090, 0x00},
        {0x091, 0x00}, {0x092, 0x00}, {0x093, 0x00}, {0x094, 0x00},
        {0x095, 0x00}, {0x096, 0x00}, {0x097, 0x00}, {0x098, 0x00},
        {0x099, 0x00}, {0x0A0, 0x00}, {0x0A1, 0x00}, {0x0A2, 0x00},
        {0x0A3, 0x00}, {0x0A4, 0x00}, {0x0A5, 0x00}, {0x0A6, 0x00},
        {0x0A7, 0x00}, {0x0A8, 0x00}, {0x0A9, 0x00}, {0x0AA, 0x00},
        {0x0AB, 0x00}, {0x0AC, 0x00}, {0x0AD, 0x00}, {0x0AE, 0x00},
        {0x0AF, 0x00}, {0x0B0, 0x00}, {0x0B1, 0x00}, {0x0B2, 0x00},
        {0x0B3, 0x00}, {0x0B4, 0x00}, {0x0B5, 0x00}, {0x0B6, 0x00},
        {0x0B7, 0x00}, {0x0B8, 0x00}, {0x0B9, 0x00}, {0x0BA, 0x00},
        {0x0BB, 0x00}, {0x0BC, 0x00}, {0x0BD, 0x00}, {0x0BE, 0x00},
        {0x0BF, 0x00}, {0x0C0, 0x00}, {0x0C1, 0x00}, {0x0C2, 0x00},
        {0x0C3, 0x00}, {0x0C4, 0x00}, {0x0C5, 0x00}, {0x0C6, 0x00},
        {0x0C7, 0x00}, {0x0C8, 0x00}, {0x0C9, 0x00}, {0x0CA, 0x00},
        {0x0CB, 0x00}, {0x0CC, 0x00}, {0x0CD, 0x00}, {0x0CE, 0x00},
        {0x0CF, 0x00}, {0x0D0, 0x00}, {0x0D1, 0x00}, {0x0D2, 0x00},
        {0x0D3, 0x00}, {0x0D4, 0x00}, {0x0D5, 0x00}, {0x0D6, 0x00},
        {0x0D7, 0x00}, {0x0D8, 0x00}, {0x0D9, 0x00}, {0x0DA, 0x00},
        {0x0DB, 0x00}, {0x0DC, 0x00}, {0x0DD, 0x00}, {0x0DE, 0x00},
        {0x0DF, 0x00}, {0x0E0, 0x00}, {0x0E1, 0x00}, {0x0E2, 0x00},
        {0x0E3, 0x00}, {0x0E4, 0x00}, {0x0E5, 0x00}, {0x0E6, 0x00},
        {0x0E7, 0x00}, {0x0E8, 0x00}, {0x0E9, 0x00}, {0x0EA, 0x00},
        {0x0EB, 0x00}, {0x0EC, 0x00}, {0x0ED, 0x00}, {0x0EE, 0x00},
        {0x0EF, 0x00}, {0x0F0, 0x00}, {0x0F1, 0x00}, {0x0F2, 0x00},
        {0x0F3, 0x00}, {0x0F4, 0x00}, {0x0F5, 0x00}, {0x0F6, 0x00},
        {0x0F7, 0x00}, {0x0F8, 0x00}, {0x0F9, 0x00}, {0x0FA, 0x00},
        {0x0FB, 0x00}, {0x0FC, 0x00}, {0x0FD, 0x00}, {0x0FE, 0x00},
        {0x0FF, 0x00},
    };

    for (size_t i = 0; i < sizeof(cfg) / sizeof(cfg[0]); i++) {
        if (i2c_write_byte(handle, cfg[i].reg, cfg[i].val) < 0)
            return -1;
    }

    /* 5. Clear any pending interrupt */
    if (i2c_write_byte(handle, VL6180X_REG_RESULT_INTERRUPT_CLEAR, 0x01) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Distance measurement                                                */
/* ------------------------------------------------------------------ */
static int vl6180x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status = 0;
    uint16_t range = 0;

    /* Start a single-shot range measurement */
    if (i2c_write_byte(handle, VL6180X_REG_SYSRANGE_START, 0x01) < 0)
        return -1;

    /* Poll for completion (up to ~50 ms) */
    for (int i = 0; i < 50; i++) {
        if (i2c_read_byte(handle, VL6180X_REG_RESULT_INTERRUPT_STATUS, &status) < 0)
            return -1;
        if (status & 0x01)
            break;
        gpioDelay(1000);  /* 1 ms */
    }

    if (!(status & 0x01)) {
        fprintf(stderr, "[VL6180X] measurement timeout\n");
        return -1;
    }

    /* Read range result */
    if (i2c_read_word(handle, VL6180X_REG_RESULT_RANGE_VAL, &range) < 0)
        return -1;

    /* Clear interrupt so the next measurement can signal */
    if (i2c_write_byte(handle, VL6180X_REG_RESULT_INTERRUPT_CLEAR, 0x01) < 0)
        return -1;

    *distance_mm = range;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(uint16_t distance_mm)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("[LOG] fopen");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, distance: %u mm\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, (unsigned)distance_mm);
    } else {
        fprintf(fp, "(timestamp error), distance: %u mm\n", (unsigned)distance_mm);
    }

    fclose(fp);
}

static void log_door_state(uint16_t distance_mm)
{
    if (distance_mm < DOOR_THRESHOLD_MM) {
        printf("DOOR_OPEN\n");
        FILE *fp = fopen(LOG_FILE, "a");
        if (fp) {
            time_t t = time(NULL);
            struct tm tm;
            if (localtime_r(&t, &tm))
                fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, DOOR_OPEN\n",
                        tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                        tm.tm_hour, tm.tm_min, tm.tm_sec);
            fclose(fp);
        }
    } else {
        printf("DOOR_CLOSED\n");
        FILE *fp = fopen(LOG_FILE, "a");
        if (fp) {
            time_t t = time(NULL);
            struct tm tm;
            if (localtime_r(&t, &tm))
                fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, DOOR_CLOSED\n",
                        tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                        tm.tm_hour, tm.tm_min, tm.tm_sec);
            fclose(fp);
        }
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL6180X_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (rc=%d) — sensor may be absent or "
                        "bus unavailable\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl6180x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "VL6180X initialization failed — check wiring and "
                        "that the sensor is present at 0x%02X\n",
                        VL6180X_I2C_ADDR);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("VL6180X initialized. Logging to %s every 100 ms. Ctrl+C to stop.\n",
           LOG_FILE);

    while (g_running) {
        uint16_t distance = 0;

        if (vl6180x_read_distance(g_i2c_handle, &distance) < 0) {
            fprintf(stderr, "Read error — re-initializing sensor...\n");
            i2cClose(g_i2c_handle);
            gpioDelay(1000000);  /* 1 s back-off */
            g_i2c_handle = i2cOpen(I2C_BUS, VL6180X_I2C_ADDR, 0);
            if (g_i2c_handle < 0) {
                fprintf(stderr, "Re-open failed (rc=%d) — exiting\n",
                        g_i2c_handle);
                break;
            }
            if (vl6180x_init(g_i2c_handle) < 0) {
                fprintf(stderr, "Re-init failed — exiting\n");
                break;
            }
            continue;
        }

        log_data(distance);
        log_door_state(distance);
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Clean shutdown */
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

