/*
 * Raspberry Pi 4 Model B - Dual IMP23ABSU Ultrasonic MEMS Microphone Logger
 *
 * Wiring:
 *   Sensor 1: I2C bus 1, address 0x29
 *   Sensor 2: I2C bus 1, address 0x2A
 *   SDA -> GPIO2 (Pin 3), SCL -> GPIO3 (Pin 5)
 *
 * Build: gcc -Wall -Wextra -O2 -o audio_logger audio_logger.c -lpigpio -lrt
 * Run:   sudo ./audio_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SENSOR1_ADDR   0x29
#define SENSOR2_ADDR   0x2A
#define SAMPLE_RATE_US 10000   /* 10 ms */
#define SAMPLE_BYTES   2       /* 16-bit signed sample */
#define LOG_FILE       "audio_log.dat"

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_h1 = -1;
static int  g_i2c_h2 = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_h1 >= 0) {
        i2cClose(g_i2c_h1);
        g_i2c_h1 = -1;
    }
    if (g_i2c_h2 >= 0) {
        i2cClose(g_i2c_h2);
        g_i2c_h2 = -1;
    }
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit signed sample from an IMP23ABSU sensor                 */
/* Returns 0 on success, -1 on I2C error.                              */
/* ------------------------------------------------------------------ */
static int read_sensor_sample(int handle, int16_t *out)
{
    char buf[SAMPLE_BYTES];
    int  bytes;

    bytes = i2cReadDevice(handle, buf, SAMPLE_BYTES);
    if (bytes != SAMPLE_BYTES) {
        fprintf(stderr, "[WARN] i2cReadDevice returned %d (expected %d)\n",
                bytes, SAMPLE_BYTES);
        return -1;
    }

    /* IMP23ABSU outputs 16-bit data left-justified in two's complement */
    *out = (int16_t)((uint16_t)buf[0] << 8 | (uint8_t)buf[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp a sample                                                  */
/* ------------------------------------------------------------------ */
static void timestamp_sample(struct timespec *ts)
{
    if (clock_gettime(CLOCK_REALTIME, ts) != 0) {
        perror("clock_gettime");
    }
}

/* ------------------------------------------------------------------ */
/* Compute TDOA from two timestamps                                     */
/* ------------------------------------------------------------------ */
static double compute_tdoa(const struct timespec *t1,
                           const struct timespec *t2)
{
    double sec_diff  = (double)(t2->tv_sec  - t1->tv_sec);
    double nsec_diff = (double)(t2->tv_nsec - t1->tv_nsec);
    return sec_diff + nsec_diff / 1.0e9;
}

/* ------------------------------------------------------------------ */
/* Append one CSV row                                                  */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, const struct timespec *ts1,
                     const struct timespec *ts2, double tdoa)
{
    fprintf(fp, "%ld.%09ld,%ld.%09ld,%ld,%ld,%.6f\n",
            (long)ts1->tv_sec,  ts1->tv_nsec,
            (long)ts2->tv_sec,  ts2->tv_nsec,
            (long)ts1->tv_sec,  ts2->tv_nsec,
            tdoa);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct timespec ts1, ts2;
    double         tdoa;

    /* --- pigpio init ------------------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C handles -------------------------------------------- */
    g_i2c_h1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (g_i2c_h1 < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n",
                SENSOR1_ADDR, g_i2c_h1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_i2c_h2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (g_i2c_h2 < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n",
                SENSOR2_ADDR, g_i2c_h2);
        i2cClose(g_i2c_h1);
        g_i2c_h1 = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- open log file ----------------------------------------------- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        i2cClose(g_i2c_h1);
        g_i2c_h1 = -1;
        i2cClose(g_i2c_h2);
        g_i2c_h2 = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handling --------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- main sampling loop ------------------------------------------ */
    while (g_running) {
        int16_t s1 = 0, s2 = 0;

        if (read_sensor_sample(g_i2c_h1, &s1) != 0) {
            fprintf(stderr, "[WARN] Sensor 1 read failed; skipping sample\n");
            gpioDelay(SAMPLE_RATE_US);
            continue;
        }

        if (read_sensor_sample(g_i2c_h2, &s2) != 0) {
            fprintf(stderr, "[WARN] Sensor 2 read failed; skipping sample\n");
            gpioDelay(SAMPLE_RATE_US);
            continue;
        }

        timestamp_sample(&ts1);
        timestamp_sample(&ts2);

        tdoa = compute_tdoa(&ts1, &ts2);
        log_data(g_log_fp, &ts1, &ts2, tdoa);

        gpioDelay(SAMPLE_RATE_US);
    }

    /* --- graceful shutdown ------------------------------------------ */
    cleanup();
    return EXIT_SUCCESS;
}

