    struct timespec ts1, ts2;
    double         tdoa;

    /* --- pigpio init ------------------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C handles -------------------------------------------- */
    g_i2c_h1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (g_i2c_h1 < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n",
                SENSOR1_ADDR, g_i2c_h1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_i2c_h2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (g_i2c_h2 < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n",
                SENSOR2_ADDR, g_i2c_h2);
        i2cClose(g_i2c_h1);
        g_i2c_h1 = -1;
        gpioTerminate();
        return EXIT_FAILURE;
