#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16488A Register Map (16-bit addresses, MSB of word = 0) */
#define ADIS16488A_REG_GYRO_XOUT  0x04
#define ADIS16488A_REG_GYRO_YOUT  0x06
#define ADIS16488A_REG_GYRO_ZOUT  0x08
#define ADIS16488A_REG_ACCEL_XOUT 0x0A
#define ADIS16488A_REG_ACCEL_YOUT 0x0C
#define ADIS16488A_REG_ACCEL_ZOUT 0x0E

/* Sensitivities (from ADIS16488A datasheet) */
#define GYRO_SENSITIVITY   0.005f   /* degrees/sec/LSB */
#define ACCEL_SENSITIVITY  0.00025f /* g/LSB */

/* SPI parameters */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0x03     /* mode 3: CPOL=1, CPHA=1 */

/* Timing */
#define SAMPLE_PERIOD_US 100000  /* 100 ms */
#define STALL_TIME_US    40      /* >= 40 us stall time */
#define NON_BLOCKING_US  5000    /* 5 ms poll interval */

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t running = 1;

typedef struct {
    float gyro_x, gyro_y, gyro_z;
    float accel_x, accel_y, accel_z;
} imu_data_t;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper (atexit)                                            */
/* ------------------------------------------------------------------ */
static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (fp != NULL) {
        fclose(fp);
        fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register from the ADIS16488A                          */
/* Returns 0 on success, -1 on SPI error, -2 on API error.             */
/* ------------------------------------------------------------------ */
static int read_register(uint8_t reg, int16_t *out) {
    char tx[2], rx[2];
    int  result;

    /* Build command word: MSB = 0 (read), 7 bits = register address */
    tx[0] = (char)(reg & 0x7F);
    tx[1] = 0x00;

    /* pigpio spiXfer uses the 4-wire SPI bus; ADIS16488A is 3-wire
       so we send the command and read back 2 dummy bytes; the data
       we capture on the next transfer. */
    result = spiXfer(spi_handle, tx, rx, 2);
    if (result < 0) {
        fprintf(stderr, "SPI command transfer failed (reg=0x%02X): %d\n",
                reg, result);
        return -1;
    }

    /* Stall time between request and data transfer */
    gpioDelay(STALL_TIME_US);

    /* Read the 16-bit data word */
    result = spiRead(spi_handle, (char *)tx, 2);
    if (result < 0) {
        fprintf(stderr, "SPI data read failed (reg=0x%02X): %d\n",
                reg, result);
        return -1;
    }
    if (result != 2) {
        fprintf(stderr, "SPI data read short transfer (reg=0x%02X): %d\n",
                reg, result);
        return -1;
    }

    /* Data is returned MSB-first */
    *out = (int16_t)(((uint8_t)tx[0] << 8) | (uint8_t)tx[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read IMU data                                                       */
/* ------------------------------------------------------------------ */
static int read_imu_data(imu_data_t *data) {
    int16_t raw;

    if (read_register(ADIS16488A_REG_GYRO_XOUT, &raw) != 0)
        return -1;
    data->gyro_x = (float)raw * GYRO_SENSITIVITY;

    if (read_register(ADIS16488A_REG_GYRO_YOUT, &raw) != 0)
        return -1;
    data->gyro_y = (float)raw * GYRO_SENSITIVITY;

    if (read_register(ADIS16488A_REG_GYRO_ZOUT, &raw) != 0)
        return -1;
    data->gyro_z = (float)raw * GYRO_SENSITIVITY;

    if (read_register(ADIS16488A_REG_ACCEL_XOUT, &raw) != 0)
        return -1;
    data->accel_x = (float)raw * ACCEL_SENSITIVITY;

    if (read_register(ADIS16488A_REG_ACCEL_YOUT, &raw) != 0)
        return -1;
    data->accel_y = (float)raw * ACCEL_SENSITIVITY;

    if (read_register(ADIS16488A_REG_ACCEL_ZOUT, &raw) != 0)
        return -1;
    data->accel_z = (float)raw * ACCEL_SENSITIVITY;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log data to CSV                                                     */
/* ------------------------------------------------------------------ */
static int log_data(const imu_data_t *data) {
    struct timespec ts;
    struct tm tm_info;
    char timestamp[40];

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }

    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp),
             sizeof(timestamp) - strlen(timestamp),
             ".%03ld", ts.tv_nsec / 1000000);

    if (fprintf(fp, "%s,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
                timestamp,
                data->gyro_x, data->gyro_y, data->gyro_z,
                data->accel_x, data->accel_y, data->accel_z) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void) {
    imu_data_t imu_data;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel (mode 3 = CPOL=1, CPHA=1) */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open CSV file */
    fp = fopen("imu_data.csv", "w");
    if (fp == NULL) {
        perror("fopen");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (fprintf(fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n") < 0) {
        perror("fprintf header");
        fclose(fp);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        fclose(fp);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register cleanup with atexit */
    if (atexit(cleanup) != 0) {
        fprintf(stderr, "atexit registration failed\n");
        fclose(fp);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("IMU data logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (running) {
        if (read_imu_data(&imu_data) == 0) {
            if (log_data(&imu_data) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read IMU data; skipping sample.\n");
        }

        /* Non-blocking delay that checks running flag every 5 ms */
        for (int i = 0; i < 10 && running; i++) {
            gpioDelay(NON_BLOCKING_US);
        }
    }

    printf("\nShutting down gracefully...\n");
    return EXIT_SUCCESS;
}

