#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        SPI_MODE_3
#define SPI_BITS        8

#define ADIS16448_GYRO_XOUT_H  0x04
#define ADIS16448_GYRO_XOUT_L  0x05
#define ADIS16448_ACCEL_XOUT_H 0x06
#define ADIS16448_ACCEL_XOUT_L 0x07

#define GYRO_SCALE  0.02f   /* dps per LSB */
#define ACCEL_SCALE 0.00025f /* g per LSB */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_transfer(int fd, const uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_register(int fd, uint8_t reg_addr, uint16_t *data) {
    uint8_t tx[2] = { (uint8_t)(reg_addr | 0x80), 0x00 };
    uint8_t rx[2] = { 0 };

    if (spi_transfer(fd, tx, rx, 2) < 0) {
        return -1;
    }

    /* ADIS16448: data is returned in the second 16-bit SPI cycle */
    uint8_t dummy[2] = { 0 };
    if (spi_transfer(fd, dummy, rx, 2) < 0) {
        return -1;
    }

    *data = ((uint16_t)rx[0] << 8) | rx[1];
    return 0;
}

static int read_imu_data(int fd, float *gyro_x, float *gyro_y, float *gyro_z,
                         float *accel_x, float *accel_y, float *accel_z) {
    uint16_t raw_gyro_x, raw_gyro_y, raw_gyro_z;
    uint16_t raw_accel_x, raw_accel_y, raw_accel_z;

    if (read_register(fd, ADIS16448_GYRO_XOUT_H, &raw_gyro_x) < 0) return -1;
    if (read_register(fd, ADIS16448_GYRO_XOUT_L, &raw_gyro_y) < 0) return -1;
    if (read_register(fd, ADIS16448_GYRO_XOUT_L, &raw_gyro_z) < 0) return -1;
    if (read_register(fd, ADIS16448_ACCEL_XOUT_H, &raw_accel_x) < 0) return -1;
    if (read_register(fd, ADIS16448_ACCEL_XOUT_L, &raw_accel_y) < 0) return -1;
    if (read_register(fd, ADIS16448_ACCEL_XOUT_L, &raw_accel_z) < 0) return -1;

    *gyro_x = (float)((int16_t)raw_gyro_x) * GYRO_SCALE;
    *gyro_y = (float)((int16_t)raw_gyro_y) * GYRO_SCALE;
    *gyro_z = (float)((int16_t)raw_gyro_z) * GYRO_SCALE;
    *accel_x = (float)((int16_t)raw_accel_x) * ACCEL_SCALE;
    *accel_y = (float)((int16_t)raw_accel_y) * ACCEL_SCALE;
    *accel_z = (float)((int16_t)raw_accel_z) * ACCEL_SCALE;

    return 0;
}

int main(void) {
    int spi_fd = -1;
    int chip_fd = -1;
    int ret_code = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE;
