#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16448 Register Addresses */
#define ADIS16448_REG_GYRO_XOUT 0x04
#define ADIS16448_REG_GYRO_YOUT 0x06
#define ADIS16448_REG_GYRO_ZOUT 0x08
#define ADIS16448_REG_ACCEL_XOUT 0x0A
#define ADIS16448_REG_ACCEL_YOUT 0x0C
#define ADIS16448_REG_ACCEL_ZOUT 0x0E

/* Scaling factors (from ADIS16448 datasheet) */
#define GYRO_SCALE  0.05f   /* degrees/sec per LSB */
#define ACCEL_SCALE 0.00025f /* g per LSB */

/* SPI parameters */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000 /* 1 MHz */
#define SPI_FLAGS   0       /* Mode 0, active-low CE0 */

/* Globals for cleanup */
static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/*
 * ADIS16448 SPI read sequence (two 16-bit transfers):
 *   Transfer 1: [0x80 | reg, 0x00, 0x00, 0x00]  -> sets read bit (bit 15)
 *   Transfer 2: [dummy, dummy, dummy, dummy]     -> clocks out 16-bit data
 * The 16-bit data is returned in the order: [high, low].
 */
static int adis16448_read_register(uint8_t reg, int16_t *out) {
    char tx_cmd[4] = { (char)(0x80 | (reg & 0x7F)), 0x00, 0x00, 0x00 };
    char rx_cmd[4] = { 0 };
    char tx_data[4] = { 0x00, 0x00, 0x00, 0x00 };
    char rx_data[4] = { 0 };

    /* Transfer 1: send read command */
    if (spiXfer(spi_handle, tx_cmd, rx_cmd, 4) != 4) {
        fprintf(stderr, "SPI command transfer failed for register 0x%02X\n", reg);
        return -1;
    }

    /* Stall time per datasheet (>= 40 us) */
    gpioDelay(50); /* 50 us */

    /* Transfer 2: dummy bytes to clock out data */
    if (spiXfer(spi_handle, tx_data, rx_data, 4) != 4) {
        fprintf(stderr, "SPI data transfer failed for register 0x%02X\n", reg);
        return -1;
    }

    *out = (int16_t)(((uint16_t)(uint8_t)rx_data[0] << 8) | (uint8_t)rx_data[1]);
    return 0;
}

static int read_imu_data(float *gyro_x, float *gyro_y, float *gyro_z,
                         float *accel_x, float *accel_y, float *accel_z) {
    int16_t raw_gyro_x, raw_gyro_y, raw_gyro_z;
    int16_t raw_accel_x, raw_accel_y, raw_accel_z;

    if (adis16448_read_register(ADIS16448_REG_GYRO_XOUT, &raw_gyro_x) != 0) return -1;
    if (adis16448_read_register(ADIS16448_REG_GYRO_YOUT, &raw_gyro_y) != 0) return -1;
    if (adis16448_read_register(ADIS16448_REG_GYRO_ZOUT, &raw_gyro_z) != 0) return -1;
    if (adis16448_read_register(ADIS16448_REG_ACCEL_XOUT, &raw_accel_x) != 0) return -1;
    if (adis16448_read_register(ADIS16448_REG_ACCEL_YOUT, &raw_accel_y) != 0) return -1;
    if (adis16448_read_register(ADIS16448_REG_ACCEL_ZOUT, &raw_accel_z) != 0) return -1;

    *gyro_x = (float)raw_gyro_x * GYRO_SCALE;
    *gyro_y = (float)raw_gyro_y * GYRO_SCALE;
    *gyro_z = (float)raw_gyro_z * GYRO_SCALE;
    *accel_x = (float)raw_accel_x * ACCEL_SCALE;
    *accel_y = (float)raw_accel_y * ACCEL_SCALE;
    *accel_z = (float)raw_accel_z * ACCEL_SCALE;

    return 0;
}

int main(void) {
    float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, speed %d)\n", SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADIS16448 IMU Reader (Ctrl+C to exit)\n");

    while (!terminate) {
        if (read_imu_data(&gyro_x, &gyro_y, &gyro_z, &accel_x, &accel_y, &accel_z) == 0) {
            printf("Gyro: X=%.3f, Y=%.3f, Z=%.3f  |  Accel: X=%.3f, Y=%.3f, Z=%.3f\n",
                   gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
        } else {
            fprintf(stderr, "Failed to read IMU data\n");
        }
        gpioDelay(100000); /* 100 ms */
    }

    /* Cleanup */
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

