/*
 * MPU-6886 6-axis IMU reader for Raspberry Pi 4 Model B
 * Bus: I2C-1 (GPIO2=SDA, GPIO3=SCL), address 0x68
 * Reads accel (ACCEL_XOUT_H) and gyro (GYRO_XOUT_H) every 50 ms.
 *
 * Build:  gcc -O2 -Wall -o mpu6886 mpu6886.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6886_ADDR   0x68

/* MPU-6886 register map (bank 0) */
#define REG_SMPLRT_DIV   0x19
#define REG_PWR_MGMT_1   0x6B
#define REG_ACCEL_XOUT_H 0x3B
#define REG_GYRO_XOUT_H  0x43

#define SAMPLE_PERIOD_MS 50
#define MAX_RETRIES      3

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write one byte to an 8-bit register; returns 0 on success, -1 on error. */
static int reg_write8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "reg_write8(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read N bytes starting at an 8-bit register; returns 0 on success, -1 on error. */
static int reg_read(int fd, uint8_t reg, uint8_t *dst, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "reg_read: write reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, dst, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "reg_read: read reg 0x%02X (%zu bytes): got %zd, %s\n",
                reg, len, n, strerror(errno));
        return -1;
    }
    return 0;
}

/* Initialize the MPU-6886: wake up, set sample rate divider to 0 (1 kHz/s). */
static int mpu6886_init(int fd)
{
    if (reg_write8(fd, REG_PWR_MGMT_1, 0x00) < 0)
        return -1;
    usleep(100000); /* allow oscillator to stabilize */
    if (reg_write8(fd, REG_SMPLRT_DIV, 0x00) < 0)
        return -1;
    return 0;
}

/* Read 14 bytes: accel (6) + temp (2) + gyro (6). */
static int mpu6886_read(int fd,
                        int16_t *ax, int16_t *ay, int16_t *az,
                        int16_t *gx, int16_t *gy, int16_t *gz)
{
    uint8_t raw[14];
    if (reg_read(fd, REG_ACCEL_XOUT_H, raw, sizeof(raw)) < 0)
        return -1;

    *ax = (int16_t)((raw[0]  << 8) | raw[1]);
    *ay = (int16_t)((raw[2]  << 8) | raw[3]);
    *az = (int16_t)((raw[4]  << 8) | raw[5]);
    /* raw[6..7] = temperature (skipped) */
    *gx = (int16_t)((raw[8]  << 8) | raw[9]);
    *gy = (int16_t)((raw[10] << 8) | raw[11]);
    *gz = (int16_t)((raw[12] << 8) | raw[13]);
    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                MPU6886_ADDR, strerror(errno));
        goto cleanup;
    }

    if (mpu6886_init(fd) < 0) {
        fprintf(stderr, "MPU-6886 init failed (sensor absent or bus error)\n");
        goto cleanup;
    }

    printf("MPU-6886 ready on %s @ 0x%02X. Sampling every %d ms.\n",
           I2C_BUS, MPU6886_ADDR, SAMPLE_PERIOD_MS);
    fflush(stdout);

    while (g_running) {
        int16_t ax, ay, az, gx, gy, gz;
        bool ok = false;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; ++attempt) {
            if (mpu6886_read(fd, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
                ok = true;
                break;
            }
            usleep(10000); /* 10 ms backoff before retry */
        }

        if (!ok) {
            fprintf(stderr, "MPU-6886 read failed after %d attempts; continuing.\n",
                    MAX_RETRIES);
            continue;
        }

        printf("Accel: %6d %6d %6d  |  Gyro: %6d %6d %6d\n",
               ax, ay, az, gx, gy, gz);
        fflush(stdout);

        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
    return rc;
}

