#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

/* ADXL345 Register Addresses */
#define ADXL345_ADDRESS        0x52
#define ADXL345_DEVID          0x00
#define ADXL345_POWER_CTL      0x2D
#define ADXL345_DATA_FORMAT    0x31
#define ADXL345_DATAX0         0x32
#define ADXL345_BW_RATE        0x2C

/* Expected Device ID */
#define ADXL345_DEVID_VALUE    0xE5

/* Configuration */
#define I2C_BUS               1
#define LED_GPIO               17
#define IMPACT_THRESHOLD_G     2.5f
#define POLL_DELAY_US          10000   /* 10 ms */
#define LED_ON_DELAY_US        500000  /* 500 ms */
#define LOG_FILE_NAME          "impact_log.txt"

/* Scale factor for ±2 g range (4 mg/LSB full resolution) */
#define SCALE_FACTOR_G         0.004f

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_checked(int handle, uint8_t reg, uint8_t value,
                             const char *ctx)
{
    if (i2cWriteByteData(handle, reg, value) < 0) {
        fprintf(stderr, "[ERROR] I2C write 0x%02X <- 0x%02X failed: %s\n",
                reg, value, ctx);
        return -1;
    }
    return 0;
}

static int i2c_read_checked(int handle, uint8_t reg, uint8_t *value,
                            const char *ctx)
{
    int v = i2cReadByteData(handle, reg);
    if (v < 0) {
        fprintf(stderr, "[ERROR] I2C read 0x%02X failed: %s\n",
                reg, ctx);
        return -1;
    }
    *value = (uint8_t)v;
    return 0;
}

/* ------------------------------------------------------------------ */
/* ADXL345 initialization                                              */
/* ------------------------------------------------------------------ */
static int adxl345_init(int handle)
{
    uint8_t devid = 0;

    /* Verify device identity */
    if (i2c_read_checked(handle, ADXL345_DEVID, &devid, "DEVID read") < 0)
        return -1;

    if (devid != ADXL345_DEVID_VALUE) {
        fprintf(stderr, "[ERROR] Device ID mismatch: got 0x%02X, expected 0x%02X\n",
                devid, ADXL345_DEVID_VALUE);
        return -1;
    }

    /* Standby mode to allow configuration changes */
    if (i2c_write_checked(handle, ADXL345_POWER_CTL, 0x00, "POWER_CTL standby") < 0)
        return -1;

    /* Full resolution, ±2 g range (0x0B) */
    if (i2c_write_checked(handle, ADXL345_DATA_FORMAT, 0x0B,
                          "DATA_FORMAT set") < 0)
        return -1;

    /* 100 Hz output data rate (0x0A) */
    if (i2c_write_checked(handle, ADXL345_BW_RATE, 0x0A, "BW_RATE set") < 0)
        return -1;

    /* Enable measurement mode */
    if (i2c_write_checked(handle, ADXL345_POWER_CTL, 0x08, "POWER_CTL measure") < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read acceleration (g)                                               */
/* ------------------------------------------------------------------ */
static int read_acceleration(int handle, float *x, float *y, float *z)
{
    uint8_t xl, xh, yl, yh, zl, zh;

    if (i2c_read_checked(handle, ADXL345_DATAX0, &xl, "DATAX0") < 0)
        return -1;
    if (i2c_read_checked(handle, ADXL345_DATAX0 + 1, &xh, "DATAX1") < 0)
        return -1;
    if (i2c_read_checked(handle, ADXL345_DATAX0 + 2, &yl, "DATAY0") < 0)
        return -1;
    if (i2c_read_checked(handle, ADXL345_DATAX0 + 3, &yh, "DATAY1") < 0)
        return -1;
    if (i2c_read_checked(handle, ADXL345_DATAX0 + 4, &zh, "DATAZ0") < 0)
        return -1;
    if (i2c_read_checked(handle, ADXL345_DATAX0 + 5, &zl, "DATAZ1") < 0)
        return -1;

    int16_t raw_x = (int16_t)((xh << 8) | xl);
    int16_t raw_y = (int16_t)((yh << 8) | yl);
    int16_t raw_z = (int16_t)((zh << 8) | zl);

    *x = (float)raw_x * SCALE_FACTOR_G;
    *y = (float)raw_y * SCALE_FACTOR_G;
    *z = (float)raw_z * SCALE_FACTOR_G;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Impact detection                                                    */
/* ------------------------------------------------------------------ */
static bool detect_impact(float x, float y, float z, float threshold)
{
    float magnitude = sqrtf(x * x + y * y + z * z);
    return (magnitude > threshold);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_impact(FILE *fp, float x, float y, float z, float mag)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(fp, "[timestamp_error] Impact: mag=%.3f g (X=%.3f, Y=%.3f, Z=%.3f)\n",
                mag, x, y, z);
    } else {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d Impact: mag=%.3f g (X=%.3f, Y=%.3f, Z=%.3f)\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                mag, x, y, z);
    }
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Safe to call even if not initialised */
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "[FATAL] Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDRESS, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, ADXL345_ADDRESS, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize ADXL345 */
    if (adxl345_init(g_i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] ADXL345 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'\n", LOG_FILE_NAME);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADXL345 monitoring started. Threshold: %.2f g. Press Ctrl+C to exit.\n",
           IMPACT_THRESHOLD_G);

    /* Main loop */
    while (g_running) {
        float x, y, z;

        if (read_acceleration(g_i2c_handle, &x, &y, &z) < 0) {
            fprintf(stderr, "[WARN] Read error — continuing\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (detect_impact(x, y, z, IMPACT_THRESHOLD_G)) {
            printf("Impact detected! (X=%.3f, Y=%.3f, Z=%.3f)\n", x, y, z);

            /* Turn LED on */
            gpioWrite(LED_GPIO, 1);
            gpioDelay(LED_ON_DELAY_US);
            gpioWrite(LED_GPIO, 0);

            /* Log to file */
            log_impact(g_log_file, x, y, z, sqrtf(x * x + y * y + z * z));
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

