#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* ICM-20602 I2C address (AD0 tied to GND) */
#define ICM20602_ADDR 0x68

/* Bank 0 registers */
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x2D
#define GYRO_XOUT_H  0x33

/* Bank 2 registers (gyro full-scale range) */
#define GYRO_CONFIG_1 0x1B

/* Scaling factors */
#define ACCEL_SCALE 16384.0f  /* +/- 2g */
#define GYRO_SCALE  131.0f    /* +/- 250 dps */

#define I2C_BUS 1
#define SAMPLE_PERIOD_US 100000  /* 100 ms = 10 Hz */

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} imu_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_imu(void) {
    /* Wake up: clear sleep bit, use internal 8 MHz oscillator */
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing PWR_MGMT_1: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */

    /* Set gyro full-scale range to +/- 250 dps (FS_SEL = 0) */
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG_1, 0x00) < 0) {
        fprintf(stderr, "Error writing GYRO_CONFIG_1: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int read_imu_data(imu_data_t *data) {
    char buf[12];
    int16_t ax, ay, az, gx, gy, gz;

    /* Burst read 12 bytes starting at ACCEL_XOUT_H (0x2D) */
    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buf, 12) != 12) {
        fprintf(stderr, "Error reading IMU data block: %s\n", strerror(errno));
        return -1;
    }

    ax = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    ay = (int16_t)((buf[2] << 8) | (uint8_t)buf[3]);
    az = (int16_t)((buf[4] << 8) | (uint8_t)buf[5]);
    gx = (int16_t)((buf[6] << 8) | (uint8_t)buf[7]);
    gy = (int16_t)((buf[8] << 8) | (uint8_t)buf[9]);
    gz = (int16_t)((buf[10] << 8) | (uint8_t)buf[11]);

    data->accel_x = (float)ax / ACCEL_SCALE;
    data->accel_y = (float)ay / ACCEL_SCALE;
    data->accel_z = (float)az / ACCEL_SCALE;
    data->gyro_x  = (float)gx / GYRO_SCALE;
    data->gyro_y  = (float)gy / GYRO_SCALE;
    data->gyro_z  = (float)gz / GYRO_SCALE;

    return 0;
}

static void log_data(const imu_data_t *data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(log_file, "%ld.%09ld,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
            (long)ts.tv_sec, ts.tv_nsec,
            data->accel_x, data->accel_y, data->accel_z,
            data->gyro_x, data->gyro_y, data->gyro_z);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    imu_data_t imu_data;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, ICM20602_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %s\n",
                I2C_BUS, ICM20602_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_imu() != 0) {
        fprintf(stderr, "IMU initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,accel_x,accel_y,accel_z,gyro_x,gyro_y,gyro_z\n");
        fflush(log_file);
    }

    signal(SIGINT, signal_handler);

    printf("Logging IMU data to imu_log.csv (Ctrl+C to stop)...\n");

    while (!terminate) {
        if (read_imu_data(&imu_data) == 0) {
            log_data(&imu_data);
        } else {
            fprintf(stderr, "Read failed, continuing...\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

