/* Expected WHO_AM_I value for MMA8451Q */
#define MMA8451_WHO_AM_I_VAL    0x33

/* Impact threshold: 2.0 g in counts (±2g range, 1g = 1024 counts) */
#define IMPACT_THRESHOLD_G     2.0f
#define IMPACT_THRESHOLD_COUNTS (int16_t)(IMPACT_THRESHOLD_G * 1024.0f)

/* GPIO pin for LED (BCM numbering) */
#define LED_PIN 17

/* I2C bus on Raspberry Pi 3 Model B+ */
#define I2C_BUS 1

/* Sampling interval in microseconds */
#define SAMPLE_INTERVAL_US 100000

/* LED on-time in microseconds */
#define LED_ON_TIME_US 500000

/* Global resources for signal handler cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    int16_t x, y, z;
} accelerometer_data_t;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    /* Ensure LED is off before releasing pigpio */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read a single byte from an MMA8451Q register                         */
/* ------------------------------------------------------------------ */
static int read_register(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error on reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an MMA8451Q register                          */
/* ------------------------------------------------------------------ */
static int write_register(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write error on reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read accelerometer data (6 bytes starting at OUT_X_MSB)             */
/* ------------------------------------------------------------------ */
static int read_accelerometer_data(accelerometer_data_t *data) {
    char buffer[6];
    int rc = i2cReadI2CBlockData(i2c_handle, MMA8451_REG_OUT_X_MSB, buffer, 6);
    if (rc != 6) {
        fprintf(stderr, "I2C block read error: expected 6 bytes, got %d\n", rc);
        return -1;
    }

    data->x = (int16_t)(((uint8_t)buffer[0] << 8) | (uint8_t)buffer[1]);
    data->y = (int16_t)(((uint8_t)buffer[2] << 8) | (uint8_t)buffer[3]);
    data->z = (int16_t)(((uint8_t)buffer[4] << 8) | (uint8_t)buffer[5]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Verify sensor identity                                              */
/* ------------------------------------------------------------------ */
static int verify_sensor_identity(void) {
    uint8_t who_am_i = 0;
    if (read_register(MMA8451_REG_WHO_AM_I, &who_am_i) != 0) {
        return -1;
    }
    if (who_am_i != MMA8451_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, MMA8451_WHO_AM_I_VAL);
        return -1;
    }
    printf("MMA8451Q identified (WHO_AM_I = 0x%02X)\n", who_am_i);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the MMA8451Q: standby mode, then active mode              */
/* ------------------------------------------------------------------ */
static int initialize_accelerometer(void) {
    /* CTRL_REG1: active mode, 800 Hz ODR, little-endian */
    if (write_register(MMA8451_REG_CTRL_REG1, 0x01) != 0) {
        return -1;
    }
    /* CTRL_REG2: ±2g range, high-resolution off */
    if (write_register(MMA8451_REG_CTRL_REG2, 0x00) != 0) {
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log data with timestamp                                             */
/* ------------------------------------------------------------------ */
static void log_data(const accelerometer_data_t *data) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d\n", timestamp, data->x, data->y, data->z);
    fflush(log_file);
}

/* ------------------------------------------------------------------ */
/* Check for impact and trigger LED                                    */
/* ------------------------------------------------------------------ */
static void check_impact(const accelerometer_data_t *data) {
    if (abs((int16_t)data->x) > IMPACT_THRESHOLD_COUNTS ||
        abs((int16_t)data->y) > IMPACT_THRESHOLD_COUNTS ||
        abs((int16_t)data->z) > IMPACT_THRESHOLD_COUNTS) {

        printf("Impact detected! (X: %d, Y: %d, Z: %d)\n", data->x, data->y, data->z);

        if (gpioWrite(LED_PIN, 1) != 0) {
            fprintf(stderr, "Failed to turn on LED\n");
        }

        /* Keep LED on for 500 ms (check terminate flag periodically) */
        uint32_t elapsed = 0;
        while (elapsed < LED_ON_TIME_US && !terminate) {
            gpioDelay(10000); /* 10 ms */
            elapsed += 10000;
        }

        if (gpioWrite(LED_PIN, 0) != 0) {
            fprintf(stderr, "Failed to turn off LED\n");
        }
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at address 0x1D */
    i2c_handle = i2cOpen(I2C_BUS, MMA8451_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, MMA8451_ADDRESS, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify sensor identity */
    if (verify_sensor_identity() != 0) {
        fprintf(stderr, "MMA8451Q not detected on I2C bus %d at addr 0x%02X\n",
                I2C_BUS, MMA8451_ADDRESS);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize accelerometer */
    if (initialize_accelerometer() != 0) {
        fprintf(stderr, "Failed to initialize MMA8451Q\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output and ensure it starts off */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MMA8451Q impact monitor running. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (!terminate) {
        accelerometer_data_t data;

        if (read_accelerometer_data(&data) != 0) {
            fprintf(stderr, "Read error; continuing after short delay\n");
            gpioDelay(100000); /* 100 ms backoff */
            continue;
        }

        log_data(&data);
        check_impact(&data);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

