    return 0;
}

static int read_magnetic_field(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t x_msb, x_lsb, y_msb, y_lsb, z_msb, z_lsb;

    if (i2c_read_reg8(fd, TMAG5273_REG_X_MSB, &x_msb) < 0) return -1;
    if (i2c_read_reg8(fd, TMAG5273_REG_X_LSB, &x_lsb) < 0) return -1;
    if (i2c_read_reg8(fd, TMAG5273_REG_Y_MSB, &y_msb) < 0) return -1;
    if (i2c_read_reg8(fd, TMAG5273_REG_Y_LSB, &y_lsb) < 0) return -1;
    if (i2c_read_reg8(fd, TMAG5273_REG_Z_MSB, &z_msb) < 0) return -1;
    if (i2c_read_reg8(fd, TMAG5273_REG_Z_LSB, &z_lsb) < 0) return -1;

