#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <pigpio.h>

#define I2C_BUS         "/dev/i2c-1"
#define ADXL345_ADDR    0x52
#define ADXL345_DEVID   0x00
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0  0x32
#define ADXL345_INT_ENABLE 0x2E
#define ADXL345_INT_MAP  0x2F
#define ADXL345_INT_SOURCE 0x30
#define ADXL345_DATA_FORMAT 0x31

#define INTERRUPT_PIN   17
#define LOG_FILE        "freefall_log.csv"
#define SAMPLE_PERIOD_US 100000

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static int  g_gpio_int = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C burst read from 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int adxl345_init(int fd)
{
    uint8_t devid = 0;
    if (i2c_read_reg(fd, ADXL345_DEVID, &devid) < 0)
        return -1;
    if (devid != 0xE5) {
        fprintf(stderr, "ADXL345 not found (DEVID=0x%02X, expected 0xE5)\n", devid);
        return -1;
    }

    if (i2c_write_reg(fd, ADXL345_POWER_CTL, 0x00) < 0)
        return -1;
    if (i2c_write_reg(fd, ADXL345_DATA_FORMAT, 0x00) < 0)
        return -1;
    if (i2c_write_reg(fd, ADXL345_INT_MAP, 0x00) < 0)
        return -1;
    if (i2c_write_reg(fd, ADXL345_INT_ENABLE, 0x00) < 0)
        return -1;
    if (i2c_write_reg(fd, ADXL345_POWER_CTL, 0x08) < 0)
        return -1;
    return 0;
}

static int adxl345_read_xyz(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (i2c_read_burst(fd, ADXL345_DATAX0, buf, 6) < 0)
        return -1;
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static void log_sample(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld,%d,%d,%d\n", tbuf, ts.tv_nsec / 1000000, x, y, z);
    fflush(fp);
}

static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        i2c_write_reg(g_i2c_fd, ADXL345_POWER_CTL, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_gpio_int >= 0) {
        gpioSetAlertFunc(INTERRUPT_PIN, NULL);
        gpioSetMode(INTERRUPT_PIN, PI_INPUT);
        g_gpio_int = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", ADXL345_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (adxl345_init(g_i2c_fd) < 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "w");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(g_log_fp, "Timestamp,X,Y,Z\n");
    fflush(g_log_fp);

    g_gpio_int = gpioSetMode(INTERRUPT_PIN, PI_INPUT);
    if (g_gpio_int < 0) {
        fprintf(stderr, "gpioSetMode failed: %s\n", pigpio_error(g_gpio_int));
        cleanup();
        return EXIT_FAILURE;
    }
    g_gpio_int = gpioSetAlertFunc(INTERRUPT_PIN, NULL);
    if (g_gpio_int < 0) {
        fprintf(stderr, "gpioSetAlertFunc failed: %s\n", pigpio_error(g_gpio_int));
        cleanup();
        return EXIT_FAILURE;
    }

    if (i2c_write_reg(g_i2c_fd, ADXL345_INT_ENABLE, 0x04) < 0) {
        fprintf(stderr, "Failed to enable free-fall interrupt\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Free-fall detection started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int fd = gpioGetEventFD();
        if (fd < 0) {
            fprintf(stderr, "gpioGetEventFD failed: %s\n", pigpio_error(fd));
            break;
        }

        struct timeval tv = { SAMPLE_PERIOD_US / 1000000,
                              (SAMPLE_PERIOD_US % 1000000) * 1000 };
        int rv = select(fd + 1, NULL, NULL, NULL, &tv);
        if (rv < 0) {
            if (errno == EINTR)
                continue;
            fprintf(stderr, "select error: %s\n", strerror(errno));
            break;
        }
        if (rv == 0)
            continue;

        uint8_t event_buf[32];
        ssize_t n = read(fd, event_buf, sizeof(event_buf));
        if (n < 0) {
            if (errno == EINTR)
                continue;
            fprintf(stderr, "read on event fd failed: %s\n", strerror(errno));
            break;
        }
        if (n == 0)
            continue;

        for (int i = 0; i < n; i++) {
            uint32_t event = event_buf[i];
            if (event & 0x04) {
                uint8_t int_source = 0;
                if (i2c_read_reg(g_i2c_fd, ADXL345_INT_SOURCE, &int_source) < 0)
                    continue;
                if (int_source & 0x04) {
                    int16_t x, y, z;
                    if (adxl345_read_xyz(g_i2c_fd, &x, &y, &z) == 0) {
                        log_sample(g_log_fp, x, y, z);
                    } else {
                        fprintf(stderr, "Failed to read acceleration data\n");
                    }
                }
                if (i2c_write_reg(g_i2c_fd, ADXL345_INT_SOURCE, 0x04) < 0)
                    fprintf(stderr, "Warning: failed to clear interrupt source\n");
            }
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

