/*
 * LSM6DSR IMU logger with fall detection for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   LSM6DSR SDA -> GPIO2 (BCM 3, physical pin 3)
 *   LSM6DSR SCL -> GPIO3 (BCM 5, physical pin 5)
 *   LSM6DSR VDD -> 3.3 V
 *   LSM6DSR GND -> GND
 *
 * Build: gcc -O2 -Wall -o lsm6dsr_log lsm6dsr_log.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- LSM6DSR register definitions ---- */
#define LSM6DSR_ADDR_ACCEL 0x19
#define LSM6DSR_ADDR_GYRO  0x1A

#define WHO_AM_I_ACCEL 0x0F
#define WHO_AM_I_GYRO  0x0F
#define WHO_AM_I_VAL   0x6A

#define CTRL1_XL       0x10
#define CTRL2_G        0x11
#define OUTX_L_G       0x22
#define OUTX_L_XL      0x28

/* ---- Configuration constants ---- */
#define I2C_BUS        1
#define SAMPLE_RATE_HZ 104
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)
#define ACCEL_SCALE    2.0f   /* +/- 2 g  */
#define GYRO_SCALE     250.0f /* +/- 250 dps */
#define FREEFALL_THRESHOLD_G  0.2f
#define IMPACT_THRESHOLD_G    2.5f
#define IMPACT_WINDOW_S       1.0f
#define LOG_FILE_NAME "motion_log.txt"

/* ---- Global state ---- */
static int i2c_handle_accel = -1;
static int i2c_handle_gyro  = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef enum { STATE_IDLE, STATE_FREEFALL, STATE_IMPACT } fall_state_t;
static fall_state_t fall_state = STATE_IDLE;
static struct timespec impact_start;

/* ---- Signal handler ---- */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "I2C write to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(handle, reg_buf, 1) != 0) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

/* ---- Sensor init ---- */
static int init_lsm6dsr(void) {
    /* Verify device identity */
    int id_accel = i2cReadByteData(i2c_handle_accel, WHO_AM_I_ACCEL);
    if (id_accel != WHO_AM_I_VAL) {
        fprintf(stderr, "Accel WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                id_accel & 0xFF, WHO_AM_I_VAL);
        return -1;
    }
    int id_gyro = i2cReadByteData(i2c_handle_gyro, WHO_AM_I_GYRO);
    if (id_gyro != WHO_AM_I_VAL) {
        fprintf(stderr, "Gyro WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                id_gyro & 0xFF, WHO_AM_I_VAL);
        return -1;
    }

    /* Gyro: ODR 104 Hz, FS 250 dps, no low-noise -> 0x60 */
    if (i2c_write_reg(i2c_handle_gyro, CTRL2_G, 0x60) != 0) return -1;

    /* Accel: ODR 104 Hz, FS 2 g, no low-power -> 0x60 */
    if (i2c_write_reg(i2c_handle_accel, CTRL1_XL, 0x60) != 0) return -1;

    return 0;
}

/* ---- Read sensor data ---- */
static int read_accel(float *ax, float *ay, float *az) {
    uint8_t buf[6];
    if (i2c_read_block(i2c_handle_accel, OUTX_L_XL, buf, 6) != 0) return -1;
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *ax = (float)raw_x / ACCEL_SCALE;
    *ay = (float)raw_y / ACCEL_SCALE;
    *az = (float)raw_z / ACCEL_SCALE;
    return 0;
}

static int read_gyro(float *gx, float *gy, float *gz) {
    uint8_t buf[6];
    if (i2c_read_block(i2c_handle_gyro, OUTX_L_G, buf, 6) != 0) return -1;
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *gx = (float)raw_x / GYRO_SCALE;
    *gy = (float)raw_y / GYRO_SCALE;
    *gz = (float)raw_z / GYRO_SCALE;
    return 0;
}

/* ---- Fall detection ---- */
static void detect_fall(float ax, float ay, float az) {
    float mag = sqrtf(ax * ax + ay * ay + az * az);
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);

    if (mag < FREEFALL_THRESHOLD_G) {
        if (fall_state != STATE_FREEFALL) {
            fall_state = STATE_FREEFALL;
            impact_start = now;
            printf("[%ld.%09ld] FREEFALL detected (magnitude %.3f g)\n",
                   (long)now.tv_sec, now.tv_nsec, mag);
        }
    } else if (fall_state == STATE_FREEFALL) {
        float elapsed = (now.tv_sec - impact_start.tv_sec) +
                        (now.tv_nsec - impact_start.tv_nsec) / 1e9f;
        if (elapsed > IMPACT_WINDOW_S) {
            if (mag > IMPACT_THRESHOLD_G) {
                fall_state = STATE_IMPACT;
                printf("[%ld.%09ld] IMPACT confirmed (magnitude %.3f g)\n",
                       (long)now.tv_sec, now.tv_nsec, mag);
            } else {
                printf("[%ld.%09ld] Impact threshold exceeded but not confirmed\n",
                       (long)now.tv_sec, now.tv_nsec);
            }
        }
    } else {
        fall_state = STATE_IDLE;
    }
}

/* ---- Logging ---- */
static void log_data(float ax, float ay, float az, float gx, float gy, float gz) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char time_str[32];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(log_file, "%s.%03ld,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            time_str, ts.tv_nsec / 1000000,
            ax, ay, az, gx, gy, gz);
    fflush(log_file);
}

/* ---- Cleanup ---- */
static void cleanup(void) {
    if (i2c_handle_accel >= 0) i2cClose(i2c_handle_accel);
    if (i2c_handle_gyro >= 0) i2cClose(i2c_handle_gyro);
    if (log_file) fclose(log_file);
    gpioTerminate();
}

/* ---- Main ---- */
int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle_accel = i2cOpen(I2C_BUS, LSM6DSR_ADDR_ACCEL, 0);
    if (i2c_handle_accel < 0) {
        fprintf(stderr, "Failed to open I2C for accel (addr 0x%02X): %d\n",
                LSM6DSR_ADDR_ACCEL, i2c_handle_accel);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle_gyro = i2cOpen(I2C_BUS, LSM6DSR_ADDR_GYRO, 0);
    if (i2c_handle_gyro < 0) {
        fprintf(stderr, "Failed to open I2C for gyro (addr 0x%02X): %d\n",
                LSM6DSR_ADDR_GYRO, i2c_handle_gyro);
        i2cClose(i2c_handle_accel);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_lsm6dsr() != 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "# LSM6DSR motion log started\n");
    fprintf(log_file, "# timestamp,ax_g,ay_g,az_g,gx_dps,gy_dps,gz_dps\n");
    fflush(log_file);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("LSM6DSR logging started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        float ax, ay, az, gx, gy, gz;

        if (read_accel(&ax, &ay, &az) != 0) {
            fprintf(stderr, "Accel read error; continuing\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }
        if (read_gyro(&gx, &gy, &gz) != 0) {
            fprintf(stderr, "Gyro read error; continuing\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        log_data(ax, ay, az, gx, gy, gz);
        detect_fall(ax, ay, az);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

