/* Expected WHO_AM_I value for ADIS16266 */
#define ADIS16266_WHO_AM_I_VAL   0xAD

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0x03     /* Mode 3: CPOL=1, CPHA=1 */

/* Scale factor for gyro data (degrees/sec/LSB) */
#define GYRO_SCALE_FACTOR 0.0305

/* Sampling interval in microseconds (10 ms) */
#define SAMPLE_INTERVAL_US 10000

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/*
 * Read a 16-bit register from the ADIS16266.
 * SPI protocol: send [reg | 0x80, 0x00], receive [don't care, data_low, data_high].
 * The response is 2 bytes: the low byte in the second received word,
 * the high byte in the third received word (after the command echo).
 */
static int adis16266_read_register(uint8_t reg, uint16_t *value) {
    char tx_buf[3];
    char rx_buf[3];
    int  result;

    tx_buf[0] = (char)(reg | 0x80);  /* OR with bit 7 to read */
    tx_buf[1] = 0x00;
    tx_buf[2] = 0x00;

    result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "SPI read transfer failed for register 0x%02X (returned %d)\n",
                reg, result);
        return -1;
    }

    /* Data is returned in rx_buf[1] (low byte) and rx_buf[2] (high byte) */
    *value = (uint16_t)(((uint8_t)rx_buf[1] << 8) | (uint8_t)rx_buf[2]);
    return 0;
}

/* Write a 16-bit register to the ADIS16266.
 * SPI protocol: send [reg & 0x7F, data_low, data_high], no response expected.
 */
static int adis16266_write_register(uint8_t reg, uint16_t value) {
    char tx_buf[3];
    int  result;

    tx_buf[0] = (char)(reg & 0x7F);  /* OR with bit 7 to write */
    tx_buf[1] = (char)(value & 0xFF);
    tx_buf[2] = (char)((value >> 8) & 0xFF);

    result = spiXfer(spi_handle, tx_buf, NULL, 3);
    if (result != 3) {
        fprintf(stderr, "SPI write transfer failed for register 0x%02X (returned %d)\n",
                reg, result);
        return -1;
    }
    return 0;
}

/* Initialize the ADIS16266: verify WHO_AM_I and configure control registers. */
static int adis16266_init(void) {
    uint16_t who_am_i = 0;

    if (adis16266_read_register(ADIS16266_REG_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != ADIS16266_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%04X, expected 0x%04X\n",
                who_am_i, ADIS16266_WHO_AM_I_VAL);
        return -1;
    }

    /*
     * CTRL_REG1 (0x0C): set ODR = 100 Hz (0x00), full-scale range = +/-250 deg/s (0x00)
     * Bits [11:10] ODR, [9:8] FS, [7:6] reserved, [5:4] reserved, [3:0] reserved.
     */
    if (adis16266_write_register(ADIS16266_REG_CTRL_REG1, 0x0000) != 0) {
        fprintf(stderr, "Failed to write CTRL_REG1\n");
        return -1;
    }

    /*
     * CTRL_REG2 (0x0E): enable gyro output (bit 0), set to 1 Hz update rate (bits 1:0 = 00).
     * Bits [7:6] reserved, [5:4] update rate (00 = 1 Hz), [3:0] reserved.
     */
    if (adis16266_write_register(ADIS16266_REG_CTRL_REG2, 0x0001) != 0) {
        fprintf(stderr, "Failed to write CTRL_REG2\n");
        return -1;
    }

    return 0;
}

/* Read gyroscope data (angular rate in degrees/sec). */
static int read_gyro_data(gyro_data_t *data) {
    uint16_t raw_x = 0, raw_y = 0, raw_z = 0;

    if (adis16266_read_register(ADIS16266_REG_GYRO_X_OUT, &raw_x) != 0) {
        fprintf(stderr, "Failed to read GYRO_X_OUT\n");
        return -1;
    }
    if (adis16266_read_register(ADIS16266_REG_GYRO_Y_OUT, &raw_y) != 0) {
        fprintf(stderr, "Failed to read GYRO_Y_OUT\n");
        return -1;
    }
    if (adis16266_read_register(ADIS16266_REG_GYRO_Z_OUT, &raw_z) != 0) {
        fprintf(stderr, "Failed to read GYRO_Z_OUT\n");
        return -1;
    }

    data->x = (float)raw_x * GYRO_SCALE_FACTOR;
    data->y = (float)raw_y * GYRO_SCALE_FACTOR;
    data->z = (float)raw_z * GYRO_SCALE_FACTOR;

    return 0;
}

/* Log gyroscope data to the CSV file. */
static int log_gyro_data(const gyro_data_t *data) {
    struct timespec ts;
    struct tm tm_info;
    char timestamp[40];

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp),
             sizeof(timestamp) - strlen(timestamp),
             ".%03ld", ts.tv_nsec / 1000000);

    if (fprintf(log_file, "%s,%.4f,%.4f,%.4f\n",
                timestamp, data->x, data->y, data->z) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    gyro_data_t gyro_data;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel: CE0 (GPIO8), 1 MHz, Mode 3 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize ADIS16266 */
    if (adis16266_init() != 0) {
        fprintf(stderr, "ADIS16266 initialisation failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file once */
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open gyro_log.csv");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,X_deg_s,Y_deg_s,Z_deg_s\n");
        fflush(log_file);
    }

    /* Register signal handler for graceful shutdown */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Logging gyroscope data to gyro_log.csv (Ctrl+C to stop)...\n");

    /* Main sampling loop */
    while (!terminate) {
        if (read_gyro_data(&gyro_data) == 0) {
            if (log_gyro_data(&gyro_data) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Gyro read failed, continuing...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

