#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- L3G4200D constants (verified against datasheet) ---- */
#define L3G4200D_ADDR        0x29
#define WHO_AM_I             0x0F
#define WHO_AM_I_EXPECTED    0xD3
#define CTRL_REG1            0x20
#define CTRL_REG4            0x23
#define OUT_X_L              0x28
#define OUT_X_H              0x29
#define OUT_Y_L              0x2A
#define OUT_Y_H              0x2B
#define OUT_Z_L              0x2C
#define OUT_Z_H              0x2D

#define SENSITIVITY_MDPS_LSB 114.285f   /* 8.75 mdps / LSB => 114.285 LSB/mdps */
#define SAMPLE_PERIOD_US     10000      /* 10 ms */
#define MAX_RETRIES          3

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a byte to an I2C register with retry on transient errors.     */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int i2c_write_byte_retry(int handle, uint8_t reg, uint8_t value)
{
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        int rc = i2cWriteByteData(handle, reg, value);
        if (rc == 0)
            return 0;
        fprintf(stderr, "Warning: i2cWriteByteData(reg=0x%02X, val=0x%02X) failed "
                        "(attempt %d/%d, rc=%d)\n",
                reg, value, attempt + 1, MAX_RETRIES, rc);
        gpioDelay(1000);  /* 1 ms back-off */
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Read a byte from an I2C register with retry on transient errors.    */
/* Returns the byte value (0-255) on success, -1 on failure.           */
/* ------------------------------------------------------------------ */
static int i2c_read_byte_retry(int handle, uint8_t reg)
{
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        int rc = i2cReadByteData(handle, reg);
        if (rc >= 0)
            return rc;
        fprintf(stderr, "Warning: i2cReadByteData(reg=0x%02X) failed "
                        "(attempt %d/%d, rc=%d)\n",
                reg, attempt + 1, MAX_RETRIES, rc);
        gpioDelay(1000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Read a block of bytes from consecutive registers with retry.       */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int i2c_read_block_retry(int handle, uint8_t reg,
                                uint8_t *buf, uint32_t len)
{
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
        if (rc == (int)len)
            return 0;
        fprintf(stderr, "Warning: i2cReadI2CBlockData(reg=0x%02X, len=%u) "
                        "failed (attempt %d/%d, rc=%d)\n",
                reg, len, attempt + 1, MAX_RETRIES, rc);
        gpioDelay(1000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Initialise the L3G4200D: verify WHO_AM_I, then configure CTRL_REG1.   */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int gyro_init(int handle)
{
    int id = i2c_read_byte_retry(handle, WHO_AM_I);
    if (id < 0) {
        fprintf(stderr, "Error: cannot read WHO_AM_I register (bus error or "
                        "sensor absent).\n");
        return -1;
    }
    if (id != WHO_AM_I_EXPECTED) {
        fprintf(stderr, "Error: WHO_AM_I mismatch: got 0x%02X, expected 0x%02X.\n",
                id, WHO_AM_I_EXPECTED);
        return -1;
    }

    /*
     * CTRL_REG1 (0x20):
     *   ODR[3:0] = 0010  -> 100 Hz output rate
     *   FS[1:0]  = 00    -> +/- 2 g full scale
     *   BDU      = 1     -> block data update
     * Bits [7:4] must be 0 for the default ODR/FS combination.
     */
    if (i2c_write_byte_retry(handle, CTRL_REG1, 0x21) != 0) {
        fprintf(stderr, "Error: failed to write CTRL_REG1.\n");
        return -1;
    }

    /*
     * CTRL_REG4 (0x23):
     *   FS_SEL = 00  -> +/- 2 g full scale (match ODR[3:0] above)
     *   HR       = 0  -> high-resolution mode disabled (ODR 100 Hz)
     *   BOOT     = 0  -> boot mode clear
     */
    if (i2c_write_byte_retry(handle, CTRL_REG4, 0x00) != 0) {
        fprintf(stderr, "Error: failed to write CTRL_REG4.\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read gyroscope data (6 bytes from OUT_X_L through OUT_Z_H).          */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int gyro_read(int handle, float *x, float *y, float *z)
{
    uint8_t buf[6];
    if (i2c_read_block_retry(handle, OUT_X_L, buf, sizeof(buf)) != 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    *x = (float)raw_x / SENSITIVITY_MDPS_LSB;
    *y = (float)raw_y / SENSITIVITY_MDPS_LSB;
    *z = (float)raw_z / SENSITIVITY_MDPS_LSB;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append one CSV record with a nanosecond-precision timestamp.        */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float x, float y, float z)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_local;
    localtime_r(&ts.tv_sec, &tm_local);

    char ts_str[40];
    strftime(ts_str, sizeof(ts_str), "%Y-%m-%d %H:%M:%S", &tm_local);
    snprintf(ts_str + strlen(ts_str),
             sizeof(ts_str) - strlen(ts_str),
             ".%09ld", ts.tv_nsec);

    fprintf(fp, "%s,%.4f,%.4f,%.4f\n", ts_str, x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        /*
         * L3G4200D library cleanup: write 0x00 to CTRL_REG1 to shut down
         * the device, then release the I2C handle.
         */
        (void)i2c_write_byte_data(g_i2c_handle, CTRL_REG1, 0x00);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialise pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus 1 at the L3G4200D address ---- */
    g_i2c_handle = i2cOpen(1, L3G4200D_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (rc=%d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Initialise sensor ---- */
    if (gyro_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: L3G4200D initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file (write header) ---- */
    g_log_file = fopen("gyro_log.csv", "w");
    if (g_log_file == NULL) {
        perror("fopen gyro_log.csv");
        cleanup();
        return EXIT_FAILURE;
    }
    fprintf(g_log_file, "Timestamp,X,Y,Z\n");
    fflush(g_log_file);

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("L3G4200D gyroscope logging started. Press Ctrl+C to stop.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        float x, y, z;
        if (gyro_read(g_i2c_handle, &x, &y, &z) == 0) {
            log_data(g_log_file, x, y, z);
        } else {
            fprintf(stderr, "Warning: gyro read failed; continuing.\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

