/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        /*
         * L3G4200D library cleanup: write 0x00 to CTRL_REG1 to shut down
         * the device, then release the I2C handle.
