{
    /* ---- Initialise pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus 1 at the L3G4200D address ---- */
    g_i2c_handle = i2cOpen(1, L3G4200D_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (rc=%d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Initialise sensor ---- */
    if (gyro_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: L3G4200D initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file (write header) ---- */
    g_log_file = fopen("gyro_log.csv", "w");
    if (g_log_file == NULL) {
        perror("fopen gyro_log.csv");
        cleanup();
        return EXIT_FAILURE;
    }
    fprintf(g_log_file, "Timestamp,X,Y,Z\n");
    fflush(g_log_file);

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("L3G4200D gyroscope logging started. Press Ctrl+C to stop.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        float x, y, z;
        if (gyro_read(g_i2c_handle, &x, &y, &z) == 0) {
            log_data(g_log_file, x, y, z);
        } else {
            fprintf(stderr, "Warning: gyro read failed; continuing.\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

