#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE_NAME "flame_events.log"
#define POLL_INTERVAL_US 500000  /* 500 ms */

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (Ctrl+C)                       */
/* ------------------------------------------------------------------ */
static void signal_handler(int signal)
{
    (void)signal;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a timestamped line to the log file and flush immediately       */
/* ------------------------------------------------------------------ */
static void log_event(const char *message)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r() failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s – %s\n", timestamp, message);
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file is not open.\n");
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — closes log file and calls pigpio cleanup           */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int ret;

    /* --- Initialize pigpio library ---------------------------------- */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "pigpio initialisation failed (code %d).\n", ret);
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO17 as input with internal pull-up ------------- */
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);

    /* --- Open log file in append mode -------------------------------- */
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handler for SIGINT --------------------------- */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n",
                strerror(errno));
    }

    printf("Flame sensor monitoring started on GPIO%d.\n", FLAME_SENSOR_GPIO);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main polling loop ------------------------------------------ */
    while (program_running) {
        int level = gpioRead(FLAME_SENSOR_GPIO);

        if (level == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading GPIO%d (PI_BAD_GPIO).\n",
                    FLAME_SENSOR_GPIO);
            log_event("ERROR: Failed to read flame sensor GPIO");
        } else {
            /* KY-026 DO is active-LOW: LOW (0) => flame detected */
            const char *message = (level == 0)
                ? "FLAME DETECTED!"
                : "No flame detected.";

            log_event(message);

            if (level == 0) {
                printf("%s\n", message);
            }
        }

        /* Sleep 500 ms; gpioDelay is microseconds */
        gpioDelay(POLL_INTERVAL_US);
    }

    /* --- Graceful shutdown ------------------------------------------ */
    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

