#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_I2C_ADDR   0x28
#define LOG_FILE       "vibration_log.csv"
#define SAMPLE_MS      100

/*
 * Omron D7S-0001 vibration sensor I2C read sequence (16-bit big-endian,
 * two bytes per axis, no register address prefix).
 *   reg_addr = 0x00  -> X axis
 *   reg_addr = 0x02  -> Y axis
 *   reg_addr = 0x04  -> Z axis
 */
#define REG_X 0x00
#define REG_Y 0x02
#define REG_Z 0x04

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    return sigaction(SIGINT, &sa, NULL);
}

/*
 * Write an ISO-8601 UTC timestamp into buf (size >= 25).
 * Returns 0 on success, -1 on failure.
 */
static int get_iso8601_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        return -1;
    }
    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit big-endian axis value from the D7S.
 * Returns 0 on success and stores the value in *out; returns -1 on error.
 */
static int read_axis(int fd, uint8_t reg, int16_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    uint8_t buf[2];
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int log_data(FILE *fp, const char *ts, int16_t x, int16_t y, int16_t z)
{
    if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
        return -1;
    }
    if (fflush(fp) != 0) {
        return -1;
    }
    return 0;
}

int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    if (install_signal_handler() != 0) {
        fprintf(stderr, "Error: failed to install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, D7S_I2C_ADDR) < 0) {
        fprintf(stderr, "Error: cannot set I2C slave address 0x%02X: %s\n",
                D7S_I2C_ADDR, strerror(errno));
        goto cleanup;
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    /* Write header only if the file is empty */
    if (fseek(fp, 0, SEEK_END) == 0) {
        long sz = ftell(fp);
        if (sz == 0) {
            if (fprintf(fp, "Timestamp,X,Y,Z\n") < 0 || fflush(fp) != 0) {
                fprintf(stderr, "Error: failed to write CSV header: %s\n",
                        strerror(errno));
                goto cleanup;
            }
        }
    } else {
        fprintf(stderr, "Warning: cannot determine CSV file size: %s\n",
                strerror(errno));
    }

    printf("D7S vibration logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t x = 0, y = 0, z = 0;
        int ok = 1;

        if (read_axis(fd, REG_X, &x) != 0) {
            fprintf(stderr, "Warning: read X axis failed: %s\n", strerror(errno));
            ok = 0;
        }
        if (ok && read_axis(fd, REG_Y, &y) != 0) {
            fprintf(stderr, "Warning: read Y axis failed: %s\n", strerror(errno));
            ok = 0;
        }
        if (ok && read_axis(fd, REG_Z, &z) != 0) {
            fprintf(stderr, "Warning: read Z axis failed: %s\n", strerror(errno));
            ok = 0;
        }

        if (ok) {
            char ts[32];
            if (get_iso8601_timestamp(ts, sizeof(ts)) != 0) {
                fprintf(stderr, "Warning: cannot get timestamp: %s\n",
                        strerror(errno));
            } else {
                if (log_data(fp, ts, x, y, z) != 0) {
                    fprintf(stderr, "Warning: failed to write log entry: %s\n",
                            strerror(errno));
                }
            }
        }

        /* Sleep SAMPLE_MS milliseconds, but wake early on signal */
        for (int ms = 0; ms < SAMPLE_MS && g_running; ms += 10) {
            usleep(10 * 1000);
        }
    }

    printf("\nShutting down cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        fclose(fp);
    }
    if (fd >= 0) {
        close(fd);
    }
    return rc;
}

