#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MMA8452Q_ADDR  0x1D
#define WHO_AM_I_REG   0x0D
#define WHO_AM_I_VAL   0x33
#define CTRL_REG1      0x2A
#define CTRL_REG2      0x2B
#define OUT_X_MSB      0x01
#define OUT_X_LSB      0x02
#define OUT_Y_MSB      0x03
#define OUT_Y_LSB      0x04
#define OUT_Z_MSB      0x05
#define OUT_Z_LSB      0x06
#define TILT_THRESHOLD 45.0f
#define LOG_FILE       "fall_log.txt"
#define POLL_DELAY_US  10000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg 0x%02X, val 0x%02X) failed: %s\n", reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C block write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C block read (reg 0x%02X, len %d) failed: %s\n", reg, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_accelerometer(int fd) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, WHO_AM_I_REG, &who_am_i) != 0) {
        return -1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, WHO_AM_I_VAL);
        return -1;
    }

    /* Standby: clear ACTIVE bit in CTRL_REG1 */
    if (i2c_write_reg8(fd, CTRL_REG1, 0x00) != 0) {
        return -1;
    }
    usleep(1000);

    /* Data rate = 100 Hz (ODR = 0x08), normal mode (ZYXDA = 0x08) */
    if (i2c_write_reg8(fd, CTRL_REG1, 0x08) != 0) {
        return -1;
    }
    usleep(1000);

    return 0;
}

static int read_accelerometer(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_block(fd, OUT_X_MSB, buf, 6) != 0) {
        return -1;
    }
    *x = (int16_t)(((uint16_t)buf[0] << 8) | buf[1]) >> 4;
    *y = (int16_t)(((uint16_t)buf[2] << 8) | buf[3]) >> 4;
    *z = (int16_t)(((uint16_t)buf[4] << 8) | buf[5]) >> 4;
    return 0;
}

static float calculate_tilt(int16_t x, int16_t y, int16_t z) {
    float fx = (float)x;
    float fy = (float)y;
    float fz = (float)z;
    return atan2f(sqrtf(fx * fx + fy * fy), fz) * 180.0f / (float)M_PI;
}

static void log_fall(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_fp, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
    fflush(g_log_fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MMA8452Q_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MMA8452Q_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    if (init_accelerometer(g_i2c_fd) != 0) {
        fprintf(stderr, "Accelerometer initialization failed.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("Monitoring accelerometer data (100 Hz)... Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t x, y, z;
        if (read_accelerometer(g_i2c_fd, &x, &y, &z) != 0) {
            fprintf(stderr, "Read error, continuing...\n");
            usleep(POLL_DELAY_US);
            continue;
        }

        float tilt = calculate_tilt(x, y, z);
        if (tilt > TILT_THRESHOLD) {
            log_fall(x, y, z);
            printf("Fall detected! Tilt: %.2f degrees\n", tilt);
        }

        usleep(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

