#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define LIS3MDL_ADDR   0x19
#define LIS3MDL_REG_CRA_R    0x20
#define LIS3MDL_REG_CRB_R    0x21
#define LIS3MDL_REG_MR_R     0x22
#define LIS3MDL_REG_OUT_X_L  0x28
#define LIS3MDL_REG_OUT_X_H  0x29
#define LIS3MDL_REG_OUT_Y_L  0x2A
#define LIS3MDL_REG_OUT_Y_H  0x2B
#define LIS3MDL_REG_OUT_Z_L  0x2C
#define LIS3MDL_REG_OUT_Z_H  0x2D

#define SCALE_FACTOR_MG  0.146f   /* mG per LSB at ±4 gauss */
#define OFFSET_MG        0.0f
#define METAL_THRESHOLD_MG 800.0f
#define SAMPLE_RATE_HZ   10
#define MAX_RETRIES      3

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        perror("i2c_write_reg8: write");
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_reg8: write");
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        perror("i2c_read_reg8: read");
        return -1;
    }
    return 0;
}

static int init_lis3mdl(int fd)
{
    /* CRA_R: temp enable, ODR 10 Hz, high-resolution off */
    if (i2c_write_reg8(fd, LIS3MDL_REG_CRA_R, 0x10) < 0)
        return -1;
    /* CRB_R: full-scale ±4 gauss, reboot off */
    if (i2c_write_reg8(fd, LIS3MDL_REG_CRB_R, 0x00) < 0)
        return -1;
    /* MR_R: continuous-conversion mode */
    if (i2c_write_reg8(fd, LIS3MDL_REG_MR_R, 0x00) < 0)
        return -1;
    return 0;
}

static int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t xl, xh, yl, yh, zl, zh;
    if (i2c_read_reg8(fd, LIS3MDL_REG_OUT_X_L, &xl) < 0) return -1;
    if (i2c_read_reg8(fd, LIS3MDL_REG_OUT_X_H, &xh) < 0) return -1;
    if (i2c_read_reg8(fd, LIS3MDL_REG_OUT_Y_L, &yl) < 0) return -1;
    if (i2c_read_reg8(fd, LIS3MDL_REG_OUT_Y_H, &yh) < 0) return -1;
    if (i2c_read_reg8(fd, LIS3MDL_REG_OUT_Z_L, &zl) < 0) return -1;
    if (i2c_read_reg8(fd, LIS3MDL_REG_OUT_Z_H, &zh) < 0) return -1;
    *x = (int16_t)((xh << 8) | xl);
    *y = (int16_t)((yh << 8) | yl);
    *z = (int16_t)((zh << 8) | zl);
    return 0;
}

static void calibrate_data(int16_t x, int16_t y, int16_t z,
                           float *x_mg, float *y_mg, float *z_mg)
{
    *x_mg = (float)x * SCALE_FACTOR_MG + OFFSET_MG;
    *y_mg = (float)y * SCALE_FACTOR_MG + OFFSET_MG;
    *z_mg = (float)z * SCALE_FACTOR_MG + OFFSET_MG;
}

static float calculate_magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

static void log_data(FILE *fp, float x, float y, float z, float mag)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            x, y, z, mag);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open(" I2C_BUS ")");
        return EXIT_FAILURE;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    int init_ok = 0;
    for (int attempt = 1; attempt <= MAX_RETRIES; ++attempt) {
        if (init_lis3mdl(g_i2c_fd) == 0) {
            init_ok = 1;
            break;
        }
        fprintf(stderr, "LIS3MDL init attempt %d/%d failed\n", attempt, MAX_RETRIES);
        if (attempt < MAX_RETRIES)
            usleep(100000); /* 100 ms backoff */
    }
    if (!init_ok) {
        fprintf(stderr, "LIS3MDL initialization failed after %d attempts\n", MAX_RETRIES);
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    g_log_fp = fopen("magnetic_log.txt", "a");
    if (!g_log_fp) {
        perror("fopen(magnetic_log.txt)");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("LIS3MDL logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
