#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/*
 * ADXL354B SPI Interface (Mode 0, 1 MHz)
 *   Byte 0: Command (0x0B) | Read/Write bit (0x80) | Data byte 0
 *   Byte 1: Data byte 1
 *   Byte 2: Data byte 2
 *   Byte 3: Data byte 3 (if MSB of command is set)
 *
 * ADXL354B Register Map (from datasheet)
 *   Register 0x02: Part ID (read-only, should return 0x0D)
 *   Register 0x03: XDATA_L (read/write, 20-bit signed)
 *   Register 0x04: XDATA_H
 *   Register 0x05: YDATA_L
 *   Register 0x06: YDATA_H
 *   Register 0x07: ZDATA_L
 *   Register 0x08: ZDATA_H
 *   Register 0x09: Status (read-only, bit 0 = STABLE, bit 1 = RUN)
 *   Register 0x0A: Power Control (read/write, bit 0 = RUN, bit 1 = STANDBY)
 *   Register 0x0B: Reset (write-only, 0x00 = standby, 0x01 = reset)
 */

#define SPI_CHANNEL    0
#define SPI_SPEED      1000000  /* 1 MHz */
#define SPI_FLAGS      0        /* Mode 0, active-low CE */

#define ADXL354B_REG_PARTID      0x02
#define ADXL354B_REG_XDATA_L     0x03
#define ADXL354B_REG_STATUS      0x09
#define ADXL354B_REG_POWER_CTL   0x0A
#define ADXL354B_REG_RESET       0x0B

#define ADXL354B_PARTID_VALUE    0x0D
#define ADXL354B_RESET_CMD      0x01

#define LOG_FILE_NAME  "vibration_log.txt"
#define SAMPLE_PERIOD_US 100000  /* 100 ms */
#define MAX_RETRIES     3

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/*
 * Read a single register from the ADXL354B.
 * SPI frame: [cmd|R/W|0x00, 0x00, 0x00]  -> response on last byte.
 */
static int adxl354b_read_register(uint8_t reg, uint8_t *value) {
    char tx[3] = { (char)(reg | 0x80), 0x00, 0x00 };
    char rx[3] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI read transfer failed for register 0x%02X\n", reg);
        return -1;
    }
    *value = (uint8_t)rx[2];
    return 0;
}

/*
 * Write a single register in the ADXL354B.
 * SPI frame: [cmd|W|data, 0x00, 0x00]
 */
static int adxl354b_write_register(uint8_t reg, uint8_t value) {
    char tx[3] = { (char)(reg | 0x00), (char)value, 0x00 };
    char rx[3] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI write transfer failed for register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

/*
 * Read acceleration data from the ADXL354B.
 * SPI frame: [0x0B|R|0x00, 0x00, 0x00]  -> response: [X_msb, X_lsb, Y_msb, Y_lsb, Z_msb, Z_lsb]
 * 20-bit signed values are assembled from the lower 12 bits of each 3-byte group.
 */
static int adxl354b_read_acceleration(accelerometer_data_t *data) {
    char tx[3] = { (char)(ADXL354B_REG_XDATA_L | 0x80 | 0x40), 0x00, 0x00 };
    char rx[3] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed for acceleration read\n");
        return -1;
    }

    uint8_t x_msb = (uint8_t)rx[0];
    uint8_t x_lsb = (uint8_t)rx[1];
    uint8_t y_msb = (uint8_t)rx[2];

    /* 20-bit left-justified: bits [19:4] hold the signed data */
    int32_t x_raw = ((int32_t)x_msb << 12) | ((int32_t)x_lsb << 4);
    int32_t y_raw = ((int32_t)y_msb << 12) | ((int32_t)(x_lsb & 0x0F) << 8);

    /* Sign-extend from 20 bits to 32 bits */
    if (x_raw & 0x80000) x_raw |= 0xFFF00000;
    if (y_raw & 0x80000) y_raw |= 0xFFF00000;

    data->x = (int16_t)x_raw;
    data->y = (int16_t)y_raw;
    data->z = 0;  /* Z axis not read in this burst; read separately below */
    return 0;
}

/*
 * Read the Z-axis acceleration data.
 * SPI frame: [0x0B|R|0x00, 0x00, 0x00]  -> response: [X_msb, X_lsb, Y_msb, Y_lsb, Z_msb, Z_lsb]
 */
static int adxl354b_read_z_acceleration(int16_t *z) {
    char tx[3] = { (char)(ADXL354B_REG_XDATA_L | 0x80 | 0x40), 0x00, 0x00 };
    char rx[3] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed for Z-axis read\n");
        return -1;
    }

    uint8_t z_msb = (uint8_t)rx[0];
    uint8_t z_lsb = (uint8_t)rx[1];

    int32_t z_raw = ((int32_t)z_msb << 12) | ((int32_t)z_lsb << 4);
    *z = (int16_t)z_raw;
    return 0;
}

static int adxl354b_reset(void) {
    if (adxl354b_write_register(ADXL354B_REG_RESET, ADXL354B_RESET_CMD) != 0) {
        fprintf(stderr, "Failed to reset ADXL354B\n");
        return -1;
    }
    gpioDelay(1000);  /* 1 ms reset settling time */
    return 0;
}

static int adxl354b_verify(void) {
    uint8_t partid = 0;
    if (adxl354b_read_register(ADXL354B_REG_PARTID, &partid) != 0) {
        fprintf(stderr, "Failed to read PARTID\n");
        return -1;
    }
    if (partid != ADXL354B_PARTID_VALUE) {
        fprintf(stderr, "Unexpected PARTID: 0x%02X (expected 0x%02X)\n", partid, ADXL354B_PARTID_VALUE);
        return -1;
    }
    printf("ADXL354B detected (PARTID=0x%02X)\n", partid);
    return 0;
}

static int initialize_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d: %s\n", SPI_CHANNEL, pigpio_error(spi_handle));
        return -1;
    }
    return 0;
}

static int log_data(const accelerometer_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, X: %d, Y: %d, Z: %d\n", timestamp, data->x, data->y, data->z) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (adxl354b_reset() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (adxl354b_verify() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Clear RUN bit to enter standby, then wait for STABLE */
    if (adxl354b_write_register(ADXL354B_REG_POWER_CTL, 0x00) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }
    gpioDelay(1000);

    /* Set RUN bit to start measurement */
    if (adxl354b_write_register(ADXL354B_REG_POWER_CTL, 0x02) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE_NAME);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging vibration data to %s. Press Ctrl+C to stop.\n", LOG_FILE_NAME);

    while (!terminate) {
        accelerometer_data_t data;
        int16_t z;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && !terminate) {
            if (adxl354b_read_acceleration(&data) == 0 && adxl354b_read_z_acceleration(&z) == 0) {
                data.z = z;
                success = 1;
                break;
            }
            retries++;
            gpioDelay(1000);
        }

        if (success) {
            if (log_data(&data) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data after %d retries\n", MAX_RETRIES);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

