#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ADIS16362 Register Addresses */
#define ADIS16362_REG_X_GYRO_OUT  0x04
#define ADIS16362_REG_Y_GYRO_OUT  0x06
#define ADIS16362_REG_Z_GYRO_OUT  0x08
#define ADIS16362_REG_X_ACCEL_OUT 0x0A
#define ADIS16362_REG_Y_ACCEL_OUT 0x0C
#define ADIS16362_REG_Z_ACCEL_OUT 0x0E

/* Scaling factors (from ADIS16362 datasheet) */
#define GYRO_SCALE  0.05f   /* degrees/sec per LSB */
#define ACCEL_SCALE 0.0025f /* g per LSB */

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_BAUD    1000000 /* 1 MHz */
#define SPI_FLAGS   0x03    /* Mode 3: CPOL=1, CPHA=1 (active-high, sampled on trailing edge) */

/* Timing */
#define SAMPLE_DELAY_US 10000 /* 10 ms -> ~100 Hz */

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float gyro_x, gyro_y, gyro_z;
    float accel_x, accel_y, accel_z;
} imu_data_t;

/* ---- Signal handler ---- */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* ---- Cleanup helper ---- */
static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ---- Read a 16-bit register (address + MSB, then dummy read) ---- */
static int read_register_16(int handle, uint8_t reg, int16_t *out) {
    char tx[2], rx[2];
    int  ret;

    /* Phase 1: send address with MSB set */
    tx[0] = (char)(reg | 0x80);
    tx[1] = 0x00;
    ret = spiXfer(handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI xfer (addr phase) failed: %s\n", strerror(errno));
        return -1;
    }
    /* Data is returned on the second transfer */
    (void)tx; (void)rx;

    /* Phase 2: dummy transfer to clock out data */
    tx[0] = 0x00;
    tx[1] = 0x00;
    ret = spiXfer(handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI xfer (data phase) failed: %s\n", strerror(errno));
        return -1;
    }

    *out = (int16_t)(((uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

/* ---- Read a single axis ---- */
static int read_axis_16(int handle, uint8_t reg, int16_t *out) {
    return read_register_16(handle, reg, out);
}

/* ---- Read all six axes ---- */
static int read_imu_data(int handle, imu_data_t *data) {
    int16_t raw;

    if (read_axis_16(handle, ADIS16362_REG_X_GYRO_OUT, &raw) != 0) return -1;
    data->gyro_x = (float)raw * GYRO_SCALE;

    if (read_axis_16(handle, ADIS16362_REG_Y_GYRO_OUT, &raw) != 0) return -1;
    data->gyro_y = (float)raw * GYRO_SCALE;

    if (read_axis_16(handle, ADIS16362_REG_Z_GYRO_OUT, &raw) != 0) return -1;
    data->gyro_z = (float)raw * GYRO_SCALE;

    if (read_axis_16(handle, ADIS16362_REG_X_ACCEL_OUT, &raw) != 0) return -1;
    data->accel_x = (float)raw * ACCEL_SCALE;

    if (read_axis_16(handle, ADIS16362_REG_Y_ACCEL_OUT, &raw) != 0) return -1;
    data->accel_y = (float)raw * ACCEL_SCALE;

    if (read_axis_16(handle, ADIS16362_REG_Z_ACCEL_OUT, &raw) != 0) return -1;
    data->accel_z = (float)raw * ACCEL_SCALE;

    return 0;
}

/* ---- Log one data row ---- */
static int log_data(FILE *fp, const imu_data_t *data) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%ld.%09ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
                (long)ts.tv_sec, ts.tv_nsec,
                data->gyro_x, data->gyro_y, data->gyro_z,
                data->accel_x, data->accel_y, data->accel_z) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    imu_data_t imu_data;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI device */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen("imu_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header */
    if (fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n") < 0) {
        fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fflush(log_file);

    /* Install signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADIS16362 IMU logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (!terminate) {
        if (read_imu_data(spi_handle, &imu_data) != 0) {
            fprintf(stderr, "Failed to read IMU data, skipping sample\n");
        } else {
            if (log_data(log_file, &imu_data) != 0) {
                fprintf(stderr, "Failed to log data, continuing\n");
            }
        }
        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

