{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        printf("[%s] %s", ts, msg);
    } else {
        printf("[unknown] %s", msg);
    }
    fflush(stdout);
}

int main(void)
{
    int rc;
    int pigpio_initialized = 0;
    int line_requested = 0;

