    int handle = gpioOpen(GPIO_CHIP_NAME, PI_OPEN_MODE_READ);
    if (handle < 0) {
        fprintf(stderr, "gpioOpen(%s) failed (code %d): %s\n",
                GPIO_CHIP_NAME, handle, strerror(errno));
        goto cleanup;
    }

    /* Request the GPIO line for input */
    rc = gpioSetMode(handle, GPIO_PIN, PI_INPUT);
    if (rc != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed (code %d): %s\n",
                GPIO_PIN, rc, strerror(errno));
        goto cleanup;
    }

    line_requested = 1;

    log_message(SELF_PARK_MSG);

    /* Simulate self-parking routine (busy-wait-free sleep) */
    for (int i = 0; i < 5 && g_running; i++) {
        sleep(1);
    }

    if (!g_running) {
        log_message("Interrupted by signal. Exiting.\n");
        goto cleanup;
    }

    log_message(SELF_PARK_COMP);

cleanup:
    if (line_requested) {
        gpioSetMode(handle, GPIO_PIN, PI_INPUT); /* release line */
    }
    if (pigpio_initialized) {
        gpioTerminate();
    }
    return EXIT_SUCCESS;
}

