/*
 * KY-032 IR Obstacle Sensor Monitor (Raspberry Pi 3 Model B+)
 *
 * Wiring:
 *   Sensor 1 OUT -> GPIO17 (physical pin 11)
 *   Sensor 2 OUT -> GPIO27 (physical pin 13)
 *   VCC         -> 3.3 V (physical pin 1)
 *   GND         -> GND   (physical pin 9)
 *
 * The KY-032 module drives its output LOW when an obstacle is detected
 * and HIGH when the path is clear.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o ky032_monitor ky032_monitor.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./ky032_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 27
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/*
 * Returns a statically-buffered "YYYY-MM-DD HH:MM:SS" timestamp.
 * Not thread-safe; acceptable for this single-threaded application.
 */
static const char *get_timestamp(void)
{
    static char ts[20];
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        snprintf(ts, sizeof(ts), "----/--/-- --:--:--");
        return ts;
    }
    struct tm tmv;
    if (localtime_r(&now, &tmv) == NULL) {
        snprintf(ts, sizeof(ts), "----/--/-- --:--:--");
        return ts;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv);
    return ts;
}

/*
 * Reads both sensor lines in a single pigpio bulk-read call.
 * Returns 0 on success, -1 on error.
 */
static int read_sensors(int *s1, int *s2)
{
    int vals[2] = { SENSOR1_GPIO, SENSOR2_GPIO };
    int rc = gpioReadBulk(2, vals);
    if (rc < 0) {
        fprintf(stderr, "gpioReadBulk failed: %s\n", pigpio_error(rc));
        return -1;
    }
    *s1 = vals[0];
    *s2 = vals[1];
    return 0;
}

/*
 * Interprets the active-low KY-032 output:
 *   0 -> obstacle detected
 *   1 -> path clear
 */
static const char *interpret_detection(int s1, int s2)
{
    if (s1 == 0 && s2 == 0) return "Both sensors detect obstacle";
    if (s1 == 0)            return "Sensor 1 detects obstacle";
    if (s2 == 0)            return "Sensor 2 detects obstacle";
    return "No obstacle detected";
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure both pins as inputs (no pull-ups; the KY-032 module
     * drives the line actively). */
    if (gpioSetMode(SENSOR1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Allow the sensor modules to settle after power-up. */
    gpioDelay(500000);  /* 500 ms */

    printf("KY-032 Obstacle Monitor started. Press Ctrl+C to exit.\n");
    printf("%-20s %-20s %-20s\n", "Timestamp", "Sensor1", "Sensor2");
    printf("------------------------------------------------\n");

    while (g_running) {
        int s1, s2;

        if (read_sensors(&s1, &s2) != 0) {
            fprintf(stderr, "Sensor read error; continuing.\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        const char *status = interpret_detection(s1, s2);
        printf("%-20s %-20s %-20s\n",
               get_timestamp(),
               s1 == 0 ? "LOW" : "HIGH",
               s2 == 0 ? "LOW" : "HIGH");
        printf("------------------------------------------------\n");

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

