/*
 * ADIS16266 Gyroscope Reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADIS16266 VCC  -> 3.3V (Pin 1)
 *   ADIS16266 GND  -> GND  (Pin 9)
 *   ADIS16266 SCLK -> GPIO11 (SPI0 SCLK, Pin 23)
 *   ADIS16266 SDI  -> GPIO9  (SPI0 MISO, Pin 21)
 *   ADIS16266 SDO  -> GPIO10 (SPI0 MOSI, Pin 19)
 *   ADIS16266 CS   -> GPIO8  (SPI0 CE0,  Pin 24)
 *
 * Build: gcc -O2 -Wall -o adis16266 adis16266.c
 * Run:   sudo ./adis16266
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_MODE        SPI_MODE_3
#define SPI_BITS        8

/* ADIS16266 register addresses (MSB of address byte = 1 for read) */
#define ADIS16266_REG_XGYRO_OUT  0x04
#define ADIS16266_REG_YGYRO_OUT  0x06
#define ADIS16266_REG_ZGYRO_OUT  0x08

/* Scale factor: 0.02 degrees per second per LSB */
#define ADIS16266_SCALE_FACTOR  0.02f

#define SAMPLE_PERIOD_MS  100

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    g_spi_fd = fd;
    return 0;
}

static void spi_close(void)
{
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/*
 * ADIS16266 two-transfer read: send [reg | 0x80] then [0x00],
 * resulting in a 2-byte data payload.
 */
static int spi_read_register(uint8_t reg, int16_t *out)
{
    if (out == NULL) {
        return -1;
    }

    uint8_t tx[3] = { (uint8_t)(reg | 0x80), 0x00, 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed (reg 0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = (int16_t)(((uint16_t)rx[1] << 8) | (uint16_t)rx[2]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Data acquisition                                                   */
/* ------------------------------------------------------------------ */
static int read_gyro_data(float *x_rate, float *y_rate, float *z_rate)
{
    int16_t raw_x, raw_y, raw_z;

    if (spi_read_register(ADIS16266_REG_XGYRO_OUT, &raw_x) < 0) {
        return -1;
    }
    if (spi_read_register(ADIS16266_REG_YGYRO_OUT, &raw_y) < 0) {
        return -1;
    }
    if (spi_read_register(ADIS16266_REG_ZGYRO_OUT, &raw_z) < 0) {
        return -1;
    }

    *x_rate = (float)raw_x * ADIS16266_SCALE_FACTOR;
    *y_rate = (float)raw_y * ADIS16266_SCALE_FACTOR;
    *z_rate = (float)raw_z * ADIS16266_SCALE_FACTOR;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (spi_init() < 0) {
        return EXIT_FAILURE;
    }

    printf("ADIS16266 Gyroscope Reader\n");
    printf("SPI: %s | Mode %d | %d Hz | %d bits\n",
           SPI_DEVICE, SPI_MODE, SPI_SPEED_HZ, SPI_BITS);
    printf("Press Ctrl+C to exit.\n\n");

    struct timespec sleep_time = { 0, SAMPLE_PERIOD_MS * 1000000L };

    while (g_running) {
        float x_rate, y_rate, z_rate;

        if (read_gyro_data(&x_rate, &y_rate, &z_rate) < 0) {
            fprintf(stderr, "Error reading gyroscope data. Retrying...\n");
            nanosleep(&sleep_time, NULL);
            continue;
        }

        printf("X: %+.4f deg/s | Y: %+.4f deg/s | Z: %+.4f deg/s\n",
               x_rate, y_rate, z_rate);

        if (nanosleep(&sleep_time, NULL) < 0) {
            if (errno == EINTR) {
                continue;  /* Signal received; loop will check g_running */
            }
            fprintf(stderr, "Error during sleep: %s\n", strerror(errno));
            break;
        }
    }

    printf("\nExiting...\n");
    spi_close();
    return EXIT_SUCCESS;
}

