#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* LSM6DSR I2C address (SA0 tied to GND) */
#define LSM6DSR_ADDR 0x1D

/* LSM6DSR register addresses */
#define WHO_AM_I_REG   0x0F
#define CTRL1_XL       0x10
#define CTRL2_G        0x11
#define OUTX_L_G       0x22
#define OUTX_L_XL      0x28

/* Expected device ID */
#define LSM6DSR_ID     0x6D

/* Accelerometer and gyroscope full-scale selections */
#define ACCEL_FS_4G    0x00
#define GYRO_FS_245    0x00

/* Global variables for signal handling and cleanup */
static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

/* Signal handler for Ctrl+C */
static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

/* Function to initialize the LSM6DSR */
static int init_lsm6dsr(int handle) {
    /* Verify device identity */
    int who_am_i = i2cReadByteData(handle, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != LSM6DSR_ID) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, LSM6DSR_ID);
        return -1;
    }

    /* Configure accelerometer: 4 g full scale, 100 Hz ODR, XYZ axes enabled */
    if (i2cWriteByteData(handle, CTRL1_XL, ACCEL_FS_4G | 0x80) < 0) {
        fprintf(stderr, "Error writing to CTRL1_XL register\n");
        return -1;
    }

    /* Configure gyroscope: 245 dps full scale, 100 Hz ODR, XYZ axes enabled */
    if (i2cWriteByteData(handle, CTRL2_G, GYRO_FS_245 | 0x80) < 0) {
        fprintf(stderr, "Error writing to CTRL2_G register\n");
        return -1;
    }

    return 0;
}

/* Function to read accelerometer data */
static int read_accelerometer(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(handle, OUTX_L_XL, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading accelerometer data: %d\n", result);
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

/* Function to read gyroscope data */
static int read_gyroscope(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(handle, OUTX_L_G, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading gyroscope data: %d\n", result);
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the LSM6DSR address */
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the LSM6DSR */
    if (init_lsm6dsr(i2c_handle) < 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handling for Ctrl+C */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    int16_t accel_x, accel_y, accel_z;
    int16_t gyro_x, gyro_y, gyro_z;

    /* Main loop */
    while (running) {
        /* Read accelerometer data */
        if (read_accelerometer(i2c_handle, &accel_x, &accel_y, &accel_z) < 0) {
            fprintf(stderr, "Error reading accelerometer data, exiting\n");
            break;
        }

        /* Read gyroscope data */
        if (read_gyroscope(i2c_handle, &gyro_x, &gyro_y, &gyro_z) < 0) {
            fprintf(stderr, "Error reading gyroscope data, exiting\n");
            break;
        }

        /* Print the data to stdout */
        printf("AccelX: %d, AccelY: %d, AccelZ: %d, GyroX: %d, GyroY: %d, GyroZ: %d\n",
               accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
        fflush(stdout);

        /* Delay for 100 ms */
        gpioDelay(100000); /* 100 ms in microseconds */
    }

    /* Cleanup */
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

