/*
 * FXOS8700 I2C reader for Raspberry Pi 4 Model B
 * Bus: I2C-1 (SDA=GPIO2, SCL=GPIO3)
 * Build: gcc -O2 -Wall -o fxos8700 fxos8700.c -lm
 */
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- FXOS8700 constants (datasheet rev 1.2) ---- */
#define FXOS8700_ADDRESS         (0x1D << 1)   /* SA0 tied high on Adafruit breakout */
#define FXOS8700_REG_STATUS     0x00
#define FXOS8700_REG_OUT_X_MSB  0x01
#define FXOS8700_REG_M_OUT_X_MSB 0x33
#define FXOS8700_REG_WHO_AM_I   0x0D
#define FXOS8700_WHO_AM_I_VAL   0xC7
#define FXOS8700_REG_CTRL_REG1  0x2A
#define FXOS8700_REG_CTRL_REG2  0x2B
#define FXOS8700_REG_XYZ_DATA_CFG 0x0E
#define FXOS8700_REG_M_CTRL_REG1 0x5B
#define FXOS8700_REG_M_CTRL_REG2 0x5C

#define STATUS_DRDY_BIT  (1u << 0)
#define STATUS_OVL_BIT   (1u << 1)

#define I2C_BUS            1
#define SAMPLE_PERIOD_US   100000   /* 100 ms */
#define MAX_RETRIES        3

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- low-level I2C helpers ---- */

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "[I2C] read block reg 0x%02X failed (rc=%d, expected %u)\n",
                reg, rc, len);
        return -1;
    }
    return 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "[I2C] write byte reg 0x%02X val 0x%02X failed (rc=%d)\n",
                reg, val, rc);
        return -1;
    }
    return 0;
}

/* ---- sensor init ---- */

static int fxos8700_init(int handle)
{
    uint8_t who;

    /* Verify device identity */
    if (i2c_read_block(handle, FXOS8700_REG_WHO_AM_I, &who, 1) != 0)
        return -1;
    if (who != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "[FXOS8700] WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode to configure registers */
    if (i2c_write_byte(handle, FXOS8700_REG_CTRL_REG1, 0x00) != 0)
        return -1;

    /* Accelerometer full-scale ±2g (default) */
    if (i2c_write_byte(handle, FXOS8700_REG_XYZ_DATA_CFG, 0x00) != 0)
        return -1;

    /* Magnetometer full-scale 4 Gauss (default) */
    if (i2c_write_byte(handle, FXOS8700_REG_M_CTRL_REG1, 0x1F) != 0)
        return -1;

    /* M_CTRL_REG2: continuous conversion mode */
    if (i2c_write_byte(handle, FXOS8700_REG_M_CTRL_REG2, 0x20) != 0)
        return -1;

    /* CTRL_REG2: ODR 100 Hz, no one-shot */
    if (i2c_write_byte(handle, FXOS8700_REG_CTRL_REG2, 0x20) != 0)
        return -1;

    /* CTRL_REG1: active mode */
    if (i2c_write_byte(handle, FXOS8700_REG_CTRL_REG1, 0x01) != 0)
        return -1;

    return 0;
}

/* ---- read combined block ---- */

static int fxos8700_read(int handle,
                         int16_t *ax, int16_t *ay, int16_t *az,
                         int16_t *mx, int16_t *my, int16_t *mz)
{
    uint8_t raw[12];
    int16_t acc[3], mag[3];
    int ok = 0;

    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        if (i2c_read_block(handle, FXOS8700_REG_OUT_X_MSB, raw, sizeof(raw)) == 0) {
            ok = 1;
            break;
        }
        gpioDelay(1000); /* 1 ms back-off */
    }
    if (!ok) {
        fprintf(stderr, "[FXOS8700] read combined block failed after %d attempts\n",
                MAX_RETRIES);
        return -1;
    }

    /* 14-bit left-aligned accelerometer: shift right 2 to get 14-bit */
    acc[0] = (int16_t)((raw[0] << 8) | raw[1]) >> 2;
    acc[1] = (int16_t)((raw[2] << 8) | raw[3]) >> 2;
    acc[2] = (int16_t)((raw[4] << 8) | raw[5]) >> 2;

    /* 16-bit magnetometer (little-endian) */
    mag[0] = (int16_t)((raw[6]  << 8) | raw[7]);
    mag[1] = (int16_t)((raw[8]  << 8) | raw[9]);
    mag[2] = (int16_t)((raw[10] << 8) | raw[11]);

    *ax = acc[0];
    *ay = acc[1];
    *az = acc[2];
    *mx = mag[0];
    *my = mag[1];
    *mz = mag[2];
    return 0;
}

int main(void)
{
    int handle = -1;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    handle = i2cOpen(I2C_BUS, FXOS8700_ADDRESS, 0);
    if (handle < 0) {
        fprintf(stderr, "i2cOpen failed (rc=%d)\n", handle);
        goto cleanup_gpio;
    }

    if (fxos8700_init(handle) != 0) {
        fprintf(stderr, "FXOS8700 initialisation failed\n");
        goto cleanup_i2c;
    }

    printf("FXOS8700 ready on I2C bus %d, address 0x%02X.\n", I2C_BUS,
           FXOS8700_ADDRESS & 0xFF);
    printf("Press Ctrl+C to stop.\n\n");

    while (g_running) {
        int16_t ax, ay, az, mx, my, mz;

        if (fxos8700_read(handle, &ax, &ay, &az, &mx, &my, &mz) == 0) {
            printf("Accel: X=%6d  Y=%6d  Z=%6d  (g)\n", ax, ay, az);
            printf("Magn:  X=%6d  Y=%6d  Z=%6d  (Gauss)\n", mx, my, mz);
        } else {
            fprintf(stderr, "Read failed; will retry next cycle.\n");
        }

