/*
 * ADXL345 Tilt Monitor for Raspberry Pi 5
 *
 * Reads acceleration from an ADXL345 accelerometer over I2C and logs
 * timestamped tilt events to /var/log/tilt_events.log whenever the
 * tilt angle exceeds a threshold.
 *
 * Wiring:
 *   ADXL345 SDA -> GPIO2 (pin 3)
 *   ADXL345 SCL -> GPIO3 (pin 5)
 *   ADXL345 VDD -> 3.3 V
 *   ADXL345 GND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o tilt_monitor tilt_monitor.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./tilt_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS              1       /* /dev/i2c-1 on Raspberry Pi 5          */
#define ADXL345_ADDR         0x53    /* ADXL345 default I2C address (ALT=0)   */

#define REG_DEVID            0x00
#define REG_THRESH_ACT       0x28
#define REG_ACT_INACT_CTL    0x27
#define REG_BW_RATE          0x2C
#define REG_POWER_CTL        0x2D
#define REG_DATA_FORMAT      0x31
#define REG_DATAX0           0x32

#define DEVID_EXPECTED       0xE5    /* ADXL345 device ID                     */

#define TILT_THRESHOLD       30.0f   /* degrees                               */
#define SAMPLE_PERIOD_US     100000  /* 100 ms                                */
#define LOG_FILE             "/var/log/tilt_events.log"

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_fp    = NULL;

/* ----------------------------- Prototypes -------------------------------- */

static void signal_handler(int sig);
static int  adxl345_init(void);
static int  adxl345_read_accel(float *ax, float *ay, float *az);
static float calculate_tilt_angle(float ax, float ay, float az);
static void log_event(float ax, float ay, float az, float tilt);
static void cleanup(void);

/* ----------------------------- Signal Handler ---------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- ADXL345 Init ------------------------------ */

static int adxl345_init(void)
{
    int handle = i2cOpen(I2C_BUS, ADXL345_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (handle=%d). "
                        "Check wiring and that i2c-dev is enabled.\n", handle);
        return -1;
    }

    /* Verify device identity */
    int devid = i2cReadByteData(handle, REG_DEVID);
    if (devid < 0) {
        fprintf(stderr, "[ERROR] Failed to read DEVID register.\n");
        i2cClose(handle);
        return -1;
    }
    if (devid != DEVID_EXPECTED) {
        fprintf(stderr, "[ERROR] DEVID mismatch: got 0x%02X, expected 0x%02X.\n",
                devid, DEVID_EXPECTED);
        i2cClose(handle);
        return -1;
    }

    /* Standby mode to allow configuration changes */
    if (i2cWriteByteData(handle, REG_POWER_CTL, 0x00) < 0) {
        fprintf(stderr, "[ERROR] Failed to set standby mode.\n");
        i2cClose(handle);
        return -1;
    }

    /* Data format: full resolution, +/-200 g range, right-justified */
    if (i2cWriteByteData(handle, REG_DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "[ERROR] Failed to set DATA_FORMAT.\n");
        i2cClose(handle);
        return -1;
    }

    /* Output data rate: 100 Hz (0x0A) */
    if (i2cWriteByteData(handle, REG_BW_RATE, 0x0A) < 0) {
        fprintf(stderr, "[ERROR] Failed to set BW_RATE.\n");
        i2cClose(handle);
        return -1;
    }

    /* Measurement mode */
    if (i2cWriteByteData(handle, REG_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "[ERROR] Failed to set measurement mode.\n");
        i2cClose(handle);
        return -1;
    }

    return handle;
}

/* ----------------------------- Read Accel -------------------------------- */

static int adxl345_read_accel(float *ax, float *ay, float *az)
{
    char data[6];
    int  bytes;

    bytes = i2cReadI2CBlockData(g_i2c_handle, REG_DATAX0, data, 6);
    if (bytes != 6) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData returned %d (expected 6).\n",
                bytes);
        return -1;
    }

    /* ADXL345 outputs little-endian: LSB first, then MSB */
    int16_t raw_x = (int16_t)(((uint8_t)data[1] << 8) | (uint8_t)data[0]);
    int16_t raw_y = (int16_t)(((uint8_t)data[3] << 8) | (uint8_t)data[2]);
    int16_t raw_z = (int16_t)(((uint8_t)data[5] << 8) | (uint8_t)data[4]);

    /* Full-resolution mode: 4 mg/LSB => divide by 4096 for g */
    const float scale = 1.0f / 4096.0f;
    *ax = (float)raw_x * scale;
    *ay = (float)raw_y * scale;
    *az = (float)raw_z * scale;

    return 0;
}

/* ----------------------------- Tilt Calc --------------------------------- */

static float calculate_tilt_angle(float ax, float ay, float az)
{
    float norm = sqrtf(ax * ax + ay * ay + az * az);
    if (norm < 1e-6f) {
        return 0.0f;                 /* avoid divide-by-zero for flat surfaces */
    }
    return atan2f(ay, sqrtf(ax * ax + az * az)) * 180.0f / (float)M_PI;
}

/* ----------------------------- Log Event --------------------------------- */

static void log_event(float ax, float ay, float az, float tilt)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_fp,
            "%s - Tilt: %.2f deg (AX=%.3f, AY=%.3f, AZ=%.3f)\n",
            timestamp, tilt, ax, ay, az);
    fflush(g_log_fp);
}

/* ----------------------------- Cleanup ----------------------------------- */

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */

int main(void)
{
    float ax, ay, az, tilt;

    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- I2C init --- */
    g_i2c_handle = adxl345_init();
    if (g_i2c_handle < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("[FATAL] fopen(" LOG_FILE ")");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("ADXL345 tilt monitor running. Threshold: %.1f deg. "
           "Press Ctrl+C to exit.\n", TILT_THRESHOLD);

    /* --- Main loop --- */
    while (g_running) {
        if (adxl345_read_accel(&ax, &ay, &az) == 0) {
            tilt = calculate_tilt_angle(ax, ay, az);

            if (tilt > TILT_THRESHOLD) {
                log_event(ax, ay, az, tilt);
                printf("Tilt exceeded %.1f deg! Logged.\n", TILT_THRESHOLD);
            }
        } else {
            fprintf(stderr, "[WARN] I2C read failure; will retry next cycle.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

