                printf("Tilt exceeded %.1f deg! Logged.\n", TILT_THRESHOLD);
            }
        } else {
            fprintf(stderr, "[WARN] I2C read failure; will retry next cycle.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

