#define SENSOR_PIN 17          /* BCM 17, physical pin 11 */
#define WINDOW_SECONDS 5
#define SAMPLE_DELAY_US 1000   /* 1 ms between samples */
#define PAUSE_SECONDS 1

static volatile sig_atomic_t g_terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead(%d) failed: %s\n", pin, pigpio_error(v));
        return -1;
    }
    return v;
}

static int count_high_readings(int pin, int seconds)
{
    int count = 0;
    time_t start = time(NULL);
    if (start == (time_t)-1) {
        perror("time()");
        return -1;
    }

    while (!g_terminate) {
        time_t now = time(NULL);
        if (now == (time_t)-1) {
            perror("time()");
            return -1;
        }
        if (difftime(now, start) >= seconds)
            break;

        int v = read_sensor(pin);
        if (v < 0)
            return -1;
        if (v == 1)
            count++;
    }
    return count;
}

static void print_timestamp(void)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time()");
        return;
