    long val = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0' || val < 0 || val != (long)val) {
        fprintf(stderr, "Error: threshold must be a positive integer (got '%s').\n", argv[1]);
        return EXIT_FAILURE;
