        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed.\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring KY-038 sound sensor on GPIO%d (BCM). Threshold: %ld high readings per %d s window.\n",
           SENSOR_PIN, val, WINDOW_SECONDS);
    printf("Press Ctrl+C to exit.\n");

    while (!g_terminate) {
        int count = count_high_readings(SENSOR_PIN, WINDOW_SECONDS);
        if (count < 0) {
            fprintf(stderr, "Error reading sensor during window.\n");
            break;
        }

        print_timestamp();
        if (count > (int)val) {
            printf("ALERT: %d high readings exceed threshold %ld\n", count, val);
        } else {
            printf("Status: %d high readings (threshold %ld)\n", count, val);
        }
        fflush(stdout);

        if (!g_terminate)
            sleep(PAUSE_SECONDS);
    }

    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

