/*
 * door_access.c — Raspberry Pi 4 Model B
 *
 * Two TIP120-driven 5 V active-HIGH relay modules on GPIO17 (Door A)
 * and GPIO27 (Door B) control 12 V electromagnetic door locks.
 * A HIGH level energizes the relay (door closed); LOW de-energizes
 * it (door unlocked for 5 s).  A random six-digit security code is
 * generated on each entry attempt and compared to user input.
 * Matches are logged to access_log.txt.
 *
 * Build:  gcc -Wall -o door_access door_access.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define DOOR_A_PIN  17          /* BCM 17 */
#define DOOR_B_PIN  27          /* BCM 27 */
#define UNLOCK_SEC  5           /* seconds to keep door unlocked */
#define MIN_CODE    100000      /* 100000..999999 */
#define MAX_CODE    999999
#define LOG_FILE    "access_log.txt"

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int generate_code(int *code)
{
    if (code == NULL)
        return -1;

    *code = (rand() % (MAX_CODE - MIN_CODE + 1)) + MIN_CODE;
    return 0;
}

static int read_code(int *code)
{
    if (code == NULL)
        return -1;

    char buf[16];
    printf("Enter security code: ");
    fflush(stdout);

    if (fgets(buf, sizeof(buf), stdin) == NULL) {
        if (feof(stdin))
            return -1;
        perror("fgets");
        return -1;
    }

    /* strip trailing newline */
    buf[strcspn(buf, "\r\n")] = '\0';

    char *endptr = NULL;
    errno = 0;
    long val = strtol(buf, &endptr, 10);
    if (errno != 0 || endptr == buf || *endptr != '\0') {
        fprintf(stderr, "Invalid input. Please enter a numeric value.\n");
        return -1;
    }
    *code = (int)val;
    return 0;
}

static int log_access(int code)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time");
        fclose(fp);
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%d\n", ts, code) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

static int unlock_door(struct gpiod_line *line, int duration_sec)
{
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("gpiod_line_set_value(HIGH)");
        return -1;
    }
    sleep(duration_sec);
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("gpiod_line_set_value(LOW)");
        return -1;
    }
    return 0;
}

int main(void)
{
    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    srand((unsigned int)time(NULL));

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name(gpiochip4)");
        return EXIT_FAILURE;
    }

    struct gpiod_line *line_a = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (line_a == NULL) {
        perror("gpiod_chip_get_line(DOOR_A_PIN)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct gpiod_line *line_b = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (line_b == NULL) {
        perror("gpiod_chip_get_line(DOOR_B_PIN)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line_a, "door_access", 0) < 0) {
        perror("gpiod_line_request_output(DOOR_A_PIN)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line_b, "door_access", 0) < 0) {
        perror("gpiod_line_request_output(DOOR_B_PIN)");
        gpiod_line_release(line_a);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Door access control system started.\n");
    printf("Enter security code: ");
    fflush(stdout);

    while (g_running) {
        int code;
        if (generate_code(&code) != 0) {
            fprintf(stderr, "Failed to generate code.\n");
            break;
        }
        printf("Generated code: %d\n", code);

        if (read_code(&code) != 0) {
            if (!g_running)
                break;
            fprintf(stderr, "Access denied.\n");
            continue;
        }

        if (code == code) {
            printf("Access granted.\n");
            if (unlock_door(line_a, UNLOCK_SEC) != 0)
                break;
            if (unlock_door(line_b, UNLOCK_SEC) != 0)
                break;
            if (log_access(code) != 0)
                break;
        } else {
            fprintf(stderr, "Access denied.\n");
        }
    }

    /* Ensure doors are locked on exit */
    gpiod_line_set_value(line_a, 0);
    gpiod_line_set_value(line_b, 0);

    gpiod_line_release(line_a);
    gpiod_line_release(line_b);
    gpiod_chip_close(chip);

    printf("Door access control system stopped.\n");
    return EXIT_SUCCESS;
}

