#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x22
#define BH1750_CONT_HIGH_RES_MODE 0x10
#define BH1750_CONV_TIME_MS 180
#define LOG_FILE "light_log.txt"
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_bh1750(int handle, float *lux) {
    char buf[2];
    int rc;

    /* Trigger one-time measurement in continuous high-resolution mode */
    rc = i2cWriteByteData(handle, BH1750_ADDR, BH1750_CONT_HIGH_RES_MODE);
    if (rc < 0) {
        fprintf(stderr, "Error writing to BH1750 (trigger): %s\n", strerror(errno));
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(BH1750_CONV_TIME_MS * 1000);

    /* Read 2 bytes of result */
    rc = i2cReadDevice(handle, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "Error reading from BH1750 (rc=%d): %s\n", rc, strerror(errno));
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static void log_data(float lux) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) != NULL) {
