#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <syslog.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MPR121_ADDR 0x2A
#define PWM_PIN 18
#define PORT 12345
#define LOG_FILE "frequency_log.txt"
#define SECRET_KEY "MySecretKey"
#define BUFFER_SIZE 1024
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define TOUCH_SAMPLE_US 20000
#define PWM_DURATION_US 5000000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int server_fd = -1;
static int client_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write(int fd, uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(fd, buf, 2) != 0) {
        syslog(LOG_ERR, "I2C write to reg 0x%02X failed: %s", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpr121_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(fd, reg_buf, 1) != 0) {
        syslog(LOG_ERR, "I2C write (reg select 0x%02X) failed: %s", reg, strerror(errno));
        return -1;
    }
    if (i2cReadDevice(fd, (char *)buf, len) != len) {
        syslog(LOG_ERR, "I2C read from reg 0x%02X failed: %s", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpr121_init(int fd) {
    if (mpr121_write(fd, 0x80, 0x63) != 0) return -1;
    gpioDelay(10000);

    if (mpr121_write(fd, 0x2B, 0x01) != 0) return -1;
