    if (mpr121_write(fd, 0x4B, 0x0F) != 0) return -1;
    if (mpr121_write(fd, 0x4C, 0x0F) != 0) return -1;
    if (mpr121_write(fd, 0x4D, 0x0F) != 0) return -1;
    if (mpr121_write(fd, 0x4E, 0x0F) != 0) return -1;
    if (mpr121_write(fd, 0x4F, 0x0F) != 0) return -1;

    if (mpr121_write(fd, 0x5E, 0x0C) != 0) return -1;
    if (mpr121_write(fd, 0x5F, 0x00) != 0) return -1;
    if (mpr121_write(fd, 0x60, 0x00) != 0) return -1;
    if (mpr121_write(fd, 0x61, 0x00) != 0) return -1;
