    if (mpr121_write(fd, 0x64, 0x00) != 0) return -1;
    if (mpr121_write(fd, 0x65, 0x00) != 0) return -1;
    if (mpr121_write(fd, 0x66, 0x00) != 0) return -1;
    if (mpr121_write(fd, 0x67, 0x00) != 0) return -1;
    if (mpr121_write(fd, 0x68, 0x00) != 0) return -1;
    if (mpr121_write(fd, 0x69, 0x00) != 0) return -1;
    if (mpr121_write(fd, 0x6A, 0x00) != 0) return -1;
    if (mpr121_write(fd, 0x6B, 0x00) != 0) return -1;
    if (mpr121_write(fd, 0x6C, 0x00) != 0) return -1;
    if (mpr121_write(fd, 0x6D, 0x00) != 0) return -1;
