    if (mpr121_write(fd, 0x77, 0x0F) != 0) return -1;
    if (mpr121_write(fd, 0x78, 0x0F) != 0) return -1;
    if (mpr121_write(fd, 0x79, 0x0F) != 0) return -1;
    if (mpr121_write(fd, 0x7A, 0x0F) != 0) return -1;
    if (mpr121_write(fd, 0x7B, 0x0F) != 0) return -1;
    if (mpr121_write(fd, 0x7C, 0x0F) != 0) return -1;
    if (mpr121_write(fd, 0x7D, 0x0F) != 0) return -1;
    if (mpr121_write(fd, 0x7E, 0x0F) != 0) return -1;
    if (mpr121_write(fd, 0x7F, 0x0F) != 0) return -1;

    if (mpr121_write(fd, 0x80, 0x00) != 0) return -1;
    gpioDelay(10000);

    return 0;
}

static int read_touch_data(int fd, uint16_t *touch_data) {
    uint8_t buf[24];
    if (mpr121_read_block(fd, 0x00, buf, 24) != 0) return -1;
    *touch_data = ((uint16_t)buf[1] << 8) | buf[0];
    return 0;
}

static int play_tone(int freq, int duration_us) {
    if (gpioSetPWMfrequency(PWM_PIN, freq) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency to %d Hz", freq);
        return -1;
    }
    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) < 0) {
        syslog(LOG_ERR, "Failed to set PWM range");
        return -1;
    }
    if (gpioPWM(PWM_PIN, PWM_RANGE / 2) < 0) {
        syslog(LOG_ERR, "Failed to start PWM on GPIO%d", PWM_PIN);
        return -1;
    }
    gpioDelay(duration_us);
    gpioPWM(PWM_PIN, 0);
    return 0;
}

static int log_frequency(const char *filename, int freq) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        syslog(LOG_ERR, "Failed to open log file %s: %s", filename, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Frequency: %d Hz\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, freq);
    fclose(fp);
    return 0;
}

static int authenticate_command(const char *command) {
    size_t len = strlen(command);
    if (len < 16) return 0;
    if (strncmp(command, "MOTION_DETECTED:", 16) != 0) return 0;
    if (len - 16 < strlen(SECRET_KEY)) return 0;
    if (strstr(command + 16, SECRET_KEY) == NULL) return 0;
    return 1;
}

static void cleanup(void) {
    if (client_fd >= 0) { close(client_fd); client_fd = -1; }
    if (server_fd >= 0) { close(server_fd); server_fd = -1; }
    if (i2c_fd >= 0) { i2cClose(i2c_fd); i2c_fd = -1; }
    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("theremin_server", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set signal handlers: %s", strerror(errno));
        closelog();
        return 1;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return 1;
    }

    i2c_fd = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %d at addr 0x%02X: %s", I2C_BUS, MPR121_ADDR, strerror(errno));
        gpioTerminate();
        closelog();
        return 1;
    }

    if (mpr121_init(i2c_fd) != 0) {
        syslog(LOG_ERR, "Failed to initialize MPR121");
        cleanup();
        return 1;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        syslog(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        cleanup();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        syslog(LOG_ERR, "setsockopt failed: %s", strerror(errno));
        cleanup();
        return 1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        syslog(LOG_ERR, "Bind failed: %s", strerror(errno));
        cleanup();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        syslog(LOG_ERR, "Listen failed: %s", strerror(errno));
        cleanup();
        return 1;
    }

    syslog(LOG_INFO, "Theremin server listening on port %d", PORT);

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            if (errno == EINTR && !running) break;
            syslog(LOG_ERR, "Accept failed: %s", strerror(errno));
            continue;
        }

        char client_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_addr.sin_addr, client_ip, sizeof(client_ip));
        syslog(LOG_INFO, "Connection from %s:%d", client_ip, ntohs(client_addr.sin_port));

        char buffer[BUFFER_SIZE];
        ssize_t bytes_received = recv(client_fd, buffer, BUFFER_SIZE - 1, 0);
        if (bytes_received < 0) {
            syslog(LOG_ERR, "recv failed: %s", strerror(errno));
            close(client_fd);
            client_fd = -1;
            continue;
        }
        if (bytes_received == 0) {
            close(client_fd);
            client_fd = -1;
            continue;
        }
        buffer[bytes_received] = '\0';

        syslog(LOG_INFO, "Received command: %s", buffer);

        if (authenticate_command(buffer)) {
            uint16_t touch_data;
            if (read_touch_data(i2c_fd, &touch_data) == 0) {
                int freq = (touch_data & 0x0FFF) + 100;
                syslog(LOG_INFO, "Touch data: 0x%04X, Frequency: %d Hz", touch_data, freq);
                if (play_tone(freq, PWM_DURATION_US) == 0) {
                    log_frequency(LOG_FILE, freq);
                } else {
                    syslog(LOG_ERR, "Failed to play tone");
                }
            } else {
                syslog(LOG_ERR, "Failed to read touch data");
            }
        } else {
            syslog(LOG_WARNING, "Invalid or incomplete command");
        }

        close(client_fd);
        client_fd = -1;
        gpioDelay(100000);
    }

    syslog(LOG_INFO, "Shutting down...");
    cleanup();
    return 0;
}

