/*
 * LSM303DLHC Magnetometer (LSM303) reader for Raspberry Pi Zero W.
 *
 * Reads the Z-axis magnetic field magnitude over I2C bus 1 (SDA1/SCL1)
 * using the LSM303's default data register (0x00) and drives an LED on
 * GPIO17 (BCM) with hardware PWM whose brightness is proportional to
 * the Z-axis field strength.
 *
 * Build:  gcc -O2 -Wall -o lsm303_led lsm303_led.c -lpigpio -lrt
 * Run:    sudo ./lsm303_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* ---- LSM303DLHC constants ---- */
#define I2C_BUS          "/dev/i2c-1"
#define LSM303_ADDR      0x19   /* LSM303DLHC default I2C address (SA0 tied high) */
#define LSM303_CRA_REG   0x00   /* Temp enable / data register select */
#define LSM303_CRA_VAL   0x00   /* Use default: temp sensor disabled, data reg 0x00 */
#define LSM303_MR_REG    0x02   /* Operating mode register */
#define LSM303_MR_VAL    0x00   /* Ultra-high performance mode */
#define LSM303_OUT_X_H_M 0x08  /* Magnetometer X-axis MSB register */
#define LSM303_OUT_X_L_M 0x09
#define LSM303_OUT_Y_H_M 0x0A
#define LSM303_OUT_Y_L_M 0x0B
#define LSM303_OUT_Z_H_M 0x0C
#define LSM303_OUT_Z_L_M 0x0D

/* ---- Application constants ---- */
#define LED_PIN          17     /* BCM GPIO17 */
#define SAMPLE_PERIOD_US 100000 /* 100 ms in microseconds */
#define I2C_RETRIES      3
#define I2C_RETRY_DELAY  10000  /* 10 ms between retries */

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Open the I2C bus and set the slave address.                         */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an 8-bit register.                           */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "write(reg 0x%02X, val 0x%02X): %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read `len` bytes starting at `reg` using a combined SMBus-style     */
/* transaction: write register address, then read.                     */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    /* Write the register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "write(reg ptr 0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }

    /* Read the data bytes */
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "read(reg 0x%02X, len %zu): %s\n",
                reg, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the LSM303DLHC: temp sensor disabled, ultra-high perf mode.*/
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int lsm303_init(int fd)
{
    if (i2c_write_reg8(fd, LSM303_CRA_REG, LSM303_CRA_VAL) < 0)
        return -1;
    if (i2c_write_reg8(fd, LSM303_MR_REG, LSM303_MR_VAL)    < 0)
        return -1;

    /* Allow the sensor to settle into ultra-high performance mode */
    gpioDelay(2000); /* 2 ms */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the magnetometer and return the Z-axis field magnitude.       */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int lsm303_read_z(int fd, int16_t *out)
{
    uint8_t raw[6];

    for (int attempt = 0; attempt < I2C_RETRIES; ++attempt) {
        if (i2c_read_block(fd, LSM303_OUT_Z_H_M, raw, sizeof(raw)) == 0) {
            int16_t z = (int16_t)((raw[0] << 8) | raw[1]);
            *out = z;
            return 0;
        }
        if (attempt < I2C_RETRIES - 1)
            gpioDelay(I2C_RETRY_DELAY);
    }

    return -1;
}

/* ------------------------------------------------------------------ */
/* Map the Z-axis field magnitude to an LED brightness value (0-255).*/
/* ------------------------------------------------------------------ */
static uint8_t z_to_brightness(int16_t z)
{
    /*
     * LSM303DLHC magnetometer output range: +/- 1.3 Gauss (10-bit).
     * Default gain setting (gain = 1) yields 10 mGauss / LSB.
     * Map: 0 Gauss -> 0, 1.3 Gauss -> 255.
     */
    const float scale = 255.0f / 1.3f;
    return (uint8_t)((float)z * scale);
}

/* ------------------------------------------------------------------ */
/* Set the LED PWM brightness.                                        */
/* ------------------------------------------------------------------ */
static void led_set_brightness(uint8_t brightness)
{
    if (gpioPWM(LED_PIN, brightness) < 0)
        fprintf(stderr, "gpioPWM(%d): %s\n", LED_PIN, pigpio_error(0));
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times.                       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    /* Ensure LED is off and PWM is stopped */
    gpioWrite(LED_PIN, 0);
    gpioPWM(LED_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* ---- LED pin setup ---- */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    /* ---- Open I2C ---- */
    g_i2c_fd = i2c_open(I2C_BUS, LSM303_ADDR);
    if (g_i2c_fd < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Sensor init ---- */
    if (lsm303_init(g_i2c_fd) < 0) {
        fprintf(stderr, "LSM303 init failed (sensor may be absent or bus fault)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen("mag_log.txt", "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(mag_log.txt): %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    fprintf(stderr, "LSM303DLHC magnetometer reader started. Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        int16_t z = 0;

        if (lsm303_read_z(g_i2c_fd, &z) == 0) {
            uint8_t brightness = z_to_brightness(z);
            led_set_brightness(brightness);

            time_t now = time(NULL);
            struct tm tm_buf;
            struct tm *t = localtime_r(&now, &tm_buf);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

            fprintf(g_log_fp, "%s, Z: %d, brightness: %u\n",
                    ts, z, brightness);
            fflush(g_log_fp);
        } else {
            fprintf(stderr, "Skipping sample due to I2C error.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ---- Graceful cleanup ---- */
    fprintf(stderr, "\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

