    /* ---- Open I2C ---- */
    g_i2c_fd = i2c_open(I2C_BUS, LSM303_ADDR);
    if (g_i2c_fd < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Sensor init ---- */
    if (lsm303_init(g_i2c_fd) < 0) {
        fprintf(stderr, "LSM303 init failed (sensor may be absent or bus fault)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen("mag_log.txt", "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(mag_log.txt): %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    fprintf(stderr, "LSM303DLHC magnetometer reader started. Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        int16_t z = 0;

        if (lsm303_read_z(g_i2c_fd, &z) == 0) {
            uint8_t brightness = z_to_brightness(z);
            led_set_brightness(brightness);

            time_t now = time(NULL);
            struct tm tm_buf;
            struct tm *t = localtime_r(&now, &tm_buf);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

            fprintf(g_log_fp, "%s, Z: %d, brightness: %u\n",
                    ts, z, brightness);
            fflush(g_log_fp);
        } else {
            fprintf(stderr, "Skipping sample due to I2C error.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ---- Graceful cleanup ---- */
    fprintf(stderr, "\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

