/*
 * HMC5883L magnetometer reader with running-average hard-iron offset correction.
 *
 * Board:  Raspberry Pi Zero W  (I2C bus 1, GPIO2=SDA, GPIO3=SCL)
 * Sensor: HMC5883L  (I2C address 0x1E, default)
 *
 * Build:  gcc -O2 -Wall -Wextra -o hmc5883l_offset hmc5883l_offset.c
 * Run:    ./hmc5883l_offset
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- HMC5883L constants (verified against datasheet) ---- */
#define HMC5883L_ADDR        0x1E
#define HMC5883L_CONFIG_A    0x00
#define HMC5883L_CONFIG_B    0x01
#define HMC5883L_MODE        0x02
#define HMC5883L_DATA_X_MSB  0x03
#define HMC5883L_DATA_Z_MSB  0x05
#define HMC5883L_DATA_Y_MSB  0x07

/*
 * Config A: 8-average, 15 Hz, normal measurement
 *  0x70 = 0111 0000
 *   bits: [7:6]=01 (8-average), [5:4]=01 (15 Hz), [3:0]=0000 (normal)
 */
#define HMC5883L_CFG_A_VAL   0x70
/*
 * Config B: Gain = 1.3 Gauss (0x20)
 *  0x20 = 0010 0000
 *   bits: [7:5]=001 (gain 1.3 Ga), [4:0]=00000 (no bias)
 */
#define HMC5883L_CFG_B_VAL   0x20
/*
 * Mode: continuous conversion
 *  0x00 = 0000 0000
 *   bit 7=0 (not power-down), bit 6=0 (not reset), etc.
 */
#define HMC5883L_MODE_VAL   0x00

#define I2C_BUS             1
#define SAMPLE_PERIOD_US    500000   /* 500 ms */
#define WINDOW_SIZE         100
#define MAX_READ_RETRIES    3

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Write a byte to an HMC5883L register.
 * Returns 0 on success, -1 on failure.
 */
static int hmc_write_byte(int handle, uint8_t reg, uint8_t value)
{
    for (int attempt = 0; attempt < MAX_READ_RETRIES; attempt++) {
        int rc = i2cWriteByteData(handle, reg, value);
        if (rc == 0)
            return 0;
        fprintf(stderr, "Warning: i2cWriteByteData(reg=0x%02X, val=0x%02X) failed (attempt %d/%d): rc=%d\n",
                reg, value, attempt + 1, MAX_READ_RETRIES, rc);
        gpioDelay(10000);  /* 10 ms back-off */
    }
    return -1;
}

/*
 * Read a signed 16-bit big-endian value from two consecutive registers.
 * Returns 0 on success, -1 on failure.
 */
static int hmc_read_signed16(int handle, uint8_t reg, int16_t *out)
{
    for (int attempt = 0; attempt < MAX_READ_RETRIES; attempt++) {
        int msb = i2cReadByteData(handle, reg);
        if (msb < 0) {
            fprintf(stderr, "Warning: i2cReadByteData(reg=0x%02X) failed (attempt %d/%d): rc=%d\n",
                    reg, attempt + 1, MAX_READ_RETRIES, msb);
            gpioDelay(10000);
            continue;
        }
        int lsb = i2cReadByteData(handle, reg + 1);
        if (lsb < 0) {
            fprintf(stderr, "Warning: i2cReadByteData(reg=0x%02X+1) failed (attempt %d/%d): rc=%d\n",
                    reg, attempt + 1, MAX_READ_RETRIES, lsb);
            gpioDelay(10000);
            continue;
        }
        *out = (int16_t)((msb << 8) | lsb);
        return 0;
    }
    return -1;
}

/*
 * Read a single unsigned byte from a register.
 * Returns 0 on success, -1 on failure.
 */
static int hmc_read_byte(int handle, uint8_t reg, uint8_t *out)
{
    for (int attempt = 0; attempt < MAX_READ_RETRIES; attempt++) {
        int rc = i2cReadByteData(handle, reg);
        if (rc >= 0) {
            *out = (uint8_t)rc;
            return 0;
        }
        fprintf(stderr, "Warning: i2cReadByteData(reg=0x%02X) failed (attempt %d/%d): rc=%d\n",
                reg, attempt + 1, MAX_READ_RETRIES, rc);
        gpioDelay(10000);
    }
    return -1;
}

/*
 * Configure the HMC5883L for normal-gain, 15 Hz, 8-average continuous mode.
 * Returns 0 on success, -1 on failure.
 */
static int hmc_configure(int handle)
{
    if (hmc_write_byte(handle, HMC5883L_CONFIG_A, HMC5883L_CFG_A_VAL) != 0)
        return -1;
    if (hmc_write_byte(handle, HMC5883L_CONFIG_B, HMC5883L_CFG_B_VAL) != 0)
        return -1;
    if (hmc_write_byte(handle, HMC5883L_MODE, HMC5883L_MODE_VAL) != 0)
        return -1;
    return 0;
}

/*
 * Read one sample from the HMC5883L.
 * Returns 0 on success, -1 on failure.
 */
static int hmc_read_sample(int handle, int16_t *x, int16_t *y, int16_t *z)
{
    if (hmc_read_signed16(handle, HMC5883L_DATA_X_MSB, x) != 0)
        return -1;
    if (hmc_read_signed16(handle, HMC5883L_DATA_Z_MSB, z) != 0)
        return -1;
    if (hmc_read_signed16(handle, HMC5883L_DATA_Y_MSB, y) != 0)
        return -1;
    return 0;
}

/*
 * Compute the running average of the last `size` samples.
 * `sum` is updated in place; `count` is set to the number of valid samples.
 */
static void running_average(const int16_t *data, int size,
                            int16_t *sum, int *count)
{
    *count = 0;
    *sum = 0;
    for (int i = 0; i < size; i++) {
        *sum += data[i];
        (*count)++;
    }
    *sum /= size;
}

/*
 * Apply the running-average offset to a single sample.
 * Returns the corrected value.
 */
static int16_t apply_offset(int16_t raw, const int16_t *window, int size)
{
    int16_t sum = 0;
    int count = 0;
    running_average(window, size, &sum, &count);
    return (int16_t)(raw - sum);
}

int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus 1 at the HMC5883L address --- */
    g_i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, HMC5883L_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure sensor --- */
    if (hmc_configure(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: HMC5883L configuration failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Allocate running-average window --- */
    int16_t window[WINDOW_SIZE];
    for (int i = 0; i < WINDOW_SIZE; i++)
        window[i] = 0;

    int sample_count = 0;
    int16_t raw_x, raw_y, raw_z;
    int16_t offset_x, offset_y, offset_z;

    printf("HMC5883L magnetometer reader (bus %d, addr 0x%02X). Press Ctrl+C to stop.\n",
           I2C_BUS, HMC5883L_ADDR);

    /* --- Main sampling loop --- */
    while (g_running) {
        if (hmc_read_sample(g_i2c_handle, &raw_x, &raw_y, &raw_z) != 0) {
            fprintf(stderr, "Error: failed to read magnetometer data after retries.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /* Apply running-average offset to each axis */
        offset_x = apply_offset(raw_x, window, WINDOW_SIZE);
        offset_y = apply_offset(raw_y, window, WINDOW_SIZE);
        offset_z = apply_offset(raw_z, window, WINDOW_SIZE);

        /* Shift window: discard oldest sample, insert new raw value */
        for (int i = WINDOW_SIZE - 2; i >= 0; i--)
            window[i + 1] = window[i];
        window[0] = raw_x;
        sample_count++;

        printf("X: %6d  Y: %6d  Z: %6d  (samples: %d)\n",
               offset_x, offset_y, offset_z, sample_count);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

