/*
 * LSM303D accelerometer monitor for Raspberry Pi Zero W.
 *
 * Reads tri-axial acceleration over I2C (bus 1, address 0x19), stores
 * samples in a 64-entry circular buffer, and on a rising edge of the
 * INT1 pin (BCM GPIO 23, physical pin 16) dumps the last ten samples.
 *
 * Build:  gcc -O2 -Wall -Wextra -o lsm303d_mon lsm303d_mon.c -lgpiod
 * Run:    sudo ./lsm303d_mon   (needs /dev/i2c-1 and gpio access)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

/* ---- LSM303D constants ------------------------------------------------ */
#define LSM303D_ADDR        0x19
#define LSM303D_WHO_AM_I    0x0F
#define LSM303D_WHO_AM_I_ID 0x49

#define LSM303D_CTRL_REG1   0x20
#define LSM303D_CTRL_REG2   0x21
#define LSM303D_CTRL_REG3   0x22
#define LSM303D_CTRL_REG4   0x23
#define LSM303D_CTRL_REG5   0x24
#define LSM303D_CTRL_REG6   0x25
#define LSM303D_CTRL_REG7   0x26

#define LSM303D_OUT_X_L_A   0x28
#define LSM303D_OUT_X_H_A   0x29
#define LSM303D_OUT_Y_L_A   0x2A
#define LSM303D_OUT_Y_H_A   0x2B
#define LSM303D_OUT_Z_L_A   0x2C
#define LSM303D_OUT_Z_H_A   0x2D

#define ACCEL_SENSITIVITY_MG_LSB 0.061f   /* mg/LSB at ±2g */
#define ACCEL_THRESHOLD_MG       2000.0f  /* 2 g */

#define BUFFER_SIZE      64
#define DUMP_COUNT       10
#define SAMPLE_PERIOD_US 10000           /* 10 ms */

/* ---- GPIO / I2C helpers ---------------------------------------------- */

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1)
        return -1;
    if (read(fd, val, 1) != 1)
        return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2)
        return -1;
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1)
        return -1;
    if (read(fd, buf, len) != (ssize_t)len)
        return -1;
    return 0;
}

/* ---- Circular buffer ------------------------------------------------- */

typedef struct {
    float x, y, z;
} accel_sample_t;

typedef struct {
    accel_sample_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static void cb_init(circular_buffer_t *cb)
{
    cb->head  = 0;
    cb->count = 0;
}

static void cb_push(circular_buffer_t *cb, float x, float y, float z)
{
