}

static int safe_nanosleep(long milliseconds) {
    struct timespec req = {
        .tv_sec  = milliseconds / 1000,
        .tv_nsec = (milliseconds % 1000) * 1000000L
    };
    struct timespec rem;
    while (nanosleep(&req, &rem) == -1) {
        if (errno != EINTR) {
            return -1;
        }
        req = rem;
    }
    return 0;
}

