#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define RELAY1_GPIO 17
#define RELAY2_GPIO 27
#define UART_PORT_PRIMARY "/dev/serial0"
#define UART_PORT_SECONDARY "/dev/serial1"
#define BAUD_RATE 9600
#define EXPECTED_CODE "123456"
#define READ_TIMEOUT_SEC 5
#define RELAY_UNLOCK_MS 2000
#define MAX_CODE_LENGTH 6
#define BUF_SIZE 256

static volatile sig_atomic_t g_running = 1;
static int g_serial_fd_primary = -1;
static int g_serial_fd_secondary = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_uart(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", port, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, B9600);
    cfsetispeed(&tty, B9600);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 1; /* 100 ms inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_code(int fd, char *buf, size_t buf_size) {
    size_t idx = 0;
    char ch;
    ssize_t n;

    while (idx < buf_size - 1) {
        n = read(fd, &ch, 1);
        if (n < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                usleep(10000);
                continue;
            }
            fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            usleep(10000);
            continue;
        }

        if (ch >= '0' && ch <= '9') {
            buf[idx++] = ch;
        } else if (ch == '\r' || ch == '\n') {
            if (idx > 0) {
                buf[idx] = '\0';
                return (int)idx;
            }
        } else {
            idx = 0;
        }
    }

    buf[buf_size - 1] = '\0';
    return (int)idx;
}

static int validate_code(const char *code) {
    if (strlen(code) != MAX_CODE_LENGTH) {
        return 0;
    }
    for (size_t i = 0; i < MAX_CODE_LENGTH; i++) {
        if (code[i] < '0' || code[i] > '9') {
            return 0;
        }
    }
    return 1;
}

static int compare_codes(const char *a, const char *b) {
    int len = (int)strlen(a);
    if (len != (int)strlen(b)) {
        return 0;
    }
    for (int i = 0; i < len; i++) {
        if ((unsigned char)a[i] != (unsigned char)b[i]) {
            return 0;
        }
    }
    return 1;
}

static void unlock_doors(void) {
    if (gpioWrite(RELAY1_GPIO, 1) < 0) {
        fprintf(stderr, "Error writing HIGH to RELAY1_GPIO: %s\n", pigpio_error(0));
    }
    if (gpioWrite(RELAY2_GPIO, 1) < 0) {
        fprintf(stderr, "Error writing HIGH to RELAY2_GPIO: %s\n", pigpio_error(0));
    }
    gpioDelay(RELAY_UNLOCK_MS * 1000);
    if (gpioWrite(RELAY1_GPIO, 0) < 0) {
        fprintf(stderr, "Error writing LOW to RELAY1_GPIO: %s\n", pigpio_error(0));
    }
    if (gpioWrite(RELAY2_GPIO, 0) < 0) {
        fprintf(stderr, "Error writing LOW to RELAY2_GPIO: %s\n", pigpio_error(0));
    }
}

static void cleanup(void) {
    if (g_serial_fd_primary >= 0) {
        close(g_serial_fd_primary);
        g_serial_fd_primary = -1;
    }
    if (g_serial_fd_secondary >= 0) {
        close(g_serial_fd_secondary);
        g_serial_fd_secondary = -1;
    }
    gpioWrite(RELAY1_GPIO, 0);
    gpioWrite(RELAY2_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY1_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting RELAY1_GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RELAY2_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting RELAY2_GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY1_GPIO, 0);
    gpioWrite(RELAY2_GPIO, 0);

    g_serial_fd_primary = init_uart(UART_PORT_PRIMARY);
    if (g_serial_fd_primary < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_serial_fd_secondary = init_uart(UART_PORT_SECONDARY);
    if (g_serial_fd_secondary < 0) {
        close(g_serial_fd_primary);
        g_serial_fd_primary = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    char code1[MAX_CODE_LENGTH + 1];
    char code2[MAX_CODE_LENGTH + 1];
    int code1_len = 0;
    int code2_len = 0;
    time_t code1_start = 0;
    time_t code2_start = 0;

    while (g_running) {
        int rc1 = read_code(g_serial_fd_primary, code1, sizeof(code1));
        if (rc1 > 0) {
            code1[rc1] = '\0';
            if (validate_code(code1)) {
                code1_len = rc1;
                code1_start = time(NULL);
            } else {
                code1_len = 0;
            }
        } else if (rc1 < 0) {
            code1_len = 0;
        }

        int rc2 = read_code(g_serial_fd_secondary, code2, sizeof(code2));
        if (rc2 > 0) {
            code2[rc2] = '\0';
            if (validate_code(code2)) {
                code2_len = rc2;
                code2_start = time(NULL);
            } else {
                code2_len = 0;
            }
        } else if (rc2 < 0) {
            code2_len = 0;
        }

        if (code1_len == MAX_CODE_LENGTH && code2_len == MAX_CODE_LENGTH) {
            if (compare_codes(code1, code2) == 1 &&
                compare_codes(code1, EXPECTED_CODE) == 1) {
                printf("Authentication successful! Unlocking doors...\n");
                unlock_doors();
            } else {
                fprintf(stderr, "Authentication failed! Codes do not match.\n");
            }
            code1_len = 0;
            code2_len = 0;
        } else if (code1_len == MAX_CODE_LENGTH) {
            code1_len = 0;
        } else if (code2_len == MAX_CODE_LENGTH) {
            code2_len = 0;
        }

        time_t now = time(NULL);
        if (code1_len == MAX_CODE_LENGTH && (now - code1_start) > READ_TIMEOUT_SEC) {
            code1_len = 0;
        }
        if (code2_len == MAX_CODE_LENGTH && (now - code2_start) > READ_TIMEOUT_SEC) {
            code2_len = 0;
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

