#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define RELAY_ON_TIME_SEC 300
#define RELAY_OFF_TIME_SEC 60
#define TIMER_INTERVAL_SEC 60

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_msg(int priority, const char *msg) {
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, "%s", msg);
    closelog();
}

static int set_relay_state(int pin, int state) {
    int rc = gpioWrite(pin, state);
    if (rc < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "gpioWrite failed on pin %d (state %d): %d", pin, state, rc);
        log_msg(LOG_ERR, buf);
    }
    return rc;
}

static int all_relays_off(void) {
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (set_relay_state(pins[i], 1) < 0) return -1;
    }
    return 0;
}

static int deactivate_relay(int pin, int duration_sec) {
    if (set_relay_state(pin, 0) < 0) return -1;
    gpioDelay(duration_sec * 1000000);
    if (set_relay_state(pin, 1) < 0) return -1;
    return 0;
}

static int activate_relay(int pin, int duration_sec) {
    if (set_relay_state(pin, 0) < 0) return -1;
    gpioDelay(duration_sec * 1000000);
    if (set_relay_state(pin, 1) < 0) return -1;
    return 0;
}

static void timer_callback(void *userdata) {
    (void)userdata;
    static int current_relay = 0;
    char msg[256];

    snprintf(msg, sizeof(msg), "Timer fired. Activating relay %d", current_relay + 1);
    log_msg(LOG_INFO, msg);

    if (activate_relay(RELAY1_PIN, RELAY_ON_TIME_SEC) < 0) {
        log_msg(LOG_ERR, "Failed to activate relay 1");
        return;
    }
    current_relay = 0;

    for (int i = 1; i < 4; i++) {
        snprintf(msg, sizeof(msg), "Timer fired. Activating relay %d", i + 1);
        log_msg(LOG_INFO, msg);

        if (activate_relay(RELAY2_PIN, RELAY_ON_TIME_SEC) < 0) {
            log_msg(LOG_ERR, "Failed to activate relay 2");
            return;
        }
        current_relay = i;

        if (activate_relay(RELAY3_PIN, RELAY_ON_TIME_SEC) < 0) {
            log_msg(LOG_ERR, "Failed to activate relay 3");
            return;
        }
        current_relay = i;

        if (activate_relay(RELAY4_PIN, RELAY_ON_TIME_SEC) < 0) {
            log_msg(LOG_ERR, "Failed to activate relay 4");
            return;
        }
        current_relay = i;
    }

    snprintf(msg, sizeof(msg), "Timer fired. Activating relay %d", current_relay + 1);
    log_msg(LOG_INFO, msg);

    if (deactivate_relay(RELAY1_PIN, RELAY_OFF_TIME_SEC) < 0) {
        log_msg(LOG_ERR, "Failed to deactivate relay 1");
        return;
    }
    current_relay = 1;

    for (int i = 2; i < 4; i++) {
        snprintf(msg, sizeof(msg), "Timer fired. Activating relay %d", i + 1);
        log_msg(LOG_INFO, msg);

        if (deactivate_relay(RELAY2_PIN, RELAY_OFF_TIME_SEC) < 0) {
            log_msg(LOG_ERR, "Failed to deactivate relay 2");
            return;
        }
        current_relay = i;

        if (deactivate_relay(RELAY3_PIN, RELAY_OFF_TIME_SEC) < 0) {
            log_msg(LOG_ERR, "Failed to deactivate relay 3");
            return;
        }
        current_relay = i;

        if (deactivate_relay(RELAY4_PIN, RELAY_OFF_TIME_SEC) < 0) {
            log_msg(LOG_ERR, "Failed to deactivate relay 4");
            return;
        }
        current_relay = i;
    }

    snprintf(msg, sizeof(msg), "Timer fired. Activating relay %d", current_relay + 1);
    log_msg(LOG_INFO, msg);

    if (all_relays_off() < 0) {
        log_msg(LOG_ERR, "Failed to deactivate all relays");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        log_msg(LOG_ERR, "pigpio initialisation failed");
        return EXIT_FAILURE;
    }

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) < 0) {
            char buf[128];
            snprintf(buf, sizeof(buf), "gpioSetMode failed on pin %d", pins[i]);
            log_msg(LOG_ERR, buf);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (set_relay_state(pins[i], 1) < 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    if (gpioSetTimerFuncEx(0, TIMER_INTERVAL_SEC, timer_callback, NULL) < 0) {
        log_msg(LOG_ERR, "Failed to set timer function");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_msg(LOG_INFO, "Irrigation system started");

    while (g_running) {
        gpioDelay(1000000);
    }

    log_msg(LOG_INFO, "Irrigation system shutting down");
    gpioSetTimerFuncEx(0, TIMER_INTERVAL_SEC, NULL, NULL);
    all_relays_off();
    gpioTerminate();
    return EXIT_SUCCESS;
}

