    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", path, strerror(errno));
        return -1;
    }
    if (write(fd, value, strlen(value)) < 0) {
        fprintf(stderr, "write(%s, %s) failed: %s\n", path, value, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

