/*
 * Relay toggler for Raspberry Pi 3 Model B+
 * Four 5V relay modules on BCM GPIO18, 23, 24, 25, toggling every 2, 3, 5, 7 s.
 * Uses pigpio for GPIO control.  Clean shutdown on every exit path.
 *
 * Build:  gcc -O2 -Wall -Wextra -o relay_toggle relay_toggle.c -lpigpio -lrt
 * Run:    sudo ./relay_toggle
 */
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <time.h>
#include <pigpio.h>

#define RELAY1_PIN 18
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

#define INTERVAL_2S  2
#define INTERVAL_3S  3
#define INTERVAL_5S  5
#define INTERVAL_7S  7

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_relay(unsigned pin, int level)
{
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Error: gpioWrite failed on pin %u (level %d)\n", pin, level);
        return -1;
    }
    return 0;
}

static int all_relays_off(void)
{
    int rc = 0;
    rc |= set_relay(RELAY1_PIN, 0);
    rc |= set_relay(RELAY2_PIN, 0);
    rc |= set_relay(RELAY3_PIN, 0);
    rc |= set_relay(RELAY4_PIN, 0);
    return rc;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    unsigned pins[] = { RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN };
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed on pin %u\n", pins[i]);
            return -1;
        }
        if (set_relay(pins[i], 0) != 0)
            return -1;
    }
    return 0;
}

static void cleanup(void)
{
    all_relays_off();
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0)
        return EXIT_FAILURE;

    struct timespec next;
    if (clock_gettime(CLOCK_MONOTONIC, &next) != 0) {
        perror("clock_gettime");
        cleanup();
        return EXIT_FAILURE;
    }

    const unsigned pins[] = { RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN };
    const int intervals[] = { INTERVAL_2S, INTERVAL_3S, INTERVAL_5S, INTERVAL_7S };

    while (g_running) {
        for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
            if (clock_gettime(CLOCK_MONOTONIC, &next) != 0) {
                perror("clock_gettime");
                goto done;
            }
            long delta_ns = (next.tv_sec - (time_t)next.tv_nsec / 1000000000L) * intervals[i] -
                            (next.tv_sec - (time_t)next.tv_nsec / 1000000000L) * intervals[i];
            if (delta_ns < 0)
                delta_ns = 0;

            int level = gpioRead(pins[i]);
            if (level < 0) {
                fprintf(stderr, "Error: gpioRead failed on pin %u\n", pins[i]);
                goto done;
            }

            if (set_relay(pins[i], level ? 0 : 1) != 0)
                goto done;

            if (clock_nanosleep(CLOCK_MONOTONIC, 0, &next, NULL) != 0) {
                perror("clock_nanosleep");
                goto done;
            }
            next.tv_nsec += delta_ns * 1000;
            if (next.tv_nsec >= 1000000000L) {
                next.tv_sec += 1;
                next.tv_nsec -= 1000000000L;
            }
        }
    }

done:
    cleanup();
    return g_running ? EXIT_FAILURE : EXIT_SUCCESS;
}

