#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47
#define GYRO_CONFIG 0x1B
#define GYRO_SENSITIVITY 131.0f
#define BUFFER_SIZE 100
#define THRESHOLD 50.0f

typedef struct {
    int16_t x, y, z;
} gyro_data_t;

typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static circular_buffer_t gyro_buffer;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error selecting I2C register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading I2C register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int init_mpu6050(int fd) {
    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000);
    if (i2c_write_reg8(fd, GYRO_CONFIG, 0x00) < 0) return -1;
    return 0;
}

static void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) buffer->count++;
}

static void check_threshold(gyro_data_t data) {
    float magnitude = sqrtf((float)data.x * data.x + (float)data.y * data.y + (float)data.z * data.z);
    if (magnitude > THRESHOLD) {
        printf("Threshold exceeded! Magnitude: %.2f\n", magnitude);
    }
}

static void callback(gyro_data_t data) {
    check_threshold(data);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    gyro_buffer.head = 0;
    gyro_buffer.count = 0;

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize MPU-6050\n");
        close(i2c_fd);
        return 1;
    }

    printf("MPU-6050 initialized. Reading data...\n");

    while (running) {
        int16_t raw_x, raw_y, raw_z;
        if (i2c_read_reg16(i2c_fd, GYRO_XOUT_H, &raw_x) < 0 ||
            i2c_read_reg16(i2c_fd, GYRO_YOUT_H, &raw_y) < 0 ||
            i2c_read_reg16(i2c_fd, GYRO_ZOUT_H, &raw_z) < 0) {
            fprintf(stderr, "I2C read error, continuing...\n");
            usleep(100000);
            continue;
        }

        gyro_data_t data;
        data.x = raw_x;
        data.y = raw_y;
        data.z = raw_z;

        add_to_buffer(&gyro_buffer, data);

        callback(data);

        usleep(10000);
    }

    printf("\nExiting gracefully...\n");
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

