/*
 * MH-Z19B CO2 Monitor for Raspberry Pi 3 Model B+
 *
 * Reads CO2 concentration from an MH-Z19B sensor over UART using the
 * /dev/serial0 device (BCM 14 TXD / BCM 15 RXD).
 *
 * Build:  gcc -Wall -Wextra -o co2_monitor co2_monitor.c -lthe_driver -lrt
 * Run:    ./co2_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>

#include "the_driver.h"

#define UART_DEVICE      "/dev/serial0"
#define BAUD_RATE        9600
#define LOG_FILE         "co2_log.json"
#define ERROR_LOG_FILE   "co2_error.log"
#define SAMPLE_INTERVAL  5          /* seconds between readings */
#define RESPONSE_TIMEOUT 1000000    /* microseconds (1 s) */
#define RESPONSE_LEN     9           /* bytes in a complete MH-Z19B frame */
#define MAX_RETRIES      100         /* retries per partial read */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_uart_fd = -1;
static FILE    *g_log_fp  = NULL;
static FILE    *g_err_fp  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    struct tm       tm_info;

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        snprintf(buf, len, "1970-01-01T00:00:00.000000000");
        return;
    }
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm_info);
    size_t used = strlen(buf);
    snprintf(buf + used, len - used, ".%06ld", ts.tv_nsec / 1000);
}

/* ------------------------------------------------------------------ */
/* Error logging                                                       */
/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    char ts[40];
    get_timestamp(ts, sizeof(ts));

    if (g_err_fp) {
        fprintf(g_err_fp, "%s - ERROR: %s\n", ts, msg);
        fflush(g_err_fp);
    }
    fprintf(stderr, "%s - ERROR: %s\n", ts, msg);
}

/* ------------------------------------------------------------------ */
/* JSON logging                                                        */
/* ------------------------------------------------------------------ */
static void log_data(int co2_ppm, int error_flag)
{
    char ts[40];
    get_timestamp(ts, sizeof(ts));

    if (g_log_fp) {
        fprintf(g_log_fp,
                "{\"timestamp\":\"%s\",\"co2_ppm\":%d,\"error_flag\":%d}\n",
                ts, co2_ppm, error_flag);
        fflush(g_log_fp);
    }
}

/* ------------------------------------------------------------------ */
/* MH-Z19B frame parsing                                               */
/* ------------------------------------------------------------------ */
/*
 * MH-Z19B response (9 bytes):
 *   [0..2]  start byte (0x02) + status (0x00 = OK) + B1
 *   [3..4]  MSB/LSB of CO2 concentration (ppm)
 *   [5..6]  MSB/LSB of temperature (°C)
 *   [7..8]  MSB/LSB of humidity (%RH)
 *   [9]     CRC byte
 *
 * CRC-4 polynomial 0x13, init 0x00, no final XOR.
 */
static int parse_co2(const uint8_t *frame, int *co2_ppm)
{
    /* Status byte must be 0x00 (OK) */
    if (frame[1] != 0x00) {
        return -1;
    }

    /* Raw ppm from bytes 3 and 4 (big-endian) */
    uint16_t raw = ((uint16_t)frame[3] << 8) | frame[4];
    *co2_ppm = (int)raw;
    return 0;
}

/* ------------------------------------------------------------------ */
/* CRC-4 calculation (MH-Z19B style)                                   */
/* ------------------------------------------------------------------ */
static uint8_t crc4(const uint8_t *data, size_t len)
{
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 4; b++) {
            if (crc & 0x08)
                crc = (uint8_t)((crc << 1) ^ 0x13);
            else
                crc = (uint8_t)(crc << 1);
            crc &= 0x0F;
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Send a 9-byte command frame                                         */
/* ------------------------------------------------------------------ */
static int send_command(int fd, const uint8_t *cmd, size_t len)
{
    ssize_t written = write(fd, cmd, len);
    if (written < 0) {
        return -1;
    }
    if ((size_t)written != len) {
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read exactly n bytes with timeout                                   */
/* ------------------------------------------------------------------ */
static int read_exact(int fd, uint8_t *buf, size_t n, int timeout_us)
{
    size_t got = 0;
    uint8_t ch;
    int     elapsed = 0;

    while (got < n && elapsed < timeout_us) {
        ssize_t r = read(fd, &ch, 1);
        if (r < 0) {
            if (errno == EINTR) {
                continue;
            }
            return -1;
        }
        if (r == 0) {
            /* VTIME timeout on /dev/tty* reads 0 bytes, not EAGAIN */
            continue;
        }
        buf[got++] = ch;
        elapsed = 0;
    }

    if (got < n) {
        return (got == 0) ? -1 : -2;  /* partial read */
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one MH-Z19B frame                                              */
/* ------------------------------------------------------------------ */
static int read_co2_frame(int fd, int *co2_ppm)
{
    uint8_t frame[RESPONSE_LEN];

    /*
     * MH-Z19B needs a short idle period after power-on / reset before
     * the first measurement request.  A 100 ms delay is sufficient.
     */
    usleep(100000);

    /*
     * Send the 9-byte command frame:
     *   0x02 0x00 0x00 0x00 0x00 0x00 0x00 0x00 0x00
     * (status + B1 padding) triggers a single measurement.
     */
    uint8_t cmd[RESPONSE_LEN] = {
        0x02, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
    };

    if (send_command(fd, cmd, sizeof(cmd)) != 0) {
        log_error("Failed to send measurement request");
        return -1;
    }

    /*
     * At 9600 baud a byte takes ~1.1 ms.  A 100 ms response gives
     * ~90 bytes worth of data.  Wait for the full frame.
     */
    if (read_exact(fd, frame, RESPONSE_LEN, RESPONSE_TIMEOUT) != 0) {
        log_error("Timeout waiting for MH-Z19B response");
        return -1;
    }

    /* Validate CRC-4 over the first 8 bytes */
    if (crc4(frame, 8) != frame[8]) {
        log_error("CRC mismatch on MH-Z19B frame");
        return -1;
    }

    if (parse_co2(frame, co2_ppm) != 0) {
        log_error("MH-Z19B status byte indicates non-OK condition");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
