#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define HMC5883L_ADDR 0x1E
#define CONFIG_REG_A 0x00
#define MODE_REG 0x02
#define DATA_OUT_X_MSB 0x03
#define DATA_OUT_X_LSB 0x04
#define DATA_OUT_Z_MSB 0x05
#define DATA_OUT_Z_LSB 0x06
#define DATA_OUT_Y_MSB 0x07
#define DATA_OUT_Y_LSB 0x08

#define TARGET_HEADING 90.0
#define DEVIATION_THRESHOLD 10.0
#define ALERT_GPIO 17
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL_US 100000

#define HMC5883L_X_OFFSET 100
#define HMC5883L_Y_OFFSET (-50)

typedef struct {
    float heading;
    uint32_t timestamp;
} HeadingData;

static HeadingData circularBuffer[BUFFER_SIZE];
static int bufferIndex = 0;
static int bufferCount = 0;

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signalHandler(int signal) {
    (void)signal;
    running = 0;
}

static int initHMC5883L(int handle) {
    if (i2cWriteByteData(handle, CONFIG_REG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to CONFIG_REG_A\n");
        return -1;
    }
    if (i2cWriteByteData(handle, MODE_REG, 0x00) < 0) {
        fprintf(stderr, "Error writing to MODE_REG\n");
        return -1;
    }
    return 0;
}

static int readMagnetometerData(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(handle, DATA_OUT_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }
    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);
    return 0;
}

static float calculateHeading(int16_t x, int16_t y) {
    float heading = atan2f((float)y, (float)x) * 180.0 / M_PI;
    if (heading < 0) {
        heading += 360.0;
    }
    return heading;
}

static float applyHardIronCompensation(int16_t rawX, int16_t rawY) {
    float compX = (float)rawX - HMC5883L_X_OFFSET;
    float compY = (float)rawY - HMC5883L_Y_OFFSET;
    return atan2f(compY, compX) * 180.0 / M_PI;
}

static void addToCircularBuffer(float heading) {
    circularBuffer[bufferIndex].heading = heading;
    circularBuffer[bufferIndex].timestamp = gpioTick();
    bufferIndex = (bufferIndex + 1) % BUFFER_SIZE;
    if (bufferCount < BUFFER_SIZE) {
        bufferCount++;
    }
}

static float getAverageHeading() {
    if (bufferCount == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < bufferCount; i++) {
        sum += circularBuffer[i].heading;
    }
    return sum / (float)bufferCount;
}

static void checkDeviation(float currentHeading) {
    float avgHeading = getAverageHeading();
    float deviation = fabsf(currentHeading - TARGET_HEADING);
    if (deviation > DEVIATION_THRESHOLD) {
        gpioWrite(ALERT_GPIO, 1);
        printf("Deviation detected! Current: %.2f, Average: %.2f, Target: %.2f\n", currentHeading, avgHeading, TARGET_HEADING);
    } else {
        gpioWrite(ALERT_GPIO, 0);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (initHMC5883L(i2c_handle) < 0) {
        fprintf(stderr, "HMC5883L initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signalHandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int16_t rawX, rawY, rawZ;
    float heading, compensatedHeading;

    while (running) {
        if (readMagnetometerData(i2c_handle, &rawX, &rawY, &rawZ) == 0) {
            heading = calculateHeading(rawX, rawY);
            compensatedHeading = applyHardIronCompensation(rawX, rawY);
            addToCircularBuffer(compensatedHeading);
            checkDeviation(compensatedHeading);
        } else {
            fprintf(stderr, "Failed to read magnetometer data. Retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioWrite(ALERT_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

