/*
 * Raspberry Pi 5 - BH1750 Ambient Light Sensor & RGB Lamp Controller
 *
 * Reads lux from a BH1750 on I2C bus 1 (address 0x5C), triggers RGB
 * relays on GPIO 17 (RED), 27 (GREEN), 22 (BLUE) based on lux thresholds,
 * and logs timestamped data to lighting_log.txt every second.
 *
 * Build: gcc -O2 -Wall -o light_control light_control.c -lpigpio -lrt
 * Run:   sudo ./light_control
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS         "/dev/i2c-1"
#define BH1750_ADDR     0x5C
#define BH1750_CMD_POWER_ON   0x01
#define BH1750_CMD_POWER_OFF  0x00
#define BH1750_CMD_CONT_HRES  0x10   /* 1 lux resolution, ~120 ms */
#define BH1750_CONV_MS      120

#define RED_PIN   17
#define GREEN_PIN 27
#define BLUE_PIN  22

#define LUX_THRESHOLD_LOW   50
#define LUX_THRESHOLD_MED   150
#define LUX_THRESHOLD_HIGH  300

#define LOG_FILE "lighting_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        (void)write(g_i2c_fd, BH1750_CMD_POWER_OFF, 1);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log) {
        fflush(g_log);
        fclose(g_log);
        g_log = NULL;
    }
    /* Safe to call even if not initialised */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);
    gpioWrite(RED_PIN, 0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN, 0);
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_i2c(void)
{
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                BH1750_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }
    /* Power on and start continuous high-resolution mode */
    if (write(g_i2c_fd, BH1750_CMD_POWER_ON, 1) < 0) {
        fprintf(stderr, "BH1750 power-on failed: %s\n", strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }
    if (write(g_i2c_fd, BH1750_CMD_CONT_HRES, 1) < 0) {
        fprintf(stderr, "BH1750 mode set failed: %s\n", strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_lux(int *lux_out)
{
    uint8_t buf[2];
    ssize_t n = read(g_i2c_fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        if (n < 0)
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        else
            fprintf(stderr, "I2C short read: %zd bytes\n", n);
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (int)(raw / 1.2);
    return 0;
}

/* ------------------------------------------------------------------ */
static void set_relay(int pin, int on)
{
    gpioWrite(pin, on ? 1 : 0);
}

/* ------------------------------------------------------------------ */
static void control_lamp(int lux)
{
    if (lux < LUX_THRESHOLD_LOW)
        set_relay(RED_PIN, 1);
    else if (lux < LUX_THRESHOLD_MED)
        set_relay(GREEN_PIN, 1);
    else if (lux < LUX_THRESHOLD_HIGH)
        set_relay(BLUE_PIN, 1);
    else
        set_relay(RED_PIN, 1);
        set_relay(GREEN_PIN, 1);
        set_relay(BLUE_PIN, 1);
}

/* ------------------------------------------------------------------ */
static void log_data(int lux, int r, int g, int b)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    fprintf(g_log, "%04d-%02d-%02d %02d:%02d:%02d, Lux: %d, R: %d, G: %d, B: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, lux, r, g, b);
    fflush(g_log);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0)
        return EXIT_FAILURE;

    if (init_i2c() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Lighting control started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int lux = -1;
        if (read_lux(&lux) < 0) {
            /* Sensor absent or bus error: turn off all relays and retry */
            set_relay(RED_PIN, 0);
            set_relay(GREEN_PIN, 0);
            set_relay(BLUE_PIN, 0);
            sleep(1);
            continue;
        }

        control_lamp(lux);
        int r = gpioRead(RED_PIN);
        int g = gpioRead(GREEN_PIN);
        int b = gpioRead(BLUE_PIN);
        log_data(lux, r, g, b);

        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

