#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/stat.h>
#include <sys/types.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define PWM_CHIP 2
#define PWM_CHANNEL 0
#define SERVO_PIN 18
#define LOG_FILE "solar_tracker.log"
#define SERVO_MIN_US 500
#define SERVO_MAX_US 2500
#define SERVO_NEUTRAL_US 1500

#define MPU6050_REG_SMPLRT_DIV 0x19
#define MPU6050_REG_CONFIG 0x1A
#define MPU6050_REG_GYRO_CONFIG 0x1B
#define MPU6050_REG_ACCEL_CONFIG 0x1C
#define MPU6050_REG_ACCEL_XOUT_H 0x3B
#define MPU6050_REG_TEMP_OUT_H 0x41
#define MPU6050_REG_GYRO_XOUT_H 0x43
#define MPU6050_REG_PWR_MGMT_1 0x6B

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int init_mpu6050(int fd) {
    if (i2c_write_reg8(fd, MPU6050_REG_PWR_MGMT_1, 0x00) < 0) {
        return -1;
    }
    usleep(100000);
    if (i2c_write_reg8(fd, MPU6050_REG_SMPLRT_DIV, 0x07) < 0) {
        return -1;
    }
    if (i2c_write_reg8(fd, MPU6050_REG_CONFIG, 0x00) < 0) {
        return -1;
    }
    if (i2c_write_reg8(fd, MPU6050_REG_GYRO_CONFIG, 0x00) < 0) {
        return -1;
    }
    if (i2c_write_reg8(fd, MPU6050_REG_ACCEL_CONFIG, 0x00) < 0) {
        return -1;
    }
    return 0;
}

static int read_mpu6050_data(int fd, int16_t *ax, int16_t *ay, int16_t *az, int16_t *gx, int16_t *gy, int16_t *gz) {
    if (i2c_read_reg16(fd, MPU6050_REG_ACCEL_XOUT_H, ax) < 0) return -1;
    if (i2c_read_reg16(fd, MPU6050_REG_ACCEL_XOUT_H + 2, ay) < 0) return -1;
    if (i2c_read_reg16(fd, MPU6050_REG_ACCEL_XOUT_H + 4, az) < 0) return -1;
    if (i2c_read_reg16(fd, MPU6050_REG_GYRO_XOUT_H, gx) < 0) return -1;
    if (i2c_read_reg16(fd, MPU6050_REG_GYRO_XOUT_H + 2, gy) < 0) return -1;
    if (i2c_read_reg16(fd, MPU6050_REG_GYRO_XOUT_H + 4, gz) < 0) return -1;
    return 0;
}

static void calculate_pitch_roll(int16_t ax, int16_t ay, int16_t az, float *pitch, float *roll) {
    *pitch = atan2((float)ax, sqrt((float)ay * ay + (float)az * az)) * 180.0 / M_PI;
