    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_CHANNEL);
    int duty_cycle_fd = open(path, O_WRONLY);
    if (duty_cycle_fd < 0) {
        close(period_fd);
        return -1;
    }
    if (write(period_fd, "1000000", 8) < 0) {
        close(period_fd);
        close(duty_cycle_fd);
        return -1;
    }
    if (write(duty_cycle_fd, "0", 1) < 0) {
        close(period_fd);
        close(duty_cycle_fd);
        return -1;
    }
    close(period_fd);
    close(duty_cycle_fd);
    return 0;
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
