#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define NUM_RELAYS 4
#define FADE_DURATION 1800
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define SCHEDULE_FILE "lighting_schedule.txt"

static const int relay_pins[NUM_RELAYS] = {4, 17, 27, 22};
static volatile sig_atomic_t running = 1;

typedef struct {
    int hour;
    int minute;
    int second;
    int relay_number;
    int state;
} schedule_entry_t;

static schedule_entry_t schedule[NUM_RELAYS];
static int schedule_size = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_schedule(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening schedule file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    schedule_size = 0;
    char line[256];
    while (fgets(line, sizeof(line), fp) != NULL) {
        if (sscanf(line, "%d:%d:%d,%d,%s",
                   &schedule[schedule_size].hour,
                   &schedule[schedule_size].minute,
                   &schedule[schedule_size].second,
                   &schedule[schedule_size].relay_number,
                   schedule[schedule_size].state) == 5) {
            schedule_size++;
            if (schedule_size >= NUM_RELAYS) {
                fprintf(stderr, "Warning: schedule file contains more entries than relays (%d)\n", schedule_size);
                break;
            }
        } else {
            fprintf(stderr, "Warning: invalid schedule entry: %s", line);
        }
    }

    fclose(fp);
    return 0;
}

static int validate_schedule(void) {
    if (schedule_size == 0) {
        fprintf(stderr, "Error: no schedule entries found\n");
        return -1;
    }
    for (int i = 0; i < schedule_size; i++) {
        if (schedule[i].hour < 0 || schedule[i].hour > 23 ||
            schedule[i].minute < 0 || schedule[i].minute > 59 ||
            schedule[i].second < 0 || schedule[i].second > 59 ||
            schedule[i].relay_number < 0 || schedule[i].relay_number >= NUM_RELAYS) {
            fprintf(stderr, "Error: invalid schedule entry %d: %d:%d:%d,%d,%s\n",
                    i, schedule[i].hour, schedule[i].minute, schedule[i].second,
                    schedule[i].relay_number, schedule[i].state ? "ON" : "OFF");
            return -1;
        }
    }
    return 0;
}

static int control_relay(int relay_number, int state) {
    if (relay_number < 0 || relay_number >= NUM_RELAYS) {
        fprintf(stderr, "Error: invalid relay number %d\n", relay_number);
        return -1;
    }
    if (gpioWrite(relay_pins[relay_number], state) != 0) {
        fprintf(stderr, "Error: failed to write relay %d (GPIO%d)\n", relay_number, relay_pins[relay_number]);
        return -1;
    }
    return 0;
}

static int apply_schedule(void) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error: time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm *local_time = localtime(&now);
    if (local_time == NULL) {
        fprintf(stderr, "Error: localtime() failed\n");
        return -1;
    }

    int current_hour = local_time->tm_hour;
    int current_minute = local_time->tm_min;
    int current_second = local_time->tm_sec;

    for (int i = 0; i < schedule_size; i++) {
        if (schedule[i].relay_number < 0 || schedule[i].relay_number >= NUM_RELAYS) {
            continue;
        }

        if (schedule[i].hour == current_hour &&
            schedule[i].minute == current_minute &&
            schedule[i].second == current_second) {
            if (control_relay(schedule[i].relay_number, schedule[i].state) != 0) {
                return -1;
            }
            continue;
        }

        int target_state = schedule[i].state;
        int current_state = gpioRead(relay_pins[schedule[i].relay_number]);
        if (current_state < 0) {
            fprintf(stderr, "Error: gpioRead failed for relay %d\n", schedule[i].relay_number);
            return -1;
        }

        if (current_state != target_state) {
            for (int s = 0; s <= FADE_DURATION && running; s++) {
                int duty = (int)(((float)s / FADE_DURATION) * PWM_RANGE);
                if (duty > PWM_RANGE) duty = PWM_RANGE;
                if (duty < 0) duty = 0;

                if (gpioPWM(relay_pins[schedule[i].relay_number], duty) != 0) {
                    fprintf(stderr, "Error: gpioPWM failed for relay %d\n", schedule[i].relay_number);
                    return -1;
                }
                gpioDelay(10000);
            }
            if (gpioWrite(relay_pins[schedule[i].relay_number], target_state) != 0) {
                fprintf(stderr, "Error: gpioWrite failed for relay %d\n", schedule[i].relay_number);
                return -1;
            }
        }
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for GPIO%d\n", relay_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(relay_pins[i], PWM_FREQUENCY) < 0) {
            fprintf(stderr, "Error: gpioSetPWMfrequency failed for GPIO%d\n", relay_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(relay_pins[i], PWM_RANGE) < 0) {
            fprintf(stderr, "Error: gpioSetPWMrange failed for GPIO%d\n", relay_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioWrite(relay_pins[i], 0) != 0) {
            fprintf(stderr, "Error: gpioWrite failed for GPIO%d\n", relay_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (read_schedule(SCHEDULE_FILE) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (validate_schedule() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Smart home lighting system started. Press Ctrl+C to exit.\n");

    while (running) {
        if (apply_schedule() != 0) {
            fprintf(stderr, "Error: failed to apply schedule\n");
        }
        gpioDelay(1000000);
    }

    printf("\nShutting down...\n");
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioWrite(relay_pins[i], 0);
        gpioPWM(relay_pins[i], 0);
