#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define BUZZER_PIN  18

#define MIN_FREQUENCY 20.0
#define MAX_FREQUENCY 20000.0
#define MIN_DISTANCE  2.0
#define MAX_DISTANCE  400.0

#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  30000   /* 30 ms (~5 m round-trip) */
#define LOOP_DELAY_US    20000   /* 20 ms (~50 Hz) */
#define MEASURE_GAP_US   60000   /* 60 ms between measurements */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance in centimetres.
 * Returns >= 0 on success, -1.0 on timeout / no echo,
 * -2.0 on pigpio level read error.
 */
static float measure_distance(void)
{
    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -2.0;
    }
    gpioDelay(5);

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 1) failed\n");
        return -2.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -2.0;
    }

    uint32_t start_tick = 0, end_tick = 0;
    uint32_t deadline;

    /* Wait for echo rising edge */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: Echo start timeout (sensor absent?)\n");
            return -1.0;
        }
        gpioDelay(20);
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: Echo end timeout\n");
            return -1.0;
        }
        gpioDelay(20);
    }
    end_tick = gpioTick();

    uint32_t elapsed_us = end_tick - start_tick;
    /* Speed of sound 343 m/s => 0.0343 cm/µs; round trip / 2 */
    float distance = (elapsed_us * 0.0343f) / 2.0f;

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Warning: Distance %.2f cm out of range [%.1f, %.1f]\n",
                distance, MIN_DISTANCE, MAX_DISTANCE);
        return -1.0;
    }
    return distance;
}

/*
 * Map distance (cm) to buzzer frequency (Hz).
 * Near -> low freq, Far -> high freq, clamped to valid range.
 */
static float map_distance_to_frequency(float distance)
{
    if (distance < MIN_DISTANCE) distance = MIN_DISTANCE;
    if (distance > MAX_DISTANCE) distance = MAX_DISTANCE;

    float ratio = (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE);
    float freq = MIN_FREQUENCY + ratio * (MAX_FREQUENCY - MIN_FREQUENCY);

    if (freq < MIN_FREQUENCY) freq = MIN_FREQUENCY;
    if (freq > MAX_FREQUENCY) freq = MAX_FREQUENCY;
    return freq;
}

/*
 * Drive the buzzer at the given frequency (Hz) using hardware PWM.
 * Returns 0 on success, -1 on error.
 */
static int set_buzzer_frequency(float frequency)
{
    if (frequency < MIN_FREQUENCY || frequency > MAX_FREQUENCY) {
        fprintf(stderr, "Error: Frequency %.2f Hz out of range [%.1f, %.1f]\n",
                frequency, MIN_FREQUENCY, MAX_FREQUENCY);
        return -1;
    }

    /* 50 % duty cycle on a 0–100 range */
    unsigned duty = (unsigned)(50.0f * 100.0f / 100.0f);
    if (gpioHardwarePWM(BUZZER_PIN, (unsigned)frequency, duty) < 0) {
        fprintf(stderr, "Error: gpioHardwarePWM(%u, %.2f) failed\n",
                BUZZER_PIN, frequency);
        return -1;
    }
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(trigger) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(echo) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(buzzer) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure known initial states */
    gpioWrite(TRIGGER_PIN, 0);
    gpioHardwarePWM(BUZZER_PIN, 0, 0);

    /* Signal handling for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        gpioHardwarePWM(BUZZER_PIN, 0, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        gpioHardwarePWM(BUZZER_PIN, 0, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            /* Error already logged; silence buzzer and wait before retry */
            gpioHardwarePWM(BUZZER_PIN, 0, 0);
            gpioDelay(MEASURE_GAP_US);
            continue;
        }

        float frequency = map_distance_to_frequency(distance);

        if (set_buzzer_frequency(frequency) < 0) {
            /* Error already logged; wait before retry */
            gpioDelay(MEASURE_GAP_US);
            continue;
        }

        printf("Distance: %.2f cm  ->  Frequency: %.2f Hz\n", distance, frequency);

        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown */
    gpioHardwarePWM(BUZZER_PIN, 0, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nTheremin stopped.\n");
    return EXIT_SUCCESS;
}

