#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

#define PWM_RANGE 255
#define PWM_FREQ  1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void set_rgb(int r, int g, int b) {
    /* Common-anode: invert values (0 = full brightness, 255 = off) */
    gpioPWM(RED_PIN,   PWM_RANGE - r);
    gpioPWM(GREEN_PIN, PWM_RANGE - g);
    gpioPWM(BLUE_PIN,  PWM_RANGE - b);
}

static void turn_off_led(void) {
    /* Common-anode: 255 turns everything off */
    gpioPWM(RED_PIN,   PWM_RANGE);
    gpioPWM(GREEN_PIN, PWM_RANGE);
    gpioPWM(BLUE_PIN,  PWM_RANGE);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not register SIGINT handler.\n");
    }

    /* Configure PWM on each channel */
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO modes.\n");
        turn_off_led();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN,   PWM_RANGE) != 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(BLUE_PIN,  PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range.\n");
        turn_off_led();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN,   PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(BLUE_PIN,  PWM_FREQ) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency.\n");
        turn_off_led();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with LED off */
    turn_off_led();

    /* Simulated proximity: sine wave 0.0 to 1.0 */
    while (running) {
        double proximity = 0.5 + 0.5 * sin(time_time());
        if (proximity < 0.0) proximity = 0.0;
        if (proximity > 1.0) proximity = 1.0;

        int r = (int)(proximity * 255.0);
