#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define WINDOW_SIZE 5
#define DEFAULT_TIMEOUT_MS 1000
#define LOG_FILE "vibration_events.log"

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm timeinfo;
    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &timeinfo);
}

static void log_event(int value) {
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    if (log_file != NULL) {
        if (fprintf(log_file, "%s,%d\n", ts, value) < 0) {
            fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        } else {
            fflush(log_file);
            if (fsync(fileno(log_file)) == -1) {
                fprintf(stderr, "Warning: fsync failed on log file: %s\n", strerror(errno));
            }
        }
    }
}

static void check_earthquake_alert(const int *window, int size) {
    int count_high = 0;
    for (int i = 0; i < size; i++) {
        if (window[i] == 1) count_high++;
    }
    if (count_high >= 3) {
        char ts[32];
        get_timestamp(ts, sizeof(ts));
        printf("EARTHQUAKE ALERT! Timestamp: %s\n", ts);
        fflush(stdout);
    }
}

int main(int argc, char *argv[]) {
    int timeout_ms = DEFAULT_TIMEOUT_MS;
    if (argc > 1) {
        timeout_ms = atoi(argv[1]);
        if (timeout_ms <= 0) {
            fprintf(stderr, "Invalid timeout value. Using default: %d ms\n", DEFAULT_TIMEOUT_MS);
            timeout_ms = DEFAULT_TIMEOUT_MS;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
    }

    int window[WINDOW_SIZE];
    int window_index = 0;
    int window_filled = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        window[i] = 0;
    }

    printf("Monitoring SW-420 vibration sensor on GPIO %d (timeout %d ms)...\n", GPIO_PIN, timeout_ms);
    fflush(stdout);

    while (program_running) {
        int level = gpioRead(GPIO_PIN);
        if (level < 0) {
            fprintf(stderr, "Error reading GPIO %d\n", GPIO_PIN);
            break;
        }

        log_event(level);

        int current_value = level;

        if (window_filled < WINDOW_SIZE) {
            window[window_index] = current_value;
            window_index = (window_index + 1) % WINDOW_SIZE;
            window_filled++;
        } else {
            int oldest = window[(window_index + WINDOW_SIZE - 1) % WINDOW_SIZE];
            int new_index = (window_index + 1) % WINDOW_SIZE;
            window[new_index] = current_value;
            memmove(window, window + 1, (WINDOW_SIZE - 1) * sizeof(int));
            window[WINDOW_SIZE - 1] = current_value;
            window_index = new_index;
        }

        check_earthquake_alert(window, window_filled);

        usleep(timeout_ms * 1000);
    }

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

