#define LSM303_MAG_REGISTER_Y_OUT_L 0x0A
#define LSM303_MAG_REGISTER_Y_OUT_H 0x0B
#define LSM303_MAG_REGISTER_Z_OUT_L 0x0C
#define LSM303_MAG_REGISTER_Z_OUT_H 0x0D
#define LSM303_MAG_REGISTER_CRA_REG_M 0x00
#define LSM303_MAG_REGISTER_CRB_REG_M 0x01
#define LSM303_MAG_REGISTER_MR_REG_M 0x02

