        return -1;
    }
    /* Magnetometer gain = 1.3 Gauss (CRB_REG_M = 0x00) */
    if (i2c_write_reg8(fd, LSM303_MAG_REGISTER_CRB_REG_M, 0x00) < 0) {
        fprintf(stderr, "Error writing CRB_REG_M: %s\n", strerror(errno));
        return -1;
    }
