#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_MS 200
#define LOG_FILE "relay_log.json"

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t last_touch_tick = 0;
static volatile sig_atomic_t relay_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(int relay_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    char timestamp[32];
    if (localtime_r(&t, &tm_info) &&
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) > 0) {
        fprintf(fp, "{\"timestamp\": \"%s\", \"relay_state\": \"%s\"}\n",
                timestamp, relay_state ? "ON" : "OFF");
    } else {
        fprintf(fp, "{\"timestamp\": \"UNKNOWN\", \"relay_state\": \"%s\"}\n",
                relay_state ? "ON" : "OFF");
    }

    if (fclose(fp) != 0) {
        perror("fclose(" LOG_FILE ")");
    }
}

static void touch_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;

    if (level != 1) {
        return;
    }

    uint32_t diff = tick - last_touch_tick;
    if (diff < DEBOUNCE_MS * 1000) {
        return;
    }
    last_touch_tick = tick;

    relay_state = !relay_state;
    if (gpioWrite(RELAY_PIN, relay_state) != 0) {
        fprintf(stderr, "gpioWrite(RELAY_PIN, %d) failed\n", relay_state);
        return;
    }

    log_event(relay_state);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(TOUCH_SENSOR_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(TOUCH_SENSOR_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(RELAY_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite(RELAY_PIN, 0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(TOUCH_SENSOR_PIN, RISING_EDGE, 0, touch_isr, NULL) != 0) {
        fprintf(stderr, "gpioSetISRFuncEx failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioSetISRFuncEx(TOUCH_SENSOR_PIN, RISING_EDGE, 0, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch-controlled relay running. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100 * 1000);
    }

    gpioWrite(RELAY_PIN, 0);
    gpioSetISRFuncEx(TOUCH_SENSOR_PIN, RISING_EDGE, 0, NULL, NULL);
    gpioTerminate();

    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

