/*
 * Automated Plant Watering System - Raspberry Pi Zero W
 *
 * Hardware:
 *   - Two SG90 servos
 *       Valve servo  -> GPIO17 (physical pin 11, BCM)
 *       Nozzle servo -> GPIO18 (physical pin 12, BCM)
 *   - 5 V power supply (external, capable of supplying 2 A)
 *   - Two 3-pin headers for signal (GPIO), VCC, and GND
 *
 * Behavior:
 *   - Reads a simulated moisture level that cycles through [20, 40, 60, 80, 100] every second.
 *   - If moisture < 50, opens the valve (90 deg / 1500 us), sweeps the nozzle
 *     through 0, 45, 90, 135, 180 deg, holds spray for 5 s, closes valve,
 *     waits 5 s, repeats.
 *   - Skips the cycle if moisture >= 50.
 *   - Every servo command is retried 3 times on failure with 100 ms backoff.
 *   - On unrecoverable error, exits cleanly (no GPIO calls in signal handler).
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#include "servo_library.h"

#define VALVE_SERVO_PIN    17
#define NOZZLE_SERVO_PIN   18

#define MOISTURE_THRESHOLD 50
#define NUM_NOZZLE_ANGLES  5
#define VALVE_OPEN_US      1500
#define VALVE_CLOSED_US    500
#define NOZZLE_MIN_US      500
#define NOZZLE_MAX_US      2500
#define SPRAY_HOLD_S       5
#define CYCLE_DELAY_S      5
#define RETRY_DELAY_MS     100
#define MAX_RETRIES        3

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

/*
 * Open the valve servo to 90 degrees.
 * Returns 0 on success, -1 on failure.
 */
static int open_valve(void)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (servo_set_pulse_width(VALVE_SERVO_PIN, VALVE_OPEN_US) == 0)
            return 0;
        fprintf(stderr, "Valve open attempt %d/%d failed: %s\n",
                attempt + 1, MAX_RETRIES, strerror(errno));
        sleep_ms(RETRY_DELAY_MS);
    }
    return -1;
}

/*
 * Close the valve servo to 0 degrees.
 * Returns 0 on success, -1 on failure (warning: valve may remain open).
 */
static int close_valve(void)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (servo_set_pulse_width(VALVE_SERVO_PIN, VALVE_CLOSED_US) == 0)
            return 0;
        fprintf(stderr, "Valve close attempt %d/%d failed: %s\n",
                attempt + 1, MAX_RETRIES, strerror(errno));
        sleep_ms(RETRY_DELAY_MS);
    }
    fprintf(stderr, "CRITICAL: valve failed to close after %d retries\n", MAX_RETRIES);
    return -1;
}

/*
 * Set the nozzle servo to the given angle (0-180).
 * Returns 0 on success, -1 on failure.
 */
static int set_nozzle_angle(int angle)
{
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Invalid nozzle angle %d\n", angle);
        return -1;
    }
    int pulse_us = NOZZLE_MIN_US + (angle * (NOZZLE_MAX_US - NOZZLE_MIN_US) / 180);
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (servo_set_pulse_width(NOZZLE_SERVO_PIN, pulse_us) == 0)
            return 0;
        fprintf(stderr, "Nozzle angle %d attempt %d/%d failed: %s\n",
                angle, attempt + 1, MAX_RETRIES, strerror(errno));
        sleep_ms(RETRY_DELAY_MS);
    }
    return -1;
}

/*
 * Watering cycle: open valve, sweep nozzle, close valve, wait.
 * Returns 0 on success, -1 on failure.
 */
static int water_plant(void)
{
    if (open_valve() != 0)
        return -1;

    for (int angle = 0; angle < NUM_NOZZLE_ANGLES && g_running; angle++) {
        if (set_nozzle_angle(angle * 45) != 0) {
            fprintf(stderr, "Warning: nozzle angle %d failed, continuing\n", angle);
            continue;
        }
        printf("Spraying at angle %d degrees for %d seconds...\n",
               angle * 45, SPRAY_HOLD_S);
        fflush(stdout);
        sleep(SPRAY_HOLD_S);
    }

    if (close_valve() != 0)
        return -1;

    printf("Watering cycle complete.\n");
    fflush(stdout);
    return 0;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize servo library */
    if (servo_init() != 0) {
        fprintf(stderr, "FATAL: servo_init() failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int moisture = 20;
    printf("Plant Watering System started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        printf("Simulated moisture level: %d\n", moisture);
        fflush(stdout);

        if (moisture < MOISTURE_THRESHOLD) {
            printf("Moisture below threshold (%d). Watering plant...\n", MOISTURE_THRESHOLD);
            fflush(stdout);
            if (water_plant() != 0) {
                fprintf(stderr, "FATAL: water_plant() failed. Exiting.\n");
                break;
            }
        } else {
            printf("Moisture at or above threshold (%d). Skipping watering.\n", MOISTURE_THRESHOLD);
            fflush(stdout);
        }

        sleep(CYCLE_DELAY_S);

        moisture = (moisture + 1) % 100;
    }

    /* Clean shutdown: stop servos and release library resources */
    printf("\nShutting down...\n");
    fflush(stdout);
    servo_stop_all();
    servo_cleanup();
    printf("Plant Watering System stopped.\n");
    fflush(stdout);
    return EXIT_SUCCESS;
}

