#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* L293D coil inputs (BCM numbering) */
#define IN1 4
#define IN2 17
#define IN3 27
#define IN4 22

/* Button inputs (BCM numbering) */
#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23

/* Motor parameters */
#define STEPS_PER_ROTATION 512
#define STEP_DELAY_US 3000

/* Debounce window */
#define DEBOUNCE_WINDOW 50

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* De-energize all coils (reduce power consumption and heating) */
static void coils_off(void) {
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);
}

/* Full-step (single-coil) excitation for one direction */
static void step_full(int in1, int in2, int in3, int in4, int direction) {
    if (direction == 1) {
        gpioWrite(in1, 1);
        gpioWrite(in2, 0);
        gpioWrite(in3, 0);
        gpioWrite(in4, 0);
    } else if (direction == -1) {
        gpioWrite(in1, 0);
        gpioWrite(in2, 1);
        gpioWrite(in3, 0);
        gpioWrite(in4, 0);
    } else {
        /* direction == 0: de-energize */
        coils_off();
    }
}

/* Rotate a given number of full-steps in the given direction */
static int rotate_steps(int steps, int direction) {
    for (int i = 0; i < steps && g_running; i++) {
        step_full(IN1, IN2, IN3, IN4, direction);
        gpioDelay(STEP_DELAY_US);
    }
    coils_off();
    return 0;
}

/* Read a button with internal pull-up and active-low logic */
static int read_button(int gpio) {
    int v = gpioRead(gpio);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO %d\n", gpio);
        return -1;
    }
    return (v == 0) ? 1 : 0;
}

int main(void) {
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure L293D coil inputs as outputs */
    if (gpioSetMode(IN1, PI_OUTPUT) != 0 ||
        gpioSetMode(IN2, PI_OUTPUT) != 0 ||
        gpioSetMode(IN3, PI_OUTPUT) != 0 ||
        gpioSetMode(IN4, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set L293D coil pin modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure button inputs with internal pull-ups */
    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) != 0 ||
        gpioSetMode(UNLOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set button pin modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP);

    /* Ensure coils start de-energized */
    coils_off();

    printf("Door lock/unlock system ready.\n");
    printf("  LOCK  button: GPIO%d (active-low)\n", LOCK_BUTTON);
    printf("  UNLOCK button: GPIO%d (active-low)\n", UNLOCK_BUTTON);
    printf("  L293D coils: IN1=GPIO%d, IN2=GPIO%d, IN3=GPIO%d, IN4=GPIO%d\n",
           IN1, IN2, IN3, IN4);
    printf("Press Ctrl-C to exit.\n");

    int lock_state = 0;

    while (g_running) {
        /* --- Lock button (active-low) --- */
        int lock_pressed = read_button(LOCK_BUTTON);
        if (lock_pressed < 0) {
            /* Read error: back off briefly and retry */
            gpioDelay(100000);
            continue;
        }

        if (lock_pressed && !lock_state) {
            printf("Locking door...\n");
            fflush(stdout);
            if (rotate_steps(STEPS_PER_ROTATION, 1) != 0) {
                fprintf(stderr, "Error: lock rotation failed\n");
            } else {
                lock_state = 1;
            }
        }

        /* Debounce window for lock button */
        gpioDelay(DEBOUNCE_WINDOW * 1000);

        /* --- Unlock button (active-low) --- */
        int unlock_pressed = read_button(UNLOCK_BUTTON);
        if (unlock_pressed < 0) {
            gpioDelay(100000);
            continue;
        }

        if (unlock_pressed && lock_state) {
            printf("Unlocking door...\n");
            fflush(stdout);
            if (rotate_steps(STEPS_PER_ROTATION, -1) != 0) {
                fprintf(stderr, "Error: unlock rotation failed\n");
            } else {
                lock_state = 0;
            }
        }

        gpioDelay(10000); /* 10 ms poll interval */
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    coils_off();
    gpioTerminate();
    return EXIT_SUCCESS;
}

