#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define RELAY_PIN      18
#define DISTANCE_THRESHOLD 50
#define POLL_DELAY_US  100000

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define REG_SOFT_RESET              0x0003
#define REG_I2C_SLAVE_DEVICE_CONFIG 0x0001
#define REG_SYSTEM_MODE_START      0x0000
#define REG_RESULT_RANGE_STATUS    0x0089
#define REG_RESULT_DISTANCE        0x0096

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int read_reg16(int handle, uint16_t reg, uint8_t *buf, uint8_t len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) < 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int init_sensor(int handle) {
    /* Soft reset */
    if (write_reg16(handle, REG_SOFT_RESET, 0x00) < 0) return -1;
    gpioDelay(1000);
    if (write_reg16(handle, REG_SOFT_RESET, 0x01) < 0) return -1;
    gpioDelay(1000);

    /* Set I2C standard mode (100 kHz) */
    if (write_reg16(handle, REG_I2C_SLAVE_DEVICE_CONFIG, 0x04) < 0) return -1;

    /* Start continuous ranging */
    if (write_reg16(handle, REG_SYSTEM_MODE_START, 0x00) < 0) return -1;
    gpioDelay(1000);
    if (write_reg16(handle, REG_SYSTEM_MODE_START, 0x40) < 0) return -1;
    gpioDelay(1000);

    return 0;
}

static int read_distance(int handle, uint8_t *distance_mm) {
    uint8_t status = 0;
    uint8_t dist_buf[2] = {0};

    if (read_reg16(handle, REG_RESULT_RANGE_STATUS, &status, 1) < 0) return -1;
    if ((status & 0x01) == 0) return 1; /* data not ready */

    if (read_reg16(handle, REG_RESULT_DISTANCE, dist_buf, 2) < 0) return -1;

    *distance_mm = (dist_buf[0] << 8) | dist_buf[1];
    return 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X (code %d).\n",
                I2C_BUS, VL53L1X_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_sensor(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: Failed to initialise VL53L1X sensor.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output.\n", RELAY_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L1X distance monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint8_t distance_mm = 0;
        int rc = read_distance(g_i2c_handle, &distance_mm);

        if (rc == 0) {
            float distance_cm = (float)distance_mm / 10.0f;
            printf("Distance: %.2f cm\n", distance_cm);

            if (distance_cm <= DISTANCE_THRESHOLD) {
                gpioWrite(RELAY_PIN, 1);
            } else {
                gpioWrite(RELAY_PIN, 0);
            }
        } else if (rc < 0) {
            fprintf(stderr, "Error: I2C read failed (code %d).\n", rc);
        }
        /* rc == 1: data not ready, silently skip */

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

