/* Write one byte to an 8-bit register. Returns 0 on success, -1 on error. */
static int reg_write8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "reg_write8(0x%02X, 0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, value, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* Read one byte from an 8-bit register. Returns 0 on success, -1 on error. */
static int reg_read8(int fd, uint8_t reg, uint8_t *out)
{
    /* Send the register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "reg_read8: write pointer 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    /* Read one byte back */
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "reg_read8: read 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

/* ------------------------------------------------------------------ */
static int mpu6050_init(int fd)
{
    /* Sample rate divider = 7 -> 1 kHz / (1 + 7) = 125 Hz */
    if (reg_write8(fd, REG_SMPLRT_DIV, 0x07) < 0)
        return -1;

    /* DLPF_CFG = 0 -> bandwidth 256 Hz, delay 0.98 ms */
    if (reg_write8(fd, REG_CONFIG, 0x00) < 0)
        return -1;

    /* Gyro full-scale range: +/- 250 dps (FS_SEL = 0) */
    if (reg_write8(fd, REG_GYRO_CONFIG, GYRO_SCALE_250_DPS) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_gyro_axes(int fd, int16_t *gx, int16_t *gy, int16_t *gz)
{
    uint8_t buf[6];

    /* Set register pointer to GYRO_XOUT_H (0x43) */
    uint8_t reg = REG_GYRO_XOUT_H;
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "read_gyro_axes: write pointer failed: %s\n",
                strerror(errno));
        return -1;
    }

    /* Read 6 bytes: X_H, X_L, Y_H, Y_L, Z_H, Z_L */
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "read_gyro_axes: read failed: %s (got %zd bytes)\n",
                strerror(errno), n);
        return -1;
    }

    *gx = (int16_t)((buf[0] << 8) | buf[1]);
    *gy = (int16_t)((buf[2] << 8) | buf[3]);
    *gz = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    g_i2c_fd = open(MPU6050_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", MPU6050_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the MPU-6050 slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                MPU6050_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (mpu6050_init(g_i2c_fd) < 0) {
        fprintf(stderr, "MPU-6050 initialization failed (sensor absent or bus error).\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MPU-6050 Gyroscope Reader\n");
    printf("Bus: %s  Address: 0x%02X  Scale: +/- 250 dps\n",
           MPU6050_BUS, MPU6050_ADDR);
    printf("Press Ctrl+C to exit.\n\n");

    /* Main acquisition loop */
    while (g_running) {
        int16_t gx, gy, gz;

        if (read_gyro_axes(g_i2c_fd, &gx, &gy, &gz) < 0) {
            fprintf(stderr, "Read error — continuing.\n");
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        /* Convert raw to degrees per second (dps) */
        float gx_dps = (float)gx / 131.0f;   /* 131 LSB/dps at +/- 250 dps */
        float gy_dps = (float)gy / 131.0f;
        float gz_dps = (float)gz / 131.0f;

        printf("Gyro X: %7.2f dps  Y: %7.2f dps  Z: %7.2f dps\n",
               gx_dps, gy_dps, gz_dps);

        usleep(SAMPLE_DELAY_US);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

