/*
 * Automated Plant Watering System — Raspberry Pi 4 Model B
 *
 * Four 5 V relay modules on BCM GPIO17, GPIO18, GPIO27, GPIO22 (physical
 * pins 11, 12, 13, 15) are driven via the libgpiod character-device API.
 * Each relay is energised for 5 s, once per 24 h cycle, logging the start
 * time to watering_log.txt.  SIGINT/SIGTERM triggers a clean shutdown.
 *
 * Build:  gcc -O2 -Wall -Wextra -o watering watering.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#include <gpiod.h>

#define NUM_RELAYS      4
#define RELAY_ON_SEC    5
#define CYCLE_PERIOD_S  86400          /* 24 hours */
#define POLL_INTERVAL_S 60
#define LOG_FILE        "watering_log.txt"

static const unsigned int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void log_timestamp(const char *filename)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_local;
    if (localtime_r(&now, &tm_local) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char buf[32];
    if (strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_local) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", filename, strerror(errno));
        return;
    }

    if (fprintf(fp, "%s\n", buf) < 0)
        fprintf(stderr, "fprintf() failed: %s\n", strerror(errno));

    if (fclose(fp) != 0)
        fprintf(stderr, "fclose() failed: %s\n", strerror(errno));
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ------------------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip ------------------------------------------- */
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        /* Fallback: try the first chip found (gpiochip0 on older kernels) */
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Request relay lines as outputs, initial HIGH (inactive) ---- */
    struct gpiod_line *lines[NUM_RELAYS];
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line(%u) failed: %s\n",
                    relay_pins[i], strerror(errno));
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        if (gpiod_line_request_output(lines[i], "plant-watering", 1) < 0) {
            fprintf(stderr, "gpiod_line_request_output(%u) failed: %s\n",
                    relay_pins[i], strerror(errno));
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    /* ---- Main loop ------------------------------------------------ */
    time_t cycle_start = time(NULL);
    if (cycle_start == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Plant watering system started.  GPIO pins: %u, %u, %u, %u\n",
           relay_pins[0], relay_pins[1], relay_pins[2], relay_pins[3]);
    printf("Cycle starts at %s.  Press Ctrl+C to exit.\n",
           ctime(&cycle_start));

    while (g_running) {
        time_t now = time(NULL);
        if (now == (time_t)-1) {
            fprintf(stderr, "time() failed: %s\n", strerror(errno));
            break;
        }

        if ((now - cycle_start) >= CYCLE_PERIOD_S) {
            printf("Cycle complete.  Logging start time...\n");
            log_timestamp(LOG_FILE);

            cycle_start = now;

            for (int i = 0; i < NUM_RELAYS && g_running; i++) {
                printf("Activating relay on GPIO%u for %d s...\n",
                       relay_pins[i], RELAY_ON_SEC);

                if (gpiod_line_set_value(lines[i], 0) < 0) {   /* active-low */
                    fprintf(stderr, "gpiod_line_set_value(%u, 0) failed: %s\n",
                            relay_pins[i], strerror(errno));
                    continue;
                }

                /* Sleep in 1 s increments so signals are caught promptly */
                for (int s = 0; s < RELAY_ON_SEC && g_running; s++)
                    sleep(1);

                if (gpiod_line_set_value(lines[i], 1) < 0) {   /* inactive */
                    fprintf(stderr, "gpiod_line_set_value(%u, 1) failed: %s\n",
                            relay_pins[i], strerror(errno));
                }
            }
        } else {
            /* Wait for the next cycle boundary while remaining responsive */
            for (int s = 0; s < POLL_INTERVAL_S && g_running; s++)
                sleep(1);
        }
    }

    /* ---- Cleanup -------------------------------------------------- */
    printf("\nShutting down...\n");
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpiod_line_set_value(lines[i], 1) < 0)
            fprintf(stderr, "Warning: failed to reset GPIO%u: %s\n",
                    relay_pins[i], strerror(errno));
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    printf("Plant watering system stopped.\n");
    return EXIT_SUCCESS;
}

