#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define SUNRISE_DURATION 1800
#define LOG_FILE "smart_lighting.log"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO%d as output\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }

    if (gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(RELAY1_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(RELAY2_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(RELAY3_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(RELAY4_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void set_relay_intensity(int pin, int intensity) {
    if (intensity < 0) intensity = 0;
    if (intensity > PWM_RANGE) intensity = PWM_RANGE;
    if (gpioPWM(pin, intensity) != 0) {
        fprintf(stderr, "Failed to set PWM on GPIO%d\n", pin);
    }
}

static void sunrise_simulation(void) {
    int step = 0;
    int intensity = 0;
    char log_buffer[128];

    while (running && step < SUNRISE_DURATION) {
        intensity = (step * PWM_RANGE) / SUNRISE_DURATION;

        set_relay_intensity(RELAY1_PIN, intensity);
        set_relay_intensity(RELAY2_PIN, intensity);
        set_relay_intensity(RELAY3_PIN, intensity);
        set_relay_intensity(RELAY4_PIN, intensity);

        snprintf(log_buffer, sizeof(log_buffer),
                 "Sunrise simulation: step %d, intensity %d", step, intensity);
        log_event(log_buffer);

        sleep(1);
        step++;
    }
}

static void sunset_simulation(void) {
    int step = 0;
    int intensity = PWM_RANGE;
    char log_buffer[128];

    while (running && step < SUNRISE_DURATION) {
        intensity = (SUNRISE_DURATION - step) * PWM_RANGE / SUNRISE_DURATION;

        set_relay_intensity(RELAY1_PIN, intensity);
        set_relay_intensity(RELAY2_PIN, intensity);
        set_relay_intensity(RELAY3_PIN, intensity);
        set_relay_intensity(RELAY4_PIN, intensity);

        snprintf(log_buffer, sizeof(log_buffer),
                 "Sunset simulation: step %d, intensity %d", step, intensity);
        log_event(log_buffer);

        sleep(1);
        step++;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_event("Smart lighting simulation started");

    sunrise_simulation();

    if (!running) {
        log_event("Interrupted during sunrise simulation");
    } else {
        log_event("Sunrise simulation complete");
    }

    sunset_simulation();

    if (!running) {
        log_event("Interrupted during sunset simulation");
    } else {
        log_event("Sunset simulation complete");
    }

    set_relay_intensity(RELAY1_PIN, 0);
    set_relay_intensity(RELAY2_PIN, 0);
    set_relay_intensity(RELAY3_PIN, 0);
    set_relay_intensity(RELAY4_PIN, 0);

    gpioTerminate();
    log_event("Smart lighting simulation finished");

    return EXIT_SUCCESS;
}

