/*
 * MPU-6050 Gyroscope Reader with LED Threshold Indicator
 * Board:  Raspberry Pi 3 Model B+
 * Library: pigpio (modern API, no wiringPi)
 *
 * Wiring:
 *   MPU-6050 SDA -> GPIO2 (BCM)
 *   MPU-6050 SCL -> GPIO3 (BCM)
 *   MPU-6050 VCC -> 3.3 V
 *   MPU-6050 GND -> GND
 *   LED anode   -> GPIO17 (BCM) through 330 Ω resistor
 *   LED cathode -> GND
 *
 * Build:  gcc -O2 -Wall -o mpu6050_gyro mpu6050_gyro.c -lpigpio -lrt -lm
 * Run:    sudo ./mpu6050_gyro
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- MPU-6050 constants (verified against datasheet) ---- */
#define MPU6050_ADDR        0x68
#define MPU6050_REG_SMPLRT_DIV  0x19
#define MPU6050_REG_CONFIG     0x1A
#define MPU6050_REG_GYRO_XOUT_H 0x43
#define MPU6050_REG_PWR_MGMT_1  0x6B

/* ---- Application constants ---- */
#define I2C_BUS             1
#define LED_GPIO            17
#define BUFFER_SIZE         100
#define SAMPLE_PERIOD_US    50000   /* 50 ms -> 20 Hz */
#define GYRO_THRESHOLD      250.0   /* degrees/second */
#define MAX_REINIT_ATTEMPTS 3

/* ---- Data structures ---- */
typedef struct {
    int16_t x, y, z;
} gyro_data_t;

typedef struct {
    struct timespec timestamp;
    gyro_data_t data;
} gyro_sample_t;

/* ---- Globals ---- */
static int i2c_handle = -1;
static gyro_sample_t gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static volatile sig_atomic_t terminate = 0;

/* ---- Prototypes ---- */
static int  init_mpu6050(void);
static int  read_gyro_data(gyro_data_t *out);
static void add_to_buffer(const gyro_data_t *data, const struct timespec *ts);
static void check_threshold_and_control_led(const gyro_data_t *data);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO as output and ensure it starts OFF */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Initialize MPU-6050 */
    if (init_mpu6050() != 0) {
        fprintf(stderr, "Error: MPU-6050 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MPU-6050 gyroscope reader started. Sampling at 20 Hz.\n");
    printf("Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (!terminate) {
        gyro_data_t gyro_data;

        if (read_gyro_data(&gyro_data) != 0) {
            fprintf(stderr, "Warning: gyro read failed; re-initializing I2C.\n");
            if (init_mpu6050() != 0) {
                fprintf(stderr, "Error: I2C re-initialization failed. Exiting.\n");
                break;
            }
            continue;  /* skip this sample, try again next iteration */
        }

        /* Timestamp */
        clock_gettime(CLOCK_MONOTONIC, &gyro_buffer[buffer_index].timestamp);

        /* Store in circular buffer */
        add_to_buffer(&gyro_data, &gyro_buffer[buffer_index].timestamp);

        /* Threshold check and LED control */
        check_threshold_and_control_led(&gyro_data);

        /* Advance buffer index */
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        /* Wait for next 50 ms sample window */
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Clean shutdown */
    cleanup();
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

/* ------------------------------------------------------------------ */
/* Initialize MPU-6050: verify device presence, configure sample rate.   */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int init_mpu6050(void)
{
    /* Verify device presence by reading PWR_MGMT_1 */
    int reg = i2cReadByteData(i2c_handle, MPU6050_REG_PWR_MGMT_1);
    if (reg < 0) {
        fprintf(stderr, "Error: MPU-6050 not responding at address 0x%02X (read failed).\n",
                MPU6050_ADDR);
        return -1;
    }

    /* Wake up the device (clear SLEEP bit) */
    if (i2cWriteByteData(i2c_handle, MPU6050_REG_PWR_MGMT_1, 0x00) != 0) {
        fprintf(stderr, "Error: failed to write PWR_MGMT_1.\n");
        return -1;
    }
    gpioDelay(10000);  /* 10 ms stabilization */

    /* Set sample rate divider to 7 -> 1 kHz / (1 + 7) = 125 Hz */
    if (i2cWriteByteData(i2c_handle, MPU6050_REG_SMPLRT_DIV, 0x07) != 0) {
        fprintf(stderr, "Error: failed to write SMPLRT_DIV.\n");
        return -1;
    }

    /* Configure DLPF (digital low-pass filter) to bandwidth 256 Hz */
    if (i2cWriteByteData(i2c_handle, MPU6050_REG_CONFIG, 0x02) != 0) {
        fprintf(stderr, "Error: failed to write CONFIG.\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of gyroscope X/Y/Z data (registers 0x43–0x48).         */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int read_gyro_data(gyro_data_t *out)
{
    char buf[6];

    if (i2cReadI2CBlockData(i2c_handle, MPU6050_REG_GYRO_XOUT_H, buf, 6) != 6) {
        return -1;
    }

    out->x = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    out->y = (int16_t)((buf[2] << 8) | (uint8_t)buf[3]);
    out->z = (int16_t)((buf[4] << 8) | (uint8_t)buf[5]);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Add a sample to the circular buffer.                               */
/* ------------------------------------------------------------------ */
static void add_to_buffer(const gyro_data_t *data, const struct timespec *ts)
{
    gyro_buffer[buffer_index].timestamp = *ts;
    gyro_buffer[buffer_index].data     = *data;
}

/* ------------------------------------------------------------------ */
/* Turn LED on when any axis exceeds threshold, off otherwise.         */
/* ------------------------------------------------------------------ */
static void check_threshold_and_control_led(const gyro_data_t *data)
{
    bool exceed = (fabs((double)data->x) > GYRO_THRESHOLD ||
                   fabs((double)data->y) > GYRO_THRESHOLD ||
                   fabs((double)data->z) > GYRO_THRESHOLD);

    if (exceed) {
        gpioWrite(LED_GPIO, 1);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

/* ------------------------------------------------------------------ */
/* Release all resources.                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Signal handler — set terminate flag so the main loop exits.        */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

