#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MPU-6050 Registers */
#define MPU6050_REG_SMPLRT_DIV   0x19
#define MPU6050_REG_CONFIG       0x1A
#define MPU6050_REG_GYRO_CONFIG  0x1B
#define MPU6050_REG_GYRO_XOUT_H  0x43
#define MPU6050_REG_PWR_MGMT_1   0x6B

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   3900000  /* 3.9 MHz */
#define SPI_FLAGS   0        /* Mode 0, active-low CE */

/* GPIO Configuration */
#define LED_PIN 17

/* Circular Buffer Configuration */
#define BUFFER_SIZE 64

/* Threshold Configuration */
#define VELOCITY_THRESHOLD 200.0f

/* Data Structure */
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
    struct timespec timestamp;
} gyro_data_t;

/* Circular Buffer */
static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;

/* SPI Handle */
static int spi_handle = -1;

/* Program state */
static volatile sig_atomic_t program_running = 1;

/* Function Prototypes */
static int spi_init(void);
static int mpu6050_init(void);
static int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
static void add_to_buffer(int16_t x, int16_t y, int16_t z);
static bool check_threshold(int16_t x, int16_t y, int16_t z);
static void blink_led(int times);
static void signal_handler(int signal);
static void print_buffer(void);
static void cleanup(void);

/* SPI Initialization */
static int spi_init(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

/* MPU-6050 Initialization */
static int mpu6050_init(void) {
    /* Wake up the MPU-6050 (clear sleep bit) */
    if (spiWriteByteData(spi_handle, MPU6050_REG_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms delay for stabilization */

    /* Set sample rate divider to 7 (1 kHz / (1 + 7) = 125 Hz) */
    if (spiWriteByteData(spi_handle, MPU6050_REG_SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Error writing to SMPLRT_DIV\n");
        return -1;
    }

    /* Configure DLPF (Digital Low Pass Filter) */
    if (spiWriteByteData(spi_handle, MPU6050_REG_CONFIG, 0x01) < 0) {
        fprintf(stderr, "Error writing to CONFIG\n");
        return -1;
    }

    /* Set gyro full-scale range to +/- 250 degrees/sec */
    if (spiWriteByteData(spi_handle, MPU6050_REG_GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing to GYRO_CONFIG\n");
        return -1;
    }

    return 0;
}

/* Read Gyroscope Data */
static int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    /* Read 6 bytes starting from GYRO_XOUT_H (0x43) */
    if (spiReadI2CBlockData(spi_handle, MPU6050_REG_GYRO_XOUT_H, buffer, 6) != 6) {
        fprintf(stderr, "Error reading gyro data\n");
        return -1;
    }

    /* Data is little-endian: LSB first, then MSB */
    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

/* Add Data to Circular Buffer */
static void add_to_buffer(int16_t x, int16_t y, int16_t z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    gyro_buffer[buffer_index].timestamp = ts;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

/* Check Threshold */
static bool check_threshold(int16_t x, int16_t y, int16_t z) {
    if (abs(x) > VELOCITY_THRESHOLD || abs(y) > VELOCITY_THRESHOLD || abs(z) > VELOCITY_THRESHOLD) {
        return true;
    }
    return false;
}

/* Blink LED */
static void blink_led(int times) {
    for (int i = 0; i < times; i++) {
        gpioWrite(LED_PIN, 1);
        gpioDelay(500000); /* 500 ms */
        gpioWrite(LED_PIN, 0);
        gpioDelay(500000); /* 500 ms */
    }
}

/* Signal Handler */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Print Circular Buffer */
static void print_buffer(void) {
    printf("Timestamp,X,Y,Z\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (buffer_index + i) % BUFFER_SIZE;
        printf("%ld.%09ld,%d,%d,%d\n",
               gyro_buffer[idx].timestamp.tv_sec,
               gyro_buffer[idx].timestamp.tv_nsec,
               gyro_buffer[idx].x,
               gyro_buffer[idx].y,
               gyro_buffer[idx].z);
    }
}

/* Cleanup */
static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set LED pin as output */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Initialize SPI */
    if (spi_init() != 0) {
        gpioTerminate();
        return 1;
    }

    /* Initialize MPU-6050 */
    if (mpu6050_init() != 0) {
        cleanup();
        return 1;
    }

    /* Set up signal handler */
    signal(SIGINT, signal_handler);

    int16_t x, y, z;

    printf("Monitoring gyroscope data... Press Ctrl+C to exit.\n");

    while (program_running) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            add_to_buffer(x, y, z);

            if (check_threshold(x, y, z)) {
                printf("Threshold exceeded! Blinking LED.\n");
                blink_led(5);
            }
        } else {
            fprintf(stderr, "Failed to read gyro data. Retrying...\n");
        }

        gpioDelay(100000); /* 100 ms delay */
    }

    /* Print buffer contents */
    print_buffer();

    /* Cleanup */
    cleanup();

    printf("Program terminated.\n");
    return 0;
}

