#define MPU6050_REG_ACCEL_XOUT_H 0x3B
#define MPU6050_REG_GYRO_XOUT_H  0x43
#define MPU6050_REG_PWR_MGMT_1   0x6B
#define MPU6050_REG_WHO_AM_I     0x75

/* Expected WHO_AM_I value for MPU-6050 */
#define MPU6050_WHO_AM_I_VAL 0x68

/* GPIO pin for the LED (BCM numbering) */
#define LED_PIN 21

/* Roll and pitch threshold (degrees) */
#define ROLL_PITCH_THRESHOLD 45.0

/* Global variables */
static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

/* Function prototypes */
static int init_mpu6050(void);
static int read_mpu6050_data(int16_t *ax, int16_t *ay, int16_t *az,
                             int16_t *gx, int16_t *gy, int16_t *gz);
static void calculate_roll_pitch(int16_t ax, int16_t ay, int16_t az,
                                  int16_t gx, int16_t gy, int16_t gz,
                                  float *roll, float *pitch);
static void log_data(float roll, float pitch);
static void signal_handler(int signal);

/*
 * Initializes the MPU-6050 sensor.
 * Returns 0 on success, -1 on failure.
 */
static int init_mpu6050(void) {
    /* Read WHO_AM_I to verify sensor presence */
    int who_am_i = i2cReadByteData(i2c_handle, MPU6050_REG_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, MPU6050_WHO_AM_I_VAL);
        return -1;
    }

    /* Wake up the MPU-6050 (clear SLEEP bit) */
    if (i2cWriteByteData(i2c_handle, MPU6050_REG_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1 register\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms stabilization delay */

    /* Set sample rate divider to 7 (1 kHz / (1 + 7) = 125 Hz) */
    if (i2cWriteByteData(i2c_handle, MPU6050_REG_SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Error writing to SMPLRT_DIV register\n");
        return -1;
    }

    /* Configure DLPF (Digital Low Pass Filter) */
    if (i2cWriteByteData(i2c_handle, MPU6050_REG_CONFIG, 0x01) < 0) {
        fprintf(stderr, "Error writing to CONFIG register\n");
        return -1;
    }

    /* Set gyro full-scale range to +/- 250 degrees/sec */
    if (i2cWriteByteData(i2c_handle, MPU6050_REG_GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing to GYRO_CONFIG register\n");
        return -1;
    }

    /* Set accelerometer full-scale range to +/- 2g */
    if (i2cWriteByteData(i2c_handle, MPU6050_REG_ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing to ACCEL_CONFIG register\n");
        return -1;
    }

    return 0;
}

/*
 * Reads raw accelerometer and gyroscope data from the MPU-6050.
 * Returns 0 on success, -1 on failure.
 */
static int read_mpu6050_data(int16_t *ax, int16_t *ay, int16_t *az,
                             int16_t *gx, int16_t *gy, int16_t *gz) {
    char buf[14];

    /* Read 14 bytes starting from ACCEL_XOUT_H (0x3B) */
    if (i2cReadI2CBlockData(i2c_handle, MPU6050_REG_ACCEL_XOUT_H, buf, 14) != 14) {
        fprintf(stderr, "Error reading data block\n");
        return -1;
    }

    /* Parse accelerometer data (big-endian) */
    *ax = (int16_t)((buf[0] << 8) | buf[1]);
    *ay = (int16_t)((buf[2] << 8) | buf[3]);
    *az = (int16_t)((buf[4] << 8) | buf[5]);

    /* Parse temperature data (skipped, not used) */
    /* buf[6] and buf[7] are temperature registers */

    /* Parse gyroscope data (big-endian) */
    *gx = (int16_t)((buf[8] << 8) | buf[9]);
    *gy = (int16_t)((buf[10] << 8) | buf[11]);
    *gz = (int16_t)((buf[12] << 8) | buf[13]);

    return 0;
}

/*
 * Calculates roll and pitch angles in degrees.
 */
static void calculate_roll_pitch(int16_t ax, int16_t ay, int16_t az,
                                  int16_t gx, int16_t gy, int16_t gz,
                                  float *roll, float *pitch) {
    /*
     * Note: The MPU-6050 provides raw sensor data. To compute roll and pitch
     * from accelerometer data, we use the atan2 function with the appropriate
     * sign adjustments. For production use, consider integrating gyroscope
     * data over time to obtain stable orientation.
     */
    float roll_accel = atan2f((float)ax, sqrtf((float)ay * ay + (float)az * az))
                       * 180.0f / (float)M_PI;
    float pitch_accel = atan2f((float)ay, sqrtf((float)ax * ax + (float)az * az))
                        * 180.0f / (float)M_PI;

    *roll = roll_accel;
    *pitch = pitch_accel;
}

/*
 * Logs roll and pitch data to a file in CSV format.
 */
static void log_data(float roll, float pitch) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("tilt_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening tilt_log.txt for writing\n");
        return;
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, roll, pitch);
    fclose(fp);
}

/*
 * Signal handler for Ctrl+C.
 */
static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C bus 1 at address 0x68 */
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Initialize MPU-6050 */
    if (init_mpu6050() < 0) {
        fprintf(stderr, "MPU-6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Set LED pin as output and ensure it is off */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    int16_t ax, ay, az, gx, gy, gz;
    float roll, pitch;

    /* Main loop */
    while (running) {
        /* Read sensor data */
        if (read_mpu6050_data(&ax, &ay, &az, &gx, &gy, &gz) == 0) {
            /* Calculate roll and pitch */
            calculate_roll_pitch(ax, ay, az, gx, gy, gz, &roll, &pitch);

            /* Log data */
            log_data(roll, pitch);

            /* Check thresholds and control LED */
            if (fabsf(roll) > ROLL_PITCH_THRESHOLD ||
                fabsf(pitch) > ROLL_PITCH_THRESHOLD) {
                gpioWrite(LED_PIN, 1);
            } else {
                gpioWrite(LED_PIN, 0);
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(100000); /* 100 ms delay */
    }

    /* Cleanup */
    gpioWrite(LED_PIN, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

