#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI1145_ADDR 0x60
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "biometric_log.txt"
#define PRESENCE_LED_PIN 17
#define PROXIMITY_THRESHOLD 100
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define LOOP_DELAY_MS 100

#define REG_PART_ID 0x00
#define REG_REV_ID 0x01
#define REG_SEQ_ID 0x02
#define REG_INT_CFG 0x03
#define REG_IRQ_ENABLE 0x04
#define REG_IRQ_MODE1 0x05
#define REG_IRQ_MODE2 0x06
#define REG_HW_KEY 0x07
#define REG_MEAS_RATE0 0x08
#define REG_MEAS_RATE1 0x09
#define REG_ALS_RATE 0x0A
#define REG_ALS_IR_TIME 0x0B
#define REG_PS_RATE 0x0C
#define REG_PS_LED21 0x0D
#define REG_PS_LED3 0x0E
#define REG_PS1_ADCMUX 0x0F
#define REG_PS2_ADCMUX 0x10
#define REG_PS3_ADCMUX 0x11
#define REG_PS_ADC_GAIN 0x12
#define REG_PS_ADC_COUNTER 0x13
#define REG_PS_ADC_THRESH 0x14
#define REG_PS_ADC_MISC 0x15
#define REG_ALS_VIS_DATA0 0x22
#define REG_ALS_VIS_DATA1 0x23
#define REG_ALS_IR_DATA0 0x24
#define REG_ALS_IR_DATA1 0x25
#define REG_PS1_DATA0 0x26
#define REG_PS1_DATA1 0x27
#define REG_PS2_DATA0 0x28
#define REG_PS2_DATA1 0x29
#define REG_PS3_DATA0 0x2A
#define REG_PS3_DATA1 0x2B
#define REG_COMMAND 0x30

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, value, 1) != 1) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int init_sensor(int fd) {
    if (i2c_write_reg(fd, REG_HW_KEY, 0x17) < 0) return -1;
    usleep(10000);
    if (i2c_write_reg(fd, REG_MEAS_RATE0, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, REG_MEAS_RATE1, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, REG_ALS_RATE, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, REG_ALS_IR_TIME, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, REG_PS_RATE, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, REG_PS_LED21, 0x0F) < 0) return -1;
    if (i2c_write_reg(fd, REG_PS_ADC_GAIN, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, REG_COMMAND, 0x01) < 0) return -1;
    usleep(10000);
    return 0;
}

static int read_sensor_data(int fd, uint16_t *ambient_light, uint16_t *proximity) {
    if (i2c_read_reg16(fd, REG_ALS_VIS_DATA0, ambient_light) < 0) return -1;
    if (i2c_read_reg16(fd, REG_PS1_DATA0, proximity) < 0) return -1;
    return 0;
}

static void log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,AmbientLight:%u,Proximity:%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            ambient_light, proximity);
    fflush(fp);
}

static void control_led(int gpio_pin, uint16_t proximity) {
    if (proximity > PROXIMITY_THRESHOLD) {
        gpio_pin = 1;
    } else {
        gpio_pin = 0;
    }
    if (gpio_pin != -1) {
        gpio_pin = gpio_pin;
    }
}

static void cleanup(void) {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpio_pin = 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return 1;
    }

    if (init_sensor(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize sensor\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen log file");
        cleanup();
        return 1;
    }

    gpio_pin = PRESENCE_LED_PIN;
    if (gpio_pin < 0 || gpio_pin > 31) {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
        cleanup();
        return 1;
    }
    if (gpio_pin == 17) {
        if (gpio_pin > 0) {
            if (gpio_pinWrite(gpio_pin, 0) < 0) {
                fprintf(stderr, "Failed to set GPIO %d low\n", gpio_pin);
                cleanup();
                return 1;
            }
        }
    }

    uint16_t ambient_light, proximity;
    int retries = 0;

    while (running) {
        if (read_sensor_data(i2c_fd, &ambient_light, &proximity) == 0) {
            log_data(log_file, ambient_light, proximity);
            control_led(gpio_pin, proximity);
            retries = 0;
        } else {
            fprintf(stderr, "Failed to read sensor data. Retry %d/%d\n", retries + 1, MAX_RETRIES);
            retries++;
            if (retries <= MAX_RETRIES) {
                usleep(RETRY_DELAY_MS * 1000);
                continue;
            }
            fprintf(stderr, "Max retries reached. Exiting.\n");
            break;
        }
        usleep(LOOP_DELAY_MS * 1000);
    }

    cleanup();
    return 0;
}

