#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* ADXRS290 Register Addresses */
#define ADXRS290_REG_XGYRO_OUT 0x04
#define ADXRS290_REG_YGYRO_OUT 0x06

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* Mode 0: CPOL=0, CPHA=0 */

/* Sampling */
#define SAMPLE_DELAY_US 10000  /* 10 ms -> ~100 Hz */
#define MAX_REINIT_ATTEMPTS 3

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    int16_t x_rate;
    int16_t y_rate;
} gyro_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/*
 * Read a 16-bit register from the ADXRS290.
 * The ADXRS290 requires sending the register address OR'd with the
 * read bit (0x80) followed by a dummy byte, with the data byte
 * returned on the second transfer byte.
 */
static int read_register(uint8_t reg_addr, int16_t *out) {
    char tx[2], rx[2];
    int  result;

    tx[0] = (char)(reg_addr | 0x80);
    tx[1] = 0x00;  /* dummy byte to clock out data */

    result = spiXfer(spi_handle, tx, rx, 2);
    if (result != 2) {
        fprintf(stderr, "SPI read transfer failed for reg 0x%02X (returned %d): %s\n",
                reg_addr, result, strerror(errno));
        return -1;
    }

    *out = (int16_t)(((uint8_t)rx[1] << 8) | (uint8_t)rx[0]);
    return 0;
}

static int read_gyro_data(gyro_data_t *data) {
    if (read_register(ADXRS290_REG_XGYRO_OUT, &data->x_rate) != 0) {
        return -1;
    }
    if (read_register(ADXRS290_REG_YGYRO_OUT, &data->y_rate) != 0) {
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (fp != NULL) {
        fflush(fp);
        fclose(fp);
        fp = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, speed %d, flags %d): %s\n",
                SPI_CHANNEL, SPI_SPEED, SPI_FLAGS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fp = fopen("gyro_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open gyro_data.csv: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(fp, "timestamp_s,x_rate_raw,y_rate_raw\n");
    fflush(fp);

    int reinit_attempts = 0;

    while (!terminate) {
        gyro_data_t gyro_data;

        if (read_gyro_data(&gyro_data) != 0) {
            fprintf(stderr, "Gyro read failed; attempting SPI re-initialisation (%d/%d)...\n",
                    reinit_attempts + 1, MAX_REINIT_ATTEMPTS);
            spiClose(spi_handle);
            spi_handle = -1;

            if (reinit_attempts < MAX_REINIT_ATTEMPTS) {
                gpioDelay(100000);  /* 100 ms back-off */
                spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
                if (spi_handle < 0) {
                    fprintf(stderr, "SPI re-open failed (%d/%d): %s\n",
                            reinit_attempts + 1, MAX_REINIT_ATTEMPTS, strerror(errno));
                    reinit_attempts++;
                } else {
                    reinit_attempts = 0;
                    fprintf(stderr, "SPI re-initialised successfully.\n");
                }
            } else {
                fprintf(stderr, "Max re-initialisation attempts reached. Exiting.\n");
                break;
            }
            continue;
        }

        struct timespec ts;
        if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
            fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
            break;
        }

        double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1.0e9;

        if (fprintf(fp, "%.6f,%d,%d\n", timestamp, gyro_data.x_rate, gyro_data.y_rate) < 0) {
            fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
            break;
        }
        fflush(fp);

        gpioDelay(SAMPLE_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

