#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <stdint.h>

#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN 17
#define SEISMIC_THRESHOLD_MS 500
#define ALERT_DURATION_MS 2000
#define LOG_FILE_NAME "seismic_events.txt"

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t seismic_active = 0;
static volatile uint32_t seismic_start_tick = 0;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(void) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Seismic event detected!\n", timestamp);
        fflush(log_file);
    }
    printf("%s - Seismic event detected!\n", timestamp);
}

static void alert_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 1) {
        if (seismic_active) {
            uint32_t elapsed = tick - seismic_start_tick;
            if (elapsed >= (uint32_t)(SEISMIC_THRESHOLD_MS * 1000)) {
                log_event();
                gpioWrite(ALERT_PIN, 1);
                gpioSetTimerFunc(0, ALERT_DURATION_MS, NULL);
                seismic_active = 0;
            }
        }
    }
}

static void timer_callback(void) {
    if (seismic_active) {
        gpioWrite(ALERT_PIN, 0);
        seismic_active = 0;
    }
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set mode for SENSOR_1_PIN.\n");
        return -1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set mode for SENSOR_2_PIN.\n");
        return -1;
    }
    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set mode for ALERT_PIN.\n");
        return -1;
    }

    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down for SENSOR_1_PIN.\n");
        return -1;
    }
    if (gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down for SENSOR_2_PIN.\n");
        return -1;
    }

    if (gpioWrite(ALERT_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize ALERT_PIN to LOW.\n");
        return -1;
    }

    if (gpioSetAlertFunc(SENSOR_1_PIN, alert_callback) != 0) {
        fprintf(stderr, "Error: failed to set alert function for SENSOR_1_PIN.\n");
        return -1;
    }
    if (gpioSetAlertFunc(SENSOR_2_PIN, alert_callback) != 0) {
        fprintf(stderr, "Error: failed to set alert function for SENSOR_2_PIN.\n");
        return -1;
    }

    if (gpioSetTimerFunc(0, ALERT_DURATION_MS, timer_callback) != 0) {
        fprintf(stderr, "Error: failed to set timer function.\n");
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(ALERT_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    if (initialize_gpio() != 0) {
        fclose(log_file);
        log_file = NULL;
        return 1;
    }

    printf("Seismic monitoring system started. Press Ctrl+C to exit.\n");

    while (running) {
        if (gpioRead(SENSOR_1_PIN) == 1 && gpioRead(SENSOR_2_PIN) == 1) {
            if (!seismic_active) {
                seismic_active = 1;
                seismic_start_tick = gpioTick();
            }
        } else {
            seismic_active = 0;
        }
        gpioDelay(10000);
    }

    cleanup();
    printf("Seismic monitoring system stopped.\n");
    return 0;
}

