#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8

#define GYRO_REG_X_RATE 0x04
#define GYRO_REG_TEMP   0x06
#define GYRO_REG_STATUS 0x08
#define GYRO_REG_CTRL   0x0A

#define GYRO_CTRL_REG_VALUE 0x00
#define GYRO_STATUS_REG_VALUE 0x00

#define GYRO_RATE_THRESHOLD 20.0
#define LED_PIN 17
#define BUFFER_SIZE 100
#define SAMPLE_DELAY_US 10000

#define ADXRS290_READ_BIT 0x80

typedef struct {
    struct timespec timestamp;
    float rate;
} gyro_data_t;

typedef struct {
    gyro_data_t buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

static int spi_fd = -1;
static circular_buffer_t gyro_buffer;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return 0;
}

static int read_gyro_data(float *rate) {
    uint8_t tx[3] = { GYRO_REG_X_RATE | ADXRS290_READ_BIT, 0x00, 0x00 };
    uint8_t rx[3] = { 0 };

    if (spi_transfer(tx, rx, 3) < 0) {
        return -1;
    }

    int16_t raw_data = (int16_t)((rx[1] << 8) | rx[2]);
    *rate = (float)raw_data / 16.0;
    return 0;
}

static void buffer_init(circular_buffer_t *cb) {
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
    pthread_mutex_init(&cb->mutex, NULL);
}

static void buffer_add(circular_buffer_t *cb, float rate) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);

    pthread_mutex_lock(&cb->mutex);
    cb->buffer[cb->head].timestamp = ts;
    cb->buffer[cb->head].rate = rate;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count == BUFFER_SIZE) {
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    } else {
        cb->count++;
    }
    pthread_mutex_unlock(&cb->mutex);
}

static void buffer_get_latest(circular_buffer_t *cb, gyro_data_t *data) {
    pthread_mutex_lock(&cb->mutex);
    if (cb->count > 0) {
        int idx = (cb->head - 1 + BUFFER_SIZE) % BUFFER_SIZE;
        data->timestamp = cb->buffer[idx].timestamp;
        data->rate = cb->buffer[idx].rate;
    } else {
        data->timestamp.tv_sec = 0;
        data->timestamp.tv_nsec = 0;
        data->rate = 0.0;
    }
    pthread_mutex_unlock(&cb->mutex);
}

static void set_led(int state) {
    if (gpioWrite(LED_PIN, state) < 0) {
        fprintf(stderr, "Failed to write LED pin %d\n", LED_PIN);
    }
}

static void cleanup(void) {
    set_led(0);
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    pthread_mutex_destroy(&gyro_buffer.mutex);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin %d as output\n", LED_PIN);
        gpioTerminate();
        return 1;
    }
    set_led(0);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpioTerminate();
        return 1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        cleanup();
        return 1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        cleanup();
        return 1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        cleanup();
        return 1;
    }

    buffer_init(&gyro_buffer);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Gyroscope data acquisition started. Press Ctrl+C to exit.\n");

    while (program_running) {
        float rate;
        if (read_gyro_data(&rate) < 0) {
            fprintf(stderr, "Error reading gyro data. Retrying...\n");
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        buffer_add(&gyro_buffer, rate);

        gyro_data_t latest_data;
        buffer_get_latest(&gyro_buffer, &latest_data);

        printf("X-axis rate: %.2f deg/s, Timestamp: %ld.%09ld\n",
               latest_data.rate,
               (long)latest_data.timestamp.tv_sec,
               (long)latest_data.timestamp.tv_nsec);

        if (fabs(latest_data.rate) > GYRO_RATE_THRESHOLD) {
            set_led(1);
        } else {
            set_led(0);
        }

        usleep(SAMPLE_DELAY_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

