    set_lamp_brightness(LAMP3_PIN, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <total_fade_duration_seconds>\n", argv[0]);
        fprintf(stderr, "  Total fade duration must be between 1 and 3600 seconds.\n");
        return EXIT_FAILURE;
    }

    int total_duration = atoi(argv[1]);
    if (total_duration < 1 || total_duration > 3600) {
        fprintf(stderr, "Error: Total fade duration must be between 1 and 3600 seconds.\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LAMP1_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(LAMP2_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(LAMP3_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO modes\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(LAMP1_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(LAMP2_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(LAMP3_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(LAMP1_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(LAMP2_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(LAMP3_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: Failed to set PWM range\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to install signal handlers\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Smart Sunset Simulator started. Fading %d lamps over %d seconds...\n",
           LAMP1_PIN, LAMP2_PIN, LAMP3_PIN, total_duration);
    printf("Lamp 1: GPIO%d, Lamp 2: GPIO%d, Lamp 3: GPIO%d\n",
           LAMP1_PIN, LAMP2_PIN, LAMP3_PIN);
    printf("PWM frequency: %d Hz, range: %d\n", PWM_FREQUENCY, PWM_RANGE);
    printf("Press Ctrl+C to exit early.\n");

    int rc = EXIT_SUCCESS;

    if (fade_lamp(LAMP1_PIN, total_duration) != 0) {
        rc = EXIT_FAILURE;
        goto done;
    }
    if (fade_lamp(LAMP2_PIN, total_duration) != 0) {
        rc = EXIT_FAILURE;
        goto done;
    }
    if (fade_lamp(LAMP3_PIN, total_duration) != 0) {
        rc = EXIT_FAILURE;
        goto done;
    }

    printf("Sunset simulation complete. All lamps off.\n");

done:
    cleanup();
    return rc;
}

