#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define MPR121_ADDR 0x25
#define RELAY_GPIO 17
#define DEBOUNCE_DELAY_MS 100
#define POLL_DELAY_US 10000
#define LOG_FILE "touch_relay.log"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    if (log_file) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file);
    }
    fprintf(stderr, "%s: %s\n", timestamp, message);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_init(int handle) {
    uint8_t buf[2];
    buf[0] = 0x80;
    buf[1] = 0x63;
    if (i2cWriteDevice(handle, (char *)buf, 2) < 0) {
        log_error("Failed to write MPR121 soft reset");
        return -1;
    }
    gpioDelay(10000);
    buf[0] = 0x5E;
    buf[1] = 0x00;
    if (i2cWriteDevice(handle, (char *)buf, 2) < 0) {
        log_error("Failed to write MPR121 electrode config");
        return -1;
    }
    buf[0] = 0x5D;
    buf[1] = 0x04;
    if (i2cWriteDevice(handle, (char *)buf, 2) < 0) {
        log_error("Failed to write MPR121 filter config");
        return -1;
    }
    buf[0] = 0x5B;
    buf[1] = 0x01;
    if (i2cWriteDevice(handle, (char *)buf, 2) < 0) {
        log_error("Failed to write MPR121 charge config");
        return -1;
    }
    buf[0] = 0x5C;
    buf[1] = 0x10;
    if (i2cWriteDevice(handle, (char *)buf, 2) < 0) {
        log_error("Failed to write MPR121 AFE config");
        return -1;
    }
    buf[0] = 0x5D;
    buf[1] = 0x24;
    if (i2cWriteDevice(handle, (char *)buf, 2) < 0) {
        log_error("Failed to write MPR121 debounce config");
        return -1;
    }
    return 0;
}

static int mpr121_read_touch(int handle, uint16_t *touch_status) {
    uint8_t reg = 0x00;
    if (i2cWriteDevice(handle, (char *)&reg, 1) < 0) {
        log_error("Failed to write MPR121 touch status register address");
        return -1;
    }
    uint8_t data[2];
    if (i2cReadDevice(handle, (char *)data, 2) != 2) {
        log_error("Failed to read MPR121 touch status");
        return -1;
    }
    *touch_status = ((uint16_t)data[1] << 8) | data[0];
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioSetMode(RELAY_GPIO, PI_INPUT);
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        fclose(log_file);
        log_file = NULL;
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        fclose(log_file);
        log_file = NULL;
        return EXIT_FAILURE;
    }

    if (mpr121_init(i2c_handle) < 0) {
        log_error("MPR121 initialisation failed");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        log_error("Failed to set GPIO17 as output");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(RELAY_GPIO, 0) < 0) {
        log_error("Failed to set GPIO17 to LOW");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t touch_status;
    int relay_state = 0;
    int consecutive_errors = 0;

    while (running) {
        if (mpr121_read_touch(i2c_handle, &touch_status) == 0) {
            consecutive_errors = 0;
            if (touch_status & 0x0001) {
                if (relay_state == 0) {
                    if (gpioWrite(RELAY_GPIO, 1) == 0) {
                        relay_state = 1;
                        printf("Relay ON\n");
                    } else {
                        log_error("Failed to set GPIO17 HIGH");
                    }
                }
                gpioDelay(DEBOUNCE_DELAY_MS * 1000);
            } else {
                if (relay_state == 1) {
                    if (gpioWrite(RELAY_GPIO, 0) == 0) {
                        relay_state = 0;
                        printf("Relay OFF\n");
                    } else {
                        log_error("Failed to set GPIO17 LOW");
                    }
                }
            }
        } else {
            consecutive_errors++;
            if (consecutive_errors > 10) {
                log_error("Too many consecutive I2C errors, aborting");
                break;
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

