}

static int log_dispense(int solenoid1_pin, int solenoid2_pin, int duration_ms) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("Error getting time");
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("Error converting time");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, Solenoid 1 (GPIO%d), Solenoid 2 (GPIO%d), %d ms\n",
                timestamp, solenoid1_pin, solenoid2_pin, duration_ms) < 0) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }

    return 0;
}

static int dispense(int solenoid1_pin, int solenoid2_pin, int duration_ms) {
    if (gpioWrite(solenoid1_pin, 1) < 0) {
        fprintf(stderr, "Error activating solenoid 1 (GPIO%d)\n", solenoid1_pin);
        return -1;
    }
    if (gpioWrite(solenoid2_pin, 0) < 0) {
        fprintf(stderr, "Error deactivating solenoid 2 (GPIO%d)\n", solenoid2_pin);
        gpioWrite(solenoid1_pin, 0);
        return -1;
    }

    gpioDelay(duration_ms * 1000);

    if (gpioWrite(solenoid1_pin, 0) < 0) {
        fprintf(stderr, "Error deactivating solenoid 1 (GPIO%d)\n", solenoid1_pin);
        return -1;
    }
    if (gpioWrite(solenoid2_pin, 0) < 0) {
        fprintf(stderr, "Error deactivating solenoid 2 (GPIO%d)\n", solenoid2_pin);
        return -1;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO%d as output\n", SOLENOID_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO%d as output\n", SOLENOID_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(SOLENOID_1_PIN, 0) < 0) {
        fprintf(stderr, "Error initializing GPIO%d to LOW\n", SOLENOID_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(SOLENOID_2_PIN, 0) < 0) {
        fprintf(stderr, "Error initializing GPIO%d to LOW\n", SOLENOID_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Error registering SIGINT handler");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Pneumatic dispensing system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (dispense(SOLENOID_1_PIN, SOLENOID_2_PIN, DISPENSE_DURATION_MS) < 0) {
            fprintf(stderr, "Error during dispense cycle\n");
            break;
        }

        if (log_dispense(SOLENOID_1_PIN, SOLENOID_2_PIN, DISPENSE_DURATION_MS) < 0) {
            fprintf(stderr, "Error logging dispense event\n");
            break;
        }

        if (g_running) {
            sleep(DISPENSE_INTERVAL_S);
        }
    }

    gpioWrite(SOLENOID_1_PIN, 0);
    gpioWrite(SOLENOID_2_PIN, 0);
    gpioTerminate();

    printf("Pneumatic dispensing system stopped.\n");
    return EXIT_SUCCESS;
}

