#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* Motor A */
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18

/* Motor B */
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23

/* Enable drivers */
#define ENABLE_A 24
#define ENABLE_B 25

/* PID parameters */
#define KP 1.0
#define KI 0.01
#define KD 0.1

/* Obstacle avoidance threshold (cm) */
#define OBSTACLE_THRESHOLD 20.0

/* Log file name */
#define LOG_FILE "balance_log.txt"

/* PWM range */
#define PWM_RANGE 255

/* Loop delay (us) */
#define LOOP_DELAY 50000

/* Global flag for graceful shutdown */
static volatile sig_atomic_t running = 1;

/* PID state */
static float integral = 0.0;
static float previous_error = 0.0;

/* Log file pointer */
static FILE *log_file = NULL;

/* Function prototypes */
static void signal_handler(int sig);
static int initialize_gpio(void);
static void set_motor_speed(int motor_a_speed, int motor_b_speed);
static float calculate_pid(float tilt_error, float *integral, float previous_error);
static float simulate_tilt_sensor(void);
static float simulate_distance_sensor(void);
static void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);
static void cleanup(void);

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Initialize GPIO using pigpio */
static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    /* Set GPIO modes */
    if (gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT) != 0 ||
        gpioSetMode(ENABLE_A, PI_OUTPUT) != 0 ||
        gpioSetMode(ENABLE_B, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return -1;
    }

    /* Enable PWM on enable pins */
    if (gpioPWM(ENABLE_A, PWM_RANGE) != 0 || gpioPWM(ENABLE_B, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return -1;
    }

    /* Initialize motor enable pins to HIGH (PWM enabled) */
    if (gpioWrite(ENABLE_A, 1) != 0 || gpioWrite(ENABLE_B, 1) != 0) {
        fprintf(stderr, "Failed to write enable pins\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* Set motor speeds (clamped to +/-255) */
static void set_motor_speed(int motor_a_speed, int motor_b_speed) {
    int a_forward = motor_a_speed > 0 ? motor_a_speed : 0;
    int a_backward = motor_a_speed < 0 ? -motor_a_speed : 0;
    int b_forward = motor_b_speed > 0 ? motor_b_speed : 0;
    int b_backward = motor_b_speed < 0 ? -motor_b_speed : 0;

    a_forward = (a_forward > PWM_RANGE) ? PWM_RANGE : a_forward;
    a_backward = (a_backward > PWM_RANGE) ? PWM_RANGE : a_backward;
    b_forward = (b_forward > PWM_RANGE) ? PWM_RANGE : b_forward;
    b_backward = (b_backward > PWM_RANGE) ? PWM_RANGE : b_backward;

    gpioWrite(MOTOR_A_FORWARD, a_forward > 0);
    gpioWrite(MOTOR_A_BACKWARD, a_backward > 0);
    gpioWrite(MOTOR_B_FORWARD, b_forward > 0);
    gpioWrite(MOTOR_B_BACKWARD, b_backward > 0);

    if (a_forward > 0) gpioPWM(MOTOR_A_FORWARD, a_forward);
    if (a_backward > 0) gpioPWM(MOTOR_A_BACKWARD, a_backward);
    if (b_forward > 0) gpioPWM(MOTOR_B_FORWARD, b_forward);
    if (b_backward > 0) gpioPWM(MOTOR_B_BACKWARD, b_backward);
}

/* Calculate PID output */
static float calculate_pid(float tilt_error, float *integral, float previous_error) {
    float proportional = KP * tilt_error;
    *integral += KI * tilt_error;
    float derivative = KD * (tilt_error - previous_error);
    return proportional + *integral + derivative;
}

/* Simulate tilt sensor (returns random float between -10.0 and 10.0) */
static float simulate_tilt_sensor(void) {
    return ((float)rand() / (float)RAND_MAX) * 20.0 - 10.0;
}

/* Simulate distance sensor (returns random float between 2.0 and 400.0) */
static float simulate_distance_sensor(void) {
    return ((float)rand() / (float)RAND_MAX) * 400.0 + 2.0;
}

/* Log data to file */
static void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

