/* Cleanup resources */
static void cleanup(void) {
    /* Stop motors */
    set_motor_speed(0, 0);
    gpioWrite(ENABLE_A, 0);
    gpioWrite(ENABLE_B, 0);

    /* Close log file */
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    /* Terminate pigpio */
    gpioTerminate();
}

int main(void) {
    /* Seed random number generator */
    srand(time(NULL));

    /* Register signal handler */
    signal(SIGINT, signal_handler);

    /* Initialize GPIO */
    if (initialize_gpio() != 0) {
        return 1;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    /* Write header to log file */
    fprintf(log_file, "timestamp,tilt_error,distance,motor_a_speed,motor_b_speed\n");
    fflush(log_file);

    /* Main control loop */
    while (running) {
        /* Simulate sensor readings */
        float tilt_error = simulate_tilt_sensor();
        float distance = simulate_distance_sensor();

        /* Calculate PID output */
        float pid_output = calculate_pid(tilt_error, &integral, previous_error);

        /* Motor control */
        int motor_a_speed = (int)pid_output;
        int motor_b_speed = -(int)pid_output;

        /* Clamp motor speeds */
        if (motor_a_speed > PWM_RANGE) motor_a_speed = PWM_RANGE;
        if (motor_a_speed < -PWM_RANGE) motor_a_speed = -PWM_RANGE;
        if (motor_b_speed > PWM_RANGE) motor_b_speed = PWM_RANGE;
        if (motor_b_speed < -PWM_RANGE) motor_b_speed = -PWM_RANGE;

        /* Set motor speeds */
        set_motor_speed(motor_a_speed, motor_b_speed);

        /* Obstacle avoidance */
        if (distance < OBSTACLE_THRESHOLD) {
            set_motor_speed(-50, -50);
        } else {
