/*
 * TTP223 Capacitive Touch Sensor -> Relay Toggle
 * Board:  Raspberry Pi 3 Model B+
 * Sensor: TTP223 digital output -> GPIO4  (BCM 4, physical pin 7)
 * Relay:  5 V relay module          -> GPIO17 (BCM 17, physical pin 11)
 *
 * The TTP223 output is logic-HIGH while touched.  The relay is active-high
 * (energized when GPIO17 is HIGH).  A 50 ms debounce delay follows each
 * detection to filter out spurious transitions.
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_relay touch_relay.c -lpigpio -lrt
 * Run:    sudo ./touch_relay
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN        17
#define DEBOUNCE_US      50000   /* 50 ms */
#define POLL_US          10000   /* 10 ms polling interval */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Return a monotonic microsecond timestamp.                          */
static uint64_t now_us(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return 0;
    }
    return (uint64_t)ts.tv_sec * 1000000ULL + (uint64_t)ts.tv_nsec / 1000ULL;
}

/* ------------------------------------------------------------------ */
/* Configure a GPIO pin as input or output and verify success.        */
static int gpio_setup(int pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the sensor level with error checking.                          */
static int read_touch_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead(%d) failed\n", pin);
        return -1;
    }
    return v;
}

/* ------------------------------------------------------------------ */
/* Energize or de-energize the relay and verify success.               */
static int relay_set(int pin, int on)
{
    if (gpioWrite(pin, on ? 1 : 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(%d, %d) failed\n", pin, on);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers for clean shutdown ----------------- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio ------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d)\n",
                gpioInitialise());
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins ---------------------------------------- */
    if (gpio_setup(TOUCH_SENSOR_PIN, PI_INPUT) != 0 ||
        gpio_setup(RELAY_PIN, PI_OUTPUT)     != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /*
     * Enable internal pull-down on the sensor pin so the line is
     * defined when the sensor is disconnected or its output is
     * indeterminate.  The TTP223 drives HIGH while touched, so a
     * pull-down keeps the line LOW when the sensor is absent.
     */
    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: gpioSetPullUpDown(%d, PI_PUD_DOWN) failed\n",
                TOUCH_SENSOR_PIN);
        /* Non-fatal: continue with external pull-down if used. */
    }

    /* Ensure relay starts in the de-energized state. */
    if (relay_set(RELAY_PIN, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch-to-relay control started.\n");
    printf("  Sensor : GPIO%d (TTP223, logic-HIGH while touched)\n",
           TOUCH_SENSOR_PIN);
    printf("  Relay  : GPIO%d (active-high, energized = HIGH)\n",
           RELAY_PIN);
    printf("Press Ctrl-C to exit.\n");

    bool relay_state = false;
    uint64_t last_touch_us = 0;

    /* --- Main polling loop ------------------------------------------ */
    while (g_running) {
        int touch = read_touch_sensor(TOUCH_SENSOR_PIN);
        if (touch < 0) {
            /* Sensor read error: back off briefly and retry. */
            gpioDelay(POLL_US);
            continue;
        }

        uint64_t now = now_us();
        if (touch == 1 && !relay_state &&
            (now - last_touch_us) >= DEBOUNCE_US) {
            /* Rising edge: touch detected, debounced. */
            relay_state = true;
            if (relay_set(RELAY_PIN, 1) == 0) {
                printf("Touch detected -> relay ON\n");
            }
            last_touch_us = now;
        } else if (touch == 0 && relay_state) {
            /* Falling edge: release detected. */
            relay_state = false;
            if (relay_set(RELAY_PIN, 0) == 0) {
                printf("Release detected -> relay OFF\n");
            }
        }

        gpioDelay(POLL_US);
    }

    /* --- Clean shutdown --------------------------------------------- */
    printf("\nShutting down...\n");
    relay_set(RELAY_PIN, 0);   /* De-energize relay on exit. */
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

