/*
 * mood_light.c — Raspberry Pi 3 Model B+
 *
 * Captures 8000 Hz mono audio via ALSA, computes RMS amplitude, and drives
 * an RGB LED on GPIO17(R)/GPIO18(G)/GPIO27(B) with software PWM via the
 * driver library.  When ALSA is unavailable at build time the audio path is
 * simulated so the mood light still cycles colors.
 *
 * Build:  gcc -O2 -Wall -Wextra -DALSA_AVAILABLE -o mood_light mood_light.c -lqemu_guest_msr -lqemu_guest_pmu -lqemu_guest_icu -lm
 * Run:    ./mood_light [sensitivity_scale]
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>

#if defined(__has_include)
#  if __has_include(<alsa/asoundlib.h>)
#    define ALSA_AVAILABLE
#  else
#    define ALSA_AVAILABLE 0
#  endif
#else
#  define ALSA_AVAILABLE 0
#endif

#if ALSA_AVAILABLE
#  include <alsa/asoundlib.h>
#endif

#include "driver_lib.h"

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27

#define SAMPLE_RATE       8000
#define PERIOD_SIZE       1024
#define RMS_WINDOW_MS     10
#define UPDATE_MS         10
#define PWM_PERIOD_US     1000   /* 1 kHz software PWM */
#define PWM_DUTY_MAX      1000   /* 1000 / 1000 = 100 % */

#define DEFAULT_SENSITIVITY 1.0f

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Simulated audio input (ALSA path)                                   */
/* ------------------------------------------------------------------ */

typedef struct {
    int16_t data[PERIOD_SIZE];
} audio_buffer_t;

static int simulate_audio(audio_buffer_t *buf)
{
    for (int i = 0; i < PERIOD_SIZE; i++) {
        float phase = (float)i / (float)SAMPLE_RATE * 2.0f * (float)M_PI;
        float amp   = 100.0f * (1.0f + sinf(phase));
        buf->data[i] = (int16_t)(amp * 32767.0f);
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* ALSA audio input                                                    */
/* ------------------------------------------------------------------ */

#if ALSA_AVAILABLE

typedef struct {
    snd_pcm_t *handle;
    int        err;
} alsa_ctx_t;

static int alsa_init(alsa_ctx_t *ctx)
{
    ctx->err = 0;

    ctx->handle = snd_pcm_open("default", SND_PCM_STREAM_CAPTURE, 0);
    if (!ctx->handle) {
        fprintf(stderr, "snd_pcm_open failed: %s\n", snd_strerror(snd_pcm_error_string(snd_pcm_stream_error(ctx->handle))));
        return -1;
    }

    snd_pcm_hw_params_t *hw;
    int rc = snd_pcm_hw_params_alloca(&hw);
    if (rc < 0) {
        fprintf(stderr, "snd_pcm_hw_params_alloca failed: %s\n", snd_strerror(snd_pcm_error_string(rc)));
        goto fail;
    }

    rc = snd_pcm_hw_params_any(ctx->handle, hw);
    if (rc < 0) {
        fprintf(stderr, "snd_pcm_hw_params_any failed: %s\n", snd_strerror(snd_pcm_error_string(rc)));
        goto fail;
    }

    rc = snd_pcm_hw_params_set_access(ctx->handle, hw, SND_PCM_ACCESS_RW_INTERLEAVED);
    if (rc < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_access failed: %s\n", snd_strerror(snd_pcm_error_string(rc)));
        goto fail;
    }

    rc = snd_pcm_hw_params_set_format(ctx->handle, hw, SND_PCM_FORMAT_S16_LE);
    if (rc < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_format failed: %s\n", snd_strerror(snd_pcm_error_string(rc)));
        goto fail;
    }

    rc = snd_pcm_hw_params_set_channels(ctx->handle, hw, 1);
    if (rc < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_channels failed: %s\n", snd_strerror(snd_pcm_error_string(rc)));
        goto fail;
    }

    unsigned int rate = SAMPLE_RATE;
    rc = snd_pcm_hw_params_set_rate_near(ctx->handle, hw, &rate, 0);
    if (rc < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_rate_near failed: %s\n", snd_strerror(snd_pcm_error_string(rc)));
        goto fail;
    }
    if (rate != SAMPLE_RATE) {
        fprintf(stderr, "Warning: requested %d Hz, got %u Hz\n", SAMPLE_RATE, rate);
    }

    unsigned int period = PERIOD_SIZE;
    rc = snd_pcm_hw_params_set_period_size_near(ctx->handle, hw, &period, 0);
    if (rc < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_period_size_near failed: %s\n", snd_strerror(snd_pcm_error_string(rc)));
        goto fail;
    }
    if (period != PERIOD_SIZE) {
        fprintf(stderr, "Warning: requested %d frames, got %u\n", PERIOD_SIZE, period);
    }

    rc = snd_pcm_hw_params(ctx->handle, hw);
    if (rc < 0) {
        fprintf(stderr, "snd_pcm_hw_params failed: %s\n", snd_strerror(snd_pcm_error_string(rc)));
        goto fail;
    }

    rc = snd_pcm_prepare(ctx->handle);
    if (rc < 0) {
        fprintf(stderr, "snd_pcm_prepare failed: %s\n", snd_strerror(snd_pcm_error_string(rc)));
        goto fail;
    }

    return 0;

fail:
    snd_pcm_close(ctx->handle);
    ctx->handle = NULL;
    return -1;
}

static int alsa_read(alsa_ctx_t *ctx, audio_buffer_t *buf)
{
