    if (rc == -EPIPE) {
        fprintf(stderr, "ALSA buffer overrun\n");
        snd_pcm_prepare(ctx->handle);
        return -1;
    } else if (rc == -ESTRPIPE) {
        fprintf(stderr, "ALSA suspended, resuming...\n");
        snd_pcm_resume(ctx->handle);
        return -1;
    } else if (rc < 0) {
        fprintf(stderr, "snd_pcm_readi failed: %s\n", snd_strerror(snd_pcm_error_string(rc)));
        return -1;
    }
    return 0;
}

static void alsa_cleanup(alsa_ctx_t *ctx)
{
    if (ctx->handle) {
        snd_pcm_drain(ctx->handle);
        snd_pcm_close(ctx->handle);
        ctx->handle = NULL;
    }
}

#else

typedef struct {
    audio_buffer_t buf;
} alsa_ctx_t;

static int alsa_init(alsa_ctx_t *ctx)
{
