/* ------------------------------------------------------------------ */
/* RMS                                                                 */
/* ------------------------------------------------------------------ */

static float calculate_rms(const audio_buffer_t *buf)
{
    double sum_sq = 0.0;
    for (int i = 0; i < PERIOD_SIZE; i++) {
        double s = (double)buf->data[i];
        sum_sq += s * s;
    }
    return (float)sqrt(sum_sq / (double)PERIOD_SIZE);
}

/* ------------------------------------------------------------------ */
/* RGB LED control                                                     */
/* ------------------------------------------------------------------ */

static void set_led_color(float r, float g, float b)
{
    int r_on  = (int)(r * 255.0f);
    int g_on  = (int)(g * 255.0f);
    int b_on  = (int)(b * 255.0f);

    /* Software PWM via driver library */
    if (r_on > 0) {
        if (gpio_write(RED_PIN, 1) < 0)
            fprintf(stderr, "gpio_write RED failed\n");
        usleep(PWM_DUTY_MAX);
        if (gpio_write(RED_PIN, 0) < 0)
            fprintf(stderr, "gpio_write RED off failed\n");
    }
    if (g_on > 0) {
        if (gpio_write(GREEN_PIN, 1) < 0)
            fprintf(stderr, "gpio_write GREEN failed\n");
        usleep(PWM_DUTY_MAX);
        if (gpio_write(GREEN_PIN, 0) < 0)
            fprintf(stderr, "gpio_write GREEN off failed\n");
    }
    if (b_on > 0) {
        if (gpio_write(BLUE_PIN, 1) < 0)
            fprintf(stderr, "gpio_write BLUE failed\n");
        usleep(PWM_DUTY_MAX);
        if (gpio_write(BLUE_PIN, 0) < 0)
            fprintf(stderr, "gpio_write BLUE off failed\n");
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(int argc, char *argv[])
{
    float sensitivity = DEFAULT_SENSITIVITY;

    if (argc > 1) {
        sensitivity = (float)atof(argv[1]);
        if (sensitivity <= 0.0f) {
            fprintf(stderr, "Invalid sensitivity; using default %.2f\n", DEFAULT_SENSITIVITY);
            sensitivity = DEFAULT_SENSITIVITY;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return EXIT_FAILURE;
    }

#if ALSA_AVAILABLE
    alsa_ctx_t alsa;
    if (alsa_init(&alsa) < 0) {
        fprintf(stderr, "ALSA initialization failed; continuing with simulated audio\n");
    }
#endif

    printf("Mood light started. Sensitivity: %.2f\n", sensitivity);
    fflush(stdout);

    while (g_running) {
        audio_buffer_t buf;

#if ALSA_AVAILABLE
        if (alsa_read(&alsa, &buf) < 0) {
            fprintf(stderr, "Audio read error; continuing\n");
            usleep(UPDATE_MS * 1000);
            continue;
        }
#else
        (void)alsa_read;
        (void)&alsa;
        simulate_audio(&buf);
#endif

        float rms = calculate_rms(&buf);
        float scaled = rms * sensitivity;

        /* Non-linear mapping: low amplitude -> blue, high -> red */
        float norm = scaled / 100.0f;
        float r = 0.0f, g = 0.0f, b = 0.0f;
        if (norm > 1.0f) {
            r = 1.0f - norm;
            g = 0.0f;
            b = 0.0f;
        } else if (norm > 0.5f) {
            r = 0.0f;
            g = 1.0f - (norm - 0.5f) * 2.0f;
            b = 0.0f;
        } else {
            r = 0.0f;
            g = 0.0f;
            b = 1.0f - (norm * 2.0f);
        }

        set_led_color(r, g, b);

        printf("RMS: %.2f  ->  R:%.1f G:%.1f B:%.1f\n", rms, r, g, b);
        fflush(stdout);

        usleep(UPDATE_MS * 1000);
    }

#if ALSA_AVAILABLE
    alsa_cleanup(&alsa);
#endif

    printf("\nMood light stopped.\n");
    return EXIT_SUCCESS;
}

