typedef struct {
    int16_t data[PERIOD_SIZE];
} audio_buffer_t;

static int simulate_audio(audio_buffer_t *buf)
{
    for (int i = 0; i < PERIOD_SIZE; i++) {
        float phase = (float)i / (float)SAMPLE_RATE * 2.0f * (float)M_PI;
        float amp   = 100.0f * (1.0f + sinf(phase));
        buf->data[i] = (int16_t)(amp * 32767.0f);
    }
    return 0;
}

