#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* TCS34725 I2C address (7-bit, no ADDR pin tie) */
#define TCS34725_I2C_ADDR 0x29

/* TCS34725 register addresses */
#define TCS34725_ENABLE  0x80
#define TCS34725_ATIME   0x81
#define TCS34725_CDATA   0x94
#define TCS34725_RDATA   0x96
#define TCS34725_GDATA   0x98
#define TCS34725_BDATA   0x9A

/* Enable register bits */
#define TCS34725_ENABLE_PON  0x01
#define TCS34725_ENABLE_AEN  0x02

/* Integration time: 154 ms (ATIME = 0xFF) */
#define TCS34725_ATIME_154MS 0xFF

/* Sampling interval in microseconds (500 ms) */
#define SAMPLE_INTERVAL_US 500000

/* Global resources for signal handler cleanup */
static int i2c_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t running = 1;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Write a single byte to a TCS34725 register; returns 0 on success, -1 on error */
static int tcs_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* Read a single byte from a TCS34725 register; returns 0 on success, -1 on error */
static int tcs_read_byte(int handle, uint8_t reg, uint8_t *out) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* Read a 16-bit little-endian word from a TCS34725 register; returns 0 on success, -1 on error */
static int tcs_read_word(int handle, uint8_t reg, uint16_t *out) {
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cReadWordData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    /* pigpio returns data in the low 16 bits; TCS34725 is little-endian */
    *out = (uint16_t)rc;
    return 0;
}

/* Initialize the TCS34725 sensor; returns 0 on success, -1 on error */
static int tcs_init(int handle) {
    /* Power on */
    if (tcs_write_byte(handle, TCS34725_ENABLE, TCS34725_ENABLE_PON) < 0)
        return -1;
    gpioDelay(3000); /* 3 ms power-on delay */

    /* Set integration time to 154 ms */
    if (tcs_write_byte(handle, TCS34725_ATIME, TCS34725_ATIME_154MS) < 0)
        return -1;

    /* Enable RGBC ADC */
    if (tcs_write_byte(handle, TCS34725_ENABLE,
                       TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0)
        return -1;

    return 0;
}

/* Read all four color channels; returns 0 on success, -1 on error */
static int tcs_read_channels(int handle, uint16_t *clear, uint16_t *red,
                             uint16_t *green, uint16_t *blue) {
    if (tcs_read_word(handle, TCS34725_CDATA, clear) < 0)
        return -1;
    if (tcs_read_word(handle, TCS34725_RDATA, red) < 0)
        return -1;
    if (tcs_read_word(handle, TCS34725_GDATA, green) < 0)
        return -1;
    if (tcs_read_word(handle, TCS34725_BDATA, blue) < 0)
        return -1;
    return 0;
}

/* Log one sample row to the CSV file */
static void log_data(FILE *fp, uint16_t clear, uint16_t red,
                     uint16_t green, uint16_t blue) {
    time_t now = time(NULL);
    fprintf(fp, "%ld,%u,%u,%u,%u\n", (long)now, clear, red, green, blue);
    fflush(fp);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the TCS34725 address */
    i2c_handle = i2cOpen(1, TCS34725_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                TCS34725_I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
