#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 27
#define RELAY3_PIN 22
#define RELAY4_PIN 23

#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 21600
#define SUNSET_DURATION  3600
#define NIGHTTIME_DURATION 14400

#define PWM_RANGE 100
#define PWM_FREQUENCY 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_relay(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error: gpioWrite failed on pin %d (state %d)\n", pin, state);
        return -1;
    }
    return 0;
}

static int all_relays_off(void) {
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioWrite(pins[i], 1) != 0) {
            fprintf(stderr, "Error: gpioWrite failed on pin %d during shutdown\n", pins[i]);
            return -1;
        }
    }
    return 0;
}

static int sunrise(int duration) {
    int step = 60;
    for (int elapsed = 0; elapsed < duration && running; elapsed += step) {
        int duty = (elapsed * 100) / duration;
        if (duty > 100) duty = 100;
        if (duty < 0) duty = 0;

        int on_time = (duty * 1000) / 100;
        int off_time = 1000 - on_time;

        if (set_relay(RELAY1_PIN, 0) != 0) return -1;
        if (set_relay(RELAY2_PIN, 0) != 0) return -1;
        if (set_relay(RELAY3_PIN, 0) != 0) return -1;
        if (set_relay(RELAY4_PIN, 0) != 0) return -1;
        gpioDelay(on_time * 1000);

        if (set_relay(RELAY1_PIN, 1) != 0) return -1;
        if (set_relay(RELAY2_PIN, 1) != 0) return -1;
        if (set_relay(RELAY3_PIN, 1) != 0) return -1;
        if (set_relay(RELAY4_PIN, 1) != 0) return -1;
        gpioDelay(off_time * 1000);
    }
    return 0;
}

static int daytime(int duration) {
    for (int elapsed = 0; elapsed < duration && running; elapsed += 60) {
        if (set_relay(RELAY1_PIN, 0) != 0) return -1;
        if (set_relay(RELAY2_PIN, 0) != 0) return -1;
        if (set_relay(RELAY3_PIN, 0) != 0) return -1;
        if (set_relay(RELAY4_PIN, 0) != 0) return -1;
        gpioDelay(60 * 1000);
    }
    return 0;
}

static int sunset(int duration) {
    int step = 60;
    for (int elapsed = 0; elapsed < duration && running; elapsed += step) {
        int duty = (100 - (elapsed * 100) / duration);
        if (duty < 0) duty = 0;
        if (duty > 100) duty = 100;

        int on_time = (duty * 1000) / 100;
        int off_time = 1000 - on_time;

        if (set_relay(RELAY1_PIN, 0) != 0) return -1;
        if (set_relay(RELAY2_PIN, 0) != 0) return -1;
        if (set_relay(RELAY3_PIN, 0) != 0) return -1;
        if (set_relay(RELAY4_PIN, 0) != 0) return -1;
        gpioDelay(on_time * 1000);

        if (set_relay(RELAY1_PIN, 1) != 0) return -1;
        if (set_relay(RELAY2_PIN, 1) != 0) return -1;
        if (set_relay(RELAY3_PIN, 1) != 0) return -1;
        if (set_relay(RELAY4_PIN, 1) != 0) return -1;
        gpioDelay(off_time * 1000);
    }
    return 0;
}

static int nighttime(int duration) {
    int step = 60;
    for (int elapsed = 0; elapsed < duration && running; elapsed += step) {
        if (set_relay(RELAY1_PIN, 0) != 0) return -1;
        if (set_relay(RELAY2_PIN, 0) != 0) return -1;
        if (set_relay(RELAY3_PIN, 0) != 0) return -1;
        if (set_relay(RELAY4_PIN, 0) != 0) return -1;
        gpioDelay(step * 1000);
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed on pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(pins[i], PI_PUD_UP) != 0) {
            fprintf(stderr, "Error: gpioSetPullUpDown failed on pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    if (gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RELAY1_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(RELAY2_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(RELAY3_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(RELAY4_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        if (sunrise(SUNRISE_DURATION) != 0) break;
        if (!running) break;
        if (daytime(DAYTIME_DURATION) != 0) break;
        if (!running) break;
        if (sunset(SUNSET_DURATION) != 0) break;
        if (!running) break;
        if (nighttime(NIGHTTIME_DURATION) != 0) break;
    }

    if (all_relays_off() != 0) {
        fprintf(stderr, "Warning: failed to turn off relays during shutdown\n");
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

