#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_GPIO 17
#define DEBOUNCE_MS 200
#define VIDEO_DIR "/home/pi/videos"
#define LOG_DIR "/home/pi/logs"
#define LOG_FILE "motion_log.txt"
#define CAPTURE_DURATION_SEC 5
#define POLL_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int get_iso8601_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm timeinfo;

    if (time(&rawtime) == (time_t)-1) {
        return -1;
    }
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &timeinfo) == 0) {
        return -1;
    }
    return 0;
}

static int capture_video(const char *filename) {
    char command[512];
    int ret = snprintf(command, sizeof(command),
        "raspivid -w 640 -h 480 -t %d -o '%s' --nopreview",
        CAPTURE_DURATION_SEC * 1000, filename);
    if (ret < 0 || (size_t)ret >= sizeof(command)) {
        fprintf(stderr, "Error: command buffer too small\n");
        return -1;
    }

    int status = system(command);
    if (status == -1) {
        perror("system() failed");
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: raspivid exited with status %d\n", status);
        return -1;
    }
    return 0;
}

static int log_motion_event(const char *timestamp) {
    if (log_file == NULL) {
