#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_CONFIG 0x1B
#define SAMPLE_INTERVAL_US 10000
#define MAX_REINIT_ATTEMPTS 3

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpu6050_init(int fd) {
    if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000);
    if (i2c_write_byte(fd, GYRO_CONFIG, 0x00) < 0) return -1;
    return 0;
}

static int read_gyro_data(int fd, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_bytes(fd, GYRO_XOUT_H, buf, 6) < 0) return -1;
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);
    *x = (float)raw_x / 131.0f;
    *y = (float)raw_y / 131.0f;
    *z = (float)raw_z / 131.0f;
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(fp, "%ld.%03ld,%.3f,%.3f,%.3f\n", (long)ts.tv_sec, ts.tv_nsec / 1000000, x, y, z);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (mpu6050_init(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize MPU-6050\n");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("gyro_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open gyro_log.csv: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");
        fflush(log_file);
    }

    float x, y, z;
    int reinit_attempts = 0;

    while (running) {
        if (read_gyro_data(i2c_fd, &x, &y, &z) == 0) {
            log_data(log_file, x, y, z);
            reinit_attempts = 0;
        } else {
            fprintf(stderr, "Read failed, attempting re-initialization (%d/%d)\n", reinit_attempts + 1, MAX_REINIT_ATTEMPTS);
            if (reinit_attempts < MAX_REINIT_ATTEMPTS) {
                if (mpu6050_init(i2c_fd) < 0) {
                    fprintf(stderr, "Re-init failed\n");
                }
            } else {
                fprintf(stderr, "Max re-init attempts reached, continuing to log with errors\n");
            }
            reinit_attempts++;
        }
        usleep(SAMPLE_INTERVAL_US);
    }

    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

