#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define RELAY_1_PIN 4
#define RELAY_2_PIN 17
#define RELAY_3_PIN 27
#define RELAY_4_PIN 22

#define MOISTURE_THRESHOLD 30
#define LOG_FILE_NAME "irrigation_log.txt"
#define POLL_INTERVAL_SEC 5

static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    unsigned pins[] = {RELAY_1_PIN, RELAY_2_PIN, RELAY_3_PIN, RELAY_4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: failed to set GPIO%u as output.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(pins[i], 1) < 0) {
            fprintf(stderr, "Error: failed to initialize GPIO%u HIGH.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static int read_moisture_sensor(void) {
    return rand() % 100;
}

static void control_relay(int zone, int state) {
    unsigned pin;
    if (zone == 1) { pin = RELAY_1_PIN; }
    else if (zone == 2) { pin = RELAY_2_PIN; }
    else if (zone == 3) { pin = RELAY_3_PIN; }
    else if (zone == 4) { pin = RELAY_4_PIN; }
    else {
        fprintf(stderr, "Error: invalid relay zone %d.\n", zone);
        return;
    }

    if (gpioWrite(pin, state ? 1 : 0) < 0) {
        fprintf(stderr, "Error: failed to write GPIO%u.\n", pin);
    }
}

static void log_data(int moisture, int r1, int r2, int r3, int r4) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed.\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "Moisture: %d, Relay1: %s, Relay2: %s, Relay3: %s, Relay4: %s, Timestamp: %s\n",
            moisture, r1 ? "ON" : "OFF", r2 ? "ON" : "OFF", r3 ? "ON" : "OFF", r4 ? "ON" : "OFF", timestamp);
    fflush(log_file);
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(RELAY_1_PIN, 1);
    gpioWrite(RELAY_2_PIN, 1);
    gpioWrite(RELAY_3_PIN, 1);
    gpioWrite(RELAY_4_PIN, 1);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    srand((unsigned)time(NULL));

    while (running) {
        int moisture = read_moisture_sensor();
        int r1 = (moisture < MOISTURE_THRESHOLD) ? 0 : 1;
        int r2 = (moisture >= MOISTURE_THRESHOLD) ? 0 : 1;
        int r3 = (moisture >= MOISTURE_THRESHOLD) ? 0 : 1;
        int r4 = (moisture >= MOISTURE_THRESHOLD) ? 0 : 1;

        control_relay(1, r1);
        control_relay(2, r2);
        control_relay(3, r3);
        control_relay(4, r4);

        log_data(moisture, r1, r2, r3, r4);

        gpioDelay(POLL_INTERVAL_SEC * 1000000);
    }

    cleanup();
    return 0;
}

