#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ADXL345 I2C address (SDO tied to GND) */
#define ADXL345_ADDRESS 0x52

/* ADXL345 registers */
#define ADXL345_POWER_CTL   0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0      0x32

/* Free-fall threshold: 0.2 g */
#define FREEFALL_THRESHOLD_G 0.2

/* Alarm GPIO (BCM numbering) */
#define ALARM_GPIO 27

/* Polling interval in microseconds (100 ms) */
#define POLL_INTERVAL_US 100000

/* Free-fall confirmation delay in microseconds (0.5 s) */
#define FREEFALL_CONFIRM_US 500000

/* Alarm hold time in microseconds (5 s) */
#define ALARM_HOLD_US 5000000

/* Global state */
static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a byte to an ADXL345 register and check the result           */
/* ------------------------------------------------------------------ */
static int adxl345_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Read a byte from an ADXL345 register                                */
/* ------------------------------------------------------------------ */
static int adxl345_read_byte(int handle, uint8_t reg)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian value from two consecutive registers     */
/* ------------------------------------------------------------------ */
static int adxl345_read_word(int handle, uint8_t reg)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cReadWordData(reg=0x%02X) failed: %d\n", reg, rc);
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Initialise the ADXL345                                              */
/* ------------------------------------------------------------------ */
static int adxl345_init(int handle)
{
    /* Standby mode so configuration changes take effect */
    if (adxl345_write_byte(handle, ADXL345_POWER_CTL, 0x00) < 0)
        return -1;

    /* Data format: full resolution, +/-200 g range, right-justified */
    if (adxl345_write_byte(handle, ADXL345_DATA_FORMAT, 0x0B) < 0)
        return -1;

    /* Clear the self-test bit so normal operation resumes */
    if (adxl345_write_byte(handle, ADXL345_POWER_CTL, 0x08) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read acceleration in g from the ADXL345                             */
/* ------------------------------------------------------------------ */
static int adxl345_read_acceleration(int handle, float *x, float *y, float *z)
{
    int16_t raw_x, raw_y, raw_z;

    raw_x = (int16_t)adxl345_read_word(handle, ADXL345_DATAX0);
    if (raw_x < 0)
        return -1;

    raw_y = (int16_t)adxl345_read_word(handle, ADXL345_DATAX0 + 2);
    if (raw_y < 0)
        return -1;

    raw_z = (int16_t)adxl345_read_word(handle, ADXL345_DATAX0 + 4);
    if (raw_z < 0)
        return -1;

    /* Full-resolution mode: 4 mg/LSB => divide by 4096 */
    *x = (float)raw_x / 4096.0f;
    *y = (float)raw_y / 4096.0f;
    *z = (float)raw_z / 4096.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Detect a free-fall event                                            */
/* ------------------------------------------------------------------ */
static bool detect_freefall(float x, float y, float z)
{
    return (fabsf(x) < FREEFALL_THRESHOLD_G &&
            fabsf(y) < FREEFALL_THRESHOLD_G &&
            fabsf(z) < FREEFALL_THRESHOLD_G);
}

/* ------------------------------------------------------------------ */
/* Log a free-fall event to file                                       */
/* ------------------------------------------------------------------ */
static void log_freefall(float x, float y, float z)
{
    FILE *fp = fopen("freefall.log", "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open freefall.log for appending\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                x, y, z);
    } else {
        fprintf(fp, "timestamp_error,%.3f,%.3f,%.3f\n", x, y, z);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(ALARM_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the ADXL345 address */
    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                ADXL345_ADDRESS, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise the sensor */
    if (adxl345_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: ADXL345 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure alarm GPIO as output, initially low */
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_GPIO, 0);

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Free-fall detection started. Press Ctrl+C to exit.\n");

    while (program_running) {
        float x, y, z;

        if (adxl345_read_acceleration(i2c_handle, &x, &y, &z) < 0) {
            fprintf(stderr, "Warning: I2C read error, continuing...\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (detect_freefall(x, y, z)) {
            gpioDelay(FREEFALL_CONFIRM_US);

            /* Re-read after the confirmation delay */
            if (adxl345_read_acceleration(i2c_handle, &x, &y, &z) < 0) {
                fprintf(stderr, "Warning: I2C read error during confirmation, continuing...\n");
                continue;
            }

            if (detect_freefall(x, y, z)) {
                printf("Free-fall confirmed!\n");
                log_freefall(x, y, z);
                gpioWrite(ALARM_GPIO, 1);
                gpioDelay(ALARM_HOLD_US);
                gpioWrite(ALARM_GPIO, 0);
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

