#define CYCLE_DELAY_US   200000
#define MAX_PULSE_US     23200
#define TIMEOUT_US       100000
#define LOG_FILE         "distance_log.txt"

static volatile uint32_t g_tick = 0;
static volatile uint32_t g_pulse_us = 0;
static volatile bool     g_echo_seen = false;
static volatile bool     g_running   = true;
static FILE             *g_log_fp    = NULL;
static pthread_mutex_t   g_mutex;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = false;
}

static void tick_increment(void)
{
    uint32_t prev = g_tick;
    gpioDelay(1000);
    uint32_t cur = g_tick;
    g_tick = cur;
    if (cur - prev > 0xFFFFFFFFu)
        g_tick = prev + 1u;
}

static void echo_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;
    if (level == 1) {
        g_echo_seen = true;
        g_pulse_us  = tick - g_tick;
    } else if (level == 0 && g_echo_seen) {
        g_pulse_us = tick - g_tick;
        g_echo_seen = false;
    }
}

static void trigger_pulse(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static void log_distance(uint32_t pulse_us)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    long long ns = (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;
    fprintf(g_log_fp, "%lld,%.2f\n", ns, pulse_us / 1000000.0);
    fflush(g_log_fp);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (pthread_mutex_init(&g_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialisation failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioWrite(TRIGGER_PIN, 0);

    if (gpioSetISRFuncEx(ECHO_PIN, RISING_EDGE, 0, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set rising-edge ISR\n");
        pthread_mutex_destroy(&g_mutex);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetISRFuncEx(ECHO_PIN, FALLING_EDGE, 0, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set falling-edge ISR\n");
        gpioSetISRFuncEx(ECHO_PIN, RISING_EDGE, 0, NULL, NULL);
        pthread_mutex_destroy(&g_mutex);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("Error opening log file");
        gpioSetISRFuncEx(ECHO_PIN, RISING_EDGE, 0, NULL, NULL);
        pthread_mutex_destroy(&g_mutex);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        fclose(g_log_fp);
        gpioSetISRFuncEx(ECHO_PIN, RISING_EDGE, 0, NULL, NULL);
        pthread_mutex_destroy(&g_mutex);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (g_running) {
        g_echo_seen = false;
        g_pulse_us  = 0;
        trigger_pulse();

        tick_increment();
        tick_increment();
        tick_increment();

        uint32_t start_tick = g_tick;
        while (g_running && !g_echo_seen && (g_tick - start_tick) < TIMEOUT_US)
            tick_increment();

        if (!g_echo_seen) {
            fprintf(stderr, "Timeout: no echo received within %d us\n", TIMEOUT_US);
            continue;
        }

        if (g_pulse_us > MAX_PULSE_US) {
            fprintf(stderr, "Invalid pulse width: %u us (out of range)\n", g_pulse_us);
            continue;
        }

        log_distance(g_pulse_us);
        printf("Distance: %.2f cm\n", g_pulse_us / 1000000.0);

        while (g_running && (g_tick - start_tick) < CYCLE_DELAY_US)
            tick_increment();
    }

    printf("\nCleaning up...\n");
    gpioSetISRFuncEx(ECHO_PIN, RISING_EDGE, 0, NULL, NULL);
    gpioSetISRFuncEx(ECHO_PIN, FALLING_EDGE, 0, NULL, NULL);
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    pthread_mutex_destroy(&g_mutex);
    gpioTerminate();
    return EXIT_SUCCESS;
}

