#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <pigpio.h>

#define I2C_BUS 1
#define LIS3DH_ADDR 0x19
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define BUZZER_PIN 17
#define DEFAULT_FF_THRESHOLD 0.2
#define DEFAULT_IMPACT_THRESHOLD 1.5
#define SAMPLE_DELAY_US 100000
#define I2C_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t value) {
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        int rc = i2cWriteByteData(handle, reg, value);
        if (rc == 0) return 0;
        gpioDelay(10000);
    }
    return -1;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
        if (rc == (int)len) return 0;
        gpioDelay(10000);
    }
    return -1;
}

static int init_lis3dh(int handle) {
    if (i2c_write_reg(handle, CTRL_REG1, 0x70) != 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG1\n");
        return -1;
    }
    if (i2c_write_reg(handle, CTRL_REG4, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG4\n");
        return -1;
    }
    return 0;
}

static int read_acceleration(int handle, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_block(handle, OUT_X_L, buf, 6) != 0) {
        fprintf(stderr, "Error: Failed to read acceleration data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)raw_x / 16384.0f;
    *y = (float)raw_y / 16384.0f;
    *z = (float)raw_z / 16384.0f;
    return 0;
}

static bool detect_freefall(float x, float y, float z) {
    return (fabsf(x) < DEFAULT_FF_THRESHOLD && fabsf(y) < DEFAULT_FF_THRESHOLD && fabsf(z) < DEFAULT_FF_THRESHOLD);
}

static bool detect_impact(float x, float y, float z) {
    return (fabsf(x) > DEFAULT_IMPACT_THRESHOLD && fabsf(y) > DEFAULT_IMPACT_THRESHOLD && fabsf(z) > DEFAULT_IMPACT_THRESHOLD);
}

static void activate_buzzer(int pin, int duration_ms) {
    gpioWrite(pin, 1);
    gpioDelay(duration_ms * 1000);
    gpioWrite(pin, 0);
}

int main(int argc, char *argv[]) {
    float freefall_threshold = DEFAULT_FF_THRESHOLD;
    float impact_threshold = DEFAULT_IMPACT_THRESHOLD;

    int opt;
    while ((opt = getopt(argc, argv, "f:i:")) != -1) {
        switch (opt) {
            case 'f': freefall_threshold = atof(optarg); break;
            case 'i': impact_threshold = atof(optarg); break;
            default:
                fprintf(stderr, "Usage: %s [-f freefall_threshold] [-i impact_threshold]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, LIS3DH_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_lis3dh(i2c_handle) != 0) {
        fprintf(stderr, "Error: LIS3DH initialisation failed (sensor may be absent)\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioWrite(BUZZER_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Monitoring acceleration (freefall threshold: %.2f g, impact threshold: %.2f g)...\n", freefall_threshold, impact_threshold);

    while (running) {
        float x, y, z;
        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            if (detect_freefall(x, y, z)) {
                printf("Freefall detected!\n");
            } else if (detect_impact(x, y, z)) {
                printf("Impact detected! Activating buzzer.\n");
                activate_buzzer(BUZZER_PIN, 1000);
            }
        } else {
            fprintf(stderr, "Warning: I2C read failed, retrying...\n");
        }
        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(BUZZER_PIN, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

