    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Configure one motor's four IN pins as outputs and set them low.   */
static int configure_motor(int in1, int in2, int in3, int in4)
{
    int pins[4] = {in1, in2, in3, in4};
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: gpioSetMode failed for GPIO%d\n", pins[i]);
            return -1;
        }
        if (gpioWrite(pins[i], 0) < 0) {
            fprintf(stderr, "Error: gpioWrite failed for GPIO%d\n", pins[i]);
            return -1;
        }
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Drive a single step for the given motor.                            */
static int step_motor(int in1, int in2, int in3, int in4, int step_idx)
{
    const int *seq = step_sequence[step_idx];
    if (gpioWrite(in1, seq[0]) < 0 ||
        gpioWrite(in2, seq[1]) < 0 ||
        gpioWrite(in3, seq[2]) < 0 ||
        gpioWrite(in4, seq[3]) < 0) {
        fprintf(stderr, "Error: failed to write motor pins\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Move a motor by 'count' steps in the given direction.               */
/* direction: +1 forward, -1 reverse.                                  */
static int move_motor(int in1, int in2, int in3, int in4,
                      int count, int direction)
{
    int current_step = 0;
    for (int i = 0; i < count && g_running; i++) {
        current_step += direction;
        if (current_step < 0)   current_step = 3;
        if (current_step > 3)  current_step = 0;
        if (step_motor(in1, in2, in3, in4, current_step) < 0)
            return -1;
        gpioDelay(STEP_DELAY_US);
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Calculate number of steps needed for a given linear distance.       */
/* 28BYJ-48: 2048 steps per revolution, gear ratio 1/64.               */
static int calculate_steps(float distance_mm)
{
    return (int)(((distance_mm * 1000.0f) / (float)SQUARE_DIAMETER_MM) *
                 (float)STEPS_PER_REVOLUTION / 64.0f);
}

/* ------------------------------------------------------------------ */
/* Safely stop both motors and set all pins low.                       */
static void stop_motors(void)
{
    gpioWrite(MOTOR1_IN1, 0);
    gpioWrite(MOTOR1_IN2, 0);
    gpioWrite(MOTOR1_IN3, 0);
    gpioWrite(MOTOR1_IN4, 0);
    gpioWrite(MOTOR2_IN1, 0);
    gpioWrite(MOTOR2_IN2, 0);
    gpioWrite(MOTOR2_IN3, 0);
    gpioWrite(MOTOR2_IN4, 0);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure motor pins ---- */
    if (configure_motor(MOTOR1_IN1, MOTOR1_IN2, MOTOR1_IN3, MOTOR1_IN4) < 0 ||
        configure_motor(MOTOR2_IN1, MOTOR2_IN2, MOTOR2_IN3, MOTOR2_IN4) < 0) {
        fprintf(stderr, "Error: motor configuration failed\n");
        stop_motors();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handler for graceful shutdown ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        stop_motors();
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        stop_motors();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("28BYJ-48 dual stepper ready. Ctrl+C to stop.\n");

    /* ---- Trace a 50 mm square ---- */
    int steps_x = calculate_steps((float)SQUARE_DIAMETER_MM);
    int steps_y = calculate_steps((float)SQUARE_DIAMETER_MM);

    printf("Moving X %d steps, Y %d steps...\n", steps_x, steps_y);

    if (move_motor(MOTOR1_IN1, MOTOR1_IN2, MOTOR1_IN3, MOTOR1_IN4,
                   steps_x, 1) < 0) {
        fprintf(stderr, "Error: X-axis movement failed\n");
        stop_motors();
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (move_motor(MOTOR2_IN1, MOTOR2_IN2, MOTOR2_IN3, MOTOR2_IN4,
                   steps_y, 1) < 0) {
        fprintf(stderr, "Error: Y-axis movement failed\n");
        stop_motors();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Graceful shutdown ---- */
    printf("Stopping motors and cleaning up...\n");
    stop_motors();
    gpioTerminate();
    return EXIT_SUCCESS;
}

