#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <errno.h>
#include <pigpio.h>

/* LIS3DH Registers */
#define LIS3DH_REG_CTRL1   0x20
#define LIS3DH_REG_CTRL4   0x23
#define LIS3DH_REG_OUT_X_L 0x28
#define LIS3DH_REG_OUT_X_H 0x29
#define LIS3DH_REG_OUT_Y_L 0x2A
#define LIS3DH_REG_OUT_Y_H 0x2B
#define LIS3DH_REG_OUT_Z_L 0x2C
#define LIS3DH_REG_OUT_Z_H 0x2D

/* Configuration */
#define DEFAULT_I2C_BUS 1
#define DEFAULT_I2C_ADDRESS 0x19
#define DEFAULT_THRESHOLD 2.0f
#define LOG_FILE "/var/log/high_acceleration.log"
#define SAMPLE_INTERVAL_US 100000  /* 100 ms = 10 Hz */

/* LIS3DH CTRL_REG1 (0x20) bits */
#define CTRL1_TUM_100HZ  0x30   /* 100 Hz output data rate */
#define CTRL1_ODR_100HZ  0x30   /* 100 Hz output data rate */
#define CTRL1_HR_MODE    0x01   /* High-resolution mode (12-bit) */
#define CTRL1_ALL_AXES  0x07   /* X, Y, Z axes enabled */
#define CTRL1_VALUE      (CTRL1_TUM_100HZ | CTRL1_ODR_100HZ | CTRL1_HR_MODE | CTRL1_ALL_AXES)

/* LIS3DH CTRL_REG4 (0x23) bits */
#define CTRL4_FS_2G      0x00   /* Full-scale range ±2 g */
#define CTRL4_VALUE      CTRL4_FS_2G

/* Globals for cleanup */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float x, y, z;
} AccelerationData;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a register; returns 0 on success, -1 on error     */
/* ------------------------------------------------------------------ */
static int write_register(int handle, uint8_t reg, uint8_t value)
{
    if (i2cWriteByteData(handle, reg, value) < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from a register; returns value >= 0 on success   */
/* ------------------------------------------------------------------ */
static int read_register(int handle, uint8_t reg)
{
    int v = i2cReadByteData(handle, reg);
    if (v < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n",
                reg, strerror(errno));
    }
    return v;
}

/* ------------------------------------------------------------------ */
/* Initialize the LIS3DH accelerometer                                 */
/* ------------------------------------------------------------------ */
static int initialize_accelerometer(int handle)
{
    /* CTRL_REG1: 100 Hz, high-resolution, all axes enabled */
    if (write_register(handle, LIS3DH_REG_CTRL1, CTRL1_VALUE) < 0)
        return -1;

    /* CTRL_REG4: ±2 g full-scale */
    if (write_register(handle, LIS3DH_REG_CTRL4, CTRL4_VALUE) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read acceleration data (12-bit left-justified, two's complement)    */
/* ------------------------------------------------------------------ */
static AccelerationData read_acceleration_data(int handle)
{
    AccelerationData data = {0.0f, 0.0f, 0.0f};
    int16_t raw_x, raw_y, raw_z;

    int x_l = read_register(handle, LIS3DH_REG_OUT_X_L);
    int x_h = read_register(handle, LIS3DH_REG_OUT_X_H);
    int y_l = read_register(handle, LIS3DH_REG_OUT_Y_L);
    int y_h = read_register(handle, LIS3DH_REG_OUT_Y_H);
    int z_l = read_register(handle, LIS3DH_REG_OUT_Z_L);
    int z_h = read_register(handle, LIS3DH_REG_OUT_Z_H);

    if (x_l < 0 || x_h < 0 || y_l < 0 || y_h < 0 ||
        z_l < 0 || z_h < 0) {
        fprintf(stderr, "Error reading acceleration data: %s\n",
                strerror(errno));
        return data;  /* Return zeros on error */
    }

    /* Combine low and high bytes (12-bit left-justified) */
    raw_x = (int16_t)((x_h << 8) | x_l);
    raw_y = (int16_t)((y_h << 8) | y_l);
    raw_z = (int16_t)((z_h << 8) | z_l);

    /* Convert to g: 12-bit left-justified, ±2 g full-scale */
    /* Sensitivity: 1 mg/LSB = 0.001 g/LSB */
    data.x = (float)raw_x * 0.001f;
    data.y = (float)raw_y * 0.001f;
    data.z = (float)raw_z * 0.001f;

    return data;
}

/* ------------------------------------------------------------------ */
/* Check if any axis exceeds the threshold                             */
/* ------------------------------------------------------------------ */
static int check_threshold(AccelerationData data, float threshold)
{
    return (fabsf(data.x) > threshold ||
            fabsf(data.y) > threshold ||
            fabsf(data.z) > threshold);
}

/* ------------------------------------------------------------------ */
/* Log acceleration data to file                                       */
/* ------------------------------------------------------------------ */
static void log_acceleration_data(AccelerationData data, float threshold)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) != NULL) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, X: %.3f, Y: %.3f, Z: %.3f, Threshold: %.3f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                data.x, data.y, data.z, threshold);
    } else {
        fprintf(fp, "(time error), X: %.3f, Y: %.3f, Z: %.3f, Threshold: %.3f\n",
                data.x, data.y, data.z, threshold);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                   */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Usage                                                               */
/* ------------------------------------------------------------------ */
static void usage(const char *program_name)
{
    fprintf(stderr,
        "Usage: %s [-a i2c_address_hex] [-t threshold_g]\n"
        "  -a  I2C address (hex, default: 0x19)\n"
        "  -t  Threshold in g (default: 2.0, must be > 0)\n",
        program_name);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int i2c_address = DEFAULT_I2C_ADDRESS;
    float threshold = DEFAULT_THRESHOLD;
    int opt;

    while ((opt = getopt(argc, argv, "a:t:h")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 16);
                if (i2c_address < 0x03 || i2c_address > 0x77) {
                    fprintf(stderr,
                        "Invalid I2C address 0x%02X (must be 0x03-0x77)\n",
                        i2c_address);
                    return EXIT_FAILURE;
                }
                break;
            case 't':
                threshold = strtof(optarg, NULL);
                if (threshold <= 0.0f) {
                    fprintf(stderr, "Threshold must be > 0\n");
                    return EXIT_FAILURE;
                }
                break;
            case 'h':
            default:
                usage(argv[0]);
                return EXIT_SUCCESS;
        }
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(DEFAULT_I2C_BUS, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %s\n",
                DEFAULT_I2C_BUS, i2c_address, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize accelerometer */
    if (initialize_accelerometer(i2c_handle) < 0) {
        fprintf(stderr, "Error initializing accelerometer\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n",
                strerror(errno));
    }

    printf("Monitoring acceleration (threshold %.2f g)... Press Ctrl+C to exit.\n",
           threshold);

    /* Main loop */
    while (!terminate) {
        AccelerationData data = read_acceleration_data(i2c_handle);

        if (check_threshold(data, threshold)) {
            log_acceleration_data(data, threshold);
            printf("Threshold exceeded! Logged to %s\n", LOG_FILE);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

