#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x1D
#define RELAY_GPIO     17
#define FIELD_THRESHOLD 5.0f
#define SAMPLE_PERIOD_US 100000
#define REG_DEVICE_CONFIG 0x00
#define REG_FIELD_MSB    0x01
#define REG_FIELD_LSB    0x02
#define REG_DEVICE_ID    0x0F
#define DEVICE_ID_EXPECTED 0x1D
#define POLL_TIMEOUT_COUNT 50
#define POLL_TIMEOUT_US   1000

static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *event) {
    FILE *fp = fopen("magnetic_events.txt", "a");
    if (!fp) {
        perror("fopen magnetic_events.txt");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s: %s\n", ts, event);
    }
    fclose(fp);
}

static int initialize_sensor(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }

    int id = i2cReadByteData(i2c_handle, REG_DEVICE_ID);
    if (id < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", id);
        return -1;
    }
    if (id != DEVICE_ID_EXPECTED) {
        fprintf(stderr, "Unexpected device ID 0x%02X (expected 0x%02X)\n", id, DEVICE_ID_EXPECTED);
        return -1;
    }

    int rc = i2cWriteByteData(i2c_handle, REG_DEVICE_CONFIG, 0x00);
    if (rc < 0) {
        fprintf(stderr, "Error writing DEVICE_CONFIG: %d\n", rc);
        return -1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);
    return 0;
}

static int read_field(float *field) {
    int msb = i2cReadByteData(i2c_handle, REG_FIELD_MSB);
    if (msb < 0) {
        fprintf(stderr, "Error reading FIELD_MSB: %d\n", msb);
        return -1;
    }
    int lsb = i2cReadByteData(i2c_handle, REG_FIELD_LSB);
    if (lsb < 0) {
        fprintf(stderr, "Error reading FIELD_LSB: %d\n", lsb);
        return -1;
    }
    uint16_t raw = ((uint16_t)msb << 8) | (uint16_t)lsb;
    *field = (float)raw * 0.01f;
    return 0;
}

static void control_relay(float field) {
    static int relay_state = 0;
    if (field > FIELD_THRESHOLD && !relay_state) {
        gpioWrite(RELAY_GPIO, 1);
        relay_state = 1;
        log_event("Relay activated");
    } else if (field <= FIELD_THRESHOLD && relay_state) {
        gpioWrite(RELAY_GPIO, 0);
        relay_state = 0;
        log_event("Relay deactivated");
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    log_event("Program terminated");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (initialize_sensor() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        cleanup();
        return EXIT_FAILURE;
    }

    int timeout_count = 0;
    while (program_running) {
        float field;
        if (read_field(&field) != 0) {
            log_event("Error reading magnetic field, retrying next cycle");
            gpioWrite(RELAY_GPIO, 0);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        if (field < 0.0f || field > 10.0f) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Invalid field reading: %.2f mT", field);
            log_event(msg);
            gpioWrite(RELAY_GPIO, 0);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        control_relay(field);

        if (timeout_count >= POLL_TIMEOUT_COUNT) {
            log_event("Sensor timeout: device not responding after 50 polls");
            gpioWrite(RELAY_GPIO, 0);
            break;
        }
        timeout_count = 0;

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

