#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PORT 5000
#define LOG_FILE "relay_log.txt"
#define BUFFER_SIZE 1024
#define BACKLOG 3

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int new_socket = -1;
static FILE *log_file = NULL;

static void log_event(const char *message) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

static void cleanup(void) {
    if (new_socket >= 0) {
        close(new_socket);
        new_socket = -1;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
    if (log_file) {
        log_event("Shutdown complete.");
        fclose(log_file);
        log_file = NULL;
    }
}

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
