/*
 * Raspberry Pi Zero W — Dual SLF3S-1300F Liquid Flow Sensor Monitor
 *
 * Hardware:
 *   - I2C bus 1 (GPIO2=SDA, GPIO3=SCL), 100 kHz
 *   - Sensor 1: 0x2A, Sensor 2: 0x2B
 *   - Safety relay module on GPIO 18 (BCM), active-high
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o flow_monitor flow_monitor.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./flow_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS              1
#define SENSOR1_ADDR         0x2A
#define SENSOR2_ADDR         0x2B
#define RELAY_GPIO           18
#define FLOW_THRESHOLD       5.0f   /* ml/min */
#define POLL_DELAY_US        100000 /* 100 ms */
#define LOG_FILE             "flow_log.txt"

/* SLF3S-1300F: start continuous measurement command */
#define CMD_START_MEASURE    0x362F

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_h1 = -1;
static int  g_i2c_h2 = -1;
static bool g_pigpio_inited = false;

/* ---- CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR) ---- */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_h1 >= 0) {
        i2cClose(g_i2c_h1);
        g_i2c_h1 = -1;
    }
    if (g_i2c_h2 >= 0) {
        i2cClose(g_i2c_h2);
        g_i2c_h2 = -1;
    }
    if (g_pigpio_inited) {
        gpioWrite(RELAY_GPIO, 0);
        gpioTerminate();
        g_pigpio_inited = false;
    }
}

/* ---- Read one SLF3S-1300F sensor ----
 * Returns 0 on success (flow_rate populated), -1 on error.
 */
static int read_flow_rate(int handle, float *flow_rate)
{
    uint8_t buf[3];
    int n = i2cReadDevice(handle, (char *)buf, 3);
    if (n != 3) {
        fprintf(stderr, "[warn] i2cReadDevice returned %d (expected 3)\n", n);
        return -1;
    }
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[warn] CRC mismatch on handle %d\n", handle);
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *flow_rate = (float)raw / 100.0f; /* ml/min */
    return 0;
}

/* ---- Log flow data with millisecond timestamp ---- */
static void log_flow_data(float f1, float f2)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("[error] fopen log");
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s.%03ld, Sensor1: %.2f ml/min, Sensor2: %.2f ml/min\n",
            tbuf, ts.tv_nsec / 1000000L, f1, f2);
    fflush(fp);
    fclose(fp);
}

/* ---- Control relay ---- */
static void control_relay(float f1, float f2)
{
    int target = (f1 < FLOW_THRESHOLD || f2 < FLOW_THRESHOLD) ? 1 : 0;
    if (gpioWrite(RELAY_GPIO, target) != 0)
        fprintf(stderr, "[warn] gpioWrite(%d) failed\n", target);
}

/* ---- Initialize pigpio, I2C, and relay GPIO ----
 * Returns 0 on success, -1 on failure (resources partially released).
 */
static int initialize(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[error] gpioInitialise failed\n");
        return -1;
    }
    g_pigpio_inited = true;

    g_i2c_h1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (g_i2c_h1 < 0) {
        fprintf(stderr, "[error] i2cOpen sensor 1 (0x%02X) failed: %d\n",
                SENSOR1_ADDR, g_i2c_h1);
        return -1;
    }

    g_i2c_h2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (g_i2c_h2 < 0) {
        fprintf(stderr, "[error] i2cOpen sensor 2 (0x%02X) failed: %d\n",
                SENSOR2_ADDR, g_i2c_h2);
        i2cClose(g_i2c_h1);
        g_i2c_h1 = -1;
        return -1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[error] gpioSetMode(%d, OUTPUT) failed\n", RELAY_GPIO);
        i2cClose(g_i2c_h1);
        i2cClose(g_i2c_h2);
        g_i2c_h1 = -1;
        g_i2c_h2 = -1;
        return -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    return 0;
}

/* ---- Start continuous measurement on both sensors ----
 * Returns 0 on success, -1 on failure.
 */
static int start_measurement(void)
{
    uint8_t cmd[2] = { (uint8_t)(CMD_START_MEASURE >> 8),
                       (uint8_t)(CMD_START_MEASURE & 0xFF) };
    if (i2cWriteDevice(g_i2c_h1, (char *)cmd, 2) != 0) {
        fprintf(stderr, "[error] start_measurement sensor 1 failed\n");
        return -1;
    }
    if (i2cWriteDevice(g_i2c_h2, (char *)cmd, 2) != 0) {
        fprintf(stderr, "[error] start_measurement sensor 2 failed\n");
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[error] sigaction");
        return EXIT_FAILURE;
    }

    if (initialize() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (start_measurement() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Allow first measurement to complete (datasheet: ~10 ms) */
    gpioDelay(15000);

    while (g_running) {
        float f1 = 0.0f, f2 = 0.0f;
        bool ok1 = (read_flow_rate(g_i2c_h1, &f1) == 0);
        bool ok2 = (read_flow_rate(g_i2c_h2, &f2) == 0);

        if (!ok1 || !ok2) {
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        log_flow_data(f1, f2);
        control_relay(f1, f2);
        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    printf("[info] Shutdown complete.\n");
    return EXIT_SUCCESS;
}

