        fprintf(stderr, "[error] start_measurement sensor 1 failed\n");
        return -1;
    }
    if (i2cWriteDevice(g_i2c_h2, (char *)cmd, 2) != 0) {
        fprintf(stderr, "[error] start_measurement sensor 2 failed\n");
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[error] sigaction");
        return EXIT_FAILURE;
    }

    if (initialize() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (start_measurement() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Allow first measurement to complete (datasheet: ~10 ms) */
    gpioDelay(15000);

    while (g_running) {
        float f1 = 0.0f, f2 = 0.0f;
        bool ok1 = (read_flow_rate(g_i2c_h1, &f1) == 0);
        bool ok2 = (read_flow_rate(g_i2c_h2, &f2) == 0);

        if (!ok1 || !ok2) {
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        log_flow_data(f1, f2);
        control_relay(f1, f2);
        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    printf("[info] Shutdown complete.\n");
    return EXIT_SUCCESS;
}

