#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>
#include <stdbool.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENABLE_PIN 22
#define MOTOR_INPUT_1_PIN 23
#define MOTOR_INPUT_2_PIN 24

#define MOTOR_RUN_TIME_US 5000000  /* 5 seconds in microseconds */
#define POLL_INTERVAL_US 200000    /* 200 ms in microseconds */
#define DRY_CONFIRMATION_POLLS 3   /* 3 consecutive dry readings to re-arm */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int motor_stop(void)
{
    int rc = 0;
    if (gpioWrite(MOTOR_ENABLE_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to set ENA low: %s", pigpio_error(0));
        rc = -1;
    }
    if (gpioWrite(MOTOR_INPUT_1_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to set IN1 low: %s", pigpio_error(0));
        rc = -1;
    }
    if (gpioWrite(MOTOR_INPUT_2_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to set IN2 low: %s", pigpio_error(0));
        rc = -1;
    }
    return rc;
}

static int motor_run(void)
{
    int rc = 0;
    if (gpioWrite(MOTOR_ENABLE_PIN, 1) < 0) {
        syslog(LOG_ERR, "Failed to set ENA high: %s", pigpio_error(0));
        rc = -1;
    }
    if (gpioWrite(MOTOR_INPUT_1_PIN, 1) < 0) {
        syslog(LOG_ERR, "Failed to set IN1 high: %s", pigpio_error(0));
        rc = -1;
    }
    if (gpioWrite(MOTOR_INPUT_2_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to set IN2 low: %s", pigpio_error(0));
        rc = -1;
    }
    return rc;
}

static int close_window(void)
{
    syslog(LOG_INFO, "Closing window...");
    if (motor_run() < 0) {
        syslog(LOG_ERR, "Motor run failed");
        return -1;
    }
    gpioDelay(MOTOR_RUN_TIME_US);
    if (motor_stop() < 0) {
        syslog(LOG_ERR, "Motor stop failed");
        return -1;
    }
    syslog(LOG_INFO, "Window closed.");
    return 0;
}

static int rain_detected(void)
{
    syslog(LOG_INFO, "Rain detected!");
    return close_window();
}

static int dry_confirmation(void)
{
    for (int i = 0; i < DRY_CONFIRMATION_POLLS; i++) {
        if (gpioRead(RAIN_SENSOR_PIN) == 1) {
            return 0;
        }
        gpioDelay(POLL_INTERVAL_US);
    }
    syslog(LOG_INFO, "Sensor dry and stable.");
    return 0;
}

int main(void)
{
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to register SIGINT handler: %m");
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to register SIGTERM handler: %m");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set rain sensor pin mode");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) < 0) {
        syslog(LOG_ERR, "Failed to set pull-up on rain sensor pin");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_ENABLE_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_INPUT_1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_INPUT_2_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set motor pin modes");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (motor_stop() < 0) {
        syslog(LOG_ERR, "Initial motor stop failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Rain sensor monitoring started (GPIO %d, pull-up). Ctrl+C to exit.", RAIN_SENSOR_PIN);

    int last_state = gpioRead(RAIN_SENSOR_PIN);
    if (last_state < 0) {
        syslog(LOG_ERR, "Initial sensor read failed: %s", pigpio_error(0));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int current_state = gpioRead(RAIN_SENSOR_PIN);
        if (current_state < 0) {
            syslog(LOG_ERR, "Sensor read failed: %s", pigpio_error(0));
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (current_state == 0 && last_state == 1) {
            /* Rising edge: dry -> wet (rain detected) */
            if (rain_detected() < 0) {
                syslog(LOG_ERR, "Rain detection sequence failed");
            }
            if (dry_confirmation() < 0) {
                syslog(LOG_ERR, "Dry confirmation failed");
            }
        }

        last_state = current_state;
        gpioDelay(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down...");
    if (motor_stop() < 0) {
        syslog(LOG_ERR, "Motor stop during shutdown failed");
    }
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

