#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define LOCK_BUTTON    21
#define UNLOCK_BUTTON  22

#define LOCK_PULSE_US  2000
#define UNLOCK_PULSE_US 1000
#define DEBOUNCE_US    50000   /* 50 ms */
#define POLL_US        10000   /* 10 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int set_servo_pulse(int pulse_us)
{
    if (gpioServo(SERVO_PIN, pulse_us) != 0) {
        fprintf(stderr, "Error: gpioServo(%d, %d) failed\n", SERVO_PIN, pulse_us);
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    /* Stop the servo PWM signal */
    gpioServo(SERVO_PIN, 0);

    /* Ensure buttons are released */
    gpioWrite(LOCK_BUTTON, 0);
    gpioWrite(UNLOCK_BUTTON, 0);

    /* Release servo pin */
    gpioSetMode(SERVO_PIN, PI_INPUT);

    /* Terminate pigpio */
    gpioTerminate();
}

int main(void)
{
    int ret = EXIT_SUCCESS;

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure button pins as inputs with internal pull-up resistors */
    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(LOCK_BUTTON) failed\n");
        ret = EXIT_FAILURE;
        goto done;
    }
    if (gpioSetMode(UNLOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(UNLOCK_BUTTON) failed\n");
        ret = EXIT_FAILURE;
        goto done;
    }
    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(LOCK_BUTTON) failed\n");
        ret = EXIT_FAILURE;
        goto done;
    }
    if (gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(UNLOCK_BUTTON) failed\n");
        ret = EXIT_FAILURE;
        goto done;
    }

    /* Configure servo pin as output */
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(SERVO_PIN) failed\n");
        ret = EXIT_FAILURE;
        goto done;
    }

    /* Ensure servo starts in a stopped state */
    if (set_servo_pulse(0) != 0) {
        ret = EXIT_FAILURE;
        goto done;
    }

    printf("Door lock control system started.\n");
    printf("  Servo pin : GPIO%d (BCM)\n", SERVO_PIN);
    printf("  Lock button: GPIO%d (BCM, active-low to ground)\n", LOCK_BUTTON);
    printf("  Unlock button: GPIO%d (BCM, active-low to ground)\n", UNLOCK_BUTTON);
    printf("Press Ctrl+C to exit.\n");

    int last_lock_state = -1;   /* -1 = unknown, 0 = unlocked, 1 = locked */

    while (g_running) {
        int lock_pressed = (gpioRead(LOCK_BUTTON) == 0);
        int unlock_pressed = (gpioRead(UNLOCK_BUTTON) == 0);

        if (lock_pressed) {
            if (set_servo_pulse(LOCK_PULSE_US) != 0) {
                ret = EXIT_FAILURE;
                break;
            }
            printf("Door LOCKED\n");
            fflush(stdout);
            last_lock_state = 1;

            /* Debounce: wait until button is released or timeout */
            uint32_t wait_start = gpioTick();
            while (g_running && gpioRead(LOCK_BUTTON) == 0) {
                if ((gpioTick() - wait_start) > DEBOUNCE_US) {
                    break;
                }
                gpioDelay(POLL_US);
            }
        } else if (unlock_pressed) {
            if (set_servo_pulse(UNLOCK_PULSE_US) != 0) {
                ret = EXIT_FAILURE;
                break;
            }
            printf("Door UNLOCKED\n");
            fflush(stdout);
            last_lock_state = 0;

            /* Debounce: wait until button is released or timeout */
            uint32_t wait_start = gpioTick();
            while (g_running && gpioRead(UNLOCK_BUTTON) == 0) {
                if ((gpioTick() - wait_start) > DEBOUNCE_US) {
                    break;
                }
                gpioDelay(POLL_US);
            }
        }

        gpioDelay(POLL_US);
    }

done:
    cleanup();
    if (ret == EXIT_SUCCESS) {
        printf("Shutdown complete.\n");
    }
    return ret;
}

