#define POLL_INTERVAL_US 100000   /* 100 ms */
#define FLOODLIGHT_DURATION_SEC 60
#define LOG_FILE "security_log.txt"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int log_event(const char *event_type, const char *timestamp,
                     const char *additional_info)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%s %s %s\n", timestamp, event_type,
                additional_info ? additional_info : "") < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int activate_floodlight(int pin, int duration_sec)
{
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Error turning ON floodlight on GPIO %d\n", pin);
        return -1;
    }

    time_t start = time(NULL);
    if (start == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        gpioWrite(pin, 0);
        return -1;
    }

    while (g_running) {
        time_t now = time(NULL);
        if (now == (time_t)-1) {
            fprintf(stderr, "Error getting time: %s\n", strerror(errno));
            break;
        }
        if ((now - start) >= duration_sec) {
            break;
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error turning OFF floodlight on GPIO %d\n", pin);
        return -1;
    }
    return 0;
}

static void cleanup_floodlight(int pin)
{
    gpioWrite(pin, 0);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting PIR pin %d as input\n", PIR_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(FLOODLIGHT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting floodlight pin %d as output\n", FLOODLIGHT_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(FLOODLIGHT_PIN, 0) != 0) {
        fprintf(stderr, "Error initializing floodlight pin %d to OFF\n", FLOODLIGHT_PIN);
        gpioTerminate();
        return 1;
    }

    printf("Motion detection started. PIR=BCM%d, Floodlight=BCM%d, Duration=%ds\n",
           PIR_PIN, FLOODLIGHT_PIN, FLOODLIGHT_DURATION_SEC);
    printf("Press Ctrl+C to exit.\n");

    int last_pir_state = gpioRead(PIR_PIN);
    if (last_pir_state < 0) {
        fprintf(stderr, "Error reading initial PIR state\n");
        cleanup_floodlight(FLOODLIGHT_PIN);
        gpioTerminate();
        return 1;
    }

    while (g_running) {
        int current_pir_state = gpioRead(PIR_PIN);
        if (current_pir_state < 0) {
            fprintf(stderr, "Error reading PIR state\n");
            break;
        }

        if (current_pir_state == 1 && last_pir_state == 0) {
            time_t rawtime;
            struct tm timeinfo;
            char timestamp[32];

            time(&rawtime);
            if (localtime_r(&rawtime, &timeinfo) == NULL) {
                fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
                break;
            }

            if (strftime(timestamp, sizeof(timestamp),
                         "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
                fprintf(stderr, "Error formatting timestamp\n");
                break;
            }

            if (log_event("Motion Detected", timestamp, NULL) != 0) {
                fprintf(stderr, "Error logging motion event\n");
            }

            if (activate_floodlight(FLOODLIGHT_PIN, FLOODLIGHT_DURATION_SEC) != 0) {
                fprintf(stderr, "Error activating floodlight\n");
            }

            if (log_event("Floodlight Deactivated", timestamp, NULL) != 0) {
                fprintf(stderr, "Error logging floodlight deactivation event\n");
            }
        }

        last_pir_state = current_pir_state;
        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup_floodlight(FLOODLIGHT_PIN);
    gpioTerminate();
    printf("\nExiting gracefully. Floodlight OFF.\n");
    return 0;
}

