/*
 * MPR121 Capacitive Touch Relay Controller for Raspberry Pi 5
 *
 * Wiring:
 *   MPR121 SDA -> GPIO2 (I2C1 SDA)
 *   MPR121 SCL -> GPIO3 (I2C1 SCL)
 *   MPR121 ADDR -> GND  (I2C address 0x80)
 *   MPR121 VDD -> 3.3V
 *   MPR121 GND -> GND
 *   Relay IN  -> GPIO17 (BCM)
 *   Relay VCC -> 3.3V or 5V (per relay module)
 *   Relay GND -> GND
 *
 * Build: gcc -O2 -Wall -o mpr121_relay mpr121_relay.c -lpigpio -lrt
 * Run:   sudo ./mpr121_relay
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- MPR121 I2C address (ADDR pin tied to GND) ---- */
#define MPR121_ADDR 0x80

/* ---- MPR121 register addresses ---- */
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECONFIG      0x5E
#define MPR121_SOFTRESET      0x80
#define MPR121_MHDR           0x2B
#define MPR121_NHDR           0x2C
#define MPR121_NCLR           0x2D
#define MPR121_FDLR           0x2E
#define MPR121_MHDF           0x2F
#define MPR121_NHDF           0x30
#define MPR121_NCLF           0x31
#define MPR121_FDLF           0x32
#define MPR121_NHDT           0x33
#define MPR121_NCLT           0x34
#define MPR121_FDLT           0x35
#define MPR121_DEBOUNCE       0x5B
#define MPR121_CONFIG1        0x5C
#define MPR121_CONFIG2        0x5D
#define MPR121_AUTOCONFIG0    0x7B
#define MPR121_AUTOCONFIG1    0x7C
#define MPR121_USL            0x7D
#define MPR121_LSL            0x7E
#define MPR121_TL             0x7F

/* ---- Relay GPIO pin (BCM) ---- */
#define RELAY_PIN 17

/* ---- Debounce time in microseconds ---- */
#define DEBOUNCE_US 200000

/* ---- Global state ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static bool g_relay_state = false;

/* ---- Signal handler ---- */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* ---- Low-level I2C helpers ---- */
static int mpr121_write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(g_i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n", reg, value, rc);
    }
    return rc;
}

static int mpr121_read_reg(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ---- MPR121 initialization ---- */
static int mpr121_init(void) {
    /* Soft reset */
    if (mpr121_write_reg(MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(10000); /* 10 ms settle */

    /* Baseline filtering – rising */
    if (mpr121_write_reg(MPR121_MHDR, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHDR, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCLR, 0x0E) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDLR, 0x00) < 0) return -1;

    /* Baseline filtering – falling */
    if (mpr121_write_reg(MPR121_MHDF, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHDF, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCLF, 0x0E) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDLF, 0x00) < 0) return -1;

    /* Touch / release thresholds */
    if (mpr121_write_reg(MPR121_NHDT, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCLT, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDLT, 0x00) < 0) return -1;

    /* Debounce: 3 samples for touch, 3 for release */
    if (mpr121_write_reg(MPR121_DEBOUNCE, 0x33) < 0) return -1;

    /* FFI = 6 samples, CDC = 16 µA */
    if (mpr121_write_reg(MPR121_CONFIG1, 0x10) < 0) return -1;

    /* CDT = 0.5 µs, SFI = 4 samples, ESI = 1 ms */
    if (mpr121_write_reg(MPR121_CONFIG2, 0x20) < 0) return -1;

    /* Auto-config enable, range 2.4–3.3 V, 12 electrodes */
    if (mpr121_write_reg(MPR121_AUTOCONFIG0, 0x0B) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTOCONFIG1, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_USL, 0xC8) < 0) return -1;
    if (mpr121_write_reg(MPR121_LSL, 0x82) < 0) return -1;
    if (mpr121_write_reg(MPR121_TL, 0xB4) < 0) return -1;

    /* Enable 12 electrodes, baseline tracking */
    if (mpr121_write_reg(MPR121_ELECONFIG, 0x0C) < 0) return -1;

    return 0;
}

/* ---- Read 12-bit touch status ---- */
static int mpr121_read_touch(uint16_t *touch_status) {
    uint8_t lo, hi;
    if (mpr121_read_reg(MPR121_TOUCHSTATUS_L, &lo) < 0) return -1;
    if (mpr121_read_reg(MPR121_TOUCHSTATUS_H, &hi) < 0) return -1;
    *touch_status = ((uint16_t)hi << 8) | lo;
    return 0;
}

/* ---- Relay control ---- */
static void relay_set(bool on) {
    if (gpioWrite(RELAY_PIN, on ? 1 : 0) < 0) {
        fprintf(stderr, "Warning: gpioWrite failed on pin %d\n", RELAY_PIN);
    }
    g_relay_state = on;
    printf("Relay %s\n", on ? "ON" : "OFF");
}

/* ---- Cleanup ---- */
static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at MPR121 address */
    g_i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", MPR121_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify sensor presence by reading touch status */
    uint16_t test;
    if (mpr121_read_touch(&test) < 0) {
        fprintf(stderr, "MPR121 not detected on bus 1 at 0x%02X\n", MPR121_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure relay pin as output, ensure OFF */
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    relay_set(false);

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Initialize MPR121 */
    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MPR121 initialized. Touch electrode 0 to toggle relay.\n");

    /* Main loop */
    uint32_t last_touch_us = 0;
    bool electrode_0_touched = false;

    while (g_running) {
        uint16_t touch = 0;
        if (mpr121_read_touch(&touch) < 0) {
            /* I2C error – back off briefly and retry */
            gpioDelay(100000);
            continue;
        }

        bool now_touched = (touch & 0x0001) != 0;
        uint32_t now = gpioTick();

        if (now_touched && !electrode_0_touched &&
            (now - last_touch_us) >= DEBOUNCE_US) {
            electrode_0_touched = true;
            last_touch_us = now;
            relay_set(!g_relay_state);
            g_relay_state = !g_relay_state;
        } else if (!now_touched && electrode_0_touched) {
            electrode_0_touched = false;
            last_touch_us = now;
        }

        gpioDelay(10000); /* 10 ms poll interval */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

