#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdarg.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <syslog.h>
#include <fcntl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define SERVO_PIN 17
#define PIR_PIN 4
#define PORT 5000
#define LOG_FILE "security.log"
#define PWM_FREQ 50
#define PWM_RANGE 2000000
#define MAX_CMD_LEN 256
#define MAX_RESP_LEN 64

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static FILE *log_file = NULL;

static void log_message(int priority, const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    syslog(priority, "%s ", ts);
    vsyslog(priority, fmt, ap);
    if (log_file) {
        fprintf(log_file, "%s ", ts);
        vfprintf(log_file, fmt, ap);
        fputc('\n', log_file);
        fflush(log_file);
    }
    va_end(ap);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int send_all(int fd, const char *buf, size_t len) {
    size_t sent = 0;
    while (sent < len) {
        ssize_t n = send(fd, buf + sent, len - sent, MSG_NOSIGNAL);
        if (n < 0) {
            if (errno == EINTR) continue;
            return -1;
        }
        sent += (size_t)n;
    }
    return 0;
}

static int handle_client(int client_fd) {
    char buffer[MAX_CMD_LEN + 1];
    ssize_t n = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
    if (n < 0) {
        log_message(LOG_ERR, "recv failed: %s", strerror(errno));
        return -1;
    }
    if (n == 0) {
        log_message(LOGINFO, "Client disconnected");
        return 0;
    }
    buffer[n] = '\0';
    buffer[strcspn(buffer, "\r\n")] = '\0';
    char *cmd = strtok(buffer, " \t\r\n");
    if (!cmd) {
        log_message(LOGWARNING, "Empty command received");
        return 0;
    }
    if (strcmp(cmd, "PIR") == 0) {
        int pir = gpioRead(PIR_PIN);
        char resp[MAX_RESP_LEN];
        snprintf(resp, sizeof(resp), "PIR:%d", pir);
        if (send_all(client_fd, resp, strlen(resp)) < 0) {
            log_message(LOG_ERR, "send failed: %s", strerror(errno));
            return -1;
        }
        log_message(LOGINFO, "PIR command handled: %s", resp);
    } else {
        char angle_str[16];
        int angle = 0;
        if (sscanf(cmd, "the library's API call %15s", angle_str) == 1) {
            angle = atoi(angle_str);
            if (angle >= 0 && angle <= 180) {
                int pulse_width = (int)(500 + (angle * 1000 / 180));
                if (gpioServo(SERVO_PIN, pulse_width) == 0) {
                    char resp[MAX_RESP_LEN];
                    snprintf(resp, sizeof(resp), "OK: servo set to %d", angle);
                    if (send_all(client_fd, resp, strlen(resp)) < 0) {
                        log_message(LOG_ERR, "send failed: %s", strerror(errno));
                        return -1;
                    }
                    log_message(LOGINFO, "Servo command handled: %s", resp);
                } else {
                    log_message(LOG_ERR, "gpioServo failed for angle %d", angle);
                    const char *err = "ERROR: servo command failed\n";
                    send_all(client_fd, err, strlen(err));
                }
            } else {
                const char *err = "ERROR: invalid angle (0-180)\n";
                send_all(client_fd, err, strlen(err));
                log_message(LOG_ERR, "Invalid angle: %s", cmd);
            }
        } else {
            const char *err = "ERROR: invalid command format\n";
            send_all(client_fd, err, strlen(err));
            log_message(LOG_ERR, "Invalid command format: %s", cmd);
        }
    }
    return 0;
}

static void cleanup(void) {
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    closelog();
}

int main(void) {
    openlog("security_server", LOG_PID | LOG_CONS, LOG_USER);
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        syslog(LOG_ERR, "Cannot open log file %s: %s", LOG_FILE, strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }
    log_message(LOG_INFO, "Starting security server");
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        fclose(log_file);
        log_file = NULL;
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        log_message(LOG_ERR, "Failed to set SERVO_PIN mode");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PIR_PIN, PI_INPUT) < 0) {
        log_message(LOG_ERR, "Failed to set PIR_PIN mode");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_message(LOG_ERR, "sigaction failed: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        log_message(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        log_message(LOG_ERR, "setsockopt failed: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(PORT);
    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        log_message(LOG_ERR, "Bind failed: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (listen(server_fd, 3) < 0) {
        log_message(LOG_ERR, "Listen failed: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    log_message(LOGINFO, "Listening on port %d", PORT);
    while (running) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            if (errno == EINTR && !running) break;
            log_message(LOG_ERR, "Accept failed: %s", strerror(errno));
            continue;
        }
        char ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_addr.sin_addr, ip, sizeof(ip));
        char conn_msg[64];
        snprintf(conn_msg, sizeof(conn_msg), "Connection from %s:%d", ip, ntohs(client_addr.sin_port));
        log_message(LOGINFO, "%s", conn_msg);
        handle_client(client_fd);
        close(client_fd);
    }
    log_message(LOGINFO, "Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

