#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x5C
#define GROW_LIGHT_GPIO 23
#define LUX_THRESHOLD 150
#define LOG_FILE "grow_log.txt"
#define SAMPLE_INTERVAL_US 2000000
#define BH1750_CONV_TIME_US 120000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_bh1750(int handle, uint16_t *lux_out) {
    if (handle < 0) {
        return -1;
    }

    if (i2cWriteByte(handle, 0x10) < 0) {
        return -2;
    }

    gpioDelay(BH1750_CONV_TIME_US);

    char buf[2] = {0};
    int bytes_read = i2cReadDevice(handle, buf, 2);
    if (bytes_read != 2) {
        return -3;
    }

    *lux_out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static void log_data(FILE *fp, uint16_t lux) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Lux: %u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, lux);
    fflush(fp);
}

static void control_grow_light(uint16_t lux) {
    int current_state = gpioRead(GROW_LIGHT_GPIO);
    if (current_state < 0) {
        return;
    }
    int new_state = (lux < LUX_THRESHOLD) ? 1 : 0;
    if (new_state != current_state) {
        if (gpioWrite(GROW_LIGHT_GPIO, new_state) == 0) {
            printf("Grow light %s\n", new_state ? "ON" : "OFF");
        } else {
            fprintf(stderr, "Error writing to GPIO %d\n", GROW_LIGHT_GPIO);
        }
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(GROW_LIGHT_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", BH1750_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GROW_LIGHT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", GROW_LIGHT_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GROW_LIGHT_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting up signal handlers");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("BH1750 grow-light controller started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t lux = 0;
        int rc = read_bh1750(i2c_handle, &lux);

        if (rc == 0) {
            log_data(log_file, lux);
            control_grow_light(lux);
            printf("Lux: %u\n", lux);
        } else {
            time_t t = time(NULL);
            struct tm tm;
            if (localtime_r(&t, &tm) != NULL) {
                fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, Error reading BH1750 (rc=%d)\n",
                        tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                        tm.tm_hour, tm.tm_min, tm.tm_sec, rc);
                fflush(log_file);
            }
            fprintf(stderr, "Error reading BH1750 (rc=%d)\n", rc);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
