#define DEFAULT_SCALE_FACTOR    1.0
#define DEFAULT_DURATION_MS     200
#define DEFAULT_AVG_SAMPLES     5
#define STARTUP_AVG_SAMPLES     10
#define POLL_INTERVAL_US        500000
#define HX711_TIMEOUT_US        1000000
#define MAX_RETRIES              3

