#define HX711_DOUT_PIN 23
#define HX711_SCK_PIN  24
#define SOLENOID_PIN   25

#define DEFAULT_THRESHOLD_GRAMS 1000
#define DEFAULT_SCALE_FACTOR    1.0
#define DEFAULT_DURATION_MS     200
#define DEFAULT_AVG_SAMPLES     5
#define STARTUP_AVG_SAMPLES     10
#define POLL_INTERVAL_US        500000
#define HX711_TIMEOUT_US        1000000
#define MAX_RETRIES              3

static volatile sig_atomic_t g_running = 1;
static int g_threshold_grams = DEFAULT_THRESHOLD_GRAMS;
static double g_scale_factor  = DEFAULT_SCALE_FACTOR;
static int g_duration_ms      = DEFAULT_DURATION_MS;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_hx711_raw(int32_t *out) {
    if (gpioWrite(HX711_SCK_PIN, 0) < 0) return -1;

    uint32_t elapsed = 0;
    while (gpioRead(HX711_DOUT_PIN) == 1) {
        if (elapsed >= HX711_TIMEOUT_US) {
            syslog(LOG_ERR, "HX711 DOUT stuck HIGH (timeout)");
            return -1;
        }
        gpioDelay(100);
        elapsed += 100;
    }

    uint32_t value = 0;
    for (int i = 0; i < 24; i++) {
        if (gpioWrite(HX711_SCK_PIN, 1) < 0) return -1;
        gpioDelay(1);
        value <<= 1;
        if (gpioRead(HX711_DOUT_PIN) == 1) value |= 1;
        if (gpioWrite(HX711_SCK_PIN, 0) < 0) return -1;
        gpioDelay(1);
    }

    if (gpioWrite(HX711_SCK_PIN, 1) < 0) return -1;
    gpioDelay(1);
    if (gpioWrite(HX711_SCK_PIN, 0) < 0) return -1;
    gpioDelay(1);

    if (value & 0x800000) value |= 0xFF000000;

    int32_t signed_val = (int32_t)value;
    if (signed_val & 0x80000000) signed_val |= 0xFF000000;

    *out = signed_val;
    return 0;
}

static int read_hx711_average(int32_t *out, int samples) {
    int64_t sum = 0;
    int ok = 0;
    for (int i = 0; i < samples; i++) {
        int32_t raw;
        if (read_hx711_raw(&raw) == 0) {
            sum += raw;
            ok++;
        }
        gpioDelay(1000);
    }
    if (ok == 0) return -1;
    *out = (int32_t)(sum / ok);
    return 0;
}

