#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <errno.h>
#include <time.h>
#include <stdbool.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define MQTT_BROKER_ADDRESS "localhost"
#define MQTT_BROKER_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define MQTT_QOS 0
#define GPIO_PIN 17
#define KEEPALIVE_INTERVAL 60
#define RECONNECT_DELAY 5
#define MAX_PAYLOAD_LENGTH 256

static volatile sig_atomic_t running = 1;
static MQTTClient client;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(int priority, const char *message) {
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, "%s", message);
    closelog();
}

static int set_relay_state(int state) {
    int rc = gpioWrite(GPIO_PIN, state);
    if (rc < 0) {
        log_event(LOG_ERR, "Failed to write GPIO pin");
        return -1;
    }
    return 0;
}

static void message_arrived(void *context, char *topicName,
                             int topicLen, MQTTClient_message *message) {
    (void)context; (void)topicLen;
    if (message == NULL || message->payload == NULL || message->payloadlen <= 0) {
        log_event(LOG_ERR, "Received empty MQTT message");
        MQTTClient_freeMessage(&message);
        MQTTClient_free(topicName);
        return;
    }
    char *payload = malloc(message->payloadlen + 1);
    if (payload == NULL) {
        log_event(LOG_ERR, "Memory allocation failed for payload");
        MQTTClient_freeMessage(&message);
        MQTTClient_free(topicName);
        return;
    }
    memcpy(payload, message->payload, message->payloadlen);
    payload[message->payloadlen] = '\0';

    if (strcmp(payload, "ON") == 0) {
        if (set_relay_state(1) == 0) {
            log_event(LOG_INFO, "Relay turned ON");
        }
    } else if (strcmp(payload, "OFF") == 0) {
        if (set_relay_state(0) == 0) {
            log_event(LOG_INFO, "Relay turned OFF");
        }
    } else {
        log_event(LOG_ERR, "Invalid payload received");
    }
    free(payload);
    MQTTClient_freeMessage(&message);
    MQTTClient_free(topicName);
}

static void connect_callback(void *context, char *cause) {
    (void)context;
    if (cause != NULL) {
        log_event(LOG_ERR, cause);
    } else {
        log_event(LOG_INFO, "Connected to MQTT broker");
        int rc = MQTTClient_subscribe(client, MQTT_TOPIC, MQTT_QOS);
        if (rc != MQTTCLIENT_SUCCESS) {
            log_event(LOG_ERR, "Failed to subscribe to topic");
        } else {
            log_event(LOG_INFO, "Subscribed to topic");
        }
    }
}

static void disconnect_callback(void *context, char *cause) {
    (void)context;
    if (cause != NULL) {
        log_event(LOG_WARNING, cause);
    } else {
        log_event(LOG_INFO, "Disconnected from MQTT broker");
    }
}

static void delivery_complete_callback(void *context, char *cause) {
    (void)context;
    if (cause != NULL) {
        log_event(LOG_WARNING, cause);
    }
}

static int mqtt_connect(void) {
    int rc;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = KEEPALIVE_INTERVAL;
    conn_opts.cleansession = 1;
    conn_opts.connectTimeout = 10;

    rc = MQTTClient_connect(client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        log_event(LOG_ERR, "Failed to connect to MQTT broker");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    MQTTClient_unsubscribe(client, MQTT_TOPIC);
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        log_event(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        log_event(LOG_ERR, "Failed to set GPIO pin mode");
        gpioTerminate();
        return 1;
    }

    if (set_relay_state(0) != 0) {
        log_event(LOG_ERR, "Failed to initialize relay state");
        gpioTerminate();
        return 1;
    }

    MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID,
                      MQTTCLIENT_PERSISTENCE_NONE, NULL);
    MQTTClient_setCallbacks(client, NULL, connect_callback,
                            disconnect_callback, message_arrived,
                            delivery_complete_callback);

    if (mqtt_connect() != 0) {
        gpioTerminate();
        return 1;
    }

    while (running) {
        sleep(1);
    }

    log_event(LOG_INFO, "Shutting down");
    cleanup();
    return 0;
}

