#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO1_PIN 7
#define SERVO2_PIN 8
#define SERVO3_PIN 9
#define SERVO4_PIN 10
#define SERVO5_PIN 11

#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SERVO_HOLD_TIME_SEC 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_pulse(int pin, int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE_WIDTH || pulse_width > SERVO_MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: pulse width %d out of range [%d, %d] on pin %d\n",
                pulse_width, SERVO_MIN_PULSE_WIDTH, SERVO_MAX_PULSE_WIDTH, pin);
        return -1;
    }
    if (gpioServo(pin, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed on pin %d (pulse %d)\n", pin, pulse_width);
        return -1;
    }
    return 0;
}

int main(void) {
    const int pins[] = {SERVO1_PIN, SERVO2_PIN, SERVO3_PIN, SERVO4_PIN, SERVO5_PIN};
    const int pulse_widths[] = {1000, 1500, 2000, 500, 2500};
    const int num_servos = sizeof(pins) / sizeof(pins[0]);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install signal handlers\n");
    }

    for (int i = 0; i < num_servos && running; i++) {
        if (set_servo_pulse(pins[i], pulse_widths[i]) != 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }
        printf("Moving servo %d to position %d us\n", i + 1, pulse_widths[i]);
        fflush(stdout);
        sleep(SERVO_HOLD_TIME_SEC);
    }

    for (int i = 0; i < num_servos; i++) {
        if (gpioServo(pins[i], 0) < 0) {
            fprintf(stderr, "Warning: failed to stop servo %d\n", i + 1);
        }
    }

    gpioTerminate();
    printf("Servos stopped and GPIO released.\n");
    return EXIT_SUCCESS;
}

