/*
 * Closed-loop DC motor speed control for a miniature vehicle.
 *
 * Hardware: Raspberry Pi 3 Model B+
 *   Motor A: DRV8833 IN1 -> GPIO17 (PWM), IN2 -> GPIO18 (direction)
 *   Motor B: DRV8833 IN3 -> GPIO22 (PWM), IN4 -> GPIO23 (direction)
 *   Encoder A: phase A -> GPIO4, phase B -> GPIO5
 *   Encoder B: phase A -> GPIO6, phase B -> GPIO12
 *
 * Build: gcc -O2 -Wall -o motor_control motor_control.c -lpigpio -lrt
 * Run:   sudo ./motor_control
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define MOTOR_A_PWM   17
#define MOTOR_A_DIR   18
#define MOTOR_B_PWM   22
#define MOTOR_B_DIR   23

#define ENCODER_A_A   4
#define ENCODER_A_B   5
#define ENCODER_B_A   6
#define ENCODER_B_B   12

/* ---- Control parameters ---- */
#define TARGET_RPM     50.0
#define KP             1.0
#define KI             0.1
#define PWM_FREQ_HZ    10000
#define PWM_RANGE      255
#define LOOP_DELAY_US  100000   /* 100 ms */
#define STALL_TIMEOUT  2000     /* 2 s with no encoder ticks */

/* ---- Globals ---- */
static volatile int32_t encoder_a_count = 0;
static volatile int32_t encoder_b_count = 0;
static volatile bool encoder_a_running = true;
static volatile bool encoder_b_running = true;

static volatile sig_atomic_t running = 1;

/* ---- Prototypes ---- */
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *user);
static void encoder_b_isr(int gpio, int level, uint32_t tick, void *user);
static void signal_handler(int sig);
static void stop_motors(void);
static void cleanup(void);
static void set_motor_speed(int motor, int duty);
static double calculate_rpm(int32_t count, double elapsed);
static double calculate_integral(double prev_err, double elapsed);
static double pi_control(double setpoint, double measured, double *integral);

/* ---- ISRs ---- */
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *user)
{
    (void)gpio; (void)level; (void)tick; (void)user;
    if (encoder_a_running) {
        encoder_a_count++;
    }
}

static void encoder_b_isr(int gpio, int level, uint32_t tick, void *user)
{
    (void)gpio; (void)level; (void)tick; (void)user;
    if (encoder_b_running) {
        encoder_b_count++;
    }
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ---- Motor helpers ---- */
static void stop_motors(void)
{
    gpioPWM(MOTOR_A_PWM, 0);
    gpioPWM(MOTOR_B_PWM, 0);
    gpioWrite(MOTOR_A_DIR, 0);
    gpioWrite(MOTOR_B_DIR, 0);
}

static void cleanup(void)
{
    stop_motors();
    gpioTerminate();
}

/* ---- Motor drive: hold one pin high, PWM the other ---- */
static void set_motor_speed(int motor, int duty)
{
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;

    if (motor == 1) {
        gpioWrite(MOTOR_A_DIR, 1);
        gpioPWM(MOTOR_A_PWM, duty);
        gpioWrite(MOTOR_A_DIR, 0);
    } else if (motor == 2) {
        gpioWrite(MOTOR_B_DIR, 1);
        gpioPWM(MOTOR_B_PWM, duty);
        gpioWrite(MOTOR_B_DIR, 0);
    }
}

/* ---- RPM calculation ---- */
static double calculate_rpm(int32_t count, double elapsed)
{
    if (elapsed <= 0.0) return 0.0;
    /* 64 ticks/rev * 60 s/min / (ticks / s) */
    return (60.0 * count) / (elapsed * 64.0);
}

/* ---- Integral clamp ---- */
static double calculate_integral(double prev_err, double elapsed)
{
    double integral = prev_err * (elapsed / 1000000.0); /* 100 ms */
    if (integral > 1000.0) integral = 1000.0;
    if (integral < -1000.0) integral = -1000.0;
    return integral;
}

/* ---- PI controller ---- */
static double pi_control(double setpoint, double measured, double *integral)
{
    double error = setpoint - measured;
    *integral += error;

    double output = KP * error + KI * (*integral);

    /* Anti-windup clamp */
    if (output < 0.0) {
        output = 0.0;
        *integral = 0.0;
    } else if (output > PWM_RANGE) {
        output = PWM_RANGE;
        *integral = (setpoint > measured) ? PWM_RANGE / KP : -PWM_RANGE / KP;
    }

    return output;
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure motor control pins */
    if (gpioSetMode(MOTOR_A_PWM, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_A_DIR, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_PWM, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_DIR, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set motor GPIO modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure encoder pins */
    if (gpioSetMode(ENCODER_A_A, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_A_B, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_B_A, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_B_B, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set encoder GPIO modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM range and frequency */
    if (gpioSetPWMrange(MOTOR_A_PWM, PWM_RANGE) != 0 ||
        gpioSetPWMrange(MOTOR_B_PWM, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(MOTOR_A_PWM, PWM_FREQ_HZ) < 0 ||
        gpioSetPWMfrequency(MOTOR_B_PWM, PWM_FREQ_HZ) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register ISRs (rising edge) */
    if (gpioSetISRFuncEx(ENCODER_A_A, RISING_EDGE, 0, encoder_a_isr, NULL) != 0 ||
        gpioSetISRFuncEx(ENCODER_A_B, RISING_EDGE, 0, encoder_a_isr, NULL) != 0 ||
        gpioSetISRFuncEx(ENCODER_B_A, RISING_EDGE, 0, encoder_b_isr, NULL) != 0 ||
        gpioSetISRFuncEx(ENCODER_B_B, RISING_EDGE, 0, encoder_b_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to register ISRs.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Signal handling */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise controller state */
    double integral_a = 0.0, integral_b = 0.0;
    struct timespec last_a = {0, 0}, last_b = {0, 0};
    clock_gettime(CLOCK_MONOTONIC, &last_a);
    clock_gettime(CLOCK_MONOTONIC, &last_b);

    printf("Motor control started. Target RPM: %.1f\n", TARGET_RPM);

    while (running) {
        /* Snapshot encoder counts */
        int32_t a_count = encoder_a_count;
        int32_t b_count = encoder_b_count;
        encoder_a_count = 0;
        encoder_b_count = 0;

        /* Read current time */
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);

        /* Calculate elapsed since last sample */
        double elapsed_a = (now.tv_sec - last_a.tv_sec) +
                           (now.tv_nsec - last_a.tv_nsec) / 1e9;
        double elapsed_b = (now.tv_sec - last_b.tv_sec) +
                           (now.tv_nsec - last_b.tv_nsec) / 1e9;

        last_a = now;
        last_b = now;

        /* Stall detection */
        if (elapsed_a > STALL_TIMEOUT && a_count == 0) {
            printf("Warning: Encoder A stall detected (no ticks for %.0f s).\n",
                   elapsed_a);
        }
        if (elapsed_b > STALL_TIMEOUT && b_count == 0) {
            printf("Warning: Encoder B stall detected (no ticks for %.0f s).\n",
                   elapsed_b);
        }

        /* Calculate RPM */
        double rpm_a = calculate_rpm(a_count, elapsed_a);
        double rpm_b = calculate_rpm(b_count, elapsed_b);

        /* PI control */
        double duty_a = pi_control(TARGET_RPM, rpm_a, &integral_a);
        double duty_b = pi_control(TARGET_RPM, rpm_b, &integral_b);

        /* Clamp duty cycle */
        if (duty_a < 0.0) duty_a = 0.0;
        if (duty_a > PWM_RANGE) duty_a = PWM_RANGE;
        if (duty_b < 0.0) duty_b = 0.0;
        if (duty_b > PWM_RANGE) duty_b = PWM_RANGE;

        /* Drive motors */
        set_motor_speed(1, (int)duty_a);
        set_motor_speed(2, (int)duty_b);

        /* Print status */
        printf("Motor A: PWM=%.1f RPM=%.1f | Motor B: PWM=%.1f RPM=%.1f\n",
               duty_a, rpm_a, duty_b, rpm_b);

        gpioDelay(LOOP_DELAY_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

