 *   - Turns relay ON  when lux < 50 (dusk).
 *   - Turns relay OFF when lux > 200 (dawn).
 *   - Hysteresis: never toggles more than once per full cycle.
 *   - Logs every reading and state change to chicken_coop_log.txt.
 *   - On any I2C/GPIO/file error: logs the failure and turns the relay off.
 *   - On SIGINT/SIGTERM: turns relay off, closes handles, exits cleanly.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o chicken_coop_lighting chicken_coop_lighting.c \
 *       -lpigpio -lrt
 *   (pigpio daemon must be running, or run with sudo)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define BH1750_ADDR          0x5C          /* ADDR pin -> GND */
#define BH1750_CMD_POWER    0x00          /* Power on / off */
#define BH1750_CMD_MODE     0x01          /* Continuous / one-shot */
#define BH1750_CMD_READ     0x02          /* Read measurement */
#define BH1750_MEAS_MS      180           /* Min measurement time */
#define BH1750_LUX_MAX      65535.0f      /* 16-bit unsigned */

#define RELAY_GPIO          17             /* BCM pin */
#define DUSK_THRESHOLD      50
#define DAWN_THRESHOLD      200
#define POLL_INTERVAL_S     5
#define LOG_FILE            "chicken_coop_log.txt"

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;
static int      g_relay_state = 0;        /* 0 = OFF, 1 = ON */

/* --------------------------- Forward declarations ------------------------ */
static void signal_handler(int sig);
static void log_message(const char *msg);
static void log_reading(int lux, int relay_state);
static int  bh1750_init(void);
static int  bh1750_read_lux(int handle, float *lux_out);
static void control_relay(int state);
static void cleanup(void);

/* ------------------------------- Handlers -------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_message(const char *msg)
{
    if (!g_log_file)
        return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_file, "%s: %s\n", ts, msg);
    fflush(g_log_file);
}

static void log_reading(int lux, int relay_state)
{
    if (!g_log_file)
        return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_file, "%s: Lux = %d, Relay = %s\n",
            ts, lux, relay_state ? "ON" : "OFF");
    fflush(g_log_file);
}

/*
 * Open the I2C bus and configure the BH1750 for continuous mode.
 * Returns 0 on success, -1 on failure.
 */
static int bh1750_init(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, BH1750_ADDR, g_i2c_handle);
        return -1;
    }

    /* Power on */
    if (i2cWriteByteData(g_i2c_handle, BH1750_CMD_POWER, 0x01) < 0) {
        fprintf(stderr, "Error: BH1750 power-on write failed\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    /* Continuous mode */
    if (i2cWriteByteData(g_i2c_handle, BH1750_CMD_MODE, 0x00) < 0) {
        fprintf(stderr, "Error: BH1750 mode set failed\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    /* Allow first measurement to complete */
    gpioDelay(BH1750_MEAS_MS * 1000);
    return 0;
}

/*
 * Read the 16-bit measurement from the BH1750.
 * Returns 0 on success and stores lux in *lux_out; -1 on error.
 */
static int bh1750_read_lux(int handle, float *lux_out)
{
    if (handle < 0 || lux_out == NULL)
        return -1;

    /* Trigger a forced read */
    if (i2cWriteByteData(handle, BH1750_CMD_READ, 0x00) < 0) {
        fprintf(stderr, "Error: BH1750 read trigger failed\n");
        return -1;
    }

    /* Wait for conversion (datasheet: ~120 ms typ, 180 ms max) */
    gpioDelay(BH1750_MEAS_MS * 1000);

    /* Read 2 bytes (MSB first) */
    char buf[2];
    int n = i2cReadDevice(handle, buf, 2);
    if (n != 2) {
        fprintf(stderr, "Error: BH1750 read failed (got %d bytes)\n", n);
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void control_relay(int state)
{
    if (state == g_relay_state)
        return;                       /* Hysteresis: no double toggle */

    if (gpioWrite(RELAY_GPIO, state) < 0) {
        log_message("Error: gpioWrite failed for relay");
        return;
    }
    g_relay_state = state;

    if (state)
        log_message("Relay turned ON");
    else
        log_message("Relay turned OFF");
}

static void cleanup(void)
{
    /* Ensure relay is off */
    if (g_relay_state) {
        gpioWrite(RELAY_GPIO, 0);
        g_relay_state = 0;
    }

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    if (g_log_file) {
        log_message("Program exiting, relay turned off");
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for relay pin %d\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);          /* Relay OFF at startup */

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("Error: cannot open log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise sensor */
    if (bh1750_init() != 0) {
        log_message("Error: BH1750 initialisation failed");
        fclose(g_log_file);
        g_log_file = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Program started: BH1750 monitoring begun");

    int last_relay_state = g_relay_state;

    while (g_running) {
        float lux = 0.0f;

        if (bh1750_read_lux(g_i2c_handle, &lux) == 0) {
            int new_state = (lux < DUSK_THRESHOLD) ? 1 : 0;

            /* Hysteresis: only toggle when outside current state */
            if (new_state != last_relay_state) {
                control_relay(new_state);
                last_relay_state = new_state;
            }

            log_reading((int)lux, g_relay_state);
        } else {
            /* Sensor read failed — safe state: relay off */
            if (g_relay_state) {
                gpioWrite(RELAY_GPIO, 0);
                g_relay_state = 0;
                log_message("Sensor read failed — relay turned off (safe state)");
            }
            log_message("Error: BH1750 read failed");
        }

        /* Sleep in 100 ms slices so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_S * 10 && g_running; i++)
            gpioDelay(100000);          /* 100 ms */
    }

    cleanup();
    return EXIT_SUCCESS;
}

