#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_MS 50
#define LOOP_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int relay_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_state(int state) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    printf("%s Relay is now %s\n", ts, state ? "ON" : "OFF");
    fflush(stdout);
}

static int safe_set_mode(int pin, unsigned mode) {
    if (gpioSetMode(pin, mode) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(int pin, unsigned level) {
    if (gpioWrite(pin, level) < 0) {
        fprintf(stderr, "Error: gpioWrite(%d, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(TOUCH_PIN, PI_INPUT) < 0 ||
        safe_set_mode(RELAY_PIN, PI_OUTPUT) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_write(RELAY_PIN, 0) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch-toggled relay running. Press Ctrl+C to exit.\n");
    fflush(stdout);

    int last_touch = 0;
    int debouncing = 0;

    while (running) {
        int touch = gpioRead(TOUCH_PIN);
        if (touch < 0) {
            fprintf(stderr, "Error: gpioRead(%d) failed\n", TOUCH_PIN);
            break;
        }

        if (touch == 1 && last_touch == 0 && !debouncing) {
            gpioDelay(DEBOUNCE_MS * 1000);
            if (running && gpioRead(TOUCH_PIN) == 1) {
                relay_state = !relay_state;
                if (safe_write(RELAY_PIN, relay_state) < 0) {
                    break;
                }
                log_state(relay_state);
                debouncing = 1;
            }
        } else if (touch == 0 && last_touch == 1 && debouncing) {
            gpioDelay(DEBOUNCE_MS * 1000);
            if (running && gpioRead(TOUCH_PIN) == 0) {
                debouncing = 0;
            }
        }

        last_touch = touch;
        gpioDelay(LOOP_DELAY_US);
    }

    safe_write(RELAY_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

