#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN 27
#define FLOW_THRESHOLD 5.0
#define FLOW_HYSTERESIS 0.5
#define LOG_FILE "water_flow.log"
#define DEBOUNCE_TIMEOUT_SEC 1
#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static int pulse_count = 0;
static int solenoid_state = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *flow_line = NULL;
static struct gpiod_line *solenoid_line = NULL;

static void log_message(const char *message) {
    pthread_mutex_lock(&log_mutex);
    if (log_file) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
        fprintf(log_file, "[%s] %s\n", timestamp, message);
        fflush(log_file);
    }
    pthread_mutex_unlock(&log_mutex);
}

static void flow_isr(void *userdata) {
    (void)userdata;
    struct timespec ts = {0, 100000000}; /* 100 ms */
    static struct timespec last_event = {0, 0};
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);

    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);

    last_event = now;
    nanosleep(&ts, NULL);
}

static double calculate_flow_rate(int pulses, double interval_sec) {
    if (interval_sec <= 0.0) return 0.0;
    return (double)pulses / interval_sec;
}

static void control_solenoid(double flow_rate) {
    if (flow_rate > FLOW_THRESHOLD && solenoid_state == 1) {
        if (gpiod_line_set_value(solenoid_line, 0) < 0) {
            log_message("Error: failed to set solenoid LOW");
            return;
        }
        solenoid_state = 0;
        log_message("Solenoid closed (flow > threshold).");
    } else if (flow_rate < (FLOW_THRESHOLD - FLOW_HYSTERESIS) && solenoid_state == 0) {
        if (gpiod_line_set_value(solenoid_line, 1) < 0) {
            log_message("Error: failed to set solenoid HIGH");
            return;
        }
        solenoid_state = 1;
        log_message("Solenoid opened (flow < hysteresis).");
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (solenoid_line) {
        gpiod_line_set_value(solenoid_line, 1);
        gpiod_line_release(solenoid_line);
        solenoid_line = NULL;
    }
    if (flow_line) {
        gpiod_line_release(flow_line);
        flow_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    pthread_mutex_destroy(&log_mutex);
    pthread_mutex_destroy(&pulse_mutex);
    if (log_file) {
        log_message("Program terminated.");
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }
    log_message("Program started.");

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        fclose(log_file);
        log_file = NULL;
        return EXIT_FAILURE;
    }

    flow_line = gpiod_chip_get_line(chip, FLOW_SENSOR_PIN);
    if (!flow_line) {
        perror("gpiod_chip_get_line (flow)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_rising_edge_events(flow_line, "water_flow_monitor") < 0) {
        perror("gpiod_line_request_rising_edge_events (flow)");
        cleanup();
        return EXIT_FAILURE;
    }

    solenoid_line = gpiod_chip_get_line(chip, SOLENOID_PIN);
    if (!solenoid_line) {
        perror("gpiod_chip_get_line (solenoid)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(solenoid_line, "water_flow_monitor", 1) < 0) {
        perror("gpiod_line_request_output (solenoid)");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_set_value(solenoid_line, 1) < 0) {
        perror("gpiod_line_set_value (solenoid init)");
        cleanup();
        return EXIT_FAILURE;
    }
    solenoid_state = 1;
    log_message("Solenoid initialized to OPEN state.");

    struct sigevent sev;
    memset(&sev, 0, sizeof(sev));
    sev.sigev_notify = SIGEV_THREAD;
    sev.sigev_notify_function = flow_isr;
    sev.sigev_notify_attributes = NULL;
    if (sigevent(SIGEV_THREAD, &sev, NULL) < 0) {
        perror("sigevent");
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        sleep(SAMPLE_INTERVAL_SEC);

        pthread_mutex_lock(&pulse_mutex);
        int pulses = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        double flow_rate = calculate_flow_rate(pulses, (double)SAMPLE_INTERVAL_SEC);
        char msg[128];
        snprintf(msg, sizeof(msg), "Flow rate: %.2f LPM (pulses: %d)", flow_rate, pulses);
        log_message(msg);
        control_solenoid(flow_rate);
    }

    cleanup();
    return EXIT_SUCCESS;
}

