    if (solenoid_line) {
        gpiod_line_set_value(solenoid_line, 1);
        gpiod_line_release(solenoid_line);
        solenoid_line = NULL;
    }
    if (flow_line) {
        gpiod_line_release(flow_line);
        flow_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    pthread_mutex_destroy(&log_mutex);
    pthread_mutex_destroy(&pulse_mutex);
    if (log_file) {
        log_message("Program terminated.");
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }
    log_message("Program started.");

