#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <math.h>
#include <stdbool.h>

#define PORT 12345
#define MAX_CLIENTS 5
#define HX711_DATA_PIN 23
#define HX711_SCK_PIN 24
#define SERVO_PIN 18
#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000
#define SERVO_NEUTRAL_PULSE_WIDTH 1500
#define DISPENSING_DELAY 1
#define HX711_TIMEOUT_ATTEMPTS 1000
#define HX711_TIMEOUT_US 1

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int new_socket = -1;
static int client_socket = -1;
static FILE *log_file = NULL;
static double calibration_factor = 1.0;
static double known_weight = 100.0;

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_SCK_PIN, PI_OUTPUT);
    gpioWrite(HX711_SCK_PIN, 0);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioServo(SERVO_PIN, SERVO_NEUTRAL_PULSE_WIDTH);
    return 0;
}

static int read_hx711(long *value) {
    int i;
    int timeout = 0;
    while (gpioRead(HX711_DATA_PIN) == 1) {
        gpioDelay(1);
        timeout++;
        if (timeout > HX711_TIMEOUT_ATTEMPTS) {
            fprintf(stderr, "HX711 timeout: sensor not ready or absent\n");
            return -1;
        }
    }
    *value = 0;
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK_PIN, 1);
        gpioDelay(1);
        *value = (*value << 1) | (gpioRead(HX711_DATA_PIN) & 1);
        gpioWrite(HX711_SCK_PIN, 0);
        gpioDelay(1);
    }
    gpioWrite(HX711_SCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_SCK_PIN, 0);
    gpioDelay(1);
    if (*value & 0x800000) {
        *value |= 0xFF000000;
    }
    return 0;
}

static double dispense_ingredient(double target_weight) {
    double actual_weight = 0.0;
    long raw_value;
    int pulse_width;

    if (target_weight < 0) {
        fprintf(stderr, "Invalid target weight: %lf\n", target_weight);
        return -1.0;
    }

    pulse_width = (int)lround(SERVO_NEUTRAL_PULSE_WIDTH + (target_weight / known_weight) * (SERVO_MAX_PULSE_WIDTH - SERVO_NEUTRAL_PULSE_WIDTH));
    if (pulse_width < SERVO_MIN_PULSE_WIDTH) pulse_width = SERVO_MIN_PULSE_WIDTH;
    if (pulse_width > SERVO_MAX_PULSE_WIDTH) pulse_width = SERVO_MAX_PULSE_WIDTH;

    gpioServo(SERVO_PIN, pulse_width);
    sleep(DISPENSING_DELAY);

    if (read_hx711(&raw_value) != 0) {
        fprintf(stderr, "Failed to read HX711 after dispensing\n");
        return -1.0;
    }

    actual_weight = (double)raw_value / calibration_factor;
    return actual_weight;
}

static void log_dispensing_event(double target_weight, double actual_weight, const char *error_message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "{\"timestamp\": \"%s\", \"target_weight\": %.2f, \"actual_weight\": %.2f, \"error_message\": \"%s\"}\n",
                timestamp, target_weight, actual_weight, error_message ? error_message : "None");
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

static void *handle_client(void *arg) {
    int sock = *(int *)arg;
    free(arg);
    char buffer[1024];
    double target_weight;
    double actual_weight;
    char error_message[256];

    ssize_t bytes_received = recv(sock, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        perror("recv failed");
        close(sock);
        return NULL;
    }
    buffer[bytes_received] = '\0';
    target_weight = atof(buffer);

    actual_weight = dispense_ingredient(target_weight);
    if (actual_weight < 0) {
        snprintf(error_message, sizeof(error_message), "Dispensing failed");
        log_dispensing_event(target_weight, 0.0, error_message);
        const char *response = "Error: Dispensing failed";
        send(sock, response, strlen(response), 0);
    } else {
        snprintf(error_message, sizeof(error_message), "None");
        log_dispensing_event(target_weight, actual_weight, error_message);
        char response[256];
        snprintf(response, sizeof(response), "Weight dispensed: %.2f grams", actual_weight);
        send(sock, response, strlen(response), 0);
    }
    close(sock);
    return NULL;
}

static void load_configuration(void) {
    FILE *fp = fopen("config.ini", "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: config.ini not found, using defaults\n");
        return;
    }
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        if (strncmp(line, "calibration_factor", 20) == 0) {
            if (sscanf(line, "calibration_factor = %lf", &calibration_factor) != 1) {
                fprintf(stderr, "Warning: Invalid calibration_factor in config.ini\n");
            }
        } else if (strncmp(line, "known_weight", 13) == 0) {
            if (sscanf(line, "known_weight = %lf", &known_weight) != 1) {
                fprintf(stderr, "Warning: Invalid known_weight in config.ini\n");
            }
        }
    }
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    load_configuration();

    if (init_gpio() != 0) {
        return 1;
    }

    log_file = fopen("dispensing_log.json", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket failed");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt failed");
        close(server_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (listen(server_fd, MAX_CLIENTS) < 0) {
        perror("listen failed");
        close(server_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Listening on port %d...\n", PORT);

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t addrlen = sizeof(client_addr);
        new_socket = accept(server_fd, (struct sockaddr *)&client_addr, &addrlen);
        if (new_socket < 0) {
            if (errno == EINTR && !running) {
                break;
            }
            perror("accept failed");
            continue;
        }

        client_socket = new_socket;
        printf("Connection accepted from %s:%d\n", inet_ntoa(client_addr.sin_addr), ntohs(client_addr.sin_port));

        pthread_t thread_id;
        int *new_sock = malloc(sizeof(int));
        if (new_sock == NULL) {
            perror("malloc failed");
            close(new_socket);
            continue;
        }
        *new_sock = new_socket;

        if (pthread_create(&thread_id, NULL, handle_client, (void *)new_sock) < 0) {
            perror("pthread_create failed");
            free(new_sock);
            close(new_socket);
            continue;
        }
        pthread_detach(thread_id);
    }

    if (client_socket >= 0) {
        close(client_socket);
    }
    if (new_socket >= 0) {
        close(new_socket);
    }
    if (server_fd >= 0) {
        close(server_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioServo(SERVO_PIN, SERVO_NEUTRAL_PULSE_WIDTH);
    gpioTerminate();
    printf("Shutdown complete.\n");
    return 0;
}

