#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_PIN 4
#define RELAY_PIN 17
#define DEFAULT_DEBOUNCE_MS 50
#define POLL_DELAY_US 10000

static volatile sig_atomic_t g_running = 1;
static int g_debounce_ms = DEFAULT_DEBOUNCE_MS;
static int g_relay_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_relay_state(int state) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);
    printf("%s Relay: %s\n", timestamp, state ? "ON" : "OFF");
    fflush(stdout);
}

static void toggle_relay(void) {
    g_relay_state = !g_relay_state;
    if (gpioWrite(RELAY_PIN, g_relay_state) != 0) {
        fprintf(stderr, "Error: failed to write relay pin %d\n", RELAY_PIN);
        return;
    }
    log_relay_state(g_relay_state);
}

static void parse_arguments(int argc, char *argv[]) {
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-d") == 0 && i + 1 < argc) {
            g_debounce_ms = atoi(argv[++i]);
            if (g_debounce_ms <= 0) {
                fprintf(stderr, "Warning: invalid debounce time '%s', using default %d ms\n", argv[i], DEFAULT_DEBOUNCE_MS);
                g_debounce_ms = DEFAULT_DEBOUNCE_MS;
            }
        } else {
            fprintf(stderr, "Usage: %s [-d debounce_ms]\n", argv[0]);
            exit(EXIT_FAILURE);
        }
    }
}

int main(int argc, char *argv[]) {
    parse_arguments(argc, argv);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_PIN, PI_INPUT) != 0) {
