#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <termios.h>
#include <fcntl.h>
#include <pigpio.h>

#define SERVO_PIN      18          /* BCM 18, physical pin 12 (hardware PWM) */
#define PWM_FREQ_HZ    50          /* 50 Hz -> 20 ms period */
#define MIN_PULSE_US   500         /* ~0°   */
#define MAX_PULSE_US   2500        /* ~180° */
#define START_ANGLE    90
#define STEP           10

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_terminal_raw(void)
{
    struct termios tty;
    if (tcgetattr(STDIN_FILENO, &tty) != 0) {
        perror("tcgetattr");
        return -1;
    }
    tty.c_lflag &= ~(ICANON | ECHO);
    tty.c_cc[VMIN]  = 1;
    tty.c_cc[VTIME] = 0;
    if (tcsetattr(STDIN_FILENO, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        return -1;
    }
    return 0;
}

static void restore_terminal(void)
{
    struct termios tty;
    if (tcgetattr(STDIN_FILENO, &tty) != 0)
        return;
    tty.c_lflag |= (ICANON | ECHO);
    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 0;
    tcsetattr(STDIN_FILENO, TCSANOW, &tty);
}

static int angle_to_pulse_us(int angle)
{
    if (angle < 0)   angle = 0;
    if (angle > 180) angle = 180;
    return MIN_PULSE_US + (angle * (MAX_PULSE_US - MIN_PULSE_US) / 180);
}

int main(void)
{
    int angle = START_ANGLE;
    int rc = EXIT_SUCCESS;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(SERVO_PIN, PWM_FREQ_HZ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO%d\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(SERVO_PIN, 2000000 / PWM_FREQ_HZ) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO%d\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_terminal_raw() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        rc = EXIT_FAILURE;
        goto cleanup;
    }
    if (sigaction(SIGQUIT, &sa, NULL) != 0) {
        perror("sigaction(SIGQUIT)");
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    printf("Servo control on GPIO%d (50 Hz, 20 ms period).\n", SERVO_PIN);
    printf("Start angle: %d°.  Press '+' to increase, '-' to decrease, 'q' to quit.\n",
           angle);
    fflush(stdout);

    while (g_running) {
        int ch = getchar();
        if (ch == EOF) {
            if (feof(stdin))
                break;
            continue;
        }

        if (ch == '+') {
            angle += STEP;
            if (angle > 180) angle = 180;
        } else if (ch == '-') {
            angle -= STEP;
            if (angle < 0) angle = 0;
        } else if (ch == 'q' || ch == 'Q') {
            break;
        }

        int pw = angle_to_pulse_us(angle);
        if (gpioPWM(SERVO_PIN, pw) != 0) {
            fprintf(stderr, "gpioPWM failed for GPIO%d, pulse %d us\n",
                    SERVO_PIN, pw);
            rc = EXIT_FAILURE;
            break;
        }

        printf("Angle: %d°  Pulse: %d us\n", angle, pw);
        fflush(stdout);
    }

    /* Stop PWM pulses and release the pin */
    gpioPWM(SERVO_PIN, 0);
    gpioWrite(SERVO_PIN, 0);

cleanup:
    gpioTerminate();
    restore_terminal();
    return rc;
}

