#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define HALL_SENSOR_GPIO 17
#define DEBOUNCE_US 2000
#define SAMPLE_INTERVAL_S 5
#define LOG_FILE "motor_rpm.log"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_rpm(double rpm) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%.2f\n", timestamp, rpm) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    unsigned int pulse_count = 0;
    struct timespec last_pulse_time;
    struct timespec current_time;
    double rpm = 0.0;
    int ret;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(HALL_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", HALL_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(HALL_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for GPIO %d\n", HALL_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFunc(HALL_SENSOR_GPIO, RISING_EDGE, DEBOUNCE_US, NULL) != 0) {
        fprintf(stderr, "gpioSetISRFunc failed for GPIO %d\n", HALL_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (clock_gettime(CLOCK_MONOTONIC, &last_pulse_time) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        gpioSetISRFunc(HALL_SENSOR_GPIO, RISING_EDGE, DEBOUNCE_US, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioSetISRFunc(HALL_SENSOR_GPIO, RISING_EDGE, DEBOUNCE_US, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring motor RPM on GPIO %d. Press Ctrl+C to exit.\n", HALL_SENSOR_GPIO);

    while (running) {
        sleep(SAMPLE_INTERVAL_S);

        if (!running) {
            break;
        }

        if (clock_gettime(CLOCK_MONOTONIC, &current_time) != 0) {
            fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
            continue;
        }

        unsigned int elapsed_us = (unsigned int)((current_time.tv_sec - last_pulse_time.tv_sec) * 1000000UL +
                                                  (current_time.tv_nsec - last_pulse_time.tv_nsec) / 1000UL);

        if (elapsed_us >= DEBOUNCE_US) {
            pulse_count++;
            last_pulse_time = current_time;
        }

        rpm = (double)pulse_count / (double)elapsed_us * 60.0;

        if (log_rpm(rpm) != 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        printf("RPM: %.2f\n", rpm);
    }

    printf("\nShutting down...\n");

    gpioSetISRFunc(HALL_SENSOR_GPIO, RISING_EDGE, DEBOUNCE_US, NULL);
    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    return EXIT_SUCCESS;
}

