        return EXIT_FAILURE;
    }

    printf("Monitoring motor RPM on GPIO %d. Press Ctrl+C to exit.\n", HALL_SENSOR_GPIO);

    while (running) {
        sleep(SAMPLE_INTERVAL_S);

        if (!running) {
            break;
        }

        if (clock_gettime(CLOCK_MONOTONIC, &current_time) != 0) {
            fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
            continue;
        }

        unsigned int elapsed_us = (unsigned int)((current_time.tv_sec - last_pulse_time.tv_sec) * 1000000UL +
                                                  (current_time.tv_nsec - last_pulse_time.tv_nsec) / 1000UL);

        if (elapsed_us >= DEBOUNCE_US) {
            pulse_count++;
            last_pulse_time = current_time;
        }

        rpm = (double)pulse_count / (double)elapsed_us * 60.0;

        if (log_rpm(rpm) != 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        printf("RPM: %.2f\n", rpm);
    }

    printf("\nShutting down...\n");

    gpioSetISRFunc(HALL_SENSOR_GPIO, RISING_EDGE, DEBOUNCE_US, NULL);
    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    return EXIT_SUCCESS;
}

