#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_PIN 4
#define RELAY_PIN 17
#define POLL_DELAY_US 50000   /* 50 ms */
#define RELAY_HOLD_S 10       /* hold relay ON for > 10 s */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int safe_set_mode(unsigned gpio, unsigned mode)
{
    if (gpioSetMode(gpio, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", gpio, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned gpio, unsigned level)
{
    if (gpioWrite(gpio, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", gpio, level);
        return -1;
    }
    return 0;
}

int main(void)
{
    int relay_state = 0;
    int touch_held = 0;
    uint32_t hold_start = 0;
    int rc = EXIT_SUCCESS;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(TOUCH_PIN, PI_INPUT) != 0 ||
        safe_set_mode(RELAY_PIN, PI_OUTPUT) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_write(RELAY_PIN, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        safe_write(RELAY_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch-to-relay running. Touch=BCM%d, Relay=BCM%d. Ctrl+C to exit.\n",
           TOUCH_PIN, RELAY_PIN);

    while (running) {
        int touch = gpioRead(TOUCH_PIN);
        if (touch < 0) {
            fprintf(stderr, "Error: gpioRead(%d) failed\n", TOUCH_PIN);
            rc = EXIT_FAILURE;
            break;
        }

        if (touch == 1) {
            if (!touch_held) {
                touch_held = 1;
                hold_start = gpioTick();
                printf("Touch detected; relay %s\n", relay_state ? "ON (hold active)" : "ON");
            } else {
                uint32_t now = gpioTick();
                uint32_t elapsed = now - hold_start;
                if (elapsed >= (uint32_t)(RELAY_HOLD_S * 1000000)) {
                    printf("Hold limit (%ds) reached; forcing relay OFF\n", RELAY_HOLD_S);
                    if (safe_write(RELAY_PIN, 0) != 0) {
                        rc = EXIT_FAILURE;
                        break;
                    }
                    relay_state = 0;
                    touch_held = 0;
                }
            }
        } else {
            touch_held = 0;
        }

        if (safe_write(RELAY_PIN, relay_state) != 0) {
            rc = EXIT_FAILURE;
            break;
        }
        relay_state = !relay_state;

        usleep(POLL_DELAY_US);
    }

    /* Clean shutdown: ensure relay is OFF and release pigpio */
    safe_write(RELAY_PIN, 0);
    gpioTerminate();

    if (rc == EXIT_SUCCESS)
        printf("\nExiting cleanly.\n");

    return rc;
}

