#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN          18
#define DIRECTION_PIN    23
#define FLOW_SENSOR_PIN  24

#define PWM_RANGE        255
#define PWM_FREQ         1000
#define SAMPLE_PERIOD_US 100000
#define LOG_FILE         "flow_log.csv"

static volatile sig_atomic_t g_running = 1;
static volatile int g_pulse_count = 0;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void flow_sensor_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    g_pulse_count++;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set PWM pin %d as output.\n", PWM_PIN);
        return -1;
    }
    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on pin %d.\n", PWM_PIN);
        return -1;
    }
    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on pin %d.\n", PWM_PIN);
        return -1;
    }
    if (gpioPWM(PWM_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize PWM duty cycle on pin %d.\n", PWM_PIN);
        return -1;
    }

    if (gpioSetMode(DIRECTION_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set direction pin %d as output.\n", DIRECTION_PIN);
        return -1;
    }
    if (gpioWrite(DIRECTION_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to write direction pin %d high.\n", DIRECTION_PIN);
        return -1;
    }

    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set flow sensor pin %d as input.\n", FLOW_SENSOR_PIN);
        return -1;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_sensor_isr, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISR on flow sensor pin %d.\n", FLOW_SENSOR_PIN);
        return -1;
    }

    return 0;
}

static double calculate_flow_rate(int pulses, double elapsed_ms) {
    if (elapsed_ms <= 0.0) return 0.0;
    return (pulses / elapsed_ms) * 60.0;
}

static int control_valve(double target_flow_rate) {
    static int last_pulse_count = 0;
    int pulses = g_pulse_count - last_pulse_count;
    last_pulse_count = g_pulse_count;

    double flow_rate = calculate_flow_rate(pulses, (double)SAMPLE_PERIOD_US / 1000.0);

    double error = target_flow_rate - flow_rate;
    int duty_cycle = (int)(100.0 * error);
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    if (gpioPWM(PWM_PIN, duty_cycle) < 0) {
        fprintf(stderr, "Error: failed to set PWM duty cycle to %d.\n", duty_cycle);
        return -1;
    }
    return duty_cycle;
}

static void log_data(FILE *fp, double flow_rate, int valve_position) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000L) + (ts.tv_nsec / 1000000L);
    fprintf(fp, "%ld,%.2f,%d\n", timestamp_ms, flow_rate, valve_position);
    fflush(fp);
}

int main(int argc, char *argv[]) {
    double target_flow_rate = 0.0;

    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                target_flow_rate = atof(optarg);
                if (target_flow_rate <= 0.0) {
                    fprintf(stderr, "Error: target flow rate must be positive.\n");
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s -t <target_flow_rate_L_min>\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: failed to open log file '%s'.\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to install signal handlers.\n");
        fclose(g_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Starting flow control loop. Target flow rate: %.2f L/min\n", target_flow_rate);

    while (g_running) {
        int valve_position = control_valve(target_flow_rate);
        if (valve_position < 0) {
            fprintf(stderr, "Error: valve control failed.\n");
            break;
        }
        log_data(g_log_file, target_flow_rate, valve_position);
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    gpioPWM(PWM_PIN, 0);
    gpioWrite(DIRECTION_PIN, 0);
    gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, NULL, NULL);
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
    printf("Shutdown complete.\n");
    return EXIT_SUCCESS;
}

