#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    100000
#define SPI_BITS         8
#define SPI_MODE         0

#define LOCK_1_PIN      17
#define LOCK_2_PIN      27
#define BUTTON_PIN      22

#define LOG_FILE        "/var/log/door_access.log"
#define UNLOCK_DURATION 5
#define DEBOUNCE_US     50000
#define POLL_DELAY_US   100000
#define MAX_RETRIES     4

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(const char *msg)
{
    if (!g_log_fp) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(g_log_fp, "%s %s\n", ts, msg);
    fflush(g_log_fp);
}

static int spi_xfer(const unsigned char *tx, unsigned char *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = len;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return 0;
}

static int read_rfid(unsigned char *tag)
{
    memset(tag, 0, sizeof(tag));
    if (spi_xfer((unsigned char[4]){0x26, 0x00, 0x00, 0x00}, tag, 10) < 0)
        return -1;
    return 0;
}

static int verify_tag(const unsigned char *tag)
{
    if (tag[0] == 0 && tag[1] == 0 && tag[2] == 0 && tag[3] == 0 &&
        tag[4] == 0 && tag[5] == 0 && tag[6] == 0 && tag[7] == 0 &&
        tag[8] == 0) {
        return 0; /* no tag present */
    }
    /* Simple CRC4 check for the first 4 bytes (placeholder) */
    unsigned char crc = 0;
    for (int i = 0; i < 4; i++) {
        crc ^= tag[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x07;
            else
                crc <<= 1;
        }
    }
    return (crc == 0) ? 1 : 0;
}

static void unlock_doors(void)
{
    gpioWrite(LOCK_1_PIN, 0);
    gpioWrite(LOCK_2_PIN, 0);
    gpioDelay(UNLOCK_DURATION * 1000000);
    gpioWrite(LOCK_1_PIN, 1);
    gpioWrite(LOCK_2_PIN, 1);
}

static void cleanup(void)
{
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    gpioWrite(LOCK_1_PIN, 1);
    gpioWrite(LOCK_2_PIN, 1);
    gpioWrite(BUTTON_PIN, 1);
    if (g_log_fp) {
        log_event("Program terminated.");
        fclose(g_log_fp);
