        in2_pin = MOTOR1_IN2;
    } else if (motor == 2) {
        pwm_pin = MOTOR2_ENB;
        in1_pin = MOTOR2_IN3;
        in2_pin = MOTOR2_IN4;
    } else {
        fprintf(stderr, "Invalid motor number: %d\n", motor);
        return;
    }

    /* Compute duty cycle (0–255) from RPM target */
    float error = TARGET_RPM - rpm;
    float pid_p = KP * error;
    float pid_i = KI * (error + (float)encoder1.count);
    float pid_d = KD * (error - (float)encoder1.count);
    float pid_output = pid_p + pid_i + pid_d;

    int duty = (int)(pid_output * 255.0f);
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;

    gpioPWM(pwm_pin, duty);

    /* Quadrature direction: 1 = CW, -1 = CCW, 0 = brake */
    int dir = (pid_output > 0) ? 1 : -1;
    gpioWrite(in1_pin, dir);
    gpioWrite(in2_pin, dir == 1 ? 0 : 1);
}

static void stop_motor(int motor) {
    int pwm_pin;
    if (motor == 1) pwm_pin = MOTOR1_ENA;
    else if (motor == 2) pwm_pin = MOTOR2_ENB;
    else {
        fprintf(stderr, "Invalid motor number: %d\n", motor);
        return;
    }
    gpioPWM(pwm_pin, 0);
    gpioWrite(MOTOR1_IN1, 0);
    gpioWrite(MOTOR1_IN2, 0);
    gpioWrite(MOTOR2_IN3, 0);
    gpioWrite(MOTOR2_IN4, 0);
}

/* ---- Cleanup ---- */
static void cleanup(void) {
    stop_motor(1);
    stop_motor(2);
    gpioTerminate();
    pthread_mutex_lock(&g_log_mutex);
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    pthread_mutex_unlock(&g_log_mutex);
    pthread_mutex_destroy(&g_log_mutex);
}

/* ---- Main ---- */
int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log = fopen("motor_log.csv", "w");
    if (!g_log) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(g_log, "Timestamp,PID_P,PID_I,PID_D,Speed_RPM\n");
    fflush(g_log);

    /* Configure motor control pins */
    if (gpioSetMode(MOTOR1_ENA, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR1_IN1, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR1_IN2, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_ENB, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_IN3, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_IN4, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set motor GPIO modes\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure encoder pins */
    if (gpioSetMode(ENCODER1_A, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER1_B, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER2_A, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER2_B, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set encoder GPIO modes\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Enable pull-ups on encoder B pins */
    gpioSetPullUpDown(ENCODER1_B, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER2_B, PI_PUD_UP);

    /* Set PWM frequency and range */
    gpioSetPWMfrequency(MOTOR1_ENA, PWM_FREQ_HZ);
    gpioSetPWMfrequency(MOTOR2_ENB, PWM_FREQ_HZ);
    gpioSetPWMrange(MOTOR1_ENA, PWM_RANGE);
    gpioSetPWMrange(MOTOR2_ENB, PWM_RANGE);

    /* Start encoder threads */
    pthread_t t1, t2;
    if (pthread_create(&t1, NULL, encoder_thread, &encoder1) != 0) {
        perror("Failed to create encoder 1 thread");
        cleanup();
        return EXIT_FAILURE;
    }
    if (pthread_create(&t2, NULL, encoder_thread, &encoder2) != 0) {
        perror("Failed to create encoder 2 thread");
        g_running = 0;
        pthread_join(t1, NULL);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Main control loop */
    while (g_running) {
        int a1 = gpioRead(ENCODER1_A);
        int b1 = gpioRead(ENCODER1_B);
        int a2 = gpioRead(ENCODER2_A);
        int b2 = gpioRead(ENCODER2_B);

        if (a1 < 0 || b1 < 0 || a2 < 0 || b2 < 0) {
            fprintf(stderr, "Warning: encoder read error\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /* Decode quadrature and compute RPM */
        int dir1 = (a1 == b1) ? 1 : -1;
        int dir2 = (a2 == b2) ? 1 : -1;
        int count1 = encoder1.count;
        int count2 = encoder2.count;
        float rpm1 = (float)count1 / 60.0f;
        float rpm2 = (float)count2 / 60.0f;

        /* PID and speed logging */
        float pid_p1 = KP * (TARGET_RPM - rpm1);
        float pid_i1 = KI * (TARGET_RPM - rpm1 + (float)count1);
        float pid_d1 = KD * (TARGET_RPM - rpm1 - (float)count1);
        float pid_p2 = KP * (TARGET_RPM - rpm2);
        float pid_i2 = KI * (TARGET_RPM - rpm2 + (float)count2);
        float pid_d2 = KD * (TARGET_RPM - rpm2 - (float)count2);
        log_data(pid_p1, pid_i1, pid_d1, rpm1);
        log_data(pid_p2, pid_i2, pid_d2, rpm2);

        /* Set motor speeds */
        set_motor_speed(1, rpm1);
        set_motor_speed(2, rpm2);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Graceful shutdown */
    g_running = 0;
    pthread_join(t1, NULL);
    pthread_join(t2, NULL);
    cleanup();
    return EXIT_SUCCESS;
}

