#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define MPR121_ADDR 0x2A
#define I2C_BUS "/dev/i2c-1"
#define RELAY_GPIO 17
#define LOG_FILE "relay_log.txt"
#define POLL_DELAY_US 50000

/* MPR121 Register Addresses */
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR 0x5E
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5C
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_NHDT 0x33
#define MPR121_NCLT 0x34
#define MPR121_FDLT 0x35
#define MPR121_TOUCHTH_0 0x41
#define MPR121_RELEASETH_0 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_ECR 0x5E
#define MPR121_SOFTRESET 0x80

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(i2c_fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *value) {
    if (write(i2c_fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(i2c_fd, value, 1) != 1) {
        return -1;
    }
    return 0;
}

static int mpr121_init(void) {
    if (i2c_write_reg(MPR121_SOFTRESET, 0x63) < 0) {
        fprintf(stderr, "Error: MPR121 soft reset failed.\n");
        return -1;
    }
    gpioDelay(10000);

    if (i2c_write_reg(MPR121_MHDR, 0x01) < 0) return -1;
    if (i2c_write_reg(MPR121_NHDR, 0x01) < 0) return -1;
    if (i2c_write_reg(MPR121_NCLR, 0x0E) < 0) return -1;
    if (i2c_write_reg(MPR121_FDLR, 0x00) < 0) return -1;
    if (i2c_write_reg(MPR121_MHDF, 0x01) < 0) return -1;
    if (i2c_write_reg(MPR121_NHDF, 0x01) < 0) return -1;
    if (i2c_write_reg(MPR121_NCLF, 0x01) < 0) return -1;
    if (i2c_write_reg(MPR121_FDLF, 0x00) < 0) return -1;
    if (i2c_write_reg(MPR121_NHDT, 0x00) < 0) return -1;
    if (i2c_write_reg(MPR121_NCLT, 0x00) < 0) return -1;
    if (i2c_write_reg(MPR121_FDLT, 0x00) < 0) return -1;

    for (int i = 0; i < 12; i++) {
        if (i2c_write_reg(MPR121_TOUCHTH_0 + 2 * i, 0x0C) < 0) return -1;
        if (i2c_write_reg(MPR121_RELEASETH_0 + 2 * i, 0x0A) < 0) return -1;
    }

    if (i2c_write_reg(MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (i2c_write_reg(MPR121_CONFIG1, 0x10) < 0) return -1;
    if (i2c_write_reg(MPR121_CONFIG2, 0x20) < 0) return -1;

    if (i2c_write_reg(MPR121_ECR, 0x00) < 0) return -1;
    gpioDelay(1000);

    if (i2c_write_reg(MPR121_ECR, 0x0C) < 0) return -1;
    gpioDelay(1000);

    return 0;
}

static int read_touch_status(uint16_t *touch_status) {
    uint8_t low, high;
    if (i2c_read_reg(MPR121_TOUCHSTATUS_L, &low) < 0) {
        return -1;
    }
    if (i2c_read_reg(MPR121_TOUCHSTATUS_H, &high) < 0) {
        return -1;
    }
    *touch_status = (uint16_t)((high << 8) | low);
    return 0;
}

static void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s Relay state: %s\n", timestamp, state ? "HIGH" : "LOW");
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        i2c_write_reg(MPR121_ECR, 0x00);
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed.\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    int last_state = -1;
    while (running) {
        uint16_t touch_status;
        if (read_touch_status(&touch_status) < 0) {
            fprintf(stderr, "Error: Failed to read touch status.\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        int current_state = (touch_status != 0) ? 1 : 0;
        if (current_state != last_state) {
            gpioWrite(RELAY_GPIO, current_state);
            log_relay_state(current_state);
            last_state = current_state;
        }

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return 0;
}

