#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE1_GPIO 17
#define VALVE2_GPIO 18
#define VALVE1_DURATION_MS 500
#define VALVE2_DURATION_MS 1000
#define VALVE1_PAUSE_S 5
#define VALVE2_PAUSE_S 10
#define LOG_FILE "valve_log.txt"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_event(FILE *fp, const char *event) {
    if (!fp) return;
    time_t t = time(NULL);
    struct tm tm_info;
    char timestamp[32];
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }
    if (fprintf(fp, "%s: %s\n", timestamp, event) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed\n");
    }
}

static void activate_valve(int gpio, int duration_ms) {
    if (gpioWrite(gpio, 1) != 0) {
        fprintf(stderr, "Failed to set GPIO %d HIGH\n", gpio);
        return;
    }
    log_event(g_log_fp, "Valve activated");
    gpioDelay(duration_ms * 1000);
    if (gpioWrite(gpio, 0) != 0) {
        fprintf(stderr, "Failed to set GPIO %d LOW\n", gpio);
    }
    log_event(g_log_fp, "Valve deactivated");
}

static void sleep_seconds(int seconds) {
    sleep(seconds);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
