#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define MIN_DUTY 0
#define MAX_DUTY 255
#define MIN_DURATION_MS 50
#define MAX_DURATION_MS 200
#define MIN_STEPS 5
#define MAX_STEPS 15
#define PWM_RANGE 255

static volatile sig_atomic_t shutdown_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    shutdown_flag = 1;
}

typedef struct {
    int duty1;
    int duty2;
    int duration_ms;
} MotorStep;

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", MOTOR1_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", MOTOR2_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(MOTOR1_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range for GPIO %d\n", MOTOR1_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(MOTOR2_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range for GPIO %d\n", MOTOR2_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void generate_random_pattern(MotorStep *pattern, int *pattern_length) {
    *pattern_length = rand() % (MAX_STEPS - MIN_STEPS + 1) + MIN_STEPS;
    for (int i = 0; i < *pattern_length; i++) {
        pattern[i].duty1 = rand() % (MAX_DUTY - MIN_DUTY + 1) + MIN_DUTY;
        pattern[i].duty2 = rand() % (MAX_DUTY - MIN_DUTY + 1) + MIN_DUTY;
        pattern[i].duration_ms = rand() % (MAX_DURATION_MS - MIN_DURATION_MS + 1) + MIN_DURATION_MS;
    }
}

static void play_pattern(const MotorStep *pattern, int pattern_length) {
    for (int i = 0; i < pattern_length; i++) {
        if (shutdown_flag) break;

        if (gpioPWM(MOTOR1_PIN, pattern[i].duty1) != 0) {
            fprintf(stderr, "Warning: gpioPWM failed on GPIO %d\n", MOTOR1_PIN);
        }
        if (gpioPWM(MOTOR2_PIN, pattern[i].duty2) != 0) {
            fprintf(stderr, "Warning: gpioPWM failed on GPIO %d\n", MOTOR2_PIN);
        }

        gpioDelay(pattern[i].duration_ms * 1000);
    }
}

static void stop_motors(void) {
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);
}

int main(void) {
    srand(time(NULL));

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    MotorStep *pattern = (MotorStep *)malloc(MAX_STEPS * sizeof(MotorStep));
    if (pattern == NULL) {
        fprintf(stderr, "Error: memory allocation failed for pattern array\n");
        gpioTerminate();
        return 1;
    }

    while (!shutdown_flag) {
        int pattern_length = 0;
        generate_random_pattern(pattern, &pattern_length);
        play_pattern(pattern, pattern_length);
    }

    stop_motors();
    free(pattern);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return 0;
}

