#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

#define CALIBRATION_FILE "calibration.txt"
#define WEIGHT_LOG_FILE "weight_log.txt"

#define NUM_CALIBRATION_READINGS 100
#define WEIGHT_THRESHOLD 10.0
#define READ_TIMEOUT_US 500000
#define SAMPLE_INTERVAL_US 500000

static double scale_factor = 1.0;
static double offset = 0.0;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(void) {
    int data = 0;
    int timeout = 0;

    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    while (gpioRead(HX711_DATA_PIN) == 1) {
        gpioDelay(10);
        timeout += 10;
        if (timeout >= READ_TIMEOUT_US) {
            fprintf(stderr, "Error: HX711 read timeout (sensor not ready or disconnected).\n");
            return -1;
        }
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1);
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data |= 1;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1);
    }

    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    if (data & 0x800000) {
        data |= ~0xFFFFFF;
    }

    return data;
}

static double calibrate_hx711(void) {
    double sum = 0.0;
    int valid_readings = 0;

    printf("Calibrating HX711 (ensure no weight on load cell)...\n");
    for (int i = 0; i < NUM_CALIBRATION_READINGS; i++) {
        int raw = read_hx711();
        if (raw == -1) {
            fprintf(stderr, "Calibration failed: sensor read timeout.\n");
            return -1.0;
        }
        sum += raw;
        valid_readings++;
        gpioDelay(100000);
    }

    if (valid_readings == 0) {
        fprintf(stderr, "Calibration failed: no valid readings.\n");
        return -1.0;
    }

    double average = sum / valid_readings;
    offset = average;
    printf("Calibration complete. Offset: %.2f\n", offset);
    return 0.0;
}

static double calculate_weight(int raw_value) {
    return (raw_value - offset) / scale_factor;
}

static int control_solenoid(double weight) {
    if (weight > WEIGHT_THRESHOLD) {
        gpioWrite(SOLENOID_PIN, 1);
        printf("Weight %.2f kg exceeds threshold %.2f kg. Solenoid engaged.\n", weight, WEIGHT_THRESHOLD);
        return 1;
    } else {
        gpioWrite(SOLENOID_PIN, 0);
        printf("Weight %.2f kg below threshold %.2f kg. Solenoid disengaged.\n", weight, WEIGHT_THRESHOLD);
        return 0;
    }
}

static int load_calibration_data(void) {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Could not open calibration file '%s'. Using defaults.\n", CALIBRATION_FILE);
        return -1;
    }

    if (fscanf(fp, "%lf %lf", &scale_factor, &offset) != 2) {
        fprintf(stderr, "Warning: Invalid calibration data. Using defaults.\n");
        scale_factor = 1.0;
        offset = 0.0;
    } else {
        printf("Calibration data loaded: scale=%.6f, offset=%.6f\n", scale_factor, offset);
    }

    fclose(fp);
    return 0;
}

static int save_calibration_data(void) {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration file for writing.\n");
        return -1;
    }

    fprintf(fp, "%.6f %.6f\n", scale_factor, offset);
    fclose(fp);
    printf("Calibration data saved to %s\n", CALIBRATION_FILE);
    return 0;
}

static int log_weight_data(double weight) {
    FILE *fp = fopen(WEIGHT_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file '%s'.\n", WEIGHT_LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Weight: %.2f kg\n", s, weight);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioWrite(SOLENOID_PIN, 0);

    if (load_calibration_data() != 0) {
        scale_factor = 1.0;
        offset = 0.0;
    }

    if (calibrate_hx711() != 0) {
        fprintf(stderr, "Error: HX711 calibration failed.\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Weight monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double weight = calculate_weight(raw_value);
        control_solenoid(weight);

        if (log_weight_data(weight) != 0) {
            fprintf(stderr, "Warning: Failed to log weight data.\n");
        }

        if (save_calibration_data() != 0) {
            fprintf(stderr, "Warning: Failed to save calibration data.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return 0;
}

