#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DT_PIN 23
#define HX711_SCK_PIN 24
#define SOLENOID_PIN 17

#define WEIGHT_THRESHOLD 100.0
#define LOCK_DURATION 5
#define LOG_FILE "stock_events.txt"
#define READ_TIMEOUT_US 1000000
#define SAMPLE_DELAY_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static int read_hx711(void) {
    int32_t data = 0;
    int timeout = 0;

    gpioWrite(HX711_SCK_PIN, 0);
    gpioDelay(1);

    while (gpioRead(HX711_DT_PIN)) {
        gpioDelay(10);
        timeout += 10;
        if (timeout >= READ_TIMEOUT_US) {
            log_event("Error: HX711 data line stuck high (timeout)");
            return -1;
        }
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK_PIN, 1);
        gpioDelay(1);
        data = data << 1;
        if (gpioRead(HX711_DT_PIN)) {
            data |= 1;
        }
        gpioWrite(HX711_SCK_PIN, 0);
        gpioDelay(1);
    }

    gpioWrite(HX711_SCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_SCK_PIN, 0);
    gpioDelay(1);

    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

static double convert_to_grams(int32_t raw_value) {
    return (double)raw_value / 1000.0;
}

static int activate_solenoid(int duration_seconds) {
    if (gpioWrite(SOLENOID_PIN, 1) != 0) {
        log_event("Error: Failed to activate solenoid");
        return -1;
    }
    gpioDelay(duration_seconds * 1000000);
    if (gpioWrite(SOLENOID_PIN, 0) != 0) {
        log_event("Error: Failed to deactivate solenoid");
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(HX711_DT_PIN, PI_INPUT) != 0 ||
        gpioSetMode(HX711_SCK_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(HX711_SCK_PIN, 0);
    gpioWrite(SOLENOID_PIN, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Program started");

    while (running) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            log_event("Error: HX711 read failed");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        double weight = convert_to_grams(raw_value);
        char log_message[128];
        snprintf(log_message, sizeof(log_message), "Weight: %.2f g", weight);
        log_event(log_message);

        if (weight < WEIGHT_THRESHOLD) {
            log_event("Weight below threshold, activating solenoid");
            if (activate_solenoid(LOCK_DURATION) != 0) {
                log_event("Error: Solenoid activation failed");
            }
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    log_event("Program terminated");
    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

