#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27
#define CALIBRATION_FILE "calibration.txt"
#define SECURITY_LOG_FILE "security.log"
#define THRESHOLD_WEIGHT 5.0
#define TIMEOUT_US 100000
#define SAMPLE_DELAY_US 100000
#define LOCK_DURATION_S 5

static volatile sig_atomic_t running = 1;
static double calibration_factor = 1.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int32_t *out) {
    if (gpioWrite(HX711_CLOCK_PIN, 0) < 0) return -1;
    gpioDelay(1);

    uint32_t data = 0;
    for (int i = 0; i < 24; i++) {
        if (gpioWrite(HX711_CLOCK_PIN, 1) < 0) return -1;
        gpioDelay(2);
        if (gpioWrite(HX711_CLOCK_PIN, 0) < 0) return -1;
        gpioDelay(1);
        data <<= 1;
        if (gpioRead(HX711_DATA_PIN) == 1) data |= 1;
    }

    if (gpioWrite(HX711_CLOCK_PIN, 1) < 0) return -1;
    gpioDelay(2);
    if (gpioWrite(HX711_CLOCK_PIN, 0) < 0) return -1;
    gpioDelay(1);

    if (data & 0x800000) data |= 0xFF000000;
    *out = (int32_t)data;
    return 0;
}

static int calibrate_hx711(void) {
    printf("Place a known weight on the load cell and press Enter to calibrate.\n");
    while (getchar() != '\n') { /* drain */ }

    int32_t raw = 0;
    if (read_hx711(&raw) != 0) {
        fprintf(stderr, "Error: failed to read HX711 during calibration.\n");
        return -1;
    }
    printf("Raw value: %d\n", raw);

    printf("Enter the known weight in kg: ");
    fflush(stdout);
    double known_weight = 0.0;
    if (scanf("%lf", &known_weight) != 1 || known_weight <= 0.0) {
        fprintf(stderr, "Invalid input. Calibration aborted.\n");
        return -1;
    }
    while (getchar() != '\n') { /* drain */ }

    calibration_factor = known_weight / (double)raw;
    printf("Calibration factor: %.6f\n", calibration_factor);

    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (!fp) {
        perror("Error opening calibration file");
        return -1;
    }
    fprintf(fp, "%.6f\n", calibration_factor);
    fclose(fp);
    return 0;
}

static double get_weight(void) {
    int32_t raw = 0;
    if (read_hx711(&raw) != 0) {
        fprintf(stderr, "Error reading HX711.\n");
        return -1.0;
    }
    return (double)raw / calibration_factor;
}

static int engage_solenoid(void) {
    if (gpioWrite(SOLENOID_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to engage solenoid.\n");
        return -1;
    }
    printf("Solenoid engaged.\n");
    return 0;
}

static int disengage_solenoid(void) {
    if (gpioWrite(SOLENOID_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to disengage solenoid.\n");
        return -1;
    }
    printf("Solenoid disengaged.\n");
    return 0;
}

static int log_security_event(double weight) {
    FILE *fp = fopen(SECURITY_LOG_FILE, "a");
    if (!fp) {
        perror("Error opening security log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r failed");
        fclose(fp);
        return -1;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Weight: %.2f kg\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, weight);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction failed");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(HX711_DATA_PIN, PI_INPUT) < 0 ||
        gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO modes.\n");
        gpioTerminate();
        return 1;
    }

    gpioWrite(SOLENOID_PIN, 0);

    if (calibrate_hx711() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Starting weight monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        double weight = get_weight();
        if (weight < 0.0) {
            fprintf(stderr, "Error reading weight. Retrying...\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        printf("Weight: %.2f kg\n", weight);

        if (weight > THRESHOLD_WEIGHT) {
            printf("Threshold exceeded! Engaging solenoid lock.\n");
            if (engage_solenoid() == 0) {
                log_security_event(weight);
                for (int i = 0; i < LOCK_DURATION_S * 10 && running; i++) {
                    gpioDelay(100000);
                }
                disengage_solenoid();
            }
        }

