#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_PIN 16
#define RELAY_PIN 20
#define LOG_FILE "relay_events.log"
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Read the KY-022 sensor.
 * Returns 1 if an obstacle is detected (active-low), 0 if clear, or -1 on error.
 */
static int read_sensor(int pin) {
    int level = gpioRead(pin);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead failed on pin %d (rc=%d)\n", pin, level);
        return -1;
    }
    return (level == 0) ? 1 : 0;
}

/*
 * Toggle the relay state.
 * Returns the new relay state (0 or 1) on success, -1 on error.
 */
static int toggle_relay(int pin) {
    int current = gpioRead(pin);
    if (current < 0) {
        fprintf(stderr, "Error: gpioRead failed on relay pin %d (rc=%d)\n", pin, current);
        return -1;
    }
    int new_state = (current == 0) ? 1 : 0;
    if (gpioWrite(pin, new_state) < 0) {
        fprintf(stderr, "Error: gpioWrite failed on relay pin %d (rc=%d)\n", pin, new_state);
        return -1;
    }
    return new_state;
}

/*
 * Log a relay state change with an ISO-8601 timestamp.
 * Returns 0 on success, -1 on error.
 */
static int log_event(const char *filename, int relay_state) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("Error getting time");
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("Error converting time");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Relay state: %s\n", timestamp, relay_state ? "ON" : "OFF") < 0) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }
    return 0;
}

int main(void) {
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error installing SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error installing SIGTERM handler");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure sensor pin as input */
    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for sensor pin %d\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure relay pin as output */
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for relay pin %d\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure relay starts in a known OFF state */
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite failed to initialise relay pin %d\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring KY-022 sensor on GPIO%d, relay on GPIO%d. Press Ctrl+C to exit.\n",
           SENSOR_PIN, RELAY_PIN);

    int relay_state = 0;
    int last_sensor_value = 0;  /* 0 = no obstacle (assumed OFF) */

    while (running) {
        int sensor_value = read_sensor(SENSOR_PIN);
        if (sensor_value < 0) {
            /* Sensor read error — log and continue */
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* KY-022 is active-low: LOW (0) means obstacle detected */
        if (sensor_value == 1) {
            if (last_sensor_value == 0) {
                /* Obstacle just appeared — switch relay to opposite state */
                relay_state = toggle_relay(RELAY_PIN);
                if (relay_state < 0) {
                    /* Relay toggle failed — log and continue */
                    gpioDelay(POLL_DELAY_US);
                    continue;
                }
                if (log_event(LOG_FILE, relay_state) != 0) {
                    fprintf(stderr, "Warning: failed to log relay state change\n");
                }
            }
        } else {
            /* No obstacle — ensure relay is OFF */
            if (relay_state != 0) {
                if (toggle_relay(RELAY_PIN) == 0) {
                    relay_state = 0;
                    if (log_event(LOG_FILE, relay_state) != 0) {
                        fprintf(stderr, "Warning: failed to log relay state change\n");
                    }
                }
            }
        }

        last_sensor_value = sensor_value;
        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown: ensure relay is OFF and release pigpio resources */
    printf("\nShutting down...\n");
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

