/*
 * Timed Watering System — Raspberry Pi 3 Model B+
 * Valve: Parker Hannifin Series 9 General Purpose Miniature Solenoid Valve
 *   (12 V, 1.6 W) driven via an external N-channel MOSFET or relay module.
 * GPIO: BCM 18 (active-low, default low = valve off)
 *
 * Build:  gcc -O2 -Wall -Wextra -o watering watering.c
 * Run:    sudo ./watering   (root needed for /dev/gpiochip0 on older kernels)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <pigpio.h>

#define GPIO_PIN        18          /* BCM 18 — active-low MOSFET gate/relay */
#define CONFIG_FILE     "watering.conf"
#define DEFAULT_DURATION 60          /* seconds */
#define MIN_DURATION    1
#define MAX_DURATION    3600

static volatile sig_atomic_t g_stop = 0;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_stop = 1;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Configuration file parsing                                          */
/* ------------------------------------------------------------------ */
static int read_configuration(const char *filename, int *duration_out)
{
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening configuration file '%s': %s\n",
                filename, strerror(errno));
        return -1;
    }

    char line[256];
    int  found = 0;

    while (fgets(line, sizeof(line), fp) != NULL) {
        /* Strip trailing newline / carriage return */
        line[strcspn(line, "\r\n")] = '\0';

        /* Skip blank / comment lines */
        if (line[0] == '#' || line[0] == '\0')
            continue;

        /* Expect "duration=<seconds>" */
        char *eq = strchr(line, '=');
        if (eq == NULL) {
            fprintf(stderr, "Configuration file: malformed line (no '='): '%s'\n", line);
            fclose(fp);
            return -1;
        }

        *eq = '\0';
        char *key   = line;
        char *value = eq + 1;

        if (strcmp(key, "duration") != 0) {
            fprintf(stderr, "Configuration file: unknown key '%s'\n", key);
            fclose(fp);
            return -1;
        }

        char *endptr = NULL;
        long val = strtol(value, &endptr, 10);

        if (endptr == value || *endptr != '\0') {
            fprintf(stderr, "Configuration file: invalid duration value '%s'\n", value);
            fclose(fp);
            return -1;
        }

        if (val < MIN_DURATION || val > MAX_DURATION) {
            fprintf(stderr, "Configuration file: duration %ld out of range [%d, %d]\n",
                    val, MIN_DURATION, MAX_DURATION);
            fclose(fp);
            return -1;
        }

        *duration_out = (int)val;
        found = 1;
        break;
    }

    if (fclose(fp) != 0)
        perror("Warning: error closing configuration file");

    if (!found) {
        fprintf(stderr, "Configuration file: 'duration' not found\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO setup                                                          */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed (code %d)\n", gpioInitialise());
        return -1;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", GPIO_PIN);
        gpioTerminate();
        return -1;
    }

    /* Active-low: default is OFF (valve closed) */
    if (gpioWrite(GPIO_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite(%d, 0) failed\n", GPIO_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Valve control                                                       */
/* ------------------------------------------------------------------ */
static int control_valve(int duration_seconds)
{
    printf("Activating valve for %d seconds...\n", duration_seconds);
    fflush(stdout);

    if (gpioWrite(GPIO_PIN, 1) != 0) {
        fprintf(stderr, "gpioWrite(%d, 1) failed — valve activation failed\n", GPIO_PIN);
        return -1;
    }

    /*
     * sleep() is interrupted by signals; if interrupted it returns the
     * remaining seconds, which we treat as a request to stop early.
     */
    unsigned int remaining = (unsigned int)duration_seconds;
    while (remaining > 0 && !g_stop) {
        unsigned int chunk = remaining;
        if (chunk > 60)
            chunk = 60;          /* 1-second granularity so signals are
                                   noticed promptly */

        unsigned int slept = sleep(chunk);
        if (slept == 0 || slept == chunk) {
            remaining = 0;
        } else {
            remaining = (unsigned int)(remaining - slept);
        }
    }

    if (g_stop) {
        fprintf(stderr, "\nInterrupted — shutting down early.\n");
        return -1;
    }

    if (gpioWrite(GPIO_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite(%d, 0) failed — valve deactivation failed\n", GPIO_PIN);
        return -1;
    }

    printf("Valve deactivated.\n");
    fflush(stdout);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup_gpio(void)
{
    /* Ensure valve is off before releasing pigpio */
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int duration = DEFAULT_DURATION;

    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    if (read_configuration(CONFIG_FILE, &duration) != 0) {
        fprintf(stderr, "Using default watering duration: %d seconds\n",
                duration);
    } else {
        printf("Watering duration configured: %d seconds\n", duration);
    }

    if (initialize_gpio() != 0)
        return EXIT_FAILURE;

    if (control_valve(duration) != 0) {
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    cleanup_gpio();
    return EXIT_SUCCESS;
}

