 * Raspberry Pi Zero W - Line Following Robot
 * Sensor: Keywish 3-Way IR Tracking Sensor
 *   Left   sensor -> GPIO4  (BCM)
 *   Middle sensor -> GPIO17 (BCM)
 *   Right  sensor -> GPIO27 (BCM)
 * Motor driver: L298N
 *   Left  motor PWM -> GPIO22 (BCM)
 *   Right motor PWM -> GPIO23 (BCM)
 *   Left  motor IN  -> GPIO24 (BCM)
 *   Right motor IN -> GPIO25 (BCM)
 *
 * Sensor outputs are active-low digital signals (0 = track detected, 1 = no track).
 * Control law:
 *   - Middle sensor low  -> drive straight  (left = right = 150)
 *   - Left  sensor low   -> turn right    (left  = 75, right = 150)
 *   - Right sensor low   -> turn left     (left = 150, right = 75)
 *   - No sensor low      -> stop
 *
 * Log file: trace_log.txt (ISO-8601 timestamps, CSV: timestamp,left,right,s0,s1,s2)
 */

#define LEFT_SENSOR_PIN    4
#define MIDDLE_SENSOR_PIN  17
#define RIGHT_SENSOR_PIN   27

#define LEFT_MOTOR_PIN     22
#define RIGHT_MOTOR_PIN    23
#define MOTOR_EN1_PIN      24
#define MOTOR_EN2_PIN      25

#define PWM_FREQUENCY      1000   /* Hz */
#define PWM_RANGE          255
#define LOOP_DELAY_US      10000  /* 10 ms */

#define SPEED_BASE         150
#define SPEED_TURN_HALF    75

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a sensor pin; returns 0 or 1, or -1 on error                   */
/* ------------------------------------------------------------------ */
static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on pin %d: %s\n",
                pin, pigpio_error(v));
        return -1;
    }
    return v;
}

/* ------------------------------------------------------------------ */
/* Set motor speed (0-255) on the given pin                            */
/* ------------------------------------------------------------------ */
static int set_motor_speed(int pin, int speed)
{
    if (speed < 0) speed = 0;
    if (speed > PWM_RANGE) speed = PWM_RANGE;

    int rc = gpioPWM(pin, speed);
    if (rc < 0) {
        fprintf(stderr, "gpioPWM failed on pin %d: %s\n",
                pin, pigpio_error(rc));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Stop both motors (PWM = 0)                                          */
/* ------------------------------------------------------------------ */
static void stop_motors(void)
{
    set_motor_speed(LEFT_MOTOR_PIN, 0);
    set_motor_speed(RIGHT_MOTOR_PIN, 0);
}

/* ------------------------------------------------------------------ */
/* Log one data row to the CSV file                                     */
/* ------------------------------------------------------------------ */
static void log_data(int s0, int s1, int s2, int left, int right)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return;
    }

    struct tm tm_buf;
    struct tm *tm = localtime_r(&now, &tm_buf);
    if (tm == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(g_log_file, "%s,%d,%d,%d,%d,%d\n",
                ts, s0, s1, s2, left, right) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
    } else {
        fflush(g_log_file);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    stop_motors();

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor pins as inputs ---- */
    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set sensor pin modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Configure motor pins as outputs ---- */
    if (gpioSetMode(LEFT_MOTOR_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(RIGHT_MOTOR_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_EN1_PIN,  PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_EN2_PIN,  PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set motor pin modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Set PWM frequency on motor pins ---- */
    if (gpioSetPWMfrequency(LEFT_MOTOR_PIN,  PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(RIGHT_MOTOR_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Set PWM range (0-255) on motor pins ---- */
    if (gpioSetPWMrange(LEFT_MOTOR_PIN,  PWM_RANGE) < 0 ||
        gpioSetPWMrange(RIGHT_MOTOR_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Ensure motors are stopped at startup ---- */
    stop_motors();

    /* ---- Open log file ---- */
    g_log_file = fopen("trace_log.txt", "a");
    if (g_log_file == NULL) {
        perror("fopen(\"trace_log.txt\")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Write CSV header if file is empty ---- */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,left,right,s0,s1,s2\n");
        fflush(g_log_file);
    }

    /* ---- Install signal handler for graceful shutdown ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Line follower running. Press Ctrl+C to stop.\n");

    /* ---- Main control loop ---- */
    while (g_running) {
        int s0 = read_sensor(LEFT_SENSOR_PIN);
        int s1 = read_sensor(MIDDLE_SENSOR_PIN);
        int s2 = read_sensor(RIGHT_SENSOR_PIN);

        if (s0 < 0 || s1 < 0 || s2 < 0) {
            fprintf(stderr, "Sensor read error; stopping motors.\n");
            stop_motors();
            break;
        }

        /*
         * Active-low sensor logic:
         *   s0 = 0  -> left  sensor detects track
         *   s1 = 0  -> middle sensor detects track
         *   s2 = 0  -> right sensor detects track
         */
        int left_speed  = 0;
        int right_speed = 0;

        if (s0 == 0 && s1 == 0 && s2 == 0) {
            /* No track detected anywhere: stop */
        } else if (s0 == 0 && s1 == 0) {
            /* Only left sensor sees track: turn right */
            left_speed  = SPEED_TURN_HALF;
            right_speed = SPEED_BASE;
        } else if (s0 == 0 && s2 == 0) {
            /* Only right sensor sees track: turn left */
            left_speed  = SPEED_BASE;
            right_speed = SPEED_TURN_HALF;
        } else {
            /* Middle sensor sees track: drive straight */
            left_speed  = SPEED_BASE;
            right_speed = SPEED_BASE;
        }

        if (set_motor_speed(LEFT_MOTOR_PIN,  left_speed)  < 0 ||
            set_motor_speed(RIGHT_MOTOR_PIN, right_speed) < 0) {
            fprintf(stderr, "Motor PWM write failed; stopping.\n");
            stop_motors();
            break;
        }

        log_data(s0, s1, s2, left_speed, right_speed);

        gpioDelay(LOOP_DELAY_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

