#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x5C
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150
#define MEASUREMENT_DELAY_MS 180
#define LOG_FILE "grow_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int pigpio_initialized = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld: %s\n", timestamp, ts.tv_nsec / 1000000, message);
    fclose(fp);
}

static int read_lux(int handle, int *lux_out) {
    if (handle < 0) {
        log_message("Error: Invalid I2C handle in read_lux.");
        return -1;
    }
    if (!lux_out) {
        log_message("Error: lux_out is NULL in read_lux.");
        return -1;
    }

    // Send measurement command (no register address needed for BH1750)
    // The BH1750 auto-increments its internal register pointer when the master
    // writes a byte without specifying a register, so writing 0x10 starts a one-time
    // measurement that returns the lux value in the next read.
    uint8_t cmd = 0x10;
    if (write(handle, &cmd, 1) != 1) {
        log_message("Error: Failed to send measurement command to BH1750.");
        return -1;
    }

    // Wait for measurement to complete
    usleep(MEASUREMENT_DELAY_MS * 1000);

    // Read 2 bytes of result
    uint8_t buf[2];
    if (read(handle, buf, 2) != 2) {
        log_message("Error: Failed to read lux value from BH1750.");
        return -1;
    }

    *lux_out = (buf[0] << 8) | buf[1];
    return 0;
}

static void control_relay(int gpio, int state) {
    if (gpio_initialized) {
        gpioWrite(gpio, state);
    }
}

int main(void) {
    // Register signal handler for graceful shutdown
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    pigpio_initialized = 1;

    // Set relay GPIO as output and ensure it starts OFF
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    // Open I2C bus
    i2c_handle = open(I2C_BUS, O_RDWR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        log_message("Error: Failed to open I2C bus.");
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_handle, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        log_message("Error: Failed to set I2C slave address.");
        close(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Grow lamp controller started. Press Ctrl+C to exit.\n");
    log_message("Program started.");

    int last_relay_state = -1; // Unknown initial state

    while (running) {
        int lux = 0;
        if (read_lux(i2c_handle, &lux) == 0) {
            char log_buf[128];
            snprintf(log_buf, sizeof(log_buf), "Lux: %d", lux);
            log_message(log_buf);

            if (lux < LUX_THRESHOLD) {
                if (last_relay_state != 1) {
                    control_relay(RELAY_GPIO, 1);
                    last_relay_state = 1;
                    log_message("Relay turned ON (lux below threshold).");
                }
            } else {
                if (last_relay_state != 0) {
                    control_relay(RELAY_GPIO, 0);
                    last_relay_state = 0;
                    log_message("Relay turned OFF (lux above threshold).");
                }
            }
        } else {
            log_message("Error: Failed to read lux value.");
        }

        usleep(100000); // 100 ms delay between readings
    }

    // Cleanup
    printf("\nShutting down...\n");
    log_message("Program exiting.");

    if (i2c_handle >= 0) {
        close(i2c_handle);
    }
    if (pigpio_initialized) {
        gpioWrite(RELAY_GPIO, 0);
        gpioTerminate();
    }

    return 0;
}

