static int set_servo(int pulse_width)
{
    if (pulse_width < SERVO_MIN_SAFE || pulse_width > SERVO_MAX_SAFE) {
        fprintf(stderr, "Error: pulse width %d out of safe range [%d, %d]\n",
                pulse_width, SERVO_MIN_SAFE, SERVO_MAX_SAFE);
        return -1;
    }
    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pin %d\n", SERVO_PIN);
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    /* Stop the servo PWM signal and release the GPIO pin. */
    gpioServo(SERVO_PIN, 0);
    gpioSetMode(SERVO_PIN, PI_INPUT);
    gpioTerminate();
}

int main(void)
{
    int rc;

    /* Initialize pigpio library. */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", rc);
        return EXIT_FAILURE;
    }

    /* Configure button pins as inputs with pull-up resistors. */
    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", LOCK_BUTTON);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(UNLOCK_BUTTON, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", UNLOCK_BUTTON);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", LOCK_BUTTON);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", UNLOCK_BUTTON);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure servo pin as output and set initial position (unlocked). */
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", SERVO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (set_servo(SERVO_UNLOCKED) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }
    printf("Door unlocked. Press the lock button to lock the door.\n");
    printf("Press Ctrl+C to exit.\n");

    /* Install SIGINT handler for clean shutdown. */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Main loop: poll buttons with debounce. */
    while (g_running) {
        if (gpioRead(LOCK_BUTTON) == 0) {
            /* Debounce: wait 100 ms then re-read. */
            gpioDelay(100000); /* 100 ms in microseconds */
            if (gpioRead(LOCK_BUTTON) == 0) {
                printf("Locking door...\n");
                fflush(stdout);
                if (set_servo(SERVO_LOCKED) < 0) {
                    fprintf(stderr, "Error: failed to set servo to locked position.\n");
                } else {
                    printf("Door locked.\n");
                }
                fflush(stdout);
                /* Wait for button release to avoid repeated locks. */
                while (g_running && gpioRead(LOCK_BUTTON) == 0) {
                    gpioDelay(10000);
                }
            }
        }
        if (gpioRead(UNLOCK_BUTTON) == 0) {
            gpioDelay(100000);
            if (gpioRead(UNLOCK_BUTTON) == 0) {
                printf("Unlocking door...\n");
                fflush(stdout);
                if (set_servo(SERVO_UNLOCKED) < 0) {
                    fprintf(stderr, "Error: failed to set servo to unlocked position.\n");
                } else {
                    printf("Door unlocked.\n");
                }
                fflush(stdout);
                while (g_running && gpioRead(UNLOCK_BUTTON) == 0) {
                    gpioDelay(10000);
                }
            }
        }
        gpioDelay(10000); /* 10 ms poll interval */
    }

    /* Clean shutdown. */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

