#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define PULSE_DURATION_MOTOR1_MS 200
#define PULSE_DURATION_MOTOR2_MS 300

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    /* Ensure motors are off before releasing lines */
    gpioWrite(MOTOR1_PIN, 0);
    gpioWrite(MOTOR2_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins as outputs */
    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", MOTOR1_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", MOTOR2_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure motors are off at start */
    if (gpioWrite(MOTOR1_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise GPIO%d low.\n", MOTOR1_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(MOTOR2_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise GPIO%d low.\n", MOTOR2_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Main loop: pulse motor 1, then motor 2, repeatedly */
    while (running) {
        if (gpioWrite(MOTOR1_PIN, 1) != 0) {
            fprintf(stderr, "Error: failed to write HIGH to GPIO%d.\n", MOTOR1_PIN);
            break;
        }
        gpioDelay(PULSE_DURATION_MOTOR1_MS * 1000); /* microseconds */
        if (!running) break;

        if (gpioWrite(MOTOR1_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to write LOW to GPIO%d.\n", MOTOR1_PIN);
            break;
        }

        if (gpioWrite(MOTOR2_PIN, 1) != 0) {
            fprintf(stderr, "Error: failed to write HIGH to GPIO%d.\n", MOTOR2_PIN);
            break;
        }
        gpioDelay(PULSE_DURATION_MOTOR2_MS * 1000);
        if (!running) break;

        if (gpioWrite(MOTOR2_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to write LOW to GPIO%d.\n", MOTOR2_PIN);
            break;
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

