#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <fcntl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN    27
#define ZMQ_BIND_ADDR    "tcp://*:5555"
#define ZMQ_CONNECT_ADDR "tcp://localhost:5555"
#define SOUND_ALERT_TOPIC "SOUND_ALERTS"
#define POLL_DELAY_US    10000
#define ALARM_DURATION_S 1

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_message(const char *msg) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] %s\n", ts, msg);
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT) < 0) {
        log_message("Failed to set sound sensor pin mode");
        return -1;
    }

    if (gpioSetMode(ALARM_LED_PIN, PI_OUTPUT) < 0) {
        log_message("Failed to set alarm LED pin mode");
        return -1;
    }

    if (gpioWrite(ALARM_LED_PIN, 0) < 0) {
        log_message("Failed to initialise alarm LED state");
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void) {
    gpioWrite(ALARM_LED_PIN, 0);
    gpioTerminate();
}

static int init_zmq(void) {
    int context_new = zmq_ctx_new();
    if (context_new == NULL) {
        log_message("ZeroMQ context creation failed");
        return -1;
    }

    int socket_new = zmq_socket(context_new, ZMQ_SUB);
    if (socket_new == NULL) {
        log_message("ZeroMQ socket creation failed");
        zmq_ctx_destroy(context_new);
        return -1;
    }

    int linger = 0;
    if (zmq_setsockopt(socket_new, ZMQ_LINGER, &linger, sizeof(linger)) != 0) {
        log_message("Failed to set ZMQ linger option");
        zmq_close(socket_new);
        zmq_ctx_destroy(context_new);
        return -1;
    }

    if (zmq_setsockopt(socket_new, ZMQ_SUBSCRIBE, SOUND_ALERT_TOPIC, strlen(SOUND_ALERT_TOPIC)) != 0) {
        log_message("Failed to set ZMQ subscription topic");
        zmq_close(socket_new);
        zmq_ctx_destroy(context_new);
        return -1;
    }

    if (zmq_bind(socket_new, ZMQ_BIND_ADDR) != 0) {
        log_message("Failed to bind ZMQ socket");
        zmq_close(socket_new);
        zmq_ctx_destroy(context_new);
        return -1;
    }

    return socket_new;
}

static void publish_sound_alert(void) {
    int context = zmq_ctx_new();
    if (context == NULL) {
        log_message("Failed to create context for publish socket");
        return;
    }

    int socket = zmq_socket(context, ZMQ_PUSH);
    if (socket == NULL) {
        log_message("Failed to create publish socket");
        zmq_ctx_destroy(context);
        return;
    }

    int linger = 0;
    if (zmq_setsockopt(socket, ZMQ_LINGER, &linger, sizeof(linger)) != 0) {
        log_message("Failed to set ZMQ linger option for publish socket");
        zmq_close(socket);
        zmq_ctx_destroy(context);
        return;
    }

    if (zmq_connect(socket, ZMQ_CONNECT_ADDR) != 0) {
        log_message("Failed to connect publish socket");
        zmq_close(socket);
        zmq_ctx_destroy(context);
        return;
    }

    char message[128];
    snprintf(message, sizeof(message), "SOUND_DETECTED");

    if (zmq_send(socket, message, strlen(message), 0) != 0) {
        log_message("Failed to send message via publish socket");
    }

    zmq_close(socket);
    zmq_ctx_destroy(context);
}

static void trigger_alarm(void) {
    if (gpioWrite(ALARM_LED_PIN, 1) < 0) {
        log_message("Failed to turn on alarm LED");
        return;
    }

    sleep(ALARM_DURATION_S);

    if (gpioWrite(ALARM_LED_PIN, 0) < 0) {
        log_message("Failed to turn off alarm LED");
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <sound_sensor|alarm_node>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *mode = argv[1];

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    if (strcmp(mode, "sound_sensor") == 0) {
        log_message("Starting sound sensor mode");

        while (g_running) {
            int sound_level = gpioRead(SOUND_SENSOR_PIN);
            if (sound_level < 0) {
                log_message("Failed to read sound sensor pin");
                break;
            }

            if (sound_level == 0) {
                log_message("Sound detected!");
                publish_sound_alert();
            }

            gpioDelay(POLL_DELAY_US);
        }

        cleanup_gpio();
    } else if (strcmp(mode, "alarm_node") == 0) {
        log_message("Starting alarm node mode");

        int socket_new = init_zmq();
        if (socket_new == -1) {
            cleanup_gpio();
            return EXIT_FAILURE;
        }

        while (g_running) {
            zmq_msg_t message;
            int rc = zmq_msg_init_size(&message, 16);
            if (rc != 0) {
                log_message("Failed to init zmq_msg");
                break;
            }

            rc = zmq_msg_recv(&message, socket_new, 0);
            if (rc == -1) {
                if (errno == EINTR) {
                    continue;
                }
                log_message("Failed to receive message from ZMQ socket");
                break;
            }

            char body[16];
            rc = zmq_msg_copy(&message, body, 16);
            if (rc == -1) {
                log_message("Failed to copy message body");
                break;
            }
            body[rc] = '\0';

            log_message(body);
            trigger_alarm();
        }

        zmq_close(socket_new);
        zmq_ctx_destroy(NULL);
        cleanup_gpio();
    } else {
        fprintf(stderr, "Invalid mode: %s\n", mode);
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

