            log_message(body);
            trigger_alarm();
        }

        zmq_close(socket_new);
        zmq_ctx_destroy(NULL);
        cleanup_gpio();
    } else {
        fprintf(stderr, "Invalid mode: %s\n", mode);
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

