    (void)mosq;
    (void)userdata;
    syslog(LOG_WARNING, "MQTT disconnected (rc=%d)", rc);
}

static void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    (void)mosq;
    (void)userdata;
    if (message->payloadlen > 0) {
        char payload[128];
        int len = message->payloadlen < (int)sizeof(payload) - 1 ? message->payloadlen : (int)sizeof(payload) - 1;
        memcpy(payload, message->payload, len);
        payload[len] = '\0';
        syslog(LOG_INFO, "Received MQTT message: %s", payload);
    }
}

static int mqtt_publish(const char *topic, const char *payload) {
    int rc = mosquitto_publish(mqtt_client, NULL, topic, (int)strlen(payload), payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish failed: %s", mosquitto_strerror(rc));
    }
    return rc;
}

static void cleanup(void) {
    if (mqtt_client) {
        mosquitto_disconnect(mqtt_client);
        mosquitto_destroy(mqtt_client);
        mqtt_client = NULL;
    }
    mosquitto_lib_cleanup();
    closelog();
}

int main(void) {
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set signal handlers");
        closelog();
        return 1;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "gpioInitialise failed");
        closelog();
        return 1;
    }

    gpioSetMode(IR_GPIO, PI_INPUT);
    gpioSetPullUpDown(IR_GPIO, PI_PUD_UP);

    if (gpioSetAlertFuncEx(IR_GPIO, ir_callback, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO alert function");
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_lib_init();
    mqtt_client = mosquitto_new(NULL, true, NULL);
    if (!mqtt_client) {
        syslog(LOG_ERR, "Failed to create MQTT client");
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_connect_callback_set(mqtt_client, mqtt_connect_callback);
    mosquitto_disconnect_callback_set(mqtt_client, mqtt_disconnect_callback);
    mosquitto_message_callback_set(mqtt_client, mqtt_message_callback);

    int rc = mosquitto_connect(mqtt_client, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(rc));
        cleanup();
        gpioTerminate();
        return 1;
    }

    rc = mosquitto_loop_start(mqtt_client);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT loop_start failed: %s", mosquitto_strerror(rc));
        cleanup();
        gpioTerminate();
        return 1;
    }

    syslog(LOG_INFO, "IR decoder started (GPIO%d -> MQTT %s:%d)", IR_GPIO, MQTT_HOST, MQTT_PORT);

    while (running) {
        pthread_mutex_lock(&frame_mutex);
        bool frame_ready = nec_frame_ready;
        nec_frame_ready = false;
        pthread_mutex_unlock(&frame_mutex);

        if (frame_ready) {
            uint32_t addr, cmd;
            if (decode_nec(pulses, pulse_count, &addr, &cmd) == 0) {
                char json[256];
                snprintf(json, sizeof(json),
                    "{\"address\":0x%08X,\"command\":0x%08X,\"topic\":\"ir/decoded\"}",
                    addr, cmd);
                pthread_mutex_lock(&mqtt_mutex);
                if (mqtt_publish(MQTT_TOPIC, json) != MOSQ_ERR_SUCCESS) {
                    syslog(LOG_ERR, "Failed to publish MQTT message");
                }
                pthread_mutex_unlock(&mqtt_mutex);
                syslog(LOG_INFO, "Decoded NEC: 0x%08X 0x%08X", addr, cmd);
            } else {
                syslog(LOG_WARNING, "NEC decode failed");
            }
        }

        if (pulse_count > 0) {
            pulse_count = 0;
        }
        usleep(10000);
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    gpioTerminate();
    return 0;
}

