#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x5C
#define BH1750_CMD_CONT_HIGH_RES 0x10
#define CONV_TIME_MS   180
#define NUM_SENSORS    4
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define SAMPLE_PERIOD_S 1

static volatile sig_atomic_t g_terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/*
 * Read lux from a single BH1750 at the given I2C address.
 * Returns 0 on success and stores the lux value in *out_lux;
 * returns -1 on any I2C or conversion error (lux set to NaN).
 */
static int read_bh1750(int fd, uint8_t addr, float *out_lux)
{
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        *out_lux = (float)NAN;
        return -1;
    }

    /* Issue one-byte command, then wait for conversion to complete. */
    uint8_t cmd = BH1750_CMD_CONT_HIGH_RES;
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "write(0x%02X): %s\n", addr, strerror(errno));
        *out_lux = (float)NAN;
        return -1;
    }

    usleep(CONV_TIME_MS * 1000);

    uint8_t buf[2];
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != 2) {
        fprintf(stderr, "read(0x%02X): expected 2 bytes, got %zd (%s)\n",
                addr, n, n < 0 ? strerror(errno) : "short read");
        *out_lux = (float)NAN;
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *out_lux = (float)raw / 1.2f;
    return 0;
}

static void format_multicast(float lux[NUM_SENSORS], int valid[NUM_SENSORS],
                             char *buf, size_t buflen)
{
    size_t off = 0;
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (valid[i]) {
            int idx = snprintf(buf + off, buflen - off, "%d,%.2f;", i + 1, lux[i]);
            if (idx < 0 || (size_t)idx >= buflen - off) {
                /* Prevent buffer overflow; truncate and add a sentinel. */
                buf[off] = '\0';
                break;
            }
            off += idx;
        } else {
            /* Sensor not ready yet; mark as invalid in the list. */
            off += snprintf(buf + off, buflen - off, "%d,NaN;", i + 1);
        }
    }
}

static int send_multicast(const char *data)
{
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        return -1;
    }

    int ttl = 1;
    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("setsockopt(IP_MULTICAST_TTL)");
        close(sockfd);
        return -1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(MULTICAST_PORT);
    if (inet_pton(AF_INET, MULTICAST_ADDR, &addr.sin_addr) != 1) {
        fprintf(stderr, "inet_pton(%s): invalid address\n", MULTICAST_ADDR);
        close(sockfd);
        return -1;
    }

    if (sendto(sockfd, data, strlen(data), 0,
               (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("sendto");
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

int main(void)
{
    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open(" I2C_BUS ")");
        return EXIT_FAILURE;
    }

    float lux[NUM_SENSORS];
    int valid[NUM_SENSORS];

    for (int i = 0; i < NUM_SENSORS; i++) {
        lux[i] = (float)NAN;
        valid[i] = 0;
    }

    /* --- Main acquisition loop --- */
    while (!g_terminate) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            valid[i] = read_bh1750(i2c_fd, (uint8_t)i, &lux[i]);
        }

        char data[256];
        format_multicast(lux, valid, data, sizeof(data));

        if (send_multicast(data) < 0) {
            fprintf(stderr, "Failed to send multicast packet\n");
        }

        sleep(SAMPLE_PERIOD_S);
    }

    /* --- Cleanup --- */
    close(i2c_fd);
    return EXIT_SUCCESS;
}

