#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define AWM7300V_ADDR   0x48
#define LOG_FILE        "airflow_log.txt"
#define MAX_RETRIES     3
#define RETRY_DELAY_MS  100
#define SAMPLE_PERIOD_S 1

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_zero_len(int fd)
{
    /* Issue a zero-length write to generate a start condition. */
    if (write(fd, NULL, 0) < 0) {
        if (errno == ENXIO) {
            fprintf(stderr, "Sensor not present on bus (ENXIO).\n");
        } else {
            fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        }
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        if (errno == ENXIO) {
            fprintf(stderr, "Sensor not present on bus (ENXIO).\n");
        } else {
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        }
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C read short: got %zd of %zu bytes.\n", n, len);
        return -1;
    }
    return 0;
}

static int read_awm7300v(int fd, float *flow_out)
{
    uint8_t buf[2];
    int rc;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        rc = i2c_read_bytes(fd, buf, sizeof(buf));
        if (rc == 0) {
            uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
            /* AWM7300V: 14-bit flow data in bits [15:2]. */
            uint16_t flow_14bit = raw & 0x3FFF;
            *flow_out = (float)flow_14bit / 10.0f;
            return 0;
        }
        if (attempt < MAX_RETRIES - 1) {
            usleep(RETRY_DELAY_MS * 1000);
        }
    }
    return -1;
}

static int log_flow_rate(FILE *fp, float flow_rate)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed.\n");
        return -1;
    }
    if (fprintf(fp, "%s, Flow Rate: %.2f SLPM\n", ts, flow_rate) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, AWM7300V_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                AWM7300V_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("AWM7300V airflow logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD_S);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float flow_rate;

        if (i2c_write_zero_len(g_i2c_fd) < 0) {
            /* Bus error or sensor absent — skip this sample. */
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        if (read_awm7300v(g_i2c_fd, &flow_rate) < 0) {
            fprintf(stderr, "Failed to read flow rate after %d retries.\n",
                    MAX_RETRIES);
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        if (log_flow_rate(g_log_fp, flow_rate) < 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down cleanly...\n");

    if (g_log_fp != NULL) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    return EXIT_SUCCESS;
}

