/*
 * AS7341 Plant Health Monitor — Raspberry Pi 3 Model B+
 *
 * Reads 10 spectral channels from an Adafruit AS7341 on /dev/i2c-1 every 5 s,
 * computes a simplified lux approximation, and logs timestamped CSV data
 * to spectral_log.csv.
 *
 * Wiring:
 *   AS7341 SDA  -> GPIO2 (pin 3)
 *   AS7341 SCL  -> GPIO3 (pin 5)
 *   AS7341 VDD  -> 3.3 V
 *   AS7341 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o spectral_monitor spectral_monitor.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- AS7341 register definitions (datasheet) ---- */
#define AS7341_I2C_ADDR        0x5C

#define AS7341_ENABLE          0x80
#define AS7341_ATIME           0x81
#define AS7341_WTIME           0x83
#define AS7341_CFG6            0x77
#define AS7341_CFG7            0x78
#define AS7341_CFG8            0x79
#define AS7341_CFG9            0x7A
#define AS7341_ID              0x12
#define AS7341_STATUS          0x13
#define AS7341_CDATAL          0x14
#define AS7341_CDATAH          0x15
#define AS7341_FDATAL          0x16
#define AS7341_FDATAH          0x17
#define AS7341_NDATAL          0x18
#define AS7341_NDATAH          0x19
#define AS7341_PDATA           0x1A

#define AS7341_ENABLE_PON      0x01
#define AS7341_ENABLE_SP_EN    0x02
#define AS7341_ENABLE_AEN      0x04
#define AS7341_ENABLE_AVALID   0x08

#define AS7341_ID_VALUE        0x44   /* 'D' in ASCII */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ---- Helpers ---- */

static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        /* Put sensor in shutdown mode before closing */
        if (ioctl(g_i2c_fd, I2C_SLAVE, AS7341_I2C_ADDR) == 0) {
            (void)i2c_smbus_write_byte_data(g_i2c_fd, AS7341_ENABLE, 0x00);
        }
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/*
 * Write a byte to an 8-bit register.
 * Returns 0 on success, -1 on error.
 */
static int reg_write8(int fd, uint8_t reg, uint8_t value)
{
    if (ioctl(fd, I2C_SLAVE, AS7341_I2C_ADDR) < 0) {
        fprintf(stderr, "I2C_SLAVE ioctl failed: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_smbus_write_byte_data(fd, reg, value) < 0) {
        fprintf(stderr, "reg_write8(0x%02X, 0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a byte from an 8-bit register.
 * Returns the byte (0–255) on success, -1 on error.
 */
static int reg_read8(int fd, uint8_t reg)
{
    if (ioctl(fd, I2C_SLAVE, AS7341_I2C_ADDR) < 0) {
        fprintf(stderr, "I2C_SLAVE ioctl failed: %s\n", strerror(errno));
        return -1;
    }
    int v = i2c_smbus_read_byte_data(fd, reg);
    if (v < 0) {
        fprintf(stderr, "reg_read8(0x%02X) failed: %s\n", reg, strerror(errno));
    }
    return v;
}

/*
 * Read a 16-bit little-endian register pair.
 * Returns 0 on success, -1 on error.
 */
static int reg_read16(int fd, uint8_t reg_lsb, uint16_t *out)
{
    int lsb = reg_read8(fd, reg_lsb);
    if (lsb < 0)
        return -1;
    int msb = reg_read8(fd, reg_lsb + 1);
    if (msb < 0)
        return -1;
    *out = (uint16_t)((msb << 8) | lsb);
    return 0;
}

/*
 * Initialize the AS7341: verify ID, power on, configure SMUX, enable spectral
 * measurement, and wait for the first conversion to complete.
 * Returns 0 on success, -1 on error.
 */
static int as7341_init(int fd)
{
    int id = reg_read8(fd, AS7341_ID);
    if (id < 0) {
        fprintf(stderr, "Cannot read AS7341 ID register.\n");
        return -1;
    }
    if (id != AS7341_ID_VALUE) {
        fprintf(stderr, "AS7341 ID mismatch: got 0x%02X, expected 0x%02X.\n",
                id, AS7341_ID_VALUE);
        return -1;
    }
    printf("AS7341 detected (ID = 0x%02X).\n", id);

    if (reg_write8(fd, AS7341_ENABLE, AS7341_ENABLE_PON) < 0)
        return -1;
    usleep(10000);  /* 10 ms power-on delay */

    /*
     * SMUX configuration (CFG6, CFG7, CFG8, CFG9) — typical
     * broadband/clear/NIR setup.  Adjust per your specific
     * photodiode/filter combination.
     */
    if (reg_write8(fd, AS7341_CFG6, 0x00) < 0) return -1;
    if (reg_write8(fd, AS7341_CFG7, 0x00) < 0) return -1;
    if (reg_write8(fd, AS7341_CFG8, 0x00) < 0) return -1;
    if (reg_write8(fd, AS7341_CFG9, 0x00) < 0) return -1;

    if (reg_write8(fd, AS7341_ENABLE,
                   AS7341_ENABLE_PON | AS7341_ENABLE_SP_EN) < 0)
        return -1;

    /* Wait for the first conversion to complete (AVALID bit set) */
    for (int i = 0; i < 20; i++) {
        int status = reg_read8(fd, AS7341_STATUS);
