        usleep(10000);
    }
    return 0;
}

/*
 * Read all 10 spectral channels (F1–F8, Clear, NIR) and compute a
 * simplified lux approximation.
 * Returns 0 on success, -1 on error.
 */
static int as7341_read_spectral(int fd, float *lux_out)
{
    uint16_t f1, f2, f3, f4, f5, f6, f7, f8, clear, nir;

    if (reg_read16(fd, AS7341_CDATAL, &f1) < 0) return -1;
    if (reg_read16(fd, AS7341_FDATAL, &f2) < 0) return -1;
    if (reg_read16(fd, AS7341_NDATAL, &f3) < 0) return -1;
    if (reg_read16(fd, AS7341_PDATA,   &f4) < 0) return -1;
    if (reg_read16(fd, AS7341_CDATAL, &clear) < 0) return -1;
    if (reg_read16(fd, AS7341_FDATAL, &nir)  < 0) return -1;
    if (reg_read16(fd, AS7341_NDATAL, &f5)  < 0) return -1;
    if (reg_read16(fd, AS7341_CDATAL, &f6)  < 0) return -1;
    if (reg_read16(fd, AS7341_FDATAL, &f7)  < 0) return -1;
    if (reg_read16(fd, AS7341_NDATAL, &f8)  < 0) return -1;

    /*
     * Simplified lux approximation (placeholder — real apps use
     * calibrated curves or the datasheet's integral-normalized
     * algorithm).
     */
    float sum = f1 + f2 + f3 + f4 + clear + nir + f5 + f6 + f7 + f8;
    *lux_out = (sum / 10.0f) * 100.0f;
    return 0;
}

/*
 * Append a timestamped CSV line to the log file.
 * Returns 0 on success, -1 on error.
 */
static int log_data(FILE *fp, float lux)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%.2f\n", ts, lux) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen("spectral_log.csv", "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open spectral_log.csv: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,lux\n");
        fflush(g_log_fp);
    }

    /* ---- Initialize sensor ---- */
    if (as7341_init(g_i2c_fd) < 0) {
        fprintf(stderr, "AS7341 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging spectral data every 5 s. Press Ctrl+C to stop.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        float lux;
        if (as7341_read_spectral(g_i2c_fd, &lux) < 0) {
            fprintf(stderr, "Sensor read error — continuing.\n");
        } else {
            printf("Lux: %.2f\n", lux);
            if (log_data(g_log_fp, lux) < 0) {
                fprintf(stderr, "Logging failed — continuing.\n");
            }
        }
        sleep(5);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

