#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define DEFAULT_I2C_ADDRESS 0x50
#define DEFAULT_SAMPLING_INTERVAL 1
#define DEFAULT_OUTPUT_FILENAME "seismic_data.csv"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define ERROR_LOG_FILENAME "seismic_error.log"

static volatile sig_atomic_t program_running = 1;
static int i2c_fd = -1;
static FILE *csv_file = NULL;
static const char *output_filename = DEFAULT_OUTPUT_FILENAME;

typedef struct {
    float x;
    float y;
    float z;
} AccelerationData;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    FILE *error_file = fopen(ERROR_LOG_FILENAME, "a");
    if (error_file != NULL) {
        fprintf(error_file, "%s: %s\n", timestamp, message);
        fclose(error_file);
    } else {
        fprintf(stderr, "%s: %s\n", timestamp, message);
    }
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, buf, 2) == 2) return 0;
        log_error("I2C write failed, retrying...");
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *value) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, &reg, 1) != 1) {
            log_error("I2C write (reg select) failed, retrying...");
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        uint8_t buf[2];
        if (read(fd, buf, 2) != 2) {
            log_error("I2C read failed, retrying...");
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        *value = (int16_t)((buf[0] << 8) | buf[1]);
        return 0;
    }
    return -1;
}

static int initialize_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        log_error("Failed to open /dev/i2c-1");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        log_error("Failed to set I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

static int read_acceleration_data(int fd, AccelerationData *data) {
    int16_t raw_x, raw_y, raw_z;
    if (i2c_read_reg16(fd, 0x02, &raw_x) < 0) return -1;
    if (i2c_read_reg16(fd, 0x04, &raw_y) < 0) return -1;
    if (i2c_read_reg16(fd, 0x06, &raw_z) < 0) return -1;

    data->x = (float)raw_x / 1000.0f;
    data->y = (float)raw_y / 1000.0f;
    data->z = (float)raw_z / 1000.0f;
    return 0;
}

static int log_data_to_csv(AccelerationData data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
