    if (fprintf(csv_file, "%s,%.3f,%.3f,%.3f\n", timestamp, data.x, data.y, data.z) < 0) {
        log_error("Failed to write to CSV file");
        return -1;
    }
    fflush(csv_file);
    return 0;
}

static void cleanup(void) {
    if (csv_file != NULL) {
        fflush(csv_file);
        fclose(csv_file);
        csv_file = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(int argc, char *argv[]) {
    int i2c_address = DEFAULT_I2C_ADDRESS;
    int sampling_interval = DEFAULT_SAMPLING_INTERVAL;

    int opt;
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 0);
                break;
            case 'i':
                sampling_interval = atoi(optarg);
                if (sampling_interval <= 0) {
                    fprintf(stderr, "Invalid sampling interval. Using default.\n");
                    sampling_interval = DEFAULT_SAMPLING_INTERVAL;
                }
                break;
            case 'f':
                output_filename = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i sampling_interval] [-f output_filename]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = initialize_i2c(i2c_address);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    csv_file = fopen(output_filename, "a");
    if (csv_file == NULL) {
        log_error("Failed to open CSV file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,x_g,y_g,z_g\n");
        fflush(csv_file);
    }

    printf("Starting seismic data acquisition...\n");
    printf("I2C Address: 0x%02X\n", i2c_address);
    printf("Sampling Interval: %d seconds\n", sampling_interval);
    printf("Output File: %s\n", output_filename);
    printf("Press Ctrl+C to stop.\n");

    while (program_running) {
        AccelerationData data;
        if (read_acceleration_data(i2c_fd, &data) == 0) {
            if (log_data_to_csv(data) != 0) {
                log_error("Failed to log data to CSV");
            }
        } else {
            log_error("Failed to read acceleration data");
        }
        sleep(sampling_interval);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

