#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <termios.h>
#include <sys/select.h>

#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE B921600
#define CSV_FILE "radar_data.csv"
#define READ_BUF_SIZE 4096
#define MAGIC_WORD_SIZE 8
#define MAX_OBJECTS 100

/* TI mmWave TLV frame structure (simplified for this exercise) */
#define TLV_HEADER_SIZE 8
#define TLV_TYPE_DETECTED_OBJECTS 1
#define TLV_TYPE_RANGE_PROFILE 2

typedef struct {
    uint32_t version;
    uint32_t total_packet_len;
    uint32_t platform;
    uint32_t frame_number;
    uint32_t time_subframe;
    uint32_t num_detected_obj;
    uint32_t num_tlvs;
    uint32_t subframe_number;
} __attribute__((packed)) FrameHeader;

typedef struct {
    uint16_t range_idx;
    uint16_t doppler_idx;
    uint16_t peak_val;
    uint16_t x;
    uint16_t y;
    uint16_t z;
} __attribute__((packed)) DetectedObject;

static volatile sig_atomic_t g_running = 1;
static int g_uart_fd = -1;
static FILE *g_csv = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_uart(const char *device, speed_t baud) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "tcgetattr failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud);
    cfsetispeed(&tty, baud);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 1; /* 100 ms inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "tcsetattr failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_exact(int fd, void *buf, size_t len) {
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, (uint8_t *)buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "UART read error: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "UART read timeout (got %zu of %zu bytes)\n", total, len);
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

static int find_magic_word(int fd, uint8_t *magic) {
    uint8_t buf[MAGIC_WORD_SIZE];
    size_t idx = 0;
    while (g_running) {
        ssize_t n = read(fd, buf + idx, MAGIC_WORD_SIZE - idx);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "UART read error during magic search: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "UART read timeout during magic search\n");
            return -1;
        }
        idx += (size_t)n;
        if (idx >= MAGIC_WORD_SIZE) {
            if (memcmp(buf, (const uint8_t *)"AWR1642", 8) == 0) {
                memcpy(magic, buf, MAGIC_WORD_SIZE);
                return 0;
            }
        }
    }
    return -1;
}

static int parse_frame(int fd, uint8_t *magic) {
    FrameHeader hdr;
    if (read_exact(fd, &hdr, sizeof(hdr)) != 0) return -1;

    if (hdr.total_packet_len < sizeof(hdr) || hdr.total_packet_len > READ_BUF_SIZE) {
        fprintf(stderr, "Invalid frame length: %u\n", hdr.total_packet_len);
        return -1;
    }

    uint8_t payload[READ_BUF_SIZE];
    if (read_exact(fd, payload, hdr.total_packet_len - sizeof(hdr)) != 0) return -1;

    size_t offset = 0;
    for (uint32_t i = 0; i < hdr.num_tlvs && offset + TLV_HEADER_SIZE <= hdr.total_packet_len - sizeof(hdr); i++) {
        uint32_t tlv_type, tlv_len;
        memcpy(&tlv_type, payload + offset, 4);
        memcpy(&tlv_len, payload + offset + 4, 4);
        offset += TLV_HEADER_SIZE;

        if (offset + tlv_len > hdr.total_packet_len - sizeof(hdr)) {
            fprintf(stderr, "TLV length exceeds frame bounds\n");
            return -1;
        }

        if (tlv_type == TLV_TYPE_DETECTED_OBJECTS) {
            size_t obj_size = sizeof(DetectedObject);
            if (tlv_len < obj_size) {
                fprintf(stderr, "Detected objects TLV too short\n");
                return -1;
            }
            size_t num_objs = tlv_len / obj_size;
            for (size_t j = 0; j < num_objs && j < MAX_OBJECTS; j++) {
                DetectedObject obj;
                memcpy(&obj, payload + offset + j * obj_size, obj_size);
                float range = obj.range_idx * 0.0436f; /* approx: 4.36 cm per index */
                float velocity = obj.doppler_idx * 0.0506f; /* approx: 5.06 cm/s per index */
                time_t now = time(NULL);
                fprintf(g_csv, "%ld,%zu,%.3f,%.3f\n", (long)now, j, range, velocity);
                fflush(g_csv);
            }
        }
        offset += tlv_len;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (g_uart_fd < 0) return 1;

    g_csv = fopen(CSV_FILE, "a");
    if (!g_csv) {
        fprintf(stderr, "Error opening CSV %s: %s\n", CSV_FILE, strerror(errno));
        close(g_uart_fd);
        return 1;
    }
    fprintf(g_csv, "# timestamp,object_index,range_m,velocity_mps\n");
    fflush(g_csv);

    uint8_t magic[MAGIC_WORD_SIZE];
    if (find_magic_word(g_uart_fd, magic) != 0) {
        fprintf(stderr, "Failed to find magic word; aborting.\n");
        fclose(g_csv);
        close(g_uart_fd);
        return 1;
    }

    while (g_running) {
        if (parse_frame(g_uart_fd, magic) != 0) {
            fprintf(stderr, "Frame parse error; continuing.\n");
        }
    }

    fprintf(stderr, "\nShutting down...\n");
    if (g_csv) { fflush(g_csv); fclose(g_csv); }
    if (g_uart_fd >= 0) { close(g_uart_fd); }
    return 0;
}

