#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <sys/select.h>
#include <signal.h>
#include <termios.h>

#define UART_PORT     "/dev/serial0"
#define BAUD_RATE     B115200
#define LINE_BUF_SIZE 256
#define READ_BUF_SIZE 1024
#define POLL_TIMEOUT  2   /* seconds */
#define READ_TIMEOUT  0.5 /* seconds */

static volatile sig_atomic_t g_running = 1;
static int g_uart_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* UART configuration                                                  */
/* ------------------------------------------------------------------ */
static int configure_uart(int fd)
{
    struct termios tty;

    if (tcgetattr(fd, &tty) == -1) {
        perror("tcgetattr");
        return -1;
    }

    /* 8N1, no flow control, raw mode */
    tty.c_cflag &= ~(PARENB | CSTOPB | CSIZE | CRTSCTS);
    tty.c_cflag |=  CS8 | CREAD | CLOCAL;

    /* Raw input */
    tty.c_iflag &= ~(IXON | IXOFF | IXANY | IGNBRK | BRKINT |
                     PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    /* Raw output */
    tty.c_oflag &= ~OPOST;

    /* Raw mode, no echo */
    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ECHONL | ISIG | IEXTEN);

    /* VMIN=0, VTIME=0 → non-blocking */
    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 0;

    /* Blocking read with 0.5 s inter-byte timeout (VTIME = 5 deciseconds) */
    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 5;

    if (cfsetospeed(&tty, BAUD_RATE) == -1) {
        perror("cfsetospeed");
        return -1;
    }
    if (cfsetispeed(&tty, BAUD_RATE) == -1) {
        perror("cfsetispeed");
        return -1;
    }

    if (tcsetattr(fd, TCSANOW, &tty) == -1) {
        perror("tcsetattr");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a complete line from the UART                                  */
/* ------------------------------------------------------------------ */
static int read_uart_line(int fd, char *line, size_t line_size)
{
    size_t idx = 0;
    char   ch;
    ssize_t n;

    while (idx < line_size - 1) {
        n = read(fd, &ch, 1);
        if (n == -1) {
            if (errno == EINTR) {
                continue;
            }
            perror("read");
            return -1;
        }
        if (n == 0) {
            /* VTIME expired with no data → no data available */
            break;
        }

        if (ch == '\n') {
            line[idx] = '\0';
            return 0;
        }

        if (ch != '\r') {
            line[idx++] = ch;
        }
    }

    line[idx] = '\0';
    return (idx > 0) ? 0 : -1;
}

/* ------------------------------------------------------------------ */
/* Parse a line of the form <unix_timestamp>,<range_meters>\n         */
/* ------------------------------------------------------------------ */
static int parse_line(const char *line, double *timestamp, double *range)
{
    char  copy[LINE_BUF_SIZE];
    char *saveptr = NULL;
    char *tok;
    char *endptr;

    if (strlen(line) >= sizeof(copy)) {
        return -1;
    }
    strcpy(copy, line);

    tok = strtok_r(copy, ",", &saveptr);
    if (tok == NULL) {
        return -1;
    }

    errno = 0;
    *timestamp = strtod(tok, &endptr);
    if (errno != 0 || endptr == tok) {
        return -1;
    }

    tok = strtok_r(NULL, ",", &saveptr);
    if (tok == NULL) {
        return -1;
    }

    errno = 0;
    *range = strtod(tok, &endptr);
    if (errno != 0 || endptr == tok) {
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    char    line_buf[LINE_BUF_SIZE];
    char    read_buf[READ_BUF_SIZE];
    double  timestamp, range;
    time_t  wall_time;
    struct  timeval tv;
    fd_set  rfds;

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    g_uart_fd = open(UART_PORT, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (g_uart_fd == -1) {
        perror("open(" UART_PORT ")");
        return EXIT_FAILURE;
    }

    if (configure_uart(g_uart_fd) != 0) {
        close(g_uart_fd);
        g_uart_fd = -1;
        return EXIT_FAILURE;
    }

    printf("UART %s opened at 115200 8N1. Reading AWR1642 data...\n", UART_PORT);
    fflush(stdout);

    while (g_running) {
        FD_ZERO(&rfds);
        FD_SET(g_uart_fd, &rfds);

        tv.tv_sec  = POLL_TIMEOUT;
        tv.tv_usec = 0;

        int rc = select(g_uart_fd + 1, &rfds, NULL, NULL, &tv);
        if (rc == -1) {
            if (errno == EINTR) {
                continue;
            }
            perror("select");
            break;
        }
        if (rc == 0) {
            /* Timeout — no data available within 2 s */
            continue;
        }

        if (read_uart_line(g_uart_fd, line_buf, sizeof(line_buf)) == 0) {
            if (parse_line(line_buf, &timestamp, &range) == 0) {
                wall_time = time(NULL);
                printf("Timestamp: %s, Range: %.2f meters\n",
                       ctime(&wall_time), range);
                fflush(stdout);
            } else {
                fprintf(stderr, "Parse error: '%s'\n", line_buf);
            }
        } else {
            /* read_uart_line returned -1 (no data or error) */
            if (errno != EAGAIN && errno != EWOULDBLOCK) {
                fprintf(stderr, "UART read error: %s\n", strerror(errno));
            }
        }
    }

    if (g_uart_fd != -1) {
        close(g_uart_fd);
        g_uart_fd = -1;
    }

    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

