#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <stdbool.h>
#include <sys/select.h>
#include <sys/time.h>
#include <sys/ioctl.h>
#include <linux/serial.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN  4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27

#define UART_DEVICE "/dev/ttyAMA0"
#define BAUD_RATE   B115200

#define POLL_DELAY_US 100000  /* 100 ms -> 10 Hz */

/* ------------------------------------------------------------------ */
/* Globals                                                            */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;
static int  g_uart_fd = -1;
static bool g_pigpio_initialized = false;

/* ------------------------------------------------------------------ */
/* Signal handler                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* UART initialization                                                */
/* ------------------------------------------------------------------ */

static int init_uart(const char *device, speed_t baud)
{
    int fd = open(device, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        perror("open() UART");
        return -1;
    }

    /* Clear O_NDELAY so reads block */
    if (fcntl(fd, F_SETFL, 0) < 0) {
        perror("fcntl F_SETFL");
        close(fd);
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr()");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud);
    cfsetispeed(&tty, baud);

    tty.c_cflag  = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag  = 0;
    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_lflag  = 0;
    tty.c_oflag  = 0;

    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 5;   /* 0.5 s inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr()");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

/* ------------------------------------------------------------------ */
/* Sensor reading                                                     */
/* ------------------------------------------------------------------ */

/*
 * KY-033: digital LOW  -> obstacle detected
 *          HIGH        -> clear
 */
static void read_sensors(int left, int middle, int right)
{
    printf("[%ld] L:%d M:%d R:%d\n", (long)time(NULL), left, middle, right);
}

/* ------------------------------------------------------------------ */
/* Emergency stop                                                     */
/* ------------------------------------------------------------------ */

static void emergency_stop(void)
{
    printf("EMERGENCY STOP!\n");
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                            */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    if (g_uart_fd >= 0) {
        close(g_uart_fd);
        g_uart_fd = -1;
    }
    if (g_pigpio_initialized) {
        gpioTerminate();
        g_pigpio_initialized = false;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    g_pigpio_initialized = true;

    /* --- GPIO setup --- */
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);

    gpioSetPullUpDown(LEFT_SENSOR_PIN,  PI_PUD_UP);
    gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_SENSOR_PIN,  PI_PUD_UP);

    /* --- UART init --- */
    g_uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (g_uart_fd < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- Main loop --- */
    while (g_running) {
        int left   = gpioRead(LEFT_SENSOR_PIN);
        int middle = gpioRead(MIDDLE_SENSOR_PIN);
        int right  = gpioRead(RIGHT_SENSOR_PIN);

        read_sensors(left, middle, right);

        if (left == 0 && middle == 0 && right == 0) {
            emergency_stop();
        }

        usleep(POLL_DELAY_US);
    }

    /* --- Graceful exit --- */
    cleanup();
    return EXIT_SUCCESS;
}

